-- 当前包：1572 条，ID 100001-101572，source=seed:xinzhili-essence-v17-20260706
BEGIN;

INSERT INTO rag_documents (id, title, content, tags, status, source, sort, update_time)
VALUES
(100001, '英雄之旅总览：把生命当作创造与疗愈的冒险', '英雄之旅不是追逐名利的个人奋斗剧本，而是一种把生命视为伟大冒险的意识训练：人被某种更深的力量触碰，离开惯性的生活方式，经历失联、磨难、失败、整合与疗愈，最后带着获得的礼物回到世界，贡献给他人。课程正文把这一主线放在当代处境中理解：人很容易陷入负面念头、焦虑、抑郁、过度分析和小我身份，因而失去与生命力、创造力、身体和世界的连接。所谓正能量人生，并不是永远顺利，而是能全身心参与生命，在困难中保持开放，把痛苦转化为更完整的人性。整个十二模块可视为一条路径：听见召唤，看见拒绝，找到向导，训练创造性心智，连接资源，召回温柔、勇猛、顽皮等原型能量，把障碍和恶魔转化为资源，再把礼物传给他人。英雄之旅的核心价值，是让个人从孤立的小我走向身心灵整合，再走向社群与世界的疗愈；每个人都携带一份独特礼物，旅程的意义在于听见它、训练自己承载它、并把它分享出去。它不是一次顿悟，也不是外部成就清单，而是持续的身心练习：安顿、呼吸、放下固化形式，重新选择如何回应生命。用于问答检索时，可对应生命意义、创造力低落、人生卡住、痛苦转化、如何贡献社会等问题。', '["英雄之旅", "创造力", "疗愈整合", "正能量人生", "生命礼物", "社群贡献"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1, now()),
(100002, '聆听召唤：从童年火光到一生价值的辨认', '召唤不是头脑临时想出的目标，而是生命中反复触碰你的深层信号。它可能来自童年第一次被某个人、一本书、一首音乐、一个科学家或艺术家点亮的瞬间，也可能来自一次巨大的痛苦之后的重生，或来自想象临终回望时会让自己说出此生值得的价值。课程强调，人常被左脑的过度分析锁住，越努力想答案，越难听见召唤；所以练习不是思考清单，而是先安顿身体、呼吸、向天空伸展、向大地释放，再把问题像种子一样投入全身心，让画面、记忆和感受自然浮现。可反复询问：小时候谁启发了我，哪次挣扎让我更有生命力，哪个艺术作品打开过我，若生命将尽我希望完成什么。召唤常常短暂，却不会消失；它像内在已经存在的火，提醒你什么能让生命鲜活、快乐、神奇，也提醒你如何成为更好的自己并帮助别人。当出现多个答案时，不必急着选择哪一个正确，而是观察哪个让身体更放松、更有热、更多泪水或敬畏；这些生理反应常比逻辑判断更接近召唤。', '["召唤", "童年记忆", "生命使命", "身心练习", "价值澄清", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 2, now()),
(100003, '拒绝召唤与找到向导：把“不可能”转化为支持', '当一个人感到自己想创造某种生命、事业或关系时，拒绝召唤几乎会同步出现。它可能是父母、家庭、社会、性别角色、职业规划或内在批评者的声音，反复说你不能、你不该、那不现实。课程没有把这部分视为错误，而把它看成英雄之旅必经的张力：心中的渴望和头脑中的限制讯息同时存在，真正的成熟不是假装没有阻力，而是能与阻力同场工作。练习的关键，是先触碰心，说出我最想创造的是什么，并让身体做出代表梦想的动作；再走到另一边，进入批评者角色，用姿态和声音表达不允许，重复几次直到能看见它的能量模式；最后请出导师、祖先、榜样或灵性向导，走进他们的身体、眼神和神态，接收支持与许可。向导可以是现实老师、亲人、已故长辈、文学人物或内在智慧。这样做不是否认批评，而是让支持系统比批评更有能量，使人能在真实世界中带着勇气迈步。', '["拒绝召唤", "内在批评", "向导", "导师资源", "身体模型", "自我支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 3, now()),
(100004, '创造性心智：用游戏、幽默和多重视角重新连接生命', '创造性心智的核心是不被单一视角锁住。课程把右脑比作开放的海洋，能把任何事物连接到其他事物；左脑则像语言电脑，擅长代表、分析和控制，但如果成为唯一中心，就会让人困在机器世界，失去心灵、身体和奥秘感。创造性的人会移动、发散、玩耍、幽默，并能像孩子一样流动，同时保有成人的成熟。练习上，可以一天多次收回注意力、触碰心、打开全身通道，暂时放下固定身份，感受自己既是孩子、成年人、古老的生命、大树、动物，也是宇宙的一部分。通过身体动作、声音、笑和想象，人的小我身份会松动，生命意图便能从更广阔的创造意识中表达出来。这种玩耍不是逃避现实，而是让心智恢复灵活性。若发现自己僵硬、无趣、只能想出一种做法，正是需要进入创造性心智的信号。', '["创造性心智", "右脑连接", "左脑分析", "游戏精神", "多重身份", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 4, now()),
(100005, '三种心智与正念种子：静止、寂静、无边无际', '课程把更深的正念状态分为语言心智、身体心智和场域心智。语言心智容易担忧、解释和计划；身体心智若被紧绷占据，就会阻塞生命之气；场域心智则指人与家庭、城市、自然、社群及万有生命的连接。仅在头脑里设定目标，往往缺少直觉、自信和流动，因此需要把意图放入更精微的身心场域中。三颗种子的练习分别对应三个层面：把静止投入身体，让肌肉和姿态慢下来，像大树向下扎根又向天空打开；把寂静投入语言心智，让杂念在宽阔空间中休息，而不是用力驱赶；把无边无际投入场域心智，让涟漪从心和腹部扩散到周围一切人事物。等身体像光、头脑有寂静、场域能包容时，再说出我想在世界上创造的是什么，创造力会比紧张努力更稳定。', '["三种心智", "正念种子", "语言心智", "身体心智", "场域心智", "生命之气"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 5, now()),
(100006, '三个正向连接：意图、中心与资源圆环', '真正把召唤带到世界，不只是想清楚目标，而是同时建立三个正向连接。第一是简洁、正向、有共振的意图，例如我最想创造的是某种关系、疗愈、平静或贡献；第二是身体中心，可能在心口、腹部或其他最有能量感的地方，当压力、未知、速度过快或注意力涣散时，回到中心就等于回到根基；第三是资源圆环，包含导师、朋友、家人、自然地点、动物、祖先、灵性存有、社群或任何能支持你走路的人事物。练习时先安顿，下沉并打开；再看见未来时间线，一步步前进，每一步都重新感受意图、中心和资源。资源不是抽象安慰，而是一个可被身体感到的场：有人看见你、爱你、理解你、支持你继续。三连可作为任何计划前的微流程：先说清意图，再摸到中心，最后看见资源；三者同时在线时，行动更有弹性和耐力。', '["资源连接", "正向意图", "身体中心", "资源圆环", "时间线", "社群支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 6, now()),
(100007, '三种原型能量：温柔、勇猛与顽皮的整合', '为了让召唤能在沟通和行动中实现，课程提出三种普世原型能量：温柔、勇猛、顽皮。温柔让人先对自己良善，也能在紧张的人际氛围中建立信任和安全；但只有温柔会失去边界，所以需要勇猛的专注、火焰、决心和复原力。勇猛若脱离心灵，会变成暴力、批评或霸凌，因此必须回到人性的中心。顽皮则让人从过度严肃和僵硬中解放出来，带来笑、轻盈、好奇和创造性沟通。练习方式是为每种能量找到代表人物或榜样，进入他们的身体、眼神和姿态，再回到自己身上，用这股能量表达同一个生命意图。成熟表达是三者同时服务于心灵，而不是各自失控。冲突中若只有温柔，容易退让；只有勇猛，容易压迫；只有顽皮，容易逃避深度。', '["原型能量", "温柔", "勇猛", "顽皮", "沟通", "创造力训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 7, now()),
(100008, '用原型能量面对障碍：合气道式地欢迎与引导', '障碍在英雄之旅中被称为恶魔，可能是内在恐惧、批评、失联、羞耻，也可能是外在家人、机构、工作环境或不支持你的人。课程借用艾瑞克森取向和合气道精神：不要与阻碍硬碰硬，不要暴力消灭、逃离或控制，而是先与它相合，欢迎它，再把关系带向更好的方向。练习时先站在意图和中心里，看见未来道路，再让一个具体障碍出现在前方。用正向勇猛面对它时，感受边界、眼神、站立方式和可以说出的清晰话语；用顽皮面对它时，跳舞、转圈、笑，避免把力量交给障碍；用温柔面对它时，先支持自己的脆弱，再以成熟善意触碰阻碍背后的痛苦。障碍不是旅程失败的证据，而是提醒你回到中心并调用更完整的自己。', '["障碍转化", "恶魔", "合气道", "非暴力", "边界", "原型应用"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 8, now()),
(100009, '转化恶魔：从问题行为里识别正向需求', '问题、症状和成瘾行为表面上像敌人，深处常隐藏着尚未被看见的正向需求。课程用恶龙可能是等待被发现的礼物来说明这一点：如果只分析、压制、逃避或攻击问题，就会切断它携带的资源。更有效的方法是发展身体模型。选择一个反复让你挣扎的行为或情绪，例如焦虑、缺乏安全感、拖延、上瘾；不要急着解释，不要命令它停止，而是让身体自然做出一个姿态或重复动作，并以比平常慢数倍的节奏、温柔和好奇来体验它。然后在动作中询问：这个模式想为我创造什么，它想满足哪种正向需求。关键在于区分需求和策略：需求可能是安全、温暖、休息、连接或自由，旧策略可以被替换，但需求必须被尊重。', '["恶魔转化", "身体模型", "正向需求", "症状意义", "艾瑞克森", "成瘾疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 9, now()),
(100010, '目标与障碍整合：让对立面成为同一支舞', '目标和障碍并不总是敌对关系，很多症状其实在尝试恢复平衡。一个人用紧绷、强硬和肌肉力量逼自己完成项目，结果拖延不断出现；拖延看似恶魔，深处却可能代表放松、休息、释放和阴性能量，提醒他不能只靠蛮力。整合练习先为目标建立身体模型，感受我真正想创造的是什么；再为每当我想创造它时被触发的那一面建立身体模型，如抑郁、自我批判、恐惧、愤怒或拖延。不要用对错评判两边，而是用缓慢、温柔、顽皮、好奇的动作欢迎每一面，倾听它各自代表的正向需求。整合后的行动不是折中妥协，而是让目标获得障碍所携带的智慧：努力获得休息，勇气获得柔软，前进获得节奏，因此更能长期持续。', '["目标整合", "障碍整合", "阴阳平衡", "拖延", "身体舞蹈", "创造性完整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 10, now()),
(100011, '传递给他人：把获得的礼物变成世界的光', '英雄之旅最终不是把天分囤积起来，而是传递给他人。课程通过艾瑞克森对学生的教导指出，真正的回报方式是把有用的东西继续分享。一个人在年轻时需要专注自己的目标，但当能力和成功逐渐出现，如果只追逐名利、金钱和外在认可，创造力会再次收缩；若把天赋视为被托付的礼物，并用来帮助别人，生命会更快乐、更宽广。练习上，先放下比较、表演和赚钱的压力，进入让自己感到神圣、平静、合一的空间，感受内在不可摧毁的光。分享不是拯救姿态，也不是牺牲自我，而是让自己的觉醒映照并唤醒他人的觉醒。真正分享时必须先保持自己的光，不在关系中耗尽自己，而是从充满的中心去照亮。', '["传递给他人", "贡献", "礼物", "艾瑞克森", "慈悲练习", "社群疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 11, now()),
(100012, '回顾整合：把每一天活成完整的英雄之旅', '最后的整合练习把十二个模块收束为日常道路：先安顿、下沉大地、向天空打开，让语言像音乐和梦一样流入全身；记得自己来到世界是为了给出一份礼物，也诚实看见曾经因为不被支持而转身拒绝。然后寻找榜样、向导和能让灵魂相触的人，学习把觉知中心从头脑转回身体、心灵和场域。日常行动中，要保留玩耍、温柔、勇猛、专注和严肃的混合状态；遇到障碍时，退后一步成为大树，回到静止、寂静和无边无际，再用身体模型、合气道式欢迎和创造性好奇把冲突转为合作。英雄之旅不是一次性完成的课程，而是每一天都能重新选择的活法：过好今天，享受这一刻，并支持他人也活出他们的旅程。', '["回顾整合", "每日练习", "感恩", "宽恕", "宇宙连接", "享受生命"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 12, now()),
(100013, '1号完美型：核心识别与成长建议', '1号的核心不是简单的爱挑剔，而是内在长期有一套高标准在审判：这件事对不对、够不够好、还能不能改进。他们把责任、秩序、原则和正确性放在快乐之前，擅长发现漏洞、维护规范、把事情做扎实。盲点是把应该当成唯一道路，把错误看成道德问题，把愤怒压成不满、讽刺、僵硬的礼貌或反复纠错。成长关键是从内在批评家退后一步，区分我想要和我应该，允许错误、风险和多种答案存在；把事实核对代替脑内定罪，把感谢与肯定说出口；给日程留白，练习享受、求助和适度妥协；把怒气视为被忽略需求的信号，用清楚、非控诉的语言表达边界。成熟的1号会把高标准转化为可靠、正直和持续改善，而不是让自己和他人永远不合格。', '["九型人格", "1号", "完美型", "完美主义者", "内在批评", "愤怒", "原则", "成长建议"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 13, now()),
(100014, '2号助人型：核心识别与成长建议', '2号的核心驱动力是通过被需要、被喜欢、被认可来确认自己的价值。他们能快速捕捉他人的情绪和需求，愿意支持、照顾、连接资源，也善于让别人感觉自己很重要。盲点是注意力长期放在他人身上，自己的真实需要会变得模糊，付出容易夹带期待：我这么懂你、帮你，你是否也会爱我、重视我？得不到回应时，2号可能受伤、抱怨、控制、吃醋。成长建议是停止用过度付出来换取关系安全，帮助前先问：这是对方真正需要，还是我想证明自己重要？把隐性期待改成直接请求，允许自己接受照顾；建立边界，不把拒绝理解为不爱。成熟的2号能温暖地滋养他人，也能诚实承认自己的欲望、脆弱和限度。', '["九型人格", "2号", "助人型", "给予者", "被需要", "认可", "边界", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 14, now()),
(100015, '3号成就型：核心识别与成长建议', '3号的核心关注是成功、效率、形象和可见成果：我怎样被尊敬、被认可、被证明有价值。他们行动快、目标感强、能读懂场域并切换角色，适合推动项目、包装想法、销售愿景、鼓舞团队。代价是把正在做什么误当成我是谁，把悲伤、恐惧、疲惫和亲密需求视为影响表现的干扰。成长方向是从表演自我回到诚实自我：定期停下问自己喜欢什么、不喜欢什么、身体感觉如何；把休息和情感觉察也放进日程，而非只安排产出；学习承认失败、困惑和普通时刻，不急着换项目或换形象。成熟的3号依然高效有感染力，但其价值不再完全依赖掌声。', '["九型人格", "3号", "成就型", "实干者", "形象", "成功", "工作狂", "诚实"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 15, now()),
(100016, '4号自我型：核心识别与成长建议', '4号的核心经验是强烈地感到我与别人不同，并在失落、渴望、独特性和真实表达中寻找自我。他们情感细腻，能进入他人的痛苦，富有审美、创造力和意义感。盲点是注意力容易停在缺失处：现实有什么不够，别人拥有什么而我没有，理想关系为何迟迟不到；情绪会被当成身份，嫉妒、忧郁、浪漫化和戏剧性表达会反复出现。成长建议是尊重情感但不被情感定义：把我感觉如此与事实必然如此分开；在普通日常中建立稳定行动；把嫉妒当成愿望线索，转化为可执行选择；亲密关系中直接表达需要，少用疏离、戏剧化或测试来证明爱。', '["九型人格", "4号", "自我型", "悲情浪漫者", "情绪", "嫉妒", "真实", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 16, now()),
(100017, '5号理智型：核心识别与成长建议', '5号的核心策略是用观察、知识和边界来保护时间、能量与内在空间。他们擅长客观分析、系统研究、保持冷静，常在独处后才重新接触情绪。压力点在于把外界需求体验成侵入，把亲密、承诺或即时回应视为资源消耗，于是退回头脑、分隔生活领域、少说少给；情绪可能不是没有，而是被推迟到安全独处时才浮现。成长建议不是强迫外向，而是让知识与生命重新连接：在尚未准备完美时也小步参与；用简短语言告诉别人自己需要多少时间和空间，而不是消失；练习在当下辨认身体和情绪，别只事后复盘。', '["九型人格", "5号", "理智型", "观察者", "边界", "知识", "抽离", "独处"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 17, now()),
(100018, '6号忠诚型：核心识别与成长建议', '6号的核心注意力在安全、信任、风险和权威：哪里会出问题，谁可靠，我的决定是否稳妥。他们能预演最坏情况，发现隐藏漏洞，对团队和承诺很忠诚。盲点是焦虑会让他们在顺从与挑战权威之间摆动，既想得到保护又担心被控制；他们可能怀疑他人动机、拖延决定、反复确认，或用反恐惧方式冲向危险来证明自己不怕。成长建议是发展内在权威：把事实、想象、直觉和投射分栏记录；为决策设定截止时间，允许足够好而非绝对安全；公开提出疑问，不在背后累积猜测；练习想象正面结果，让身体体验安全。', '["九型人格", "6号", "忠诚型", "怀疑论者", "安全", "信任", "权威", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 18, now()),
(100019, '7号快乐型：核心识别与成长建议', '7号的核心追求是可能性、自由、快乐和未来计划。他们乐观、点子多、反应快，能把不同事物连接成新方案，擅长带来兴奋感、创新气氛和对未来的信心。盲点是害怕被限制、无聊或痛苦困住，容易用新选择、合理化、玩笑和忙碌避开难受感；承诺后仍保留退路，兴趣下降就转向下一个刺激，未完成事项堆积。成长建议是把自由从永远有别的选择升级为能选择并完成：限制同时进行的项目，给承诺设置收尾标准；遇到痛苦时先停留、呼吸、命名感受，不急着转移；评估计划时同时看风险、资源和代价。', '["九型人格", "7号", "快乐型", "享乐主义者", "自由", "乐观", "选择", "逃避痛苦"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 19, now()),
(100020, '8号领袖型：核心识别与成长建议', '8号的核心关注是力量、控制、公正和真实。他们直接、有行动力，能在混乱中接管局面，保护弱者，讨厌虚伪、软弱和被蒙在鼓里。压力点在于把世界分成强者与弱者，隐藏脆弱，用愤怒、强势和报复来恢复控制，可能无意中让他人害怕或沉默。成长建议是把力量从压制转为承担：行动前先听完整信息，尤其欢迎坏消息；区分我在保护与我在控制；练习用较低强度表达需求，给别人反应时间；在可信对象面前承认害怕、在乎或受伤，不把柔软等同于失败；冲突中追求清楚和修复，而不只是胜利。', '["九型人格", "8号", "领袖型", "保护者", "控制", "正义", "愤怒", "脆弱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 20, now()),
(100021, '9号和平型：核心识别与成长建议', '9号的核心策略是维持和谐、避免冲突，并把自己融入他人的节奏。他们能倾听多方、理解不同立场、提供稳定支持，是天然的调停者。盲点是忘记自己的优先级，把重要愿望让位给琐事、习惯或他人安排，表面顺从内心保留，压力下以拖延、麻木、被动抵抗表达愤怒。成长建议是把和平从没有冲突升级为真实参与：每天写下自己的一个偏好、一个不愿意、一个下一步行动；用期限和结构帮助聚焦，先做最重要的小步骤；练习直接表达不同意见，不用拖延让别人猜；把愤怒视为生命力和边界的信号。', '["九型人格", "9号", "和平型", "调停者", "和谐", "冲突回避", "惯性", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 21, now()),
(100022, '通用机制：注意力焦点、直觉与三大中心', '九型不是先看外在行为，而是看注意力被什么自动吸走。性格一旦形成，人会选择性搜集信息：1号看对错与改进，2号看别人是否需要和喜欢自己，3号看表现能否获得肯定，4号看缺失、独特和真实感，5号看边界与资源要求，6号看风险和隐藏意图，7号看快乐选择与未来可能，8号看失控、不公和力量对比，9号看他人安排与各方立场。身体中心8、9、1常通过腹部和本能感知环境；情感中心2、3、4通过关系、形象和情绪共鸣感知；精神中心5、6、7通过观察、预测和联想感知。成长入口是成为内心观察者：记录自己第一时间注意到什么、忽略什么；区分事实、解释、幻想和直觉。', '["九型人格", "通用机制", "注意力", "直觉", "三大中心", "身体中心", "情感中心", "精神中心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 22, now()),
(100023, '通用机制：两翼、核心动机与同型差异', '两翼指某个型号相邻两侧型号对其表达方式的影响。它不是另一个核心类型，也不是简单的副人格，而是让同一型号呈现不同气质的调味层：偏5翼的4号可能更内收、理性和孤僻，偏3翼的4号可能更外显、形象化和有舞台感；偏8翼的9号更硬、更能顶住压力，偏1翼的9号更克制、更在意正确与秩序。使用两翼时要避免只凭风格判断，例如一个强势的9号不等于8号，一个外向的5号也不等于7号。先问核心动机：他是在维护和谐、保留资源，还是追求自由？再看两翼怎样改变表达。两翼解释差异，不替代访谈、情境和长期注意力观察。', '["九型人格", "通用机制", "两翼", "核心动机", "同型差异", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 23, now()),
(100024, '通用机制：压力线、安全线与状态变化', '每个型号不是静态标签，而是由日常主型、压力状态、安全状态共同构成。压力状态常沿箭头离开本型：1到4、2到8、3到9、4到2、5到7、6到3、7到1、8到5、9到6；安全状态常沿反向进入：1到7、2到4、3到6、4到1、5到8、6到9、7到5、8到2、9到3。使用时不要把安全线等同于一定健康、压力线等同于一定糟糕；安全也可能暴露阴影，压力也可能激发能力。关键是观察状态变化：在放松、受威胁、被爱、被批评时你变成什么样？成长不是迷恋安全态，而是能觉察三种状态、整合其正面资源，并在负面反应出现前暂停选择。', '["九型人格", "通用机制", "压力线", "安全线", "动态变化", "九角星", "状态识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 24, now()),
(100025, '通用机制：关系与职场沟通的九型用法', '九型用于关系和职场时，重点不是给人分类，而是找到对方的原动力、焦虑点和沟通入口。1号需要尊重其标准，同时减少你错了的羞辱感；2号需要感谢但也要鼓励其说出真实需求；3号需要目标和认可，也要提醒其关注人和过程；4号需要真实与意义，反馈要避免轻率否定其感受；5号需要提前信息、边界和思考时间；6号需要透明、稳定承诺和可验证依据；7号需要空间与愿景，同时要明确收尾责任；8号需要直说、完整信息和可信赖的边界；9号需要清晰结构、温和追问和表达异议的安全感。成熟用法是用类型翻译彼此语言：把评判译成对质量的在乎，把控制译成对安全的需求，把拖延译成冲突恐惧，再讨论可执行请求。', '["九型人格", "关系", "职场", "沟通", "领导力", "反馈", "冲突", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 25, now()),
(100026, '关键对话：先恢复安全感，再讨论观点差异', '关键对话通常同时具备三个特征：观点不同、利害关系重大、情绪强烈。很多沟通失败不是因为道理不够，而是对话安全感已经破裂；一旦人感觉被攻击、羞辱或不被尊重，就会转入沉默或暴力：沉默包括回避、掩饰、退出，暴力包括控制、贴标签、攻击和打断。有效处理关键对话的第一步，不是立刻证明自己正确，而是观察气氛是否安全：对方是否还愿意说真话，自己是否还在听。若安全感下降，应先暂停内容争论，说明共同目的和尊重，例如“我不是要否定你，我想一起把问题解决”。然后再陈述事实、表达感受、解释自己的故事、询问对方看法。App 问答可用于伴侣冲突、上下级反馈、客户沟通和团队分歧。', '["关键对话", "沟通", "安全感", "冲突", "反馈", "沉默", "暴力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 26, now()),
(100027, '非暴力沟通四步：观察、感受、需要、请求', '非暴力沟通的核心，是把注意力从评判、指责、命令和辩解，转向人真实的观察、感受、需要和请求。第一步是观察：具体说发生了什么，避免“你总是”“你从来不”等概括性评价。第二步是感受：表达自己身体和情绪的真实状态，如失落、担心、疲惫、安心，而不是伪装成感受的指责。第三步是需要：为自己的感受负责，看到背后未被满足的需要，如尊重、休息、连接、自由、安全、理解。第四步是请求：提出具体、可执行、当下可回应的请求，而不是模糊期待或命令。它并非软弱妥协，而是让双方从敌对意识回到生命需要。适合回答亲密关系争吵、亲子沟通、职场表达、如何提出边界和如何道歉。', '["非暴力沟通", "观察", "感受", "需要", "请求", "同理心", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 27, now()),
(100028, '情绪急救：拒绝、孤独、失败和反刍需要及时处理', '日常心理伤害也需要像身体伤口一样做急救。拒绝会带来尖锐痛感，削弱自尊和归属感；孤独会让人更敏感、更防御，甚至把真正能靠近的人推开；失败容易让人把一次结果扩大成对自我的否定；反刍会让痛苦反复激活，形成焦虑和抑郁倾向。情绪急救的第一原则是尽早处理，而不是硬扛。可以先给情绪命名，承认痛苦真实存在；再把事件与自我价值拆开，避免“我被拒绝=我不值得”；随后做具体修复：联系安全的人、恢复日常行动、减少反复回放、写下可学习之处。若痛苦持续影响睡眠、工作、饮食、现实判断或有自伤风险，应寻求专业帮助。App 可用于被拒绝、失恋、孤独、失败、自卑和内耗等场景。', '["情绪急救", "拒绝", "孤独", "失败", "反刍", "自尊", "心理创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 28, now()),
(100029, '自控力：先观察失控模式，再设计环境', '自控不是靠羞辱自己变强，而是成为自己的观察者，理解何时、何地、因为什么失控。很多人越相信自己意志坚定，越容易把自己暴露在诱惑中；一旦失败，又因为意外和羞耻而放弃。更有效的方法是像科学家一样收集数据：什么时候最容易拖延，什么情绪会触发消费或暴食，哪些人、地点、App 或疲劳状态会削弱自控。然后设计环境而不是只发誓：减少诱惑可见度，提前设定下一步动作，把长期目标和眼前选择连接起来，用小实验测试哪种方法有效。自控力还包含“我要做”“我不要”“我想要”三种力量：不仅要抵制诱惑，也要记得真正重要的目标。App 可用于拖延、成瘾、情绪性消费、减肥、学习和习惯改变。', '["自控力", "意志力", "拖延", "习惯改变", "观察者", "诱惑", "目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 29, now()),
(100030, '解决冲突：把冲突当作信息，而不是立即消灭', '冲突不可完全避免，重要的是把它当作信息入口，而不是马上逃跑、压制或赢过对方。高质量冲突处理从理解发生了什么开始：双方各自看到了什么事实，分别受到什么影响，各自真正关心什么。很多人一遇冲突就急着解决，反而没弄清原因；也有人任由敌意升级，错失修复机会。有效做法是先降低攻击性表达，帮助聆听和说话变得容易：少用指责，多用具体事件；少说“你就是”，多问“你当时看到的是什么”；承认对方处境，同时表达自己的边界和请求。冲突的目标不是双方都委屈地妥协，而是找到能照顾重要需要的新路径。App 可用于伴侣冷战、团队矛盾、朋友误会、谈判和家庭分歧。', '["解决冲突", "聆听", "对话", "边界", "关系修复", "谈判", "误会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 30, now()),
(100031, '创伤反应：身体会记住未完成的危险', '创伤并不只是记忆里的一段故事，也会保存在身体、神经系统和关系反应中。经历过创伤的人可能明知现在安全，却在类似声音、气味、表情、距离或权威情境中突然紧绷、麻木、愤怒、逃离或讨好；这不是矫情，而是身体在用旧系统保护自己。疗愈的核心之一是重新建立安全与调节能力：先识别触发点和身体信号，再用呼吸、地面感、身体移动、稳定关系和可预测环境帮助神经系统回到当下。不要急着逼自己讲完所有创伤细节，身体安全比叙事完整更基础。关系中，创伤者需要被看见、被尊重节奏，而不是被催促“想开点”。App 可用于惊恐、麻木、过度警觉、亲密关系触发和创伤后自我理解。', '["创伤疗愈", "身体记忆", "安全感", "神经系统", "触发点", "情绪调节", "依恋"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 31, now()),
(100032, '回避型模式：逃避情绪会让关系和自我更空', '回避型或逃避型人格模式常见于对拒绝、失望、犯错和暴露脆弱高度敏感的人。为了不被伤害，他们会隐藏不安全感，努力保持理性、独立、无所谓，甚至把真实情绪像流感一样躲开。短期看，逃避能减少痛苦；长期看，它会让人失去与自己和他人的情绪连接，形成空虚、焦虑、亲密困难和自我价值感低落。成长不是一次性冲进情绪，而是安全地接触：当想逃跑、责备或麻木时，先停下，命名身体感受和脑中故事；区分真实事件与旧信念；用小剂量表达需要和脆弱，观察关系是否真的崩塌。App 可用于回避亲密、不敢表达、不安全依恋、内心空虚和情绪逃避。', '["回避型人格", "不安全依恋", "情绪逃避", "亲密关系", "脆弱", "自我价值", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 32, now()),
(100033, '边界表达：清楚说不，不等于伤害关系', '很多关系问题不是缺少爱，而是缺少清楚边界。没有边界的人容易讨好、压抑、拖延、爆发；边界过硬的人则可能控制、隔离、拒绝连接。健康边界是既承认关系重要，也承认自己的时间、身体、情绪和价值同样重要。表达边界时，先具体说明事实和影响，再表达自己的限制和可提供的替代方案，例如“我今晚需要休息，不能继续讨论；明天十点我可以认真听你说”。边界不是惩罚，也不是让对方猜，而是让关系可持续。若对方不适应你的新边界，不代表你错了；这只是关系系统在重新调整。App 可用于不会拒绝、被索取、关系内耗、职场加班、人情压力和亲密关系空间。', '["边界", "拒绝", "讨好", "关系内耗", "自我照顾", "沟通", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 33, now()),
(100034, '行动改变：把大目标拆成可重复的小实验', '无论是九型成长、英雄之旅还是自控力训练，真正改变都需要从宏大愿望落到小实验。大目标容易激发热情，也容易引发压力、完美主义和拖延；小实验则让人用数据学习，而不是用自责消耗。设计实验时要明确：我要观察什么，下一步最小行动是什么，何时做，做完如何记录。比如想改善沟通，不是发誓以后不吵架，而是每次冲突前先说一个事实、一个感受、一个请求；想减少拖延，不是要求自己从此自律，而是先开始5分钟并记录触发点。失败不是人格失败，而是实验数据，提醒你调整环境、节奏、支持或目标。App 可用于习惯养成、学习计划、关系修复、情绪管理和职业目标推进。', '["行动改变", "小实验", "习惯养成", "拖延", "目标拆解", "复盘", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 34, now()),
(100035, '关系修复：先承认影响，再解释动机', '关系受伤后，很多人急着解释自己不是故意的，却忽略对方已经受到影响。修复对话应先承认事实和影响：我看到我刚才打断你，让你觉得不被尊重；再表达自己的感受和需要；最后提出可执行的修复请求或承诺。解释动机可以放在后面，因为如果先解释，容易被听成辩解。修复也包括聆听对方版本，不急着纠正其中每个细节。道歉不是自我贬低，而是对关系的负责；原谅也不是立刻恢复原状，而是双方重新建立安全感和边界。若伤害反复发生，修复需要具体行为变化，而不只是情绪表达。App 可用于道歉、冷战后复联、伴侣争吵、朋友误会、亲子冲突和职场关系恢复。', '["关系修复", "道歉", "影响", "安全感", "冷战", "亲密关系", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 35, now()),
(100036, '福格行为模型：行为发生要同时具备动机、能力与提示', '当用户说“我知道该做但就是做不到”时，优先从行为设计入手。一个行为要发生，通常需要动机足够、能力门槛足够低、提示在正确时间出现。动机最不稳定，不能把改变押在热血上；更可靠的方式是把行为缩小到几乎不会失败，并绑定已有习惯。比如“刷牙后做一次深呼吸”“进门后先问一句今天怎么样”。先让行为发生，再让身份感和自信跟上。', '["行为改变", "福格模型", "微习惯", "动机", "提示", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 36, now()),
(100037, '微习惯设计：小到不会失败，才容易长期坚持', '很多改变失败不是因为目标太小，而是第一步太大。微习惯的关键是把行动拆到两分钟内可完成，先追求“出现”而不是“完美”。用户想读书，可先设为“打开书读一段”；想运动，可先设为“穿上鞋出门站一分钟”。完成后及时给自己一个正向标记，让大脑把新行为和成就感连接起来。稳定后再自然加量，而不是一开始靠逼迫冲刺。', '["微习惯", "行动设计", "成长", "自我效能", "坚持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 37, now()),
(100038, '习惯回路：找出提示、惯常行为和奖励', '习惯不是单个动作，而是“提示—惯常行为—奖励”的回路。想改变坏习惯，先观察它通常在什么时候、什么情绪、什么地点、和谁在一起时发生，再识别真正奖励：是放松、逃避压力、获得刺激，还是寻求连接。不要只删除行为，而要保留奖励、替换动作。例如压力大就刷短视频，可能真正需要的是短暂恢复；可替换成五分钟散步、伸展或给朋友发一句话。', '["习惯回路", "行为改变", "奖励", "提示", "替代行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 38, now()),
(100039, '自控力不是硬扛，而是提前设计环境', '自控力资料的核心提醒是：越到诱惑现场才靠意志力，越容易失败。更有效的是提前改环境，让好行为更容易、坏行为更麻烦。想少刷手机，把手机放远、关通知、设置固定查看窗口；想控制饮食，不把高诱惑食物放在手边；想避免情绪化回复，先写草稿不发送。自控不是讨厌自己，而是承认人会受情境影响，然后温和地设计情境。', '["自控力", "环境设计", "意志力", "诱惑", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 39, now()),
(100040, '拖延的背后常是情绪调节，而不是懒', '拖延往往不是时间管理问题，而是情绪管理问题：任务让人感到羞耻、恐惧、无聊或无力，于是大脑选择短期缓解。处理拖延时，不要只问“怎么提高效率”，先问“我在回避哪种感受”。可把任务拆成下一步可见动作，并设置低压力开始仪式：只做五分钟、只写标题、只打开文件。开始后焦虑下降，行动会反过来带来掌控感。', '["拖延", "情绪调节", "行动", "自我效能", "任务拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 40, now()),
(100041, '认知觉醒：改变先从注意力回到当下开始', '成长不是一口气重塑人生，而是逐步看见自动反应。认知觉醒强调把注意力从模糊焦虑拉回具体事实：我现在在想什么、身体有什么感觉、下一步最小行动是什么。用户陷入“我不行、来不及、都完了”时，可先把大问题拆成可观察的场景和可执行的十分钟行动。觉察不是想明白一切，而是让自己从自动驾驶切回主动驾驶。', '["认知觉醒", "注意力", "自我改变", "行动", "觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 41, now()),
(100042, '成长型改变：先做实验，不急着定义自己', '当用户把一次失败解释成“我就是这种人”，改变会被身份标签锁死。更好的语言是实验：这次策略不适合我，下一次换一个提示、环境或支持方式。把改变当实验，可以降低羞耻感，也能保留复盘能力。每次只调整一个变量，例如时间、地点、同行者、任务大小或奖励方式。真正重要的不是一次做对，而是形成可迭代的自我更新系统。', '["成长", "实验思维", "复盘", "身份", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 42, now()),
(100043, '焦虑自助：先区分真实问题和假想灾难', '焦虑会把可能性伪装成确定性，让人提前生活在最坏结果里。处理时先写下担心内容，再分成两类：真实可行动的问题，和目前无法验证的灾难想象。前者列出下一步行动；后者练习延迟担心、回到身体和现实证据。不要和焦虑争辩“别想了”，而是问：我现在能做哪一个具体动作？如果不能行动，我能否先照顾身体，让神经系统降档？', '["焦虑", "认知行为", "担心", "情绪调节", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 43, now()),
(100044, '情绪粒度：说得越准确，越容易选对行动', '“我很烦”通常太粗糙，无法指导行动。情绪粒度训练是把模糊难受细分：委屈、羞耻、嫉妒、失望、担心、孤独、被忽视、无力、愤怒。不同情绪需要不同回应：失望需要调整期待，羞耻需要自我接纳，愤怒常提示边界，孤独提示连接需求。App 回答情绪问题时，应先帮用户命名感受，再从感受背后的需要进入行动建议。', '["情绪", "情绪粒度", "自我觉察", "需要", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 44, now()),
(100045, '情绪急救：心理小伤也要及时处理', '拒绝、孤独、失败、反刍和自责就像心理擦伤，如果不处理会扩大成长期痛苦。情绪急救的重点不是立刻积极，而是防止二次伤害：不要用一次拒绝证明自己不值得，不要让失败变成全面否定，不要在脑内反复播放羞辱场景。可用三步处理：承认受伤，给出多个解释，做一个能恢复自尊或连接的小行动。', '["情绪急救", "拒绝", "孤独", "失败", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 45, now()),
(100046, '创伤反应：身体会先于理性进入防御', '创伤相关资料提醒，很多“反应过度”其实是身体把当下误判为过去的危险。用户突然僵住、爆发、逃离、麻木，并不一定是矫情，而可能是神经系统进入战斗、逃跑、冻结或讨好。支持方式不是逼自己马上讲道理，而是先恢复安全：看见周围环境、触碰稳定物体、慢慢呼气、让身体知道此刻已经不同于过去。稳定后再处理故事和意义。', '["创伤", "身体反应", "安全感", "神经系统", "疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 46, now()),
(100047, '愤怒的积极功能：它常在提醒边界被侵犯', '愤怒并不总是坏情绪，它常提示某个边界、价值或需求被忽视。问题不在愤怒本身，而在表达方式。用户生气时可先问：我在保护什么？我希望对方停止什么、开始什么、理解什么？等身体降温后，用边界句表达：“当发生 X 时，我感到 Y，因为我需要 Z；下次请具体做 A。”这样既不压抑愤怒，也不让愤怒变成攻击。', '["愤怒", "边界", "情绪管理", "需求", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 47, now()),
(100048, '抑郁低谷：先恢复行动循环，再追求意义感', '抑郁状态会让人失去动力，而失去行动又会进一步降低情绪。支持用户时，不宜只说“想开点”。更实用的是行为激活：每天安排极小、可完成、可记录的行动，如洗澡、晒太阳、走五分钟、整理一小块桌面、联系一个安全的人。行动不是为了立刻开心，而是重建“我还能影响一点点生活”的证据。必要时建议寻求专业支持。', '["抑郁", "行为激活", "低谷", "行动", "支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 48, now()),
(100049, '反刍思维：把脑内复盘变成纸面问题', '反刍会让人以为自己在解决问题，实际是在重复痛苦。识别标志是：想了很久却没有新信息、没有行动、情绪更糟。可把脑内循环写成三个问题：我正在反复想哪句话？它对应的事实证据是什么？我能采取的最小行动是什么？如果没有行动，就给担心设置时间盒，转向身体活动或连接他人。把想法落到纸面，能把情绪风暴变成可处理对象。', '["反刍", "焦虑", "情绪急救", "书写", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 49, now()),
(100050, '存在焦虑：意义不是找到标准答案，而是承担选择', '存在主义心理治疗提醒，人的痛苦不只来自症状，也来自自由、孤独、死亡和意义感。用户问“我到底为什么活着”时，不必急着给鸡汤答案。可以引导其看见：意义往往不是被发现的固定物，而是在选择、关系、创造和承担中生成。先从一个愿意负责的小选择开始：今天我想怎样对待身体、关系、工作或某个重要价值？', '["存在主义", "意义感", "选择", "自由", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 50, now()),
(100051, '依恋系统：亲密关系里的追和躲都是求安全', '亲密关系中的“追问”和“冷处理”常不是单纯作或无情，而是两种安全策略。焦虑型通过靠近、确认、解释来降低不安；回避型通过拉开距离、沉默、强调独立来恢复掌控。若双方只攻击表层行为，就会形成越追越逃。修复时要翻译需求：追的一方需要可预期回应，躲的一方需要不被淹没的空间。先约定冷静时长和恢复沟通时间，比无限争对错更有效。', '["依恋", "亲密关系", "追逃循环", "安全感", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 51, now()),
(100052, '爱的五种语言：用对方能接收的方式表达爱', '很多关系并非没有爱，而是表达通道错位。爱的五种语言包括肯定的话语、高质量陪伴、接受礼物、服务行动和身体接触。用户可以观察伴侣最常抱怨什么、最常主动给出什么、最容易因什么感动，来判断主要爱语。关系经营不是只用自己喜欢的方式付出，而是学习对方能接收的方式，同时也清楚告诉对方自己需要什么。', '["亲密关系", "爱的五种语言", "伴侣", "表达爱", "需求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 52, now()),
(100053, '伴侣冲突：先分清事实、解释和感受', '伴侣争吵常把事实、解释和感受混在一起：“你又不在乎我”其实可能包含事实“你迟到了三十分钟”、解释“你不重视我”、感受“我失望和不安”。修复时先拆开三层，事实越具体越少争议，解释越开放越能对话，感受越真诚越容易被听见。可以说：“你晚到三十分钟时，我脑中解释成自己不重要，所以很失落。我想知道实际发生了什么。”', '["伴侣沟通", "冲突修复", "事实", "感受", "解释"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 53, now()),
(100054, '亲子沟通：先连接，再纠正', '儿童沟通资料的一个关键原则是：孩子在被理解前很难真正听见道理。亲子冲突中，先描述孩子可能的感受和愿望，再谈规则与后果。比如“你很想继续玩，所以被叫停很生气”，比“别闹了”更能降低防御。连接不是纵容，而是先让孩子的大脑从对抗状态回到可学习状态。之后再给有限选择和清晰边界。', '["亲子沟通", "儿童心理", "连接", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 54, now()),
(100055, '家庭关系中的边界：爱不是互相吞没', '家庭里常把“我都是为你好”当成越界理由。健康边界不是冷漠，而是区分谁的情绪、选择和后果由谁负责。用户面对父母、伴侣或孩子的压力时，可用三句式：我理解你的担心；这件事我会自己决定；我愿意在某个范围内和你讨论。边界需要温和重复，不必每次都证明自己有资格说不。', '["家庭关系", "边界", "自主", "沟通", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 55, now()),
(100056, '人际游戏：反复上演的冲突通常有隐藏收益', '沟通分析资料强调，有些冲突像固定剧本：表面在解决问题，实际在重复熟悉角色，例如“你看我多可怜”“你总是错”“只有我能救你”。这些游戏会带来隐藏收益：避免真正亲密、证明旧信念、获得注意或逃避责任。识别方法是看结局是否总相似、情绪是否熟悉、双方是否越谈越远。退出游戏的第一步，是拒绝继续扮演被分配的角色。', '["沟通分析", "人际游戏", "关系模式", "责任", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 56, now()),
(100057, '讨好型关系：把“被喜欢”从生存需求降级为普通愿望', '讨好型模式会让人把别人的满意当作安全来源。用户需要练习把“希望被喜欢”与“必须被喜欢才能安全”分开。可以从低风险场景练习表达偏好：今天我想吃这个、这个时间我不方便、我需要考虑一下。每一次没有迎合却仍然安全，都会给神经系统新证据。边界不是突然强硬，而是逐步把自我带回关系中。', '["讨好型人格", "边界", "关系", "自我价值", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 57, now()),
(100058, '关键对话开场：用共同目的降低防御', '高风险对话开始前，先不要急着陈述立场，而要建立共同目的。共同目的回答的是：我们为什么值得继续谈？例如“我不是想追责，而是想让之后合作更顺”“我想谈这件事，是因为这段关系对我重要”。当对方感到你不是来羞辱或控制，才可能从防御转向合作。事实、感受和请求都应服务于共同目的。', '["关键对话", "共同目的", "安全感", "高难沟通", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 58, now()),
(100059, '非暴力沟通的难点：请求必须具体且可拒绝', '非暴力沟通不只是温柔说话。很多人把要求伪装成请求，例如“你能不能尊重我一点”。真正的请求要具体、当下、可执行、可拒绝，如“今晚十点前能否把行程告诉我”。如果对方不能拒绝，那更像控制；如果不够具体，对方不知道怎么做。清楚请求能让关系从猜测和指责转向协商。', '["非暴力沟通", "请求", "需要", "边界", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 59, now()),
(100060, '共情不是同意，而是准确理解对方的内在经验', '共情力的重点不是替对方辩护，也不是放弃自己的立场，而是先准确复述对方的感受、需要和处境。有效共情常包含三层：你经历了什么，你因此有什么感受，这背后什么对你重要。共情之后仍可以设边界。比如“我听见你很委屈，也很想被支持；同时我不能接受用吼叫继续谈。”这样既连接，也不纵容。', '["共情", "倾听", "边界", "沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 60, now()),
(100061, 'NLP地图：人回应的是自己的解释系统', '沟通中，别人不是直接回应现实，而是回应自己脑中的地图：经验、信念、价值和语言习惯。同一句话可能被理解成建议、批评、控制或关心。遇到误解时，不要只重复原话，可换一种感官通道和框架：给画面、给步骤、给感受、给选择。先理解对方地图，再邀请对方更新地图，比强迫对方接受自己的版本更有效。', '["NLP", "地图不是疆域", "沟通", "信念", "换框"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 61, now()),
(100062, '语言风格会透露关系位置和情绪距离', '语言风格资料提醒，词语不只传递内容，也传递关系位置。频繁使用绝对化词汇会增加压迫感；大量“你总是、你从不”容易引发防御；只讲道理不说感受，会让亲密关系变冷；过度道歉可能暴露低位和讨好。App 在润色沟通话术时，应把攻击性判断改成具体事实，把绝对化改成当下情境，把隐藏需求说清楚。', '["语言风格", "沟通", "关系位置", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 62, now()),
(100063, '影响力原则：先建立可信度，再提出请求', '影响力不是操控，而是降低对方理解和决策成本。常见有效因素包括互惠、承诺一致、社会认同、喜好、权威和稀缺。但在关系和咨询场景中，最重要的是可信度与尊重。先说明共同利益、展示理解、给出选择，再提出具体请求。若只利用技巧压迫对方，即使短期有效，也会破坏信任。', '["影响力", "说服", "信任", "请求", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 63, now()),
(100064, '金字塔表达：先给结论，再给理由和行动', '用户需要向伴侣、客户或团队说明复杂问题时，可使用金字塔结构：先说核心结论，再给三到四个理由，最后给下一步行动。这样能减少对方在信息中的迷路感。情绪沟通也可借用：我的结论是我希望我们调整相处方式；理由是最近三次约定都失效、我感到不安、我仍重视关系；下一步是我们约定一个可执行规则。', '["金字塔原理", "表达结构", "沟通", "结论先行", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 64, now()),
(100065, '谈判不是压倒对方，而是扩大可交换资源', '谈判资料适合转化为关系协商建议：不要只盯一个立场，而要找背后的利益。双方争“谁对谁错”时，资源只有面子；转向“各自真正想保护什么”时，可能出现时间、方式、顺序、补偿、试行期等多个变量。好的谈判不是让一方认输，而是创造比僵持更好的交换方案。', '["谈判", "利益", "协商", "冲突解决", "双赢"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 65, now()),
(100066, '九型领导力：不同型号需要不同反馈方式', '九型用于管理和关系时，不是贴标签，而是调整沟通入口。1号重标准，反馈要具体且尊重其原则；2号重关系，先肯定付出再邀请表达需求；3号重成果，给清晰目标和真实反馈；4号重独特和意义，避免轻率否定感受；5号重边界，提前给信息；6号重安全，说明依据与风险；7号重自由，给选择；8号重直接，少绕弯；9号重和谐，要明确邀请其立场。', '["九型人格", "领导力", "反馈", "沟通", "团队"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 66, now()),
(100067, '人格识别：看注意力焦点，不只看外在行为', '同一种行为可能来自不同动机。努力工作可能是1号的责任、3号的成就、6号的安全、8号的掌控；照顾别人可能是2号的连接，也可能是9号避免冲突。识别九型时，应观察注意力自动被什么吸走：错误、需求、形象、缺失、边界、风险、可能性、力量还是和谐。动机比行为更稳定，也更适合给出成长建议。', '["九型人格", "识别方法", "动机", "注意力", "性格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 67, now()),
(100068, '性格陷阱：早年适应策略长大后可能变成限制', '性格陷阱不是道德缺陷，而是曾经帮助人适应环境的策略在新场景中过度使用。比如过度警觉曾经保护自己，如今可能变成不信任；讨好曾经减少冲突，如今可能失去边界；控制曾经带来安全，如今可能压迫关系。成长不是否定过去的自己，而是感谢旧策略，再发展更多选择。', '["性格陷阱", "人格", "早年经验", "成长", "模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 68, now()),
(100069, '回避型模式：真正需要的不是消失，而是安全距离', '回避型用户常在关系变近时想逃，因为亲密被体验为压力、要求或失控。修复不是强迫自己立刻完全开放，而是学会表达安全距离：“我需要半小时冷静，但我会回来继续谈。”这样既保护空间，也减少对方被抛弃感。回避的成长方向，是把消失变成可预期的暂停，把独立变成有连接的独立。', '["回避型人格", "依恋", "亲密关系", "边界", "安全距离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 69, now()),
(100070, '人格障碍资料的启发：先看长期模式和功能损害', '面对“TA 是不是某种人格障碍”的问题，App 不应轻易诊断，而要引导用户观察长期模式：是否跨场景反复出现，是否导致关系、工作或自我功能受损，是否难以通过普通沟通调整。可提供非诊断性建议：保护边界、记录事实、减少被拉入极端互动，必要时寻求专业评估。知识库应避免给人贴病理标签。', '["人格", "边界", "关系风险", "非诊断", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 70, now()),
(100071, '系统思考：不要只盯事件，要看结构和反馈回路', '系统思考提醒，很多问题不是单次事件，而是结构持续制造同样结果。关系里反复争吵，可能有追逃反馈回路；工作中总拖延，可能有目标过大、反馈太慢、奖励缺失的结构。提问时从“谁错了”升级为“什么结构让这个结果反复发生”。找到反馈回路后，改变一个杠杆点，比反复责备更有效。', '["系统思考", "反馈回路", "关系模式", "行为改变", "结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 71, now()),
(100072, '批判性提问：先问证据，再问替代解释', '学会提问适合提升 App 回答的思辨质量。用户陷入单一解释时，可引导其问：我有什么证据？证据是否可靠？还有没有其他解释？这个结论有没有忽略例外？如果最好的朋友遇到同样情况，我会怎样判断？批判性思维不是否定一切，而是让情绪化判断多经过一道证据和替代解释的过滤。', '["批判性思维", "提问", "证据", "替代解释", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 72, now()),
(100073, '第三选择：从你赢我输转向共同创造', '冲突中的两难常被卡成“按你的”或“按我的”。第三选择思维要求先暂停立场竞争，进入理解和共创：我先真正理解你，你也理解我，然后我们一起找一个比双方原方案更好的方案。它特别适合亲密关系和团队冲突，因为关系质量本身也是结果的一部分。不是折中到双方都不满意，而是扩大问题框架。', '["第三选择", "冲突解决", "共创", "协作", "思维模型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 73, now()),
(100074, '社会性动物：人会被情境和群体强烈影响', '社会心理学提醒，人的行为不只来自性格，也受情境、规范、群体认同和他人期待影响。用户评价自己或他人时，不要过早归因为“人品就是这样”。可问：当时的压力、群体氛围、权威暗示、奖励惩罚、旁观者反应是什么？理解情境不是推卸责任，而是找到更有效的改变入口。', '["社会心理学", "情境", "群体", "归因", "行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 74, now()),
(100075, '态度改变：先降低威胁，再提供新经验', '态度很少因为被强行说服而改变。直接否定对方常会激发防御，让其更坚持原观点。更有效的是先承认其关切，再提供小的新经验或证据，让对方保留自尊地更新。亲密关系中也是如此：如果一开口就是“你错了”，对方会保护自我；如果先说“我理解你担心的是 X，同时我想补充 Y”，才更可能产生移动。', '["态度改变", "社会影响", "说服", "防御", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 75, now()),
(100076, '心智模型：同一问题要用多个镜头看', '高质量思维不是掌握一个万能模型，而是能切换镜头。遇到关系问题，可用依恋看安全感，用系统思考看互动回路，用非暴力沟通看需要，用九型看注意力焦点。遇到行动问题，可用习惯回路、福格模型和自控环境设计。多模型能避免把复杂人生简化成一句标签。', '["思维模型", "多元视角", "决策", "关系", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 76, now()),
(100077, '高品质思维：先选模型，再处理问题', '《30个高品质思维模型》OCR 后可提炼为一个实用原则：不要把所有问题都当成情绪、性格或努力问题。遇到选择困难，用机会成本和长期收益看；遇到反复冲突，用系统回路看；遇到沟通卡住，用换位和利益结构看；遇到目标失控，用拆解和反馈看。模型不是答案，而是提问方式。App 回答时可以先判断问题类型，再选择适合的思维框架，避免给出泛泛建议。', '["思维模型", "问题拆解", "决策", "系统思考", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 77, now()),
(100078, '人际吸引和自尊：关系问题常牵动自我评价', '社会心理资料显示，人际反馈会强烈影响自我评价。用户被冷落或拒绝时，痛苦不只来自事件，也来自“我是不是不值得”的解释。支持时应把事件和价值拆开：一次回应慢，不等于你没有价值；一次关系失败，不等于你不适合被爱。先稳住自尊，再决定是否沟通、调整期待或离开。', '["自尊", "人际关系", "拒绝", "社会心理", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 78, now()),
(100079, '人生阶段：成长任务会随着年龄和角色改变', '成年发展心理学提醒，不同阶段的核心任务不同：建立身份、亲密关系、事业责任、照顾下一代、重新整合意义。用户的困惑不一定是退步，可能是旧阶段策略无法满足新阶段任务。App 回答时可问：你现在处在人生哪个转折？这个问题是在要求你发展什么新能力？这样能把焦虑转化为发展任务。', '["成年发展", "人生阶段", "成长任务", "身份", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 79, now()),
(100080, '人性的弱点：被重视感是沟通的底层需求', '人际沟通中，很多人首先需要感到被尊重、被看见、被认真对待。赞美、记住名字、真诚兴趣、少批评多理解，并不是讨好技巧，而是在满足基本的被重视需求。用于 App 建议时，应避免机械取悦，而是提醒用户：先让对方感到自己不是被审判的对象，再提出观点或请求。', '["人际沟通", "尊重", "被看见", "关系", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 80, now()),
(100081, 'NLP目标框架：把愿望改写成可执行结果', 'NLP 资料适合转化为 App 的目标澄清工具：不要只说“我不要焦虑、不要吵架、不要拖延”，而要改成正向、具体、可验证、由自己能启动的结果。例如“我想在冲突开始后先暂停三十秒，再用事实和需要表达”。一个好目标要能回答：我想要什么，何时何地发生，如何知道达成，它对我和关系是否生态，第一步由谁开始。这样能把模糊愿望转为行动脚本。', '["NLP", "目标设定", "行为改变", "可执行", "正向目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 81, now()),
(100082, 'NLP感知位置：从我、你、旁观者三角度重看冲突', '处理冲突时，可用 NLP 的感知位置练习。第一位置是我：我看见什么、感到什么、需要什么；第二位置是对方：如果我是 TA，可能害怕什么、想保护什么；第三位置是旁观者：一个中立的人会如何描述双方互动。用户卡在委屈或愤怒中时，不要求立刻原谅，而是先切换观察位置。位置切换能降低单一叙事的黏性，让沟通从控诉转向理解和选择。', '["NLP", "感知位置", "换位思考", "冲突修复", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 82, now()),
(100083, 'NLP逻辑层次：别在身份层攻击，只在行为层调整', '沟通中最容易伤人的错误，是把行为问题上升到身份否定：“你就是自私”“我就是没用”。NLP 的逻辑层次可帮助拆分：环境、行为、能力、信念价值、身份、使命。越高层越敏感，越低层越可改。反馈别人时，应尽量落在具体行为和影响上；鼓励自己时，可以把失败从身份层降回策略层：不是我不行，而是这个方法、环境或能力训练还需要调整。', '["NLP", "逻辑层次", "身份", "反馈", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 83, now()),
(100084, 'NLP亲和感：先校准对方状态，再推动观点', '高效沟通不是急着输出观点，而是先建立亲和感。亲和不等于讨好，而是观察对方的节奏、情绪、用词和关注点，让对方感到被接上。用户想说服或修复关系时，可先复述对方关键词，确认理解，再提出自己的需要。若对方在压力中，先降低语速、减少结论、给出选择；若对方重结果，就给结构和下一步。先连接频道，再传递内容。', '["NLP", "亲和感", "校准", "影响力", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 84, now()),
(100085, 'NLP换框：问题行为背后常有未被满足的正向意图', '换框不是强行积极，而是寻找行为背后的功能。拖延可能在保护人免于羞耻，冷处理可能在保护人免于被淹没，控制可能在追求安全。识别正向意图后，仍要评估旧策略是否有代价，再寻找更成熟的替代方式。这样既不纵容问题行为，也不把人简单定罪。App 在回答关系和成长问题时，可先问“这个反应原本想帮你避免什么”。', '["NLP", "换框", "正向意图", "行为模式", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 85, now()),
(100086, '语言风格：功能词比大道理更透露心理状态', '语言风格资料强调，真正透露心理状态的往往不是华丽内容词，而是人称、虚词、连接词、否定词、时态等小词。一个人频繁使用“我”可能处在自我关注或压力中；大量绝对化词汇会让表达更封闭；过多否定和转折可能显示防御或矛盾。用于 App 时，不应把单个词当诊断，而是把语言线索作为理解用户情绪、关系位置和注意力焦点的辅助证据。', '["语言风格", "功能词", "心理线索", "自我觉察", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 86, now()),
(100087, '人称代词：我、你、我们会改变关系气氛', '沟通话术里，人称代词会影响关系气氛。只说“你怎么总是”容易让对方感到被审判；只说“我都怪我”容易让自己陷入低位；适度使用“我们”能提示共同面对问题，但若用“我们”掩盖个人责任，也会显得逃避。更成熟的表达是：我为自己的感受和请求负责，你为你的选择负责，我们一起决定下一步规则。', '["人称代词", "关系沟通", "责任", "表达", "语言风格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 87, now()),
(100088, '语言同步：相似的表达节奏能增加被理解感', '语言风格研究提示，人在连接顺畅时，表达节奏、词类和关注点会自然靠近。关系沟通中，可以有意识地先使用对方熟悉的词和框架，再提出新观点。比如对方重视效率，就先谈结果和步骤；对方重视感受，就先谈体验和影响。同步不是模仿操控，而是降低理解成本。同步之后再温和引入不同意见，通常比直接反驳更容易被听见。', '["语言同步", "沟通", "亲和感", "表达节奏", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 88, now()),
(100089, '从绝对化语言回到具体事实', '冲突中的“总是、从不、每次、所有人都”会迅速放大威胁，让对方进入辩解。语言风格资料可用于提醒用户把绝对化改成具体事实：把“你从来不关心我”改成“这周三次我提到难受时，你都没有继续问”；把“我永远做不好”改成“这次演示有两处没有准备充分”。事实越具体，越能讨论；标签越绝对，越容易卡住。', '["绝对化语言", "事实表达", "冲突降温", "沟通", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 89, now()),
(100090, '书写能帮助整理情绪叙事', '语言与心理研究显示，把混乱经历写出来，能帮助人把情绪、事实和意义重新组织。App 可以引导用户做三段式书写：发生了什么；我当时有哪些感受和身体反应；这件事触碰了我什么需要，以及下一步我能做什么。书写不是为了美化痛苦，而是把脑内反刍转为外部文本，使人更容易看见模式、选择行动。', '["书写疗愈", "情绪整理", "反刍", "语言", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 90, now()),
(100091, '九型发展层级：同一型号也有健康和失衡差异', '《九型人格2》强调，同一人格类型不是固定表现，而会随健康水平呈现不同层级。健康状态下，类型天赋会服务于生命：1号正直、2号慈悲、3号真实高效、4号创造、5号洞察、6号勇敢、7号喜悦、8号保护、9号安定。失衡时，同一能量会扭曲成批判、索取、表演、沉溺、抽离、怀疑、逃避、控制或麻木。因此 App 使用九型时，应同时判断主型和状态，而不是看到一个行为就定型。', '["九型人格", "发展层级", "健康状态", "失衡", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 91, now()),
(100092, '九型误判：理想自我不等于真实类型', '很多人测九型时会把“我想成为的人”误认为“我真实的自动策略”。例如想显得善良而选2号，想显得强大而选8号，想显得理性而选5号。更可靠的识别方式，是看压力下最自动的防御、反复出现的恐惧和注意力焦点。真正的类型常让人有一点被看穿，而不只是感觉很喜欢。App 解读时应提示用户：问卷只是入口，动机和长期模式更重要。', '["九型人格", "误判", "理想自我", "动机", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 92, now()),
(100093, '九型应用：不要用类型限制人，要用类型增加选择', '九型知识容易被误用成标签：“我是6号所以我就是焦虑”“他是8号所以没法沟通”。更成熟的用法是看见自动模式，然后增加选择。类型解释了为什么某些问题反复出现，但不决定人只能这样。App 回答应避免“你就是某型所以必然如何”，而应说“如果你有这种模式，可以尝试发展相反能力”。九型的目标是自由，不是把人关进九个盒子。', '["九型人格", "标签风险", "自由", "成长", "自我超越"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 93, now()),
(100094, '九型矛盾感：人会在不同场景表现出多个类型影子', '用户常问“为什么我像好几个型号”。九型人格2的一个实用提醒是：人会在不同关系、压力和角色中呈现多个类型的影子，但核心类型仍看最深层动机和防御。一个人可以既慷慨又自私，既温和又攻击，既理性又情绪化；这些矛盾不一定说明类型混乱，而可能是侧翼、压力线、安全线、健康层级和社会角色共同作用。识别时要看长期重复的主旋律。', '["九型人格", "侧翼", "压力线", "情境", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 94, now()),
(100095, '九型关系建议：先看对方害怕失去什么', '九型用于关系沟通时，可以先问“这个型号最怕失去什么”。1号怕失去正确和尊严，2号怕失去被需要，3号怕失去价值和认可，4号怕失去真实自我，5号怕失去空间和资源，6号怕失去安全和支持，7号怕失去自由和可能性，8号怕失去掌控和脆弱保护，9号怕失去和谐。理解恐惧后，沟通更容易避开对方防御，也更能提出对方听得进去的请求。', '["九型人格", "关系沟通", "核心恐惧", "防御", "理解他人"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 95, now()),
(100096, '情绪亲密：亲密关系的核心是能共同承受真实情绪', '情绪亲密不是两个人永远开心，而是双方能在恐惧、羞耻、愤怒、悲伤和脆弱出现时仍保持连接。很多关系疏远不是因为没有爱，而是情绪一强就进入攻击、退缩、讲道理或转移。App 回答亲密关系问题时，可以引导用户先说“我此刻真实感到什么”，再说“我需要怎样被回应”。能被安全表达和接住的情绪，会成为关系更深的入口。', '["情绪亲密", "亲密关系", "脆弱", "安全感", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 96, now()),
(100097, '适应性情绪与非适应性情绪要分开处理', '情绪资料区分适应性和非适应性情绪。适应性恐惧提醒真实风险，适应性愤怒保护边界，适应性羞耻帮助人回到关系伦理；非适应性情绪则常来自旧创伤、过度解释或环境误判，会让人反复陷入不合比例的反应。处理时不要笼统压制情绪，而要问：这份情绪在当下是否提供有效信息？如果是，转化为行动；如果不是，先安抚身体和旧经验。', '["情绪管理", "适应性情绪", "恐惧", "愤怒", "羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 97, now()),
(100098, '羞耻感的修复：从我不好回到我做了什么', '健康羞耻能提醒人尊重边界和关系，但有毒羞耻会把具体行为变成身份否定：“我错了”变成“我这个人很糟”。用户陷入羞耻时，应先把身份和行为分开：我做了某件需要承担的事，不等于我没有价值。修复顺序是承认影响、承担责任、表达歉意、做出补偿，同时停止用自我攻击替代真实改变。', '["羞耻", "自我价值", "修复", "责任", "情绪亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 98, now()),
(100099, '悲伤不是软弱，它帮助人承认失去并重新连接', '悲伤常被误解为负能量，但它的功能是帮助人承认失去、放下无法挽回的部分，并重新寻找连接。用户失恋、关系破裂或人生阶段结束时，不必急着“振作”。可以允许悲伤有时间、身体感和表达出口：哭、写下失去、讲给安全的人听、为告别做一个仪式。悲伤被看见后，人才能把爱和意义带入下一阶段。', '["悲伤", "失去", "情绪疗愈", "亲密关系", "告别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 99, now()),
(100100, '情绪表达要同时包含感受、需要和边界', '只表达情绪而没有需要，容易变成宣泄；只有边界而没有感受，容易显得冷硬；只有需要而没有边界，容易陷入讨好。情绪亲密中的成熟表达可以是：“我感到害怕和失落，因为我需要稳定回应；如果你需要空间，请告诉我多久后回来谈。”这类表达既让对方知道你内在发生了什么，也给出可协商的行动方向。', '["情绪表达", "需要", "边界", "关系沟通", "亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 100, now()),
(100101, '愤怒控制：先识别身体预警，而不是等爆发后补救', '愤怒很少突然出现，身体通常会先给信号：心跳加快、肩颈绷紧、脸热、拳头握紧、呼吸变浅、声音提高。控制愤怒的第一步不是讲道理，而是建立预警清单。一旦信号出现，就先暂停、离开刺激源、延长呼气、喝水或让身体移动。越早在低强度阶段介入，越不需要在高强度爆发后道歉和修复。', '["愤怒管理", "身体信号", "暂停", "情绪调节", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 101, now()),
(100102, '愤怒情境记录：找出触发点、想法和后果', '控制愤怒需要记录模式。每次愤怒后可写四项：触发事件是什么；我当时脑中冒出的解释是什么；身体和行为如何反应；结果是解决了问题还是扩大了伤害。几次记录后，用户会看见常见触发点，如被否定、等待、失控、被催促或感到不公平。看见模式后，才能提前设计替代反应，而不是每次都以为只是对方惹我。', '["愤怒管理", "情境记录", "触发点", "认知", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 102, now()),
(100103, '破坏性愤怒与建设性边界要区分', '愤怒本身能提供边界信息，但破坏性愤怒会通过羞辱、威胁、冷暴力或攻击来伤害关系。建设性边界则把能量转成清楚要求：“这件事我不能接受”“我们暂停十分钟再谈”“下次请提前告诉我”。App 回答用户“我一生气就伤人”时，应同时承认愤怒背后的需求，并训练非伤害性的表达方式。目标不是没有愤怒，而是不让愤怒掌舵。', '["愤怒", "边界", "关系修复", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 103, now()),
(100104, '愤怒暂停协议：离开不是逃避，回来才是关键', '冲突升温时，暂停比继续争输赢更有用。但暂停必须有协议，否则会被体验成冷暴力或抛弃。可说：“我现在太激动，继续会伤人。我需要二十分钟冷静，八点二十回来继续谈。”暂停期间不反刍、不写攻击长文，而是降身体唤醒。关键是按约定回来，哪怕只先确认还愿意谈。这样既保护关系，也训练自我控制。', '["愤怒暂停", "冲突降温", "冷静期", "关系安全", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 104, now()),
(100105, '愤怒后的修复：不要只解释动机，要承认影响', '愤怒爆发后，很多人急着解释“我不是故意的”。但对方首先需要听见影响被承认。修复顺序可以是：我刚才提高音量/说了伤人的话；这让你感到害怕或受伤；这部分我负责；下次我会在身体信号出现时暂停；现在我想听听你的感受。解释动机可以放后面，不能替代承担影响。真正的道歉要带行为改变。', '["愤怒修复", "道歉", "影响", "责任", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 105, now()),
(100106, '抑郁康复：低谷中先建立支持网络，而不是独自硬扛', '抑郁相关案例资料提醒，走出低谷很少只靠一个人的意志力。用户陷入持续无力、绝望或自责时，应优先建立支持网络：可信任的亲友、专业咨询或医疗资源、规律作息、身体活动和危机联系人。支持不是替用户解决人生，而是在其能量最低时提供外部结构。App 回答时应鼓励用户把“我必须自己扛”改成“我可以借助系统恢复”。', '["抑郁", "支持系统", "康复", "心理健康", "低谷"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 106, now()),
(100107, '抑郁中的小行动：先恢复生活节律，再追求动力', '抑郁会让人等待“有动力再行动”，但恢复常常相反：先用极小行动恢复节律，再让动力慢慢回来。可从睡眠、饮食、晒光、洗漱、散步、联系一个安全的人开始，每天只记录是否完成，不用要求情绪立刻变好。小行动的作用不是证明自己强大，而是给大脑和身体重新建立可预测的安全感。', '["抑郁", "行为激活", "生活节律", "小行动", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 107, now()),
(100108, '双相和重度低谷：App 不做诊断，但要识别求助信号', '资料涉及抑郁和双相困境时，App 应保持非诊断原则：不根据聊天直接下诊断，但要识别风险信号。若用户出现持续失眠或嗜睡、明显功能下降、极端绝望、自伤念头、冲动高涨或情绪大幅波动，应建议尽快联系专业医生、咨询师或身边可信任的人。知识库给出的作用是陪伴、稳定和转介，不替代临床评估。', '["抑郁", "双相", "风险识别", "专业求助", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 108, now()),
(100109, '康复叙事：真实故事能给低谷者带来可恢复的证据', '抑郁康复案例的价值，不在于要求用户照搬别人的路径，而在于提供“人可以从深渊回来”的证据。App 回答低谷用户时，可以把康复描述为多因素过程：承认病痛、求助、调整环境、重建节律、学习情绪技能、逐步恢复关系和意义。避免把成功故事变成压力，而要把它变成希望：你不需要立刻好起来，只需要开始被支持。', '["康复故事", "希望感", "抑郁", "支持", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 109, now()),
(100110, '言语行为：一句话不仅传递信息，也在完成行动', '言语行为理论适合提升 App 的沟通建议：很多话不是单纯描述，而是在做事。道歉是在承担，承诺是在建立未来义务，请求是在邀请合作，指责是在分配责任，命令是在施加权力。因此沟通问题不能只看字面内容，还要看这句话完成了什么关系动作。用户想修复关系时，应选择能完成连接、澄清、承担和请求的语言，而不是无意识地完成攻击。', '["言语行为", "沟通", "道歉", "承诺", "关系动作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 110, now()),
(100111, '承诺表达：说“我会”时要明确条件、时间和行动', '承诺是一种言语行为，会改变关系中的期待。模糊承诺如“我以后会改”容易让对方再次失望；有效承诺要包含具体行动、时间、条件和复盘方式。例如“下次争吵时我会先暂停十分钟，晚上九点回来继续谈”。App 给用户生成道歉或修复话术时，应避免空泛保证，改成可观察的承诺。', '["承诺", "言语行为", "关系修复", "道歉", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 111, now()),
(100112, '请求和要求：真正的请求允许对方回应和协商', '从言语行为角度看，请求、要求和命令会创造不同关系位置。请求承认对方有选择，要求带有更强压力，命令则假设权力差。亲密关系中很多“你能不能”其实是包装过的命令，难怪引发防御。更成熟的表达是说明需要、提出具体请求，并允许对方说明难处：“我希望今晚能聊十分钟，你现在方便吗？”', '["请求", "要求", "边界", "关系沟通", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 112, now()),
(100113, '亲子沟通：孩子行为背后常有能力缺口和情绪需求', '亲子资料提醒，孩子的问题行为不一定是故意作对，常常是情绪调节、表达能力、规则理解或连接需求不足。家长若只用批评和惩罚，短期可能压住行为，长期会削弱信任。更有效的是先翻译行为：孩子在保护什么、害怕什么、还不会什么？然后同时给连接和边界。App 回答亲子问题时，应避免把孩子标签化为懒、坏或不懂事。', '["亲子沟通", "儿童情绪", "行为背后", "连接", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 113, now()),
(100114, '亲子冲突：先处理情绪，再处理道理和规则', '孩子情绪上来时，大脑很难接收长篇道理。亲子冲突的顺序应是：先让孩子知道自己的感受被看见，再明确规则，再给选择和后果。例如“你很想继续玩，所以被叫停很生气；但睡觉时间到了。你可以现在收玩具，或我陪你收两分钟。”先连接不是纵容，而是让孩子从对抗状态回到可合作状态。', '["亲子冲突", "情绪处理", "规则", "选择", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 114, now()),
(100115, '家长权威：稳定、一致和尊重比吼叫更有力量', '有效家长权威不是声音大，而是规则稳定、边界一致、态度尊重。孩子需要知道什么可以协商，什么不能越界，以及越界后会发生什么。若家长情绪化地时松时紧，孩子会不断测试边界。App 可建议家长提前约定少量关键规则，用简短语言重复，并在执行时减少羞辱。温和和坚定可以同时存在。', '["亲子教育", "权威", "规则", "边界", "稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 115, now()),
(100116, '培养孩子自我价值：多肯定努力、选择和品格', '亲子关系中，孩子不只需要被评价成绩，也需要确认自己作为人的价值。家长可以多肯定具体努力、选择、品格和成长：“你刚才虽然生气，但还是回来谈了”“你愿意尝试新方法”。这类反馈比泛泛说“你真棒”更能建立内在自我价值。App 回答亲子问题时，可把关注点从控制孩子转向发展孩子能力。', '["亲子关系", "自我价值", "肯定", "成长", "能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 116, now()),
(100117, '情绪是一种语言：每种情绪都在传递信息', '《情绪的语言》可提炼为核心原则：情绪不是需要消灭的噪音，而是身体和心理的语言。恐惧提示风险，愤怒提示边界，悲伤提示失去，羞耻提示关系伦理，嫉妒提示渴望和比较。App 回答情绪问题时，不应只让用户“别想太多”，而要帮助翻译：这份情绪想告诉我什么？它指向什么需要？我能采取什么成熟行动？', '["情绪语言", "情绪管理", "需要", "边界", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 117, now()),
(100118, '恐惧的功能：不是阻止行动，而是要求检查安全', '恐惧的作用是提示风险和未知。健康恐惧会让人收集信息、设定边界、做好准备；失衡恐惧则会让人冻结、逃避或过度想象。用户害怕时，可以先感谢恐惧在保护自己，再问：我需要确认什么事实？需要什么支持？最小安全行动是什么？这样恐惧从敌人变成风险评估系统。', '["恐惧", "安全", "风险评估", "情绪语言", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 118, now()),
(100119, '嫉妒的信息：看见自己真正渴望什么', '嫉妒常被羞耻化，但它也能暴露真实渴望。看到别人拥有关系、成就、自由或关注时，用户可以问：我羡慕的到底是什么？这代表我也想发展哪种能力或生活？成熟处理嫉妒，不是贬低对方，也不是贬低自己，而是把比较转化为愿望和行动。嫉妒被翻译后，可能成为自我探索的入口。', '["嫉妒", "渴望", "比较", "情绪语言", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 119, now()),
(100120, '悲痛需要仪式和见证，而不是被催促放下', '悲痛是失去之后的深层情绪，它需要时间、仪式和见证。如果一个人被催促“别难过了”，悲痛可能转入麻木或长期反刍。App 支持悲痛用户时，可引导其说出失去了什么、这份关系或阶段曾代表什么、想如何纪念和告别。放下不是遗忘，而是让爱和意义找到新的位置。', '["悲痛", "失去", "仪式", "情绪疗愈", "告别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 120, now()),
(100121, '简快疗法：改变不一定要长期分析全部过去', 'NLP 简快心理疗法强调，改变可以从当前资源、目标状态和可重复的新反应开始，而不一定要把所有过去细节分析完。App 可把它转化为实用问法：你想从现在的困境走向什么状态？你过去哪怕短暂体验过这种状态吗？当时有什么资源？下一次触发时，你能做哪个不同动作？这种取向适合把用户从反复解释带回行动练习。', '["NLP", "简快疗法", "资源", "目标状态", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 121, now()),
(100122, '资源取向：先找到用户已经拥有的例外经验', '当用户说“我从来做不到”时，简快疗法会寻找例外：有没有一次稍微好一点？有没有某个人、场景或状态下你能做到一点？例外不是否认问题，而是证明系统中已有资源。App 可以追问例外发生的条件，然后把它复制到新情境。比起只分析失败，寻找例外更能激活自我效能。', '["资源取向", "例外经验", "自我效能", "NLP", "改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 122, now()),
(100123, '次感元调整：改变内在画面会影响情绪强度', 'NLP 资料中常用内在表征理解情绪：同一记忆如果画面很大、很近、很亮、声音很强，情绪会更强；如果把画面拉远、变小、变暗，身体反应可能下降。App 可把这作为非临床的自我调节练习：当某个画面反复刺激你时，试着在想象中调节距离、大小和声音，同时回到呼吸和当下环境。', '["NLP", "次感元", "情绪调节", "想象", "自助练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 123, now()),
(100124, '信念松动：把绝对句改成可更新假设', '很多痛苦来自僵硬信念，如“我永远不被爱”“我一定会失败”。简快取向会把绝对信念改成可检验假设：在什么情境下它不完全成立？有没有反例？如果它只是旧保护策略，我现在能否更新它？App 回答时可帮助用户从身份化结论转向可调整信念，让改变有入口。', '["信念", "NLP", "认知调整", "绝对化", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 124, now()),
(100125, '沟通分析：关系互动中常有父母、成人、儿童三种自我状态', '沟通分析资料可转化为 App 的互动识别工具：人在交流时可能从父母自我状态说话，表现为批评、教导、保护；从成人自我状态说话，表现为事实、选择和协商；从儿童自我状态说话，表现为反抗、讨好、委屈或玩耍。冲突升级时，常是双方从成人状态滑入父母对儿童、儿童对父母。修复的关键是把话语拉回成人状态：讲事实、说感受、提请求、谈后果。', '["沟通分析", "自我状态", "成人状态", "关系沟通", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 125, now()),
(100126, '心理游戏：反复冲突背后常有熟悉但痛苦的脚本', '伯恩的人际游戏理论提醒，很多关系冲突表面在讨论事情，实际在重复固定脚本：受害者等待被拯救，拯救者过度负责后委屈，迫害者用指责获得控制。游戏的结局通常很熟悉：双方都证明了自己的旧信念。App 可帮助用户识别：这场争吵是不是又走到同一个结局？我正在扮演哪个角色？我能否退出脚本，改用成人状态表达需要和边界？', '["心理游戏", "沟通分析", "戏剧三角", "关系模式", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 126, now()),
(100127, '退出人际游戏：不接角色，回到真实请求', '退出心理游戏不是赢过对方，而是不再接下被分配的角色。对方指责时，不进入反击；对方求救但拒绝负责时，不急着拯救；自己想委屈控诉时，先问真正请求是什么。可用句式：“我愿意谈具体问题，但不接受互相羞辱。”“你希望我具体怎么帮？哪一步由你自己做？”把隐藏交易改成明说请求，游戏就失去动力。', '["人际游戏", "退出脚本", "真实请求", "边界", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 127, now()),
(100128, '亲密与自主：好的关系不是玩游戏，而是直接表达', '沟通分析的成长方向是从心理游戏走向自主和亲密。自主意味着能觉察自己的脚本，而不是自动重复；亲密意味着能直接表达真实感受和需要，而不是用拐弯、测试、讽刺或冷战获取回应。App 在关系咨询中可引导用户把“你猜我怎么了”换成“我现在需要被听见”，把测试对方换成清楚请求。', '["亲密关系", "自主", "沟通分析", "真实表达", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 128, now()),
(100129, '儿童心理：不要把成人逻辑直接套到孩子身上', '儿童心理学提醒，孩子不是缩小版成人。不同发展阶段的注意力、情绪调节、语言表达、因果理解和自我控制能力都不同。家长如果用成人标准要求孩子“马上懂事”，容易把能力不足误解成故意作对。App 回答亲子问题时，应先判断孩子可能处于什么发展阶段，再给出符合年龄的规则、选择和练习。', '["儿童心理", "发展阶段", "亲子教育", "情绪调节", "能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 129, now()),
(100130, '儿童问题行为：先看发展任务，再看教育方法', '孩子的退缩、攻击、撒谎、拖延或哭闹，可能对应不同发展任务：争取自主、寻求连接、表达挫败、测试边界或回避羞耻。处理时先问这个行为在孩子的发展中服务什么，而不是直接贴坏习惯标签。家长需要同时提供安全关系和稳定边界，让孩子在可承受的范围里学习表达、等待、协商和承担后果。', '["儿童行为", "亲子关系", "发展任务", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 130, now()),
(100131, '家长焦虑会进入孩子系统', '儿童心理资料强调，家长的焦虑、冲突和不稳定会影响孩子的安全感。孩子很多时候不是听家长说什么，而是感受家庭气氛。若父母长期紧张、指责或忽冷忽热，孩子可能用问题行为表达系统压力。App 可建议家长先调节自身情绪，再处理孩子行为：降低音量、明确规则、减少羞辱、保持可预测的回应。', '["家长焦虑", "儿童安全感", "家庭系统", "亲子沟通", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 131, now()),
(100132, '拖延循环：短期逃避会强化长期焦虑', '拖延症资料指出，拖延的即时奖励是缓解不舒服：不用面对失败、评价、无聊或复杂任务。但短期舒服会带来长期焦虑，下一次更想逃。破循环的关键不是骂自己，而是识别“我正在用逃避换短暂轻松”。可以把任务拆到五分钟，先开始而不追求完成，并在开始后记录焦虑是否下降。行动会削弱拖延带来的假奖励。', '["拖延", "逃避", "焦虑", "行动", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 132, now()),
(100133, '拖延背后的完美主义：宁可不做也不愿做得不够好', '很多拖延来自完美主义：任务一旦开始，就可能暴露不足，所以大脑选择延后。用户可练习“低质量初稿”策略：先允许做出粗糙版本，再修改。把目标从一次做好改成先产生材料；把评价从结果改成是否开始。对完美型用户尤其重要：完成一个可改进的版本，比等待理想状态更接近真实成长。', '["拖延", "完美主义", "初稿", "行动", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 133, now()),
(100134, '反拖延计划：明确下一步、开始时间和障碍预案', '有效反拖延计划要具体到下一步，而不是写“我要努力”。格式可以是：在什么时间、什么地点、做哪一个动作、做多久、如果遇到阻碍怎么办。例如“晚饭后八点，在书桌前打开文档写标题十分钟；如果想刷手机，就把手机放到客厅”。计划越可执行，越不依赖临时情绪。', '["反拖延", "计划", "执行意图", "障碍预案", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 134, now()),
(100135, '人际沟通：先听懂，再回应，而不是准备反驳', '人际沟通技巧资料强调，倾听不是沉默等待自己发言，而是主动理解对方的事实、感受和需要。有效回应可以先复述：“我听到你在意的是……你感到……对吗？”这会降低防御，让对方感到被看见。App 在生成沟通建议时，应先给倾听句，再给表达句，避免用户一上来就输出立场。', '["人际沟通", "倾听", "复述", "理解", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 135, now()),
(100136, '表达感受时少用指责，多用我信息', '“你让我很痛苦”容易让对方防御；“我在这件事里感到难过和不安”更容易被听见。我信息不是只谈自己，而是把事实、感受、影响和请求组合起来：当发生 X 时，我感到 Y，因为它影响 Z；我希望下次 A。这样既表达真实，又减少攻击。App 可把用户的指责句自动改写为我信息。', '["我信息", "感受表达", "人际沟通", "冲突降温", "请求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 136, now()),
(100137, '反馈技巧：具体行为比人格评价更有建设性', '给反馈时，评价人格会引发羞耻和抵抗；描述具体行为更可能带来改变。把“你不负责任”改成“这次约定的材料周三没有提交，导致项目延迟一天”。再说明影响、询问原因、共同制定下一步。无论亲密关系还是职场，反馈都应落在可观察行为上，而不是给人贴稳定标签。', '["反馈", "行为描述", "职场沟通", "关系沟通", "建设性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 137, now()),
(100138, '界限沟通：温和语气加清楚底线', '很多人以为有边界就必须强硬，其实边界可以温和但清楚。有效边界包含三部分：我理解你的处境；我能做的范围是；超出范围我不会做。比如“我知道你很急，我今晚可以帮你看十分钟，但不能替你完成全部。”温和让关系保持连接，清楚让对方知道规则。边界模糊才更容易积怨和爆发。', '["边界", "人际沟通", "底线", "温和坚定", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 138, now()),
(100139, '人格模式：先观察长期重复，而不是给人贴诊断', '人格障碍相关资料适合给 App 提供非诊断性框架：不要因为一次冲突就说某人是某种人格障碍，而要观察长期、跨场景、反复出现的模式，以及它是否造成关系、工作和自我功能受损。App 回答时应聚焦行为模式、边界和求助建议，而不是替用户给自己或他人下临床诊断。这样既能保护用户，也避免把复杂关系简化成标签。', '["人格模式", "非诊断", "关系风险", "边界", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 139, now()),
(100140, '人格障碍的认知视角：核心信念会驱动反复行为', '认知治疗资料强调，很多持久的人格模式背后有核心信念，例如“别人会伤害我”“我必须控制才安全”“我不值得被爱”“如果被拒绝就完了”。这些信念会让人选择性解读关系，并反复触发防御行为。App 可帮助用户把冲突从“我就是这样”拆成“我在什么信念下自动反应”，再寻找更平衡的新信念和行为实验。', '["认知治疗", "核心信念", "人格模式", "行为实验", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 140, now()),
(100141, '边缘化互动：强烈情绪下先稳定，再讨论关系结论', '人格障碍治疗资料中反复强调，强烈情绪会让关系判断变得极端：全好或全坏、亲密或抛弃、信任或背叛。App 不做诊断，但可给出稳定策略：当情绪强度过高时，先暂停关系结论，回到身体、事实和当下安全；等情绪降到可对话范围，再讨论事件、感受和请求。不要在情绪顶点做分手、拉黑、报复等重大决定。', '["强烈情绪", "关系判断", "稳定", "人格模式", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 141, now()),
(100142, '回避和依赖模式：一个怕靠近，一个怕分离', '人格相关资料可帮助理解两类关系困难：回避模式把亲密体验为压力和被吞没，因此倾向退缩；依赖模式把分离体验为危险，因此倾向黏附、确认和难以独立。App 回答关系问题时，可把表层行为翻译成安全需求，同时提醒用户发展相反能力：回避者练习可预期回应，依赖者练习自我安抚和独立选择。', '["回避", "依赖", "亲密关系", "安全感", "人格模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 142, now()),
(100143, '人格改变：不是消灭自己，而是增加反应选择', '认知行为疗法看重具体练习：识别触发情境、自动想法、情绪强度、行为后果，再设计新反应。人格改变不是否定整个人，而是让原本单一的防御策略多出选择。用户若总是攻击、讨好、退缩或控制，可以先记录触发点，再练习一个更小的新动作：停顿、提问、表达需要、设边界或寻求支持。', '["人格改变", "认知行为", "触发点", "新反应", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 143, now()),
(100144, '需求层次：先满足基础安全，再谈自我实现', '动机与人格资料提醒，人的成长需要基础条件。若用户长期缺睡、缺安全、缺支持、经济或关系高度不稳，却要求自己立刻自我实现，容易变成自责。App 可先判断问题处在哪一层需求：生理、安全、归属、尊重还是自我实现。越底层的需求越需要具体支持和稳定结构；越高层的需求越适合谈意义、创造和潜能。', '["需求层次", "马斯洛", "安全感", "自我实现", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 144, now()),
(100145, '自我实现：不是完美成功，而是更真实地成为自己', '马斯洛的自我实现不是外界眼中的完美人生，而是人的潜能、价值和创造力逐渐被活出来。它通常伴随更真实的自我接纳、更少迎合、更能投入当下、更愿意服务超出小我的价值。App 回答人生意义问题时，可引导用户从“我应该成为什么样”转向“什么让我更真实、更有生命力、更愿意贡献”。', '["自我实现", "真实自我", "意义感", "潜能", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 145, now()),
(100146, '高峰体验：短暂的完整感可以成为人生方向线索', '动机与人格中提到的高峰体验，可用于帮助用户回忆生命中短暂但强烈的完整、清明、感动或创造时刻。这些时刻不一定频繁，却能提示人的核心价值和潜能方向。App 可引导用户回忆：什么时候我感到特别真实、自由、宁静或被点亮？那里可能藏着比外部评价更可靠的成长线索。', '["高峰体验", "价值澄清", "生命力", "自我实现", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 146, now()),
(100147, '缺失性需要与成长性需要要区分', '缺失性需要来自匮乏，如缺安全、缺爱、缺尊重；成长性需要来自生命扩展，如创造、学习、贡献和理解。两者都重要，但处理方式不同。用户若在匮乏中追求成长，可能越努力越焦虑；若基础需求已相对稳定，却仍只追求补偿，也会感到空。App 可帮助用户判断：此刻我是在补缺口，还是在响应成长召唤？', '["缺失性需要", "成长性需要", "动机", "自我觉察", "人生阶段"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 147, now()),
(100148, '走出抑郁：抑郁会影响动机、注意力、睡眠和身体', '抑郁不仅是心情不好，它会影响动机、注意力、精力、睡眠、食欲、身体感和对快乐的体验。用户在抑郁状态下做不到平时能做的事，不应简单解释为懒或脆弱。App 回答时应把抑郁视为身心系统整体低能量状态，建议从睡眠、饮食、活动、支持和专业求助等多点恢复，而不是只靠一句“想开点”。', '["抑郁", "身心状态", "动机", "睡眠", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 148, now()),
(100149, '抑郁中的自责会加重抑郁循环', '抑郁状态下，人容易把精力下降、兴趣丧失、拖延和社交退缩解释成“我没用”。这种自责会进一步消耗能量，形成恶性循环。更有效的是把症状和身份分开：我现在处在低能量状态，不等于我没有价值。先减少自责，再做微小行动，才能逐步恢复掌控感。App 应帮助用户识别自责语言并改写为支持性语言。', '["抑郁", "自责", "自我价值", "支持性语言", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 149, now()),
(100150, '抑郁恢复需要活动计划，而不是等待心情变好', '走出抑郁的行为思路是：先安排可完成的小活动，再等待情绪慢慢回应。活动计划不必宏大，可从起床、洗漱、晒太阳、五分钟走路、整理一个角落开始。关键是可执行、可记录、可重复。用户若说“我没有动力”，App 可以回应：先不追求动力，先做一个小到可以完成的动作，让身体重新接触生活。', '["抑郁恢复", "活动计划", "行为激活", "小行动", "生活节律"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 150, now()),
(100151, '儿童绘画：画面是儿童表达情绪和经验的一种语言', '儿童绘画与心理治疗资料提醒，孩子常常无法直接用语言说出复杂感受，但会通过画面、颜色、大小、位置、重复主题和讲述方式表达经验。App 在亲子问题中可建议家长不要急着解释画得好坏，而是温和询问：“这是谁？发生了什么？你画这里时想到什么？”重点是让孩子讲述，而不是成人单方面解读。', '["儿童绘画", "儿童心理", "情绪表达", "亲子沟通", "治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 151, now()),
(100152, '解读儿童画：不能只凭单个符号下结论', '儿童画不能机械解码，例如黑色就代表抑郁、画怪物就代表创伤。更可靠的方式是结合孩子年龄、发展水平、生活事件、绘画过程和孩子自己的讲述。App 若涉及儿童画，应避免下诊断，只提供观察方向：主题是否反复出现，孩子讲述时情绪如何，画面与近期事件是否相关，是否需要专业儿童心理支持。', '["儿童画", "非诊断", "观察", "儿童心理", "亲子"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 152, now()),
(100153, '儿童创伤表达：重复主题可能是在寻求理解和整合', '在儿童绘画治疗中，反复出现的危险、分离、攻击、受伤或孤独主题，可能是在尝试表达尚未被整合的经验。家长不应立刻责备“别画这些”，也不应过度惊吓，而要提供安全的讲述空间。可说：“你愿意讲讲这幅画里的故事吗？”如果孩子持续痛苦、退缩或行为明显变化，应考虑专业评估和支持。', '["儿童创伤", "绘画表达", "安全讲述", "亲子支持", "心理治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 153, now()),
(100154, 'NLP过滤机制：误解常来自删减、扭曲与类推', '人在沟通中并不是原样接收现实，而会自动经过三类过滤：删减让人只注意部分信息；扭曲让事实被解释成批评、威胁或否定；类推会把一次经验扩展成“总是、从不、一定”。App 处理冲突时，可引导用户先做三问：我漏掉了哪些信息？还有哪些同样合理的解释？有没有反例说明这不是普遍规律？这样能把“对方就是针对我”降级为“我现在有一个解释，需要验证”。', '["NLP", "沟通模型", "删减", "扭曲", "类推", "误解修复", "提问"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 154, now()),
(100155, 'NLP表象系统：用对方能接收的感官通道组织语言', '不同人理解信息时偏好的通道不同：有人重“看见画面”，有人重“听到逻辑”，有人重“感觉是否踏实”，也有人依赖内在自我对话。沟通时不要只用自己习惯的表达方式，而要把关键信息翻译成多通道：画面是什么、听起来怎么说、身体或情绪感受如何、下一步怎么做。对方常用“看起来、听起来、感觉、我想”等词，可作为选择表达入口的线索。', '["NLP", "表象系统", "共同语言", "亲和感", "沟通表达", "感官通道"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 155, now()),
(100156, '小词汇审计：但是、试着、不要会悄悄改变行动暗示', '微小词汇会改变听者接收到的关系和行动暗示。“但是”容易否定前半句，可改成“同时/而且”；“试着”暗示困难和不确定，可改为具体承诺；“不要担心”会先唤起担心，可改成“先放松、先做第一步”；“这是很难的”把困难绝对化，可改成“我还没找到容易的方法”。App 生成沟通话术时，可加入小词汇审计，减少无意中的否定、无力和反向暗示。', '["语言风格", "NLP", "小词汇", "暗示", "沟通润色", "行动指令"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 156, now()),
(100157, '元程序沟通：先识别对方的动机过滤器，再选择说服入口', '影响他人不是把同一套理由重复给所有人，而是识别对方的“过滤器”：TA 更关注获得好处还是避免风险？喜欢选择空间还是固定程序？依据内部标准还是外部认可？更关心人、地点、活动、时间还是信息？同一个建议，对风险型用户要说明安全和代价，对机会型用户要说明收益和可能；对程序型用户给步骤，对选择型用户给选项。匹配元程序能降低理解阻力，但不能替代真实尊重。', '["NLP", "元程序", "影响力", "说服", "价值观", "职场沟通", "动机"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 157, now()),
(100158, '决策策略：把一次好决定拆成可复用的内在流程', '所谓策略，可以理解为一个人达成某个结果时反复使用的内在流程。面对选择困难时，不必只问“哪个更好”，可以回忆一次自己很满意的决定：当时先看见什么、听见什么、比较了哪些标准、想象了什么后果、身体如何确认、最后如何行动。把成功决策拆成步骤后，可形成个人模板；理解他人的决策策略，也有助于销售、谈判和关系协商。', '["NLP", "决策策略", "模拟卓越", "自我效能", "选择困难", "行为复制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 158, now()),
(100159, '表达性写作的四个语言信号：情绪、意义与视角切换', '有帮助的书写不是单纯宣泄，而是把经历组织成可理解的故事。可关注四个信号：适度承认负面情绪，而非压住；出现积极情绪或希望线索；因果、理解、意义等认知词逐渐增加；人称代词能在“我、他人、我们”之间切换。App 可把书写提示设计成：发生了什么、我有什么感受、别人可能经历了什么、这件事说明了什么、下一步我能做什么。视角弹性越高，越不容易困在单一受害叙事里。', '["语言风格", "表达性写作", "书写疗愈", "视角切换", "情绪整理", "LIWC"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 159, now()),
(100160, '言语行为适切条件：承诺、道歉和命令都要满足关系规则', '一句话是否有效，不只看字面是否好听，还要看它是否满足适切条件：说话者是否有资格这样说，听者是否能理解，内容是否具体，意图是否真诚，后续义务是否清楚。空泛的“我以后会改”不是好承诺；没有承担影响的“对不起”也难以完成修复。App 生成承诺、道歉、请求话术时，应检查：具体行动、时间条件、能力边界、责任承担和复盘方式是否齐全。', '["言语行为", "承诺", "道歉", "请求", "关系规则", "沟通质量"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 160, now()),
(100161, '制度性事实：语言能创造责任、身份和共同规则', '有些事实不是自然发生的，而是由共同规则承认后才成立：承诺、任命、约定、道歉、家庭协议都属于这类语言创造的关系事实。两个人说“我们约好了”，只有在双方都理解条款、承认规则、知道后果时才真正有约束力。App 可把关系协商从口头情绪升级为共同规则：谁参与、约定什么、何时执行、如何检查、违反后如何处理。', '["言语行为", "制度性事实", "规则", "责任", "家庭协议", "关系协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 161, now()),
(100162, '太空时间：亲子危机时先开辟无追责的连接窗口', '当亲子关系已经出现明显隔膜时，可预先约定“太空时间”：在这段时间里暂停算旧账、讲道理、谈判和追责，只表达关怀、支持、真实感受和连接需求。它最好在平时心情好时建立规则，危机时双方都可以提出启动，一般不少于 30 分钟。关键不是放弃规则，而是先防止关系断线；家长若继续批判、否定、居高临下，这个技巧会失效。', '["亲子沟通", "太空时间", "关系修复", "情绪安全", "家庭冲突", "连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 162, now()),
(100163, '家中规则合约：少量、明确、可复述，规则才有教育力', '孩子不守规则，常不是故意挑战，而是规则太多、太模糊、没有解释清楚，或家长自己执行不一致。有效规则应少量优先，可先限制在七条以内；用具体行为替代抽象要求，如“晚上 9 点前完成作业”比“早点做完”更清楚；让孩子复述规则，确认理解；家长也要遵守相同规则或解释例外。规则越清楚，惩罚越少；爱和规则需要同时存在。', '["亲子教育", "家庭规则", "边界", "一致性", "规则合约", "温和坚定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 163, now()),
(100164, '家庭会议五步骤：把家庭问题从互相责怪变成共同解决', '家庭问题反复出现时，可用会议流程替代临场吵架：第一，用正面、简短、无责怪的语言确定问题；第二，先收集多个方案，不急着批评；第三，讨论每个方案的可行性和每个人的感受，选出都能接受的方案；第四，分配行动和支持方式；第五，约定复盘时间，检查满意度。家庭会议应在情绪平稳时练习，它不削弱家长权威，反而训练孩子的问题解决能力。', '["家庭会议", "亲子沟通", "共同解决问题", "家庭系统", "冲突修复", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 164, now()),
(100165, '检定语言模式：从表层话语追问出深层限制', '用户说出的只是表层结构，背后常有删减、模糊和限制性信念。比如“我希望会变好”可能隐藏无力感，“我应该”可能隐藏外部压力，“我不能”可能缺少具体障碍说明。App 不宜急着给建议，而应先检定：具体是谁、什么情境、怎么知道、什么阻止了你、有没有例外、你真正选择什么？把“希望、应该、不能”转成“我选择、我会、我能先做哪一步”，能恢复用户的行动感。', '["NLP", "检定语言模式", "深层结构", "提问", "信念松动", "沟通澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 165, now()),
(100166, '添增力量：先找出问题行为提供了什么力量', '一些不良行为并不只是“坏习惯”，也可能在临时提供力量：愤怒给人支撑，成瘾给人镇定，暴食给人安全感，控制给人掌控感。若只要求停止，用户会失去原本借来的力量。更好的顺序是：识别行为满足的力量需求；寻找更低代价的替代资源；调用过去成功经验、榜样角色或新的支持性信念。改变不是拿走拐杖，而是先让人重新站稳。', '["NLP简快疗法", "资源取向", "自我价值", "问题行为", "正向功能", "行为替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 166, now()),
(100167, '倾听障碍清单：识别自己是在听，还是在准备反应', '很多“我在听”其实是假倾听：对比自己、猜测对方意图、在脑中演练反驳、只听想听的部分、急着评判、好为人师、争辩挖苦、转移话题或一味讨好。App 可在冲突建议中先做倾听检查：我能否复述对方事实？我是否听见了情绪？我是否已经在准备反击？在回应前先复述并确认，能显著降低防御。', '["人际沟通", "倾听障碍", "主动倾听", "共情", "冲突降温", "复述"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 167, now()),
(100168, '弦外之音：声调、语速和重音会泄露真实关系态度', '话语的伤害不总在字面，常在辅助语言里：音高、语速、音量、停顿、重音和语调会传递自信、轻蔑、不耐烦、犹豫或优越感。内容上说“我当然支持你”，如果重音和语气带着讽刺，听者接收到的可能是否定。App 生成沟通脚本时，除了文字，还应提示语气：慢一点、低一点、停顿确认、避免反讽重音；同时提醒用户检查自己的真实目的是否与表达一致。', '["人际沟通", "辅助语言", "弦外之音", "语气", "非语言沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 168, now()),
(100169, '人格理解：同一个人可以被多个流派同时照亮', '人格心理学不只提供一种解释，而是用多镜头理解人：精神分析关注无意识、防御和早期经验；特质流派关注稳定差异；生物学流派关注遗传、气质和脑机制；人本主义关注价值、成长和真实自我；行为主义和社会学习关注环境、强化和观察学习；认知流派关注图式、解释和自我调节。App 回答人格问题时，不宜把用户归入单一标签，而应根据问题选择镜头：这是关系脚本、长期特质、情境学习、身体反应，还是信念解释在起作用？', '["人格心理学", "多流派", "特质", "认知", "人本主义", "行为学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 169, now()),
(100170, '大五人格：用于描述倾向，不用于决定命运', '大五人格可以帮助用户描述自己在开放性、尽责性、外向性、宜人性和神经质等维度上的相对倾向，但它不是命运判决。高神经质不等于注定痛苦，低外向不等于社交失败；特质只是“更容易怎样反应”的概率，不等于“只能怎样生活”。App 使用人格维度时，应把结论转化为策略：高敏感者设计恢复空间，低尽责者使用外部结构，高外向者注意深度连接，低宜人者练习表达关心。', '["大五人格", "特质", "自我理解", "成长策略", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 170, now()),
(100171, '特质与情境：解释行为要同时看人和场景', '人格讨论常陷入两种极端：一种认为行为全由性格决定，另一种认为人只是被环境推着走。更实用的理解是，行为来自特质与情境的互动：同一个谨慎的人在安全关系中会更开放，同一个外向的人在高风险场合也会沉默。App 分析用户或伴侣行为时，应追问：这是长期稳定倾向，还是某个场景触发？若换时间、关系、压力水平和奖惩环境，行为会不会变化？', '["特质情境", "行为解释", "人格", "关系分析", "情境触发"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 171, now()),
(100172, '自我效能感：改变从“我能做一点”开始', '社会认知理论强调，人对自己能否完成行动的判断，会影响是否开始、坚持多久以及遇到挫折后如何恢复。自我效能感不是空喊自信，而是来自可重复的小成功、榜样示范、他人支持和身体状态改善。App 处理拖延、焦虑或关系修复时，可把目标缩小到一个可完成动作，并记录成功证据；当用户说“我不行”，应帮助改写成“我现在能先完成哪一小步”。', '["自我效能", "社会认知", "小成功", "行为改变", "自我调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 172, now()),
(100173, '自我图式：人会用熟悉的自我故事筛选信息', '认知流派提醒，人不是被事件本身直接决定，而是会通过自我图式解释事件。若用户带着“我不被喜欢”的图式，普通延迟回复也可能被理解为拒绝；若带着“我必须完美”的图式，小失误也会变成自我否定。App 可引导用户把自我故事拿出来检验：我现在用的是什么标签？它让我忽略了哪些证据？有没有一个更宽的自我描述能容纳缺点、努力和变化？', '["自我图式", "认知流派", "自我故事", "关系误读", "信念检验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 173, now()),
(100174, '主体间性：痛苦常在关系场中形成，也要在关系中被理解', '主体间性心理治疗把来访者和咨询师看作共同构成的关系系统。人的感受并非孤立存在，而是在特定关系、文化、历史和互动方式中被组织出来。App 回答关系创伤、亲密恐惧或咨询相关问题时，可避免把痛苦完全归因于个人缺陷，而是帮助用户看见：我在什么关系场里形成了这种反应？当前互动如何重新激活旧经验？新的关系经验如何支持我重新组织自我感？', '["主体间性", "关系系统", "心理治疗", "经验组织", "关系创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 174, now()),
(100175, '情感协调：先让对方感到被理解，再推动改变', '主体间取向强调，情感协调不是简单复述，而是治疗师或倾听者努力贴近对方当下主观体验，并把理解以可接收的方式反馈出来。很多人并不缺道理，而是缺“我的感受被准确看见”的经验。App 生成安慰或咨询式回应时，应先命名可能的感受、承认其处境意义，再进入建议；过早分析、纠正或教育，会让对方更孤独。', '["情感协调", "共情", "倾听", "关系修复", "心理咨询"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 175, now()),
(100176, '共情内省式倾听：理解对方的内在逻辑，而不是抢着解释', '共情内省式倾听要求倾听者暂时放慢自己的理论、评判和解决冲动，进入对方经验内部，理解其感受怎样在对方世界里成立。对 App 来说，这意味着先问“在你的处境里，这为什么会这么痛？”而不是先问“你为什么不换个想法？”当用户情绪强烈时，优先输出理解、澄清和陪伴；当其稳定后，再提供解释、练习和行动建议。', '["共情内省", "倾听模式", "心理咨询", "情绪支持", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 176, now()),
(100177, '治疗关系修复：断裂本身也可以成为新的经验', '关系治疗中难免出现误解、失望、距离或冲突。主体间视角不把这些断裂只看作失败，而是把它们视为共同理解旧模式和创造新经验的机会。App 在关系修复建议中可引导用户：发生了什么断裂？各自怎样理解？它触发了什么旧感受？现在能否用更安全、更直接的方式谈论？修复不是证明谁对谁错，而是让关系有机会承载真实感受。', '["关系修复", "治疗关系", "主体间性", "断裂修复", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 177, now()),
(100178, '抑郁认知三元素：自己、世界和未来同时变暗', '贝克抑郁理论把抑郁中的认知核心概括为三类负性模式：用负性方式看自己，觉得自己无价值或有缺陷；用负性方式看世界，觉得环境充满剥夺、失败和阻碍；用负性方式看未来，觉得情况不会改善。App 遇到抑郁倾向表达时，可帮助用户把“事实”与“抑郁滤镜”区分开：这是我全部的人生，还是低落状态下被激活的一套解释？', '["抑郁", "贝克认知理论", "负性认知", "自我世界未来", "认知滤镜"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 178, now()),
(100179, '抑郁症状要分层看：情绪、认知、动机和身体会互相牵连', '抑郁不是单一情绪问题，常同时表现为情绪低落或空洞、负性自我评价、注意和思维迟缓、做事动力下降、回避、睡眠食欲和身体能量变化。App 回答时应避免把用户简单归为“懒、玻璃心、想太多”，而要提示这是一个身心系统状态。更有效的恢复路径通常需要多点介入：规律作息、微小活动、认知检验、关系支持和必要的专业帮助。', '["抑郁症状", "情绪", "认知", "动机", "身体反应", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 179, now()),
(100180, '抑郁图式：旧的负性模板会在压力下被重新激活', '抑郁易感性可以理解为某些负性图式在压力下被激活。平时用户可能还能维持功能，但在失恋、失败、丧失、冲突或长期压力下，旧模板会把事件解释成“我不够好、我会失去、未来没希望”。App 可帮助用户识别激活点：最近发生了什么压力？它碰到了哪种核心信念？有没有证据说明这只是旧模板，而不是全部现实？', '["抑郁图式", "压力触发", "核心信念", "认知易感性", "反刍"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 180, now()),
(100181, '反刍会放大抑郁：重复想不等于真正解决', '抑郁状态下，人容易反复咀嚼同一件事，以为想清楚才能行动，但反刍常让注意力越来越窄、情绪越来越重、行动越来越少。App 可以把反刍和问题解决区分开：反刍是循环问“为什么我这么糟”，问题解决是写下可验证事实、可影响部分、下一步行动和需要支持的人。若思考超过一定时间仍只增加痛苦，就应转向身体活动、外部支持或具体任务。', '["反刍", "抑郁", "问题解决", "注意力", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 181, now()),
(100182, '抑郁复发预防：恢复后仍要维护认知和生活系统', '抑郁好转不等于风险完全消失，维持治疗、认知练习和生活结构能降低复发概率。App 可把复发预防做成日常清单：睡眠和活动是否稳定？是否又开始孤立？是否出现“我没用、没希望”的自动解释？是否停止了有效练习？是否有可以提前联系的支持对象？重点是早识别、早调整，而不是等到完全崩溃才求助。', '["抑郁复发", "维持治疗", "认知疗法", "生活结构", "早期预警"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 182, now()),
(100183, '把信念当假设：用小实验替代空想式显化', '《能量》类资料适合被 App 转译成自我觉察练习：不要把“意念创造现实”理解成逃避现实责任，而是把信念当作可检验假设。若用户相信“没有机会”，可以设计一个 48 小时小实验：主动寻找三个机会线索、记录自己忽略了什么、采取一个微行动。这样把抽象信念落到注意力、选择和行动上，既保留积极探索，也避免陷入空想。', '["能量练习", "信念实验", "注意力", "积极心理", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 183, now()),
(100184, '注意力会筛选现实：你寻找什么，就更容易看见什么', '人每天接触的信息远远超过能处理的范围，因此注意力会像过滤器一样选择哪些线索进入意识。当用户长期只寻找威胁、缺失和失败，大脑会不断证明“世界就是这样”；当用户练习寻找资源、支持和可行动线索，也会更容易看见新的可能。App 可引导用户做注意力复盘：今天我自动看见了什么？我忽略了什么？如果我寻找一个微小资源，会在哪里？', '["注意力", "选择性知觉", "资源取向", "积极练习", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 184, now()),
(100185, '感恩不是否认问题，而是训练大脑看见已拥有的资源', '感恩练习的价值不在于粉饰困难，而在于让用户从“我只有缺口”的单一叙事中恢复平衡。有效感恩要具体：今天谁提供了支持？我完成了哪件小事？身体还在支持我什么？环境里有什么可用资源？App 在低落或匮乏感问题中，可建议用户每天记录三项具体资源，并配合一个现实行动，让感恩连接到力量，而不是变成压抑情绪的口号。', '["感恩", "资源觉察", "积极心理", "匮乏感", "低落恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 185, now()),
(100186, '疯传 STEPPS：传播不是运气，而是六类心理机制叠加', '《疯传》提出，内容和行为更容易传播，往往不是因为广告预算最大，而是触发了六类机制：社交货币让分享者显得有价值；诱因让人被环境反复提醒；情绪唤醒推动转发；公开可见让模仿更容易；实用价值让人愿意帮别人；故事把信息包装进可复述情节。App 可把这套框架用于课程、活动和内容传播诊断：缺哪一环，就补哪一环。', '["疯传", "STEPPS", "传播心理", "影响力", "内容策略", "社交货币"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 186, now()),
(100187, '社交货币：用户分享的不是内容，而是分享后的自我形象', '人们愿意分享能让自己显得聪明、有品位、有内部消息、乐于助人或与众不同的内容。传播设计不应只问“我们想说什么”，还要问“用户转发后会显得怎样”。App 可用于内容建议：给用户一个可展示的洞察、身份、成就或独特表达，让分享行为成为自我形象的一部分；但社交货币必须和真实价值相连，否则会变成噱头。', '["社交货币", "内容传播", "身份表达", "用户分享", "影响力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 187, now()),
(100188, '诱因：把想传播的行为绑定到高频场景', '好内容如果没有被想起的触发点，也容易沉下去。诱因的关键是把信息绑定到用户日常会频繁遇见的场景、词语、时间和动作上：一到周一想到复盘，一看到咖啡想到能量，一遇到冲突想到暂停三问。App 可帮助课程和产品设计触发器：用户什么时候最需要这条知识？现实中什么线索会提醒 TA？如何把提醒嵌入日常而不是只靠一次宣传？', '["诱因", "触发器", "习惯场景", "内容传播", "行为设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 188, now()),
(100189, '高唤醒情绪更容易推动传播，但要服务真实价值', '不是所有情绪都同样推动传播。高唤醒情绪，如惊讶、敬佩、愤怒、焦虑、兴奋，更容易促使人行动；低唤醒情绪，如满足或悲伤，未必带来同样的转发动力。App 生成传播建议时，可帮助用户寻找内容中的情绪核心：它让人惊讶在哪里？敬佩什么？担心什么？但情绪唤醒不等于煽动，最好让情绪服务于理解、行动和真实帮助。', '["情绪传播", "高唤醒", "内容策略", "影响力", "行动动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 189, now()),
(100190, '实用价值：越具体、越省力、越能帮到别人，越容易被转发', '人们常分享有用信息，因为这让他们能帮助别人、维持关系并展示判断力。实用价值要具体：省多少钱、少踩什么坑、按哪几步做、适合谁、不适合谁。App 可把知识库内容改写成可传播建议：标题直接说用途，正文给步骤和场景，结尾给转发对象。抽象鸡汤不如一个清晰清单，模糊道理不如一个今天就能用的小工具。', '["实用价值", "清单化", "内容传播", "帮助他人", "行动步骤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 190, now()),
(100191, '故事是信息的运输工具：让观点藏在可复述情节里', '故事能传播，是因为人们更愿意复述人物、冲突、转折和结果，而不是背诵抽象观点。一个好故事应让核心信息不能被轻易剥离：如果用户讲完故事却忘了产品、课程或方法，说明信息没有嵌入情节。App 可建议内容创作者用“人物遇到什么困境—尝试什么方法—发生什么转变—听众能带走什么行动”来组织表达，让知识随故事一起被记住。', '["故事传播", "叙事", "内容策略", "知识表达", "可复述"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 191, now()),
(100192, '人格测验的信度与效度：分数只能作线索，不能作判决', '人格测验要先问两件事：信度，即同一测验能否稳定、一致地测到某种倾向；效度，即它测到的东西是否真是想测的建构。高信度不等于高效度，一个量表可能稳定地测到“社会赞许倾向”而不是自尊。自陈量表还会受到伪装、敷衍答题、阅读理解、反应倾向和测评动机影响。App 解读测评结果时，应提醒：结果适合作为自我观察、讨论和后续行为验证的起点，不适合单凭一个分数判断人格、诊断障碍、录用或淘汰某人。更可靠的做法是结合长期行为、他人反馈、情境记录、功能损害和专业评估。', '["人格测验", "信度", "效度", "自陈量表", "测评解读"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 192, now()),
(100193, 'DSM-5替代性模型：人格障碍评估从类别转向功能画像', '人格障碍不宜只用“是不是某型”理解。维度化模型把重点放在两类信息：人格功能受损和病理性人格特质。人格功能包括身份认同、自我定向、共情、亲密等自我与人际能力；病理特质则描述消极情绪、疏离、对抗、脱抑制、精神质等方向的程度。这样能把人格问题放到连续体上看：普通人也会有某些特质，只是强度、僵化度、跨情境稳定性和功能损害不同。App 适合用作非诊断回答：先评估长期性、跨场景、功能损害、自我/人际能力，再讨论边界、求助和干预，而不是给用户或他人贴临床标签。', '["人格障碍", "DSM5", "维度模型", "人格功能", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 193, now()),
(100194, '图式—模式—策略：人格障碍的认知行为底层模型', '认知行为视角把人格障碍理解为“图式—模式—策略”的持续循环。图式是关于自我、他人和世界的深层信念；模式是某些图式在特定情境下被整体激活后的认知、情绪、动机和行为状态；策略原本有适应意义，如寻求安全、保持自主、争取认可、避免伤害，但当它过度发展、发展不足或僵化使用时，就会制造持久的人际和自我功能问题。干预不是简单纠正错误想法，而是先看策略保护了什么，再通过关系体验、行为实验、图式反馈、正念或角色扮演，让人发展更灵活的新策略。', '["人格障碍", "CBT", "图式", "模式", "行为策略", "个案概念化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 194, now()),
(100195, '人格障碍治疗联盟：关系本身就是行为实验室', '人格障碍干预比症状干预更依赖治疗联盟，因为改变慢、挫败多，且来访者的核心信念常会在治疗关系中被激活：害怕被拒绝、被控制、被羞辱、被利用，或觉得必须取悦/反抗治疗师。有效工作不是只讲技术，而是把关系困难纳入概念化：发生误解时及时标记，鼓励具体反馈，治疗师保持非防御态度，把会谈中的回避、顺从、攻击、理想化或贬低视为可观察材料。App 可借鉴这一点：面对高度敏感或长期模式用户，先建立可预测、尊重边界的互动，再引导事实记录、情绪稳定和小步实验。', '["治疗联盟", "人格障碍", "治疗关系", "CBT", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 195, now()),
(100196, '回避型人格模式：安全行为会短期降焦虑、长期困住自我', '回避型模式的核心不是“不想关系”，而是“渴望关系但预期羞辱、批评、拒绝”。回避、沉默、提前退出、不表达真实需求、只给正面反馈等安全行为，短期能降低焦虑，却让人失去验证新经验的机会，长期强化“我无法承受他人评价”的信念。认知行为干预强调：先建立足够安全的关系，再识别回避链条，逐步暴露于可承受的社交风险，练习自信表达、负面反馈、情绪耐受和行为实验。App 可把“逃开”翻译成保护策略，同时帮助用户设计低风险的接近练习。', '["回避型人格", "安全行为", "社交焦虑", "行为实验", "情绪耐受"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 196, now()),
(100197, '自恋型人格的认知理解：脆弱自尊与特权策略并存', '自恋模式不只是“自大”，更常是脆弱自尊与补偿性优越感的组合。个体可能把价值感建立在特殊、卓越、被认可之上，因此对批评、忽视、失败或地位受损高度敏感；当自尊受威胁时，容易使用贬低他人、要求特殊待遇、回避羞耻、争夺控制等策略。App 回答时不宜用“自恋”骂人，而应拆成可观察模式：是否需要持续赞美，是否难以承认影响，是否把普通反馈理解为羞辱，是否通过控制关系维持自尊。对当事人可引导区分真实自我价值与外部评价，练习承担影响而不崩塌。', '["自恋型人格", "自尊", "羞耻", "关系模式", "认知治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 197, now()),
(100198, '偏执型人格模式：威胁扫描会把保护策略变成关系破坏', '偏执型模式可以理解为保护策略过度化：个体高度关注被伤害、被侵犯、被欺骗或被控制的可能，倾向把模糊信息解释成针对自己的威胁。它的短期功能是降低被动受害感，长期后果却是不断检查、质疑、反击和疏离，让他人更防御，反过来“证明”世界不可信。App 在关系咨询中可帮助用户把“对方一定有恶意”改写为可检验假设：事实是什么、还有哪些解释、若保持边界但暂缓攻击会怎样。面对他人的偏执化互动，则强调安全、边界、书面事实和避免陷入辩解循环。', '["偏执型人格", "威胁解释", "保护策略", "关系边界", "认知重评"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 198, now()),
(100199, '超越性动机与存在价值：成长后期需要比“我”更大的方向', '在基本需要相对稳定后，人仍可能感到空洞，因为动机不只包括补缺口和实现个人潜能，还包括对真、善、美、创造、意义、整体性、正义、卓越等存在价值的回应。马斯洛晚期把这类更高动机称为超越性动机或超越性需要：人需要献身于某种大于个人欲望的对象，突破只以自我利益为中心的生活。App 可在用户问“为什么条件不错仍空虚”时引导：先确认基础需求与心理困扰，再探索哪些价值让他愿意服务、学习、创造、守护或奉献。它不是道德绑架，而是成熟人格的方向感来源。', '["马斯洛", "超越性动机", "存在价值", "意义感", "成长需要"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 199, now()),
(100200, '九型心理缓冲带：防御机制会遮住类型真相', '九型资料把“心理缓冲带”理解为人为了维持自我形象而形成的防御系统。它会把性格中的负面特征、羞耻和矛盾挡在意识之外，使人只看到自己愿意相信的版本。不同类型常有不同防御倾向，如反向作用、压抑、认同、内投、分隔、投射、合理化、否定、麻醉等。RAG 中这比“测出我是几号”更有价值：识别类型时看一个人如何维护自我感、怎样解释冲突、哪些反馈最难听进去。成长不是撕掉防御，而是在安全和诚实中看见它保护的脆弱需要。', '["九型人格", "心理防御", "自我观察", "类型识别", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 200, now()),
(100201, '九型潜藏激情：类型背后的情绪习性比行为更关键', '九型人格的“激情”指反复劫持注意力的情绪习性，不是偶发情绪。它们可被看作早期适应留下的阴影：当某种情绪习惯被点燃，人会围绕它组织解释、关系和行动，并失去自我观察能力。判断类型时，不只看外在行为，而要看注意力最容易被什么情绪主题牵引：愤怒、骄傲、形象、嫉羡、匮乏、恐惧、贪多、控制、怠惰或麻木等。App 可引导用户记录“我在冲突中最自动的情绪剧本是什么”，再把激情当成返回真实需要和失落品质的线索。', '["九型人格", "潜藏激情", "注意力", "情绪习性", "类型成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 201, now()),
(100202, '情绪工作五项底层技能：接地、边界、引导、抱怨与复原', '强烈情绪不是只靠理解就能处理。先把自己带回身体和当下，再给内在体验划出边界，才更容易安全地翻译情绪。可作为五步框架：1）接地：借呼吸、身体感、脚下支撑，让情绪流过而不被淹没；2）定义边界：用愤怒、羞耻等信号辨认“我与他人”的界线；3）负责任地引导情绪：不压抑、不乱发泄，找安全容器表达；4）有意识地抱怨：把怨气从攻击变为看见未满足需要；5）恢复自我活力：情绪过后回到资源、节律和行动。适合回答“情绪上来怎么办”“如何不被情绪吞没”。', '["情绪语言", "情绪调节", "接地", "边界", "身体觉察", "自我复原", "强烈情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 202, now()),
(100203, '情绪亲密的三层共情：感觉到、同情、同感都需要边界', '与人共情不是越融合越好。情绪亲密可分三层：感觉到，是用身体临在、表情、语调和细节读取对方状态；同情，是在心的层面与对方相连，让对方感到安全和被理解；同感，是双方在共享情绪中并肩共振。风险也随层级增加：只“感觉到”可能变成旁观或操控；“同情”过度会吸收太多、丢失自己；“同感”失衡会形成封闭的“我们”而拒绝反馈。健康共情=连接+自主+可质疑，适合亲密关系、咨询倾听和团队情绪支持。', '["情绪亲密", "共情", "同情", "同感", "边界", "倾听", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 203, now()),
(100204, '愤怒两步公式：痛苦或压力遇到触发思维才会点燃', '愤怒常由两部分组成：先有身体或情感上的痛苦/压力，如疲劳、头痛、被拒绝、需要受阻；随后出现触发思维，把情境解释为“对方故意伤害我、冒犯我、应该受惩罚”。痛苦像燃料，触发思维像火柴；任一部分被看见，愤怒链条就有机会中断。RAG 可用于生成愤怒日志字段：压力源、客观事件、触发解释、愤怒强度、实际行为、对自己后果、对他人后果。干预重点是同时降低生理唤醒和替换指责、灾难化、支配性想法。', '["愤怒管理", "触发思维", "压力", "认知扭曲", "愤怒日志", "身体唤醒"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 204, now()),
(100205, '愤怒的隐藏奖赏：短期奏效会强化爆发', '有些愤怒难改，不是因为当事人不知道它伤人，而是因为它短期内“有用”：别人退让、停止要求、改变安排，自己获得控制感和释放感。这种奖赏会把愤怒训练成默认工具，即使长期代价是关系疏远、抵抗升级和自责。反愤怒方案要问三件事：这次爆发带来了什么积极结果？我真正想保护的需要是什么？有没有不破坏关系也能达成同样结果的方式，如坚定表达、协商、设置容忍度、独立制定计划。适合处理“我知道发火不好但忍不住”。', '["愤怒强化", "控制感", "边界表达", "替代行为", "协商", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 205, now()),
(100206, '抑郁中的自我批评：评估行为，不审判整个人', '自我批评在抑郁中常从“我这件事没做好”滑向“我这个人不行”。把成绩、考试、家务、工作等结果绑定到“我”的价值，会让失败变成自我攻击。更有帮助的区分是：行为可以复盘，结果可以失望，策略可以调整，但人的基本价值不随一次成败升降。走出抑郁需要两种思维协作：理性思维像侦探，检查证据、寻找多种解释、做小实验；同情性思维像可靠照护者，用友好、支持、宽恕和修复取代威胁惩罚。适合自责、羞耻、完美主义引发的抑郁检索。', '["抑郁", "自我批评", "自我价值", "同情性思维", "理性思维", "羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 206, now()),
(100207, '抑郁康复的共同照护：研究自己的模式并预设求助信号', '康复故事反复指向一个实用原则：来访者不是被动等待治疗，而要逐渐成为自己康复系统的共同管理者。做法包括：记录自己的发作模式和季节/生活事件触发点；观察睡眠、饮食、精力、语速、退缩、冲动等早期信号；把有效疗法、药物、运动、互助、日记、光照、饮食等整理成个人方案；提前授权可信亲友在发现异常时联系医生或治疗师。它不是“靠自己硬扛”，而是把自我觉察、专业支持和社会支持制度化，让低谷时仍有人能拉响警报。', '["抑郁康复", "自我监测", "支持系统", "早期信号", "治疗合作", "生活方式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 207, now()),
(100208, '拖延三管齐下：改写思维、锻炼情绪肌肉、用五分钟启动', '拖延不是单纯懒惰，而是认知、情绪、行为连锁：任务出现负面看法，引发焦虑、厌恶或压力，再用低压力活动替代，获得即时放松，拖延因此被强化。反拖延可三管齐下：认知上识别“以后再做、准备好再开始、失败就完了”等拖延思维，把计划看成可检验假说而非人格审判；情绪上练“情绪肌肉”，接纳不适、观察身体紧张，放弃短期逃避换长期收益；行为上用五分钟计划，先承诺开始五分钟，再决定下一个五分钟。适合任务启动困难和压力型拖延。', '["拖延", "三管齐下", "情绪肌肉", "五分钟计划", "认知改写", "行动启动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 208, now()),
(100209, 'TA 的认可饥渴：人际游戏常在替代真实亲密', '沟通分析把人际互动看成满足三种基本渴望的方式：刺激渴望、认可渴望和结构渴望。婴儿需要身体抚触，成人也需要象征性“安抚”，如问候、微笑、回应和被看见；但仅有问候不够，人还需要安排清醒时间，于是活动、仪式、消遣、游戏、亲密成为不同层级的时间结构。心理游戏之所以顽固，是因为它既提供认可和时间结构，又避免真实亲密的脆弱。App 可据此区分：用户是在寻求真实请求、普通消遣，还是通过反复冲突获取安抚。', '["沟通分析", "认可饥渴", "安抚", "时间结构", "心理游戏", "亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 209, now()),
(100210, 'TA 三类沟通：互补维持互动，交错制造中断，隐藏形成游戏', '在沟通分析中，一次沟通不只看说了什么，还看由哪个自我状态发出、邀请对方哪个自我状态回应。互补沟通指刺激和回应方向匹配，互动能顺利继续；交错沟通指回应来自意料之外的自我状态，谈话容易卡住、冲突或转向；隐藏沟通则同时存在社交层和心理层，表面像理性对话，底层却在交换依赖、控制、惩罚、讨好或逃避。心理游戏常是隐藏沟通反复运行并导向可预测结局。适合解析“明明只是小事却总吵起来”的对话结构。', '["沟通分析", "互补沟通", "交错沟通", "隐藏沟通", "自我状态", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 210, now()),
(100211, '人际游戏公式：骗局、弱点、回应、转换和结局', '心理游戏不是简单“耍心机”，而是习以为常但功能不良的安抚方式。G 公式可作为识别模板：一方抛出看似合理的刺激或骗局；对方的弱点被勾住并回应；随后发起者或参与者自我状态转换；最后出现熟悉的情绪结局，如正义愤怒、委屈、被踢、无助。戏剧三角补充说明角色会在受害者、拯救者、迫害者之间快速互换。退出游戏的关键不是争输赢，而是识别隐蔽动机、拒绝接预设角色、把沟通拉回真实请求和可协商边界。', '["人际游戏", "G公式", "戏剧三角", "受害者", "拯救者", "迫害者", "沟通分析"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 211, now()),
(100212, '主体间场：治疗师不是旁观者，而是共同创造治疗环境的人', '主体间心理治疗把咨访关系看成由两个主体共同形成的系统。治疗师对来访者主观经验的理解，会受到治疗师自身主体性、理论假设、文化背景、情绪反应和经验组织方式影响；这些影响不是要被假装消除，而是要被敏感地觉察和使用。治疗环境也不是固定容器，而由场所、共情倾听、互动关系以及不可预知的双方经历共同创造。RAG 可用于提醒咨询师：解释来自关系背景，任何“客观看法”都要检查自己在主体间场中的贡献。', '["主体间场", "咨访关系", "治疗师主体性", "共同创造", "反思", "心理治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 212, now()),
(100213, '情感协调的治疗力：破裂—修复和特殊情感时刻会重组经验', '主体间治疗强调经验围绕情感组织，因此改变情感体验会为新的经验组织打开机会。婴儿研究提供了三个关键原则：互动中的持续调节、破坏与修复、特殊情感时刻。迁移到心理治疗中，来访者与治疗师会共同期待、误会、调整和修复；当某一刻来访者真实感到“我的体验被另一个人感受到并适当回应”，就可能扩大自我调节范围，形成新的共享情感经验。它解释了为什么一次真诚的理解、一次关系裂痕后的修复，有时比完美解释更有治疗作用。', '["情感协调", "破裂修复", "特殊情感时刻", "自我调节", "主体间性", "治疗关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 213, now()),
(100214, '霍妮三种人际移动：亲近、对抗、疏远都是求安全', '霍妮把许多内心冲突理解为三种人际方向的拉扯：亲近他人时，用户可能用讨好、依赖、牺牲来换安全；对抗他人时，可能用控制、竞争、证明自己来避免被伤害；疏远他人时，可能用冷淡、消失、自给自足来保住自主。App 端回答时，不宜只把这些反应评价为“太软弱”“太强势”或“太冷漠”，而要追问：我此刻在防什么危险？我最怕失去的是爱、价值、尊严还是自由？成熟不是固定选择某一种策略，而是在不同关系里能更有弹性地靠近、设限或退后。', '["霍妮", "内心冲突", "人际模式", "讨好", "对抗", "疏远", "安全感", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 214, now()),
(100215, '理想化自我与外化：假和谐会把冲突推远', '内在冲突常会被两种方式暂时盖住：一是制造一个“我应该永远优秀、正确、被喜欢”的理想化形象；二是在理想化破裂后，把痛苦完全外化为“都怪别人/环境”。前者让人不断羞耻和自责，后者让人短期舒服却远离可改变的部分。App 可帮助用户区分愿景与苛刻形象：我要求自己必须成为什么样才配被接纳？现实中哪一小部分是我能承担和调整的？哪一部分确实属于外部限制，需要边界、协商或资源支持？', '["霍妮", "理想化自我", "外化", "内耗", "羞耻", "责任", "自我接纳", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 215, now()),
(100216, '每日情绪日志：焦虑要写成可检验的想法', '焦虑自助不只是让用户“别想太多”，而是把脑内灾难化写成可检查的材料。可引导用户用每日情绪日志记录：触发事件是什么；焦虑、羞耻、愤怒等情绪各有多强；脑中自动想法是什么；其中有哪些放大、读心、非黑即白、应该化等认知扭曲；更平衡的回应是什么；重新评分后情绪是否下降。这样做的重点不是强迫积极，而是把“我完了”变成“这是一个想法，我能找证据、找替代解释、做小实验”。', '["焦虑", "认知疗法", "每日情绪日志", "认知扭曲", "自助", "想法检验", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 216, now()),
(100217, '暴露与行为实验：停止用回避喂养恐惧', '许多焦虑之所以持续，是因为回避让大脑一直没有机会更新：“我不去，所以没出事”会被误解为“幸好我不去，否则一定完蛋”。暴露不是鲁莽硬闯，而是把害怕情境拆成可承受的小阶梯：先写下预测的最坏结果和概率，再设计一次安全、具体、可停止的小实验，记录真实发生了什么。用于社交焦虑、羞怯、反复担忧时，App 可建议用户减少一个安全行为、完成一次低风险接触，再用结果修正旧信念。', '["焦虑", "暴露法", "行为实验", "回避", "安全行为", "社交焦虑", "信念更新"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 217, now()),
(100218, '认知不协调：改变观点常从小行为和自我辩解开始', '人做了与自我形象不一致的事，会产生不舒服的认知不协调，并倾向于通过改变态度或编理由来恢复一致感。关系沟通和行为改变中，与其强迫对方承认“你错了”，不如邀请一个低压力、可自愿的小行动，再让对方从行动经验中更新看法。反过来，用户也要警惕自己被承诺、沉没成本和公开表态绑住：我现在坚持，是因为证据更充分，还是因为不想承认之前的选择可能有问题？', '["认知不协调", "态度改变", "自我辩解", "承诺", "行为改变", "沟通", "社会影响"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 218, now()),
(100219, '社会学习：榜样、强化和环境比说教更能改行为', '社会学习视角提醒，行为常由观察、模仿、奖惩和自我期待共同塑造。亲子、伴侣或团队场景里，单纯说教和羞辱往往不如清楚示范、即时反馈和环境设计有效。App 可把建议落到三个问题：谁正在示范这种行为？这个行为之后立刻得到了什么奖励或代价？环境里哪些提示在鼓励旧模式？想培养新行为，就要让新行为更容易被看见、被做到、被肯定，而不是只要求对方“自觉一点”。', '["社会学习", "榜样", "强化", "环境设计", "行为改变", "亲子沟通", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 219, now()),
(100220, '旁观者效应：责任不明确时，善意会被群体稀释', '社会心理学中的旁观者研究显示，人越处在一群人中，越可能等待别人先行动；这不一定是冷漠，而常是责任扩散、彼此观望和误判情境造成的。App 在危机求助、团队协作或家庭分工中，可建议把“有没有人帮我”改成命名、限时、具体的请求：请 A 现在打电话，请 B 陪我去医院，请 C 今天 18 点前确认方案。明确责任能把模糊善意转化为行动，也能减少用户把无人响应解释成“我不值得被帮”。', '["旁观者效应", "责任扩散", "求助", "群体影响", "具体请求", "危机沟通", "社会心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 220, now()),
(100221, '少数意见的价值：不同声音能防止群体迷思', '群体决策中，表面一致并不总是健康；少数意见会迫使群体更仔细检查证据，激发发散思维和创造力。若为了和气、效率或权威而压制异议，团队容易进入群体迷思：没人敢说风险，最后一起做出差判断。App 可建议家庭或团队设置“反方角色”：先收集不同意见，再决定；先讨论证据，再投票；特别询问沉默者看见了什么。关系质量不是没有分歧，而是分歧能被安全表达。', '["群体迷思", "少数意见", "团队决策", "发散思维", "异议", "心理安全", "社会心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 221, now()),
(100222, '心理标签效应：诊断词会改变我们看见一个人的方式', '经典实验提醒，一旦给人贴上心理或人格标签，后续普通行为也容易被解释成标签证据。App 端应避免把“抑郁型人格、回避型、病态、自恋”等词当作判决书；更适合把标签降级为线索，并回到可观察事实：这种行为出现多久？在什么场景出现？带来什么功能损害？对方是否也有例外表现？对自我标签同样如此，“我就是废物/拖延人格”要改写为“我在某些任务前会回避，但可以观察触发点并练习下一步”。', '["心理标签", "诊断谨慎", "人格", "自我标签", "观察事实", "污名化", "心理实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 222, now()),
(100223, '思维定势与功能固着：换问题框架才能产生新选择', '人解决问题时常被既有用法和第一反应锁住，以为某个物品、角色或关系“只能这样”。思维定势会让用户在冲突中反复问“谁对谁错”，却忘了还可以问“我们真正要达成什么功能”。App 可引导用户拆框：我默认了哪些必须？这个资源除了原用途还能支持什么？如果目标不变、路径换三种，会有哪些选择？在亲密关系、职场沟通和自我改变中，创造力往往不是更用力，而是先松开旧框架。', '["思维定势", "功能固着", "创造力", "问题重构", "决策", "沟通", "心理实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 223, now()),
(100224, '社会建构视角：别把所有痛苦都解释成个人性格', '社会学视角强调，个人行为背后常有角色、规范、制度和文化脚本。用户把一切痛苦归因为“我太脆弱、我不够努力”时，App 可补问：这个家庭/单位/群体期待你扮演什么角色？哪些奖励和惩罚在维持当前模式？有没有阶层、性别、年龄、职业规则让选择变窄？这不是否认个人责任，而是避免把结构性压力伪装成性格缺陷。有效改变有时不是再逼自己，而是调整规则、边界、资源和支持网络。', '["社会学", "社会建构", "角色", "规范", "制度", "结构性压力", "自责", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 224, now()),
(100225, '成年发展的生态视角：人生危机常是角色与环境重组', '成年发展不是一条直线，也不只由年龄数字决定。人的困境会受实足年龄、生理年龄、心理年龄、社会年龄，以及时代、家庭、工作、健康和突发事件共同影响。App 回答“我这个年纪还这样是不是失败”时，可把羞耻改写为发展评估：我正在经历哪种角色转换？这个压力来自年龄常规事件、时代变化，还是非常规打击？我需要学习的新能力、支持系统和身份叙事是什么？这样能把危机从自我否定转为角色与环境重组。', '["成年发展", "生态视角", "人生阶段", "角色转换", "年龄", "身份", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 225, now()),
(100226, '改变难以坚持：洞见之后要搭建维持系统', '重大改变很少只靠一次顿悟完成。危机、故事、支持、治疗、旅行、意义感都可能触发改变，但旧环境和旧奖励会把人拉回原模式。App 在用户“我终于想通了”之后，应继续追问维持系统：未来最可能复发的场景是什么？谁能在我退回旧模式前提醒我？我要改变哪些环境提示？每周用什么仪式复盘？如果跌回去，最小恢复动作是什么？真正的改变不是永不反复，而是反复时有回到轨道的方法。', '["改变心理学", "复发预防", "维持系统", "洞见", "支持网络", "习惯保持", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 226, now()),
(100227, '影响力防身清单：好感、权威、稀缺和社会认同都要慢下来', '影响力原则既能帮助沟通，也可能劫持判断。用户在冲动购买、仓促承诺、关系让步或群体跟风前，可做防身清单：我是否因为别人先给了好处而急着回报？是否因为已公开承诺而不愿调整？是否因为大家都这样做就停止思考？是否把头衔、专业感或自信语气误当证据？是否被“最后机会、限量、错过就没了”推着走？健康的影响力应允许对方慢下来、看证据、保留拒绝权。', '["影响力", "互惠", "承诺一致", "社会认同", "权威", "稀缺", "决策", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 227, now()),
(100228, '情感隐藏模型：焦虑有时是在替未表达的情绪站岗', '有些焦虑不只来自认知扭曲，也可能在保护某些“不方便表达”的情绪：不敢承认愤怒，于是变成担心；不敢说需要，于是变成反复控制；不敢面对悲伤，于是忙着焦虑未来。App 不应把所有焦虑都机械套入“想法错了”，也可以温和询问：如果焦虑暂时停下，底下最可能浮现什么感受？我有什么请求、边界或哀伤一直没被说出口？当隐藏情绪被安全表达，焦虑有时会自然下降。', '["焦虑", "情感隐藏", "情绪表达", "需要", "边界", "认知疗法", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 228, now()),
(100229, '确认性偏见：主动寻找反证，才能突破自我证明循环', '确认性偏见会让人更容易看见支持自己观点的信息，并忽略挑战自己信念的证据。关系冲突中，用户若先认定“TA 不在乎我”“我一定会失败”，后续所有细节都可能被筛选成证据。App 可引导用户做反证练习：如果我的判断错了，会有哪些迹象？有哪些事实同时支持另一种解释？我能不能问一个开放问题，而不是继续搜集控诉材料？真正的理性不是永远相信自己，而是愿意让信念接受检验。', '["确认性偏见", "反证", "认知偏差", "关系误读", "自我觉察", "开放问题"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 229, now()),
(100230, '后知之明偏见：复盘时不要把结果倒推成“早就知道”', '事情发生后，人很容易觉得结果本来就显而易见，并低估当时的不确定性。后知之明偏见会让复盘变成责备：你明明早该看出来、我怎么这么笨、早知道就好了。App 可把复盘改成过程复盘：当时我掌握了哪些信息？哪些风险是真能看见的，哪些是事后才知道的？下一次可设置什么预警信号？这样既保留学习，又避免用结果惩罚过去的自己。', '["后知之明偏见", "复盘", "自责", "决策", "不确定性", "预警信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 230, now()),
(100231, '双曲线折扣：拖延和冲动都在高估眼前、低估未来', '双曲线折扣描述了人更重视眼前收益、低估未来代价的倾向。它会让用户今天刷手机、明天补救；今天冲动消费、未来焦虑；今天逃避对话、未来关系更僵。App 可把长期目标改造成近端约束：提前设截止日期、把任务拆成今天能完成的最小动作、让未来代价现在可见、把承诺告诉可信的人。不要只靠意志力和未来的自己，未来的自己通常也会遇到同样的诱惑。', '["双曲线折扣", "拖延", "冲动", "未来自我", "承诺", "行动设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 231, now()),
(100232, '邓宁—克鲁格效应：越不熟练，越需要外部反馈校准', '人在能力不足时，常因为缺少判断标准而高估自己；能力提升后，反而更能看见复杂性和不足。App 可在学习、关系修复或自我成长问题中提醒：自信不等于熟练，挫败也不等于没天赋。更可靠的校准方式是外部反馈、可量化结果、刻意练习和复盘证据。用户若觉得“我已经很会沟通/我很懂自己”，可以追问：别人体验是否一致？有没有反复出现的失败模式？我是否请过可靠的人指出盲点？', '["邓宁克鲁格效应", "自我评估", "反馈", "刻意练习", "盲点", "学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 232, now()),
(100233, '基本归因错误：先看情境压力，再判断人格问题', '基本归因错误让人解释他人行为时过度强调性格，低估情境压力；解释自己行为时却更容易强调处境。伴侣迟到不一定是不在乎，员工沉默不一定是没责任，孩子顶嘴也不一定是品格差。App 可在评价他人前加入情境检查：当时 TA 面临什么压力、信息、角色和资源限制？类似情境下别人会怎样？有没有稳定的跨场景模式？先看情境，不等于纵容伤害，而是让判断更准确，边界更有针对性。', '["基本归因错误", "情境", "人格判断", "关系冲突", "社会心理学", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 233, now()),
(100234, '边际效用递减：同一种满足会越用越不灵', '戈森第一定律提醒，连续满足同一种享受时，新增快乐通常会递减。它可转译为生活建议：重复刷短视频、购物、甜食、被认可或工作成就，一开始有效，后来可能越来越麻木，还需要更高剂量。App 可帮助用户区分“我真的需要更多”还是“同一种满足已经递减”。恢复活力常需要多元满足：身体休息、关系连接、创造、学习、贡献和意义，而不是把所有情绪都压到同一个出口。', '["边际效用递减", "行为经济学", "享受", "成瘾风险", "生活平衡", "多元满足"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 234, now()),
(100235, '享受均等：时间和精力要分配给真正有价值的需要', '戈森第二定律强调，要让整体享受更大，不能把全部资源投入单一需要，而要在多种需要之间分配，直到继续投入的边际收益大致相当。App 可把它用于时间管理和身心平衡：工作、亲密、健康、学习、休息、意义都需要一定投入；某一项过度挤占其他项，短期可能看似高效，长期会造成失衡。用户做选择时可问：我继续把时间投在这里，新增收益还高吗？是否有另一个被忽视的需要，投入一点就能明显改善生活质量？', '["享受均等", "资源分配", "时间管理", "生活平衡", "需要", "行为经济学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 235, now()),
(100236, '交换不是占便宜：稳定合作要让双方都看见收益', '交换关系能持续，不是因为一方永远赢，而是双方都认为交换后的处境比交换前更好。无论是亲密关系、家庭分工、团队协作还是商业谈判，如果长期只有一方付出、另一方享受，关系就会累积怨气。App 可把协商建议从“谁该听谁”改成“双方各自得到什么、付出什么、风险是什么、如何复盘”。好的交换不是冷冰冰算计，而是让贡献、需要和回报被看见，减少隐性账本和情绪爆发。', '["交换规律", "合作", "互惠", "关系协商", "家庭分工", "谈判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 236, now()),
(100237, '未知水域导航：把恐惧转成地图而不是灾难', '适用场景：用户面对关系变化、家庭冲突、分离风险或无法解释的不安时，容易把未知等同于灾难。
核心观点：恐惧并不只是要被消除的情绪，它常在提醒：当前信息不足、仪器失灵、旧办法不够用。把未知想象成“危险水域”有其价值，但如果只停留在惊慌或怨恨里，就会错过真正的航线。咨询中更有用的方向，是把恐惧转译成一张临时地图。
操作步骤：1）命名未知：我究竟不知道什么，是对方意图、关系结果、财务后果，还是自己的承受力？2）区分事实与解释：事实是发生过的行为，解释是我给它加上的意义。3）检查仪器：睡眠、情绪、支持系统、信息来源是否可靠。4）做小型探测：选择一个低风险行动，例如一次具体沟通、一次边界表达、一次独处复盘。5）观察—行动—复盘—校准：行动后记录什么有效、什么无效、下一步改变什么。
提醒：不要用“没事的”快速安抚用户，也不要把恐惧升级成灾难预言。更好的回应是：这里确实有不确定性，我们先画出可观察信号和可执行预案。恐惧被转成地图后，用户会更有控制感。
App 端提示：可把用户叙述转成一张“航海卡”：危险信号、缺失信息、可求助对象、下一步小实验、复盘时间。这样既承认风险，又避免让用户沉溺于想象中的恶龙。特别适合搭配情绪强度评分使用：恐惧越高，越要把任务拆到当天能完成的一步。', '["恐惧识别", "未知恐惧", "风险评估", "行动校准", "OODA", "自我负责"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 237, now()),
(100238, '不被视为理所当然：价值感来自稳定边界与可见投入', '适用场景：用户长期觉得自己在关系、家庭或团队中被消耗、被默认付出，却又不敢减少投入。
核心观点：不被视为理所当然，不是制造恐吓，也不是要求别人立刻感恩，而是重新让自己的时间、注意力、照顾、承诺和能力变得有边界。一个人越把重要资源无限免费化，越容易在表面“善良”下积累怨气；而怨气爆发后，又会被对方体验为攻击。
可转化为三类问题：1）我正在提供什么价值？包括情绪劳动、经济支持、家务、陪伴、专业能力、稳定性。2）我期待怎样的回应？回应要具体，例如尊重时间、共同分担、停止羞辱、愿意修复，而不是抽象地“对我好”。3）如果长期没有回应，我会如何保护自己？边界必须包含后果，否则只是抱怨。
行动建议：先停止把牺牲包装成爱。把“我都为你做了这么多”改成“这件事我愿意做到哪里，超过哪里我会停下”。把“你应该珍惜我”改成“当出现这些行为时，我会减少投入/暂停讨论/重新评估关系”。价值感不是靠证明自己不可替代，而是靠稳定地尊重自己。
App 端提示：当用户说“我不想再付出了”时，先不要劝其立刻切断，而是帮助他盘点哪些付出是自愿、哪些是讨好、哪些已经越过边界；再把每项付出配上清晰条件。若用户处在高风险关系中，边界不应只靠个人硬扛，而要同步考虑朋友、家人、专业服务或法律资源。', '["边界", "自我价值", "被重视", "期望管理", "关系成长", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 238, now()),
(100239, '记分牌模型：先看互动回路，再决定是否还要记分', '适用场景：用户在关系中反复计算“我做了多少、对方欠我多少、为什么总是我输”，陷入委屈与攻击循环。
核心观点：记分牌不是用来证明谁坏，而是用来观察互动如何一步步失衡。很多关系不是突然崩坏，而是在无数次让步、回避冲突、奖励破坏性行为、压抑真实需要中逐渐形成“我怎么做都不对”的感受。
使用方式：第一阶段，把分数写出来：哪些场景让我觉得自己永远输？我为了避免冲突做了哪些让步？我是否用沉默、讨好、补偿来换短暂平静？第二阶段，停止只围着对方反应转，改用自己的标准行动：我希望自己在这类场景中成为什么样的人？下次最小的不同回应是什么？第三阶段，评估是否还需要记分：当边界清楚、行为稳定、双方能协作时，记分牌应被放下；若仍只有单方努力，则它提示关系可能需要更大调整。
咨询提醒：不要让用户沉迷“翻旧账”。每一笔分数都要转成一个可观察行为、一个可改变动作、一个复盘日期。真正目标不是赢过对方，而是从输赢框架转向自我负责、协作或清醒退出。
App 端提示：可引导用户做七天互动记录，只写行为和后果，不写人格评价。记录后再问：哪些分数其实是我自己在继续记，哪些是真实需要被处理的关系问题。若记录显示双方都在记分，可进一步引导共同目标；若只有单方持续承担，则进入关系风险评估。', '["关系模式", "互动复盘", "权力动态", "责任", "冲突降温", "系统思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 239, now()),
(100240, '技能鸿沟：看见问题不等于会回应问题', '适用场景：用户能准确说出关系里的模式，却一到现场就变成指责、辩论、冷战或最后通牒。
核心观点：洞察和能力之间存在鸿沟。一个人可能已经看见“对方在转移话题”“我又被激怒了”“这段沟通在重复旧剧本”，但如果没有新的回应技能，洞察只会变成优越感或控诉。原材料中的“技能鸿沟”可以转化为：观察能力已经上线，行为能力还没跟上。
练习路径：1）先暂停而不是讲道理。高唤醒时，解释越多越像攻击。2）写“现场报告”：触发事件、我的身体反应、我脑中的解释、我做了什么、结果怎样。3）找出缺失技能：是不会拒绝、不会提请求、不会结束争吵、不会表达失望，还是不会承受对方不满？4）设计一句替代回应，例如“我现在听不进去，20分钟后回来继续”“这件事我不同意，但我会按这个时间处理”。5）复盘一次只改一个点。
咨询目标：把“我知道问题在哪”推进到“我下次可以做什么”。用户不需要一次变成熟，只要从自动反应前移半秒，就已经在跨越技能鸿沟。
App 端提示：当用户已经很会分析他人，却没有可执行动作时，回复重点应从“你看得很准”转向“下一次你准备停在哪里、说哪一句、做哪个动作”。这个条目也能降低自责：不会回应不是人格失败，而是技能尚未练熟，可以通过脚本和复盘训练。', '["行为复盘", "技能鸿沟", "沟通暂停", "冲突处理", "刻意练习", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 240, now()),
(100241, '先行动后解释：语言要由一致行为托底', '适用场景：用户总想通过一次长谈让对方理解自己、停止某种行为或承认错误，但现实中越解释越失效。
核心观点：语言不是没用，而是没有行为托底的语言很容易变成辩解、求认可或控制。关系中的信任通常不是被一句话建立，而是被一段时间的一致行动建立。只有当对方已经看见行为变化，语言才适合用来澄清“我现在为什么这样做、我的期待是什么、边界在哪里”。
实践顺序：1）先做可见改变，例如按承诺处理家务、准时离开争吵现场、稳定执行自己的作息和计划。2）减少解释欲，不在情绪最高点讲原则。3）当行为持续一段时间后，再用短句表达：“我最近在调整自己的生活方式；这件事我会按这个时间做；如果继续辱骂，我会暂停对话。”4）语言只服务于清晰，不服务于证明自己正确。
边界提醒：这不是冷暴力，也不是故意隐瞒重要事实。涉及安全、财务、亲密同意、重大关系决策时仍要明确沟通。此条的重点是：不要把还没被自己活出来的价值观，急着变成说服别人的演讲。
App 端提示：适合在用户准备摊牌前使用。先请用户列出过去两周自己已经稳定做到的三件事；如果列不出，说明谈话可能还缺少行为基础，需要先补行动。若用户把少说话理解为消失，需要补一句：暂停前说明回来时间，回来后完成沟通，这是安全感的一部分。', '["沟通", "一致性", "非语言信号", "边界表达", "行动承诺", "信任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 241, now()),
(100242, '相互依赖警报：牺牲换认可会把照顾变成怨恨', '适用场景：用户习惯过度负责、害怕冲突、隐藏需求，并期待别人自动理解自己的付出。
核心观点：相互依赖并不是“太爱别人”，而是把自我价值绑在被需要、被认可、被留下上。它常表现为：替别人承担本该由对方承担的责任；嘴上说“我没关系”，心里记账；害怕提出要求会被抛弃；用照顾换亲密；冲突前先撒谎、隐瞒或讨好。长期看，这会让照顾者觉得自己被利用，也让被照顾者感到被控制。
识别问题：当我说“都是为了你”时，里面是否藏着“所以你必须按我期待回应”？当我不表达需要时，是否仍期待对方读懂？当对方没有感恩时，我是否爆发怨恨？
替代策略：1）把隐性契约改成明示请求：我希望你本周承担两次接送，而不是我默默做完再生气。2）把拯救改成尊重责任：对方能做的事，让对方做。3）把害怕冲突改成可承受分歧：不同意不等于被抛弃。4）建立外部支持系统，不把伴侣、孩子或同事变成唯一情绪出口。真正的亲密不是无限牺牲，而是双方都能带着边界靠近。
App 端提示：可用“付出—期待—没说出口—怨恨”四列表帮助用户拆解隐性契约。只要期待无法被对方明确听见，就先不把对方未满足期待解释成恶意。在成长型咨询里，这类用户尤其需要练习“直接要”和“允许对方拒绝”，否则照顾会继续变形。', '["相互依赖", "隐性契约", "讨好", "认可需求", "边界", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 242, now()),
(100243, '容忍即强化：用奖励回路看待反复伤人的行为', '适用场景：用户抱怨某种行为反复出现，如冷嘲热讽、失约、甩锅、越界、情绪勒索，却每次都用退让换短暂平静。
核心观点：反复行为通常被某种奖励维持。奖励不一定是夸奖，也可能是关注、让步、补偿、替对方收拾残局、降低标准，或用沉默让事情过去。与其只问“对方为什么这么糟糕”，更有建设性的问题是：这个行为之后，系统给了它什么好处？
操作步骤：1）列出一个具体行为，不做人格审判。2）记录它发生后的常见结果：谁退让、谁获得控制、谁免于承担责任。3）停止奖励破坏性行为：不在辱骂中继续解释，不替长期失责者兜底，不用亲密或资源换和平。4）奖励修复行为：对方愿意承担、道歉、补偿、稳定改变时，给予合作与肯定。5）设置可执行后果：例如暂停讨论、重新分工、引入第三方、调整关系距离。
重要提醒：此模型不是让用户责怪自己“都是我纵容的”。在暴力、胁迫或严重风险中，优先安全与外部支持。它适用于有行动空间的关系复盘：看清奖励回路，才能改变回路。
App 端提示：适合处理反复冲突。让用户选一个最小边界做实验，例如“不在辱骂中继续解释”。实验目标不是让对方立刻改变，而是验证回路是否开始松动。当边界执行后对方短暂升级反应，不要立刻判定失败；先观察自己是否又用旧奖励把循环接回去了。', '["行为强化", "边界", "关系风险", "反馈回路", "冲突解决", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 243, now()),
(100244, '关系中的领导力：不是获得授权，而是先管理自己', '适用场景：用户觉得“对方不配合，所以我没法改变关系”，或者把领导力误解为命令、控制和压倒。
核心观点：可迁移的精华是：领导首先是自我管理，不是等别人授权。一个人若无法管理自己的时间、情绪、承诺、标准和愿景，就很难让家庭、团队或关系信任他的方向。真正的领导不是争论“你应该听我的”，而是持续做该做的事，让愿景变得可见。
行动化：1）先定义愿景：我希望这个家/关系/项目更稳定、更健康、更自由，具体表现是什么？2）定义自己的责任：哪些事无论别人怎样我都要做好？3）用标准和时间表行动：我会在周六上午处理这件事；这不是我现在的优先级；如果你想按另一标准完成，可以由你负责。4）从小计划练习执行，例如一次家庭活动、一次预算整理、一次固定运动。5）出错后修正，不抱怨追随者。
边界：领导不等于支配别人，也不等于把对方贬低成下属。它是承担自己选择的后果，并邀请能认同愿景的人协作。若长期无人愿意协作，得到的也是重要信息。
App 端提示：如果用户把领导力说成“为什么 TA 不听我的”，可把问题转回“你自己的标准、计划和后果是什么”。领导力先看可执行承诺，而不是对方服从程度。此条也适用于职场和亲子：先把自己可控范围做清楚，再讨论他人是否愿意合作。', '["领导力", "愿景", "责任", "家庭协作", "执行力", "决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 244, now()),
(100245, '定义价值与底线：先问“我想要什么”', '适用场景：用户在关系里只问“怎样才能让对方改变”，却说不清自己真正想要怎样的生活。
核心观点：很多痛苦来自目标不清。长久不等于幸福，经济稳定不等于满意，外人眼中的体面也不等于内在满足。若一个人无法定义自己珍视什么，就容易用社会剧本、沉没成本或他人期待替自己做决定。
澄清问题：1）如果不考虑面子，我为这段关系感到骄傲吗？2）我是否经常感到满足、轻松、被尊重？3）对方是否为我的生活增加价值，还是主要消耗？4）哪些是必须存在的：尊重、忠诚、亲密、共同育儿、财务透明、情绪安全、成长空间？5）哪些可以协商，哪些是底线？6）如果五年后仍是现在这样，我会感谢今天的自己留下，还是怨恨自己逃避？
咨询应用：把“我不知道要不要继续”拆成指标，而不是逼用户立刻选择。定义价值不是把自己的价值观强加给别人，而是知道自己愿意为什么投入、愿意为哪些缺失承担代价，以及什么情况下要改变距离。
App 端提示：可生成一张关系价值清单，让用户按“必须有、希望有、可协商、不能接受”分类。分类后再讨论选择，通常比直接问分不分更稳定。若用户暂时答不上来，可以先从身体反应入手：想到留下或离开时，哪里放松，哪里收紧。这个过程也能减少把责任全推给对方的冲动。', '["价值澄清", "目标设定", "底线", "关系决策", "自我诚实", "选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 245, now()),
(100246, '焦虑需要出口：改变关系时别制造无路可走的压力', '适用场景：用户开始设边界或自我提升后，对方变得焦虑、试探、黏人、指责或退缩，用户不知道该安抚还是硬扛。
核心观点：关系系统改变时，焦虑会升高。若焦虑没有清晰出口，人可能会用旧方式求安全：争吵、控制、讨好、突然亲近、突然退出、破坏进展。原材料中的“仓鼠迷宫”可中性化为：当一个人不知道怎样才能重新获得连接和安全感时，他会在脑内反复转圈。
健康做法不是操纵不确定性，而是给出可实践的出口。出口包括：明确哪些行为会增加亲近，哪些会降低亲近；明确冲突后如何修复；明确表达“我在改变自己，不是在惩罚你”；明确安全底线，如不羞辱、不威胁、不越界。
示例句：我愿意更靠近，但需要我们说话时不攻击人格；如果你愿意一起制定分工，我会投入；如果你只是用指责逼我回到旧模式，我会暂停。
咨询提醒：模糊和忽冷忽热也许能短期制造反应，但会损害安全感。真正可持续的关系改变，需要让双方知道怎样做会走向更好，而不是只知道自己正在失去什么。
App 端提示：当用户的改变引发对方焦虑时，不建议用“让 TA 着急一下”作为策略。更适合帮助用户同时表达稳定性和边界：我不会惩罚你，但我也不会回到旧模式。出口越具体，越不容易变成威胁；例如“周日晚一起复盘分工”比“你要更在乎我”更可执行。', '["焦虑", "关系修复", "安全出口", "情绪调节", "沟通设计", "支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 246, now()),
(100247, '自我提升后的拖绳效应：给关系追赶期，也保留选择权', '适用场景：用户开始健身、学习、稳定情绪、减少讨好后，发现伴侣、家人或朋友没有同步改变，于是产生怨恨或想立刻切断。
核心观点：自我提升常有“拖绳效应”：一开始你在自己的方向上前进，关系系统还没感觉到；等改变足够明显，绳子被拉直，对方才突然意识到你已经走远。此时常出现两种误判：用户觉得“你早干嘛去了”，对方觉得“你怎么突然变了”。
处理方式：1）承认不同步是正常现象。你是在自己的时间线上成长，对方不是你脑内计划的参与者。2）看见怨恨来源：对方可能像一面镜子，照出你过去放弃自己、纵容失衡的旧样子。3）给一个追赶期：在行为稳定后说明愿景、邀请协作、提供具体路径。4）设复盘点：例如三个月后看是否有真实行动，而不只看承诺。5）保留选择权：追赶期不是无限等待；若对方持续拉你回旧模式，你可以调整距离。
此模型帮助用户避免两种极端：一是报复性切断，二是为了照顾所有人而放弃自己的新航线。成熟做法是深呼吸、继续引领、观察对方是否愿意同行。
App 端提示：可让用户设置“追赶期复盘表”：我会继续做什么、我邀请对方做什么、我观察哪些行为、到期后如何决定。这样能把耐心和底线同时保住。追赶期结束后，不用急着审判对方好坏，只需看双方生活方向是否仍能相容。', '["自我提升", "关系过渡", "耐心", "结果独立", "复盘", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 247, now()),
(100248, '改变不是小把戏：避免“好转—退回—再好转”的过山车', '适用场景：用户学到某个沟通技巧或边界技巧后短期有效，一旦关系缓和就恢复旧模式，随后问题复发。
核心观点：如果改变只是策略表演，对方会逐渐不信任；如果改变被内化为新的生活方式，关系才会稳定。很多人把边界、冷静、健身、独立、减少讨好当作“让对方回心转意”的工具。短期好转后，他们立刻退回过度付出、求认可、无标准的旧状态，于是形成过山车：危机—改变—好转—松懈—复发—更大危机。每循环一次，信任都会被侵蚀。
维持方式：1）把技巧写成身份承诺：我不是为了换取某次回应才睡好、运动、守边界；这是我想成为的人。2）把好转视为反馈，不视为终点。3）当对方出现积极回应时，不用“奖励”自己放弃标准。4）建立复发预警：开始翻旧账、停止自我照顾、重新讨好、把边界变成威胁，都是退回信号。5）每月复盘一次：哪些行为已经自然化，哪些还靠愤怒撑着？
咨询中要强调：真正改变看起来不戏剧化，而是稳定、可预测、可持续。有效的事要继续做，不是等关系好一点就停止。
App 端提示：适合在用户短期好转后推送。提醒用户把新行为写进日程、环境和支持系统，而不是只靠愤怒或危机驱动；危机退去后仍能执行，才算内化。如果用户依赖对方反应来维持改变，可提醒他把改变连接到自尊、健康、孩子、职业等更稳定价值。', '["改变维持", "信任", "复发预防", "习惯保持", "关系模式", "内化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 248, now()),
(100249, '五种结果思维：关系选择不是只有修复或失败', '适用场景：用户把关系问题简化成“要么挽回成功，要么人生失败”，因此迟迟不敢看清现实。
核心观点：成熟决策需要把可能结果全部摊开，而不是只盯着最想要的一个结果。原材料把关系走向整理成多种结果，其可迁移价值在于：留下、离开、重建、接受现状、改变关系结构，都不是抽象口号，而是不同成本、风险和代价的组合。用户越能看见选项，越少被恐惧和沉没成本绑架。
咨询步骤：1）写出理想结果：我最希望怎样？2）写出现实可接受结果：如果理想达不到，什么仍可被我接受？3）写出不可接受结果：哪些状态继续一年会伤害我？4）为每个选项列成本：孩子、财务、身体、社交、心理、价值观、法律和安全。5）为留下和离开都做计划：留下需要哪些边界和复盘点；离开需要哪些资源和支持。
关键提醒：选择不是为了证明谁对谁错，而是为了让生活对自己有效。一个清醒选择的结果，即使不完美，也比在默认剧本里长期消耗更能恢复自主性。
App 端提示：可把五种结果简化为“修复、重谈、暂时接受、拉开距离、结束关系”五栏。每栏都写收益、代价、所需资源和最坏情况预案。此表也能帮助用户识别逃避：若每个选项都不愿承担成本，真正议题可能是害怕选择本身。先做预案，再做决定，能降低冲动选择。', '["关系决策", "风险评估", "选择成本", "自主性", "预案", "目标澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 249, now()),
(100250, '安全基地：人只有感觉被接住，才有力气探索', '依恋并不是儿童才有的依赖，而是贯穿一生的安全调节系统。一个人感到安全时，会自然去探索、学习、工作和建立关系；感到危险、分离或失控时，会本能地寻找一个“更强、更智慧、可回应”的对象作为安全港。对 App 端知识库来说，这个概念可以转化为一条关系成长原则：先建立可获得性，再谈改变。可获得性不只是人在场，更是情绪上能回应、能看见、能稳定。咨询、伴侣沟通或亲子互动中，如果一方已经处于威胁感里，直接讲道理、催独立、要求改变，往往会让探索系统关闭。更有效的顺序是：先确认“我在这里、我听见你、这件事可以慢慢说”，再邀请对方看见选择和行动。安全基地的目标不是让人黏住关系，而是帮助人能在连接和自主之间灵活往返：难过时可以回来被安抚，恢复后又能重新走向世界。产品化时可做成“安全基地自检”：我现在是在探索模式还是求安全模式？我需要的是建议、陪伴、确认，还是实际保护？对支持者也可给出提醒：不要把依赖需求简单评价为不成熟，也不要把独立要求包装成冷漠；成熟关系是在需要时可求助，在稳定后能放手。若用户暂时没有可靠他人，也可引导建立微型安全基地，如稳定呼吸、身体接地、联系一位可信任的人、写下此刻可控的下一步。', '["依恋", "安全基地", "安全港", "亲密关系", "心理咨询", "情绪调节", "可获得性", "自主探索"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 250, now()),
(100251, '调谐沟通：一方发信号，另一方用行动回答', '安全型依恋的核心不是完美照顾，而是“信号—回应”的调谐循环：孩子清楚表达需要，照顾者读懂线索并做出相称回应，孩子被安抚后又能继续探索。迁移到成人关系与咨询场景，沟通质量不只看说了什么，还要看对方的信号是否被准确接住。一个人流泪、沉默、退缩、提高音量或反复追问，背后常有“我需要被看见、被安抚、被确认边界”的信号。有效回应不是把自己的节奏强加给对方，而是先校准：我听见你现在很紧，我猜这不是要吵赢，而是需要确定我没有离开；你希望我先陪你平静，还是一起想办法？调谐还包括及时放手：当对方已经恢复，不继续包办、不以关心之名控制。知识库可将其写成四步：识别信号、命名需要、给出相称回应、回头确认是否真的有帮助。这条知识也适合转成对话质量评分：对方的情绪有没有被命名？请求有没有被具体化？回应是否与需要相称？例如伴侣说“你根本不在乎我”时，表层像指责，底层可能是“我需要确认你还在乎”。如果直接辩解“我怎么不在乎”，互动会升级；若先回应“你现在像是很孤单，也很想确定我在”，才可能让对方的防御下降。调谐不是读心术，猜错也可以修正，关键是持续询问和校准。', '["调谐", "依恋沟通", "共情", "情绪信号", "关系修复", "亲子沟通", "伴侣沟通", "咨询技术"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 251, now()),
(100252, '回避与焦虑不是性格缺陷，而是早年求安全的策略', '回避型和焦虑/矛盾型依恋常被误解为“冷漠”或“太黏”，但依恋视角提醒我们：它们首先是适应策略。回避者曾学到表达需要可能得不到回应，甚至会被拒绝，于是降低痛苦外显，把注意力转向任务、理性或独处；表面平静不等于没有压力。焦虑者曾经历回应不可预测，于是放大信号、持续监测对方行踪和承诺，试图用高强度表达换取稳定。App 在给建议时应避免贴标签和责备，而要帮助用户识别策略背后的安全功能：我这样做是在保护什么？代价是什么？对回避倾向的人，可用低压、具体、可选择的邀请，尊重其自主；对焦虑倾向的人，要增加可预期性，如明确回复时间、说清边界，并同时练习自我安抚。目标不是消灭策略，而是让旧策略在新关系中有机会被更新。这能帮助知识库避免“你太回避”“你太焦虑”的二次伤害。更好的语言是：你的系统曾经学会用撤退/追问来减少危险，现在我们尝试更低成本的新方法。给回避者的练习可以是说出一个小需要，而不是一次性暴露全部脆弱；给焦虑者的练习可以是延迟一次确认冲动，同时用日程、承诺和自我安抚增强可预测性。双方都需要看见：策略背后有爱和恐惧，改变要靠安全经验累积，而不是靠羞耻驱动。', '["回避型依恋", "焦虑型依恋", "矛盾型依恋", "安全策略", "亲密关系", "自我保护", "关系模式", "情绪需求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 252, now()),
(100253, '内部工作模型：亲密关系里运行的是“注意力规则”', '内部工作模型不只是“我对父母的记忆”，更像一套自动运行的注意力、记忆和解释规则：哪些信号会被看见，哪些感受会被允许，哪些证据会被忽略，哪些行为会被认为最能保住关系。安全型模型较开放，能随着新经验调整；不安全模型更容易把新关系硬塞进旧预期，例如把治疗师的短暂沉默理解为拒绝，把伴侣的迟回复解释为抛弃。知识库可将这一点转化为一种自助提问：此刻我最先注意到什么？我自动忽略了什么？我正在用哪条旧规则保护自己？这条规则当年可能有用，如今还准确吗？咨询中的改变往往不是给用户一个新道理，而是帮助他看见旧规则如何筛选现实，再通过小的安全例外让模型松动。关系成长的关键，是把“我就是这样”改写为“我学会过这样保护自己，现在可以多一个选择”。可将其设计为“旧规则捕捉卡”：触发事件是什么？我脑中立刻出现的解释是什么？它让我看见哪些证据、忽略哪些证据？如果把这条规则当作旧时的保护者，它当年在保护我免于什么？今天我能不能做一个小实验，收集相反证据？这种写法适合咨询作业、关系复盘和情绪日志。它也提醒支持者，不要急着要求用户相信新解释；旧模型之所以黏着，是因为它曾经维持过生存和亲近，必须在被理解后才可能更新。', '["内部工作模型", "依恋规则", "注意力", "认知模式", "关系误读", "心理咨询", "行为实验", "安全例外"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 253, now()),
(100254, '元认知安全：把感受当信号，不当最后判决', '依恋安全不仅体现在关系里，也体现在一个人能否对自己的心理状态保持反思。元认知能力让人知道：我现在的想法、感受和记忆是真实体验，但未必就是事实全貌；我的信念会变化，别人对同一件事也可能有不同而真实的感受。缺少这种能力时，人容易把一瞬间的情绪当作最终判决，比如“我感觉被抛弃，所以他一定不爱我”“我觉得自己很差，所以我就是失败者”。App 可以把它做成情绪急救句式：我注意到自己正在产生一个强烈解释；这个解释可能在保护我；我可以先不按它行动；我需要再收集三个事实。咨询师和支持者也要用元认知姿态回应，而不是急着反驳：你此刻的感觉很强，我们先尊重它，同时也给它一点空间，看看还有没有其他可能。这样的空间，常常就是从反射反应走向关系修复的入口。在产品中，这条可作为“情绪与事实分离”模块：先允许情绪存在，再把解释放在括号里。例句是：我很难过，这是事实；“他一定故意伤害我”是一个解释；我可以先照顾难过，再决定是否验证解释。它也适合帮助用户从关系绝望中退一步：此刻的我处在恐惧状态，所以世界看起来很窄；等身体平静后，我可能会看见更多信息。元认知不是冷冰冰地分析自己，而是用温柔的观察者位置，让情绪不必靠冲动行动来证明自己。', '["元认知", "反思功能", "情绪调节", "依恋安全", "关系误读", "认知松动", "自我觉察", "心理弹性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 254, now()),
(100255, '语言虐待的第一线索：不是脏话，而是持续让人失去现实感', '语言虐待常常不是一句明显的脏话，而是隐藏在反问、讽刺、否定、威胁、敌意和模棱两可信息里的攻击。它的伤害之一，是让受害者越来越不相信自己的感受：明明谈话后痛苦、困惑、失去方向，却又说不出“到底哪里不对”；明明被贬低、被忽视、被误导，却被对方说成太敏感、小题大做或没有幽默感。知识库在处理这类主题时，应把“感受”视为重要证据，而不是附属情绪。可提示用户记录三类线索：对方说了什么和做了什么；谈话后我的身体与情绪反应是什么；这种模式是否重复出现并让我更怀疑自己。识别语言虐待不需要等施虐者承认，也不需要旁观者完全理解。若一段关系持续让人失去现实感、自尊和表达能力，就需要把它从“沟通不好”升级为“可能存在伤害性权力模式”来评估。不建议让用户一开始就去搜集“对方是不是坏人”的结论，而是先保护现实感：把具体语句写下来，标注发生场景、是否有旁人在场、对方事后是否否认、自己是否反复想解释清楚。若记录显示同类互动反复发生，尤其总在私下发生、总让你怀疑自己、总把问题推回你身上，就要提高风险等级。知识库还应提醒：困惑本身就是线索，因为健康沟通即使有冲突，也不会长期让一方失去判断力和表达能力。', '["语言虐待", "现实感", "情绪证据", "关系伤害", "煤气灯效应", "自我怀疑", "识别红旗", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 255, now()),
(100256, '支配权力与个人权力：分清控制关系和合作关系', '语言虐待背后常有两种关系观的冲突：支配权力把关系看成输赢、上下和控制，个人权力把关系看成相互依存、共同发展和彼此尊重。前者需要通过压倒别人来获得安全感，后者允许双方都有感受、边界、请求和拒绝。这个区分很适合迁移到 App 的关系评估：一段关系是否允许共同制定目标？双方是否都能表达观点并被听见？拒绝是否会被尊重？成功是否会被祝福而不是被打压？如果每次沟通都变成谁对谁错、谁服从谁、谁证明自己没有错，用户就不应只从“我怎么解释得更清楚”入手，而要看见权力结构本身。对咨询和自助内容而言，关键不是鼓励用户赢回争论，而是恢复个人权力：知道自己的感受有价值，能清楚表达，能说不，也能在不被尊重时暂停或退出对话。当用户问“是不是我太敏感、太不懂沟通”时，这个框架能把焦点从个人缺陷转向关系结构。可以给出对照表：支配关系关心服从、面子和胜负；合作关系关心事实、感受和共同方案。支配关系里，解释越多，越可能被当作新的把柄；合作关系里，解释会带来更多理解和调整。若用户发现自己总在证明自己没有错、没有恶意、没有不合作，就需要暂停说服对方，先恢复个人权力：我能描述事实，我能保留感受，我能提出条件，我能选择离开。', '["支配权力", "个人权力", "合作关系", "控制", "边界", "伴侣关系", "自尊", "关系评估"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 256, now()),
(100257, '面对否认与讽刺：边界从“我知道自己感受是真的”开始', '在语言虐待关系中，受害者常试图用更多解释换来理解，但对方可能持续否认、嘲弄、假装道歉，或把伤害说成玩笑。此时最容易发生的陷阱，是把目标设成“让对方承认我的感受有道理”。更稳的边界起点是：我不需要先赢得对方批准，才能确认自己受到了伤害。App 可提供一个不争辩动机的表达模板：刚才你用嘲讽/吼叫/贬低的方式说话，我感到受伤和不安全；我愿意讨论事情本身，但不接受这种方式；如果继续这样说，我会暂停谈话，等双方能尊重地说话再继续。这个模板的重点是行为、影响和后果，而不是证明对方“故意伤害”。如果对方继续否认，用户要把它当作边界信息，而不是继续解释自己的纯真。边界不是让对方立刻改变，而是让自己不再被迫留在伤害性互动里。边界表达要短，因为长篇解释容易被对方带入新一轮否认。App 可建议用户提前写好三句：第一句描述行为，第二句说明影响，第三句给出后果。比如“你刚才用讽刺评价我的能力；我感到被贬低，也无法继续好好听；如果继续这样说，我会离开房间，晚些再谈。”之后要把注意力放在执行，而不是让对方承认。若对方愿意修复，再进入具体议题；若对方继续嘲讽、追击或倒打一耙，边界的意义就是帮助用户结束现场伤害。', '["边界表达", "语言虐待", "否认", "讽刺", "自我确认", "关系安全", "停止争辩", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 257, now()),
(100258, '虐待型沟通的三组红旗：竞争、操纵、亲密关闭', '虐待型伴侣关系往往缺少显眼标志，因为施虐者可能在外人面前表现良好，甚至以关心的语气发出控制信息。可迁移的识别方法，是看三组互动红旗。第一，竞争取代合作：你的成绩、学习、工作或快乐被对方体验为威胁，谈话变成谁更高、谁更有理。第二，操纵取代交流：对方打断、转移、假装不懂、事后否认约定，或只在需要你帮忙时友善。第三，亲密被关闭：你们无法共同制定计划、无法平等交换意见，也很难分享真实情绪；每次你想澄清问题，最后都变成你反省自己哪里做错。知识库可将这三组红旗用于关系自检：如果长期不能共同讨论目标、不能安全表达感受、不能在外人不在时被尊重，那么问题不只是沟通技巧不足，而可能是权力和敌意正在破坏亲密。下一步应优先做支持系统、记录证据和边界计划，而不是继续单方面优化说法。该条可用于 App 的关系风险分层：偶发冲突看修复能力，长期红旗看结构稳定性。若一次争吵后双方能道歉、复盘、调整，那是普通冲突；若每次都由一方承担全部责任，另一方从不承认影响，且你的行动空间越来越小，就更接近伤害性模式。对这类用户，内容不宜只推“如何温柔表达需求”，还要提供外部支持、财务和居住安全、可信联系人、必要时的专业或法律资源等下一步清单。因为在权力失衡关系里，单纯提升沟通技巧可能让用户继续留在危险循环中。', '["关系红旗", "操纵", "竞争", "亲密关闭", "语言虐待", "伴侣关系", "权力模式", "安全计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 258, now()),
(100259, '高难沟通顺序：先安抚本能脑，再触达情绪，最后讲逻辑', '《感召力》把说服和领导力语言拆成三个层面：本能脑先判断安全与威胁，情感脑决定是否有动力，逻辑脑最后才处理理由。把这个模型迁移到心理咨询、伴侣冲突和亲子沟通中，一个常见错误是从逻辑开始：我为什么这么做、你为什么不该生气、事实其实是怎样。对方若已经感到被攻击，逻辑只会被当成辩解。更稳的顺序是先降低威胁：放慢语速、降低音量、说明共同目的、给出选择感；再触达情绪：命名对方的失望、害怕、委屈或愤怒；最后才进入事实、限制和下一步。可用一句话开场：“我不是来赢你，我想先确认你哪里受伤了，然后我们再一起看怎么办。”这不是讨好，而是尊重大脑处理信息的顺序。安全感不够时，道理很难进入；安全感恢复后，逻辑才有被听见的机会。产品化时可把它做成“冲突开场检查”：我的语气会不会让对方更紧？我有没有先说明不是来惩罚或否定？我有没有先听见情绪，再讲事实？它也能指导 AI 回复：先承接用户处境和身体感受，再帮用户整理情绪，最后提供结构化建议。对于咨询师或陪伴者，这个顺序能防止过早教育化。许多用户不是不知道道理，而是神经系统还处在警报中；当警报没有被看见，越正确的建议越像压力。', '["高难沟通", "本能脑", "情感脑", "逻辑脑", "安全感", "冲突降温", "伴侣沟通", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 259, now()),
(100260, '移情—价值观—平衡：回应愤怒时的三段式', '当对方愤怒或失望时，直接解释政策、规则或现实限制，很容易被听成冷漠。《感召力》中处理棘手问题的序列可迁移为咨询和关系沟通模板：先移情，再价值观，最后平衡。移情不是同意对方所有判断，而是承认其情绪经验：“我理解你为什么会生气，这件事让你觉得被忽视。”价值观是找到双方仍然共享的方向：“我们都希望这段关系里能被尊重，也能把事情说清楚。”平衡才是补充现实：“同时，我不能在被吼叫时继续讨论；我们可以暂停十分钟再回来。”这个结构比“但是你也有问题”更容易保留连接，因为它先让对方感到被看见，再把边界和限制放进共同目标里。用于 App 时，要提醒用户避免假共情：如果移情只是铺垫反驳，对方会更防御；真正有效的是先认真进入对方视角，再温和而清楚地带入自己的立场。这个三段式还可以用于道歉和拒绝。道歉时：先承认“这让你很受伤”，再指出“我也重视信任”，最后说“我会怎样补救”。拒绝时：先承认“你很希望我现在答应”，再连接“我也希望我们关系里能诚实”，最后表达“但我这周做不到，我能提供另一个时间”。价值观部分尤其重要，它把双方从敌对位置拉回同一边；平衡部分则避免为了共情而牺牲边界。若只移情没有边界，会变成讨好；若只有边界没有移情，会像冷冰冰的判决。', '["移情", "价值观", "平衡", "冲突回应", "共情", "边界", "沟通模板", "高难对话"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 260, now()),
(100261, '隐喻、故事与成三：让表达被记住而不操控', '沟通不只是传递信息，也在塑造对方脑中的画面。《感召力》提醒，隐喻会悄悄分配角色：如果把组织比作机器或汽车，领导者像驾驶员，其他人就容易被放进零件位置；如果把改变比作种植、旅程或共同建造，听众更容易感到自己是有生命、有选择的参与者。心理咨询和关系成长内容尤其要谨慎选择隐喻：把用户称为“坏掉的人”会制造羞耻，把他称为“正在修复地图的人”“重新学习安全的人”则更有行动空间。故事也是人类默认的交流方式，它比抽象建议更能承载情绪和记忆；而三点式结构能让复杂建议变得完整、可执行。App 输出建议时，可把观点组织为一个温和隐喻、一个贴近日常的小故事、三个可实践动作。这样表达既容易被记住，又不靠恐吓或操控推动改变。在心理健康内容里，隐喻尤其影响用户身份感。说“你要战胜自己的脆弱”可能强化内在战争；说“你在学习和脆弱合作”会降低内耗。故事也不必宏大，可以是一个常见生活片段：一次迟回复、一次争吵后的沉默、一次敢于说不的练习。三点式则帮助用户把复杂情绪落地，如“先停下、再命名、后选择”。这条的伦理重点是：表达结构服务于理解和自主，而不是为了让用户被说服。好的心理教育让人更能做自己的决定，而不是更容易被话术牵着走。', '["隐喻", "故事", "成三原则", "表达结构", "心理教育", "沟通设计", "关系成长", "去羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 261, now()),
(100262, '成熟从停止“改变和指责模式”开始', '关系出问题时，人常在两端摇摆：把原因全放在对方身上，幻想“只要 TA 改变就好了”；或把别人的痛苦全揽成自己的失败，觉得“都是我不够好”。两者都看似有解释力，却把复杂互动简化成某个人的错，反而让成长停住。更成熟的入口不是替自己辩护，也不是自责，而是把注意力转回：我在这个循环里做了什么？我能负责什么？我如何在压力下不再自动反应？在咨询/自助场景中，可引导用户先描述互动链条：对方做了什么，我如何解读，我的身体和情绪如何升高，我采取了沉默、讨好、指责、拯救还是逃离，结果又怎样影响对方。这样，问题从“谁坏/谁对”变成“这个系统如何运转”。成熟不是自我抬高，而是在关系中承担自己那一份，减少无效反应，为他人也腾出成长空间。可迁移练习：冲突后写三栏——事实、我的反应、下一次我愿意做的一个更成人的动作。暂时少写“对方应该怎样”，除非它能转化为一个清楚、可商量、可被拒绝的请求。它还能防止咨询对话滑向审判：来访者既不需要被要求原谅，也不需要被鼓励继续控诉，而是被邀请看见自己仍有选择权。对高情绪用户，可先做稳定和安抚，再进入责任梳理；责任不是罪责，而是可改变的位置。', '["心智成熟", "关系模式", "责任边界", "自我觉察", "冲突修复", "情绪管理", "家庭系统", "咨询提示"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 262, now()),
(100263, '自我分化：在亲密联结中保持独立思考', '自我分化可以作为关系成长的核心能力：一个人既能和重要他人保持情感联结，又不把自己的立场、情绪和价值完全交给关系气氛决定。低分化时，人容易在两种反应间摆动：为了和谐而融合，压下真实想法；或为了保住自我而切断关系，表面独立、内心仍被对方牵动。较成熟的做法不是冷漠，也不是强硬，而是在紧张场景里继续表达自己，并允许对方不同意。App 可以把它拆成三个提醒：第一，先把“我真正相信什么、我想怎样做人”写清楚；第二，用平静语气表达立场，而不是用批评逼对方认同；第三，在分歧后仍维持基本联系，避免用消失、冷战或过度解释来缓解焦虑。自我分化特别适用于亲子、伴侣、职场和友谊冲突：用户需要的不是立刻赢得对方，而是在关系压力下不失去自己。分化越高，越能把“我爱你/我在乎你”和“我有不同选择”同时放在关系里。这一能力也能降低“边界=疏远”的误解。分化不是把别人推出去，而是让关系容得下两个真实的人。练习时可以从低风险关系开始：先表达一个小偏好，观察自己是否会因对方失望而过度补偿，逐步训练承受分歧的肌肉。最终评估标准不是对方是否满意，而是自己是否更清楚、更稳定、更少被卷入旧循环。', '["自我分化", "亲密关系", "独立思考", "情感联结", "边界", "原生家庭", "冲突沟通", "成熟人格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 263, now()),
(100264, '辨认真成熟与假成熟：认同和反叛都可能是在借用自我', '假成熟常常很像能力：会照顾人、会讲道理、能在公共场合表现出色、能赢得赞许，甚至能以叛逆姿态显得很有个性。但如果这种成熟依赖他人的认同，或依赖与某个人、某个群体对着干，它就不是稳定的内在立场，而是“借来的成熟”。一旦关系不稳定、弱点被看见、期待落空，个体就可能迅速讨好、疏远、愤怒或崩溃。真成熟的检验不在顺境，而在紧张和无人喝彩的场合：能否继续按价值观行动，能否清楚表达而不专横，能否忍受自己和他人的不适，能否反思自己的部分而不把责任全推给别人。App 可用此条帮助用户识别“我是在做自己，还是在维持人设”。提示问题包括：这个决定如果没人夸我，我还会做吗？如果对方不赞成，我是否立刻改变或故意反着来？我现在的强势/脆弱，是事实，还是为了影响别人？成熟不是表现得完美，而是在不同关系场景里越来越一致地承担责任。这条尤其适合成就型、讨好型或长期被比较的用户：他们可能非常能干，却在亲密关系中失去方向。后台可将“假成熟”识别为一种压力反应，而非人格缺陷；目标不是拆穿用户，而是帮助其把外部评价转回内在原则。它也能提醒内容生成避免用“强大人设”替代真实成长。', '["假成熟", "真自我", "人设", "认同需求", "反叛", "价值观", "自我一致性", "关系压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 264, now()),
(100265, '三角关系：别把两个人的紧张交给第三方解决', '当两个人之间的紧张难以承受时，最容易出现第三方：向朋友抱怨伴侣、让孩子承接夫妻焦虑、让父母或同事替自己站队、把症状或问题行为变成家庭共同关注的焦点。第三方能短暂降压，却常让真正的关系问题停留在原处，还把负担转移给无关者。识别三角关系的信号包括：我是否不断向不在场的人诉苦，却不和当事人谈？我是否成了调解者、拯救者、盟友或替罪羊？两个人是否因为共同担心我而避免面对彼此？更成熟的方向不是突然断开第三方，而是把谈话带回该发生的关系中：与当事人直接、具体、温和地沟通；向第三方倾诉时少寻求站边，多整理自己的反应；如果自己被卷入别人冲突，先问“这件事谁才是应该直接面对的人”。在家庭、伴侣和职场中，退出三角关系能减少误解，也能让每个人重新承担自己的那一份成熟任务。在 App 场景里，它可作为“倾诉后的下一步”提示：倾诉可以帮助降温，但如果只停留在倾诉，会让问题固定。更有建设性的倾诉，是请第三方帮助自己准备一次直接沟通，而不是请第三方证明自己完全正确。若直接沟通暂时不安全，也可以先做计划、求专业支持，而不是让无关者长期承压。', '["三角关系", "家庭系统", "伴侣冲突", "亲子关系", "站边", "拯救者", "关系边界", "直接沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 265, now()),
(100266, '离家独立不是逃离或依赖，而是带着真实保持联结', '成年后的独立不只是搬出去、经济自理，或减少联系。若一个人仍无法在父母面前表达不同意见，仍靠报喜不报忧维持认可，或只用义务式探望维持表面和平，他在情感上可能仍停留在未完成的离家阶段。另一端是“逃离”：把父母贴上不可理喻的标签，用疏远证明自己独立，却在相似亲密关系中继续被旧反应触发。更成熟的离家，是在联结和自主之间建立新平衡：能关心父母，但不替他们生活；能听取意见，但不把选择权交出去；能说出真实感受，但不用攻击来宣告边界。App 可把这一条用于成年亲子关系：当用户想断联、爆发或继续讨好时，引导其区分“关心”和“照顾/拯救”，写下自己愿意做与不愿意做的范围，再用尊重但清晰的语言表达。真实比表面和谐更重要，因为一个人若能在原生家庭的强情绪场中保持稳定，通常也更能在伴侣、亲子和职场关系中保持成人姿态。这也能帮助父母端用户：孩子独立不是对爱的否定，父母需要管理自己的失落和担忧，而不是用建议、金钱或内疚维持控制。成熟的亲子关系会从“谁听谁的”转向“两个成年人如何相互尊重”。它也承认某些家庭需要安全距离；成熟的重点是清醒选择，而不是被恐惧或义务自动推动。', '["离家独立", "成年亲子", "原生家庭", "真实表达", "情感联结", "责任范围", "边界", "自主"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 266, now()),
(100267, '单身期是内在安定训练场，而不是等待被拯救的空档', '单身并不等于缺少关系价值，它提供了练习自我安定、责任和方向感的窗口。若一个人把恋爱、社交媒体、购物、酒精、暧昧或被关注感当作主要镇静剂，亲密关系就会掩盖尚未发展的内在能力：独处时无法放松，焦虑时必须有人回应，人生选择被“是否有人爱我”左右。更成熟的单身期，是学习用自己的身体和理性资源管理不确定：呼吸、运动、规律作息、财务整理、职业探索、友谊经营、价值澄清，以及区分已知风险和未知恐惧。App 可将“扫描—诊断—解决”的焦虑循环转化为觉察工具：我是在处理已经发生的问题，还是在寻找未来灾难的证据？我现在想联系某个人，是为了真实交流，还是为了让自己立刻安心？这一条也适用于离婚、丧偶、空窗期和关系冷静期。单身阶段的目标不是变得不需要任何人，而是在进入亲密关系前，先不把自己的稳定完全外包给别人。它也能减少对单身用户的隐性羞辱：单身不是失败状态，而是一个可主动使用的发展阶段。若用户渴望关系，可把重点放在“我想带着怎样的自己进入关系”，而不是“谁能让我不再焦虑”。这样的表达能同时支持渴望亲密和练习独立，避免把二者对立起来。', '["单身成长", "自我安定", "焦虑管理", "亲密依赖", "内在资源", "关系选择", "自我负责", "价值澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 267, now()),
(100268, '伴侣关系的成熟悖论：少改造关系，多承担自己的部分', '很多伴侣以为关系改善的关键是“让对方终于明白”。但亲密关系里最有转化力的起点，往往是停止把全部精力放在伴侣身上，转而整理自己在循环里的贡献。常见弯路有三条：冲突与疏远的舞蹈，用争吵获得联结、再用冷淡获得距离；跷跷板模式，一方过度掌控，另一方逐渐无力；三角关系，把孩子、父母、朋友或外遇卷进两人的紧张中。成熟不是忍耐一切，也不是强势纠正，而是能说“我累了，需要十五分钟恢复，之后我来处理厨房”，能减少替对方做决定，能不让孩子成为夫妻矛盾的缓冲垫。App 可在伴侣冲突后引导用户识别：我是在攻击、退缩、支配、迁就，还是求第三方站队？我下一步能承担哪一个具体责任？当一方稳定地改变自己的反应，关系环境就会改变，另一方也会被迫重新调整。亲密不是没有差异，而是两个不完美的人都愿意在差异中更负责任地做自己。这条不意味着把关系问题都归给自己，也不要求留在伤害性关系中。它强调在安全前提下寻找自己的可行动点：停止升级冲突、明确分工、减少讽刺、按时回来沟通、直接提出需要。成熟改变通常细小、重复、可观察。因此，后台知识可优先生成“我能做什么”的句式，而不是“如何让对方改变”的控制脚本。', '["伴侣关系", "婚姻成长", "冲突循环", "跷跷板模式", "三角关系", "责任分担", "亲密与自主", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 268, now()),
(100269, '成长型助人：陪伴痛苦，但不接管对方的人生功能', '无效帮助常披着善意外衣：急着给建议、替对方分析所有人、站在 TA 这边批评不在场的人、帮 TA 消除痛苦，或把自己变成修复者。短期内，这会让受助者感到被理解，也让助人者感到重要；长期看，却可能加深依赖、制造三角关系，并剥夺对方练习解决问题的机会。成长型助人的关键，是既不逃避痛苦，也不过度接管。助人者可以稳定陪伴、认真倾听、询问过程，而不是急于下结论：问题从什么时候开始？涉及谁？你当时怎么回应？对方又怎么回应？哪些做法短期有用、长期无用？你能负责的下一步是什么？这种“研究者立场”能帮助对方从抱怨内容转向关系模式，看到自己可行动的位置。App 端可用于咨询师提示、朋友倾诉、父母支持孩子、管理者带团队：真正的支持不是让对方永远需要你，而是尊重其能力，留出空间，让对方在关系中恢复思考、选择和承担。对普通用户，它也能修正“我必须给出答案才算有用”的压力。很多时候，稳定地在场、问好问题、相信对方有能力，比立刻提供方案更有帮助。助人者若感到疲惫或怨恨，常是已经越过了自己的功能边界。这能保护双方：受助者保有主体性，助人者也不把价值感绑在拯救成功上。', '["助人者", "咨询关系", "不过度帮助", "依赖", "倾听", "研究者立场", "关系模式", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 269, now()),
(100270, '习惯是神经路径：重复会保存我们的反应方式', '詹姆斯把习惯理解为可塑性留下的路径：水流反复经过会加深沟渠，纸折过一次再折更容易，神经系统也会因重复而更容易走旧路。对自我发展而言，这意味着“我就是这样的人”常常不是本质判决，而是长期重复后的省力路径。抱怨、拖延、讨好、睡前刷手机、冲突时沉默或爆发，都可能因一次次被使用而变得自动；同时，运动、写情绪记录、暂停十分钟、清楚表达请求，也能因重复而变得省力。App 可把此条转化为温和但有力量的提示：每一次反应都在训练下一次更容易发生的自己。改变不是靠一次顿悟，而是通过新的微小通道反复被使用，逐渐让旧通道阻力变大、新通道阻力变小。它也提醒用户不要轻视“偶尔一次”：在脆弱时重走旧路会强化旧模式，而在小事上练习新回应，会给重大压力时的自己预先铺路。这条可作为复盘语言，帮助用户从羞耻中出来：旧习惯之所以强，不是因为你坏，而是因为它被训练得太熟；新习惯之所以难，也不是因为你没救，而是因为路径还浅。把改变看作铺路，会比把改变看作意志审判更可持续。因此，知识库应把“下一次更容易”作为习惯反馈的核心语言。而且越早练习越省力。', '["习惯", "神经可塑性", "行为改变", "自动反应", "微行动", "情绪调节", "自我训练", "复发预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 270, now()),
(100271, '改变习惯的四个抓手：强开端、不断链、立刻行动、每日小训练', '关于习惯改变，詹姆斯给出一组非常适合应用化的原则。第一，新习惯开始时要让动机尽量强：安排环境、公开承诺、减少诱惑，让第一步有足够推力。第二，在新习惯稳固前不要轻易重返旧习惯；每一次“破例”都像把卷好的线球松开，会削弱之前积累的神经优势。第三，决心必须尽快落到行动，否则情绪和愿望只在内心消散，反而训练出“想很多但不做”的习惯。第四，每天在小事上练一点自我管理：做一件不太想做但有益的事，拒绝一个不必要的冲动，保持一次专注。它们像给未来的压力买保险。App 可把这四点设计成习惯卡：今天的承诺是什么？我如何让环境支持它？我是否避免了最小破例？我有没有在 2 分钟内做出实际动作？这种方法不鼓励苛责，而强调连续、可执行和及时反馈。长期来看，性格不是空洞标签，而是被无数小行动塑造出来的行动倾向。当用户失败时，也可以用这四点定位问题：是开端动机不够强，环境仍在诱发旧习惯，还是决心没有转化为动作？修正设计比责骂自己更重要。所谓自律，是把有益行动训练到不必每天重新谈判。这也适合做成复盘模板，而不是只做打卡提醒。', '["习惯改变", "行为设计", "承诺", "不断链", "立即行动", "自律", "小训练", "行动倾向"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 271, now()),
(100272, '注意力选择塑造经验：发生过不等于真正进入生命', '詹姆斯强调，经验并不是外界原样进入心灵；感官和注意力会不断选择、强调、排除。一个事物可能出现一千次，如果从未被注意，它就很难成为个人经验；同一趟旅行，不同人会记住风景、价格、社交活动或自己的情绪，因为他们的兴趣不同。对心理成长而言，这能解释为什么一个长期关注威胁的人会觉得世界充满危险，一个总扫描缺点的人会在关系里不断找到证据，一个练习感恩和资源觉察的人更容易看见支持。App 可将此条用于焦虑、抑郁和关系误读：不是要求用户“积极思考”，而是邀请其检查注意力的取样方式。今天我自动寻找了什么证据？有没有被我忽略但同样真实的线索？我是否把单一刺激提升成了全部现实？注意力不是单纯的聚焦工具，它会参与建构用户的世界。训练注意力，就是训练一个人能从同一处现实中看见更多维度，从而拥有更多行动选择。这也解释了为什么同一段关系中，双方会拥有不同“事实感”。他们并非必然有人撒谎，而是注意力长期选择了不同线索。沟通时若能交换“我注意到了什么、我忽略了什么”，就比争夺唯一真相更容易靠近彼此。因此，注意力训练本质上也是关系训练和情绪训练。', '["注意力", "选择性知觉", "经验建构", "焦虑", "认知偏差", "资源觉察", "关系误读", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 272, now()),
(100273, '意识流：当下体验不是固定事实，而是不断变化的整体', '“我现在就是这样想的”并不等于一个永恒事实。詹姆斯反对把意识切成一个个静止颗粒，指出思想更像连续流动的河：同一对象在不同时间、身体状态、情绪背景和过往经验中，会被体验为不同的东西。困倦、饥饿、疲惫、低落、刚经历冲突或刚获得支持，都会改变我们对同一句话、同一个人、同一件事的感受。对 App 来说，这一条可用于降低情绪结论的绝对性：当用户说“我彻底完了”“TA 一定不在乎我”“我永远做不到”时，可以提醒这可能是此刻意识流中的高峰，而不是最终判决。更有效的提问是：此刻的身体状态是什么？这个想法带着哪些刚刚发生的背景？如果睡一觉、吃点东西、和可信的人聊过，再看它会不会不同？意识流也意味着改变有入口：不是强行否认感受，而是承认感受会流动，并通过休息、行动、书写、对话和环境改变，为下一段意识提供不同条件。它还适合危机降温：先不急着解决人生，只处理这一段意识流的条件。喝水、离开刺激源、放慢呼吸、写下想法、延迟重大决定，都是给下一段体验创造不同入口。等浪头过去，再讨论价值、边界和行动。这能把用户从绝对化判断中带回可观察的当下。', '["意识流", "情绪流动", "认知解离", "情绪管理", "身体状态", "自我观察", "危机降温", "心理弹性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 273, now()),
(100274, '情绪评分先行：先把低落从一团雾变成可追踪数据', '伯恩斯的认知疗法入口不是立刻讲大道理，而是先把情绪变成可观察数据。App 端可引导用户用 0-100 分记录低落、焦虑、愤怒、羞耻、内疚、无望等强度，并标注过去几天的变化、睡眠、活动、社交和压力事件。这样做有三个价值：第一，用户会发现情绪不是永久身份，而是会波动的状态；第二，后续练习能比较前后分数，避免只凭“我还是很糟”否定进步；第三，当分数长期很高、出现明显功能受损或危机信号时，系统能把自助建议升级为更稳妥的支持路径。评分不是诊断，而是让 App 回答从泛泛安慰转为“当前强度—触发因素—可做小步骤—复盘效果”的闭环。', '["伯恩斯", "情绪评分", "认知疗法", "自我监测", "情绪管理", "低落", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 274, now()),
(100275, '感觉不是事实：先找自动想法，再处理情绪', '当用户说“我感觉自己没价值”“我感觉对方一定讨厌我”时，App 不应直接把感觉当事实，也不应粗暴否定。更好的处理是把“感觉—想法—事实”拆开：我现在的身体和情绪感觉是什么；脑中自动冒出的句子是什么；可观察事实支持什么；有哪些事实并不支持；如果朋友遇到同样处境，我会怎样解释。伯恩斯反复强调，情绪常由我们对事件的解释触发，改变解释不是装作没事，而是把“我感觉如此”改写成“我正在产生一个想法，它需要证据检验”。这能帮助用户从被情绪裹挟，转向拥有一点观察距离。', '["自动想法", "感觉不是事实", "认知重评", "事实核对", "情绪调节", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 275, now()),
(100276, '十类认知扭曲：把“我完了”拆成可检验偏差', '强烈低落时，用户的语言常会出现固定偏差：非黑即白、以偏概全、心理过滤、否定积极、跳结论、放大缩小、情绪化推理、应该化、贴标签、个人化。App 可以把这些作为识别模板，而不是评判用户“想错了”。例如“我一次失败，所以我永远不行”包含以偏概全；“对方没回消息，所以一定不在乎我”包含读心和跳结论；“我必须让所有人满意”包含应该化。提炼的方向是：先标出偏差类型，再问证据、反例、替代解释和下一步实验。认知扭曲清单的价值在于降低羞耻：问题不是“我这个人坏”，而是“我的大脑在压力下用了过度简化的解释”。', '["认知扭曲", "非黑即白", "以偏概全", "读心", "贴标签", "个人化", "认知疗法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 276, now()),
(100277, '消极思维日志：把脑内缠斗搬到纸上处理', '消极念头在脑内转动时会显得很有力量，因为它们速度快、彼此勾连、带着情绪。伯恩斯建议把它写下来：触发事件是什么；自动想法原句是什么；对应情绪强度多少；这句话包含哪些认知扭曲；更平衡的回应是什么；重新评分后情绪是否下降。App 可把它做成问答模板，尤其适合反复自责、拖延、社交挫败、关系误读。关键要求是写“原句”，不要只写概括；回应也不能强行积极，而要可相信、可检验、可行动。这样用户不再和一团情绪搏斗，而是在纸面上逐条拆解：哪些是事实，哪些是推断，哪些是旧信念。', '["消极思维日志", "自动想法", "认知扭曲", "理性回应", "情绪记录", "书写练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 277, now()),
(100278, '每日活动计划：低动力时先恢复掌控与休闲比例', '低落和无力会让人等待“有心情再行动”，但长期等待会让生活越来越窄。每日活动计划把一天按小时拆开，先写目标，晚上写实际结果，并给每项活动标注掌控感 M 与愉悦感 P。它的重点不是逼用户完美执行，而是恢复两类体验：我还能完成一点事；我仍可以安排一点滋养。App 可建议用户先安排极小任务，如起床、洗漱、下楼、整理桌面、给朋友发一条消息，同时加入休闲和恢复，而不是把计划表变成新的自责工具。复盘时看趋势：哪些活动略微提升分数，哪些过度消耗，明天如何调整。', '["行为激活", "每日活动计划", "掌控感", "愉悦感", "低动力", "抑郁自助", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 278, now()),
(100279, '反拖延表：用预测—行动—实测打破“太难没用”', '拖延常被两种预测喂养：任务会很难；做了也没满足感。反拖延表要求用户先把任务拆成 15 分钟以内的小步骤，再分别预测难度和满足程度，完成后记录实际难度和实际满足程度。很多人会发现，大脑在开始前高估痛苦、低估回报。App 可把这个模型用于求职、学习、整理、沟通准备和健康行动：不是问“你为什么这么懒”，而是问“你预测它有多难？先做哪一步？做完实际多少分？”当数据反复证明预测不准，行动阻力会下降，自信来自证据而不是鸡血。', '["拖延", "反拖延表", "行为实验", "任务拆分", "难度预测", "满足感", "行动启动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 279, now()),
(100280, '快乐预测表：用实验松动“独处一定痛苦”', '许多关系低谷中的用户会相信：一个人做什么都没有意义，只有被爱、被陪伴、被关注才会快乐。快乐预测表把这个信念变成实验：列出可能带来成就感或愉悦的活动，标注独自完成或与他人完成，先预测快乐分数，做完后记录实际分数。它不是鼓励孤立，而是帮助用户发现快乐来源不只依附于某个人。App 可在失恋、孤独、周末低落、依赖关系中使用：安排 2-3 周小实验，比较独处和共处的真实体验，再据此规划生活。这样自尊会从“对方有没有选择我”逐步转向“我能不能照顾自己的生活”。', '["快乐预测表", "独处", "依赖", "行为实验", "自我照顾", "失恋修复", "愉悦感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 280, now()),
(100281, '语言柔道：面对自我批评，先移情再反馈协商', '伯恩斯把应对批评比作“语言柔道”：不硬碰硬反击，也不全盘吞下。App 可把它转成三步：第一，移情，先准确复述批评里可能合理的部分，让对方感觉被听见；第二，反馈，说出自己的事实、感受和边界；第三，协商，提出下一步如何修正、核对或合作。这个结构同样可用于自我批评：当内在声音说“你真没用”，先承认“我确实没完成这件事”，再反馈“这不等于我整个人没价值”，最后协商“下一步只做 10 分钟”。它能把羞耻和防御，转为具体修复。', '["语言柔道", "批评应对", "移情", "反馈", "协商", "自我批评", "冲突修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 281, now()),
(100282, '愤怒规则重写：减少“应该”，才能降温关系冲突', '愤怒常来自内心规则被违反，例如“对方应该立刻理解我”“我付出就必须被同等回报”“家人就应该按我的方式爱我”。这些规则有时听起来合理，却会把关系变成高压控制。伯恩斯建议冷却愤怒想法、重写规则、减少“应该”，把绝对命令改成现实期待：我希望对方这样做；我可以清楚请求；对方不配合时我仍能保护自己；改变自己反应通常比控制他人更可行。App 可在伴侣、亲子、职场冲突中引导：这条规则是否现实？是否可协商？如果对方不满足，我能做什么边界行动，而不是只靠怒火施压？', '["愤怒管理", "应该化", "规则重写", "边界", "关系冲突", "认知重评", "谈判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 282, now()),
(100283, '明智控制：少惩罚，多奖励可观察的合作行为', '在关系里，人们常用冷战、指责、讽刺、撤回亲密来“让对方改变”，但惩罚容易制造怨恨和防御。伯恩斯引用行为改变思路，强调用可观察记录和奖励机制影响互动：先确定自己真正想增加的行为，例如主动沟通、按时分担、尊重边界；再在对方出现目标行为时给予明确肯定；对破坏性行为减少奖赏、保持边界，而不是升级惩罚。App 应避免把这写成操控技巧，而要强调合作、透明和自我负责：我能改变的是自己的反馈模式，不能保证控制对方。关系改变要看数据：目标行为频率是否增加，双方是否更愿意协商。', '["行为强化", "关系改变", "奖励机制", "冲突降温", "合作", "边界", "反馈回路"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 283, now()),
(100284, '垂直箭头法：从表层想法挖到真正卡住人的隐性假设', '表层想法常只是入口，例如“这次没做好”。垂直箭头法继续追问：如果这是真的，为什么那么糟？它说明我是什么样的人？我最怕出现什么后果？连续追问后，隐藏信念会浮现，如“我必须完美才有价值”“别人不认可我就说明我不值得爱”“失败一次就没有未来”。App 可用这种方法做深层概念化：不要急着安慰表层事件，而是找出反复制造痛苦的假设。找到后再做两件事：评估这个假设的代价与功能；设计一个更灵活的新信念和小实验。这样用户处理的不只是一次情绪，而是长期脚本。', '["垂直箭头法", "隐性假设", "核心信念", "自我价值", "认知疗法", "深层信念"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 284, now()),
(100285, '认同上瘾：把自尊从别人评价里慢慢收回来', '认同需求本身正常，但当用户必须持续获得赞同才觉得安全，就会形成“认同上瘾”：一个眼神、一句批评、一次拒绝就足以摧毁情绪。伯恩斯提醒，别人的评价只有在用户自己先相信时，才会真正定义自我价值。App 可帮助用户区分三层：别人说了什么；这句话是否有事实依据；我是否把它上升成“我整个人没价值”。练习方向不是变得不需要任何人，而是发展独立自尊：可以听取反馈、修正行为，同时不把人格价值交给他人投票。对讨好、回避冲突、关系依赖的用户，这是一条关键成长线。', '["认同上瘾", "自尊", "他人评价", "讨好", "独立自尊", "关系依赖", "批评应对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 285, now()),
(100286, '工作不等于价值：把自尊从单一成就指标中解套', '许多用户把工作、收入、头衔、效率和社会认可等同于个人价值，因此一旦失业、被批评、晋升失败或产能下降，就会迅速陷入羞耻。伯恩斯把“工作是否等于价值”单独成章，适合提炼为 App 知识：成就是重要生活领域，但不是价值的全部来源。用户可以建立四类支点：稳定行为，如守信、学习、照顾身体；关系贡献，如真诚、支持、边界；内在品质，如好奇、勇气、善意；成长过程，如从错误中修正。这样工作挫败仍然痛，但不会直接导向“我这个人失败”。App 回答时要把职业复盘和人格价值分开。', '["自尊", "工作价值", "成就焦虑", "职业挫败", "羞耻", "价值澄清", "人格价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 286, now()),
(100287, '完美主义处理：允许平凡，减少非此即彼的自我评价', '完美主义表面上追求高标准，内核常是恐惧：只要不完美就没有价值。它会让用户拖延、过度准备、害怕暴露、无法享受成果，也会把普通错误解释成失败人格。伯恩斯的处理方向不是劝用户“随便做”，而是把标准改成现实、渐进、可修正：给任务设最低可交付版本；把错误当数据；允许 70 分先行动；用“进步、学习、影响”替代“完美、证明、赢”。App 可提醒用户识别非此即彼语言：必须、永远、彻底、完蛋、毫无意义。成熟的高标准应服务生活，而不是把人困在自责和停滞中。', '["完美主义", "非黑即白", "行动启动", "自责", "高标准", "自我接纳", "拖延"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 287, now()),
(100288, '绝望时的保护流程：先评估冲动，再扩大连接与时间窗口', '当用户表达“活不下去”“没有意义”“想消失”时，App 不能只做认知重评，应先进入保护流程。伯恩斯在绝望章节中把“选择活下来”和评估冲动作为单独主题。可迁移为四步：第一，询问冲动强度、计划具体性、可获得手段和是否独处；第二，立刻扩大连接，联系可信任的人、专业支持或当地紧急资源；第三，把时间窗口缩短到“先安全度过接下来 10 分钟/1 小时/今晚”；第四，再处理绝望想法，如“痛苦会永远持续”“没有任何人能帮我”“我只会拖累别人”。危机知识库的重点不是替代专业干预，而是让 App 在高风险信号下优先稳定、连接和升级。', '["危机支持", "绝望", "自杀冲动评估", "安全计划", "连接支持", "认知疗法", "情绪急救"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 288, now()),
(100289, '谈判前先画局势地图：目标、底线、路径与预案', '核心意思：重要沟通不要从“我要怎么说”开始，而要先把局势画成一张可执行地图。先确认自己究竟要达成什么结果：是拿到信息、建立信任、争取资源、确认合作，还是决定退出；再写清楚成功标准、时间节点、可让步范围和不可突破的底线。
使用方法：1）列出现状、目标状态、关键利益相关方与决策链条；2）区分核心利益、可交换条件、情绪诉求和表面立场；3）标出信息缺口，例如对方真实预算、风险顾虑、授权边界、时间压力；4）预设 A 路径与 B 方案，包含关键节点、可能阻力、第一步动作、责任人和复盘时间；5）提前设计退出机制，避免在现场被情绪或沉没成本绑架。
App 端可做成“沟通前卡片”：我想要的结果是什么？最低可接受结果是什么？哪些信息必须确认？如果对方拒绝，我的替代方案是什么？这张卡片会把模糊焦虑转成可检查项目。边界提醒：规划不是为了控制别人，也不是追求百分百确定。它的作用是在信息不完整时减少误判，让你知道哪些地方可以灵活，哪些地方必须守住。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["谈判准备", "信息结构", "目标设定", "底线", "风险预案", "决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 289, now()),
(100290, '开合节奏：该透露的信息先开，该保护的底线及时合', '核心意思：有效沟通不是“全说”或“不说”，而是管理信息释放的节奏。“开”是释放足够信息，让对方愿意表达、愿意合作；“合”是收束边界，把讨论聚焦到当前最重要的问题，避免过早暴露底牌或让话题失控。
使用方法：开局时先释放低风险信息，例如自己的基本关注点、合作意愿、可讨论范围，常用句式是“我想先了解你的真实关注点”“我们先确认彼此期待”。观察对方反应后，再决定是否深入。收束时把范围限定到少数核心议题，例如“先把讨论聚焦在预算和交付两个问题上”“具体条款我们内部评估后再确认”。
判断标准：如果对方愿意补充细节、提出条件或追问下一步，可以适度继续“开”；如果对方开始回避、泛泛表态或情绪紧绷，要及时“合”，减少信息密度并确认边界。适用场景包括会议发言、商务谈判、新关系建立、亲密关系中的边界协商。边界提醒：开合不是故弄玄虚，也不是诱导对方入套，而是在透明与谨慎之间找到合适比例，让信息流动服务于共同判断。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["沟通节奏", "信息释放", "边界", "谈判开局", "职场沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 290, now()),
(100291, '留白观察：用反应窗口获得比追问更多的信息', '核心意思：很多关键信息不是从对方的答案里直接出现，而是出现在停顿、补充、回避、反问、情绪变化和回应速度里。留白不是被动沉默，而是有目标地创造观察窗口：先看对方怎么动，再决定自己怎么回应。
使用方法：1）提出轻量问题后暂停，不急着解释或补充；2）观察回应速度、语气、用词、表情、身体姿态，以及对方是否主动追问细节；3）把反应分为三类：真实兴趣（主动追问、提出具体场景、分享经验）、礼貌回应（泛泛认可但不深入）、隐性抗拒（长时间沉默、转移话题、顾虑过多）；4）根据状态调整：积极就推进，谨慎就降低压力，抗拒就暂时撤退。
练习方式：在一次重要对话里，刻意把自己的第一反应延后 2-3 秒，记录对方是否补充新信息。复盘时不要只看“说了什么”，还要看“什么时候说、用什么语气说、说完后是否继续投入”。边界提醒：留白必须有时间限度和判断目标，不能变成冷处理。它的价值是帮助你降低误判，而不是用沉默惩罚对方。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["倾听", "观察反馈", "提问", "低压力沟通", "情绪信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 291, now()),
(100292, '轻问题试探：把“我再考虑”拆成可验证的真实顾虑', '核心意思：对方说“我再考虑一下”时，不要立刻理解为拒绝，也不要继续硬推。它可能代表价格阻碍、风险担忧、信任不足、授权不够或决策链条未清。更稳妥的做法是把模糊话语拆成几个可验证假设，再用轻问题逐一测试。
使用方法：先记录对方的具体用词、停顿、语气和反复提到的主题；再提出假设性问题降低压力，例如“如果预算控制在这个范围，哪个环节你最担心？”“假设我们先从小项目开始，你们团队配合度如何？”“如果时间调整到 X，你的接受度会怎样？”观察对方是给出具体顾虑、继续回避，还是开始谈条件。
判断线索：反复谈预算，多半是价格或价值感问题；询问保障、失败案例和试用，多半是风险顾虑；要求资质、客户反馈或更高层背书，常与信任不足有关。边界提醒：试探不是审问，不连续追问同一话题，不触碰隐私底线，也不把获得的信息用于要挟。好的试探是轻触即止：得到足够信号后及时收束，再决定推进、降压或退出。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["提问", "意图识别", "顾虑验证", "谈判中场", "低成本试探"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 292, now()),
(100293, '从意向到承诺：把模糊好感锁定为下一步行动', '核心意思：沟通推进的关键不是让对方说“不错”“可以考虑”，而是把模糊意向转化为可执行动作。真正的推进包含五个台阶：初步认可、价值确认、明确承诺、条件锁定、实际动作。每一步都需要验证对方真实状态，不能跳级催促。
使用方法：先确认共识：“我理解你的核心关注是 X 和 Y，我们在这个方向上一致吗？”再锁定下一步：“具体来说，下一个动作是什么？谁负责？”最后给时间锚：“我们什么时候再确认进展？如果遇到阻碍如何调整？”在项目、合同、关系升级中，都要把“以后聊”“原则上同意”改写成“下周三前给答复”“周五确认条款”“每月固定复盘”。
App 端可以提示用户把每次对话后的成果写成三行：已达成的共识、下一步行动、复盘时间。若三行写不出来，说明只是情绪上变近了，尚未形成行动承诺。边界提醒：推进不是逼定。只有在信任基础、价值交换和风险说明足够时，行动承诺才稳定。若对方仍有核心顾虑，先回到验证和消除风险，而不是施压。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["承诺", "行动锚点", "推进节奏", "关系协商", "时间节点"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 293, now()),
(100294, '价值交换与影响力：先证明真实价值，再谈深度绑定', '核心意思：稳定影响力来自真实价值交换，而不是控制、讨好或制造依赖。先让对方看见你能解决什么具体问题，再通过持续兑现价值建立信任，最后才谈长期合作、资源投入或更深层关系绑定。
使用方法：先做吸引点自查：我的核心价值是什么？我能为对方解决什么具体问题？对方现在最需要什么？我的资源、专业、经验或性格优势是否能精准匹配？随后检查关系升级条件：对方是否主动回应、是否认可价值、是否愿意投入时间或资源、是否出现共同成长的可能。团队领导、商业伙伴、内容获客、亲密关系都适用。
阶段判断：价值吸引解决“为什么要接近你”，情绪连接解决“跟你合作是否舒服”，利益绑定解决“双方是否都愿意投入”，深度影响解决“能否持续共创”。任何阶段都不能倒置。边界提醒：对方应当随时可以选择离开。健康绑定建立在互惠、共同目标和自主选择上；如果靠恐惧、不安全感、单方面索取或信息不对称让对方留下，这不是影响力，而是关系风险。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["利益交换", "影响力", "互惠", "合作关系", "价值匹配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 294, now()),
(100295, '关系筛选与退出：用结构匹配替代情绪判断', '核心意思：合作关系、职场关系和亲密关系都不能只看一时好感，也不能因为已经投入就无限坚持。更可靠的判断标准是结构匹配：价值观、节奏、利益、沟通方式和风险承受能力是否长期兼容。
使用方法：用五维检查表复盘：1）价值观是否一致，成功定义是否接近；2）决策速度、沟通频率、执行风格是否同步；3）短期目标和长期愿景是否能共赢；4）表达方式、反馈接受度、冲突处理风格是否舒适；5）风险承担意愿和止损边界是否清晰。三个维度以上长期不匹配，可视为结构性不合；两个维度不匹配，先尝试协商；一个维度不适，继续观察。
退出前做三项验证：问题是否持续足够久、双方是否尝试调整、继续投入的代价是否超过收益。这样可以避免一次争吵后的情绪化退出，也避免完美主义式筛选。边界提醒：退出时保持尊重和边界，说明事实、影响和决定，不把离开包装成惩罚，为未来可能的重新合作留下空间。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["关系协商", "合作筛选", "退出机制", "匹配度", "沉没成本"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 295, now()),
(100296, '局势变化时的策略重构：目标固定，路径灵活', '核心意思：沟通和谈判常常不是线性推进，而是在新信息、新角色、新压力下不断变化。成熟的应对不是固守原方案，也不是随风倒，而是在核心目标和底线不变的前提下，重新评估局势并调整路径。
使用方法：先识别“裂缝”：信息不对称、时间节奏错位、信任破损、利益分配失衡、资源配置矛盾、关键人员态度转向。再问三件事：变的是什么？外部环境、内部资源、目标优先级还是关系角色；为什么原策略不再适用？是执行不到位，还是假设条件已改变；什么必须改，什么可以保持？核心原则不变，具体策略、信息颗粒度和推进节奏可以调整。
行动上，可以先做小幅微调；若关键假设已失效，就重设路径、资源和时间窗口；若窗口正在关闭，则进入决断。边界提醒：权变不是放弃原则，也不是机会主义。它的价值是提前看见结构性失衡，用建设性介入、风险预警和路径重构避免更大损失。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["权变", "局势判断", "风险识别", "策略调整", "谈判决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 296, now()),
(100297, '可信表达与说服：说服力来自事实、身份、时机和兑现能力', '核心意思：真正有力量的表达不靠华丽包装，而靠可验证事实、合适身份、恰当时机和可兑现承诺。说服不是把话说满，而是让对方相信这句话经得起检查，并且你能为后果负责。
使用方法：表达前做四维自检：1）事实是否真实，是否存在夸大、模糊或偷换概念；2）身份是否匹配，是否超出权限或关系阶段；3）时机是否合适，对方当前状态是否适合接收，会不会干扰既定节奏；4）可信度是否足够，对方会质疑什么，我能否提供证据、案例、数据或行动记录。商务承诺中宁可保守承诺、透明说明风险，再用稳定交付增加信用。
在职场汇报里，要让数据和结论一致；在公开表达里，只讲自己能承担的经验；在商务承诺里，让资源、时间和执行力匹配。边界提醒：言过其实的代价会从短期失去主导权，发展到中期透支信用、长期重建信任困难。可信表达也是冲突降温工具：先确认事实和责任，再表达态度，比急着辩解更有说服力。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["说服", "可信表达", "承诺管理", "事实核对", "信任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 297, now()),
(100298, '冲突降温：先收束范围，再回到共同问题', '核心意思：冲突升温时，最常见的错误是急着证明自己对，结果让对方更防御。更有效的顺序是：暂停输出，观察反应，收束议题，退回共同利益，再提出可讨论的小问题。这样既不逃避冲突，也不让冲突扩散成关系攻击。
使用方法：第一步，停顿并观察对方是沉默、抗拒、转移话题还是情绪上扬；第二步，把讨论范围从“你总是/你从来”收束到一个可处理事实，例如“我们先只看交付时间和职责分配”；第三步，用低压力提问寻找障碍：“这个安排里你最担心的是什么？”“如果先从小范围试行，阻力在哪里？”第四步，用共同目标承接：“我们都希望这件事能推进，所以先确认下一步。”
如果对方仍然抗拒，先降低信息密度，不继续追加论点；如果对方开始说出具体担忧，再共同设计一个小范围、可验证的调整。边界提醒：降温不是让步到底，也不是压抑真实需求。需要同时保留底线与尊重：不审问、不讽刺、不威胁，必要时暂停并约定回来继续谈。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["冲突降温", "共同利益", "边界", "提问", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 298, now()),
(100299, '观察是线索假设，不是读心或操控', '核心观点：人类行为观察的价值，不在于把某个表情、姿势或动作翻译成确定的内心答案，而在于把日常互动中的细节变成可检验的线索。书中导言把观察者比作实地考察者：车站、商店、机场、聚会和街道都是观察场，但观察的目的应是更深入地理解人与人的交往，而不是探知隐秘思想、控制他人。
使用方法：看到异常动作时，先记录事实，如“他说到这个话题时两次移开目光、手指反复摩擦杯沿”，再生成低强度假设，如“可能紧张、犹豫或需要更多时间”，最后用开放式沟通核对：“这个话题是不是让你有点为难？”
边界提醒：单个动作只能提示可能性，不能作为人格、动机或道德判决。越是觉得自己“看穿了”，越要回到事实、情境和对方确认。真正成熟的观察会增加宽容：理解行为背后的处境与压力，而不是强化攻击、操控或贴标签。
App 落地：可做成“观察—假设—核对”三栏卡片。观察栏只填可拍摄、可复述的事实；假设栏最多列三种可能，不允许写“就是”；核对栏给出一句尊重式提问。这样用户既能提升敏感度，也不会把非语言知识用成审判工具。
限制提醒：若对方明确解释了原因，应优先尊重其自述；观察只能补充理解，不能替代当事人的说明。', '["行为观察", "避免读心", "事实解释分离", "核对沟通", "非语言线索", "观察伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 299, now()),
(100300, '先记录动作模式，再解释心理含义', '核心观点：人的动作并非杂乱无章，而是由大量重复的姿势、运动和事件片段构成。书中以“十指交叉时总是同一个拇指在上”为例说明，许多身体习惯稳定到本人也不自知。对 App 知识库来说，这意味着观察应从“模式”入手，而不是被一次偶发动作牵着走。
操作框架：第一步，只写可见事实：动作是什么、何时出现、持续多久、在谁面前出现。第二步，看基线：这个人平时是否也这样，还是只在某类话题、某类对象、某种压力下出现。第三步，看组合：语言内容、语气、身体方向、手脚动作和场景要求是否一致。第四步，再提出假设：这是习惯动作、礼貌动作、紧张释放，还是某种关系信号？
判断原则：一次皱眉不等于反感，一次沉默不等于冷暴力，一次热情也不等于真诚。长期、重复、跨场景仍稳定出现的模式，才比单点行为更值得讨论；即使如此，也仍需要与当事人核对。
App 落地：建议用户建立“同一个人、同一类情境、连续多次”的观察笔记，例如会议、约会、争执、沉默后修复。系统可提示用户比较平时基线与本次偏离：是偶发疲劳、环境限制，还是重复出现的互动模式。模式越稳定，假设才越值得拿出来讨论。', '["长期模式识别", "行为基线", "动作模式", "事实记录", "情境判断", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 300, now()),
(100301, '动作来源四分法：先天、发现、同化、训练与混合', '核心观点：同一个动作看起来像“性格”，实际可能来自不同来源。书中把动作来源区分为先天动作、个人发现动作、同化动作、有意训练动作，并强调成年人的许多动作是混合形成的。这个框架能帮助我们避免把文化差异、职业训练或个人习惯误解成动机。
观察应用：若某个动作在不同文化、不同年龄段都常见，可先把它当作可能的基础反应；若它与身体结构和个人习惯有关，如抱臂、站姿、手势偏向，则要看个人长期基线；若它在某个群体中特别常见，如同一地区的招呼方式、同一团队的表达习惯，可能是同化来的；若它只在特定职业或训练场景中出现，如舞台、服务、军队或仪式动作，则可能是被教出来的。
沟通提醒：不要问“你为什么用这个动作针对我”，可改为“我注意到你在这个场合会这样表达，这对你来说是习惯、礼貌，还是当时有别的感受？”这样既保留线索，又减少误判。
App 落地：可把每次观察后的解释拆成四个来源选项：身体自然反应、个人旧习惯、群体/文化学习、职业或礼仪训练。用户若无法判断，就选择“未知来源”。这个步骤能把“他故意这样”降级为“这个动作可能有多种形成路径”。', '["动作来源", "文化差异", "习得行为", "个人习惯", "情境与动机区分", "沟通核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 301, now()),
(100302, '姿势不是字典：同一动作会随文化、职业和场景变义', '核心观点：手势、点头、招呼和象征姿势不能当成固定词典。书中反复说明，区域信号会因地理和文化而变，技术姿势只在专业领域内有效，密码姿势则需要系统规则才有意义；同一姿势还可能在不同国家表达相反或无关的意思。
应用方式：当看到对方点头、摇头、挥手、比手势、抱臂或身体后撤时，先问三类背景：一是文化背景，这个动作在对方成长环境中是否有特殊含义；二是场景背景，它是礼仪、职业规范、社交习惯，还是当下情绪；三是互动背景，动作是否引发对方接近、远离、解释或修正。
避免误判：不要说“他抱臂就是防备”“她不看我就是撒谎”。更稳妥的表述是：“这个动作可能提示距离、思考或不适，但也可能只是习惯或文化表达；需要结合上下文，再用温和提问确认。”对跨文化沟通尤其要降低确定性。
App 落地：在手势和姿势内容旁加入“文化校准”提醒：这个动作在你的文化里可能代表 A，在对方文化里可能代表 B，也可能什么都不代表。系统可要求用户补充对方成长环境、职业场景和当时任务，再生成低确定性的沟通建议。
限制提醒：若没有共同文化背景，就把结论写成“我不确定这个动作代表什么”，再邀请对方解释。', '["手势解读", "跨文化沟通", "区域信号", "技术姿势", "避免绝对化", "情境线索"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 302, now()),
(100303, '目光线索：直视、移开与扫视要看节奏和关系任务', '核心观点：目光不是简单的“看=真诚、不看=心虚”。书中《视觉行为》指出，两个人相遇时会在想看与想移开之间保持微妙平衡；凝视可表示关注、亲密、威胁、支配，也可表示恐惧中的警觉；移开目光可表示服从、思考、回避压力或降低冲突。
观察维度：看方向——对方是看人、看物、看出口，还是看地面；看节奏——目光接触是自然来回、过短、过长，还是突然中断；看关系——上级、下属、陌生人、朋友、伴侣之间的目光规则不同；看话题——谈事实、谈情绪、谈请求时，目光负荷也不同。
沟通用法：若目光让你不安，不要直接指责“你不敢看我”。可以说：“我注意到说到这里时我们目光都变少了，我担心这个话题有压力，要不要放慢一点？”这样把目光当作互动温度计，而不是测谎仪。
App 落地：可设计“目光不适检查表”：我是否把对方的不看解释成否定？当时话题是否困难？对方是否在思考、羞怯、服从、害怕冲突或受文化规则影响？完成检查后再决定是继续谈、暂停，还是询问对方是否需要时间。
限制提醒：目光线索尤其受羞怯、神经多样性、权力距离和疲劳影响，不能单独用于判断诚实。', '["视觉行为", "目光接触", "沟通判断", "关系互动", "压力线索", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 303, now()),
(100304, '致意仪式：迎接、告别与身份变化的关系重置', '核心观点：问候、告别、祝贺和仪式性寒暄，不只是礼貌外壳，也是在标记关系状态。书中《致意表现》把“你好”“再见”、欢迎、告别、庆祝看作关系债务的偿还和关系秩序的重建：有人到来、离开，或社会地位发生变化时，人们会通过拥抱、握手、微笑、寒暄、祝贺等动作确认“我们如何相处”。
观察应用：关系中的不适有时发生在致意环节，而不是正文内容。比如对方进门时是否被看见，离开时是否被送别，成就是否被祝贺，失落是否被承认。过度简化的致意可能让人感觉被忽视，过度隆重的致意也可能带来压力。
沟通建议：不要仅凭问候热情判断真心。先看双方共同的礼仪期待，再看长期稳定性。如果感到被冷落，可表达影响：“刚才我进来时没有被回应，我有点失落；你当时是在忙，还是没注意到？”把仪式差异转成可讨论的关系需求。
App 落地：适合用于关系修复提醒。系统可提示用户回顾冲突并不只看争论内容，也看开头和结尾：有没有打招呼、有没有解释离开、有没有感谢、有没有在重要变化后重新确认关系。很多关系紧张来自仪式性承认缺失。
限制提醒：有些人因家庭、文化或社交焦虑不擅长仪式表达，关系判断应看后续行动是否稳定。', '["致意表现", "关系互动", "仪式感", "告别", "问候", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 304, now()),
(100305, '姿势对应：身体同步提示亲和或地位协调', '核心观点：当两个朋友地位相近、态度相似、互动顺畅时，他们常会无意识地出现姿势对应：相似坐姿、相似倾斜角度、相近点头节奏、同步的身体细微动作。书中把它视为友好交往中的自然身体表示，传递“我和你在同一边”的无声信息。
观察重点：同步要看是否自然、双方是否舒适、是否长期在类似关系中出现。朋友间的姿势对应常让人觉得“对劲”；治疗、咨询、服务或高难沟通中，适度降低姿态差异也可能带来安抚。但地位不对称时，机械模仿可能被体验为冒犯；下属过度复制上司的放松姿势，反而可能破坏关系边界。
使用边界：不要把同步当作“喜欢我”的铁证，也不要用刻意模仿操控亲和。更好的方式是校准对方节奏：若对方紧绷，先放慢语速、降低压迫感；若对方放松，再自然靠近。观察同步的目的，是判断互动是否安全，而不是制造假亲密。
App 落地：可在对话训练中把“同步”定义为跟随节奏而非复制动作。用户练习的是音量、距离、停顿、身体朝向的温和调整；一旦对方后撤、僵住或不自在，就停止靠近。同步的目标是降低威胁，不是让对方失去边界。
限制提醒：真正的同步通常轻微、自然、可退出；一旦需要用力维持，就应回到真实表达。', '["姿势对应", "身体同步", "亲和感", "地位关系", "沟通节奏", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 305, now()),
(100306, '关系符号：距离、并行、触摸和公开性构成互动证据', '核心观点：关系不是只靠语言声明，也会通过空间距离、同行方式、身体接近、挽手、拥抱、接吻、扶持、触摸部位和公开程度被他人读出。书中《关系符号》和《身体接触关系符号》提醒，旁观者会从细微动作判断两人是否有私人关系以及关系性质，但这些线索必须排除拥挤、礼仪、救助和临时任务。
观察框架：先看“是否自愿接近”——拥挤车厢里的近距离不等于亲密；再看“谁主动、谁回应”——单方面触摸与双方自然靠近不同；再看“部位和时长”——手、肩、背、头部的亲密等级不同；最后看“公开性”——私下与公开场合的动作可能承担不同关系声明。
沟通提醒：关系线索最容易被投射和误读。比起断言“你们关系不正常”，更稳妥的是表达事实与感受：“我看到你们在聚会上长时间挽手，我有些不安；这在你们之间代表什么？”让关系定义回到双方可确认的语言。
App 落地：对伴侣、亲子、同事场景都可做“关系符号复盘”：我看到了什么动作？这个动作在这个场景是否有礼仪或任务解释？对方是否愿意、放松、回应？我真正担心的关系需求是什么？最后再转成一句可验证的问题。', '["关系符号", "身体接触", "边界", "亲密关系", "事实解释分离", "公开性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 306, now()),
(100307, '非语言泄漏与矛盾信号：按可控性排序，而非直接定罪', '核心观点：当语言、表情、手脚、姿势和生理反应不一致时，确实可能出现非语言泄漏；但泄漏显示的是“内外不协调、压力或未说出的内容”，不等于必然撒谎。书中明确指出，摸鼻子、手对脸接触、手势减少等线索不能直接证明欺骗，只能提示有些东西无法顺畅表达。
判断方法：先区分两难信号和矛盾信号。两难信号可能来自真实混合情绪，如既想靠近又害怕；矛盾信号才更像外在表演与内在感受冲突。再按可控性排序：生理自发反应、腿脚和躯干动作通常比刻意语言和脸部表情更难控制，但也只是在强情绪时更有价值。
沟通用法：把“你在撒谎”改成“我听到你说没事，但你的手一直抓紧，看起来这件事可能有压力；你愿意多说一点吗？”这样既尊重线索，也给对方澄清、保留隐私或调整表达的空间。
App 落地：可作为“误判减速器”。当用户输入某个可疑动作时，系统先返回至少三个替代解释：压力、礼貌表演、混合情绪、认知负荷、隐私保护或文化差异。只有在长期一致、线索组合强、对方又拒绝澄清时，才提示用户关注边界和风险。
限制提醒：识别矛盾后先处理安全和信任，过早审问只会增加对方防御，使线索更混乱。', '["非语言泄漏", "矛盾信号", "测谎误区", "压力线索", "沟通判断", "事实核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 307, now()),
(100308, '短缺与过度信号：不自然强度常提示表演压力', '核心观点：有些非语言线索不是内容错，而是强度、时长或节奏不合适。书中把强度不足称为短缺信号，如闪电式微笑、凝固式微笑、过短目光接触；把强度过大称为过度信号，如笑得太久、动作太夸张、热情超过场景需要。两者都可能来自真实心境与社会表现之间的冲突。
观察维度：看强度是否匹配事件大小，看时间是否过短或拖长，看出现和消失是否自然，看是否只在特定对象或压力话题前后发生。还要排除文化风格：外露型文化本来动作更大，保守型文化本来表情更克制；跨文化互动中，短缺或过度可能只是彼此规则不同。
应用提醒：短缺和过度只提示“这里可能有表演、礼貌、紧张、困惑或文化差异”，不能直接推出恶意。适合的核对句是：“我感觉刚才这个回应有点勉强/用力，是不是这个场合让你难办？”把判断落在互动体验，而非人格指控。
App 落地：可帮助用户处理“感觉怪怪的”场景。系统让用户分别标注表情强度、持续时间、出现/消失速度、话题前后变化和文化背景，再给出“可能勉强、可能礼貌、可能不熟悉规则”的假设，而不是直接判定虚伪。
限制提醒：强度失配也可能来自紧张、笨拙或不熟练，不宜直接上升到人品评价。', '["短缺信号", "过度信号", "表演压力", "文化风格", "情绪识别", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 308, now()),
(100309, '领域、阻挡与防御：个人空间是安全感语言', '核心观点：人会把部落、家庭和个人空间当成需要防卫的领域，也会在压力中寻找屏障。书中《领域行为》讨论人对“自己的地方”的安全感，《阻挡信号》描述儿童躲在母亲或家具后、成人用桌子、杯子、包、手臂等建立缓冲；《防御行为》则呈现遇到危险时保护头部、躯干和脆弱部位的反应。
观察应用：对方后退、转身、把物品放在中间、抱紧身体、靠墙坐、选择能看见出口的位置，可能是在调节安全距离，而不是一定讨厌你。相反，突然闯入对方个人空间、堵住出口、隔着桌子逼问，都可能增加防御。
沟通建议：若对方出现阻挡或防御，先降低刺激：后退半步、放慢语速、给选择权、允许暂停。可说：“我注意到这个距离可能有点紧，我们可以坐远一点或晚点再谈。”尊重空间，往往比继续追问更能恢复关系安全。
App 落地：适合在高难沟通前做环境调整建议：不要堵门，不隔着屏幕逼问，不在公众场合追问私密问题；给对方水、座位、退路和暂停权。空间先安全，语言才更可能被听见。观察到阻挡时，优先降低压迫感。
限制提醒：对创伤、社交焦虑或高敏感者，空间线索可能更明显，沟通时更要给选择权。', '["领域行为", "个人空间", "阻挡信号", "防御行为", "安全感", "关系边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 309, now()),
(100310, '自发与瞳孔信号：生理唤醒只说明被触动，不等于动机', '核心观点：出汗、脸色变化、呼吸改变、瞳孔扩大或收缩等自发信号，受自发神经系统影响，通常比语言和脸部表情更难刻意控制。书中因此把它们放在较可信的位置；《瞳孔信号》还指出，在光线稳定时，瞳孔变化会随情绪刺激而变化，并且常在当事人无意识中影响互动。
使用边界：生理线索的可信，不等于含义单一。心跳加快可能是喜欢、害怕、羞耻、愤怒、兴奋、咖啡因、疲劳或环境热；瞳孔扩大可能来自兴趣，也可能来自光线、药物或一般唤醒。观察者只能说“身体被激活了”，不能直接翻译成“他喜欢我”或“她心虚”。
沟通建议：把生理观察用于自我调节和温和关心。对自己，可说“我现在身体被激活，需要暂停”；对他人，可说“我感觉这个话题让你有点紧绷，要不要喝水或休息一下？”生理信号最好服务于照顾和核对，而不是推断控制。
App 落地：可用于自我觉察而不是侦测他人。系统可提醒用户记录自己的身体唤醒：脸热、手汗、呼吸急、瞳孔或视野变化，然后问“我被什么触动了，需要安全、休息、靠近还是澄清？”对他人则只做关心式询问。
限制提醒：若涉及持续惊恐、失眠或强烈躯体不适，应把它视为需要照顾的身心信号。', '["自发信号", "瞳孔信号", "生理唤醒", "非语言线索", "避免读心", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 310, now()),
(100311, '身份、衣着与身体修饰：外观信号先问角色和场域', '核心观点：服装、发型、化妆、饰品、制服、随行人员和身体修饰都在传递社会信号。书中《身份显示》讨论权威如何通过外部形式呈现，《衣着信号》指出“穿上衣服而不发出社会信号是不可能的”，《身体修饰》则把化妆、发型、饰物、香水等视为地位、角色、性别、年龄、职业、游戏心态或群体归属的显示方式。
观察框架：先看场域——工作、约会、仪式、休闲和反叛场景对外观期待不同；再看角色——制服、礼服、低调穿着、刻意随便都可能在表达身份；再看变化——一个人突然改变穿着或修饰，可能是角色转换、关系需求、情绪状态、群体归属或审美尝试。
避免误判：外观不是人格判决。不要把“穿得随便”直接等于不尊重，也不要把“精心打扮”直接等于虚荣或勾引。更好的说法是：“我注意到你今天和以往风格不同，是有什么特别场合或心情吗？”让外观成为理解入口，而不是评价武器。
App 落地：适合用于减少外貌评价和标签化。系统可把“他穿成这样说明什么”改写为“这个外观可能在当前场域表达何种角色、归属或心情”。若涉及关系影响，再引导用户表达自己的感受与期待，而不是评价对方品味或道德。', '["身份显示", "衣着信号", "身体修饰", "角色表达", "社会信号", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 311, now()),
(100312, '社会直觉很快，但需要“事实—解释—行动”三步校准', '核心观点：迈尔斯反复提醒，社会直觉是人类在复杂环境中快速生存的工具，却不是天然可靠的裁判。我们会迅速判断一个人是否可信、一次拒绝是否代表讨厌、一段沉默是否意味着关系破裂；这些判断常常足够快，却会被过度自信、验证性偏见、可得性线索、情绪状态和信念固着放大。App 端不应简单告诉用户“别想太多”，而应帮助用户把直觉降级为假设。

使用方法：当用户说“TA 肯定不在乎我”“同事就是针对我”时，先让用户写下可观察事实：对方具体说了什么、做了什么、发生在什么情境。第二步列出至少三种解释：人格动机、情境压力、沟通误差、自己当前情绪。第三步再选择低风险行动：核对、等待更多信息、提出请求或调整边界。

沟通价值：这种做法保留直觉的提醒功能，也避免让直觉直接升级为攻击、冷战或自责。知识库可将其做成“事实不是解释，解释不是结论，结论先接受检验”的提示模板。尤其适用于亲密关系误读、职场冲突、社交焦虑、用户复盘重大决定。

落地提醒：这条适合做成误读急救流程。系统先承认直觉的保护意图，再邀请用户补证据；语气要像“我们一起核对”，而不是“你想错了”。', '["社会认知", "直觉判断", "认知偏见", "事实解释分离", "关系误读", "App问答模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 312, now()),
(100313, '归因三问：判断人格之前，先检查共同性、区别性和一致性', '核心观点：关系里的许多伤害，来自把对方的一次行为过快解释成人格缺陷。迈尔斯在归因章节中区分内部归因与情境归因，并介绍凯利的三个线索：共同性、区别性、一致性。一个人迟到，可能是“不重视我”，也可能是今天交通异常；一个孩子成绩下降，可能是动机问题，也可能是课程难度、老师互动、家庭压力共同作用。基本归因错误让我们高估人格、低估情境，尤其在生气或受伤时更明显。

App 可把归因三问做成冲突降温卡：第一，共同性：别人遇到同一情境也会这样吗？第二，区别性：TA 只在这件事上这样，还是所有场景都这样？第三，一致性：TA 是否长期重复同一模式？只有三个问题都指向稳定模式时，才更适合讨论边界和责任；若线索不足，先用核对式语言：“我注意到这次你没有回应，我脑中有个解释，但我想先了解发生了什么。”

应用边界：校准归因不是替伤害开脱，而是避免把可修复事件直接变成人格审判。对伴侣、亲子、上下级沟通来说，先查情境能减少羞辱和防御，让后续请求更具体。

落地提醒：当确有长期伤害模式时，归因三问的结论可以转向边界和保护；它不是让用户无限理解对方，而是让判断更有证据。', '["归因理论", "基本归因错误", "情境压力", "冲突降温", "沟通核对", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 313, now()),
(100314, '期望会制造互动现实：把预言改成可检验的邀请', '核心观点：迈尔斯把社会信念写得很有应用价值：我们不只是观察关系，也会用期待塑造关系。若我预期对方冷漠，我可能先退缩、语气变硬或减少解释；对方感到被排斥后真的冷淡，于是我的预期看似被证明。教师对学生的期待、伴侣对伴侣的解释、面试者对求职者的态度，都可能进入这种自我实现预言。

App 端可引导用户区分“预测”与“邀请”。预测式反应是：反正 TA 不会听，我也懒得说；邀请式反应是：我担心你可能不愿意听，但这件事对我重要，我想用十分钟讲清楚。预测把未来提前封死，邀请给对方一个不同反应的机会。

练习模板：写下我对 TA 的负面预期；写下我可能因此做出的防御动作；写下一个不牺牲边界、但能给关系创造新证据的小行动。比如从“他一定会否定我”改为“我先只说一个事实和一个请求，看他是否愿意回应”。

适用场景：关系复联、亲子期望、团队管理、用户担心被拒绝。知识库应强调：改变期待不是天真相信对方，而是减少由自己防御动作制造的坏结果。

落地提醒：系统可在用户准备放弃沟通前，生成一句低防御开场白，并要求只观察一次回应，不用立刻判定整段关系。', '["自我实现预言", "期待效应", "关系互动", "教师期望", "沟通邀请", "行为实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 314, now()),
(100315, '态度预测行为有条件：越具体、越自觉、越少外压，越可靠', '核心观点：用户常问“为什么我明明知道该沟通，还是逃避？”迈尔斯对态度与行为的总结能避免道德化指责：态度会影响行为，但只有在态度与行为足够具体、外部压力较小、个体能觉察自身态度时，预测力才更强。笼统地说“我重视健康”不一定能预测今晚是否运动；但“我认为饭后散步十分钟对我有帮助，并且我已经安排好时间”，就更接近行为。

App 落地：把“价值宣言”翻译成“具体态度”。不要只问用户“你想改善关系吗”，而要问：你是否愿意在今晚 21:00 前给对方发一句事实和请求？你认为这样做的好处、代价和阻碍是什么？如果用户行为不一致，也先查外部因素：是否太疲惫、害怕冲突、缺少脚本、环境诱惑太强，而不是直接贴上“不自律”。

咨询/成长价值：这条可用于习惯改变、亲密沟通、戒烟戒酒、学习计划和职场执行。它提醒知识库：改变不靠重复正确道理，而要让态度与场景、动作、时间和社会压力对齐。越是具体可执行，态度才越可能变成下一步行动。

落地提醒：如果用户连续失败，优先检查目标是否过于抽象、场景是否未安排、外部阻力是否被低估；修正设计比加强自责更有效。', '["态度与行为", "具体化目标", "行为设计", "自我觉察", "外部压力", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 315, now()),
(100316, '先做后信：小承诺、角色和不协调会悄悄改写自我', '核心观点：迈尔斯系统呈现了“行为也会塑造态度”。人会逐步相信自己公开说过、主动选择过、承担过责任的事。角色扮演会让最初陌生的身份变得自然；登门槛现象说明，一个自愿的小承诺会提高后续更大承诺的概率；认知不协调则解释了为什么当行为与原有信念冲突、且外在理由不足时，人会调整态度来减少心理紧张。

App 可双向使用这条知识。成长设计上，把改变做小：先表达一次感谢、先发一次清晰请求、先完成五分钟练习，让“我是能沟通/能行动的人”通过行为积累。防操控上，提醒用户识别小承诺链：免费试用、先签名、先答应一个无害请求、先公开表态，都可能让后续拒绝更难。

咨询提示：当用户说“我没有信心，所以做不到”，可温和改写为“信心有时来自做过一次”。但也要强调自愿和可选择性：被强迫的行为不易内化，反而激起抵抗。最适合的改变，是足够小、能主动选择、能看见积极后果，并与用户自己的价值一致。

落地提醒：知识库应同时提醒“微行动”与“微同意”的区别。前者服务用户价值，后者可能服务他人操控；关键看选择权和透明度。 并保留退出通道。', '["行为改变态度", "小承诺", "登门槛效应", "认知不协调", "角色扮演", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 316, now()),
(100317, '从众的两种力量：想被接纳，也想判断正确', '核心观点：从众并不只是软弱。迈尔斯把从众拆成顺从、服从和接纳，也区分了规范影响与信息影响。规范影响来自归属压力：人害怕被嘲笑、排斥、惩罚，于是公开附和。信息影响来自不确定：情境模糊、任务困难、自己没把握时，别人就像现实线索，我们更容易相信群体是对的。理解这两种力量，能让 App 帮用户从“我怎么这么没主见”的羞耻里出来。

使用方法：面对人情压力、团队意见、家庭催促或社交媒体风向时，先问两句：我是在怕被拒绝，还是在借别人判断事实？如果是规范压力，需要边界脚本和支持者；如果是信息压力，需要补充证据、咨询专业意见、延迟决定。公开回应会增强从众，事先承诺会增强独立，因此可在进入高压场景前写下底线：“如果被劝酒，我只说一次不喝，并把杯子换成水。”

沟通价值：这条不鼓励盲目反群体。成熟的独立是在重要价值上能站稳，也能在证据不足时向群体学习。App 可用于拒绝、消费决策、职场会议、亲友压力和网络舆论自保。

落地提醒：当用户需要拒绝群体压力时，先帮其找到至少一个现实或想象中的支持者。独立并不等于孤立，支持能降低规范压力。', '["从众", "规范影响", "信息影响", "顺从与接纳", "边界脚本", "社会压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 317, now()),
(100318, '说服双路径：重要决定走中心路线，日常诱惑常走外周线索', '核心观点：迈尔斯对说服的中心途径和外周途径特别适合做 App 决策提醒。中心途径发生在用户有动机、有能力认真思考时，重点看论据质量；外周途径发生在注意力不足或议题不重要时，人更受吸引力、权威感、熟悉度、情绪图像、群体热度等线索影响。很多营销、PUA 式沟通和冲动消费，并不是用更好的理由打动人，而是绕过深思。

App 可给用户一张“说服体检表”：第一，我是在看证据，还是被人设、颜值、专家头衔、恐惧画面带着走？第二，这件事对我重要吗？重要就延迟决定，主动找反方资料。第三，对方是否让我来不及想、来不及问、来不及比较？越急越要慢。第四，我是否已经公开承诺，因面子而难以退出？

态度免疫：迈尔斯还提到，温和预警和角色扮演能增强抵抗力。App 可让用户提前演练拒绝句：“我需要 24 小时考虑”“请把依据发给我”“我不在情绪强烈时下决定”。这样既能提升沟通清醒度，也避免把所有说服都妖魔化；好的说服应让人更理解事实，而不是更失去自主。

落地提醒：系统可以在用户情绪高涨、限时优惠、关系施压时触发“慢决策”提示：先睡一晚、列证据、问一个反方问题。', '["说服", "中心途径", "外周途径", "态度免疫", "消费决策", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 318, now()),
(100319, '群体场会放大反应：有人看见时更用力，没人认领时更偷懒', '核心观点：迈尔斯的群体影响章节能帮助用户理解团队与家庭系统。社会助长显示，他人在场会提高唤起水平，使优势反应更强：熟练任务可能表现更好，不熟练或困难任务可能更容易出错。社会懈怠则显示，当个人贡献无法被识别、责任被平均摊薄时，人会不自觉少出力。去个体化进一步说明，在匿名、群体唤起和责任扩散结合时，道德约束会下降，行为可能偏离平日自我。

App 落地：团队协作不要只喊“大家一起努力”，而要让责任可见、贡献可追踪、目标有挑战且有意义。亲密关系和家庭分工中，也要避免“谁有空谁做”的模糊结构，因为模糊最容易制造搭便车和怨气。对于用户在群聊、网络骂战或集体情绪中失控，可提示：匿名感和群体情绪正在降低你的自我监控，先退出场域再判断。

使用建议：把任务按人、时间、完成标准拆开；公开表扬具体贡献；对困难任务先练习再上场；对高唤起场景设置暂停按钮。群体不是必然让人变坏，也不是天然更高效；关键是评价、责任和规范如何被设计。

落地提醒：在关系咨询中，这条可解释“不是只有我不负责，而是我们没有把责任说清”。解释系统问题后，再回到个人可承担的一步。', '["群体影响", "社会助长", "社会懈怠", "去个体化", "团队协作", "责任可见化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 319, now()),
(100320, '群体极化与群体思维：高凝聚团队更要制度化异议', '核心观点：群体讨论不一定让观点更平衡，常会把成员原有倾向推向更极端。迈尔斯用群体极化解释同温层、网络社区和团队会议中“越聊越确信”的现象：成员反复听到支持性论点，并通过社会比较确认自己属于正确阵营。群体思维则发生在高凝聚、追求一致、隔绝异议的团队中，成员为了维护团结压下疑虑，最终做出糟糕决策。

App 端可服务团队管理和关系沟通：如果一个家庭、伴侣或团队总说“我们都这么认为”，要检查是否有人不敢表达不同意见。设计异议流程比期待某个人勇敢更可靠：先匿名收集风险点；会议中指定“反方角色”；领导最后发言；把“提出坏消息”定义为贡献；重大决定前安排冷静期和外部视角。

个人使用：当用户沉浸在只支持自己的社群里，可提醒其主动寻找一个高质量反对意见，而不是刷更多同类证据。亲密冲突中，也要避免找一圈只会站队的朋友，把委屈推向极端。真正可靠的支持系统，不只安慰你，也帮你看见盲点、代价和替代方案。

落地提醒：App 若用于团队复盘，可固定加入“我可能忽略了什么”“谁会不同意我们”的问题，避免只收集让团队舒服的信息。', '["群体极化", "群体思维", "团队决策", "异议机制", "同温层", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 320, now()),
(100321, '偏见不是单一恶意，而是身份、分类和公正世界共同运作', '核心观点：迈尔斯对偏见的处理比简单“不要歧视”更可用。偏见包含情感、行为倾向和信念，常由社会身份、资源竞争、社会化、制度支持、类别化和动机性解释共同维持。人会偏爱“我们”，把外群体看得更相似；会把少数群体的突出事件记得更牢；也会借“公正世界”信念责备受害者，好让自己相信世界仍然可控。

App 可用于减少关系中的标签化和群体敌意。第一步，把群体标签改回具体的人：这个人做了什么，而不是“他们都怎样”。第二步，检查是否存在内群体偏差：我们犯错是情境所迫，他们犯错就是本性。第三步，警惕责备受害者：对方遭遇不幸，不等于其应得。第四步，增加真实、平等、有共同目标的接触，而不是只在竞争和刻板叙事里认识对方。

咨询价值：用户在家庭、职场或亲密关系中也会制造小型“内外群体”：我家/你家、老员工/新人、理性的人/情绪化的人。知识库可引导其把阵营语言转成具体事实、共同需要和可协商边界。

落地提醒：在用户表达强烈群体厌恶时，先不贴“你有偏见”，而是引导其回到具体个体、具体行为和具体需求，降低防御。 再讨论公平。', '["偏见", "社会认同", "类别化", "公正世界信念", "责备受害者", "群际关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 321, now()),
(100322, '刻板印象威胁：身份标签会占用表现能量，需要高期待与高支持', '核心观点：刻板印象不只影响旁观者怎么看人，也会影响当事人如何表现。迈尔斯引用斯蒂尔等人的研究说明，当一个人担心自己会被负面刻板印象评价时，这种担心本身会占用工作记忆、提高生理唤起、增加出错恐惧，进而拉低表现。它不是能力不足，而是身份威胁正在进入任务系统。

App 端可把这条用于考试焦虑、职场表现、亲密关系中的自我怀疑。用户说“我果然不适合”“我们这种人就是不行”时，不急着灌鸡汤，而是帮他识别：当前任务里是否有标签压力？是否担心代表整个群体？是否在证明自己而不是完成任务？

干预语言：高支持不是降低标准，而是“我相信你能达到更高标准，所以给你具体反馈”。避免说“你们这类人也可以”，这会强化标签；改说“这项能力可以通过策略和练习提升，你这次主要卡在步骤二”。同时减少身份显著性，强调共同身份、任务策略和可控变量。对 App 来说，它能让鼓励从泛泛肯定变成既有要求又有安全感的反馈。

落地提醒：对青少年、女性、少数群体、转岗新人尤其要避免“你能做到已经很不错”式低期待安慰；更好的支持是具体策略和明确信任。', '["刻板印象威胁", "表现焦虑", "身份安全", "高期待高支持", "考试焦虑", "职场成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 322, now()),
(100323, '亲密不是神秘缘分：接近、相似、被喜欢和逐步表露共同塑造关系', '核心观点：迈尔斯把喜欢和爱情从“命中注定”拉回可观察机制。友谊和吸引常由接近性开始：更容易遇见、互动和熟悉的人更可能成为朋友。曝光效应让熟悉感增加好感；相似的态度、价值和生活方式会让人感到被确认；知道对方喜欢自己，也会增强喜欢的回路。激情之爱常带有强唤起和解释，而长期亲密更依赖伴侣之爱：平等、信任、自我表露和共同承担。

App 可用于关系成长，而不是教用户操控吸引。建议把“如何让 TA 爱我”改成“如何创造安全、真实、可持续的互动”。具体做法：增加低压力、高质量的共同时间；从低风险话题逐渐表露真实感受；用倾听回应对方表露，而不是立刻评价；检查双方付出与回报是否长期失衡；把新鲜活动作为补充，而不是用刺激掩盖关系问题。

关系修复提示：激情下降不等于爱消失，可能是关系从高唤起转向稳定依恋。真正需要警惕的是冷漠、轻蔑、长期不回应和无助感。成熟的爱情不是一直强烈，而是双方能反复理解、创建和重建关系。

落地提醒：这条可避免把亲密成长包装成技巧控制。App 应强调共同意愿、节奏同意和边界尊重，任何表露都应允许对方不回应。', '["亲密关系", "吸引", "接近性", "相似性", "自我表露", "伴侣之爱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 323, now()),
(100324, '利他不是只靠善良：清晰事件、具体责任和时间余量会显著提高帮助', '核心观点：迈尔斯把帮助行为拆成社会交换、社会规范、进化解释和共情利他，也特别强调情境条件。旁观者效应不是说明人冷漠，而是说明模糊情境中，人会先看别人反应；别人都没动，就容易出现多元无知。人越多，责任越分散；时间越紧，越可能跨过需要帮助的人；事件越清晰、求助越具体、有人率先行动，帮助越容易发生。

App 可把这条改写为求助和助人模板。求助时不要只说“有没有人能帮我”，而要具体点名：“小王，请你现在帮我打电话；小李，请你陪我去门口。”描述事实、需要、时间和行动。助人时，看到异常先不要用“别人会处理”安慰自己，先问三个问题：是否有人受伤？我是否能做一个低风险动作？我能否指定或带动其他人？

咨询/沟通价值：它也适合朋友倾诉。很多人不是不愿帮，而是不知道怎样帮。App 可引导用户把模糊期待翻译成具体请求：今晚陪我散步二十分钟、帮我看一遍简历、提醒我明天预约咨询。善意需要结构，结构会让善意更容易发生。

落地提醒：当用户是求助者，系统可直接生成“点名—事实—请求—时限”四段式消息；当用户是旁观者，提示先做最小安全行动。', '["利他", "旁观者效应", "责任扩散", "具体求助", "共情", "助人行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 324, now()),
(100325, '冲突常由社会困境启动：把“各自合理”改造成“共同有利”', '核心观点：迈尔斯在冲突章节中把许多矛盾解释为社会困境：每个人的短期选择看似合理，叠加后却伤害共同利益。公共地悲剧、囚徒困境、家庭分工、团队资源、伴侣冷战都类似：我多占一点、多防一点、少承担一点，短期保护自己，长期却让系统恶化。冲突还会让人把自己的行为解释为外界压力，把对方解释为贪婪、不可靠或恶意。

App 落地：先把争执从“谁坏”改写成“这个系统怎样奖励了坏结果”。家庭中，如果谁先做谁吃亏，就要重设分工和可见回报；团队中，如果合作没有奖励、搭便车没有成本，就会不断消耗积极者。亲密关系中，若道歉者总被继续追打，沉默者总能逃过责任，系统也在强化失衡。

可用工具：缩小责任单位、增加面对面沟通、让贡献可见、改变激励、建立共同规范、强调共同身份和长期利益。知识库可用一句话提示用户：不要只问“对方为什么这样”，也要问“我们当前规则让哪种行为更容易发生”。改变结构，常比责骂人格更有效。

落地提醒：这条尤其适合反复争吵的伴侣或团队。不要只追问谁先错，而要画出循环：谁做了什么、短期收益是什么、长期代价是什么。', '["冲突", "社会困境", "公共地悲剧", "合作机制", "家庭分工", "系统思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 325, now()),
(100326, '和解不是一次道歉：接触、共同目标、建设性沟通和 GRIT 逐步降温', '核心观点：迈尔斯把和平写成一套过程，而不是一句“别吵了”。单纯接触不一定消除敌意，尤其在地位不平等、竞争和刻板印象仍在时；更有效的是平等接触、共同目标、合作任务、建设性沟通和逐步互惠的降温行动。GRIT 策略强调：一方先公开表达降低紧张的意图，再做一个小而可验证、不会危及自身安全的善意行动，并邀请对方回报；若对方合作，就继续升级信任，若对方攻击，也保持边界。

App 可用于伴侣冷战、家庭长期矛盾、团队对立。先不要要求巨大让步，而是设计低风险修复动作：暂停讽刺三天、按时回复一个必要信息、归还一个资源、承认一个具体影响、共同完成一件小任务。每个动作前都说明意图：“我想让我们不再升级，所以先做这一步。”

沟通模板：少用旧账攻击、读心和威胁；多用事实、感受、需要、反馈、提问和双方都能接受的建议。若直接谈判困难，可引入第三方调解，帮助双方从“非赢即输”转向“共同有利”。和解的关键不是立刻信任，而是用连续、可验证的小行动重新制造信任。

落地提醒：GRIT 不适用于要求用户在危险关系中单方面忍让。若存在持续威胁、暴力或严重操控，优先做安全边界，再谈互惠降温。', '["和解", "GRIT", "建设性沟通", "共同目标", "关系修复", "调解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 326, now()),
(100327, '见证与承认：创伤复原从“不再孤立”开始', '核心理解：创伤不只是个人内部的痛苦，也会发生在关系与社群的断裂中。当一个人经历了不可承受的伤害，最折磨人的往往不只是事件本身，还有之后被怀疑、被责备、被要求沉默，或被旁观者劝说“算了、忘了吧”。温和的支持不是急着追问细节，也不是替对方决定该怎么处理，而是先承认：你经历的事重要，你的反应有意义，你不必独自承担。
用于 App 端沟通时，可把“见证”拆成三步：第一，稳定地在场，用简单语言表达相信与关心；第二，保护当事人的选择权，询问她现在需要安静、陪伴、实际协助还是转介资源；第三，避免站到加害或压力系统一边，例如质疑“为什么不早说”“为什么不离开”。对关系成长而言，真正的支持是一种行动：愿意记得、愿意保护、愿意和当事人一起面对现实后果。承认与弥补无法抹去过去，却能帮助人重新相信世界仍有秩序和正义。
适用场景包括：用户不确定是否该说出经历、亲友不知道如何回应、伴侣想修复信任。回答时要把“相信与保护”放在“分析原因”之前，并提醒支持者少说评判，多提供可被拒绝的具体帮助，例如陪同、记录、寻找资源或只是安静在场。', '["创伤支持", "见证", "去孤立", "社群承认", "安全沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 327, now()),
(100328, '创伤反应：不是“太敏感”，而是保护系统仍在工作', '核心理解：创伤反应可以被理解为自我保护系统在极端处境后仍保持高负荷运行。危险发生时，身体会动员逃跑、抵抗、警觉、忽略疼痛等能力；当抵抗或逃离都无效时，这套系统可能变得混乱，并在危险过去后仍无法自动复位。于是，一个人可能出现三类常见体验：过度警觉，像随时预期危险再来；记忆侵扰，某些画面、梦、气味或声音突然把人带回过去；禁闭退缩，表现为麻木、空白、隔离、失去兴趣或对未来不敢想象。
App 端表达时，应避免把这些反应道德化为“脆弱”“矫情”“故意作”。更稳妥的说法是：这是身心在努力保护你，只是保护方式已经不再适合现在。第一步不是马上挑战记忆，而是帮助用户辨认“此刻我在哪里、周围是否安全、我能做一个小选择吗”。当反应被命名，它就不再只是莫名其妙的失控，而能成为可观察、可调节、可被支持的信号。
适用场景包括：用户说自己突然暴躁、惊醒、发呆、对小事反应很大。回答时可先正常化这些反应，再邀请她观察强度和触发线索。避免要求她证明自己受过伤，也避免把麻木解释成冷漠；麻木有时也是身体在省电和自保。也可提醒用户：反应强弱会波动，波动不等于失败。', '["创伤反应", "过度警觉", "记忆侵扰", "麻木退缩", "身心保护", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 328, now()),
(100329, '身体记忆与触发：先回到现在，再理解过去', '核心理解：创伤记忆常不像普通回忆那样有清楚的时间顺序和语言说明，而更像感官碎片：身体紧绷、心跳加快、胃部不适、某个气味或声音、一个姿势、一个梦。人可能理性上知道危险已经过去，身体却像仍在当时。这不是“想太多”，而是记忆、情绪、知觉和身体感受在创伤时没有被整合。
因此，App 端不宜引导用户强行回想细节，也不宜使用高强度暴露式练习。更合适的顺序是：先安全定位，再身体安顿，最后才是意义理解。可以邀请用户用低刺激方式描述当前状态，例如“我注意到胸口紧”“我在房间里，脚踩在地上”“我现在可以选择暂停”。当用户已经稳定，再帮助她区分：这是过去留下的身体警报，不等于现在一定有危险。关系沟通中，亲友也可学习把触发看作身心信号，而不是争吵中的故意攻击；先降速、减少刺激、确认边界，再谈发生了什么。
适用场景包括：用户被某句话、气味、亲密接触或冲突瞬间带回旧感受。回答时可提供“现在—过去”区分句式：我正在经历一个旧警报，但我可以先确认当下环境。若用户仍处在危险关系中，应优先谈现实安全和可用支持，而不是记忆解释。', '["身体记忆", "触发点", "当下定位", "稳定化", "感官碎片", "低刺激支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 329, now()),
(100330, '亲近者的回应：真实评价能减轻羞耻和自责', '核心理解：创伤之后，亲近者的反应会深刻影响复原。支持、保护和真实评价，可以减轻创伤冲击；敌意、怀疑、轻描淡写或盲目接受，则可能加深羞耻、自责和孤立。所谓真实评价，不是替当事人制造虚假安慰，而是同时看见三件事：事件确实严重；人在危险中选择极其有限；许多看似“奇怪”的反应其实是正常的创伤反应。
在 App 端的沟通建议中，可以把亲友回应设计成“确认—归责—选择”三步：确认感受和经历，不急着追问证据；把责任放回伤害行为和不安全环境，而不是放到受害者的性格上；把下一步交还给当事人选择。尤其在性侵、家庭暴力、长期控制等情境中，要避免问“你为什么不反抗、为什么不离开”。更有帮助的问题是：“现在怎样会让你安全一点？”“你希望我陪你做哪一件小事？”这种回应能帮助人从被评判的位置回到有尊严的位置。
适用场景包括：亲友、伴侣、咨询助理需要回应披露。可建议使用短句：“我相信这对你很难”“谢谢你告诉我”“你希望我现在怎么陪你”。如果不知道该说什么，承认不知道也比仓促解释更好。支持的目标不是立刻让对方好起来，而是减少二次受伤。', '["关系支持", "羞耻", "自责", "亲友沟通", "真实评价", "去责备"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 330, now()),
(100331, '长期控制的影响：复原要把选择权一点点拿回来', '核心理解：长期创伤常不只是单次暴力，而是一套持续削弱自主的控制系统：制造恐惧、反复无常地惩罚、偶尔给予小恩小惠、隔绝外界支持、监控身体和日常生活、要求保密或忠诚。人在这样的环境中可能变得顺服、迟疑、依赖、难以判断危险，并不是因为“愿意受苦”，而是因为自主感被长期破坏，求生策略被固定下来。
App 端要避免用简单口号要求用户“立刻勇敢”“马上切断关系”。更稳态的方向是帮助她重新体验可控的小选择：今天要不要回复消息；是否需要找一个可信的人保存重要信息；身体需要睡眠、饮食、医疗还是安静；哪些物品、联系人、地点能支持安全感。复原不是一次夺回全部力量，而是把身体、时间、金钱、社交、表达和行动的主导权一点点收回。关系成长中，尊重边界尤其重要：任何打着关心名义的强迫，都可能复制控制；真正的帮助应增加选择，而不是替代选择。
适用场景包括：用户明知关系伤害自己却难以离开、难以拒绝、反复回到控制者身边。回答时应把重点放在控制机制和资源缺口，而不是羞辱她“不清醒”。可以帮助她建立外部连接清单、证件和财务安全意识、危机联系人，但所有建议都要允许用户按自己的节奏选择。', '["长期控制", "自主权", "安全计划", "边界", "家庭暴力理解", "小选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 331, now()),
(100332, '童年创伤的适应：先理解求生策略，再谈改变', '核心理解：童年长期受虐时，孩子必须在不安全的人际环境里维持依恋、寻找意义和保留希望。她可能否认、淡化或合理化伤害，可能发展出过度警觉、讨好、隐藏、解离、完美表现，或把责任揽到自己身上。许多策略在成人看来像“矛盾”或“问题行为”，但在当时可能是孩子能想到的唯一求生方式。
用于 App 端时，重点不是给用户贴上人格标签，而是帮助她把模式还原到历史背景中：当年这样做，可能是为了少受伤、保住关系、让世界看起来仍有一点希望；现在如果这些策略让关系、身体或生活受限，可以在安全前提下逐步更新。比如，把“我总是讨好”改写为“我曾学会通过顺从换取安全，现在我可以练习小范围表达不同意见”；把“我太坏了”改写为“自责曾让我以为自己还有控制感，但责任并不在孩子身上”。理解不是纵容伤害，而是让改变从羞耻中释放出来。
适用场景包括：用户把自己描述成“太会讨好、太矛盾、太假、没有自我”。回答时可把这些模式翻译成过去的保护性能力，再讨论今天的代价。这样既能减少羞耻，也能打开改变空间：不是把旧策略一刀切掉，而是在更安全的关系里练习新的反应。', '["童年创伤", "求生策略", "讨好反应", "解离", "自我理解", "去标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 332, now()),
(100333, '把责任放回正确的位置：反对“责备受害者”', '核心理解：长期创伤最容易被误解的地方，是旁观者常用正常环境里的标准评判极端处境中的选择。人们会问为什么不逃、为什么顺从、为什么沉默，甚至把反应解释成性格缺陷。这样的评判忽略了长期恐惧、隔离、依赖和控制会改变人的判断与行动范围，也会让受害者承担比加害者更严厉的道德审判。
App 端知识库应坚持“情境化理解”：先看处境、权力差和可用资源，再看行为。用户如果反复自责，可以引导她区分三类责任：伤害行为的责任属于加害者；当时有限选择下的求生反应不等于同意；现在可以承担的是照顾自己、寻找支持和逐步修复的责任。这样既避免把用户固定在无助位置，也避免把不属于她的罪责继续压在她身上。对咨询和沟通来说，去责备不是否认复杂性，而是给人一个更公平的起点，让她能在不被羞辱的环境中重新审视自己的边界、需要和未来行动。
适用场景包括：用户反复说“是不是我也有问题”“我当时为什么那样”。回答时可温和地区分“反思”和“自我定罪”：反思是为了现在更自由，自我定罪会继续替加害系统工作。若需要讨论自己的脆弱点，也必须在责任已经归位、情绪相对稳定之后进行。', '["责备受害者", "归因", "羞耻修复", "责任区分", "创伤理解", "去污名"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 333, now()),
(100334, '赋权式支持：帮助可以给建议，但不能替用户复原', '核心理解：创伤的核心伤害之一，是自主权被夺走和人与人的联系被切断。因此，复原关系的首要原则是恢复自主权。支持者、咨询师或亲友可以提供信息、陪伴、建议、照顾和资源，但不能代替当事人决定什么才是“正确复原”。即使出于善意的强行安排，也可能让人再次体验失控。
App 端的咨询话术可以遵循赋权原则：先询问许可，再提供选项；把建议说成“你可以考虑”，而不是“你必须”；允许用户暂停、拒绝、修改目标；把进展定义为她更能做选择，而不是她更听话。关系中的界限也属于赋权：清楚的时间、频率、联系规则和紧急处理方式，不是冷漠，而是创造安全领域。支持者也需要自己的支持系统，因为没有人能单独承受创伤带来的强烈情绪。真正稳固的帮助关系，是既可靠又有边界，既愿意靠近，又不控制对方。
适用场景包括：咨询对话、AI 陪伴和亲友支持。系统应优先使用选择题和开放许可，例如“要不要先停一下”“你想听建议还是只想被陪伴”。当用户拒绝建议时，不把拒绝视为阻抗，而视为自主权正在恢复；这本身就是复原的一部分。这种尊重会降低防御，让合作更可能发生。', '["赋权", "自主权", "支持关系", "治疗契约", "边界", "选择权"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 334, now()),
(100335, '复原三阶段：安全、回顾与哀悼、重建联系', '核心理解：复原常可概括为三个阶段：第一是建立安全，第二是回顾与哀悼，第三是重新连接生活。这个顺序不是僵硬流程，而是提醒我们：没有足够安全时，不宜贸然深入创伤细节；只停留在安全管理中，也可能让生命长期收缩；当故事逐渐被整合，人才有力量回到关系、工作、愿望和未来。复原也不是直线，旧问题会在新的人生节点返回，需要重新照顾。
App 端可把三阶段转化为温和导航：如果用户正在高激活或现实不安全，重点是稳定身体、环境和支持网络；如果用户已有一定资源，才进入叙事整理、意义理解和哀悼失去；如果用户开始关心未来，则支持她建立边界、选择信任的人、恢复兴趣和行动。每个阶段都要保留自主权：用户可以慢，可以绕路，可以暂停。所谓完成，并不是再也没有痛苦，而是症状可管理、记忆可承受、自尊和关系逐渐恢复，创伤成为生命故事的一部分，而不是全部。
适用场景包括：用户问“我是不是退步了”“为什么好一阵又被触发”。回答时可说明阶段会往复，复发不等于失败。不同阶段适合不同帮助：高压时做稳定和现实支持；较稳时做故事整合；有余力时做关系、边界和未来规划。', '["复原阶段", "安全优先", "回顾与哀悼", "重建联系", "长期修复", "阶段性支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 335, now()),
(100336, '安全优先：从身体掌控扩展到环境和支持网络', '核心理解：安全不是一句“别怕”，而是具体、分层、可执行的生活条件。书中把第一阶段的安全工作从身体开始，再扩展到环境和关系：身体层面包括睡眠、饮食、运动、医疗照顾、过度警觉和侵扰反应的管理；环境层面包括安全住所、经济和行动能力、日常自保计划；关系层面包括筛选可信的人、动员支持系统、必要时连接社会服务或司法资源。
App 端应把安全问题放在任何深入练习之前。可以设计低负荷问题：“我现在的身体最需要什么？”“我在哪里会更安全一点？”“谁能提供具体帮助？”“今天只做哪一个小步骤？”对长期受控的人，小任务尤其重要，因为它能重新训练计划、判断和主动性。安全计划不应制造恐慌，也不应替用户做决定，而是帮她把模糊的危险感拆成可观察的现实因素。稳定化的目标，是让用户逐渐体验：我能照顾身体，我能选择环境，我能联系可靠的人，我可以在现实世界里增加一点安全。
适用场景包括：用户情绪很高、睡眠饮食混乱、关系中仍有现实威胁。回答应先聚焦今天和本周，而不是人生大目标。可以把计划做得很小：喝水、开灯、联系一个人、把危险物移远、确定今晚在哪里睡。小而可完成的行动能积累主导感。', '["安全计划", "稳定化", "身体照顾", "环境安全", "支持网络", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 336, now()),
(100337, '创伤叙事要有节奏：讲述是整合，不是强迫暴露', '核心理解：当安全基础足够后，讲述创伤故事可以帮助记忆从静止、碎片和沉默，逐渐变成可被理解的生命叙事。但讲述不是越快越好，也不是越详细越有效。过度回避会让复原停滞，过早或过猛地接近记忆，则可能让人再次被淹没。关键是在“安定的现在”和“痛苦的过去”之间来回移动，让人知道自己此刻有人陪伴、有选择、有暂停权。
App 端不应提供强刺激回忆任务，而应强调节奏和许可：用户先确认现实安全和身体承受度，再选择是否整理片段；可以从事件前后的生活背景、当时的资源、重要关系和现在的理解开始，而不是直接进入最痛苦画面；若出现明显失控、麻木、惊恐或生活功能下降，应放慢并回到稳定。讲述的目标也不是侦查事实、逼出“唯一真相”，而是让用户逐渐找到语言、情感和意义，把“发生在我身上的事”放回生命脉络中，并在尊严感中重新选择下一步。
适用场景包括：用户想整理过去，但又害怕被记忆淹没。回答可建议先建立“暂停词”“结束仪式”和事后照顾，而不是直接书写最痛苦细节。若对话中出现明显失控，应停止追问故事，转向当下感官、呼吸节奏、环境确认和可信陪伴。', '["创伤叙事", "节奏", "见证", "稳定优先", "记忆整合", "温和回顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 337, now()),
(100338, '哀悼不是沉溺：承认失去，释放“不必宽恕”的压力', '核心理解：创伤会带来真实的失去：失去安全感、身体边界、童年、信任、家庭幻想、旧的自我和某些未来可能。复原中的哀悼，是承认这些损失曾经发生，并允许悲伤、愤怒、失望和空白有位置。哀悼不是沉溺过去，而是让人停止用否认或自责维持旧秩序，开始为新的生活腾出空间。
这一条对 App 端尤其重要：不要把“宽恕加害者”设为疗愈任务。用户不需要等加害者认错、悔改或获得宽恕，才能开始复原。更温和的方向是发现生活中仍存在的爱、支持、价值和选择，让注意力从加害者身上逐步回到自己身上。可以引导用户区分：我可以不再被他定义，但这不等于我必须原谅；我可以哀悼损失，同时保护边界；我可以承认愤怒，而不让愤怒控制全部生活。真正的释放，常常不是替伤害找理由，而是发现自己仍有爱与被爱的能力，仍能与人建立新的联系。
适用场景包括：用户被他人劝“放下”“原谅才算好了”。回答时可明确区分放下控制权和宽恕加害者：前者是为了自己，后者不是义务。哀悼允许反复出现，也允许轻松和快乐回来；快乐不是背叛过去，而是生命力仍在。允许不原谅，也允许慢慢重新生活。', '["哀悼", "不强求宽恕", "失去", "愤怒", "自我释放", "爱的能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 338, now()),
(100339, '重建联系与使命：边界、信任和普通生活都是复原', '核心理解：复原后期不是把创伤故事讲完就结束，而是重新进入生活。人会开始学习：哪些人值得信任，哪些人需要保持距离；怎样在亲密中保留自由意志；怎样表达需要、拒绝不合适的要求、保护下一代；怎样恢复愿望、兴趣、工作、友谊和普通日子。创伤曾让人孤立，重建联系则让人重新体验“我属于人群，也拥有自己”。
App 端可支持用户把复原落到关系和行动中：练习清晰边界，选择可靠联盟，发展同辈互助，逐步面对家庭秘密或社会压力，但所有公开表达都应有准备、有时机、有安全计划。对一些人而言，社会行动、帮助同类、教育倡导或追求正义，会把个人痛苦转化为对他人的礼物；对另一些人而言，能安稳工作、恋爱、养育、玩耍、享受生活，也同样是胜利。团体支持很有力量，但必须安全、结构清楚、适合阶段；早期以教育和自我照顾为主，深入分享应在稳定之后。长期修复的标志，是创伤仍被记得，却不再垄断人生。
适用场景包括：用户开始想恋爱、工作、公开发声、帮助别人或加入团体。回答时应提醒：使命感需要建立在自我照顾之上，不能用拯救他人来替代照顾自己。团体、倡导和正义行动都应有边界、有同伴、有退出机制；普通生活同样值得被肯定。', '["重建联系", "边界", "信任", "使命感", "团体支持", "长期修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 339, now()),
(100340, '倾听的核心：把治疗师的内在反应转化为临床信息', '《心理治疗实战录》反复提醒，治疗师并不是没有感受的“空白屏幕”。在倾听时被激发出的怜悯、愤怒、厌倦、好奇、无助、想营救、想讨好或想赶快结束等反应，本身就是理解来访者的重要线索。尤其当来访者叙述的字面内容与治疗师内心反应不一致时，常提示有未被说出的情绪、被防御遮住的关系模式，或来访者惯常激发他人回应的方式。用于 App 知识库时，可转化为咨询辅助提示：先标记“我此刻被激发了什么”，再区分这是治疗师个人议题、情境压力，还是来访者互动方式带来的信息；把感受当作待检验假设，而非事实判决。这样既能避免把反移情直接行动化，也能避免因追求中立而变得冷硬、机械、无回应。对用户端心理教育而言，这一条也可表达为：有效倾听不是没有反应，而是能觉察反应、暂缓反应，并把反应用于更准确地理解对方。在产品化时，这一条不宜被写成“凭感觉判断用户”，而应写成一套审慎流程：记录反应、命名反应、寻找触发点、回到用户原话和互动情境中验证。若系统用于辅助咨询师，可提示“此处可能需要督导或自我照顾”；若用于普通用户心理教育，则可转译为“你在关系中激发他人的感受，也可能是理解关系循环的线索”。', '["咨询倾听", "反移情觉察", "治疗师回应", "情绪承接", "临床假设", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 340, now()),
(100341, '初访不是套病史：先熟悉这个人并建立合作框架', '初始访谈的首要任务不是尽快收集完整病史、给出人格模型或套用诊断标签，而是让治疗师与来访者彼此熟悉，初步判断是否适合心理治疗，并为后续合作定下基调。书中强调，除非存在自杀风险、精神病性状态、中毒、器质性损伤或独立社会功能明显受损等紧急情况，否则初访不宜过早围绕症状清单和成长史做“搜集式审问”。治疗师可以用礼貌、真实、安定的方式开场，核对姓名和联系方式，帮助来访者适应环境；随后用开放问题邀请其说明来访理由。症状当然重要，但症状细节最好在治疗过程中、伴随具体情境自然浮现，因为其出现的情境本身就是理解症状意义的线索。App 可将这一条设计为初访清单：先做风险筛查，再确认来访者关心什么、愿不愿合作、能否理解会谈规则；不要把一次初访包装成完整诊断或治疗承诺。这也能避免 App 端常见的“问卷化冷感”：用户刚进入支持场景时，若被连续追问童年、症状频率和人格原因，可能更紧张或更自责。更合适的知识库表达是：先说明会谈/对话的目的、保密和限制，先陪用户把当前困扰说清楚，再逐步扩展到生活背景。只有当安全风险或医疗风险出现时，才把流程转向紧急求助、精神科或线下支持。', '["初始访谈", "咨询框架", "风险筛查", "合作关系", "非诊断", "咨询边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 341, now()),
(100342, '问题澄清：从概括抱怨拉回最近一次具体情境', 'Arianes 因胃痛和婚姻争吵来访时，最初只说“结了婚的人不都成天吵吗”。书中示范了几种会把会谈带进死胡同的回应：追问“总还有些可说的吧”、抽象追问“受不了是什么意思”、质疑其概括，或在初访中用沉默让来访者独自承受焦虑。更有效的做法是承认自己需要来访者协助，并把问题拉回到最近一次具体争吵：什么时候、在哪里、谁在场、发生了什么、是瞪眼、吼叫还是动手。治疗师还要解释为什么需要细节——不是审讯，而是为了确认自己真的听懂。具体化能把“我就是很痛苦”转化为可共同观察的事件，让来访者从模糊、封闭、情绪化的印象中退一步，看见事情的现实结构。App 可把它转化为问题澄清模板：先共情，再询问最近一次场景、可观察行为、身体反应、对方回应和未说出口的需要。这一条尤其适合做成 App 的追问策略：当用户使用“总是、从来、所有人、没办法”等概括词时，系统不急着反驳，而是邀请其选择一个最近、最清楚、强度适中的片段。随后再整理“事件—解释—情绪—身体—行动—后果”的链条。这样既能降低用户被评判感，也能把抽象痛苦变成可复盘、可调整的小单元。', '["问题澄清", "具体化提问", "咨询对话结构", "治疗师回应", "婚姻冲突", "身体化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 342, now()),
(100343, '直接探引遗漏部分：被回避的内容不会自动浮现', '书中反对一种常见误解：只要治疗师足够耐心，来访者没有说出的内容就会自然浮现。事实上，许多重要材料必须靠治疗师直接、适度地探引。来访者旧有的适应方式常会让他在不同情境中重复症状言行，继续归因于他人或环境，却看不见自己“此时此刻做了什么、没有做什么”。治疗师既要认真倾听以熟悉防御，也要在会谈失焦时重新抓住主诉的核心。例如 Arianes 谈花园时，花园作为减压资源值得注意，但若任由话题无边际漫谈，治疗会失去焦点；治疗师于是把话题拉回婚姻关系变化。App 可把这一条做成会谈导航：当用户叙述开始绕开核心痛点时，不急于打断，也不无限放任，而是温和标记“这里好像有个重要部分还没说清”，再邀请其回到具体行为、未表达需要和关系后果。这一策略的难点在于尺度：过早追逼会让用户感到被审问，完全等待又会让对话空转。知识库可提示助人者先确认用户是否有足够安全感，再用“我注意到这里好像停住了”“我们是否可以回到刚才那一点”之类语言邀请，而不是用“你在逃避”贴标签。它也适合辅助识别阻抗：绕开、讲道理、讲别人、讲无关细节，都可能是在保护某个尚难承受的情绪。', '["阻抗防御", "直接探引", "会谈聚焦", "此时此刻", "咨询动力", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 343, now()),
(100344, '治疗师犯错后的修复：一次会谈不必完美也能具有治疗性', 'Arianes 在自由联想尝试中变得焦虑，治疗师意识到推进太快，于是退回一步，换成更可承受的探索角度；后来临近结束时，治疗师也承认自己没有把固定会谈安排说清楚。书中由此提出一个重要原则：心理治疗复杂到很少有“完美开局、完美过程、完美结束”的会谈。治疗师必须习惯非完美，愿意把误解、莽撞、时间处理不佳或提问失准，转化为后续工作的材料。关键不是永不犯错，而是在发现来访者焦虑、困惑或关系断裂时，能以就事论事且不防御的方式修复。对于 App 咨询辅助，可设置会谈后复盘四问：我在哪一刻推进太快或退得太远？来访者的身体和情绪信号是什么？我如何澄清、道歉或重设框架？下次如何把这次断裂变成理解来访者模式的入口？这种复盘能帮助助人者减少“怕错而不作为”的僵硬。对 App 后台而言，这一条可转化为“断裂—修复”知识：当用户反馈“你没懂我”“这个建议没用”“我更乱了”时，系统不应急着辩解或继续给建议，而要先承认影响、询问哪里不贴合、重述用户关切，再调整方向。它也提醒真人咨询师：复盘不是自责，而是把技术失误、节奏失衡、边界不清转化为更准确的下一步。修复本身往往比完美回应更能建立可信关系。', '["关系修复", "治疗师复盘", "咨询误差", "会谈结束", "情绪承接", "督导训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 344, now()),
(100345, '个案概念化：把当前互动、童年经验和自我实现预言连起来', 'Arianes 的婚姻痛苦不只是“妻子不体贴”，而是他期待妻子像理想化母亲一样无需说明就懂自己；当这种期待落空时，他便退回到九岁受伤男孩的位置，预期亲近女性会忽视自己的需要。治疗师没有把童年创伤当作标签，而是在当前婚姻互动、来访者对妻子的期待、童年向母亲求助被责骂的记忆之间，提出一个可探索的假设：他把早年形成的态度带进成年亲密关系，进而以不表达需要、带着拒绝预期靠近妻子的方式，制造了自我实现预言。App 可将这条转化为个案概念化框架：当前触发事件是什么？来访者自动期待什么？这种期待像哪段早年关系？它如何影响来访者的表达、回避或攻击？当下有没有新的回应可能？内容需以假设方式呈现，不宣称已解释全部人格，也不替代专业治疗。这一条也提醒 App 不要把“原生家庭”作为万能解释。早年经验只有在它能解释当下可观察的互动循环时，才适合进入概念化；否则容易让用户停在责怪过去或把自己固定成受害者。较好的呈现方式是：过去形成了某种保护性预期，这个预期曾经有用，但现在可能让用户少表达、先防御、误读他人，从而重复旧结局。目标不是追责，而是增加新的选择。', '["个案概念化", "早年经验", "亲密关系", "自我实现预言", "防御模式", "治疗性假设"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 345, now()),
(100346, '移情是工作材料：直接处理来访者对治疗师的担心与贬低', 'Arianes 在会谈中批评治疗师办公室“很差劲”，进而把治疗师看成“失败者”。治疗师没有急着解释房子不是自己的、也没有回避这个议题，而是把它当作移情关系的材料：来访者似乎需要把治疗师看成像父亲一样软弱、失职、终将让自己失望的人。书中强调，移情不是只在精神分析中才出现的危险物，也不是一出现就会打开“潘多拉之盒”；在一般心理治疗中，来访者对治疗师的担心、欣赏、失望或攻击，常是理解其旧关系模板的关键。治疗师越能直接而不防御地处理这些感受，越能让来访者体验到：负面想法可以被说出来，关系不会因此崩塌。App 可提供移情观察提示：来访者是否把治疗师/平台/建议者想象成会批判、抛弃、失败或控制自己的人？这与其现实关系中哪些期待相似？此刻是否适合温和澄清，还是先承接情绪？用于 App 时，不宜把普通用户对平台或建议的不满都解释成移情；更稳妥的是把它作为关系线索：用户是否在期待“你也会像别人一样不可靠/批评我/控制我”？如果是，回应要先承认这种担心的现实感，再说明当前对话能做什么、不能做什么。对咨询师辅助场景，则可提示：不要急于证明自己无辜，也不要把来访者的贬低当成人身攻击；先看它在关系中承担什么功能。', '["移情关系", "治疗师回应", "负面情绪", "关系模板", "动力取向", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 346, now()),
(100347, '负向移情与攻击：先代谢治疗师自己的受伤，再形成可检验假设', 'Banks 初访时质疑治疗师年轻、男性、未必有能力，还用专业术语和前任治疗师压迫新治疗师。书中列出多种无效回应：被激怒后冷漠拒绝、用专业地位反击、急着证明自己没有性别偏见、过早指出“你在贬低我”。更有效的路径是：治疗师先觉察自己被伤害、焦虑、愤怒的感受，暂缓防御反击，再把这些反应转化为假设——如果她也这样对待潜在男性伴侣，关系会怎样？她的攻击是否在保护自己免于再次失望？随后治疗师忽略挑衅，转而询问她现实中的亲密关系。负向移情不是要被纵容，也不是治疗师必须无条件忍受辱骂；只有当这些言行能被带回会谈、促进来访者理解自身模式时，才具有治疗价值。App 可把它转化为“被攻击时三步”：稳定自己、识别关系功能、选择是否把攻击变成可讨论材料。这一条可用于训练“不过度个人化”的临床思维。来访者的尖锐语言会真实地伤到治疗师，否认这一点反而容易在后续以冷淡、讽刺或撤退表现出来。较好的做法是先在内心承认受伤，再问：这个攻击是否在测试我会不会报复？是否在迫使我离开以证明旧信念？是否在转移丧失和羞耻？只有当治疗师能稳住自己，才可能既设边界，又不放弃理解。', '["负向移情", "阻抗防御", "治疗联盟", "治疗师反应", "攻击性", "咨询边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 347, now()),
(100348, '治疗联盟不是互相喜欢：能在攻击和不信任中继续工作才是联盟', '书中对“治疗联盟”提出了一个很务实的理解：它并不等同于来访者喜欢治疗师、治疗师也喜欢来访者，更不是双方从一开始就有清晰一致的共同目标。许多来访者因为害怕亲密、预期被伤害或羞耻，会把自己表现得很不讨喜；如果治疗师把“建立亲善关系”当成首要目标，就容易被迫讨好、解释、证明自己。Banks 反复怀疑治疗师是否会发火、是否能理解她，治疗师没有急着证明“我很好”，而是把无法信任本身作为问题来探索：你想象我会做什么？这让怀疑变成可理解、可检验的材料。对 App 咨询辅助而言，这一条可用于提醒助人者：关系质量不只看互动是否温和，也看双方能否承受不信任、失望、愤怒和尴尬；治疗师要能稳定地喜欢自己的专业姿态，才能不被来访者的喜欢或不喜欢牵着走。这对 App 的启发是，支持性语言不能只追求“让用户舒服”。有时用户需要的不是被赞同，而是有人能稳定地承接其怀疑，并把怀疑拆成可讨论的问题。知识库可提供两类回应：一类用于先安定关系，如“你担心我也会误解你”；一类用于推进探索，如“如果我真的会让你失望，你最担心发生什么”。这种设计能避免系统一味讨好，也避免在用户攻击时机械地结束支持。', '["治疗联盟", "不信任", "关系承受力", "治疗师稳定性", "防御", "咨询关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 348, now()),
(100349, '诊断与治疗目标：不要只看症状标签，要看关系能力和情境功能', '书中通过 Clark、Billy、Frank、Delmore、Elbogen 和 Banks 等案例说明，临床判断不是把症状逐条套进标签，而是在具体情境中观察一个人如何生活、如何与治疗师互动、能否使用关系来反思自己。Billy 有视听体验，但与人交流的方式不像精神分裂症患儿，最终需考虑神经科因素；Clark 的丧偶抑郁要放在其长期依赖妻子维持功能的背景中理解；Delmore 与 Elbogen 都有异性关系困难，但前者能自我检视、信任治疗，后者则广泛外归因、难以把治疗师当作情感对象。治疗计划也因此不同。App 端知识库可将其表述为：心理教育内容不做诊断判决，而帮助用户区分症状、功能、关系能力、风险信号和求助路径。真正有意义的问题不是“这是什么标签”，而是“这个人在什么情境下失去秩序感？他能否借助关系恢复反思与行动？”在知识库落地时，这一条应明确区分“心理教育解释”和“临床诊断”。App 可以帮助用户理解焦虑、抑郁、创伤、人格模式等概念，但不应根据几句描述判定人格障碍或精神疾病。更有帮助的是引导用户观察：症状何时出现、是否影响睡眠饮食工作、人际中是否重复同一循环、是否能求助和反思、是否存在自伤或精神病性风险。这样既能减少标签化，也能提高转介判断质量。', '["鉴别诊断", "非标签化", "治疗目标", "功能评估", "移情关系", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 349, now()),
(100350, '青少年与抑郁初访：先评估安全和边界，再把症状放回发展任务', 'George 退学后出现失眠、食欲下降、无意义感和对“会不会发疯”的恐惧。治疗师没有立刻把会谈变成症状清单，而是先做必须的安全评估：直接询问是否想过自杀、是否曾行动、现在是否仍有冲动，同时在合适时机询问药物、酒精、毒品和自伤风险。书中强调，谈自杀时态度比措辞更重要；实事求是的提问通常能让来访者感到痛苦被认真对待。随后，治疗师清楚说明保密边界：父母付费不等于可以知道治疗细节，但若来访者无法保证不伤害自己，治疗师会采取必要保护措施，可能包括通知父母。对抑郁的理解也不以“消除症状”为唯一目标，而是帮助来访者重建自我方向、行为能力和成长任务。App 可据此设计青少年心理教育：安全筛查、隐私说明、支持网络和专业转介优先，内容只作为辅助，不替代危机干预或治疗。对 App 而言，青少年场景还需要特别处理家长角色：既要尊重青少年的隐私和主体性，也要在安全风险、虐待风险或严重功能受损时启动成人支持和线下资源。知识库可给出边界话术：哪些内容会保密，哪些情况必须寻求帮助，为什么这不是背叛而是保护。随后再帮助用户探索失恋、离家、学业、身份选择等发展任务，避免把一切简化成“情绪不好”。', '["青少年抑郁", "危机评估", "保密边界", "自杀风险", "发展任务", "专业求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 350, now()),
(100351, '适度自我披露：只有服务治疗目标时才进入会谈', '书中批评把治疗师“匿名状态”绝对化的教条。治疗师个人生活不应随意敞开，但这并不意味着治疗师必须永远像无名机器。George 问自己为什么没有接受更深入的精神分析时，治疗师不仅解释当前治疗形式为何适合，还说自己若在 18 岁时能坐在 George 的位置上，或许能避免许多不幸。作者说明，这种披露不是满足治疗师表达欲，而是为了让 George 认同一个曾在青春期探索、并非全知全能的现实导师，从而推动理想化移情走向更成熟的方向，而不是把治疗师幻想成“治疗师上帝”。App 可把它转化为助人者提示：自我披露前先问三件事——它服务谁的需要？是否帮助来访者理解自己或关系？披露后是否仍能回到来访者经验？若答案不清楚，就应保持节制。这一条也适用于 App 人设设计：系统可以有温度，但不应编造个人经历来获取信任；真人助人者可以适度分享，但必须可追溯到来访者利益。判断标准包括：披露是否简短、是否与当前主题直接相关、是否帮助用户减少孤立或形成新视角、是否会把注意力转移到助人者身上。若披露后用户开始照顾助人者、比较谁更痛苦，或偏离自己的体验，就需要及时收回焦点。', '["自我披露", "咨询边界", "理想化移情", "治疗师真实", "青少年咨询", "专业节制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 351, now()),
(100352, '治疗终结与复盘：结束不是完结，而是把功能还给来访者', 'Arianes 治疗后期提出“还需要来多久”，治疗师没有替他做终止决定，而是把结束治疗本身作为一次成长任务：问题不在于是否必须继续来，而在于来访者是否已经完成了想通过治疗为自己做的事。书中提醒，终结常会激活两类反应：担心治疗师不满自己的独立，或回避与治疗师分离的失落。因此治疗师既不应匆忙结束，也不应为了自己的失落延长治疗，而要帮助来访者讨论决定、检验联想、确认新的功能是否已经能在生活中运作。Arianes 最终把对父亲式照顾的需要转化为对侄子 Bobby 的照顾，并保留必要时再联系的通道。App 可将其设计为阶段复盘：我现在能独立处理什么？哪些旧防御还会出现？我如何把治疗中的理解迁移到现实关系？需要怎样的后续支持？终结不是治疗神话的圆满，而是把选择权与责任逐步还给来访者。这一条也可用于 App 的阶段性结案或低频随访设计：当用户状态好转时，不必制造依赖或继续挖掘所有问题，而应帮助其命名已经学会的能力、预判复发信号、确认现实支持者、约定需要时如何重新求助。复盘问题可以包括：我现在怎样理解最初的困扰？我学会了哪些不同回应？哪些情境仍容易把我带回旧模式？如果旧模式出现，我第一步能做什么？', '["治疗终结", "复盘", "自主性", "分离议题", "关系修复", "后续支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 352, now()),
(100353, '四类治疗功能：安抚、整合、恰当觉醒与诠释', '结论章将治疗师在移情关系中的功能概括为四类，可作为 App 咨询辅助的后台分类。第一是安抚：治疗师暂时承接来访者过强的正向或负向情感，不以惩罚回应挑衅，让情绪不至于压垮来访者。第二是整合：当来访者失去秩序感时，治疗师通过倾听、整理和连接，暂时帮助其恢复组织经验的能力。第三是恰当觉醒：当来访者的性格要素导致误解或伤害他人时，治疗师在时机成熟时温和面质，使其看到自己不愿承认的部分。第四是诠释：把当下行为与过去或当前关系的意义连接起来，让来访者用新的眼光理解自己。书中也提醒，这些技术没有固定层级，不能机械匹配某个诊断；同一个来访者在不同会谈中所需功能会变化。App 可据此给回复打标签：当前更需要承接、整理、面质还是解释？先判断来访者可承受度，再选择回应深度。这四类功能还能帮助避免“所有问题都用同一种语气回应”。例如用户情绪爆表时先安抚，叙述混乱时先整合，反复合理化伤人行为时才考虑恰当觉醒，已经具备反思能力时再做诠释。若顺序错了，深度解释可能变成压力，过度安抚可能固化回避，过早面质可能造成关系断裂。因此后台知识库可把每条回复先标注主要功能，再生成与用户承受度匹配的语言。', '["治疗干预", "情绪承接", "整合", "面质", "诠释", "咨询辅助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 353, now()),
(100354, '团体疗效因子地图：把关系改变看成多机制叠加', '【核心观点】团体之所以能促进关系成长，不是因为某一种神奇技术，而是多个疗效因子在同一场域中叠加：希望、普遍性、信息传递、利他、原生家庭关系的矫正性重现、社交技能、模仿、人际学习、凝聚力、情绪宣泄和存在性反思。把这些因子当作“地图”而不是清单，App 端就能避免把社群运营简化成打卡、倾诉或知识灌输。
【产品转化】设计社群或小组课时，可让每个环节对应一种机制：开场提供希望和共同语言；互动环节促进普遍性与互助；反馈环节让成员看见自己的影响；复盘环节把体验转为可迁移的行动。
【运营提醒】不同用户受益点不同：有人需要先被接纳，有人需要清晰反馈，有人需要在帮助别人时恢复价值感。知识库可提示运营者观察“哪些因子在这个群里被激活，哪些被忽略”，而不是只追求热闹或情绪释放。
【内容落点】适合做成后台的“机制标签”或运营检查表：本周内容是否只在传递知识，是否也创造了互相回应；用户是否只有表达出口，还是能收到反馈并尝试新行动；群体是否只是陪伴，还是逐渐形成规范和凝聚力。这样可以把心理教育从单篇文章升级为一套可观察、可迭代的关系场域设计。', '["团体疗效因子", "团体心理教育", "关系成长", "社群运营", "心理机制", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 354, now()),
(100355, '希望感来自可见的进步：让新成员看到“有人已经走过”', '【核心观点】希望不是空泛鼓励，而是“我也可能改变”的可见证据。团体中的成员处在不同阶段：有人刚加入、有人正在挣扎、有人已经走过一段路。新成员看到相似处境的人发生了真实进步，会比单纯听带领者解释更容易产生信心。带领者自身对团体有效性的稳定信念，也会影响成员是否愿意投入。
【产品转化】App 社群可以设计“进步证据墙”“阶段故事”“老成员给新成员的一句话”等轻量机制，展示具体、可信、非夸张的变化：学会求助、能表达感受、敢参加线下活动、减少回避。
【边界提醒】希望感不是承诺疗效，也不是制造励志压力。更适合表达为：有人曾经也困惑、羞耻、孤独，但通过持续参与、被支持和练习，获得了新的关系经验。对新用户而言，看到可达成的小变化，往往比听宏大口号更有力量。
【内容落点】希望还可以来自时间维度：提醒用户回看自己几周前与现在的差别，或让老成员讲述“我当时也不信这个练习有用，但后来发现自己能多停留十分钟”。这些细小证据比宏大成功故事更适合心理教育产品，因为它降低比较压力，同时提升自我效能。尤其要让故事保留普通人的犹豫和反复，避免把进步包装成线性胜利。', '["希望感", "同伴榜样", "康复叙事", "新成员引导", "社群氛围", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 355, now()),
(100356, '普遍性：从“只有我这样”回到“我属于人类”', '【核心观点】许多关系困扰会被孤立感放大：用户以为只有自己有羞耻、嫉妒、攻击性、依赖、疏离或奇怪幻想，于是更加不敢说。团体中的普遍性体验能把“我是坏的/怪的”松动为“这也是人类经验的一部分”。当成员听见他人也有相似担忧，并在安全氛围里被接纳，羞耻感会下降，连接感会提升。
【产品转化】App 端适合用匿名问题箱、相似经历投票、主题共鸣卡、去羞耻化文章来激活普遍性。例如：“你是否也会在关系里既渴望靠近又想逃？”让用户看到分布，而不是暴露个人隐私。
【运营提醒】普遍性不等于抹平差异。文化、性别、年龄、身份背景会影响成员能否感到“被包括”。因此，社群话术要同时呈现共同人性和差异尊重：不是“大家都一样”，而是“你的经验有其独特处，也并不使你孤立于人类之外”。
【内容落点】这一条尤其适合做成“你不是一个人”系列，但要避免把痛苦浪漫化。可用方式包括：展示匿名高频困扰、提供温和命名、邀请用户把秘密拆成“事实—感受—需要”三部分。目标不是让用户立刻公开最深秘密，而是让他们先获得一点点可说、可被理解的空间。这种呈现能同时降低羞耻并保护个人节奏。', '["普遍性", "去羞耻化", "孤独感", "匿名表达", "多元文化", "社群安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 356, now()),
(100357, '利他主义：帮助别人也是重建自我价值', '【核心观点】团体中，成员不仅通过被帮助而受益，也会通过帮助别人而恢复价值感。很多人进入关系成长场景时带着“我没有什么可提供”的自我评价；当他们的倾听、提醒、经验或一句真诚反馈真的帮到了别人，自尊和意义感会被重新点亮。利他的关键不是拯救，而是在接受帮助和提供帮助之间灵活切换。
【产品转化】社群可以设计互助型角色：欢迎新成员、经验回应、复盘伙伴、资源整理、情绪陪跑提醒等，让用户以小剂量贡献参与共同体。App 内容可强调“你不需要成为专家才可以有价值”，只要表达真实经验、提出一个好问题、见证别人，都可能成为支持。
【运营提醒】利他要避免滑向过度助人或抢救。好的互助结构应鼓励成员先照顾自己的边界，再提供有限、具体、可拒绝的帮助；同时让被帮助者也有机会回馈，避免固定的拯救者—受助者等级。
【内容落点】后台可为不同活跃度用户设计不同贡献入口：只点赞也算见证，回复一句“我懂”是陪伴，整理资源是服务，分享复盘是经验传递。贡献等级不应制造排名，而应帮助用户发现“我在关系里有影响力”。当用户长期只求被照顾，也可以温和邀请其尝试一次小回馈。', '["利他主义", "互助社群", "自我价值", "意义感", "助人边界", "同伴支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 357, now()),
(100358, '团体凝聚力：安全归属是改变的土壤，不是讨好式和谐', '【核心观点】团体凝聚力是成员对团体、带领者和彼此关系的吸引与信任：我被看见、被重视、被接纳，也愿意重视这个团体。它既本身有疗愈作用，也是其他机制发生的前提。没有足够归属感，成员很难冒险自我暴露、表达愤怒、接受反馈或尝试新行为。
【产品转化】App 社群的凝聚力可通过稳定节奏、清晰规则、可靠回应、共同语言和小组身份来建立。指标不应只看发言量，还要看成员是否愿意回来、是否提及具体成员、是否能在被触动后继续留在关系里。
【重要区分】凝聚力不是永远温暖、夸夸群或零冲突。真正有凝聚力的团体能容纳不同意见，并在冲突后继续沟通。过度追求表面和谐，可能压抑敌意，让关系停滞；过早、过猛的冲突，又可能在凝聚力尚未形成时撕裂团体。运营者要把握节奏：先稳住归属，再邀请真实。
【内容落点】凝聚力可被拆成四个可运营信号：成员是否愿意准时出现，是否愿意回应他人而不只发自己的内容，是否能在不舒服后回来说明，是否开始使用“我们”的语言。若群内只有热情欢迎却没有真实反馈，凝聚力可能停留在表层；若冲突频繁但无人离开并能复盘，反而可能是更成熟的连接。', '["团体凝聚力", "归属感", "心理安全", "冲突容纳", "社群留存", "关系氛围"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 358, now()),
(100359, '人际学习：看见意图与影响之间的差距', '【核心观点】关系成长的关键，不只是理解“我为什么这样”，还包括看见“我的行为在别人那里造成了什么影响”。团体像一个社会缩影：成员平时在外部关系里反复出现的互动循环，会在小组中重演，并被多人观察到。一个人可能主观上想靠近，却因为抢话、冷漠、讽刺、分析过度或退缩，让别人感到距离和压力。
【产品转化】App 可把人际学习转化为可练习的问题：我刚才的表达让你更想靠近还是远离？我以为自己在帮忙，你实际感到被支持还是被控制？当我沉默时，你会怎么理解我？这些问题帮助用户从“自我解释”进入“关系影响”。
【运营提醒】人际学习需要多个视角，而不是单一评判。不同成员对同一事件的感受可能不同，正是这些差异让用户看见他人的内在世界。社群内容应鼓励具体观察、感受和影响，而非人格标签。
【内容落点】后台可以给 AI 助手配置“意图—影响”提示：当用户解释自己动机时，追问别人可能收到什么；当用户抱怨别人反应时，邀请他回看自己前一步行为。这个机制也适合关系课程作业：记录一次互动中“我想传达什么、对方可能感到什么、我下次要怎样验证”。', '["人际学习", "社会缩影", "意图与影响", "关系反馈", "自我觉察", "社交技能"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 359, now()),
(100360, '此时此地：把当场发生的互动变成可迁移的学习', '【核心观点】“此时此地”不是只聊当下情绪，而是把团体现场正在发生的关系过程拿来观察、体验和理解。它有两个层面：第一，成员真实地在现场产生感受、靠近、回避、愤怒、羡慕或关心；第二，团体回看刚刚发生了什么，理解互动模式及其意义。只有体验没有反思，容易变成短暂强烈的情绪事件；只有反思没有体验，又会变成枯燥分析。
【产品转化】在社群运营中，当成员把话题转向外部人物时，可以温和拉回：“当你这样说时，群里的人有什么感受？”“你刚才选择沉默，和你在线下关系里的沉默像吗？”“这一次我们能不能试着不猜外部那个人，而是看看你和大家之间发生了什么？”
【使用边界】此时此地需要安全和节奏。它不是逼问隐私，而是帮助用户在真实互动中生成可迁移的学习：我如何表达、别人如何接收、我如何修复。
【内容落点】此时此地也能用于线上群：谁被频繁忽略，谁总在解释外部人物，谁只在别人痛苦时给建议，谁在被回应后消失。运营者不必把所有话题都拉回现场，但当外部故事反复出现且无法推进时，现场互动就是更好的材料。关键是用邀请式语言，而非审问式语言。', '["此时此地", "进程觉察", "体验与反思", "关系实验室", "小组复盘", "社群互动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 360, now()),
(100361, '反馈文化：具体、真诚、可承受地说出彼此影响', '【核心观点】有效反馈的目标，是让对方看见自己的行为如何影响关系，而不是给人格下判决。反馈太模糊，如“你挺好的”，难以促进改变；反馈太羞辱，如全面否定一个人，又会让对方防御或崩溃。更有用的表达是：描述具体行为、说出自己的感受、连接对方目标，并留下继续探索和修复的空间。
【产品转化】App 可提供反馈模板：①当你做/说……；②我感到……或我更想靠近/远离；③我猜这可能与你想要的关系目标相反；④你愿意听听大家怎么看吗？同时鼓励提问具体化：“我哪里让你难以靠近？”比“你喜欢我吗？”更可操作。
【运营提醒】反馈应随信任程度递进。早期先从观察和自我感受开始，少推测动机；只有在关系足够稳固时，才进入更深层模式。带领者要示范共情式反馈，并及时阻止嘲讽、标签化和堆积后的爆发式攻击。
【内容落点】反馈文化需要配套接收训练：用户不仅学习怎么说，也学习听到反馈时先复述、确认、暂停防御，再决定是否采纳。App 可提供“反馈后自我稳定”小工具，如呼吸、写下事实、区分行为和人格、选择一个可尝试的调整点。这样反馈才不会变成互相伤害。', '["反馈", "共情式反馈", "行为描述", "关系影响", "非标签化", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 361, now()),
(100362, '带领者的三项任务：维系结构、塑造文化、启动成员互动', '【核心观点】团体带领者不是每个问题的直接解答者，更像乐队指挥：知道何时发声、何时退后，帮助成员之间产生有效互动。其基本任务包括：创立并维系团体结构，建立适合成长的团体文化，推动疗效因子在成员互动中发生。带领者的态度比技巧更底层：关心、真诚、共情、文化调谐和稳定投入，是挑战能够被接收的前提。
【产品转化】App 端的社群运营者、课程带教或 AI 助手可被设计成“容器维护者”：提醒规则、照顾新成员融入、观察沉默者和垄断者、把外部故事转化为现场互动、鼓励成员互相回应，而不是所有人都只对管理员发言。
【行为准则】带领者无法“不影响”规范：迟到、忽略、过度主导、只回应某类表达，都会塑造文化。优秀带领者会有意识地强化自我暴露、直接沟通、尊重差异、互助和复盘，同时保护团体完整性。
【内容落点】在产品里，带领者任务可部分由规则、流程和 AI 提示承担：自动欢迎新成员，提醒匿名和保密，提示成员互相回应，识别连续沉默或过度发言。但核心判断仍需要人来把握：什么时候保护个体，什么时候保护团体；什么时候给建议，什么时候让成员之间生成答案。', '["带领者任务", "团体文化", "社群主持", "规范塑造", "互动设计", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 362, now()),
(100363, '规范与边界：保密、出勤、外部联系和同意是安全容器', '【核心观点】团体越鼓励真实表达，越需要清晰边界。很多新成员害怕被嘲笑、被迫暴露、隐私外泄，或在群体中失去自我。准备阶段需要提前解释：团体目的、参与方式、出勤期待、保密原则、外部联系、亚团体、危机例外和知情同意。边界的价值不是控制成员，而是让他们知道“这里发生什么、不会发生什么、例外如何处理”。
【产品转化】App 社群应有易懂的入群说明：不转述他人故事；只分享自己的体验；截图、私聊拉帮、二次传播需要明确禁止或说明；线下/私下联系要回到群内透明讨论；涉及身体接触、深度练习或敏感信息时需获得明确同意。
【运营提醒】单纯命令“不能做”效果有限。更好的方式是解释某行为为何损害共同目标：秘密联盟会让成员无法坦诚，隐私外泄会破坏安全，缺席会影响整个小组。规则越能连接到成长目标，越容易被内化。
【内容落点】可沉淀成入群前的“共同契约”：我可以选择分享多少；我不会截图传播他人的故事；我会尽量按约出现；我若与成员私下联系，会尊重对方并在必要时回到群内讨论影响。契约最好用问答和场景题呈现，而不是长篇制度，让用户知道规则在保护他们的表达自由。', '["边界", "保密", "知情同意", "社群规则", "入组准备", "外部联系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 363, now()),
(100364, '自我暴露与透明度：开放要服务关系成长，不是倾倒隐私', '【核心观点】自我暴露有治疗性，也有风险。成员的适度开放能带来普遍性、凝聚力和反馈机会；带领者的透明也能示范真实、正常化感受、拉近关系。但开放并不等于越多越好。判断标准始终是：这次暴露是否服务成员成长、关系真实和团体任务，还是在满足表达者的宣泄、控制、求关注或越界需求。
【产品转化】App 可把自我暴露设计成分层：轻度事实、当下感受、关系影响、深层脆弱。用户不应被要求一开始就说最隐私的内容；可以先从“我愿意分享的部分”开始。运营者或 AI 助手若进行自我揭示，应短、准、为用户服务，例如：“我注意到听到这里我有些担心，想确认你是否需要更多支持。”
【边界提醒】透明度要和保密、同意、角色清晰配套。带领者要等情绪平稳后再暴露，避免把未经处理的个人反应倾倒给成员；不确定是否合适时，应回到目标、影响和边界来判断。
【内容落点】知识库可给用户一套判断问题：我现在分享，是为了更真实地连接，还是为了获得即时安慰、证明自己、压倒别人？我分享后愿意听反馈吗？我是否尊重听众的承受度？对带领者则可提示：每次自我暴露后观察成员是否更能工作，而不是更关注带领者本人。', '["自我暴露", "透明度", "真实表达", "角色边界", "脆弱表达", "社群安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 364, now()),
(100365, '冲突处理：不急着灭火，把冲突转化为现实检验与修复', '【核心观点】冲突不是团体失败的证据，常常是关系学习的入口。有凝聚力的团体会鼓励成员在支持之外表达不同意见和不满；如果敌意被压下去，它会以冷漠、缺席、替罪羊或背后结盟的形式出现。真正关键的是：冲突中沟通不能中断，成员要为自己的表达负责，并在风暴之后继续保留关系。
【产品转化】App 社群遇到冲突时，不必立刻删除一切负面情绪，也不应放任羞辱。可引导四步：①暂停人格攻击；②请双方描述具体行为和影响；③询问各自真正重视什么；④把冲突连接到共同目标，如“我们如何既保留真实，又让这里可继续参与？”
【进阶提醒】有些冲突表面在争内容，深层可能是权力、被看见、被忽略、与带领者的不满，或偏离主要任务的次级满足。带领者要问：这个冲突让团体回避了什么？它是否能帮助成员看见自己的关系模式？
【内容落点】冲突后需要有“修通脚手架”：复述对方真正听到的影响，承认自己表达中的可负责部分，说明仍想留在关系中的意愿，商量下一次更好的提醒方式。对社群来说，最有价值的不是证明谁对谁错，而是让成员体验到：关系可以出现裂缝，也可以通过诚实、边界和责任被修复。', '["冲突处理", "关系修复", "现实检验", "替罪羊", "主要任务", "社群治理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 365, now()),
(100366, '支持与挑战平衡：先有接纳，再推动冒险与新行为', '【核心观点】支持和挑战不是对立面。没有接纳，挑战会被体验成羞辱或控制；没有挑战，支持会停留在安慰，无法推动新行为。团体工作的艺术在于：先让成员感到被关心、被理解、可留下，再邀请其面对回避、尝试表达、承受反馈、修复冲突。早期凝聚力越稳，后续越能进行更困难的人际工作。
【产品转化】App 端可用“支持—挑战双轨”设计：每次困难分享后，先有共情回应，再有一个可选择的小挑战。例如：“听起来你很受伤；如果你愿意，我们也可以一起看看，你沉默时别人可能怎么理解你。”对积极参与但回避冒险的用户，可逐步邀请更具体的表达；对按时出现但情感缺席的用户，可邀请描述此刻身体和关系感受。
【运营提醒】挑战要个性化、可拒绝、可复盘。面对高防御、羞耻重或文化上不习惯公开表达的人，节奏要慢；面对反复垄断、攻击或回避者，带领者要更清晰地把反馈连接到其目标。
【内容落点】后台可以把回应分成三档：稳定型回应用于情绪高峰，探索型回应用于用户开始好奇，挑战型回应用于关系足够稳且目标清晰时。比如同样面对“我不想说话”，早期可以接纳沉默，中期可以询问沉默的保护作用，后期可以邀请用户尝试说出一句真实感受。', '["支持与挑战", "心理安全", "冒险尝试", "新行为", "情绪承受", "小组带领"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 366, now()),
(100367, '会谈摘要与反馈监测：让团体学习有连续性', '【核心观点】团体中的重要体验常常太强烈，成员当下只能防御或生存，过后才有能力理解。会谈摘要能帮助成员重新看见关键互动，把“发生过的事”转化为可学习、可保存、可迁移的经验。持续反馈监测则让带领者不只依赖直觉，而能及时发现谁正在掉队、谁参与但不冒险、谁出席却情感缺席。
【产品转化】App 可以在小组课后生成隐私保护的复盘卡：本次主题、重要互动、可复习的关系观察、成员可自选的下一步练习。对个人层面，可提供轻量问卷追踪归属感、表达度、被理解感、冲突压力和行动尝试。对团体层面，可观察群内回应是否集中在少数人、是否出现沉默、是否有成员边缘化。
【边界提醒】摘要不是裁判判词，也不应泄露隐私。应避免姓氏和敏感身份信息，使用成员同意的安全传送系统；收集反馈后必须被使用，否则会削弱用户继续反馈的意愿。
【内容落点】摘要还可服务长期成长档案：用户能看到自己从“只讲事件”到“能讲感受”，从“听到反馈就退缩”到“能回来澄清”的变化。反馈监测则可帮助运营者发现隐性风险：高频发言者不一定参与深入，沉默者不一定没有收获，满意度高也不等于有挑战。数据要回到对话中使用。', '["会谈摘要", "反馈监测", "复盘", "连续性学习", "隐私保护", "实践证据"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 367, now()),
(100368, '类型不是判词：把它当成观察注意力流向的语言', '核心观点：心理类型更适合被理解为一套观察语言，而不是给人定终身的标签。OCR 第十章把类型分成两层：一层是一般态度，即注意力和心理能量更习惯流向客体，还是更习惯回到主体；另一层是功能类型，即一个人更常用思维、情感、感觉或直觉来适应生活。它描述的是“我通常怎样定向、怎样取样、怎样做判断”，不是“我本质上只能成为什么人”。

App 落地时，应把类型表达为倾向和假设：此刻我更被外界事实、关系反馈、机会和评价牵引，还是更被内在意义、个人原则、想象和安全感牵引？我正在用逻辑、价值、身体事实还是可能性来理解事件？这样，类型帮助用户看见自己的默认路线，而不是把选择权交给测验分数。

关系价值：当用户说“我就是这样的人”“TA 就是这种类型”时，可以引导他们改写为“我在这个场景里常这样反应”。类型越被当成观察镜头，越能增加选择；越被当成身份判决，越容易变成借口、审判或自我设限。

应用边界：如果后续要接入测评结果，建议始终用“可能更倾向于”而不是“你就是”。系统可以把类型结论和具体场景绑定，例如“在冲突中你更常先退回内在判断”，并要求用户举出反例。能找到反例，恰好说明类型没有夺走人的自由。', '["心理类型", "非标签化", "自我理解", "注意力流向", "人格成长", "App知识库"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 368, now()),
(100369, '外倾的礼物与风险：会顺应世界，也要把自己带回来', '核心观点：外倾不是“爱社交”的同义词，而是一种把兴趣、判断和行动优先连到客体与客观事实上的态度。它的礼物是现实适应力：能迅速读到环境需要，跟随机会、规则、他人反应和外部条件调整自己；在团队、市场、社交、执行场景中，这种能力很有价值。

风险在于，外倾若过度，会把“外面正在发生什么”当成唯一真实的东西。OCR 第十章提到，外倾者可能连身体状态和内在需要这种最直接的主观事实都忽视，直到疲惫、症状或亲近者的反馈出现，才发现心理已经失衡。关系中也容易出现一种误会：外倾者以为自己只是在回应现实，伴侣或朋友却感到 TA 总是被工作、社群、机会和他人评价带走。

App 可以给外倾倾向用户三个回收问题：第一，外界要我做什么？第二，我的身体和情绪正在说什么？第三，如果不急着适应别人，我真正想保留什么？这样既不否定外倾的行动力，也防止用户把自我照顾误认为自私或低效。

应用边界：外倾成长的重点不是减少关系或机会，而是在行动前后留出一个回到主体的停顿。系统可在用户连续加班、频繁社交、强烈追逐反馈时提醒：今天有没有一个决定不是为了回应外界，而是为了照顾真实需要？', '["外倾", "客体定向", "自我照顾", "身体觉察", "关系平衡", "过度适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 369, now()),
(100370, '内倾的礼物与风险：能守住主体，也要检验外界反馈', '核心观点：内倾不是“孤僻”或“不合群”，而是心理能量从客体退回主体，先由内在立场、意义、想象、原则或感受来决定反应。它的礼物是独立、深度和不轻易被环境裹挟：当外界声音很大时，内倾能保护个人判断，保留对复杂内在经验的敏感。

风险在于，内倾若过度，客体容易被体验成压力、干扰或威胁。第十章讲到，内倾类型面对客体时常有自我坚守与防御倾向，外在表达也可能显得冷漠、隐秘、犹豫或不易理解。关系中，这常被误读成“不在乎”“不信任”“高冷”；而内倾者本人可能只是还没有把内在过程翻译成别人能听懂的语言。

App 可以把内倾成长设计成双向练习：一边允许用户先安静、书写、整理自己的主观事实；一边提醒用户把一个内在结论拿到外界小范围验证。可用句式是：“我需要一点时间整理，但我会回来告诉你我的想法。”这能同时保护主体空间和关系连接。

应用边界：内倾成长的重点不是强迫自己外向，而是把内在经验做成可沟通的材料。系统可鼓励用户先用笔记保存复杂想法，再选择一句最重要的话说给对方听。只要关系能收到信号，沉默就不必被误解为拒绝。', '["内倾", "主体定向", "表达练习", "关系误读", "心理边界", "自我验证"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 370, now()),
(100371, '四种功能：思维、情感、感觉、直觉是四种取样方式', '核心观点：功能偏好不是智商、道德或能力等级，而是人理解世界时常用的取样方式。思维关心概念、因果、原则和一致性；情感关心价值、喜欢/不喜欢、关系意义和重要性排序；感觉关心当下事实、身体刺激、细节和可观察材料；直觉关心可能性、趋势、象征和尚未展开的图景。每种功能都可能以外倾或内倾方式出现，所以不能把“思维=内倾”“情感=外倾”简单等同。

App 端可以把功能用于冲突复盘：我现在的证据主要来自哪一种功能？我是在讲道理，还是在讲重要性？我是在抓事实，还是在追可能性？被我忽略的功能会提出什么问题？例如，思维强的人在伴侣沟通中可能需要补一句“这件事对你意味着什么”；情感强的人在决策中可能需要补一栏“可验证事实是什么”。

关系价值：功能语言能把“你太冷血/你太情绪化/你太死板/你想太多”翻译成“我们正在用不同通道取样”。这种翻译能降低羞辱感，让对话从人格攻击转向信息互补。

应用边界：功能识别不应变成新的优劣排序。每一种功能在压力下都会失真：思维可能变成冷酷辩护，情感可能变成迎合或审判，感觉可能变成短视，直觉可能变成空想。知识库要强调“补信息”，而不是给某种功能封王。', '["功能偏好", "思维", "情感", "感觉", "直觉", "冲突复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 371, now()),
(100372, '优势功能不是全人格：专长带来适应，也会制造盲点', '核心观点：人会把最顺手、最被奖励的功能发展成优势功能。它让我们在社会中获得位置：有人靠清晰思维解决问题，有人靠情感判断维系关系，有人靠感觉细节稳住现实，有人靠直觉发现机会。问题在于，当一个人把自己完全等同于优势功能，就会把其他部分看成麻烦、低效或不成熟。

OCR 第二章借席勒讨论“功能分化”的代价：为了发展某种能力，其他功能可能被压低；这种片面性对集体有用，却可能让个体变得贫乏。第七章也指出，与主导功能完全一致会帮助人满足集体期待，但也可能带来个体退化。

App 可把这条做成“我被奖励的那部分不是全部的我”提示。用户在职业、亲密关系或自我评价中，如果长期只用一种能力证明价值，就需要问：我最骄傲的能力正在排斥什么？我是否把休息、依赖、情绪、想象或身体感受看成没用？成长不是否定优势，而是让优势不再垄断人格。

应用边界：这条特别适合职业倦怠和亲密关系失衡。用户常把最能带来成就的能力当成唯一身份，久而久之就无法承认自己也需要被照顾、需要不确定、需要玩耍或需要停下。系统可邀请用户每周练一次“不被绩效奖励但能恢复完整感”的小行动。', '["优势功能", "人格完整", "职业压力", "自我价值", "功能分化", "整体性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 372, now()),
(100373, '劣势功能会粗糙地回来：别只靠更用力的优势功能', '核心观点：被长期压抑、未分化的功能不会消失，只会以更原始、笨拙或失控的方式回来。一个高度理性的人可能在亲密关系里突然被情绪淹没；一个习惯照顾感受的人可能在事实和边界面前混乱；一个追逐可能性的人可能忽视身体和日程；一个依赖感觉事实的人可能害怕抽象意义或未来变化。

OCR 第七章谈到，心理能量越集中在主导功能，其他功能获得的能量越少，久而久之会沉入无意识并产生反抗；第十章也描述无意识功能具有更古老、更原始的特征。App 不应把这种反弹解释成“人格崩坏”，而应解释为被冷落的功能在要求被看见。

落地练习：当用户反复在同一处失控时，不急着让 TA 更努力使用优势功能，而是询问“这里缺少哪种功能的帮助？”理性用户可练习命名感受，情感用户可写事实清单，直觉用户可做身体扫描，感觉用户可列三种未来可能。

应用边界：劣势功能训练要小剂量、低羞耻、可重复。不要要求一个长期压抑感受的人一次说清全部创伤，也不要要求一个现实感薄弱的人立刻制定完美计划。更有效的是给一个可完成的微练习，让被冷落的功能逐渐进入意识。', '["劣势功能", "未发展功能", "无意识补偿", "情绪失控", "自我调节", "人格发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 373, now()),
(100374, '辅助功能是安全通道：成长不必直冲最脆弱处', '核心观点：人格成长不是把人一下推到最不擅长、最痛苦的功能里。OCR 第十章在“主要功能和从属功能”中指出，实际生活里除主导功能外，常有相对无意识的辅助功能；发展可以经由第二功能来保护意识立足点，再逐步接近更深的无意识内容。

这对 App 很实用：如果用户是理性型，不一定一开始就要求 TA 大量暴露情绪，可以先用感觉或直觉作为桥梁——记录身体信号、画出情境图、列出可能性，再慢慢进入感受和需要。如果用户是非理性型，也不必立刻否定 TA 的体验，而可训练更稳定的理性辅助功能：给体验命名、排序、核对证据、做小计划。

关系价值：伴侣或咨询式对话中，不要用“你为什么不能直接表达感受/直接讲逻辑”逼迫对方跳到最弱处。更好的提问是：你比较容易从哪个入口靠近这件事？事实、价值、身体、可能性，哪一个现在最安全？这样成长更温和，也更可持续。

应用边界：辅助功能也能帮助 App 控制干预强度。面对高压用户，系统先寻找最安全的入口，而不是直接追问最痛点。这样可以减少防御和依赖，把成长保持在用户仍能自我承载的范围内，避免把“洞察”变成新的压迫。', '["辅助功能", "成长路径", "心理安全", "咨询提示", "功能训练", "温和改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 374, now()),
(100375, '投射：关系里的“我看见你”常混有“我放到你身上的东西”', '核心观点：投射可以理解为把主观内容放进客体，于是我们以为自己只是在看见对方，实际上也在看见自己尚未承认的情绪、愿望、恐惧或价值。OCR 第十一章定义投射时指出，主观内容离开主体并被具体化到客体中，可能是痛苦和不相容的内容，也可能是正面价值；第一章也谈到集体态度会借投射来思考和感受，从而妨碍客观看见个体差异。

App 端可用于关系误读：当用户反复说“TA 一定看不起我”“所有人都在控制我”“这个人完美无缺”时，不急着否定，而是温和拆分三层：可观察事实是什么？我赋予它的意义是什么？这个意义是否也反映了我自己的恐惧、渴望或自卑？

关系价值：识别投射不是把责任全拉回自己，也不是替对方开脱。它只是让用户在行动前多一个校准步骤：我看到的对方，有多少来自对方实际行为，有多少来自我内在尚未被安放的内容？这样能减少读心、理想化、妖魔化和过度防御。

应用边界：投射校准要保持双重视角。系统既要帮助用户收回可能属于自己的内容，也要允许对方确实有伤害行为。可用提示语：“我们先核对我加上的解释，同时也保留对事实和边界的尊重。”这样不把自我反思变成自我否定。', '["投射", "关系误读", "读心校准", "理想化", "妖魔化", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 375, now()),
(100376, '类型冲突：双方看到的常是彼此最不利的外观', '核心观点：类型差异常让人误以为对方“不讲理”。外倾更容易相信客观事实、环境要求和外部反馈；内倾更容易相信主体立场、内在图像和个人意义。第十章外倾/内倾的描述，以及对外倾思维与主观思维冲突的讨论，都显示：两种定向一旦互相评判，常会把对方看成入侵者或偏执者。

App 可把冲突翻译成两个问题：第一，对方正在服务哪一种现实——外部事实、他人期待、共同规则，还是内在原则、个人意义、长期图景？第二，我是否只看见了对方类型的低级表现，而忽略了它保护的价值？例如，外倾者催促行动，可能是在保护现实进度；内倾者要求暂停，可能是在保护判断质量。

沟通模板：不要说“你太外向/太内向”，而说“我听见你很重视外部反馈；我这边需要一点时间确认内在判断”。类型冲突的修复，不是证明谁更正常，而是让两种现实都获得位置。

应用边界：类型冲突最适合做成对话前的翻译器。系统可分别生成两种语言：给外倾者的是“请留一点空间给对方整理内在判断”；给内倾者的是“请给对方一个可见的时间点和外部信号”。双方都不必放弃自己，只需增加可理解性。', '["类型冲突", "内外倾", "关系沟通", "观点差异", "冲突翻译", "非人格攻击"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 376, now()),
(100377, '对立形态：越片面，越容易被相反面夺回方向盘', '核心观点：“对立形态”可用于解释很多自我管理失败：当意识生命长期被一种极端、片面的倾向支配时，被排除的对立面会在某个时刻变得有力量，反过来抑制甚至打破原有控制。它不需要被神秘化，可以理解为心理系统的补偿和反弹。

App 中常见例子包括：长期讨好的人突然爆发；长期理性控制的人在压力下迷信直觉或陷入灾难想象；长期独立的人在亲密关系中出现强烈依赖；长期追求自由的人被生活细节拖垮。问题不在于这些人“变了一个人”，而在于被排除的需要、情绪或功能积累到必须出现。

落地提醒：当用户说“我怎么会做出完全相反的事”，可以引导 TA 回看最近一直在压下什么：愤怒、疲惫、依赖、秩序、身体、意义、关系需要。越早承认对立面，越不需要等它以失控方式出现。成长不是永远站在一边，而是学习在张力中保持可调节。

应用边界：对立形态适合做早期预警，而不是事后责备。系统可让用户定期填写“我最近最不允许自己体验什么”，并把答案当作需要照顾的信号。越能在小幅度时承认对立面，越不容易等到关系破裂或身体耗竭才被迫转向。 先照顾小信号。', '["对立形态", "心理补偿", "片面性", "反弹", "自我调节", "人格整合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 377, now()),
(100378, '阴影与自身：成长不是美化自我，而是看见被排除的我', '核心观点：OCR 第十一章区分自我与自身：自我是意识领域中心，自身则包含更广阔的心理整体，包括无意识。文本还提到阴影作为被自身发现的部分。对 App 来说，这一观点可以转化为非神秘化的成长语言：我并不等于我愿意承认的那一小块；那些被我排除、否认、讨厌或投给别人的部分，也可能属于我的心理整体。

阴影不必被解释成“邪恶人格”，更适合看作未被承认的能力、欲望、脆弱、攻击性、依赖、嫉妒、野心或创造力。它们被压下去时，常在关系里以强烈反感、过度理想化、失控爆发或重复吸引的形式出现。

App 练习可以是：我最受不了别人哪一点？这点是否也提醒我某种被禁止的自己？如果把它从道德审判改写为一种能量，它原本想保护什么？这种练习不是纵容伤害行为，而是让用户把被排除的心理材料带回可观察、可选择、可负责的位置。

应用边界：阴影工作需要温和语言。知识库不宜说“你其实也很坏”，而应说“你强烈排斥的东西可能携带某种被禁止的生命力”。当用户能把阴影从羞耻对象改写为可负责的能量，就更容易同时保持边界和自我接纳。 练习要慢。', '["阴影", "自身", "自我", "无意识", "人格整合", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 378, now()),
(100379, '人格发展：从同一化到分化，再到更有弹性的整合', '核心观点：第十一章把分化解释为把某种功能从混合状态中分离出来，使它能够独立、清晰地运作。没有分化，人会把感觉、情感、思维、直觉混成一团：感受像事实，想象像证据，价值判断像客观规律。分化让人先看清“这是情绪、这是事实、这是推论、这是直觉”。

但分化不是终点。第二章和第七章提醒，过度分化会把人变成单一功能的代表：会思考却不会感受，会照顾却不会判断，会执行却不会想象，会预感却不会落地。健康发展更像两步：先分清功能，减少混乱；再让不同功能重新合作，恢复整体性。

App 可把它做成“先分栏，再整合”的工具。面对一件关系事件，用户先分别写：事实/身体感觉/情绪价值/想法推论/未来可能；然后再问：如果这些信息都是真的一部分，我下一步最小、最负责任的行动是什么？这种练习既避免情绪和事实混淆，也避免用冷冰冰的分析切断生命经验。

应用边界：这条可与情绪日志、冲突复盘、认知重评联动。不同之处在于，它不仅问“想法是否准确”，还问“哪一种心理功能正在说话，哪一种没有被邀请”。当不同功能都获得位置，行动往往更稳，也更有人味。', '["分化", "人格发展", "功能整合", "事实感受分离", "自我观察", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 379, now()),
(100380, '类型语言的边界：服务关系成长，不服务诊断和宿命', '核心观点：心理类型进入 App 知识库时，最重要的边界是“用于观察，不用于审判”。它可以帮助用户发现自己的定向、功能偏好、投射、劣势功能和关系误读，却不应被包装成命运说明书、灵魂等级或诊断标签。OCR 第十章已经多次提示，纯粹类型只是概括出来的典型图像，现实个体常有主导、辅助、意识和无意识功能的复杂组合。

App 的回应可采用四步：一，先描述情境中的反应，不急着命名类型；二，询问注意力流向外界还是内在；三，识别主要使用的功能和缺席的信息；四，把结论落到一个可练习动作，例如核对事实、表达感受、补充边界、休息、行动或等待。

这样做能避免和 v10 中已有的“人格测验只能作线索”“不要用类型限制人”等主题重复成空泛提醒，而是提供荣格类型独有的操作框架：态度—功能—投射—劣势功能—整合。类型的价值不在于更快定义人，而在于让人更慢、更准确、更温柔地理解自己和他人。

应用边界：最终呈现时可把“类型”放在二级解释，而不是首屏结论。先回应用户的具体困扰，再提供类型视角作为可选镜头。这样既能利用荣格类型的解释力，又避免用户把复杂人生缩减成四个字母或一个标签。', '["类型应用", "非诊断", "App问答模板", "关系成长", "人格测评边界", "荣格类型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 380, now()),
(100381, '内疚与羞耻：从“我是坏人”回到“我做错了什么”', '核心观念：健康的后悔关注行为和修复，破坏性的内疚/羞耻则把行为扩展成身份判决。伯恩斯指出，典型链条是：我做了不符合标准的事 → 这证明我是坏人/无价值的人 → 如果被发现别人会鄙视我 → 我很危险或该受惩罚。App 可引导用户把这条链拆开：事实是什么？我真正需要负责的部分是什么？有没有放大、乱贴标签、罪责归己或过度“应该”？如果我关心的是价值和关系，下一步可做的修复行为是什么？例如道歉、补偿、解释、学习新技能、设提醒、请求反馈。练习中要保留责任感，但移除人格审判：用户可以承认行为造成影响，也可以不把自己定义成坏人。这样，内疚从瘫痪性的自我惩罚转为有方向的修复行动。

使用建议：App 可把内疚处理分成“责任澄清”和“修复计划”两个页面。责任澄清包括：我是否真的违反了自己的价值？伤害的具体影响是什么？哪些后果是我造成的，哪些属于他人解释或环境限制？修复计划包括：我能否承认影响、道歉、补偿、改变流程或学习新能力？如果用户只停留在“我活该难受”，系统可提醒：惩罚自己并不等于负责，真正的负责是减少再次伤害的概率。对于羞耻强烈的用户，还要把“别人可能怎么看我”与“我实际能做什么”分开，避免读心和灾难化让修复停摆。', '["内疚", "羞耻", "后悔", "责任边界", "修复行动", "自我宽恕"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 381, now()),
(100382, '复发预防：把工具箱留在情绪变好之后', '核心观念：情绪好转后，最容易把练习丢掉；而伯恩斯反复强调，认知工具之所以能维持效果，是因为人学会了在下一次波动时处理想法、活动和关系。App 的复发预防条目可做成一页“个人情绪维护计划”：1）早期信号：情绪评分连续上升、活动M/P下降、睡眠紊乱、开始孤立、频繁出现应该/标签/灾难化；2）高风险场景：被批评、任务拖延、关系拒绝、工作比较、独处周末；3）首选工具：三栏日志、活动计划、反拖延实验、语言柔道、愤怒预演、垂直箭头；4）支持清单：可联系的人、咨询资源、需要暂停或减负的事务；5）复盘问题：这次旧规则又是什么？我下次怎样更早发现？它应被表述为维护系统，而不是“保证永不低落”。真正的预防，是在平稳期也保留观察、记录、行动和求助的通道。

使用建议：维护计划可设置为每月一次轻复盘，而不是等到危机时才启动。复盘问题包括：最近哪个旧规则最活跃？我是否减少了让我有掌控感或愉悦感的活动？我是否又开始用“总是、必须、完了、没救了”这类绝对语言？我是否停止联系支持者？App 可根据用户历史记录推荐最有效的三项工具，例如某人对三栏法反应最好，另一个人对活动计划更敏感。复发预防还应允许“部分复原”：即使只完成一个小行动、写下一条自动想法、联系一个人，也是在打断下滑链条，而不是非要一次恢复到最佳状态。', '["复发预防", "维护计划", "早期信号", "工具箱", "情绪监测", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 382, now()),
(100383, '心理学不是常识包装：先用科学态度校准直觉', '核心观点：迈尔斯在第1章把心理学入门放在“批判性思考”上，而不是先给一堆结论。人的直觉有价值，但容易受后见之明和过度自信影响：事情发生后，我们能为相反结果都编出“早就知道”的解释；在判断自己知道多少、看人多准、预测多稳时，也常比证据更自信。

App落地：当用户提出“我就是知道TA在骗我”“我早就看出自己会失败”这类判断时，知识库可以提醒系统先把直觉降级为假设：1）我看到了什么可观察事实；2）还有哪些替代解释；3）什么证据能支持或推翻我的判断；4）若要行动，最小可逆步骤是什么。

使用边界：批判性思维不是否定感受，也不是把用户变成冷冰冰的数据机器，而是帮助用户在感受强烈时不急着下终局判决。尤其适合关系误读、职场评价、自我否定、网络心理测试和“玄学式人格判断”的场景。

后台提示：这条可作为所有问答的“证据闸门”。当用户要求人格判断、关系判断或原因归因时，先输出低威胁问题，而不是直接反驳。推荐句式是：“这个直觉值得听见，我们也把它放进待验证区。”这样既保护用户体验，又减少把常识、热门说法或心理测试结果当作事实。', '["心理学基础", "科学态度", "批判性思维", "后见之明偏差", "过度自信", "事实核对", "App问答模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 383, now()),
(100384, '天性与教养共舞：遗传倾向不是命运判决', '核心观点：第4章反复校准“基因还是环境”的二分法。基因提供生物蓝图，解释人类共同性与部分个体差异；环境、文化、父母、同伴和当前情境则不断参与塑造。更准确的说法不是“人格百分之多少来自基因、百分之多少来自环境”，而是基因会影响我们进入何种环境、别人如何回应我们，而环境又会放大、缓冲或改写遗传倾向。

App落地：当用户说“我天生就是焦虑/懒/不会社交，所以没办法”时，可回应为：你可能有某些较敏感的气质或反应阈值，但这不是固定剧本。下一步不是否认先天差异，而是设计更适配的环境：减少高触发场景、选择更支持的人际反馈、用小步练习建立新的经验。

避免误用：不要把遗传解释成宿命，也不要把环境解释成“只要努力就能变成任何样子”。知识库可保留一句后台原则：天性通过教养实现，教养也总是作用在具体天性之上。

后台提示：适合用于气质、亲子、人格和情绪敏感度解释。系统可以把“我改不了”翻译成“我需要更合适的改变路径”。例如高敏感用户不必追求变得迟钝，而是学习提前识别刺激、恢复能量、选择低消耗社交和逐步扩大容忍窗口。', '["天性与教养", "行为遗传学", "基因环境互作", "气质", "人格发展", "非宿命", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 384, now()),
(100385, '选择性注意：你没看到，不等于它不存在', '核心观点：第3章和第6章提醒，意识注意像一束光，只能照亮体验中的有限部分。大量感觉信息在意识外被加工；当我们专注某个任务时，会忽略旁边显眼的变化，甚至对“换人”“换物”视而不见。第6章进一步说明，觉察微弱信号不只取决于刺激强度，也取决于期望、动机、警觉水平和当下任务。

App落地：在用户复盘冲突或自责时，系统可提示“注意力截图不是全景图”。可引导用户补三类漏看信息：当时我正在专注什么？我可能忽略了哪些环境线索？我现在的期待是否让我更容易只看见威胁、拒绝或失败？这能降低读心、灾难化和选择性证据收集。

应用价值：这条适合接入焦虑、亲密关系和学习效率场景。对焦虑者，可解释为什么人会过度扫描危险；对学习者，可提醒多任务会降低反应；对关系误解者，可提示“我当时没有注意到”比“它一定没发生”更准确。

后台提示：这条也能支持“记录而非争辩”的产品交互。系统可鼓励用户在情绪过后补写第二版复盘：第一版记录当时注意到的东西，第二版加入旁观者、时间线和环境信息。两版并列能让用户看见注意力如何被任务和情绪收窄。', '["注意力", "选择性注意", "信号检测论", "变化盲视", "知觉定势", "焦虑校准", "关系误读"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 385, now()),
(100386, '毕生发展视角：别用成人逻辑要求每个年龄段', '核心观点：第5章把发展心理学定义为研究从婴儿到老年生理、心理和社会性变化的学科，并提出三组核心问题：天性与教养、连续性与阶段性、稳定性与变化性。儿童不是缩小版成人：认知、依恋、同伴关系、身份探索和成年任务都会随年龄改变。皮亚杰的阶段理论虽被修正，但“儿童通过与世界互动建构知识”的洞见仍有价值。

App落地：亲子和自我成长问答中，不宜把所有问题都解释成“性格不好”或“道理没讲透”。儿童行为常与发展能力有关，青少年冲突常夹杂身份探索和同伴认同，成年焦虑常与亲密、工作、贡献和独立任务有关。系统可先问：这个人处在人生哪个阶段？此阶段的能力、任务和压力是什么？

提醒：发展视角不是纵容伤害行为，而是把“能不能做到”和“愿不愿意做到”分开。对于教育、亲子沟通、成年转型、自我接纳场景，它能让建议更符合年龄任务。

后台提示：这条可成为亲子模块的基础校准。面对“孩子故意气我”“青春期就是叛逆”等表达，系统先不急着给管教技巧，而是提醒用户检查能力成熟度、依恋需要、同伴压力和自主任务，再把规则设计成清晰、稳定、可执行的下一步。', '["发展心理学", "毕生发展", "儿童心理", "依恋", "青春期", "身份发展", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 386, now()),
(100387, '学习三通道：行为改变不只靠意志，还靠联结、结果和榜样', '核心观点：第7章把学习定义为经验导致的相对持久行为变化，并概括三类主要学习：经典性条件作用、操作性条件作用和观察学习。经典条件让人把两个刺激联结起来，形成自动反应；操作条件让人把行为与结果联结起来，重复被强化的行为、减少受惩罚的行为；观察学习让人通过榜样和模仿习得新行为。

App落地：用户想改变拖延、暴食、回避、冲动消费或关系反应时，不要只说“坚持”。可从三问拆解：1）什么刺激自动触发了情绪或欲望？2）这个行为获得了什么即时奖励或逃避了什么不适？3）我身边或屏幕上有哪些榜样正在教我这样反应？然后设计替代刺激、替代奖励和可模仿的微榜样。

特别价值：这条能把行为改变从道德评价转为机制分析。它也适合解释创伤触发、恐惧泛化、坏习惯维持、亲子模仿和媒体影响，但输出时要避免把复杂问题简化成单一条件反射。

后台提示：在生成行动方案时，可把每个建议都标注属于哪类学习机制：替换触发是经典条件思路，重新安排奖励是操作条件思路，找可模仿对象是观察学习思路。这样能让用户明白“改变环境”不是偷懒，而是直接作用于学习机制。', '["学习理论", "经典条件作用", "操作性条件作用", "观察学习", "行为改变", "榜样", "习惯机制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 387, now()),
(100388, '强化塑造行为：奖励具体进步，比空泛批评更能改变', '核心观点：第7章的操作性条件作用为App端行为改变提供了底层语言。行为会受结果塑造；强化不是“奖品”本身，而是任何能增加某行为出现频率的后果。塑造复杂行为时，应从接近目标的小步开始强化；间歇强化会让行为更难消退，这解释了赌博、刷手机、偶尔被回应的关系依赖为什么特别顽固。

App落地：目标设计可遵循四步：把目标改成可观察行为；记录行为出现的条件；对期望行为给出及时、具体、低成本强化；当行为稳定后，逐渐从外部奖励转向内在奖励。对亲子和团队反馈，可把“你怎么这么懒”改成“你今天按时开始了10分钟，这一步值得保留”。

边界：惩罚能暂时压制行为，却未必教会替代行为，还可能带来恐惧、逃避或无助。知识库可提示：如果必须设后果，也要同时强化想要的行为；否则用户只知道“不要做什么”，不知道“该怎样做”。

后台提示：适合做成习惯追踪、亲子反馈和职场管理的统一规则。奖励要具体、及时、贴近行为，而不是评价整个人。系统可自动把人格评价改写为行为反馈，如把“你太拖延”改为“你在19:30打开文档并写了第一段，这是可复制的启动动作”。', '["强化", "行为塑造", "操作性条件作用", "间歇强化", "自我管理", "亲子教育", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 388, now()),
(100389, '记忆不是录像：它会编码、提取，也会建构和改写', '核心观点：第8章用信息加工模型说明，记忆包含编码、存储和提取三个过程；当代研究还强调工作记忆的主动加工。记忆不是把现实逐帧录下再原样播放，而是在旧信息、当前线索、情绪状态和他人提示参与下重新建构。错误信息、想象和来源混淆，都可能让人真诚地相信并未发生或已经变形的细节。

App落地：当用户反复复盘“当时到底是不是这样”或在人际争执中坚持“我记得很清楚”时，可提醒：真诚不等于完全准确。建议先记录原始记忆，再区分亲眼所见、别人告诉我的、我后来推断的、我在情绪中想象的。对重要冲突，可使用“事实时间线”而不是“谁记得更对”的争夺。

敏感场景：涉及创伤、儿童经历、法律指控或严重伤害时，App不应诱导用户“恢复记忆”或替用户断定真伪，只能做稳定、记录、求助和证据边界提示。

后台提示：这条可服务“冲突复盘”和“创伤叙事”两类场景。对普通冲突，鼓励尽早写下原始记忆并保留不确定性；对创伤相关内容，避免追问细节和暗示性问题，优先稳定当下、尊重用户节奏，并提醒必要时找专业人员陪伴整理。', '["记忆", "工作记忆", "记忆建构", "错误信息效应", "源头遗忘", "事实时间线", "非诱导"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 389, now()),
(100390, '有效学习不是多看几遍：间隔、意义化和自测更可靠', '核心观点：第8章不仅讲记忆模型，也给出学习策略。需要努力加工的信息，靠一次性猛背很容易快速遗忘；分散学习、间隔复述、过度学习、把新材料与已有知识连接、组织成意义结构、主动回忆和自我测试，更能提升长期保持。系列位置效应提醒我们，中间部分更容易被遗忘，学习计划要特别照顾这些“中段盲区”。

App落地：学习类功能可把建议做成流程：先浏览并发问，再阅读；读完马上合上资料复述；用自己的话解释；隔一段时间再测；把错题和卡住处作为下一轮学习入口。对“我看了很多遍还是忘”的用户，重点不是责备努力不足，而是把重复观看改成主动提取。

边界：记忆术、缩写词和图像联想适合陌生材料，但不能替代理解。系统可优先鼓励“能不能教给别人”作为检验，而不是只问“看起来熟不熟”。

后台提示：产品上可把“学习完成”从阅读时长改成提取证据：能否列出要点、能否解释给新人、能否隔天答对。对于焦虑型学习者，系统要强调短而分散的复习比长时间硬扛更有效，避免把学习建议变成新的自责来源。', '["学习方法", "间隔效应", "主动回忆", "自我测试", "意义编码", "SQ3R", "长期记忆"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 390, now()),
(100391, '思维捷径有用也危险：别让启发式替你做终审', '核心观点：第9章把人类思维写成理性与非理性的混合。概念、原型、算法、启发式和顿悟帮助我们快速解决问题；但代表性启发会让人忽视基础概率，易得性启发会让鲜活案例压过统计事实，过度自信会让人高估判断准确度，信念偏差和信念保持会让人更容易接受符合原有立场的“证据”。

App落地：在决策、关系判断、风险恐惧和自我评价中，可给用户一个“捷径复核”模板：我是不是被一个典型形象带走了？我是不是因为最近看到某个案例，就高估它的概率？有没有基础数据或长期模式？如果相反结论成立，我会找哪些理由？把这些问题做成轻量检查，比直接告诉用户“你有偏见”更容易被接受。

价值：启发式不是敌人，它是日常快速判断的工具。App要做的是在高代价决策、强情绪判断和长期关系结论前，提醒用户把捷径提交给证据复核。

后台提示：这条可接在“强判断”之后：一定、永远、所有人、肯定、没救了。系统检测到绝对化语言时，可启动概率化和反例搜索，而不是直接要求用户乐观。推荐输出是“这个判断可能在提醒风险，我们给它加一个概率和证据等级”。', '["思维与判断", "启发式", "代表性启发", "易得性启发", "过度自信", "信念保持", "决策校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 391, now()),
(100392, '动机不是单一意志：需要、诱因、唤醒和意义共同推动行动', '核心观点：第11章把动机定义为激发行为并使之指向目标的需要或欲望。人不是只靠“想不想努力”行动：生理需要会形成驱力，环境中的诱因会拉动行为，过低刺激会让人无聊，过高刺激会造成压力，人还会追求最佳唤醒、归属、尊重、自我实现和超越自我的意义。工作动机部分进一步说明，工作既满足生存，也提供身份、关系、能力感和意义感。

App落地：当用户说“我没有动力”时，不要只灌鸡汤。可分层排查：基础睡眠、饮食和安全是否被破坏？目标是否太远、诱因是否只奖励短期逃避？任务难度是否高到焦虑或低到无聊？是否缺少归属、被看见、成长或贡献感？

建议模板：把大目标改成能产生适度唤醒的小挑战；增加即时反馈；把行动连接到具体关系或价值；避免把所有低动力都解释成意志薄弱。

后台提示：动机模块可避免单点归因。若用户长期低动力，先检查身体资源和压力负荷；若只是某任务低动力，再看任务难度、反馈延迟和意义连接。系统可输出“动力处方”：降低启动门槛、增加即时反馈、安排同伴监督、连接长期价值。', '["动机", "需要层次", "驱力", "诱因", "最佳唤醒", "工作动机", "意义感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 392, now()),
(100393, '情绪有身体也有解释：先降唤醒，再看标签是否准确', '核心观点：第12章把情绪拆为三部分：生理唤醒、外显行为和意识体验。不同理论分别强调身体反应、同时发生的大脑加工，以及“唤醒+认知标签”。研究还提示情绪有双路径：某些恐惧和喜欢会经由快速低通道先于有意识解释出现；复杂情绪又深受评价、记忆和预期影响。

App落地：情绪支持不宜只问“你为什么这样想”，也不宜只让用户深呼吸。更好的顺序是：先识别身体唤醒（心跳、呼吸、肌肉、胃部、冲动）；用低刺激方式降唤醒；再检查标签——这是愤怒、害怕、羞耻、兴奋外溢，还是把运动/疲劳/争吵后的唤醒误标成了别的情绪？

边界：快速情绪不是“错误”，它常是保护系统；认知重评也不是万能，尤其对简单恐惧和强生理唤醒。App可把这条用于情绪命名、冲突暂停、考试焦虑和亲密关系误读。

后台提示：这条可作为情绪急救的顺序规则：高唤醒时先身体降温，低唤醒时先轻行动和唤醒，再进入认知整理。系统不应在用户心跳很快、想攻击或崩溃时立刻要求理性分析；等唤醒下降后，再帮助用户区分事实、解释、需要和请求。', '["情绪", "生理唤醒", "认知标签", "双因素理论", "情绪双通路", "情绪调节", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 393, now()),
(100394, '压力应对先分两类：能改问题就改问题，不能改时先稳情绪', '核心观点：第12章把长期不可控压力与健康风险联系起来，同时给出两类应对：聚焦问题的应对，直接处理压力源；聚焦情绪的应对，在暂时无法改变环境时调节情绪和寻求支持。能否感到控制、解释方式是否乐观、是否有支持性关系，都会影响压力后的健康和恢复。

App落地：用户说“我压力很大”时，可先分流：这个压力源是否可改变？若可改变，生成下一步行动、沟通、资源和时间表；若短期不可改变，先做情绪稳定、距离调整、倾诉、睡眠和支持网络。不要把所有应对都变成“忍一忍”或“马上解决”。

补充策略：控制感可以从小选择开始恢复；社会支持不是泛泛求陪伴，而是找到能倾听、能协助、不会加重羞耻的人。表达性书写、适度运动、放松训练和规律生活可作为非诊断性的身心调节建议。

后台提示：压力问答可先让用户给压力源标注“可控、部分可控、暂不可控”。可控项生成行动清单，部分可控项生成边界和求助，暂不可控项生成恢复计划。这样能避免用户在不可控事件上耗尽意志，也避免把可解决问题全部情绪化处理。', '["压力", "应激", "聚焦问题应对", "聚焦情绪应对", "控制感", "社会支持", "健康心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 394, now()),
(100395, '人格基础看大五，也看人与情境的交互', '核心观点：第13章将人格定义为思维、情感和行为的典型模式，并从精神分析、人本主义、特质和社会认知等视角介绍人格。对App端最稳妥的基础框架，是把“大五人格”作为描述语言，而不是命运标签：责任心、宜人性、神经质/情绪稳定性、开放性、外倾性。人格特质有稳定性和遗传基础，但具体行为仍受情境强烈影响。

App落地：用户问“我是不是某种人”时，系统可改问“你在哪些情境更容易表现出这种模式”。例如外向测验分数不能完全预测任何一次聚会表现；红绿灯前司机行为，情境线索比人格更能预测。人格建议应鼓励用户识别稳定倾向、触发环境和可训练反应，而不是贴固定标签。

避重方向：本条可作为九型人格、荣格类型之外的科学校准层。它不否定类型工具的自我反思价值，但提醒App不要用类型替代证据、情境和选择。

后台提示：测评结果进入知识库时，应默认加上“情境限定”。例如“高神经质”不等于脆弱，而是更容易觉察威胁和波动；“低外倾”不等于社交失败，而是能量恢复方式不同。系统应给用户更多选择，而不是把分数变成身份判词。', '["人格", "大五人格", "特质理论", "人情境交互", "社会认知观", "非标签化", "人格测评边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 395, now()),
(100396, '心理障碍非诊断理解：看痛苦、失能、文化和标签风险', '核心观点：第14章强调，心理障碍不是简单的“怪”或“坏”，通常指异常、令人痛苦、适应不良或不合理的思维、情感和行为的持续模式。判断正常与异常离不开文化、时代和功能损害：强烈恐惧若不影响生活，未必构成障碍；悲伤和抑郁也要看持续、痛苦和功能受损。现代观点采用生物—心理—社会框架，而不是只归因于性格缺陷。

App落地：App不做诊断，但可以做理解和分流。后台可先问四件事：痛苦强度、持续时间、功能受损、风险信号。对用户或他人贴标签时，提醒标签既能帮助描述和求助，也会引发偏见和自我实现。可把“他就是有病”改写为“TA表现出某些需要专业评估的持续困难”。

安全边界：涉及自杀想法、严重失眠、幻觉妄想、明显功能丧失、躁狂样高风险行为或伤人风险时，知识库应引导专业求助和现实支持，而不是提供诊断结论。

后台提示：这条可作为心理健康内容的安全边界。系统可以说“这听起来已经影响生活，值得寻求专业评估”，但不要说“你就是某某障碍”。对他人行为也一样：描述观察到的模式和影响，减少诊断化称呼，既保护被谈论者，也避免误导用户决策。', '["心理障碍", "非诊断", "生物心理社会", "功能损害", "标签风险", "专业求助", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 396, now()),
(100397, '有效帮助有共同因素：希望、新视角和可信关系', '核心观点：第15章梳理精神分析、人本、行为、认知、团体家庭治疗与生物医学治疗，并指出各种有效心理治疗常有共同因素：给受挫者希望，提供理解自我和世界的新观念，建立共情、信任、关怀的关系。治疗技术有差异，但治疗联盟、来访者的期待、具体问题匹配和持续练习，都会影响效果。

App落地：这能帮助后台设计“非治疗式支持”：先稳定希望感，再提供可理解的框架，最后给可执行练习。比如恐惧类问题可借鉴暴露和系统脱敏的逐步接近；抑郁和焦虑可借鉴认知疗法对自动想法的温和提问；行为问题可借鉴强化和替代行为。

边界：App不是治疗师，不能宣称治疗疾病。它可以做心理教育、练习提示、求助准备和复盘；一旦出现严重症状、药物问题、危机风险或复杂创伤，应鼓励线下专业支持。

后台提示：App对话也可借鉴共同因素：先让用户感到被理解，再给一个能解释困境的框架，最后提供小而可做的行动。若直接给技巧而没有关系承接，用户可能把建议体验成否定；若只有共情没有新视角，又容易停留在倾诉循环。', '["心理治疗", "共同因素", "治疗联盟", "希望感", "认知疗法", "行为疗法", "App支持边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 397, now()),
(100398, '心理健康也要上游预防：生活方式和环境同样是干预点', '核心观点：第15章后半部分强调，身心不是两套系统。规律有氧运动、充足睡眠、光照、社会接触、减少反复消极思考和营养支持等生活方式改变，可能帮助情绪恢复；更宏观地看，心理障碍预防不应只等症状出现后再“修理个体”，也要关注贫困、歧视、无意义工作、长期批评、孤立和缺少控制感等上游压力源。

App落地：知识库可把心理支持分成三层：当下稳定（睡眠、呼吸、运动、饮食、联系他人）、模式调整（想法、行为、关系、压力应对）、环境预防（减少长期压迫源、增加选择权和支持网络）。对用户而言，“先照顾身体和环境”不是肤浅建议，而是生物—心理—社会系统的一部分。

边界：生活方式建议不能替代药物或治疗；对严重抑郁、双相、精神病性症状或强迫症等，生活调整只能作为配合支持。App应避免制造“你只是没运动”的羞耻感。

后台提示：这条适合做长期维护计划。系统可把用户的工具箱分为“每天维护、早期信号、压力升级、危机求助”四层，并定期提醒复盘睡眠、运动、连接、光照、工作负荷和孤立程度。目标不是追求完美生活，而是降低复发和崩溃概率。', '["心理健康预防", "生活方式", "运动", "睡眠", "社会支持", "上游预防", "生物心理社会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 398, now()),
(100399, '表达恐惧不是胆小：它是社会皮肤在提示“我可能被孤立”', '核心观点：诺尔-诺依曼把舆论理解为一种“社会皮肤”：人不是先天就能毫无代价地公开做自己，而是持续感知周围人会赞同、嘲笑、冷落还是排斥自己。当一个人明知某件事可能是对的，却预感“说出来会让我变成孤零零的那个”，沉默就不只是缺乏勇气，而是社会性本能在保护归属。App 端面对“不敢说”“不敢拒绝”“怕被群里的人觉得奇怪”的用户，不宜直接劝“真实一点”，而要先承认：你的身体正在评估关系风险。

应用方式：把表达恐惧拆成三层：一是观点本身，我真正想说什么；二是公共性，它会被谁看见、转发、记住；三是后果，我担心失去谁的认可或支持。只有把这三层分开，用户才不会把“我害怕被孤立”误解成“我这个人没主见”。

关系提醒：安全表达不是任何场合都全盘公开，而是在看见风险后仍保留选择权。可以从私下、一对一、可撤回的小表达开始，逐渐测试关系是否能承受真实差异。', '["沉默的螺旋", "表达恐惧", "孤立恐惧", "社会皮肤", "自我审查", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 399, now()),
(100400, '意见气候判断：人不只问“我怎么想”，还会问“大家怎么看”', '核心观点：沉默的螺旋的关键不在于某个观点实际有多少支持者，而在于人们如何估计“多数人站在哪边”“哪一边正在变强”。书中用大量民意测验说明，普通人会不断读取周围环境：哪些意见被提倡，哪些意见在退潮，哪些话题说出来会更安全。这个能力像一种准统计感官，并不总是准确，却会深刻影响一个人是否开口。

App 应用：当用户说“大家肯定都觉得我错”“这个群里没人会支持我”时，可以引导他分层核对意见气候：我亲眼看到的证据是什么？只是最吵的人在说，还是多数人都表态？沉默的人有没有可能只是怕麻烦、怕冲突、没有语言？趋势是在变强、变弱，还是我被单个强刺激吓到了？

沟通价值：这能帮助用户把“气氛压迫感”从事实中分离出来。很多社交压力来自对气候的快速判断，而不是明确的排斥。把气候说清楚，用户就能从自动沉默转向更有策略的表达。', '["意见气候", "社交压力", "气氛判断", "准统计感官", "关系误读", "表达决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 400, now()),
(100401, '沉默会制造强势幻觉：越少人说，越像没人支持', '核心观点：沉默的螺旋最适合解释关系和群体里的“强势幻觉”。当一方更愿意公开表达，徽章、谈话、转发和态度都更可见；另一方即使人数不少，只要更谨慎、更沉默，就会在公共图景里显得更弱。于是强势方因为被看见而更自信，弱势方因为看不见同伴而更退缩，循环就被启动。最终，群体里看似“大家都这么想”，可能只是“敢说的人都这么说”。

App 应用：当用户在家庭群、团队会议、伴侣冲突中觉得“我一定是少数”时，可以提醒他检查三件事：谁在高频发声？谁只是点头或沉默？有没有人私下表达过相近感受？在关系中，沉默不等于同意，也不等于没有人支持。

表达建议：不要一上来对抗整个气候，可以先释放低风险信号，例如“我有一点不同感受，想先确认大家是否愿意听另一种角度”。这句话既打破绝对沉默，又不会把自己立刻推到被围攻的位置。', '["舆论压力", "沉默效应", "强势幻觉", "少数意见", "群体关系", "低风险表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 401, now()),
(100402, '坐火车场景：用“小公共场合”评估自己能不能开口', '核心观点：书中的“坐火车测试”很适合转化为 App 里的表达自测。它模拟一个介于私人和公共之间的场景：你要和陌生人共处数小时，对方公开表达与你相反的观点，你会加入谈话，还是觉得没必要？这个场景的价值在于，它不问抽象的“你勇敢吗”，而是让用户感受具体压力：空间狭小、时间较长、对方已先开口、自己可能被注视。

App 应用：可把困难表达拆成场景梯度。最低风险是写下来不发送；第二层是一对一讲给可信任的人；第三层是在小群里提出“我有不同看法”；更高层才是公开发言或发帖。用户如果在“小火车包厢”级别都很紧张，就不必强迫自己直接上台，而应先增加支持线索和退出通道。

关系提示：很多人不是没有观点，而是无法承受特定场景的可见性。把表达能力从人格评价改成情境评估，能减少羞耻，也能帮助用户设计下一步练习。', '["坐火车测试", "表达练习", "公共场合", "社交暴露", "安全表达", "沟通梯度"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 402, now()),
(100403, '孤立恐惧不是软弱：独立意识和被接纳需要会同时存在', '核心观点：现代人常把“我会受别人影响”看成羞耻，因为我们崇尚独立、成熟、自主判断。但诺尔-诺依曼借奥许和米尔格兰姆等研究提醒：人确实会为了避免孤立而调整表达；这并不取消人的理性，只说明人还有社会性的一面。模仿也有两种来源：一种是学习别人怎么做，另一种是为了不被排除在共同体之外。关系成长需要同时承认这两面，而不是把从众全部骂成没骨气。

App 应用：当用户自责“我怎么总是看别人脸色”时，可以回应：你不是没有自我，而是在保护连接。接下来再问：这次顺从是在学习更好的做法，还是在躲避嘲笑和排斥？如果是学习，可以保留；如果是恐惧，可以寻找更安全的表达方式。

成长方向：真正的自主不是完全不在乎别人，而是能识别“我在乎谁、为什么在乎、是否值得为这份关系暂时妥协”。这比空喊“别管别人”更可执行。', '["从众", "孤立恐惧", "社会性本质", "自我接纳", "顺从", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 403, now()),
(100404, '威胁让人收声，支持让人开口：表达需要即时安全线索', '核心观点：书中关于吸烟者与不吸烟者的实地实验很适合解释关系里的自我审查。轻微的语言威胁、批评性语境和不友好的同行者，会让原本愿意捍卫自己观点的人降低交谈意愿；相反，当较胆怯的一方看到有人替自己说出相近立场时，开口意愿会增强。表达不是只靠内在勇气，外部安全线索会直接改变一个人能否说话。

App 应用：在伴侣、亲子、团队反馈中，先创造安全线索，再邀请真实表达。比如“你可以不同意，我不会马上反驳”“我们先听完，不做评价”“你不需要一次说完整”。这些话不是客套，而是在降低被孤立的预期。

自助练习：用户准备表达前，可以先找一个支持性线索：一个同伴、一句预告、一段文字草稿、一次可暂停的对话规则。若环境已经充满嘲笑、贴标签和道德压迫，暂缓公开表达并不等于失败，而是对风险的准确判断。', '["安全感", "自我审查", "支持线索", "表达意愿", "关系沟通", "反馈文化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 404, now()),
(100405, '可见符号也是表达：徽章、贴纸、转发和服饰都会暴露立场', '核心观点：表达不只发生在“我说了一句话”的时刻。书中把徽章、汽车贴纸、报纸是否公开阅读、发型、服饰、海报等都视为公共表达；相应地，把报纸卷起来、摘下徽章、不贴海报，也是一种沉默。对 App 端关系场景来说，用户在朋友圈点赞、群里不回应、穿某种衣服、在办公室关门，都可能被他人读取为立场信号。

App 应用：当用户困惑“我明明没说什么，为什么别人反应这么大”，可以帮助他盘点可见符号：我展示了什么？隐藏了什么？别人可能把哪个动作读成支持、反对、疏离或结盟？这不是让用户迎合所有解读，而是让他更清楚自己暴露在怎样的公共视线中。

表达策略：把立场可见度分级。低可见是写私密日记；中可见是给可信的人发消息；高可见是公开发帖、贴标签、在群里站队。很多社交压力可以通过调节可见度降低，而不是只能在“全说”与“全忍”之间二选一。', '["非语言表达", "可见性", "立场信号", "社交压力", "沉默", "公共场合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 405, now()),
(100406, '舆论压力最强时，通常已经带上“好坏对错”的道德审判', '核心观点：沉默的螺旋并不会在所有差异里同等强烈地出现。书中特别指出，只有话题被情绪化、道德化，公共压力才会真正形成。因为此时人们不再只是说“我不喜欢这个观点”，而是在暗示“持这种观点的人不体面、不善良、不属于我们”。关系中的很多僵局也是如此：伴侣争论家务、父母争论教育、团队争论方案，一旦升级为“你就是自私/不负责/没良心”，表达风险就大幅上升。

App 应用：可引导用户识别三种层级：偏好差异、利益冲突、道德定罪。偏好差异可以协商，利益冲突需要谈边界和资源，道德定罪则需要先降温，否则对话会变成自我辩护和羞辱互投。

安全表达模板：把“你怎么能这样”改成“这件事触碰了我对公平/安全/尊重的需要，我想谈具体做法”。这样既不抹掉价值，也避免把对方整个人驱逐到关系外。', '["道德压力", "舆论压力", "价值冲突", "冲突降温", "关系修复", "安全表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 406, now()),
(100407, '嘲笑、嘘声和背后议论：微小排斥信号会启动自我审查', '核心观点：孤立威胁不一定表现为正式惩罚，很多时候只是嘲笑、嘘声、冷脸、背后议论或“不坐在你旁边”。书中把这些声音和姿态视为公共场合中的排斥符号：它们让人迅速意识到，某种表达会让自己成为被围观、被轻视、被谈论的人。关系中也是如此，一句阴阳怪气、一次集体沉默、一个群聊里的表情包，都可能让人学会以后少说。

App 应用：当用户描述“我后来就不想讲了”，不要只追问观点内容，也要问：当时出现了哪些排斥信号？是明确反对，还是嘲弄式反应？有没有人提供修复信号？这样能把沉默从“我太敏感”还原为对环境线索的反应。

应对建议：如果信号轻微，可用核对式表达：“我刚刚听到笑声，有点担心自己被嘲笑，能确认一下你们的意思吗？”如果信号持续且带羞辱，就优先离开或寻求同伴支持，而不是强迫自己在不安全场中证明观点。', '["排斥信号", "嘲笑", "背后议论", "自我审查", "社交安全", "群体关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 407, now()),
(100408, '找不到说法的人更容易沉默：安全表达需要可用的话语脚本', '核心观点：书中对大众传媒的一个重要洞察是：传媒不只告诉人们“哪边更强”，还提供表达某种立场的词汇、框架和刻板印象。如果一个人的观点在公共语言里没有现成说法，他即使知道很多人和自己想法相近，也可能“理屈词穷”而沉默。放到 App 场景里，许多用户不是没有需要，而是不知道怎样把需要说得既清楚又不自我暴露过度。

App 应用：知识库应能把模糊压力翻译成可说出口的脚本。例如把“我不想再忍了”翻译成“我愿意继续合作，但我不能接受被当众讽刺”；把“我怕群里攻击我”翻译成“我只补充一个不同经验，不代表否定大家”。脚本的价值不是替用户站队，而是给他一套不羞辱自己、不攻击他人的表达工具。

风险提醒：平台热词和群体口号也可能替人思考。安全表达应帮助用户生成“自己的话”，而不是把另一套舆论直接塞进他的嘴里。', '["表达脚本", "话语资源", "媒体影响", "刻板印象", "沟通模板", "自我表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 408, now()),
(100409, '双重意见气候：亲身经验与平台气氛冲突时，要分层判断', '核心观点：书中提出“双重意见气候”：人一方面从身边真实互动中观察气氛，另一方面通过电视、报纸等媒介的“眼睛”观察世界；两者可能不一致。今天的 App 用户同样会同时生活在家庭、公司、朋友圈、短视频平台和社群评论区里。一个平台上声量很大的观点，可能并不等于身边所有人都这样想；一个群里的沉默，也可能被外部热搜放大成“全世界都在反对我”。

App 应用：当用户被舆论压得喘不过气，可以做“气候分层表”：亲眼接触的人怎么说？我信任的人怎么说？平台推荐让我看见了什么？最极端的评论占多大比例？我有没有把媒介看到的气氛投射到亲密关系里？

沟通价值：分层不是否认社会压力，而是避免把所有气候合并成一个巨大的审判者。用户一旦看到不同场域的气候并不完全相同，就更容易找到可以开口的小空间。', '["双重意见气候", "平台压力", "媒介影响", "群聊气氛", "社交判断", "信息分层"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 409, now()),
(100410, '坚实核心不是人人都要当：少数声音需要同伴、身份和退路', '核心观点：沉默的螺旋并不意味着所有少数派都会沉默。书中提到“坚实的核心”：在漫长压力中留下来的一小群人，愿意承受孤立，并可能把自己看作先锋。但这也提醒 App 端，不应把每个用户都推向“勇敢发声”的英雄叙事。能成为坚实核心的人，往往有身份认同、同伴支持、意义感或对未来变化的期待；缺少这些条件时，硬扛孤立会变成消耗。

App 应用：帮助用户评估自己此刻更适合哪种策略：沉淀观点、寻找同伴、私下表达、半公开表达，还是公开站出来。对创作者、团队成员、家庭中的少数意见者来说，最重要的不是一次性爆发，而是建立可持续的支持系统。

安全提醒：少数声音有价值，但用户的身心安全也有价值。好的知识库应同时提供勇气和退路：怎样说、对谁说、说到什么程度、被围攻时如何暂停、找谁复盘。', '["少数意见", "坚实核心", "勇气边界", "同伴支持", "心理安全", "可持续表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 410, now()),
(100411, '社会事实：既要承认主观感受，也要核对外部关系', '核心观点：书中讨论托马斯“定理”时提醒我们，人常常不是直接对事实本身行动，而是对自己理解到的事实行动；但这并不等于社会事实只存在于脑中。关系规则、组织位置、制度后果和他人的真实行为仍然存在，只是它们会经过每个人的信息、信念和利益被感知、解释，再变成行动。

App 应用：当用户说“他们都讨厌我”“这个家就是不允许我做自己”时，不要急着否定感受，也不要把感受当成全部事实。更稳妥的路径是三分法：第一，先承认主观经验——你确实感到被排斥；第二，收集外部线索——发生了哪些可观察行为、规则或后果；第三，寻找关系验证——有没有可以低风险核对的对象或场景。

关系成长提醒：痛苦既可能来自误读，也可能来自真实结构压力。成熟的自助不是“相信感觉”或“只信证据”二选一，而是把感觉当信号，把事实核对当方向盘。这样既保护用户的内在经验，也避免把暂时解释固化成自我标签或关系判决。

适合场景：用户在关系中反复把一句话、一个眼神或一次拒绝解释成全局结论时，可以用这条作为澄清模板。系统可先问“你感到什么”，再问“你看到了什么”，最后问“还有哪一种解释也能解释这些证据”。这不是让用户怀疑自己，而是把情绪、证据和关系行动放到同一张桌上。', '["社会事实", "托马斯定理", "事实核对", "感受与解释", "关系误读", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 411, now()),
(100412, '把困扰放回系统：人不是孤立节点，也不是系统玩具', '核心观点：书中反复反对两个极端：只看个人选择的个体主义，和只看整体压力、把人当棋子的整体主义。系统主义的中间路是：每个人都在家庭、学校、公司、社群、制度等多个系统里行动；系统影响个体，个体也通过行动维持或改变系统。因此，一个人的困扰很少只是“性格差”，也不必被解释成“我完全没有办法”。

App 应用：遇到“我为什么总是这样”“是不是我太敏感”这类问题，可以把分析框架从人格审判改成系统地图：我在哪个系统里出现这个反应？这个系统的规则、资源、惩罚和期待是什么？我的行动又怎样影响别人继续这样对我？

练习提示：请用户列出三个圈子——亲密关系、工作/学习、家庭/社群——分别写下“我被期待做什么”“我能影响什么”“我暂时影响不了什么”。这样既去羞耻，也保留行动感：人不是系统外的孤岛，也不是系统里的木偶。

适合场景：自责、羞耻和无力感同时出现时尤其适用。系统可以把问题从“我怎么这么差”改写成“我所在的系统如何奖励或惩罚这种反应”。如果用户仍有改变空间，再引导他选择最小可行动作；如果系统存在明显不公或危险，则优先寻找外部资源，而不是继续要求自我优化。', '["系统主义", "结构性压力", "行动感", "去羞耻", "家庭系统", "职场关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 412, now()),
(100413, '社会结构就是纽带：关系会改变人，不只是背景', '核心观点：书中把社会结构理解为系统中各成分之间的关系集合，并特别区分“会影响关系项的关系”与普通并列关系。婚姻、就业、贸易、教育、政治忠诚等不是静态背景，而是会改变当事人的纽带：它们规定可接近的资源、可说的话、需要承担的责任和违背规则的代价。

App 应用：关系问题常被说成“我不够好”“他性格冷”“我们沟通差”。系统视角会继续追问：你们之间有哪些纽带？这些纽带带来的是照顾、依赖、考核、经济交换、身份义务，还是公开承诺？同一句话在朋友、上下级、伴侣、亲子之间意义不同，因为纽带不同。

关系成长提醒：改变关系不能只改情绪表达，还要识别纽带本身。比如伴侣冲突可能同时包含亲密纽带、家务分工、经济依赖和双方家庭期待；职场委屈可能包含任务关系、评价权和晋升资源。把纽带画出来，用户更容易看见：哪些是沟通可修复的，哪些需要边界、资源或制度性调整。

适合场景：适合处理伴侣分工、职场委屈、亲子义务和朋友间金钱往来。系统可提示用户不要只描述情绪，还要描述纽带：谁依赖谁，谁评价谁，谁掌握资源，谁承担后果。许多所谓“沟通问题”其实是纽带不清或权责不对等；把它命名出来，才知道该谈感受、谈规则，还是谈退出方案。', '["社会结构", "纽带", "关系地图", "制度关系", "边界", "资源分配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 413, now()),
(100414, '角色不是性格：同一个人在不同位置会做出不同反应', '核心观点：书中指出，同一个体在不同社会系统中，或在同一系统里升职、降职、换位置时，可能出现不同行动；“角色”必须参照同一系统中的其他人才能说清。一个经理、下属、照顾者、孩子、伴侣并不是几套内在人格，而是在不同关系位置上承接不同任务、权力、期待和风险。

App 应用：当用户困惑“我在外面很能干，回家就像小孩”“我明明温和，却在团队里变得控制”时，可以先用角色视角降羞耻：这可能不是你人格分裂，而是不同系统正在调用不同角色脚本。接着追问：这个角色被要求完成什么？它拥有哪些权力？承担哪些责任？最害怕失去什么？

关系提醒：角色冲突常来自多个期待同时挤压，例如既要做孝顺子女，又要做独立伴侣；既要做高绩效员工，又要做稳定父母。成长不是消灭某个角色，而是给角色排序、协商边界，并把“我这个人不行”改写为“我正在处理多个系统给我的任务冲突”。

适合场景：用户在不同关系中表现反差很大，并因此自责“我是不是很假”时，可用角色框架帮助整合。系统可询问：这个角色从什么时候开始？谁最在意你扮演好它？如果你退出这个角色，会影响谁的利益或安全感？这些问题能把角色脚本从身份里拆出来，让用户有机会重新谈判。', '["社会角色", "角色冲突", "身份压力", "家庭关系", "职场压力", "去人格化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 414, now()),
(100415, '机制解释：别只问发生了什么，要问它如何运转', '核心观点：书中把“机制”放在解释的中心：真正理解一个过程，不只是看到两个现象一起出现，而是知道中间如何连接、靠什么力量维持、在哪些条件下会改变。作者用黑箱、灰箱、透光箱区分解释深度：黑箱只说输入输出，灰箱只给粗略中介，透光箱才尽量说明“它如何运行”。

App 应用：心理教育内容可以少做简单归因，多做机制拆解。例如“冷战伤关系”不是因为冷战这个词不好听，而是因为回避—猜测—威胁感—更回避的回路会不断强化；“讨好很累”不是因为讨好者软弱，而是认可奖励、冲突恐惧、短期安全感共同维持了行为。

用户练习：把一个困扰写成四格：触发条件、自动反应、短期收益、长期代价。再问：谁在奖励这个模式？什么环境让它更容易发生？哪个小环节最能被改变？这样能把“我就是这样”转成“这个机制正在这样运转”。

适合场景：适合把抽象建议转成可操作方案。系统若只说“多沟通”“要自信”，用户很难行动；若能指出维持机制，就能设计干预点。比如先改变触发条件，或改变短期奖励，或增加新的支持者。机制解释也能减少互相指责：我们不是在找坏人，而是在找让坏模式持续运转的零件。', '["机制解释", "行为回路", "黑箱灰箱透光箱", "心理教育", "模式识别", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 415, now()),
(100416, '微观—宏观双层图：个人行动与制度环境互相接力', '核心观点：书中批评只从个人偏好解释社会现象，也批评只从宏观结构压下来的解释。更好的系统解释要同时看自下而上的个人行动和自上而下的环境约束：社会关系经过人的头脑，最终由个体行动承接；但个体意图、期望和选择又被资源、阶层、教育、政策、组织规则塑造。

App 应用：面对“我为什么不离开这段关系/这份工作/这个家庭模式”，不要只问意志力，也不要只说环境太强。可以画双层图：宏观层写制度、经济、家庭规则、群体舆论；微观层写感受、信念、选择、身体反应；中间写它们如何互相影响。

关系成长提醒：许多痛苦不是“想通就能改”，因为微观选择需要宏观条件支持；但宏观条件也常通过微小行动被重新组织。比如争取支持者、保存证据、学习技能、调整沟通脚本，都是让个体行动接上结构改变的桥。

适合场景：用户把问题全部归因于自己不够坚定，或全部归因于社会/家庭不给机会时，都可用这条拉回双层分析。系统可以分别生成“个人层可做的三件小事”和“环境层需要争取的三种资源”。这能避免鸡汤式行动主义，也避免结构决定论，让用户在现实限制内看见可移动的边界。', '["微观宏观", "能动性与结构", "制度环境", "选择受限", "系统图", "社会支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 416, now()),
(100417, '价值与事实分开看：客观不等于没有立场', '核心观点：书中反对把客观性误解成“不能作价值判断”。客观性要求我们尽量准确描述事实、证据和机制；但当事实涉及压迫、伤害、剥夺或不平等时，研究者和助人者仍可以有清楚的伦理立场。换句话说，区分事实与价值，不是把价值赶出讨论，而是让价值判断建立在更可靠的事实理解上。

App 应用：关系成长中常见两种偏差：一种是只讲价值，“你必须原谅/必须独立/必须孝顺”；另一种是假装中立，“谁对谁错我不评价”，结果让受伤者继续自责。更好的回答可以分两步：先核对事实——发生了什么、频率如何、影响是什么；再说明价值——尊重、自主、安全、平等为什么在这里重要。

提示语：可以对用户说：“我们先把事实讲清楚，再看哪些底线被触碰。”这能避免道德说教，也避免把伤害稀释成单纯观点差异。

适合场景：适合处理家暴、语言贬低、职场不公、亲子控制等容易被“各有各的立场”稀释的问题。系统应避免替用户武断定罪，但也不能把伤害包装成中立分歧。事实核对越清楚，价值判断越有力量：频率、影响、权力差和可拒绝性，都是判断边界是否被侵犯的重要线索。', '["事实价值区分", "客观性", "伦理立场", "关系边界", "安全底线", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 417, now()),
(100418, '关系改变要系统化：只改一个环节容易产生反作用', '核心观点：书中讨论社会改革时指出，系统不能像死物一样被随意切开修理；改变一个成分会影响其他成分，有时还会带来不可预见的反作用。对家庭、亲密关系和团队也是如此：只要求一个人改变说话方式，却不改变权力、分工、奖惩和支持条件，常会让旧模式换个形式回来。

App 应用：当用户想“只要我不发脾气/只要我更温柔/只要我更努力，关系就会好”时，可以提醒做系统化改变：一看触发源，二看互动回路，三看资源支持，四看对方是否参与，五看改变后谁会失去既得好处。关系中的新行为需要新环境托住，否则容易被旧规则拉回。

小练习：为一个目标列出相关部门——情绪调节、沟通脚本、时间安排、经济资源、同伴支持、边界后果。每个部门设一个小调整，而不是把全部责任压在“我要更强大”上。

适合场景：用户已经做过多次个人努力却总是复发时，可以用来检查系统条件。系统可问：你的新做法会让谁不适？旧模式给谁带来好处？有没有共同规则来保护新模式？如果没有，改变就会变成单人硬扛。系统化改变不一定宏大，它可以是一次家庭会议、一份分工表、一个冷静期协议或一个外部支持网络。', '["系统性改变", "反作用", "关系修复", "家庭系统", "分工权力", "支持条件"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 418, now()),
(100419, '真实的人不是冷酷计算器：情绪、地位和关系会进入选择', '核心观点：书中批评把人想象成只计算收益的“经济人”。真实的人会算错，甚至根本不计算；会受情绪、关系、地位、宣传和群体氛围影响。这不是说人没有理性，而是说人的理性总在身体、身份、资源和关系网络中运行。

App 应用：当用户自责“我明知道不该这样，为什么还会选错”“我为什么总被认可牵着走”时，回答不宜停在“你要理性一点”。更有帮助的是识别选择现场：当时有什么情绪唤醒？谁在场？我在保住什么身份？我担心失去什么关系？这个决定短期给了我什么安全感或地位感？

关系成长提醒：改变选择要改变选择环境。比如在冲突前约定暂停协议，在消费或复合前设置等待期，在群体压力前准备支持者，在高唤醒时先降温。理性不是压倒情绪，而是为情绪、关系和地位压力预先设计缓冲。

适合场景：冲动复合、讨好答应、群体压力下附和、被营销或权威影响时都适用。系统可以把“选择错误”翻译成“选择环境设计不足”：当用户处于疲惫、孤独、羞耻或急需认可的状态时，最聪明的策略不是当场变理性，而是提前设置延迟、同伴确认、书面清单和离场脚本。这样既减少自责，也提高下一次选择质量。', '["理性选择批评", "情绪决策", "地位焦虑", "社会影响", "选择环境", "自责松动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 419, now()),
(100420, '场域：关系不是空地，而是有规则的游戏现场', '【核心理解】布尔迪厄提醒我们：一个人进入家庭、职场、亲密关系、学校或社群时，并不是走进一片中性的空地，而是进入一个已经有排序、有奖励、有禁忌、有“什么才算有价值”的场域。很多关系冲突表面上是性格不合，实际是在争夺谁的规则算数、谁的话更有分量、什么资源会被承认。
【关系应用】当用户说“我是不是太不会做人”“为什么我总被边缘化”，App 可先帮助他识别当前场域：这里看重钱、学历、人脉、资历、情绪劳动、性别角色，还是某种体面感？谁有权定义对错？哪些行为被奖励，哪些会被惩罚？
【成长方向】看见场域不是鼓励圆滑，而是把自责改成定位。用户可以选择学习规则、协商规则、寻找盟友，或离开不适合自己的场域。真正的关系成长，不只是把话说得更好听，也包括弄清自己正在参与什么游戏，以及是否愿意继续玩。
【后台落点】可做成“场域定位卡”：1）我在哪个关系场域；2）这里默认奖励什么；3）我缺的不是哪种性格，而是哪类资源、资格或支持；4）我愿意遵守、协商还是退出哪些规则。这样能避免把所有不适都解释为沟通能力差，也能避免把适应误读为讨好。', '["场域", "关系规则", "无形规则", "权力关系", "自我定位", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 420, now()),
(100421, '资本不只是钱：看见关系里的文化、社会与象征资源', '【核心理解】布尔迪厄把资本从“钱”扩展到多种能影响关系位置的资源：经济资本是财产和收入，文化资本是语言能力、教育经历、审美与信息，社会资本是关系网络与熟人资源，象征资本则是名声、资格、体面和被承认的合法性。很多关系里的不平等，不是因为某个人天生更值得被听见，而是他带着更多被场域承认的资本。
【关系应用】当用户在伴侣、婆媳、同事或同学关系中觉得“我说什么都没用”，App 可引导他画一张资本地图：谁掌握经济资源？谁更懂规则和话语？谁有支持网络？谁的身份更容易被相信？
【成长方向】资本地图不是给人贴阶层标签，而是帮用户少一点羞耻、多一点策略。缺信息就补信息，缺支持就建网络，缺表达资格就寻找能被承认的渠道。关系中的自尊不只来自内心强大，也来自现实资源被一点点补足。
【后台落点】这条适合接在自卑、配得感、职场弱势和亲密关系权力差内容后。系统不只给“提升自信”的建议，而要把问题拆为可补足的资源：需要钱、时间、知识、证书、见证人、可信推荐，还是一个能帮你翻译规则的人。把资本具体化，用户才不会把资源不足误会成自己不值得。', '["资本", "文化资本", "社会资本", "象征资本", "资源地图", "关系不平等"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 421, now()),
(100422, '习性：那些“不用想就会这样”的反应，常是社会经验进了身体', '【核心理解】习性不是简单的习惯，也不是固定人格，而是长期生活条件进入身体和判断后的倾向系统。它让人不用计算就知道“该怎么坐、怎么说、该不该争取、什么人适合我、什么东西不是给我准备的”。因此，一个人回避表达、过度证明、天然自信、害怕被看见，可能都不只是心理问题，也可能是过去家庭、阶层、学校和关系经验在身体里留下的方向感。
【关系应用】App 面对“我为什么总忍不住讨好/退缩/逞强”的用户，可以先不急着纠正，而是追问：这种反应最早在哪些场景有用？它曾经保护过你什么？它对应的是怎样的家庭位置、性别期待、经济压力或学校评价？
【成长方向】改变习性不能只靠讲道理，需要新的场域、新的身体经验和小步实验。用户可以从低风险表达、被支持地拒绝、在安全关系里练习不同姿态开始，让身体慢慢学会：过去的规则不必永远支配现在。
【后台落点】可设计“习性追踪练习”：写下一个自动反应，标出触发场景、身体感觉、脑中规则、最早学会它的关系，以及一个更小的新动作。比如从“我必须马上道歉”改为“我先确认事实”；从“我不能麻烦别人”改为“我提出一个可拒绝的请求”。', '["习性", "惯习", "身体化经验", "社会化", "自动反应", "自我理解", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 422, now()),
(100423, '“这不是给我准备的”：限制感如何变成内心边界', '【核心理解】布尔迪厄特别敏锐地指出，社会限制最隐蔽的地方，是它会被人体验成“我自己不想要”“我本来就不适合”。当资源和机会长期有限，人会发展出一种限制感，把外在边界变成内心边界：不敢申请、不敢亲近、不敢进入某些圈子，甚至把退缩解释成理性、懂事或不贪心。
【心理教育应用】当用户说“那种生活不是给我这种人的”“我不该有更高期待”，App 可以把这句话当作线索，而不是结论。继续问：这是你的真实愿望，还是你对失败概率、羞辱风险、家庭评价、阶层距离的提前适应？如果没有惩罚和羞耻，你还会这样选择吗？
【成长方向】看见限制感，不等于否认现实差距。它意味着用户可以把目标拆成试探：先获得信息、找到同伴、体验一次安全进入，再决定是否继续。不是每个门都必须推开，但至少要分清：这是我的选择，还是过去的社会位置替我做出的选择。
【后台落点】这条适合用于羞耻、阶层流动、择偶、职业申请和学习焦虑场景。系统要区分“我经过评估后不选择”和“我一想到就觉得自己没资格”。前者是边界，后者可能是内化限制。引导用户做一次低成本试探，比直接喊“你要相信自己”更有效。', '["限制感", "社会位置", "自我设限", "阶层感", "可能性", "羞耻修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 423, now()),
(100424, '象征权力：最深的控制，是让评价标准看起来天然正确', '【核心理解】象征权力不是简单命令别人，而是让某套分类、语言和评价标准显得自然、体面、正确。比如“有教养/没档次”“懂事/不识大体”“成功/失败”“正常/丢人”，这些词一旦被接受，就会让人用别人的尺子衡量自己。它的力量在于，被支配者也可能承认这套标准，从而把不平等误认为个人不够好。
【关系应用】在亲密关系和家庭里，象征权力常表现为一方不断定义现实：谁是理性的一方，谁是情绪化；谁叫牺牲，谁叫自私；谁的工作体面，谁的付出不算数。App 可引导用户问三句：这个词是谁发明和反复使用的？它让谁获得合法性？它让我失去了哪些表达自己的语言？
【成长方向】反抗象征权力的第一步，是重新命名。把“我太敏感”改成“我对不尊重有反应”，把“我没出息”改成“我缺少被承认的资源和路径”。新的语言会帮助用户恢复现实感，也为关系协商创造空间。
【后台落点】这条可作为关系风险和自我怀疑内容的上位解释。系统不必把每次分歧都说成符号暴力，而要看是否长期由一方垄断命名权：TA 总能定义你是什么人、你的感受算不算数、什么才叫正常。若是，就先恢复自己的词典，再讨论沟通技巧。', '["象征权力", "符号暴力", "现实感", "评价标准", "语言控制", "关系权力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 424, now()),
(100425, '文化差异不是品味高低：别把生活条件误读成个人价值', '【核心理解】布尔迪厄在《区隔》相关讨论中说明，品味并非单纯的个人审美，也常是生活机会、经济距离和文化资本的结果。有些人重形式、风格和仪式，是因为他们离生存压力更远；有些人重实用、饱足和耐用，是因为他们长期与必需品更近。把两者简单翻译成“高级/低级”“有趣/土气”，就是把社会差异道德化。
【关系应用】伴侣、亲子、朋友之间常因吃什么、穿什么、送什么礼物、怎么旅行、怎样教育孩子而互相评判。App 可提示：先不要急着判断对方“没品味”或“太装”，而要理解这背后的资源经验、家庭训练和安全感来源。
【成长方向】尊重文化差异不是放弃审美，而是把审美从攻击工具变成沟通材料。可以说“这对我代表体面/安全/放松”，而不是“你这样很低级”。当双方能讲出品味背后的生活史，关系就有机会从互相羞辱转向互相翻译。
【后台落点】适合做“品味翻译器”：把评价性语言改成需求语言。比如“你太土”可转成“我在意公共场合的体面”；“你太装”可转成“我担心自己被比较和否定”；“你太小气”可转成“我需要被重视的仪式感”。这样既保留差异，也减少羞辱。', '["文化差异", "品味", "阶层感", "生活方式", "非评判", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 425, now()),
(100426, '中间位置的紧张：过度用力、不敢松弛，也可能是位置焦虑', '【核心理解】布尔迪厄写到中间阶层时，捕捉到一种很像现代人的紧张：想摆脱旧位置，又还没有足够资源稳稳进入新位置，于是容易过度努力、过度纠错、过度证明自己“够格”。这种状态不必被羞辱为虚荣或做作，它常是处在两个评价系统之间的人，为了获得承认而发展出的生存姿态。
【关系应用】用户若总是害怕说错话、穿错衣服、用错词，或在关系里不断证明自己有价值，App 可以帮助他识别：我是在表达真实需要，还是在向某个想象的评委证明我不低级、不失败、不该被抛下？
【成长方向】缓解位置焦虑，需要从“表现正确”转向“关系真实”。可练习在安全关系中承认不知道、承认普通、承认需要帮助；也可把外部标准分层：哪些标准能帮助我成长，哪些只是让我长期羞耻。真正的从容不是学会所有上层规则，而是不再让单一评价系统决定自己的存在价值。
【后台落点】可用于完美主义、社交焦虑、阶层羞耻和职场新人内容。系统可提醒：过度用力不等于虚伪，它可能说明你正在缺少安全的承认。练习重点不是立刻“松弛感”，而是找到不需要表演也能被接住的关系，并把外部评价从“生死判决”降级为“部分参考”。', '["位置焦虑", "中间阶层", "过度证明", "羞耻", "自我价值", "关系真实"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 426, now()),
(100427, '教育不只是努力赛道：文凭会把家庭资本包装成个人能力', '【核心理解】布尔迪厄对教育的分析适合提醒 App 用户：学校并不只是公平筛选努力者的机器，它也会保存、灌输并神圣化某种文化遗产。那些从小熟悉学校语言、审美、表达方式和升学路径的孩子，更容易把家庭资本转化为成绩和文凭；而缺少这类资本的人，常把不适应误解为自己笨、不努力或没天赋。
【关系与亲子应用】当用户因学历、孩子成绩、择校或职业资格而自责时，App 可引导他同时看四层：个人努力、家庭可提供的信息和时间、学校默认的文化规则、文凭在劳动力市场里的兑换价值。这样既不否认努力，也不把所有结果压回个人。
【成长方向】教育资本可以被补建：找懂规则的人、获得信息、练习表达、认识隐性评价、争取支持网络。对父母而言，重要的不只是催孩子努力，还包括帮助孩子理解游戏规则，并减少“输不起”的羞耻。
【后台落点】这条适合亲子教育、学历羞耻和职业选择模块。回应用户时要同时保留两句话：努力有意义，但努力发生在不平等的资源结构中；文凭有现实价值，但文凭不能决定人的全部价值。这样既不犬儒，也不把教育压力继续转嫁给孩子和个体。', '["教育", "文化资本", "家庭资源", "文凭", "亲子压力", "社会不平等"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 427, now()),
(100428, '关系中的准入费：进入一个圈子前，先看它要你交什么', '【核心理解】每个场域都有准入费。它不一定是金钱，也可能是学会某种说话方式、接受某种情绪劳动、认同某些价值、维护某些面子，或默认某些人拥有更高解释权。进入职场、伴侣家庭、朋友圈、社群、精英学校和专业圈子时，人往往先被要求证明“你知道怎么玩”。
【关系应用】当用户在新关系里感到累、格格不入或总被暗示“不懂规矩”，App 可帮他列出准入费清单：我要付出时间、金钱、形象管理、服从、沉默、礼物、人情，还是自我否定？这些成本是否合理？它们换来的归属是否真实？
【成长方向】成熟的关系不是没有规则，而是规则可以被说明、协商、修正。若一个圈子的准入费是长期牺牲尊严、现实感和边界，就不只是适应问题，而是场域本身在消耗你。用户可以学习必要规则，也可以保留退出权。
【后台落点】可做成“准入费评估表”：规则是否公开、成本是否可承受、是否允许拒绝、是否有退出惩罚、是否要求你否认自我。健康圈层会让新人学习规则，但不会把羞辱当筛选；不健康圈层会不断移动门槛，让你永远觉得自己还不够格。 若用户总觉得“我已经很努力讨好了，为什么还不被接纳”，系统可进一步区分：这是学习成本，还是关系在借规则维持不平等。', '["准入费", "圈层", "关系边界", "隐性规则", "归属感", "场域适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 428, now()),
(100429, '错位感：旧习性遇到新场域时，焦虑可能是转型信号', '【核心理解】人会带着过去形成的习性进入新的场域。若新场域的机会、奖励和规则与旧经验相近，人会觉得自然；若差距很大，就会出现错位感：明明已经换了环境，却还用旧方式判断安全、价值和可能性。初代大学生、跨阶层伴侣、转行者、移居者、进入新家庭的人，都可能体验到这种“我好像不属于这里”。
【心理教育应用】App 可把这类焦虑从“我有问题”改写成“旧地图遇到新地形”。可以引导用户区分：旧场域教会我的规则是什么？新场域奖励什么？哪些旧能力仍有用，哪些会造成误会？我需要补的是知识、关系、语言，还是身体上的安全感？
【成长方向】错位不一定要立刻消除。它可能是身份转换的过渡期，需要哀悼旧熟练感，也需要练习新规则。与其逼自己马上自信，不如找一个可解释规则的人、一个允许犯错的小空间，以及一套逐步更新习性的练习。
【后台落点】适合新城市、新学校、新职业、跨阶层亲密关系和家庭重组场景。系统可以先验证用户的错位感，再帮他分别列出旧规则与新规则。目标不是立刻融入，而是保留旧经验中有力量的部分，同时补上新场域需要的语言、节奏和支持。', '["错位感", "惯习", "习性滞后", "身份转换", "跨阶层关系", "焦虑", "适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 429, now()),
(100430, '承认也是资本：被看见、被相信，会改变一个人的关系位置', '【核心理解】象征资本可以理解为被承认的资本：名声、信誉、资格、体面、可信度和“这个人说话算数”的位置。它常和社会资本交织在一起，使某些人的表达更容易被相信，某些人的痛苦更容易被轻视。关系里的很多不平等，并非只发生在钱和权上，也发生在谁被承认、谁被默认无理、谁必须反复自证。
【关系应用】当用户抱怨“为什么同样的话别人说就有用，我说就被当成闹情绪”，App 可以引导他观察承认结构：在这个家庭或团队里，谁天然可信？谁的学历、年龄、性别、职位或收入给了他说话权？谁的贡献被当成应该？
【成长方向】争取承认不是乞求认可，而是建设更公平的见证系统。用户可以记录事实、寻找第三方支持、把贡献具体化、避免只在否认自己的人面前证明自己。健康关系会扩大彼此的象征资本：让对方的感受、劳动和边界都能被看见。
【后台落点】这条适合处理“我怎么说都没人信”“我总要证明自己”的自证疲劳。系统可以建议用户减少在否认者面前耗尽自己，转而建立见证系统：书面记录、可信朋友、专业支持、共同规则、可验证事实。被承认不是虚荣需求，而是关系公平的一部分。', '["象征资本", "承认", "可信度", "关系位置", "被看见", "自证疲劳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 430, now()),
(100431, '社会学想象力：把“我怎么了”改问“什么情境在影响我”', '【核心观点】社会学想象力不是把责任都推给社会，也不是否认个人选择，而是把一个人的困扰放回其生活情境中理解：家庭、邻里、学校、组织、工作市场、历史时代和制度规则，都可能在塑造“我能做什么、我为什么这么难”。当很多人遭遇相似困境时，它往往不只是某个人不够努力，而是某种结构正在反复制造同类结果。
【App落地】用户说“我太失败了、我怎么总是做不到”时，先做双层提问：1）个人层：这件事中我能调整的行为、技能、边界是什么？2）情境层：哪些规则、资源差距、角色期待、时间压力或组织安排在推着我走？3）连接层：谁能提供信息、陪伴、制度资源或专业支持？
【关系成长】这种视角能减少羞耻和互相归罪。伴侣争吵、亲子冲突、职场挫败，都可同时看见人的选择与局面的力量。最后再回到行动：在不能立刻改变大结构时，先找一个可移动的小杠杆；在确实涉及公共议题时，允许自己寻求社群、机构或政策层面的帮助。
【可用提问】如果把这件事拍成一张社会地图，地图上除了“我”还会出现谁、哪些机构、哪些规则、哪些资源缺口？哪些因素我能今天处理，哪些只能先命名、寻找同伴或等待更大的支持？', '["社会学想象力", "个体困扰", "公共议题", "情境", "去自责", "心理教育", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 431, now()),
(100432, '常识和刻板印象都要追问：它在什么情境下成立', '【核心观点】人会用常识和刻板印象快速解释世界，例如把贫穷归因于懒惰，把某类亲密关系看成“不自然”，或把年龄、体重、性别、族群当成能力和品格的证据。社会学训练提醒我们：常识并非总错，但它通常只在特定情境下成立；刻板印象更危险，因为它把群体标签直接套到具体个人身上，遮住了制度、资源和历史原因。
【App落地】当用户用“他这种人都……”“我这种家庭出来的人注定……”来解释关系时，可引导四问：这个判断从哪里来？有没有反例？谁会因这种说法受益或受伤？如果把具体行为、处境和资源分开看，会得到什么新解释？
【关系成长】这不是要求用户“不要评价”，而是把粗暴归类转化为可核对的事实、具体影响和可协商的需要。尤其在冲突中，少用“你们男人/女人/年轻人/外地人都这样”，多说“我在这件具体事里感到什么、需要什么”。这样既能保留判断力，也能减少羞辱和防御。
【可用提问】这句话是在描述事实，还是在替一个群体下判决？如果我把“总是、都、天生”换成“在某些条件下更可能”，我会看见哪些被忽略的处境和选择？ 这能让解释更慢，也更准确。', '["刻板印象", "常识批判", "归因", "偏见", "群体标签", "沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 432, now()),
(100433, '镜中我：自我感是在重要他人的目光中长出来的', '【核心观点】自我不是孤立的内在物，而是在互动中形成的过程。人会从父母、朋友、老师、伴侣、同事、网络群体等“镜子”里理解自己：我是否聪明、可爱、体面、值得被接纳。重要他人、参照群体和概化他人共同塑造我们在意谁的评价、模仿谁的行为、遵守哪些不成文期待。
【App落地】用户说“我太在意别人眼光”时，不必简单劝他“别管别人”。可以先承认：在意评价是人类维持归属的社会能力。随后做“镜子盘点”：哪些评价来自亲密且可信的人？哪些来自不熟悉但强势的群体？哪些只是想象中的大众审判？哪些镜子长期只反馈羞耻，而不反馈真实与成长？
【成长方向】支持用户寻找更健康的参照群体，让自我感从一个严苛镜子，扩展为多面、稳定、可修正的社会支持系统。练习上，可以把“别人怎么看我”改成“哪些人的反馈值得进入我的自我定义，哪些只适合当作情境信息”。
【可用提问】我现在最怕失去谁的认可？这个人或群体是否真正了解我？我有没有把一次表情、一次沉默、一个点赞数量，误读成对整个人的判决？我还可以把自己交给哪些更温和的镜子？ 这一步能把羞耻还原成信息。', '["镜中我", "社会互动", "重要他人", "参照群体", "自我感", "归属", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 433, now()),
(100434, '角色冲突：你不是矛盾的人，而是同时被多个期待拉扯', '【核心观点】人在一天中会切换许多角色：子女、父母、伴侣、学生、员工、朋友、照顾者、领导者。每个角色都带着一套期待和“应该”：学生要跟上课业，朋友要帮忙，子女要回家，员工要服从流程，父母要照顾孩子。当两个角色的要求同时出现且互相冲突，痛苦并不说明这个人虚伪或没原则，而是社会位置之间发生了拉扯。
【App落地】处理内疚和两难时，可用角色冲突表：1）我现在被哪些角色要求？2）每个角色背后的具体期待是什么？3）如果满足A，会牺牲B的什么？4）有没有边界、协商、延期、部分满足或求助的空间？5）这次选择是在照顾长期价值，还是只是在躲避眼前评价？
【关系成长】把“你怎么这么自私/不孝/不负责”改成“我们各自被哪些角色期待拉住”，能降低道德攻击，让双方讨论真实限制和优先级。角色冲突无法靠讨好所有人解决，成熟的目标是有意识地排序、解释和承担后果。
【可用提问】此刻最强的内疚来自哪个角色？这个角色的期待是否合理、是否过时、是否由我一个人承担？如果我只能诚实满足一部分，我要怎样说明边界并保留关系？ 这一步能让选择更诚实。', '["角色冲突", "社会角色", "内疚", "边界", "家庭关系", "职场压力", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 434, now()),
(100435, '规范和制度：看不见的脚本让人感觉“不得不”', '【核心观点】很多压力来自看不见的脚本。规范是不成文的“这样才合适”，规则是更正式的准则，制度则把规则和惯例固定进学校、家庭、婚姻、法律、公司、医疗等组织里。人往往觉得自己在自由选择，实际已经被“好孩子该怎样、合格员工该怎样、体面家庭该怎样”的脚本牵引。违背脚本不一定违法，却可能招来尴尬、排斥、惩罚或羞耻。
【App落地】当用户说“我必须这样做，不然大家会觉得我很糟”时，可追问：这是明文规则，还是默认规范？谁在执行它？违反后真实代价是什么，想象代价是什么？它保护了谁，又压住了谁？哪些部分能协商，哪些需要外部资源或集体支持？
【关系成长】看见规范不是为了鼓励任性，而是让用户从自动服从变成有意识选择：我愿意遵守哪些规则，又要在哪些规则前建立边界。对亲密关系尤其重要：很多争执表面是性格不合，底层其实是双方带着不同家庭、阶层或性别脚本进入同一段关系。
【可用提问】这条脚本是我真正认同的价值，还是害怕被排斥而服从的惯例？如果我要微调它，最小、最低风险的实验是什么？谁能见证我不是在破坏关系，而是在创造更健康的规则？', '["社会规范", "制度", "规则", "社会事实", "边界", "家庭脚本", "职场脚本"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 435, now()),
(100436, '标签会变成现实：从污名到自我实现预言', '【核心观点】标签不是中性的描述。一个人或群体被贴上“坏孩子、疯子、失败者、越轨者、不正常”的标签后，周围人的期待、机构的处理方式和同伴网络都会随之改变；久而久之，被贴标签的人可能被迫进入标签所规定的位置，形成自我实现预言。污名的伤害不只在于难听，而在于它会减少机会、改变互动、制造隔离，并让人把外界判断误认为自我本质。
【App落地】面对用户自称“我就是有问题的人”时，先把标签拆开：具体发生了什么行为？谁给出了这个名称？这个名称带来哪些后果？有没有更准确、更少伤害的描述？如果确有行为需要承担责任，也应落在行为修复、支持和新选择上，而不是把整个人判死刑。
【关系成长】亲密关系和亲子沟通中，少用身份判词，多说具体事件、影响、需要和下一步。例如把“你就是废物/疯了/坏孩子”改成“这件事造成了什么影响，我们需要怎样修复”。这样既保留边界，也减少污名进入自我概念。
【可用提问】这个标签让我失去了哪些具体机会？它让我开始用什么方式看自己？有没有一个更贴近事实、也更有行动空间的新名称？我能否把“我是这种人”改成“我曾经有这种行为/处境/反应”？', '["标签理论", "污名", "自我实现预言", "越轨", "身份羞耻", "去标签化", "行为修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 436, now()),
(100437, '身份不是本质：分类会被建构，却会产生真实后果', '【核心观点】性别、种族、族群、身体特征、残疾、宗教等身份，经常被人当作个人本质，但社会学更关注这些分类如何被社会赋予意义，以及它们如何影响机会和待遇。某些分类并非天然固定，却因为法律、学校、雇主、家庭和日常互动的反复使用而变得“真实”：它会决定别人如何看你、你能进入哪些空间、你是否更容易被怀疑、奖励或排斥。
【App落地】当用户遭遇性别偏见、地域标签、身材羞辱或族群歧视时，不宜只说“别在意”。更有帮助的是：承认这不是单纯敏感；区分生理事实、社会意义和具体待遇；记录发生过的行为；寻找制度性申诉、同伴支持和心理修复。
【关系成长】身份理解要避免两种极端：既不把人简化为标签，也不否认标签在现实中造成的机会差异和心理负担。App可提醒用户：我不是标签本身，但我确实可能生活在某些标签带来的现实后果里；成长既包括自我接纳，也包括为自己争取更公平的互动条件。
【可用提问】这个身份在我的生活里带来哪些优势、限制、误解或危险？我希望别人看见我的哪些复杂性？在争取被理解之前，我需要先为自己建立什么安全边界和支持网络？', '["身份", "社会建构", "性别", "种族", "歧视", "身份安全", "社会分类"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 437, now()),
(100438, '阶层不是努力排行榜：资源、压力和机会会代际累积', '【核心观点】阶层不只是收入高低，也包括教育机会、家庭资源、社会关系、健康风险、居住环境和未来想象。贫困的影响不止是“钱少”，还会带来长期压力、发展机会不足和选择范围缩小。社会流动研究提醒我们：一个人的出身资源与成年后的机会往往有关；向上流动的故事真实存在，但不能因此把未能流动的人解释成不够努力。
【App落地】当用户因家庭条件、学历、职业起点而羞耻时，可把问题改成资源地图：我目前缺的是钱、时间、证书、关系、信息、健康、照顾支持，还是安全环境？哪些资源能通过小步积累获得，哪些需要政策、机构、社群或专业支持？
【关系成长】阶层视角能减少伴侣、亲子之间的互相轻视：不同起点会塑造不同习惯和风险感，理解差异后再谈责任与计划。它也能提醒用户不要用单一成功标准评价自己：真正的问题不是“我为什么不像别人一样轻松”，而是“我在现有资源下如何获得下一份支持”。
【可用提问】我现在羡慕或责备的人，拥有哪些我没有看见的起点资源？我拥有哪些别人可能看不见的能力和支持？下一步是补资源、换环境、找导师，还是先停止把结构压力翻译成自我攻击？', '["社会分层", "阶层", "贫困", "机会不平等", "社会流动", "资源地图", "去羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 438, now()),
(100439, '文化资本与品味：别把“没见识/不高级”当成人格评价', '【核心观点】人们常以为品味只是个人喜好，其实谈吐、穿着、爱好、审美、教育经历和“知道什么”都会成为文化资本，影响别人如何判断一个人的地位和是否“合群”。所谓有品味，常常不是天生高级，而是某些家庭、学校和圈层更早、更自然地传递了特定规则。文化资本会帮助人进入机会场，也会把没有相同背景的人挡在门外。
【App落地】用户在社交、面试、亲密关系里因“我不够体面、不懂规矩、融不进去”而自卑时，不要把这解释成低价值。可以把隐藏规则显性化：这个场域看重什么语言、礼仪、知识和关系方式？哪些可以学习，哪些不必迎合？我能否在掌握规则的同时保留自己的出身经验和真实喜好？
【关系成长】学习文化规则是扩展选择，不是羞辱原来的自己。对App知识库而言，这一条可用于解释“社交自卑、阶层羞耻、伴侣消费观差异、见家长焦虑”等问题：冲突常常不是谁更高级，而是谁熟悉哪套文化密码。
【可用提问】我进入的这个圈层默认哪些知识是“大家都懂”的？我不懂时，是能力不足，还是没有被提前教过？我可以把哪些规则当作工具学习，又把哪些评价还给评判者？', '["文化资本", "品味", "阶层复制", "社交自卑", "场域规则", "身份认同", "职场成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 439, now()),
(100440, '工作压力不只是抗压差：好工作需要自主、信任、技能和稳定', '【核心观点】工作不只是换工资的地方，也提供日常结构、身份、关系、技能成长和未来机会。判断一份工作好不好，不能只看薪水，还要看自主权、被信任程度、社会地位、技能是否被使用、上升空间和稳定性。低控制、高监控、日程不稳定、福利缺失和随时可替代，会让人长期处在不安全感中；这类痛苦不是简单的“玻璃心”或“不会时间管理”。
【App落地】用户说“我上班很崩溃”时，可从工作结构评估：我能控制节奏吗？是否被严密监控？任务是否有意义或能成长？岗位是否稳定？组织是否把风险转嫁给个人？我需要的是情绪调节、边界谈判、技能转型、求职准备，还是外部保障？
【关系成长】把职场压力带回家庭时，伴侣双方可讨论制度压力如何进入关系，而不是只互相指责脾气差。对个体而言，也要把“工作表现”与“人格价值”分开：一份坏工作可以消耗人，但不等于这个人没有能力或没有价值。
【可用提问】这份工作最消耗我的，是任务量、关系、监控、低自主、低回报，还是未来不确定？如果我暂时不能离开，能否先增加一点控制感、恢复资源，并为下一次选择积累筹码？ 先稳住身心，再做职业判断。', '["工作", "组织", "自主权", "工作满意度", "职业压力", "稳定性", "职场心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 440, now()),
(100441, '家庭是电影不是照片：亲密关系要看过程、资源和支持', '【核心观点】家庭不是一种固定类型，而是一条不断展开的路径。外人看到的“完整家庭、单亲家庭、再婚家庭、双职工家庭、同性伴侣家庭”只是某一刻的照片；真正影响成员福祉的，是家庭过程：是否有安全、照顾、经济稳定、情感支持、灵活分工和应对变化的能力。现代家庭变化与经济重构、女性教育和就业、工作—照顾冲突、婚姻制度变化相连，不能简单归咎于“家庭价值崩坏”。
【App落地】处理家庭议题时，少问“这是不是标准家庭”，多问：谁在照顾谁？资源够不够？冲突是否安全？角色能否调整？有没有外部托育、亲友、社区、工作弹性或法律支持？
【关系成长】家庭压力往往来自旧制度脚本和新现实不匹配。帮助家庭创造更灵活的安排，比评判哪种家庭形式更高级更有效。对用户来说，重要的不是把家庭修成某张理想照片，而是在变化中持续增加安全、合作和可获得的支持。
【可用提问】家里真正需要被照顾的是什么：钱、时间、老人孩子、情绪、尊严，还是安全？现在的分工是因为大家都认可，还是因为旧脚本惯性运转？有没有一项任务可以重新分配或外包？ 重点是支持真实生活，而非维护面子。', '["家庭", "亲密关系", "工作家庭冲突", "照顾", "家庭过程", "多样化家庭", "社会支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 441, now()),
(100442, '谁在定义“正常”：越轨、道德和社会控制的关系视角', '【核心观点】越轨并不等于少见，也不等于天然坏。某行为是否被看成越轨，取决于群体规范、历史语境、权力关系和社会控制方式。穿什么、爱谁、喝酒、用药、离婚、未婚生育、精神疾病、犯罪等，都曾在不同时间被不同制度以不同方式定义和惩罚。真正需要追问的是：谁有权定义正常？谁承担污名和惩罚？这种定义保护了安全，还是维护了某种不平等？
【App落地】当用户因“不像别人”而羞耻，或被家人/团队说成“有问题”时，可先区分三层：1）是否存在实际伤害或安全风险；2）是否只是违反了某个群体的习惯；3）是否被权力较强的一方道德化。若有伤害，做修复；若主要是规范压力，就需要边界、同伴支持和低风险表达。
【关系成长】把“正常/不正常”的争吵改成“影响、风险、规则来源和选择空间”的讨论。这样既不浪漫化所有越界，也不把差异自动病理化，适合用于家庭冲突、性/亲密议题、社群排斥和自我接纳场景。
【可用提问】我被说成“不正常”时，对方具体担心的风险是什么？这个风险有没有证据？如果只是不同价值观的冲突，我可以用什么低风险方式表达自己，同时保护安全和退路？', '["越轨", "社会控制", "正常性", "道德化", "污名", "边界", "非病理化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 442, now()),
(100443, '把关系问题放回资源和规则中看', '当一个人反复在关系里感到“我说了也没用”“我总是要让步”，不必急着把答案归结为性格软弱、沟通技巧差或原生家庭创伤。伦斯基提醒我们：社会关系会进入人的自我意识，关系也不只是情感交换，还包含资源、规则和位置。App 端可把这个视角转成温和的自查：谁掌握时间、金钱、信息、评价权和退出权？谁能说“不”而代价较小？谁的情绪会被优先照顾，谁的需要常被推迟？这些问题不是为了制造阵营，而是为了减少无谓自责。适用场景包括伴侣中一方长期解释、家庭中某个孩子总被要求懂事、团队里新人没有发言权。更完整的关系成长问题是：在承认个人责任的同时，能否把隐形规则说出来，把“我是不是太敏感”改成“这个互动结构让谁更有余地，谁更容易失声”。接下来的行动可以很小：澄清一条规则、要求一次平等反馈、把资源信息透明化、为拒绝设置可承受的后果、找一个见证者陪自己复盘。如果关系已经存在明显威胁，优先考虑安全和支持网络，而不是继续证明自己讲得有道理。这样，改变不只是调整心态，也是在重建更安全的互动条件。用于知识库问答时，可把它放在“关系中总觉得低人一等”“为什么我总是解释不清”“我是不是太敏感”等问题下，作为从自责转向结构觉察的入口。', '["权力结构", "关系成长", "资源差异", "自我责备", "边界", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 443, now()),
(100444, '需要与权力：冲突背后常有两套分配逻辑', '书中把分配过程概括为两条看似矛盾的原则：需要和权力。为了让合作继续，成员的基本生存和生产能力要被维持；但一旦出现“剩余”——额外机会、荣誉、金钱、关注、时间、晋升名额，谁能拿到更多，往往取决于权力如何分布。关系里的很多冲突也可以这样看：一方在说“我有基本需要，希望被听见、被照顾、被公平对待”，另一方却在用权力逻辑回应：“资源由我安排，规则由我解释，你要适应”。App 可引导用户把冲突拆开：这是基本需要没有被承认，还是额外资源的分配没有规则？谁拥有决定权？有没有申诉、协商、暂停和复盘机制？例如伴侣争吵中，“请你不要羞辱我”属于基本尊严需要；“周末更多时间按谁的偏好安排”则是可协商资源。亲子关系中，安全和照料是基本需要，零花钱、屏幕时间、课外选择则需要透明规则。内容落地时可用三问：我真正要保护的需要是什么？对方手里有什么决定权？是否能把决定权变成双方都看得见的流程？这样做能避免把所有矛盾都道德化，也能避免只讲爱与理解而忽略现实差异。真正可持续的亲密或合作，不是取消所有差异，而是让基本需要有保障，让额外资源的分配可以被讨论、被解释、被修正。', '["需要", "权力", "冲突理解", "资源分配", "亲密关系", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 444, now()),
(100445, '特权是行动余地，不是给人的总评', '“特权”在心理教育中容易被听成指责，好像某个人有特权就等于他没有痛苦、没有努力、道德上低人一等。书中的用法更适合被转译为“行动余地”：谁能控制更多剩余资源，谁就更容易拥有选择、缓冲和被原谅的空间。一个人可能在某些维度有优势，在另一些维度受限；同一个人也可能因财产、职业、教育、性别、年龄、户籍、家庭关系等不同角色，被放进不同的阶级系统。App 可以用非羞辱的方式帮助用户识别：我有哪些别人没有的支持？我在哪些地方比别人少了选择？哪些失败不是能力差，而是起点、规则和缓冲垫不同？例如“父母能托底”会让试错成本更低，“熟悉面试语言”会让能力更容易被看见，“有安全住房”会让人更能专注学习。识别特权的目的不是互相扣帽子，而是把现实说清楚：优势方可以更少防御、更愿意透明和让利；弱势方可以减少“都是我不够好”的自责，转而寻找资源、联盟和规则修正。它也适合亲密关系中的修复：拥有更多余地的一方可以先承担解释、等待和补偿成本。提醒用户也要避免反向简化：有优势的人仍可能受伤，有劣势的人也仍有行动力。特权是一张现实地图，不是给人盖棺定论。', '["特权", "行动余地", "自我评价", "多重身份", "资源地图", "去羞辱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 445, now()),
(100446, '隐性门槛：教育、语言和家庭资源会变成机会差', '现代社会常把教育和证书包装成“客观标准”，这比赤裸裸的世袭更容易被接受，也确实扩大了很多人的机会。但 OCR 文本提醒：教育机会并不等于真正平等。家庭背景会通过财力、语言技能、动机、私人学习条件、信息和期待进入孩子的竞争过程；组织越科层化，学历越容易成为雇用和晋升的前提，于是教育地位本身就变成争夺权力和特权的资源。App 端可以把这条知识用于缓解隐性羞耻：用户如果因为学历、表达、面试、职场晋升受挫而自我否定，先不要只问“我是不是不够聪明”，也要问“我缺的是知识、证书、语言环境、作品机会、导师推荐，还是熟悉规则的人”。这不是否认努力，而是让努力更精确。适用场景包括第一代大学生不懂实习路径、职场新人不会包装项目、转行者缺少证书和行业暗语、来自低资源家庭的人不敢谈判薪资。成长建议可以从补齐门槛开始：拆出可学习的技能、寻找低成本训练、建立信息来源、请求反馈、用阶段性目标替代和高资源者的一次性比较。对于咨询话术，可把“你要更自信”改成“我们一起找出哪条规则还没人教过你”。对用户的核心安抚是：卡住不一定说明你差，也可能说明你正在碰到过去没人帮你翻译的门槛。', '["隐性门槛", "教育资源", "家庭背景", "机会差异", "职场成长", "羞耻修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 446, now()),
(100447, '地位不一致：同一个人会在不同场域被高看或低看', '一个人并不只有一个身份。有人在职业上很受尊重，却因性别、年龄、地域、种族、家庭出身或经济条件被轻视；也有人在家庭中被要求服从，在工作中却承担重要责任。书中把这种现象称为地位不一致，并指出它会带来紧张：当事人自然倾向于按自己最高的地位来理解自己，也期待别人如此对待；而互动中的另一方可能出于利益或习惯，按其最低位置来对待他。App 可把这转化为关系觉察工具：当你突然感到羞辱、愤怒或“我被看扁了”，先问：对方激活了我的哪一重身份？我希望被按哪条规则对待？对方坚持的是哪条排序？这能帮助用户把痛苦从“我不值得”改写为“我的多重身份被不公平地压低了”。应对上，不一定要立刻证明自己全部价值，而是选择适当场域主张规则：在专业场景回到专业标准，在亲密关系表达尊重需求，在家庭场景说明成年人边界，在不安全环境保留能量并寻找承认自己完整身份的支持群体。它也适合解释一些“明明我做得很好，却仍感到被羞辱”的体验：受伤点不在能力本身，而在对方拒绝承认你的完整位置。也要提醒用户：别人偶尔误读不等于你必须耗尽自己纠正；持续的地位压低才需要明确边界、减少暴露或更换环境。', '["地位不一致", "多重身份", "羞耻", "尊严", "关系误读", "社会分层"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 447, now()),
(100448, '自尊与地位：被尊重是心理需要，但排序不是全部价值', '书中关于地位和声望的段落很适合进入心理教育：人们常否认自己在意地位，但许多选择都会受它影响。更深层的原因是，自尊在很大程度上依赖重要他人的尊重；一个人在家人、朋友、同事或所属群体中被如何看见，会影响自我形象和心理健康。App 需要同时传递两点：第一，想被尊重不是虚荣，而是正常的心理需要；第二，把自我价值完全押在外部排序上，会让人陷入无止境比较，因为地位欲望很容易变成“再多一点才够”。可设计练习：列出真正重要的三个评价共同体，而不是让所有人都认可自己；区分“尊严”与“排名”——尊严是基本被当人对待，排名是某个场域里的相对位置；在受挫后寻找具体反馈，而不是把一次低评价扩展为“我整个人不行”。在关系中，也可以把“你不尊重我”翻译得更具体：是没有听完、公开贬低、忽视贡献，还是把你排除在决定之外？越具体，越容易修复。对于比较焦虑强的用户，可引导他建立多来源自尊：能力、关系、身体照顾、价值实践、创造和贡献都能提供稳定感。若用户把所有精力都投入赢得某个圈层认可，App 可提示他检查代价：我是在追求被看见，还是在用排名逃离羞耻？这样既承认社会评价的力量，又不让它垄断内在价值。', '["自尊", "地位", "声望", "尊严", "比较焦虑", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 448, now()),
(100449, '从强力到规则：安全关系需要可预期的权利', '书中讨论权力时指出，强力或威胁是最直接的控制方式，但单靠强力代价高，也难以形成稳定秩序；当权力转向被承认的规则和权利时，虽然仍不完美，却会带来细微而深远的改变。关系成长可以借用这个逻辑：如果家庭、伴侣或团队里的每次冲突都由“谁声音大、谁掌钱、谁能惩罚、谁能冷暴力”决定，弱势一方会越来越沉默，表面平静却没有安全。更健康的关系需要可预期的权利：每个人都有表达、拒绝、解释、暂停、保留隐私、使用共同资源和寻求外部支持的空间。App 可建议用户把抽象公平落成规则：争吵时不威胁分手或断供；重大花费有共同知情权；拒绝亲密接触不被惩罚；复盘时先说影响再说动机；任何一方都可以提出暂停但必须约定回来讨论的时间。规则不是为了让关系变冷，而是让爱不必依赖谁更强。若用户总在问“我怎样才能让他别生气”，可以转问“我们有没有一套不靠恐惧维持的规则”。若规则被反复破坏，重点就不再是把话说得更漂亮，而是评估边界、支持和退出成本。真正的安全感来自“我即使不同意，也不会被剥夺基本尊严”。对关系训练而言，规则还要定期复盘：哪些规则真的保护了双方，哪些规则只是在维护某一方的方便或面子。', '["安全感", "规则", "权利", "关系边界", "控制关系", "尊严"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 449, now()),
(100450, '公民权思维：把被动忍耐转化为可表达的共同权利', '书中把公民权视为一种资源：它不像财产那样只属于少数人，而是在现代社会中逐渐成为更普遍的权利基础。转译到 App 端，不需要做政治动员，而是帮助用户建立“共同权利”的关系语言。很多人在弱势关系里只会忍、讨好或爆发，因为他觉得自己没有资格要求；公民权思维提醒他：有些东西不是奖励，而是基本权利，例如被倾听、不被羞辱、获得必要信息、休息、拒绝、申诉、求助和参与与自己有关的决定。它也提醒优势方：共享规则不是失去权威，而是让关系更可持续。练习上，可以把抱怨改写成权利和请求：“我不是要赢你，而是希望我们都能在争执中不被辱骂”；“我需要知道这笔共同开支的去向”；“我希望有一个可以暂停对话的规则”。当个人资源不足时，用户也可以寻找同伴、制度、专业支持或第三方协助。适用场景包括家庭照护分工、伴侣财务透明、职场加班边界、社群发言规则。在群体关系里，它还可以帮助用户从“求某个人开恩”转向“让规则对所有人一致”。提醒：权利语言不是任性索取，它总是和同等尊重、事实核对、愿意协商相配套。共同权利让人从孤立忍耐走向有边界的表达。', '["公民权", "共同权利", "表达", "边界", "关系协商", "赋权"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 450, now()),
(100451, '冲突不是人格失败：通道不足时，人会寻找制度化行动', '用户常把冲突理解为“我情绪管理差”“我不够成熟”。书中提供了另一种视角：当个人流动机会不足、单靠个人努力拿不到应得报酬时，人们常会转向集体行动；在现代社会，冲突也不必总是暴力，它可以通过合法、非暴力、制度化的方式表达。放到关系和职场中，这意味着反复出现的问题不一定靠更温柔的语气就能解决。若资源、职责、晋升、家务、照护或话语权长期没有通道，冲突会不断回流。App 可引导用户区分三种层次：情绪层——我被触发了什么；关系层——我们如何沟通和修复；制度层——有没有清晰流程、分工、反馈和申诉。成熟不是永远不冲突，而是把冲突从攻击人格转成修正规则：记录事实、提出可验证请求、寻找共同目标、引入第三方、设定复盘时间。也要承认，同一个人可能在冷淡、个人奋斗、合作和抗议之间摇摆；这种复杂反应不等于虚伪，而是人在有限通道中寻找出路。对 App 提示语来说，可以从“别想太多”改成“你想改变的是情绪强度、互动方式，还是资源规则”。如果用户已经多次温和表达无效，下一步也许不是更压抑，而是升级为书面确认、共同会议或外部支持。这会让用户更容易选择合适行动，而不是把所有责任压回自己身上。', '["冲突", "制度化表达", "职场关系", "家务分工", "申诉", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 451, now()),
(100452, '避免单一解释：把阶层和权力拆成可观察变量', '书中反复提醒，传统争论容易被“非此即彼”的概念困住：不平等到底合理还是不合理、社会到底是合作系统还是斗争舞台、某人到底是强者还是弱者。更有用的方法，是把绝对概念改成变量，把复合概念拆成组成部分。App 端可把它做成提问模板：这里涉及哪种资源——金钱、教育、职业、职位、年龄、性别、身份、家庭网络、信息还是身体安全？它的强度有多大？能不能流动？是法律支持、习俗支持，还是靠情绪压力维持？当事人是否在不同系统里位置不一致？这样做能避免两种极端：一种是把所有痛苦都归咎于个人不努力，另一种是把所有选择都交给抽象结构。拆成变量后，用户更容易找到可行动的点：补资源、改规则、换场域、找盟友、练表达、降低不必要比较。举例说，“我在公司被压制”可以拆成岗位权责、绩效标准、上级评价权、同事联盟、行业证书和个人表达策略；“我在家庭里没地位”可以拆成经济依赖、照护贡献是否被看见、长幼规则、房屋所有权和情感威胁。输出时要避免给用户一个宏大标签，而是给他一张小地图：哪一块能改，哪一块要借力，哪一块暂时只能保护自己。复杂化不是为了让人无力，而是为了把模糊压迫感变成可观察、可讨论、可调整的现实。', '["社会分层", "变量思维", "复杂问题", "结构性压力", "行动方案", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 452, now()),
(100453, '社会学视野：把个体困扰放回社会情境', '核心观点：社会学视野不是替个人找借口，而是把“我怎么会这样”扩展为“我处在什么关系、类别和制度中”。书中反复说明，婚恋、生育、职业、失业，甚至看似最私人的自我感受，都有社会模式在背后参与：性别、年龄、阶层、教育、种族、时代变迁和全球经济，会影响一个人能看见什么选择、能承担什么风险、会被怎样评价。
App 端可用法：当用户陷入强烈自责时，先做三步重构。第一，把问题从人格判决改成情境描述：不是“我无能”，而是“我正在面对某个就业、家庭或关系结构”。第二，区分个人可行动部分与结构限制：能调整的是技能、求助、沟通和边界；不能独自承担的是行业收缩、家庭资源差异、社会偏见。第三，把孤立感转成共同经验：许多人不是因为“不够努力”才受困，而是在同一种制度压力下出现类似反应。
关系成长提示：社会学视野能降低羞耻，却不取消行动。它帮助用户少一点自责，多一点观察；少问“我是不是坏了”，多问“哪些关系和规则正在塑造我，我可以从哪里重新选择”。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会学视野", "社会情境", "去自责", "结构性压力", "关系成长", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 453, now()),
(100454, '文化与规范：误解常来自不同的符号系统', '核心观点：文化并不只是“风俗习惯”，而是由符号、语言、价值观和规范组成的意义系统。一个眼神、一句玩笑、一种穿着、一顿饭的礼仪，在不同群体里可能完全不是同一件事。文化震惊之所以让人迷失、孤独甚至害怕，是因为原来能自动指导行动的符号突然失效了；人不知道该怎样解释别人，也不知道自己怎样做才合适。
App 端可用法：处理亲密关系、代际沟通、跨地域或职场冲突时，不要急着判断“对方没礼貌”“我不被尊重”。可以先问四个问题：我们对同一个动作赋予的意义一样吗？这条规则是家庭规则、地方文化、阶层习惯，还是组织规范？我是在用自己的标准评价对方，还是愿意先理解对方文化内部的逻辑？哪些规范必须尊重，哪些规范可以协商更新？
成长方向：文化相对主义不是无限纵容，而是先暂停“我的方式才自然”的反射。它让用户在差异中保持好奇：先翻译，再表达；先核对意义，再处理边界。这样能减少关系中的误读，也能帮助用户在新环境里建立安全感。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["文化", "规范", "文化震惊", "跨文化沟通", "关系误读", "边界协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 454, now()),
(100455, '社会化：人格不是孤岛，而是长期关系训练', '核心观点：社会化是一生都在发生的过程。家庭、学校、同辈群体和大众传媒不断教人“我是谁”“什么值得追求”“怎样才算合格”。早期照料会影响信任感和安全感；家庭的阶层、种族和资源会影响孩子的自我定位；学校会扩大儿童的社会世界，也会通过隐性课程教会竞争、服从、时间表和官僚规则；同辈群体影响青春期的归属与风格；媒介则把远方的图像、欲望和标准带进日常生活。
App 端可用法：当用户把性格完全归因于“我天生如此”时，可以引导他做社会化地图：我从家庭学会了什么情绪规则？学校奖励过我哪种表现？同辈群体让我害怕哪种“不合群”？媒体让我把怎样的身体、成功、恋爱当成标准？这些规则哪些曾经保护过我，哪些现在让我受限？
关系成长提示：看见社会化，不是为了怪父母、学校或社会，而是为了把自动反应变成可选择的反应。一个人可以承认过去塑造了自己，同时通过新的关系、新的学习和新的社群经验，继续再社会化。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会化", "家庭影响", "同辈群体", "大众传媒", "生命历程", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 455, now()),
(100456, '地位与角色冲突：压力常是多个身份同时要你负责', '核心观点：每个人都同时拥有多个地位：子女、伴侣、父母、学生、员工、朋友、照料者、领导者。每个地位都带来一组角色期待。压力不一定来自“内心不够强大”，也可能来自多个角色同时索要时间、情绪和责任：一边要做可靠员工，一边要做在场父母；一边要做孝顺子女，一边要维护伴侣边界；一边想亲近学生或下属，一边又要保持公平与专业距离。
App 端可用法：用户说“我什么都做不好”时，可以改问：“现在有哪些角色同时在要求你？”把冲突拆成角色清单：哪些期待来自制度，哪些来自家庭文化，哪些是自己内化的完美标准？哪些角色必须同一时间完成，哪些可以分区、排程、委托或重新谈判？
关系成长提示：角色冲突的解决不只是情绪管理，也需要结构设计。可建议用户建立“角色边界”：工作时间不默认随时回应家庭事务，家庭时间不默认被工作侵入；照料别人时保留个人恢复时间；向重要他人说明自己不是拒绝关系，而是在分配有限能量。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["角色冲突", "角色紧张", "身份压力", "工作家庭平衡", "边界", "责任分配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 456, now()),
(100457, '性别角色：把“天生应该”还原成社会期待', '核心观点：性别不只是生物差异，更是社会赋予“女性/男性”的意义、资源和限制。书中用跨文化研究说明，不同社会对“男子气质”“女子气质”的定义差异很大，很多被说成天生的分工，其实是文化和制度长期训练的结果。性别分层还会进入家庭、学校、职场和政治：女性常被期待承担更多照料和家务，男性则被期待竞争、坚强、少表达脆弱。
App 端可用法：当用户因“不够像男人/女人”而羞耻，或因家务、育儿、职业选择发生冲突时，可以帮助他把问题从人格评价转成规则识别：谁规定这件事必须由某个性别承担？这条规则对谁有利、让谁疲惫？我真正认同它，还是害怕不遵守会被否定？
关系成长提示：性别平等不是把所有人变得一样，而是让每个人都能协商适合自己的责任和表达方式。伴侣或家庭可以把“你本来就该做”改成“这件事需要谁做、怎样分担才公平”；个人也可以允许自己发展被性别脚本压下去的能力，比如男性练习求助，女性练习主张。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["性别角色", "性别分层", "家务分工", "父权制", "关系协商", "去标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 457, now()),
(100458, '家庭不是纯私域：爱也被资源、权力和制度塑形', '核心观点：家庭既是亲密关系，也是社会制度。它把人们组织起来相互照料、养育子女、传递身份、资源和规则。家庭可以提供情感支持和经济保护，也可能复制不平等：财产继承、父权制、种族与阶层内婚、家务分工和家庭暴力，都说明“家里的事”并不只是私人性格问题。现代家庭形式不断变化，核心家庭、扩大家庭、单亲、再婚和混合家庭，都需要重新定义责任和归属。
App 端可用法：当用户谈原生家庭、婚姻、离婚、育儿或照料老人时，可以同时看三层：情感层，我是否被看见、被支持；资源层，钱、时间、住房、教育机会如何分配；权力层，谁有决定权，谁承担无偿劳动，谁的需求被默认牺牲。
关系成长提示：家庭修复不是回到某个想象中的“传统正确家庭”，而是建立更清楚的照料契约。可引导用户把模糊期待写成可讨论的问题：谁负责什么，边界在哪里，冲突如何处理，孩子和老人需要哪些支持，哪些责任不能只压在一个人身上。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["家庭制度", "亲密关系", "照料劳动", "家庭权力", "混合家庭", "原生家庭"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 458, now()),
(100459, '教育与自我预言：学校既打开机会也复制差距', '核心观点：教育一方面传授知识、社会化年轻人、整合多样人口、分配社会位置；另一方面也可能把家庭资源差异包装成个人能力差异。学校里的标签会变成自我实现预言：当老师、制度或同伴把某些学生看成“聪明”“不行”“适合普通轨道”，学生可能在互动中逐渐活成这些期待。标准化考试、教育分流、学区资源差异和家庭文化资本，会让本来就有优势的孩子继续获得更好的机会。
App 端可用法：面对学习挫败、考试焦虑、学历自卑或亲子教育问题时，不要只问“孩子够不够努力”。也要问：学校给了什么标签？班级和老师如何回应？家庭能否提供安静空间、阅读支持、补习资源和稳定期待？孩子是在学习困难，还是在被长期低期待训练？
成长提示：教育仍然是流动通道，但需要反标签使用。对孩子和成人学习者，都要把评价从身份层拉回策略层：不是“我笨”，而是“我缺少某种训练、资源或反馈”。高期待要配高支持，才不会变成新的压力。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["教育", "自我实现预言", "教育分流", "文化资本", "学习焦虑", "机会不平等"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 459, now()),
(100460, '工作与后工业压力：职业焦虑背后有技术、全球化和组织结构', '核心观点：现代工作不只是个人职业选择，而是经济制度、技术变迁和全球分工共同塑造的结果。后工业经济把重心从制造业转向服务、信息和符号劳动；电脑和网络让“虚拟办公室”随处存在，也模糊了工作与生活边界。失业并不只是个人能力不足，岗位会因公司重组、行业老化、外包、经济衰退和技术替代而消失；即使有工作，很多人也面临低薪、福利减少、兼职化和被持续监控的压力。
App 端可用法：当用户因失业、转行、职业倦怠或被算法管理而自责时，可做结构化复盘：我的行业处在扩张还是收缩？技能是否被新技术替代？公司是否在全球范围寻找更低成本劳动力？我承受的是个人绩效问题，还是组织把风险转嫁给个人？
成长提示：职业韧性不是无限加班，而是提高可迁移能力、维护支持网络、谈判边界和识别结构风险。用户可以为自己保留恢复时间，减少把工作成败等同于人格价值；同时把求职和学习看成对环境变化的适应，而不是对“失败自我”的补救。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["工作压力", "后工业经济", "失业", "技术变迁", "全球化", "职业倦怠"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 460, now()),
(100461, '越轨与标签：不要让一次行为变成整个人的判决', '核心观点：越轨不是某些“坏人”的固定属性，而是社会如何定义规范、发现偏离并做出反应的过程。同一个行为可能被看成粗心、借用、叛逆、疾病或犯罪，取决于情境、权力和他人的解释。标签理论提醒我们：一次轻微偏离如果引发强烈排斥，可能改变一个人的自我概念，使他被迫进入“越轨者”身份；污名一旦成为主要身份，其他品质就容易被遮蔽。
App 端可用法：在亲子、伴侣、学校和社群中，慎用“你就是懒、坏、疯、没救”这类身份标签。更好的做法是区分行为、需要和影响：你做了什么？伤害了谁？背后可能有什么压力或需求？下一步如何修复？对于成瘾、心理困扰、肥胖、创伤反应等议题，既不要道德审判，也不要随意诊断，而是看功能损害、支持资源和专业帮助。
成长提示：去标签化不是否认责任，而是保留改变空间。让人对具体行为负责，同时不把他锁死在一个负面身份里，关系才可能修复，个人也更可能重新选择。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["越轨", "标签理论", "污名", "去标签化", "修复责任", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 461, now()),
(100462, '群体与组织：归属感、参照群体与科层效率的两面', '核心观点：人需要群体归属，但群体也会塑造比较、从众和自我评价。初级群体如家庭和亲密朋友提供情感连接，让人感到“我们”；次级群体如学校、公司和机构更目标导向、非个人化。人还会用参照群体衡量自己：想进入某个圈子时，会提前模仿其穿着、语言、价值和行为。现代社会越来越依赖正式组织和科层制，它们通过分工、层级、规则、绩效和档案提升效率，却也可能带来去人情化、仪式主义和异化。
App 端可用法：用户在团队、社群或职场中受困时，可区分三类压力：归属压力，我害怕被排除；参照压力，我用谁的标准评价自己；组织压力，我被哪些流程、KPI、规则和层级影响。这样能避免把所有问题都解释成“我不会社交”。
成长提示：健康的群体既要有情感连接，也要有清楚规则；健康的组织既要有效率，也要保留人的弹性。个人可练习选择参照群体、建立小型支持关系，并在大型组织中为自己争取可理解、可协商的空间。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["群体", "组织", "参照群体", "科层制", "归属感", "职场关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 462, now()),
(100463, '阶层与社会流动：努力有用，但起点与机会结构也在场', '核心观点：社会分层是把人们按等级组织起来的制度，不只是个人天赋和努力的差别。泰坦尼克号案例显示，阶级位置甚至会影响生死机会；现实中，家庭出身会影响健康、教育、职业、收入、寿命和社会网络。社会流动确实存在，但并不对所有人同样开放。阶层还需要意识形态维持：例如把富有解释为聪明勤奋，把贫困解释为懒惰，就会让不平等显得“公平”。
App 端可用法：当用户因收入、学历、住房、婚恋门槛或职业发展而自卑时，可以把“我差”拆成资源地图：我继承了哪些资源或缺口？教育、家庭、地域、性别、种族/族群、健康如何影响机会？我有哪些可动用的桥接资源，如培训、导师、同伴、制度福利和长期储蓄？
成长提示：承认结构不等于放弃努力，而是让努力更准确。对处在劣势的人，重点不是羞辱式鸡血，而是降低孤立、找到现实通道、积累可迁移资本；对处在优势的人，则要发展阶层觉察，避免把他人的困难简单归因为“不努力”。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会分层", "社会流动", "阶层", "贫困羞耻", "机会结构", "资源地图"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 463, now()),
(100464, '现实是互动中建构的：关系修复从改写情境定义开始', '核心观点：日常关系不是简单地“发生”，而是在互动中被共同定义出来的。一个眼神被理解成关心还是嘲讽，一次沉默被理解成冷暴力还是需要空间，都会影响后续反应。书中“现实的社会建构”和托马斯定律提醒我们：如果人们把某个情境当成真实，它就会产生真实后果。学校里的自我实现预言也是同样机制：被期待优秀或失败的人，可能在互动中逐渐表现出相应样子。
App 端可用法：处理冲突时，可引导用户做“情境定义复盘”：我当时把对方的行为定义成什么？对方可能怎样定义我的行为？我们的定义是否被旧伤、阶层、性别、权力或文化差异放大？如果换一个可检验的定义，我会怎样回应？例如把“他故意不回”暂时改成“我还不知道原因，需要核对”，就能为关系留下空间。
成长提示：改写情境定义不是自我欺骗，而是停止把猜测当事实。先核对、再表达影响、再提出请求，可以让互动从敌意循环回到共同解决。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["现实建构", "托马斯定律", "自我实现预言", "冲突复盘", "关系修复", "沟通核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 464, now()),
(100465, '社会变迁：焦虑来自变化太快，不只是个人不适应', '核心观点：社会变迁一直在发生，但现代和后现代社会的变化速度特别快。技术、人口、冲突、观念传播和全球扩散会改变家庭、工作、城市、身份和价值。变化不总是进步：汽车、电视、电脑和网络带来便利，也带来环境压力、隐私风险、旧职业消失、社区疏离和身份摇摆。现代性给人更多自由和选择，却也让传统标准松动，许多人在“我是谁”“该怎样生活”上感到不稳定。
App 端可用法：当用户说“我跟不上时代”“我总在比较”“我不知道自己是谁”时，可以把焦虑放回社会变迁：平台和技术是否改变了工作节奏？家庭模式是否比上一代更多样？价值标准是否同时来自传统、消费文化、同辈和全球媒体？用户的困惑也许不是个人失败，而是多套规则并存造成的适应成本。
成长提示：面对变迁，目标不是追上所有变化，而是建立自己的稳定锚点：可靠关系、身体节律、核心价值、可学习能力和有限信息边界。允许自己在变化中慢慢重组身份。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会变迁", "现代性", "后现代性", "身份焦虑", "技术影响", "适应压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 465, now()),
(100466, '社会学式助人：从责怪个人到调整关系和制度场域', '核心观点：这本书的许多主题可以合成一个 App 端底层原则：个体痛苦常常同时发生在身体、关系、组织和制度场域中。一个人的“问题行为”可能连着家庭社会化、学校标签、阶层资源、性别分工、工作制度、群体归属和文化规范。只做心理内部解释，容易把结构压力变成羞耻；只做社会批判，又可能让人失去行动感。社会学式助人要同时保留两者：看见结构，也寻找可操作的小改变。
App 端可用法：面对任何用户困扰，都可以用“五问”快速定位：第一，我把自己放进了哪些身份和角色？第二，谁的规范正在评价我？第三，我所在的家庭、学校、职场或社群怎样分配资源和权力？第四，有没有标签或污名正在缩小我的选择？第五，在现有结构里，我能争取什么支持、调整什么边界、改变什么互动？
成长提示：把问题放回场域，会让助人语言更温和也更有力量。它不说“都是你的错”，也不说“你什么都不能做”，而是帮助用户从孤立个体回到关系网络，再从关系网络中找到下一步。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会学助人", "场域视角", "关系制度", "去羞耻", "App问答框架", "结构与行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 466, now()),
(100467, '把个人困境放回结构中看：少一点自责，多一点可行动的理解', '核心理解：社会分层不是简单的“有人富、有人穷”，而是资源、声望、权力和机会被制度化地分配到不同位置。一个人的心理压力、健康、寿命、受教育机会和可选择的生活方式，都会受到这种位置影响。
关系启发：当自己或伴侣陷入失业、债务、低收入、住房不稳、教育受限等处境时，如果只用“你不够努力”“我太差劲”解释，很容易制造羞耻、怨怼和防御。更成熟的看法是同时看三层：我能做什么、身边有哪些资源、外部结构正在给我什么限制。
练习提示：把困扰写成三栏：结构压力（收入、时间、家庭责任、地域、健康）、可控小步（今天能完成的一个动作）、可调用支持（朋友、机构、专业服务、社区资源）。这样既不否认个人责任，也不把全部重量压在自尊上。
App端使用：这条适合放在“停止过度自责”“理解伴侣压力”的场景。它要传达的不是受害者身份，而是一种双焦点能力：既看见结构限制，也保留下一步行动。用户可以被邀请写下：哪些困难不是我一个人造成的，哪些部分仍可由我今天启动。
适用边界：条目不鼓励把所有问题外包给社会，也不鼓励对立；它强调把责任放回合适层级，让用户既能保护自尊，也能恢复行动感。', '["社会分层", "结构压力", "自责", "自尊", "心理教育", "生活机会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 467, now()),
(100468, '不平等不只收入：基本生活、健康和公共声音都会进入情绪', '核心理解：收入和财富只是可见部分，真正进入日常心理的，还包括食物、住房、医疗保健、安全环境、交通、教育、公共服务和表达利益的机会。基本必需品价格、补贴制度和医疗分配方式不同，会让同样收入的人承受完全不同的压力。
关系启发：很多焦虑、易怒、拖延和亲密关系冲突，并不是单纯情绪管理差，而是长期资源紧张造成的心理带宽不足。一个家庭若总在为房租、看病、孩子教育或父母照护作选择，伴侣之间容易把资源不足误读为“不在乎我”“不负责任”。
练习提示：讨论冲突前先问：这件事背后有没有基本需求没有被满足？是钱不够、时间不够、健康资源不够，还是信息和公共支持不够？先承认现实压力，再谈分工与沟通，能显著降低互相指责。
App端使用：可用于金钱焦虑、伴侣财务争吵、照护压力和健康焦虑模块。引导语可以是：先确认基本需求有没有缺口，再谈情绪技巧。若底层需求持续未满足，冥想、沟通话术和时间管理只能缓解表层，仍需要实际资源、制度信息和社会支持介入。
适用边界：若用户处在急性危机，如断供、无家可归、医疗中断，应优先链接现实援助；心理教育只作为稳定情绪和组织求助的辅助。', '["不平等", "基本需求", "健康资源", "安全感", "情绪压力", "关系冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 468, now()),
(100469, '先赋与自致：努力有价值，但起点并不相同', '核心理解：书中区分“先赋”和“自致”。先赋是出生阶级、性别、族群、家庭资源等个人无法选择的条件；自致是能力、学习、勤奋、选择和成就。现代社会常强调自致，但多数人的位置其实由两者共同塑造。
心理启发：理解先赋，不是为放弃找理由，而是减少有毒比较。一个人在更少安全感、更少教育支持、更少人脉和更高家庭责任下前进，本来就需要消耗更多能量。把自己和资源条件完全不同的人比较，容易损伤自尊，也容易把愤怒投向家人或伴侣。
练习提示：评估目标时同时写下“我能训练的能力”和“我需要补齐的条件”。把努力从证明自我价值，转向建设条件：补证书、找导师、扩大信息源、降低不必要消耗。努力仍然重要，但它需要被放在真实起点上设计。
App端使用：适合在比较心、成就焦虑和亲子期待主题中使用。它帮助用户把“别人能做到为什么我不能”改写为“我的起点、负担和资源组合是什么”。这会让目标更公平，也让亲密关系中的鼓励从施压变成共同建设条件。
适用边界：它不是否定努力，而是帮助用户选择更聪明的努力顺序：先补关键条件，再提高执行强度，避免用意志力硬扛结构差距。', '["先赋", "自致", "机会", "自我评价", "成长", "公平感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 469, now()),
(100470, '社会流动：向上不是个人意志的直线，而是教育、职业结构与支持网络的合力', '核心理解：社会流动研究关心一个人相对父母位置是上升、下降还是停留原位；地位获得研究进一步追问为什么会这样。书中梳理的模型显示，父母教育、父母职业、家庭社会经济地位，会通过教育机会、抱负、同辈关系和初职影响后来的职业位置；同时，职业结构本身也会改变流动空间。
关系启发：当家庭成员期待孩子“必须翻身”、伴侣期待对方“赶快成功”时，若忽略教育、行业、地域和中等收入岗位变化，就容易把结构性困难变成羞辱。更好的方式是一起画机会地图：现在有哪些门槛、哪些证书有用、哪些行业在扩张、谁能提供信息。
练习提示：把目标拆成四类资源：技能、证书、信息、人际支持。每类只选一个最小行动，而不是用一句“我要逆袭”承担全部压力。
App端使用：可设计为“机会地图”工具。用户选择一个目标后，系统提示其填写教育门槛、行业门槛、经济缓冲、推荐关系和可替代路径。这样能把抽象成功学转成路径规划，也帮助家庭成员从催促结果转向支持过程。
适用边界：不要把流动困难解释成命运注定。即使大结构有限，具体行业、城市、证书、人脉和时间窗口仍会形成可操作的微机会。', '["社会流动", "地位获得", "教育", "职业", "家庭背景", "支持网络"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 470, now()),
(100471, '阶级经验会进入自尊、品味和亲密关系：差异不等于高低', '核心理解：阶级地位不只影响收入，也会影响幸福感、自尊、工作满意度、说话方式、衣着品味、居住区、休闲方式和对教育的熟悉程度。书中把这些称为阶级亚文化和生活方式：它们多是不同资源与经历长期形成的差异，不应被简单评判为谁更高级。
关系启发：伴侣或姻亲之间常因消费观、礼仪、表达方式、孩子教育、职业选择发生摩擦。表面上是在争“你懂不懂规矩”“你太虚荣/太寒酸”，底层可能是不同阶级经验对安全感的理解不同：有人用储蓄抵御风险，有人用体面避免被轻视，有人用教育投资换未来机会。
练习提示：遇到差异先翻译成经历问题：这个习惯曾经保护过对方什么？它满足的是尊严、安全、归属还是未来感？先理解功能，再协商边界。
App端使用：适合跨阶层伴侣、婆媳/姻亲冲突、消费观差异和羞耻感主题。提醒用户：对方的品味和表达方式不是人格高低，而是生活史的痕迹。真正要协商的是共同生活的预算、尊重、边界和孩子教育，而不是赢得谁更“正确”。
适用边界：理解差异不等于纵容伤害。如果品味差异演变为羞辱、控制或经济压迫，仍需要清晰边界和具体协议来保护双方尊严。', '["阶级亚文化", "自尊", "生活方式", "关系冲突", "尊重", "家庭沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 471, now()),
(100472, '资源集中与社交网络：机会常在关系网络中流动', '核心理解：位于分层体系顶端的人并不只是个人收入高，他们常通过学校、俱乐部、董事会、政策机构、投资机构和社会纽带形成信息与机会网络。书中并不把这解释成简单阴谋，而是强调社会结构会让某些群体更容易共享信息、形成共识并影响重要决策。
成长启发：对普通个体来说，这个视角提醒我们：机会往往不仅来自“我足够好”，也来自谁知道机会、谁愿意推荐、谁能解释规则。缺少网络并不说明你能力差，只说明你需要把“建立社会资本”当作真实任务。
练习提示：每月维护三类弱连接：一个行业信息源、一个可请教的前辈、一个能互相支持的同伴。关系不是攀附，而是稳定、互惠、可信的连接。看见网络的力量，可以减少孤军奋战式自责。
App端使用：可用于职业成长、人脉焦虑和自我价值感模块。它让用户把建立连接看作技能，而非讨好。建议从低压力连接开始：请教一个问题、分享一条有用信息、参加一次同业活动、维护一次旧关系。长期看，稳定可信比短期套近乎更能转化为机会。
适用边界：建立网络应避免功利操控。App可强调互惠、透明、守信和长期贡献，帮助用户在尊重他人自主性的基础上扩展机会。', '["资源网络", "社会资本", "权力", "机会", "职业成长", "信息差"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 472, now()),
(100473, '贫困不是人格缺陷：环境压力会塑造选择', '核心理解：书中梳理多种贫困理论，特别批评把贫困简单归咎于懒惰、低自控或道德失败的看法。贫困环境论提醒我们，许多看似“短视”的选择，是人在不稳定工作、住房、治安、家庭支持和福利不足中形成的现实适应；结构论进一步强调政治经济力量会制造并维持贫困。
心理启发：当一个人长期处于危机中，延迟满足未必带来回报，计划未来也会变得困难。此时最需要的不是训诫，而是降低危机密度：稳定住所、食物、医疗、照护、收入和可预期的日程。
关系启发：家庭里若有人反复借钱、失业或无法规划，先区分“能力问题、资源问题、创伤问题、环境问题”。道德审判通常只会加深羞耻；更有效的是共同设立小边界、小支持和可验证的下一步。
App端使用：适合低谷期、债务压力、求职挫败和家庭反复冲突。系统可引导用户先做“危机降噪”：今天先保障睡眠、食物、账单优先级、必要求助和安全边界。只有当生活稍微稳定，反思、规划和习惯改变才更可能真正发生。
适用边界：理解贫困压力不等于取消边界。亲友提供支持时也应设置金额、期限和责任分工，以免救助关系变成新的消耗。', '["贫困", "环境压力", "结构因素", "羞耻", "自我同情", "行为理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 473, now()),
(100474, '家庭压力的交叉叠加：阶级、性别和族群位置会一起作用', '核心理解：家庭压力往往不是单一来源。第10章提醒我们，许多服务家庭、照顾亲属、维系亲友网络的情感工作和亲情工作长期不被当作生产性工作，却深刻影响女性的财富和地位。第11章进一步显示，族群、性别、阶级、家庭结构和福利制度会叠加影响收入与教育机会。
关系启发：伴侣冲突中常见一句话是“你怎么什么都做不好”。但如果一个人同时承担赚钱、育儿、老人照护、亲戚协调、情绪安抚和身份歧视压力，问题就不只是态度。看见交叉压力，可以把攻击改成盘点：哪些劳动被看见了，哪些责任可以重分配，哪些外部支持可以引入。
练习提示：做一张家庭劳动清单，包含有偿劳动、家务、照护、情绪安抚、亲属联络、风险管理。先让隐形劳动可见，再谈公平。
App端使用：可在伴侣分工、女性压力、单亲家庭和照护者疲惫主题中使用。用户可被邀请区分三种劳动：赚钱的劳动、维持家庭运转的劳动、稳定关系气氛的劳动。很多冲突降温的第一步，不是讲道理，而是让长期被默认的劳动获得命名和感谢。
适用边界：看见交叉压力不是为了比较谁更苦，而是为了找到更公平的分工和更准确的支持，让家庭从互相指责转向共同承压。', '["家庭压力", "交叉压力", "性别分层", "族群不平等", "照护", "隐形劳动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 474, now()),
(100475, '冲突的合法化：人会把不公平解释成“本来如此”', '核心理解：合法化过程解释的是：为什么人们会接受自己得到更少资源、较低地位或不对等权威。书中从微观层面讨论行为、自我概念、信念体系如何被群体力量塑造，也讨论分配正义准则：人们常用贡献、需要、资格、传统或机会平等来判断谁该得到什么。
心理启发：合法化会进入自我评价。一个人可能把长期低回报解释成“我不配”，把不合理分工解释成“我天生就该忍”，把关系里的控制解释成“对方更懂”。这会削弱愤怒的边界功能，也会让冲突长期潜伏。
练习提示：遇到不公平感时，不急着判定谁坏，先问四个问题：分配规则是什么？它服务于需要、贡献、权力还是习惯？谁参与制定？有没有重新协商的空间？这样能把抱怨变成可谈判的规则。
App端使用：适合公平感受伤、职场委屈和家庭权力不对等场景。它可以帮助用户把“我是不是太敏感”改为“现在运行的是哪套规则”。若规则不可谈，重点是保护边界；若规则可谈，重点是把需要和贡献说清楚，并提出可执行的替代安排。
适用边界：识别合法化不等于鼓动对抗。很多场景可以通过澄清规则、重新约定和第三方协助解决；只有持续压迫时才需要更强边界。', '["合法化", "公平感", "自责", "认知框架", "边界", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 475, now()),
(100476, '比较视角：制度不同，压力和关系也会不同', '核心理解：同样是工业社会，不同制度会给普通人完全不同的安全感。书中比较美国、日本和德国：日本的年龄排序、群体关系和企业安排影响晋升与退休；德国的工会、监事会和工作委员会让工人在裁员、培训、工时、工资等事项上拥有更多协商位置；美国则更强调市场竞争和个人责任。
心理启发：如果只用一种社会的成功叙事解释所有人，就会把制度差异变成个人羞耻。工作安全、福利、医疗、工时和工人发言权不同，会直接影响家庭时间、亲密关系耐心、育儿压力和未来感。
练习提示：面对职业焦虑时，除了问“我够不够强”，也问“我的行业规则是什么、组织有没有协商渠道、我能否和同事共同提出可行方案”。制度视角不是抱怨，而是帮助你找到更现实的杠杆。
App端使用：可用于职场压力、加班争吵和安全感主题。它提醒用户把个人困境与组织规则相连：有没有申诉渠道、协商空间、同伴支持、福利政策和法律信息。亲密关系中也可借鉴“共同协商”思路，把伴侣视为同队，而不是彼此审判的管理者。
适用边界：制度比较不是照搬他国经验，而是训练用户看见规则可以被设计。这个视角能降低自责，并启发更现实的组织沟通。', '["比较视角", "制度安排", "工作安全", "福利", "家庭关系", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 476, now()),
(100477, '全球分层：个人选择常被国家与产业位置限定', '核心理解：世界体系视角提醒我们，贫穷国家与富裕国家的差距不是简单由个人勤奋解释，也不总能靠经济增长自动解决。书中指出，增长是否均衡、土地和收入分配、跨国公司投资方式、国家在全球产业链中的位置，都会决定普通人的工作选择和生活风险。
心理启发：当我们看见全球贫困、血汗工厂或移民劳动时，容易在同情、内疚、愤怒和无力之间摇摆。更有帮助的态度是现实感：承认很多人的选择空间很窄，同时避免用舒适位置上的道德想象替他们下判断。
练习提示：把全球议题转化为可承受行动：了解商品来源、支持更公平的劳动标准、在消费中做小比例调整、对移民和低薪劳动者保持尊重。结构很大，但个人仍可选择不把贫困解释成低价值。
App端使用：适合社会议题带来的无力感、消费内疚和移民/低薪劳动者理解模块。它鼓励用户在现实范围内行动：尊重服务者、减少刻板评价、支持可信公益或劳工信息、做可持续消费选择。重点不是用宏大问题压垮自己，而是练习有边界的责任感。
适用边界：全球视角容易带来宏大无力感，因此条目应始终落回可做的小选择和尊重他人的态度，避免把用户推向愤怒或道德疲劳。', '["全球化", "世界体系", "贫困", "产业链", "现实感", "消费伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 477, now()),
(100478, '成人自我不是冷静人设，而是现场数据处理', '伯恩的“成人自我”不是年龄标签，也不是没有情绪，而是把当下事实、可能性和后果重新放到桌面上的功能。父母自我负责内化规则与自动反应，儿童自我带来自发、创造和乐趣；沟通卡住时，目标不是消灭父母/儿童，而是让成人自我重新协调：现在发生了什么？证据是什么？我有哪些选择？', '["沟通分析", "成人自我", "父母自我", "儿童自我", "事实核对", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 478, now()),
(100479, '交错沟通：小事谈崩，是回应了对方没发出的那句话', '许多争吵不是因为问题本身，而是刺激和回应来自不同自我状态：一句成人式询问，被对方听成父母式指责，于是儿童自我反击。App 可引导用户分两层复盘：原话在问什么？我实际回应的是哪种旧感受或权威形象？修复方式是先承认被触发，再把话题拉回成人-成人的事实与请求。', '["沟通分析", "交错沟通", "成人状态", "触发反应", "关系修复", "事实请求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 479, now()),
(100480, '隐蔽沟通：表面在谈事，底层在发出角色邀请', '隐蔽沟通同时跑两个频道：社会层面像理性谈事，心理层面却在邀请对方证明、屈从、反抗、被照顾或被诱惑。识别游戏时不要只看句子字面，要问“这句话想让对方扮演什么角色”。当底层邀请决定结局时，表面合约再合理也会走向可预测冲突。', '["隐蔽沟通", "社会层面", "心理层面", "角色邀请", "人际游戏", "沟通分析"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 480, now()),
(100481, '六种获益：游戏不只让人吵赢，还帮人维持旧平衡', '人际游戏顽固，是因为它一次性提供多种收益：缓解内在紧张、避开焦虑或亲密、在伴侣间固定一句台词、在外部圈子获得谈资、获得强烈安抚，以及再次确认“我/你/世界就是这样”的存在立场。做关系复盘时，与其只问“谁错了”，不如问“这场戏替我们保住了什么”。', '["隐藏收益", "六种获益", "心理地位", "安抚", "亲密回避", "关系复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 481, now()),
(100482, '“要不是因为你”：抱怨有时是在外包自己的恐惧', '这个游戏里，限制者表面上是压迫者，抱怨者表面上是受害者；但限制也可能替抱怨者挡住自己害怕面对的场景。真正的退出不是继续辩谁阻碍谁，而是把“都是你不让我”改成“如果没人拦我，我其实怕什么”。对方若给出许可，隐藏恐惧会浮出来，游戏也失去燃料。', '["要不是因为你", "IWFY", "恐惧回避", "婚姻互动", "受害者位置", "退出游戏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 482, now()),
(100483, '“看你都让我做了什么”：把过激反应包装成被迫', '当一个人把摔东西、失误、糟糕决策归咎于“你打扰我/你让我这样”，他可能正在用别人的靠近来保护自己的孤立，或把责任推给代做决定的人。App 可提示：对方确实打断了你，但反应仍属于你；下一步不是追责，而是明确空间、权限和谁来承担决定。', '["看你都让我做了什么", "SWYMD", "责任边界", "孤立防御", "婚姻游戏", "职场沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 483, now()),
(100484, '“可逮着你了”：用小错误兑换正当愤怒', '有些人会长时间等待他人犯错，一旦抓到细节，就把局部失误扩大成对整个人的审判。表面是维权或讲原则，底层收益是获得“我有理由发怒”的许可。应对这类游戏，要把规则、费用、边界和例外提前写清；真有误差时只处理误差，不进入人格清算。', '["可逮着你了", "NIGYSOB", "正当愤怒", "人格审判", "契约边界", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 484, now()),
(100485, '“踢我吧”：不断招来惩罚，以证明命运总会如此', '“踢我吧”不是单纯倒霉，而是用挑衅、越界或自我破坏把别人推到不得不拒绝、驱逐或惩罚的位置，然后再说“为什么总是我”。识别点是结局反复相似：被赶走、被抛弃、被解雇。退出时要少接“踢人”的角色，改用清晰后果、有限帮助和可执行边界。', '["踢我吧", "Kick Me", "自我破坏", "惩罚循环", "边界", "为什么总是我"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 485, now()),
(100486, '“你为什么不——是的，但是”：求建议有时是在赢得无解', '当用户不断索要建议又逐条否定时，核心未必是找方法，而是证明“没有任何办法能帮我”。这种游戏用理性讨论填满无结构时间，也避免屈从和暴露无助。回应时不要急着提供第十个方案，可转向：“你已经试过/否定了哪些？如果暂时没有方案，你想让我陪你确认什么？”', '["你为什么不", "是的但是", "YDYB", "建议拒绝", "助人边界", "无解证明"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 486, now()),
(100487, '“我只是想帮你”：助人若带隐蔽动机会让对方必须失败', '真正的帮助会公开说明能力、边界、费用和合作方式；“我只是想帮你”的游戏则需要对方不领情，以证明“人都忘恩负义”。助人者越急着给建议、越不能承受对方没照做，越容易把对方固定成失败者。App 在助人场景中应提醒：先问对方要什么帮助，避免用建议换控制感。', '["我只是想帮你", "ITHY", "助人边界", "控制感", "来访者自主", "职业助人"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 487, now()),
(100488, '关系脚本：重复游戏会把偶发冲突排练成命运', '书中把常玩游戏放进“人生脚本”框架：孩子不仅学会礼貌、程序和消遣，也从家庭情感动力中学会怎样获得关注、怎样失败、怎样证明世界。一个人最熟悉的游戏，会影响他如何使用机会，并把婚姻、事业甚至结局推向熟悉方向。识别脚本的入口，是追问“这场戏最早像谁教会我的？”', '["关系脚本", "人生脚本", "家庭动力", "儿童原型", "重复冲突", "命运感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 488, now()),
(100489, '自主的三件事：看见此刻、自由选择、无游戏地坦率', '超越游戏不是永远理智，而是恢复三种能力：觉察让人回到此时此地，不只按旧教条看世界；自发性让人能选择表达父母、成人或儿童自我的感受；亲密则是没有隐藏交易的坦率接触。关系修复可据此设计三问：我现在看见了什么？我真正想表达什么？我能否不测试、不讽刺地说出来？', '["自主性", "觉察", "自发性", "亲密", "退出游戏", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 489, now()),
(100490, 'READ 四步：先把线索变成问题，再沟通核对', '线索假设：非语言观察不是“瞬间看穿”，而是把看见的表情、姿态、距离、声音和场景整理成可检验的问题。可以按 READ 四步使用：R 先像孩子一样审视事实，记录眉眼、手脚、语调、空间与时机；E 再看整体组合，哪些线索比其他线索更重要；A 回到基线、文化和自己的偏见，分析是否有误读；D 最后决定是记下、放慢、退出，还是开口询问。
核对沟通：把结论写成低确定性句子，例如“我注意到说到这里时，你声音变小、身体往后退，我不确定是累了、需要时间，还是这个话题有压力。我们要不要暂停一下，或换个方式谈？”这样既使用线索，也把解释权留给对方。', '["READ", "非语言线索", "核对沟通", "避免读心", "情境判断", "观察伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 490, now()),
(100491, '整体心情三维：能量、方向、焦点要一起看', '线索假设：一个动作本身很少足够，真正有用的是全身状态的组合。可以先问三件事：这个人整体能量是高还是低？能量有没有指向明确对象，还是分散漂移？焦点是在外部互动上，还是退回内在思绪里？高能量、方向集中、焦点向外，可能提示愤怒、兴奋或强烈推动；低能量、方向分散、焦点向内，可能提示困惑、疲惫或被某个念头困住。
核对沟通：不要说“你就是生气/心虚”，可以说“我感觉你现在整个人很用力，注意力好像都集中在这件事上。我理解成你很在意它，对吗？还是我误读了？”先核对情绪强度和关注点，再谈具体内容。', '["整体观察", "心情系统", "能量方向焦点", "情绪线索", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 491, now()),
(100492, '眉毛和前额：确认需求不等于撒谎证据', '线索假设：眉毛、前额常在认出别人、强调意思、寻求理解或请求认可时快速变化。挑眉可能是在说“我懂了”“你懂吗”，也可能是熟人相认的瞬间反应；缺少挑眉也未必是冷漠，可能是没认出、疲劳、文化习惯或刻意控制。把眉毛变化当作“对方可能在确认关系或确认理解”的线索，比把它当成心虚证据更稳妥。
核对沟通：适合用轻量确认句承接，例如“我看到你刚才好像在确认我有没有听懂。我的理解是……对吗？”或“我们是不是以前见过？我有点不确定。”这样让表情线索转成互相校准，而不是审问。', '["面部表情", "眉毛线索", "确认需求", "关系识别", "避免读心", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 492, now()),
(100493, '声音基线：语调变化提示压力，含义仍需确认', '线索假设：声音也是非语言信息。叹气、停顿、填补空白的口头声音、音调变尖、节奏加快或变慢，都可能提示压力、困惑、厌恶、悲伤、怀疑或努力维持礼貌。但声音变化只有在知道对方平时怎么说话时才更有价值；有人平常就语速快、声调高，也有人在低压力聊天里就常叹气。
核对沟通：先建立低压力基线，再谈敏感话题。可说“我不确定是不是听错了，刚才谈到这个请求时，你声音突然紧了一点。这个话题对你有压力吗？需要我说慢一点，还是你想先整理一下？”把语调当作照顾节奏的提醒，而不是“你说谎”的证据。', '["语调", "声音基线", "口头声音", "压力线索", "沟通节奏", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 493, now()),
(100494, '调适姿势：身体可能在释放压力，先给缓冲', '线索假设：搓手、揉脖子、抖腿、抓挠、打理自己、撕手皮、反复摸物品等，可能是调适姿势，也就是身体在转移能量、安抚压力或处理无聊。它们不自动等于欺骗、抗拒或不尊重；同一个动作也可能只是习惯、环境不适、身体瘙痒或等待太久。
核对沟通：看到调适姿势时，优先降低压力而不是提高质问强度。可以说“我注意到这个话题好像让人有点紧，我们要不要喝口水、放慢一点，或者先谈你最在意的部分？”如果对方说只是习惯，就尊重其解释；只有在同类场景反复出现时，再把它作为压力模式继续观察。', '["调适姿势", "压力释放", "身体安抚", "姿态观察", "低压力沟通", "情境核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 494, now()),
(100495, '阻隔与距离：先处理安全感，再处理观点', '线索假设：交叉手臂、半转身体、站到桌后、把包或文件放在中间、降低视线、后退、寻找出口，都可能是在建立安全距离。它们不一定表示讨厌你，也可能是空间太近、权力差距大、话题太私密、现场有旁人，或对方需要一点控制感。
核对沟通：不要逼近或追问“你为什么防备我”。先撤一点压力：“我们这个距离会不会太近？要不要坐远一点、把门打开，或晚点再谈？”当对方的身体不再忙着保护自己，语言沟通才更可能进入事实和需求。若你自己出现阻隔姿势，也可直接说明：“我抱臂是因为有点紧张，不是要拒绝你。”', '["阻隔姿势", "个人空间", "距离线索", "安全感", "冲突降温", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 495, now()),
(100496, '文化与微文化：先问这套关系规则是什么', '线索假设：同一个手势、距离、致意、眼神或拥抱，在不同文化、职业、家庭、伴侣关系中可能含义不同。长期关系本身也会形成微文化：伴侣间一个扬眉、朋友间一个玩笑、团队里一个沉默，可能有他们内部的历史和禁忌。外人若只按自己的规则翻译，很容易把礼貌看成疏离，或把习惯看成挑衅。
核对沟通：遇到不确定的动作，可直接把文化差异放到台面：“我可能按自己的习惯理解了。你们这里这样做通常代表什么？”在亲密关系里可问：“以前你这个表情我会理解成开玩笑，但今天我不确定。它现在代表什么？”先校准规则，再解释情绪。', '["文化差异", "微文化", "关系规则", "情境核对", "避免误读", "跨文化沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 496, now()),
(100497, '投射过滤：服饰、文身和步态先标记为未知', '线索假设：观察者很容易把自己的故事贴到别人身上。文身、衣着、妆容、步态、性别、年龄、职业或场所，都可能触发投射，让人以为“已经看清这个人”。更稳妥的做法是把第一反应降级为假设：我看见了什么事实？我自动补了什么剧情？还有哪些无害解释？
核对沟通：如果线索影响了互动，先承认不确定：“我可能有点按外表猜测你了，想确认一下……”或“我刚才看到你沉默，就脑补成不赞同；其实你当时是在想什么？”把投射说成自己的解释，而不是对方的问题，能减少羞辱和防御。', '["投射", "偏见校准", "服饰线索", "身体装饰", "避免读心", "事实解释分离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 497, now()),
(100498, '公开冲突降温：保全面子比当场赢更重要', '线索假设：公开场合的争论会放大羞辱、地位威胁和旁观者压力。对方下巴抬高、声音变硬、动作更大、寻求同盟或盯住观众，可能不是单纯不讲理，而是在维护面子和群体位置。此时继续公开压迫，常会把分歧推向战斗姿态。
核对沟通：能私下谈就私下谈；必须当场回应时，先承认共同目标，再把分歧从人格降到事实：“这个点我们可能有不同资料，我不想让你在公开场合难堪。我们先确认目标，细节会后一起核对，可以吗？”冲突线索的用途是降温和保留退路，而不是当众拆穿。', '["冲突降温", "公开争论", "面子需求", "职场沟通", "群体压力", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 498, now()),
(100499, '高压请求：相似感和情绪诉求要先放慢', '线索假设：推销、募款、传教、亲友求助或恋爱追求都可能使用高压策略：先制造“我们是一边的”相似感，再把话题推到难以拒绝的道德或情感位置。你若感觉身体被卷入、来不及思考、很难说不，这本身就是压力线索；对方热情不必然是恶意，但需要核对真实需要和你的边界。
核对沟通：先问无压力问题，观察对方平常怎么说话、看哪里、如何回应，再决定。可以说“我愿意了解，但我需要慢一点。你具体希望我做什么？今天必须决定吗？如果我不答应，会有什么影响？”把模糊情绪诉求拆成事实、时间、选择和可拒绝请求。', '["高压沟通", "边界", "说不", "请求核对", "压力线索", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 499, now()),
(100500, '关系观察：长期关心比一次拥抱更有说明力', '线索假设：朋友还是泛泛之交，不能只看一次拥抱、一次热情或一次冷淡。有人把拥抱当亲近，有人觉得拥抱很怪；不同成长经历和微文化会让同一动作有不同意义。更值得观察的是长期稳定性：对方是否关心你过得好不好，是否记得重要处境，久别重逢后对待你的方式是否明显变化。
核对沟通：把关系判断变成可谈的期待：“我发现我们见面时很热络，但平时很少真正聊近况。我有点不确定我们对这段关系的期待是否一致。你怎么看？”这样既不因一个非语言动作定性关系，也给对方说明亲近方式的机会。', '["关系观察", "朋友关系", "微文化", "长期模式", "亲密距离", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 500, now()),
(100501, '亲密关系线索：用担忧核对期待，不用侦查定罪', '线索假设：承诺关系中的争吵常来自未说清的期待和权利。伴侣在敏感话题上眼神、声调、节奏、姿态或阻隔姿势改变，可能提示压力、隐瞒、羞耻、害怕冲突，也可能只是旧伤被触发。越亲近，越容易把过去经验投射到当下；因此线索只适合提醒你“这里需要温柔核对”，不适合变成侦查游戏。
核对沟通：用发自内心的担忧表达影响：“当我问到这件事时，我感觉我们都紧了。我不是想审你，而是这会影响我在关系里的安全感。你愿意告诉我发生了什么，或者我们先把彼此期待讲清楚吗？”目标是弄清期待、修复信任和决定下一步，而不是证明自己看穿了对方。', '["亲密关系", "期待核对", "信任修复", "语调姿态", "避免侦查", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 501, now()),
(100502, '情绪不只在心里，也在关系场里', '当一个人说“我很难受”时，不要只问“我怎么了”，也要问：这个情绪指向谁、哪段关系、哪个群体位置或哪条规则？情绪常在社会结构中被点燃，也会反过来改变人对关系和环境的选择。', '["情绪社会学", "社会结构", "关系场", "情绪觉察", "归因"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 502, now()),
(100503, '被认可，才更容易对群体有归属感', '一个人对家庭、团队或组织的承诺，往往不是靠道理说服出来的，而是来自一次次“我在这里被看见、被奖励、能做好自己”的正性体验。反复被肯定，情绪会从具体关系扩展到对群体和制度的信任。', '["归属感", "社会承诺", "正性情感", "组织关系", "身份确认"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 503, now()),
(100504, '身份被否定时，情绪会比事情本身更大', '有些冲突看似只是一次批评、拒绝或误解，实际碰到的是“我是谁”。越接近核心自我或重要身份，没被承认时情绪越强；这时先处理身份受伤，再讨论事情对错，关系更容易降温。', '["身份评价", "自我证明", "核心自我", "冲突降温", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 504, now()),
(100505, '羞愧是社会警报，不是整个人的判决', '羞愧常在“我没有达到规则、角色或期待”时出现，它能提醒人修正行为、修复关系。但如果把羞愧理解成“我整个人都不行”，痛苦会过强，反而更容易逃避、压抑或攻击。', '["羞愧", "羞耻", "社会规范", "自我价值", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 505, now()),
(100506, '愤怒有时是被压住的羞愧在找出口', '有些愤怒不是事件刚发生时的第一情绪，而是长期羞愧、失败感或不公平感被压下后的出口。若只处理“别发火”，会漏掉底层的“我没被尊重、没被承认、没被公平对待”。', '["愤怒", "羞愧", "防御机制", "外部归因", "不公平感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 506, now()),
(100507, '亲密需要可预测的节奏和尊重', '亲密不是一直热烈，而是能预测对方、跟上彼此节奏，并感到对方忠诚、诚实、尊重自己。信任一旦缺位，恐惧和愤怒会升高，互动会变得躲闪、公式化甚至虚伪。', '["亲密关系", "信任", "节奏同步", "安全感", "关系互动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 507, now()),
(100508, '情绪劳动：被规则要求管理感受', '情绪劳动不是简单“忍一忍”，而是在角色、地位或关系规则要求下，努力表现出该有的感受、藏起不该有的感受。长期隐藏真实情绪会积累紧张，最终可能以爆发、羞愧或内疚回到关系里。', '["情绪劳动", "感受规则", "表达规则", "角色压力", "情绪压抑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 508, now()),
(100509, '规范和权力会分配“谁可以怎样感觉”', '每个环境都在暗中规定：谁该自豪、谁该难过、谁能生气、谁不能挑战。当地位和权力不平等被包装成“应该如此”，低位者的悲伤、羞愧和愤怒就不只是个人情绪，也是位置带来的情绪负担。', '["规范与权力", "地位", "分层", "情绪规则", "社会评价"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 509, now()),
(100510, '关系交换不只算资源，也在交换情绪', '关系里交换的不只是钱、时间和帮助，也有被感谢、被公平对待、被尊重的情绪回报。一个人觉得“投入大于回报”时，愤怒和疏离会增加；当正性情绪被相对平等地分配，关系更容易形成团结。', '["情绪交换", "公平感", "互惠", "关系承诺", "资源分配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 510, now()),
(100511, '修复仪式让关系从羞愧回到连接', '关系破裂后，承认尴尬或羞愧、道歉、重新定义情境，并不是客套，而是在重建互动规则。能承认羞愧时，关系有机会回到正性情绪；若继续压抑，羞愧更容易变成愤怒循环。', '["修复仪式", "关系修复", "羞愧", "愤怒循环", "互动规则"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 511, now()),
(100512, '角色转换：先借一个位置理解关系，不替对方下结论', '【核心观点】心理剧中的角色转换，不是让人“猜中”对方，而是暂时换一个观察位置，看见关系里还有哪些被自己忽略的感受、限制和需要。它的价值在于扩大角色目录：一个人不只被固定在受伤、指责、讨好或防御的位置上，也能试着理解另一端的经验。
【App 转化】适合做成低强度反思提示：如果我站到对方的位置，可能会看见什么？如果我再回到自己这里，我想保留什么边界、改变什么回应？
【边界提醒】不要要求用户代入强刺激人物或重演创伤场景；更适合用于日常误会、亲密关系沟通、团队协作等可承载情境。', '["心理剧", "角色转换", "换位理解", "关系视角", "边界感", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 512, now()),
(100513, '替身：把说不出口的内在声音变成可核对的句子', '【核心观点】替身的重点不是替用户解释人生，而是把可能被压住、说不清或只停留在身体里的内容，先试探性地翻译成一句话，再交还给本人确认、修改或拒绝。好的替身像温和的“可能性草稿”，不是权威判决。
【App 转化】可设计为“我心里可能有一部分在说……”的自我核对句，帮助用户从混乱情绪中分辨多个声音：想靠近的一部分、想逃开的一部分、想保护边界的一部分。
【边界提醒】替身提示应保持低确定性，避免给用户灌输结论；尤其不要把复杂关系直接解释成单一创伤或病理原因。', '["心理剧", "替身", "内在声音", "情绪命名", "自我核对", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 513, now()),
(100514, '镜映：从旁边看见自己的姿态、语气和关系信号', '【核心观点】镜映让人暂时离开“我正在经历”的位置，改用旁观角度看见自己的表情、姿态、语气、距离和重复模式。它不是羞辱性的曝光，而是把自动反应变成可观察、可调整的材料。
【App 转化】可转成轻量问题：如果有一位友善观察者看见刚才的我，他会注意到什么？我的身体在说“靠近”“防御”“求助”还是“不要碰我”？
【边界提醒】镜映不应制造审判感。App 文案要强调“观察不是定罪”，并邀请用户核对而不是贴标签。', '["心理剧", "镜映", "身体觉察", "非语言沟通", "自我观察", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 514, now()),
(100515, '此时此地：把探索落在现在能承载的一小步', '【核心观点】心理剧重视此时此地，因为改变不是只在解释过去，而是在当下看见身体、关系和选择如何发生。过去、未来和想象都可以被带入，但最后需要回到现在：我此刻在哪里？我能做一个什么小回应？
【App 转化】适合用于对话收束：现在我身体最明显的感觉是什么？我和这件事之间需要多大距离？接下来一天里，一个低风险、可执行的小行动是什么？
【边界提醒】不要把用户一路带向深层回忆却不收束；每次内容都应有回到现实、回到身体、回到当下生活的落点。', '["心理剧", "此时此地", "当下觉察", "现实落地", "小行动", "情绪安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 515, now()),
(100516, '行动化表达：让内在经验可见，但在 App 里要轻量化', '【核心观点】心理剧把许多说不清的经验转成行动语言：站远一点、转向、放一个物件、说一句未说完的话，都会让内在关系变得可见。行动化表达的价值，是让人从“脑中反复想”进入“我看见它如何发生”。
【App 转化】更适合做成低刺激练习：用一个词、一个姿势、一个安全物件或一张纸的位置，标记“我”和“这件事”的距离。重点是观察，不是强迫情绪爆发。
【边界提醒】不要设计高强度重演、喊叫、对抗或身体接触任务；线上产品应优先采用象征、书写、想象距离等温和形式。', '["心理剧", "行动化表达", "行动外化", "象征表达", "身心连接", "练习边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 516, now()),
(100517, '行动领悟：不是想明白才改变，而是在小体验后再理解', '【核心观点】行动领悟强调“从做中学”：当一个人亲身体验不同角色、距离或回应方式，理解会带有身体感和关系感，比单纯听道理更容易转化为生活中的选择。领悟不是终点，能否回到现实中试一小步，才是关键。
【App 转化】适合在练习后追加三问：刚才我看见了什么？这和我平常的模式有什么不同？我愿意在真实生活中尝试哪一个很小、很安全的回应？
【边界提醒】不要把体验包装成顿悟承诺；App 只提供反思与微行动提示，复杂关系仍需要现实沟通与持续练习。', '["心理剧", "行动领悟", "体验式学习", "从做中学", "微行动", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 517, now()),
(100518, '共创与关系修复：心理剧不是独白，而是关系中的新回应', '【核心观点】心理剧的关系观强调共创：主角、带领者、团体和辅助角色共同生成一个可探索的场。关系修复也不是只把话说漂亮，而是在安全互动中看见自己如何影响他人、如何被他人回应，并把新经验带回生活。
【App 转化】可用于设计关系类知识：冲突不是单人故障，而是互动模式；修复可以从承认影响、听见对方位置、选择新的回应动作开始。
【边界提醒】不要让用户在 App 内单方面“完成和解”。真正的关系修复需要对方同意、现实边界和可持续行动。', '["心理剧", "共创", "会心", "关系修复", "互动模式", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 518, now()),
(100519, '情绪安全：接纳、支持和面质要同时被看见', '【核心观点】心理剧可以触及强情绪，但安全不是靠推动，而是靠接纳、支持、清楚节奏和非评断氛围。面质只有在足够安全时才有意义；没有支持的面质容易变成压力，没有面质的支持也可能停在安慰。
【App 转化】后台知识可提醒：所有情绪类内容先给容纳，再给观察，最后才给选择。用户可以被邀请命名感受、确认需要、暂停或求助，而不是被催促“释放出来”。
【边界提醒】不要把哭、崩溃、宣泄当成进步指标；App 端应优先提供稳定化、节奏调节和退出选项。', '["心理剧", "情绪安全", "接纳", "支持与面质", "节奏调节", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 519, now()),
(100520, '练习边界：保密、同意、身体距离和伦理先于技巧', '【核心观点】心理剧不是“有技巧就能做”，而是先有场域边界：空间是否私密、规则是否清楚、身体距离是否被尊重、参与者是否知道可以拒绝或暂停。边界越清楚，行动表达才越可能安全。
【App 转化】任何心理剧元素进入产品，都应改写为低风险、可退出、无需身体接触的版本；涉及他人关系时，强调现实同意与隐私，不鼓励录音、曝光或逼迫对话。
【边界提醒】线上知识库不应提供治疗型导剧脚本，只保留心理教育、观察问题和温和自助提示。', '["心理剧", "练习边界", "保密", "身体距离", "同意", "伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 520, now()),
(100521, '结束与回到自己：每次探索都要有收束和整合', '【核心观点】心理剧不是把人带进角色就结束，而是需要从角色、场景和情绪中回到自己。好的结束会帮助人确认：我现在是我，不是刚才那个角色；我回到现实；我知道接下来怎么照顾自己。
【App 转化】所有练习都应有收束段：看见周围三样东西，感受脚踩地面，写下一个此刻能做的普通行动，或给自己一句回到现实的话。
【边界提醒】不要在用户高情绪处突然结束内容，也不要把复杂体验留给用户独自消化；收束、整合、回到日常是必要组成部分。', '["心理剧", "结束", "整合", "回到自己", "落地练习", "情绪安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 521, now()),
(100522, '暖身：轻度、游戏性和信任感是进入探索的缓冲区', '【核心观点】暖身不是无关紧要的开场游戏，而是让身体、注意力和关系慢慢进入状态。对很多人来说，刚开始的不愿意、不确定或想退后，不一定是问题，而可能是安全系统在观察环境。
【App 转化】心理剧式内容前可以先给低门槛过渡：选择一个今天的情绪词、给当前能量打分、决定本次只做观察还是做一点表达。让用户有选择权，本身就是安全感的一部分。
【边界提醒】不要用“突破”“挑战”“立刻进入深处”作为引导语；温和、可停、可选择，比强行打开更适合 App 场景。', '["心理剧", "暖身", "信任感", "游戏性", "选择权", "低刺激练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 522, now()),
(100523, '象征与物件：用距离感承载内容，而不是直接冲进情绪', '【核心观点】心理剧不一定要直接说出最痛的部分，也可以让物件、椅子、纸张或象征角色先承载一部分内容。象征的好处是保留距离：用户既能看见内在关系，又不必一次性完全暴露自己。
【App 转化】可设计“把这件事放在纸上/屏幕外一个位置”的提示，让用户调节距离：太近就移远一点，太远就只观察轮廓。目标是建立可承载的关系，而不是制造强烈情绪。
【边界提醒】避免要求用户破坏真实物品、进行仪式化告别或重演高压情境；App 内只使用温和、可撤回、无损害的象征动作。', '["心理剧", "象征表达", "物件外化", "距离感", "情绪安全", "练习边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 523, now()),
(100524, '实用乐观主义八支柱：把高能量状态拆成可练习的系统', '高能量状态不是持续兴奋，也不是用积极想法覆盖现实，而是把心态、技能和行动组合成可练习的系统。App 端可把“我没状态”拆成八个可调节入口：人生目标、处理情绪、解决问题、自我价值感、自我效能感、活在当下、人际关系、健康习惯。每次只问“现在最缺哪一根支柱”，再给一个小练习，而不是直接鼓励用户硬撑。', '["高能量状态", "实用乐观主义", "状态管理", "行动框架"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 524, now()),
(100525, '高能量状态自检：先定位哪根支柱最需要补强', '状态评估适合做成低压力“生活自拍照”，目的不是诊断，而是发现精力应该集中在哪里。书中的 40 项自检分别映射八支柱：1-5 看目标，6-10 看情绪，11-15 看问题解决，16-20 看自我价值，21-25 看自我效能，26-30 看当下注意力，31-35 看关系，36-40 看健康习惯。App 可用“是/否/最近不确定”快速筛出当前最该补强的 1-2 个领域。', '["状态自检", "能量评估", "八支柱", "App问诊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 525, now()),
(100526, '目标加快乐：用 AIM 把愿景变成行动路线', '目标感需要和快乐、心流一起设计；只追求有意义但长期牺牲快乐，容易耗竭。AIM 路线可用于目标澄清：承认自己如何走到现在，识别哪些事有效、哪些带来意义和快乐，再采取小步前进。App 可引导用户写下“我想去哪里、为什么值得、这周 15 分钟能做什么”，并提醒目标可以坚定，路径要允许调整。', '["人生目标", "目标行动", "心流", "行动闭环"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 526, now()),
(100527, '情绪四步法：命名、认领、驯服、重构', '情绪处理不是压下去，也不是立刻发泄，而是先给情绪留出可观察空间。可执行流程是：命名具体情绪，认领触发情境与身体反应，驯服情绪（用同情、矫正、平静、连接的应对方式，或呼吸、身体扫描、担忧日记），最后重构视角，寻找更真实、更有帮助的解释。适合 App 在用户焦虑、愤怒、委屈时提供分步卡片。', '["情绪处理", "情绪调节", "压力恢复", "认知重构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 527, now()),
(100528, '压力恢复的 5R：先评估参与方式，再补给和求助', '遇到高情绪张力的问题时，不必默认硬扛或逃避。5R 可作为压力恢复与问题解决流程：重新评估是否参与、如何参与；给身体和情感储备加油；向可靠对象寻求信息或情绪支持；提醒自己已有能力和过往经验；在无法改变事实时重新评价与它的关系。必要时可短暂转移注意力，但不能把转移当成长期逃避。', '["问题解决", "5R策略", "恢复力", "压力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 528, now()),
(100529, '身体信号也是状态数据：把症状纳入压力恢复，而非只靠意志硬撑', '身体状态可以反映心理负荷：睡眠不足、紧张性头痛、胃部不适、心跳加速、下巴紧绷、腿软或持续疲惫，都可能提示压力已超过恢复能力。App 不应把这些当作“意志力差”，而应引导用户记录睡眠、饮食、情绪、工作负荷和身体感受的关联；先排除必要的健康问题，再用休息、情绪处理、求助和任务降载恢复基线。', '["身体状态", "压力信号", "恢复基线", "身心连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 529, now()),
(100530, '稳定自我价值：GRACE 不是自夸，而是现实而友善地校准自己', '稳定自我价值不是夸大自己，而是对自己保持内在、准确、友善且鼓励成长的认识。GRACE 可做成自我校准练习：感恩美好，承认现实，接受不完美，自我关怀，共情他人。它帮助用户把“我做错了”与“我很糟糕”分开，既能承担责任，也能休息、求助、继续尝试。', '["自我价值感", "GRACE", "自我关怀", "恢复力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 530, now()),
(100531, '自我效能循环：小经验、正向设想和反馈让“我能做”变可靠', '自我效能感来自可重复的小成功，而不是空喊自信。做法是先设计低风险、小步的亲身经验，再用正向设想、导师反馈和进展记录强化“我能学会”。当用户拖延或焦虑时，App 可提示“行动先于动机”：先做 5-15 分钟可完成版本，再记录完成后的情绪、能力证据和下一步。', '["自我效能感", "小步行动", "正向反馈", "行为激活"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 531, now()),
(100532, '注意力主权：识别过去、未来和比较三种认知陷阱', '时间和注意力是有限资源，需要被保护。注意力被劫持时，常落入三类陷阱：困于过去的反刍和后悔，困于未来的灾难化和不确定焦虑，困于比较的自卑、追赶和错失恐惧。App 可先标记用户属于哪一类，再给当下觉知、品味练习、社交媒体边界或纸笔记录，把注意力从自动滚动中拿回来。', '["注意力", "当下觉知", "反刍", "FOMO"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 532, now()),
(100533, '克服心理疲劳：休息要分身体、感官和社交情绪三类', '心理疲劳不一定靠睡一觉就解决，可能来自选择过载、睡眠不足、噪声、屏幕刺激或关系消耗。恢复时可分三类安排：身体休息（睡眠、小睡、伸展、按摩），精神/感官休息（关掉噪声、减少通知、绿洲时刻），社交情绪休息（独处和滋养性关系之间取得平衡）。App 可根据用户疲劳来源推荐对应休息，而不是笼统建议“早点睡”。', '["心理疲劳", "休息类型", "注意力恢复", "可持续行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 533, now()),
(100534, '从意图到自动化：让好习惯低门槛、坏习惯高门槛', '可持续行动依赖环境设计，而不是单靠意志力。习惯更容易坚持，通常因为它便利、有趣、可得、愉快。做法是明确意图，细化目标，制定活动计划，安排高能时间，从小事做起，设置问责与奖励；同时让不想要的行为更难接近、更少提示。遇到挫折时暂停、复盘触发因素、减少伤害，再恢复下一小步。', '["习惯养成", "自动化", "环境设计", "行动闭环"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 534, now()),
(100535, '心理健康 4M：把基础处方做成每周最低配', '4M 可作为 App 的基础能量处方：掌控（持续学习或精进一件事）、运动（让身体活动支持情绪和大脑）、有意义的接触（与人真实连接并贡献存在感）、正念（温和引导注意力）。每周最低配可以是：15 分钟学习、一次低强度运动、一次主动联系或共同活动、一次呼吸/冥想/正念停顿。重点是稳定重复，而不是一次做到完美。', '["心理健康4M", "健康习惯", "身体状态", "可持续行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 535, now()),
(100536, '生命周期不是闯关清单：每个阶段都在继续参与人生', '埃里克森的阶段观适合被理解为“发展中的关键课题”，而不是一次完成、永不回头的闯关表。信任、自主、主动、勤奋、身份、亲密等力量会在不同年龄以新的形式继续出现；每一阶段的积极力量也始终伴随相反感受。用于 App 回答时，可提醒用户：某个阶段的困难并不等于人格定型，而是当前生活正在重新激活某种发展任务；可从关系、身体、角色和社会支持一起寻找可调整的入口。', '["埃里克森", "发展阶段", "生命周期", "心理社会发展", "非诊断", "成长任务"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 536, now()),
(100537, '基本信任：安全感来自稳定可预见的关系品质', '婴儿期的信任不是被喂多少、被爱多少的简单总和，而是照料者能否稳定、敏锐、可预见地回应需要。孩子逐渐把照料者体验为“即使暂时不在眼前，也仍然可靠”的存在，同时也学会相信自己的身体和需求可以被承接。面向亲子或亲密关系的问答，可把“信任”解释为长期关系中的一致性：允许有挫折，但关系要有可理解的意义、可修复的节奏和足够稳定的回应。', '["基本信任", "安全感", "亲子关系", "照料回应", "关系品质", "希望"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 537, now()),
(100538, '自主感：边界的目的不是控制孩子，而是让孩子敢于自控', '自主阶段的核心不是“孩子想怎样就怎样”，也不是成人用羞辱换服从，而是在保持与放手之间建立可安心的外在控制。孩子需要在安全边界里练习选择、拒绝、坚持和放手，从自控与自尊中发展意志感。若成人的规则反复无常、过度羞辱，孩子更容易把探索体验成暴露、怀疑或丢脸。App 可以建议家长把规则说清楚、保持一致，并把错误当成练习自控的材料。', '["自主", "羞愧与怀疑", "边界", "自控", "亲子教育", "意志"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 538, now()),
(100539, '主动感：把“我想做”引向计划、责任和可承受的后果', '主动阶段的孩子开始更有能量，想靠近目标、提出计划、模仿大人、照顾更小的人。这个阶段需要的不是简单压下冲动，而是把“想做”转化为可执行、可负责、可合作的行动。过度禁止会让主动性和内疚感纠缠；缺少指引又会让孩子难以理解边界。适合 App 场景的表达是：给孩子小任务、可见角色和现实反馈，让他们在被允许尝试中学习责任，而不是只在犯错后被评价。', '["主动", "内疚", "责任感", "儿童发展", "角色模仿", "行动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 539, now()),
(100540, '勤奋感：孩子需要在工具世界里体验“我能学会”', '进入学校或类似学习环境后，孩子的发展重点从想象和游戏逐渐转向技能、工具、任务和同伴合作。勤奋感不是单纯“努力”，而是孩子能在真实任务中看到自己掌握了方法，并被所属文化承认为有能力的参与者。若家庭没有为学习做准备，或学校无法兑现早期成长的期待，孩子容易把困难理解成“我不行”。App 回答可强调：把任务拆小、让进步可见、减少比较羞辱，比空泛鼓励更能保护勤奋感。', '["勤奋", "自卑", "学习动力", "学校适应", "能力感", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 540, now()),
(100541, '身份发展：青春期是在身体、角色和未来之间寻找连续感', '青春期的“我是谁”不是单靠兴趣标签回答的，而是要把身体变化、早年形成的自我感、同伴评价、技能、价值和未来职业可能整合起来。身份感大于童年身份的相加，它需要内在连续感与他人眼中的一致性相互印证。青少年对偶像、群体、风格和恋爱对话的投入，常是在试着看清自己。App 端可避免把探索贴成叛逆，转而帮助用户辨认：哪些角色让我更像自己，哪些只是为了被接纳。', '["身份发展", "自我同一性", "青春期", "角色探索", "同伴关系", "价值澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 541, now()),
(100542, '青年之爱常在回答身份问题：我在你眼中是谁', '埃里克森把青年期的爱理解为身份澄清的重要场域：年轻人会把尚未稳定的自我意象投向对方，再从对方回应中看见和整理自己。因此，早期恋爱常常有大量谈话、确认、理想化和群体边界。App 回答亲密困惑时，可把一部分“反复确认关系”理解为身份探索，而不是急着判断成熟或幼稚；更有帮助的问题是：这段关系是否帮助双方更清楚地成为自己，还是只让彼此陷入排外、比较和自我丧失。', '["青年之爱", "身份澄清", "亲密关系", "青春期", "自我意象", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 542, now()),
(100543, '亲密不是吞没：清晰的自我更能承担承诺', '亲密阶段建立在相对清晰的身份感之上。一个人越能知道自己是谁，越可能与他人建立具体的依附、伙伴关系和承诺，并在必要的牺牲与妥协中不完全失去自己。相反，如果靠近总被体验成自我受损，人就可能用距离、防御或孤立保护自己。App 端可把亲密关系建议落在两个问题上：我能否在关系中保持自我连续感？我是否愿意为重要关系承担可协商的承诺？', '["亲密", "孤独", "承诺", "自我边界", "成年早期", "伴侣关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 543, now()),
(100544, '童年经验会进入成人关系，但不等于成人只能重复过去', '《童年与社会》反复把童年与成人生活连在一起：早期的信任、羞愧、主动、能力和身份经验，会在成年后的爱、忠诚、工作、权威和亲密中被重新激活。重要的是，这种影响不是命运判决，而是理解当下反应的线索。App 可用非诊断语言引导用户回看：某个关系触发点像不像早年熟悉的处境？现在的我是否可以用新的支持、解释和行动来回应，而不只是沿用旧的防御。', '["童年经验", "成人关系", "早年模式", "关系触发", "自我理解", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 544, now()),
(100545, '社会化：孩子不是被家庭单独塑造，而是在文化中学习成为人', '儿童训练并非只发生在家庭内部，也不是把成人规矩机械塞给孩子。人类漫长童年中的训练和教育，会把身体需要、情绪能量、家庭习惯、社会传统和文化理想组织起来，使孩子同时成为有机体、社会成员和独立个体。不同文化会用不同方式安排儿童训练，因此 App 在回答亲子问题时，可少用“唯一正确养法”，多问：这个家庭和文化期待孩子学会什么？这些期待是否仍能支持孩子的安全、能力和归属。', '["社会化", "儿童训练", "文化影响", "亲子关系", "家庭与社会", "成长环境"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 545, now()),
(100546, '亲子挫折需要意义：孩子承受的不是限制本身，而是无意义的中断', '埃里克森提醒，儿童并不是因为所有挫折而受伤；更关键的是挫折是否被放在可理解、可修复、与群体意义相连的框架里。父母不能只靠禁止和允许来带孩子，还需要说明事情的意义，让孩子知道规则如何服务于安全、合作和成长。当家庭或学校的要求突然、粗暴、缺少解释，孩子更容易体验到不连续和不归属。App 可建议成人先连接、再设限、再解释，帮助孩子把限制转化为可学习的经验。', '["亲子关系", "挫折意义", "规则解释", "安全感", "家庭教育", "连接与设限"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 546, now()),
(100547, '动力方向与语言顺序：先承认风险，再落到可做目标', '书中把动机分为“趋向想要的结果”和“远离不想要的后果”。用于 App 时，可以先帮用户识别自己是在逃离压力、失败、冲突，还是在靠近价值、成就、连接；二者都可用，但不要让“远离”变成长期焦虑。沟通或自我对话中，负面反馈可以先说清楚，最后必须落到具体、正向、可执行的句子，例如从“别再拖延”改成“今天 20:00 前完成第一段草稿”。', '["NLP", "动力方向", "语言模式", "目标设定", "自我激励", "行动设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 547, now()),
(100548, '价值观增压：先问“为什么重要”，再谈行动', '缺动力时，不必急着责备自己意志力差。可先问：这个目标对我为什么重要？它服务的是自由、连接、安全、创造、成长，还是别的价值？书中强调，目标、梦想和欲望常是实现价值观的工具；当目标与价值脱节，人容易进入自动驾驶。App 可以把“我想换工作/健身/修复关系”追问成“这会让我更接近什么价值”，再选择一个当天能做的小行动。', '["NLP", "价值观", "动机", "自我觉察", "目标澄清", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 548, now()),
(100549, '内在表征审计：把脑内画面和声音当作情绪线索', '同一件事在脑中呈现为大而近、明亮、带刺耳声音，和呈现为小而远、柔和、可观察，情绪强度会不同。App 可引导用户描述内在表征：画面大小、远近、颜色、清晰度，内在声音的音调、速度、来源，以及身体感受的位置和强度。随后只做温和实验：把画面调远一点、把声音放慢一点、加入更友善的语气。它不是改变事实，而是增加情绪调节的选择。', '["NLP", "表征系统", "次感元", "情绪调节", "内在声音", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 549, now()),
(100550, '完整目标：愿望要有证据、控制范围和生态影响', '一个可执行目标不只是“我想变好”。书中给出目标实现流程：使用积极词汇表达想要什么；确认行动主要在自己可控制范围内；定义看到、听到、感到哪些证据代表进展；限定何时、何地、与谁有关；检查目标对工作、家庭、朋友和身心节奏的影响。App 可把用户的模糊愿望转成一组问句，帮助其从“让别人不批评我”改写为“被批评时我能稳定倾听、筛选可用信息并回应”。', '["NLP", "目标设定", "生态检查", "证据", "行动计划", "自我效能"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 550, now()),
(100551, '角色—价值观矩阵：把人生方向落到具体身份场景', '当用户说“我不知道人生该怎么过”时，可先不急着寻找唯一使命，而是列出当前角色：自己的朋友、学习者、伴侣、父母、同事、领导者、公民等。再逐一问：在这个角色中，我多大程度体现了重要价值？有哪些证据？哪个角色最需要一个小目标？这样能把抽象自我评价转成具体场景里的行为选择。角色不是固定标签，而是可被练习、调整和重新命名的行动位置。', '["NLP", "角色", "价值观", "身份", "目标落地", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 551, now()),
(100552, '关系目标：把对方的收益放进自己的目标画面', '涉及他人的目标，不能只问“我想从关系里得到什么”。书中建议把关键人物放进目标图像，并检查自己的目标是否也给对方带来好处。App 可用于冲突、请求、合作场景：我想要什么？我能做什么？我如何知道关系目标达成？这个目标在什么背景下合适？它对我和对方的短期、长期影响是什么？这能把操控式期待改成共同满意的关系设计。', '["NLP", "关系沟通", "共同目标", "冲突修复", "请求", "影响评估"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 552, now()),
(100553, '亲和感校准：微调节奏，而不是机械模仿', '亲和感可通过姿势、呼吸、语速、音调、动作节律和情绪承认来校准。App 话术可提醒用户：先观察对方快慢、紧张程度和关注点，轻微靠近对方节奏；若对方愤怒或焦虑，先承认“你真的很在意/很生气”，确认被听见后再解决问题。它不是操控技巧，也不能替代真实能力和兑现承诺；长期关系仍取决于可靠、胜任和一致的行为。', '["NLP", "亲和感", "非语言沟通", "情绪确认", "语速", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 553, now()),
(100554, '价值观式说服：先倾听标准，再提出方案', '书中把说服力定义为给对方提供“对他们有价值”的东西，而不是把自己的价值强加给对方。App 可把说服练习改成三步：先问“你最看重什么/什么会让你觉得值得”；区分材料规格（具体条件）和更高层标准（安全、效率、被尊重、长期收益）；最后只提出能真实匹配的方案。如果不匹配，坦诚说明，比强推更能保护信任。', '["NLP", "说服", "价值观", "倾听", "需求澄清", "职场沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 554, now()),
(100555, '个人一致性：让内在声音、行动和价值观站到同一边', '在重要沟通前，可先检查自己是否一致：我说出口的目标，是否与真实价值一致？我的身体姿态、声音和承诺是否支持它？书中指出，阻碍人的常不是缺能力，而是内在部分互相拉扯；强行压下恐惧、愤怒或不安全感并不能解决问题。App 可引导用户承认各部分关切，再选择与核心价值相匹配的小行动。个人一致性不是速效技巧，而是通过一次次守约重建自我信任。', '["NLP", "一致性", "内在声音", "价值观", "自我信任", "沟通准备"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 555, now()),
(100556, '关联与分离：用视角切换给状态多一个档位', '关联是从自己的眼睛进入体验，分离是像观察者一样看见自己在体验中。App 可引导用户：对积极记忆，适度关联，重新体验资源感；对普通压力事件，先分离，像看电影一样观察发生了什么、自己学到什么，再决定下一步。视角切换不是否认情绪，也不适合单独处理强创伤或悲痛；它适合作为日常状态管理和沟通复盘的轻量工具。', '["NLP", "状态管理", "关联分离", "视角切换", "情绪调节", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 556, now()),
(100557, '批评声音重框：把攻击性自评转成可用反馈', '当内在声音说“你真差劲”时，不必直接相信，也不必立刻消灭它。可先定位声音的音调、速度和位置，观察它如何影响情绪；再问它想保护什么、提醒什么；最后协商更有效的表达方式，例如把“你永远做不好”改成“这次哪里没达标，下一步能改什么”。肯定句也要可信，像“我可以学习更体贴”通常比“我完美体贴”更容易被内在系统接受。', '["NLP", "重框", "内在批评", "自我对话", "正向意图", "语言模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 557, now()),
(100558, '稳健积极心态：不是盲目乐观，而是小步参与和自我比较', '积极心态可以被拆成可练习的结构：有吸引力的内在动力、高标准价值、把大目标分成小步、既专注当下又看见未来、亲自参与行动、用今天的自己和昨天的自己比较。App 可把它转成低压计划：今天只完成一个微步骤，记录自己比上次多做了什么，把他人的成功当模型而非羞辱来源。这样能支持持续行动，而不是用“你要积极”压住真实困难。', '["NLP", "积极心态", "小步骤", "自我比较", "成长", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 558, now()),
(100559, '经验不是直通现实：心智会把有限线索建构成可用世界', '我们常以为自己直接看见了世界、直接知道了感受和事实，但书中反复说明：感官给到的只是有限线索，心智体验是脑在后台整合线索、记忆、期待和无意识推理后形成的“可用版本”。用于心理教育时，这能帮助用户把“我感觉如此”与“事实必然如此”分开：焦虑、羞耻或关系中的受伤感是真实体验，但它们仍可能是一个需要核对和更新的内部模型，而不是最终判决。', '["心智建构", "经验校准", "无意识推理", "认知解融合", "现实检验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 559, now()),
(100560, '预测误差是学习入口：意外不是失败，而是模型在更新', '心智不断预测接下来会发生什么，并用“结果与预期不一致”的地方来学习。奖赏本身固然重要，但真正推动改变的是预测误差：比预期好、比预期坏、或预期落空，都会提示模型需要调整。在 App 中可把它转化为练习语言：不要只问“我做得好不好”，也问“这次结果和我预想哪里不同”。行为实验、暴露练习、关系沟通后的复盘，都可以把意外当数据，而不是当自我否定。', '["预测误差", "行为实验", "学习机制", "复盘", "心理灵活性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 560, now()),
(100561, '情绪像价值地图：它在标记“靠近、远离、重视或警惕”', '情绪不只是脑内噪音，也不是必须压下去的麻烦。书中把学习、奖赏、惩罚和价值联系起来：人会把地点、人物、行动和结果连成一张价值地图，熟悉街道、某张脸或某种互动方式都可能快速唤起身体反应。心理教育可借此提醒用户：强烈情绪常在说“这里对我有价值或有风险”。先识别它标记的价值，再决定是否相信它、如何行动，比单纯批评自己“太敏感”更有帮助。', '["情绪教育", "价值地图", "趋近回避", "身体信号", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 561, now()),
(100562, '身体感也是建构出来的：边界会随注意、工具和行动改变', '我们以为身体是最确定的“我”，但身体经验同样会被建构。橡胶手错觉、工具像手臂延伸、以及行动中未被意识到的身体修正都说明：身体边界并不是固定墙壁，而是脑为了行动而临时组织出的工作模型。用于 App 时，可引导用户用温和的身体扫描、接地练习和动作觉察来重建安全感：不是逼自己“相信身体”，而是慢慢收集身体可被感知、可被照顾、可与环境协作的新证据。', '["身体觉察", "身体边界", "接地练习", "身心连接", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 562, now()),
(100563, '控制感来自预测顺畅：意识到的常是意图，不是全部动作细节', '人在顺利行动时通常感觉“我在掌控”，恰恰因为许多细节没有进入意识：眼睛移动、手臂修正、触觉反馈被预测并抵消，意识中留下的是目标和意图。失控感往往出现在预测被打断、反馈太强或身体信号变陌生时。心理教育可把“我为什么连自己都控制不了”改写为“我的系统正在处理未预测到的反馈”。这样更容易从自责转向调节：放慢、降低任务难度、让身体重新获得可预测的小成功。', '["控制感", "意图", "身体反馈", "自我调节", "小成功"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 563, now()),
(100564, '想象能训练行动，但需要和真实反馈形成循环', '书中区分了有效的心理演练和封闭的空想：想象动作可以调用行动预测，帮助协调“我想做什么”和“怎样做会发生什么”；但完全停留在脑内时，缺少现实的意外和误差，创造性会变窄。App 可把这转成练习：先在脑中预演一次困难对话、暴露任务或新行为，再写下预测，随后做一个很小的现实尝试，用真实反馈更新下一轮预演。', '["心理演练", "行动计划", "反馈循环", "创造力", "行为激活"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 564, now()),
(100565, '先验信念会塑造“看见”：强预期可能压过新证据', '感知不是从外到内的线性复制，而是从已有信念出发，不断预测并修正。强先验能让我们稳定地识别世界，也可能让我们在模棱两可时只看见熟悉解释。放到心理教育里，很多自动想法都像强先验：例如“别人一定讨厌我”“我肯定会失败”。练习重点不是否认这些想法，而是降低它们的绝对性，主动寻找被忽略的证据，让新的体验有机会进入模型。', '["先验信念", "自动想法", "证据核对", "贝叶斯脑", "认知灵活"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 565, now()),
(100566, '心理灵活性：把想法当模型，而不是把模型当真相', '书中的“模型”视角很适合心理灵活性训练：一个想法、判断或自我故事，价值不在于它听起来多确定，而在于它是否能帮助我们更好地理解现实、采取有效行动、并在反馈出现时更新。僵化痛苦常来自把内部模型当成唯一真相；灵活不是没有立场，而是愿意说“这是我当前的地图”。当地图带我反复走进死胡同，就需要用新的行动和他人反馈来修订。', '["心理灵活性", "想法不是事实", "现实反馈", "自我故事", "价值行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 566, now()),
(100567, '读懂他人是建模：不要把自己的推断当成对方心声', '理解他人并不是神秘读心，而是根据动作、表情、语境、语言和过往经验建构对方信念、愿望与意图的模型。这个能力让共情和合作成为可能，也会带来误读：一个动作可能有多个目标，一句话也可能有反讽、试探或防御。App 中可用作关系教育：把“他就是故意的”改成“我正在推断他的意图”，再通过提问、复述和观察后续行为来校准模型。', '["关系沟通", "心智化", "意图推断", "共情", "误读校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 567, now()),
(100568, '情绪会传染，交流要闭合循环：看见反馈后再调整表达', '人与人互动时会无意识模仿动作、表情和情绪，彼此也在预测对方接下来会怎么理解、怎么回应。有效沟通不是把话单向丢出去，而是观察对方反应，发现预测错误，再调整表达方式。心理教育可训练用户在冲突中暂停三步：我想传达什么？我猜对方听成了什么？对方的反馈说明我需要怎样重说？这样能把情绪传染从失控循环变成修复循环。', '["情绪传染", "闭合循环", "沟通修复", "反馈", "关系调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 568, now()),
(100569, '自我感是有用的组织方式：选择发生在身体、情境与关系之中', '书中把“稳定、独立、完全掌控的自我”称作脑创造的最后一种错觉，但它不是无用幻象。自我感帮助我们体验自己是行动者，也让责任、公平、合作和文化成为可能。用于 App 时，这能提供一种温和框架：你不是孤立的小脑袋，也不是被环境完全决定的机器；你的选择来自身体状态、旧模型、当前情境和他人互动的共同作用。成长就是在这些作用中增加觉察和可选择性。', '["自我感", "代理感", "责任", "关系中的自我", "可选择性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 569, now()),
(100570, '自我观察优先：理解他人前先把镜头转回自己', '九型人格可以帮助理解关系，但它的入口不是“看穿别人”，而是先看见自己如何解释、回避和自我辩护。App 端可把它转成一个前置练习：当用户想分析伴侣、同事或家人的类型时，先记录“我在这段关系里最想证明什么、最怕被看见什么、我正在给自己找什么理由”。对他人保留换位理解，对自己练习事实核对；这样九型不会变成给别人定罪的工具，而会成为减少投射和盲点的镜子。', '["九型人格", "自我觉察", "关系洞察", "投射", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 570, now()),
(100571, '中性编号：型号不是等级、病理名或人生判决', '书中反复提醒，九型的数字只是中性坐标，不代表高低、好坏或病理诊断。某个类型在一种文化中更受欢迎，只说明社会偏好某些特质，并不说明它更有价值。App 端在生成解释时应避免“你就是这种人”“某型天生差”等句式，可改成：“你可能正在用某种熟悉模式保护自己；这个模式有优势，也有代价。”这样的表述既保留识别价值，又防止用户把类型当成命运判决或羞辱标签。', '["九型人格", "非标签化", "人格类型", "去病理化", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 571, now()),
(100572, '三元组辩证法：过度、脱离、不足构成盲点地图', '情感、思维和本能三元组不只是“你擅长哪个中心”，更像一张盲点地图：每个三元组里都有一种过度表达、一种与该能力脱离、一种表达不足。比如情感三元组中，2 号容易过度强调正面情感，3 号可能为了效率和形象切断真实感受，4 号则常间接表达情感；思维和本能三元组也有类似结构。App 可用三个问题引导用户：我在什么能力上过度用力？我在哪里失联？我把哪种能力交给幻想、规则或他人代替了？', '["九型人格", "三元组", "盲点", "情感中心", "思维中心", "本能中心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 572, now()),
(100573, '读到不舒服时先暂停：被击中可能是识别线索', '人在找型号时容易选择自己喜欢的形象，而不是更贴近真实的模式。书中提到，读到自己类型的描述时可能会焦虑、低落、发冷或不适，这不必立即解释为“我很糟”，也可能是材料触碰到了长期回避的盲点。App 端可把识别过程设计得更温和：如果某段描述让用户强烈防御，先暂停、呼吸、写下“不舒服的是哪一句、它像哪段生活经验”，再决定是否继续。识别的目标不是羞辱自己，而是获得改善入口。', '["九型人格", "类型识别", "自我防御", "自我觉察", "节奏调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 573, now()),
(100574, '不要用单一特质归型：同样强势可能出自不同动机', '同一个外在行为，背后的动机可能完全不同。书中以“发号施令”为例：8 号可能从力量和控制出发，1 号可能从“我正确”出发，2 号可能是在防止被伤害或失去关系，6 号可能带着威胁感，7 号可能是在要求环境满足需要；同样，抑郁或被误解感也可能出现在所有类型中。App 端做类型判断时，可先把“行为外观”变成待核对假设，再追问动机、恐惧、注意力焦点和长期模式，而不是凭一个标签快速归类。', '["九型人格", "动机识别", "关系互动", "行为解读", "误判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 574, now()),
(100575, '整合方向不是自责改造，而是有意识地退出旧模式', '解离常是阻力最小的路：压力升高时，人会自动滑向熟悉防御；整合则需要有意识的选择和努力。但这种努力不是责备自己、强行修正失败，也不是用更严厉的意志压住症状。更有效的入口是：看清自己的恐惧、伤痛和弱点，不评判、不辩解，然后选择一个能松动旧模式的小动作。App 端可把“成长建议”写成温和邀请：我此刻正在自动保护什么？有没有一个更自由、更有建设性的回应可以试一分钟？', '["九型人格", "整合方向", "解离方向", "成长建议", "非评判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 575, now()),
(100576, '完整画像四要素：核心类型、翼型、整合线、解离线', '一个人不是“纯粹某型”。书中建议，要获得更完整的自我图像，至少同时看核心类型、主导翼型、整合方向和解离方向：核心类型解释主要透镜，翼型解释同型差异，整合线提示更健康的能力来源，解离线提示压力下容易借来的低阶模式。App 端可把九型画像做成四层地图，而不是单一判词：我主要从哪里看世界？相邻风格怎样改变表达？压力大时我像谁？更健康时我可以发展哪类能力？', '["九型人格", "翼型", "整合方向", "解离方向", "自我画像"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 576, now()),
(100577, '核心机制螺旋：恐惧、欲望、态度与行为互相加固', '书中的“核心机制”把每种类型看成一个动态螺旋：基本恐惧引出基本欲望，欲望塑造心理能力与自我形象；一旦自我形象被认同，就会出现继发恐惧，人又通过某些态度和行为去补偿，随后产生新的恐惧，层层向下。App 可把它转成卡片式复盘：“我最底层在怕什么？我用什么欲望解决它？我维持了什么自我形象？这个形象让我不能承认哪些感受？我的补偿行为又制造了什么新冲突？”这样能从行为回到动机，而不是只纠正表面动作。', '["九型人格", "核心机制", "基本恐惧", "基本欲望", "防御机制", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 577, now()),
(100578, '父母取向不是责怪父母：它描述儿童如何适应养育与保护', '书中把人格发展追溯到儿童早期与养育者、保护者的关系取向，但这不是把责任简单推给父母，也不是说童年决定一切。更合适的理解是：孩子会在气质、家庭、环境和文化共同作用下，发展出一种生存与归属策略。App 端可用假设语言引导：“我当年可能为了安全、爱、秩序或自主学会了什么？这套策略现在还服务我吗？”这样既承认早年经验的影响，也保留成人更新模式的空间。', '["九型人格", "童年模式", "父母取向", "适应策略", "非决定论"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 578, now()),
(100579, '本能性变体：同一型号会把动机投向不同生活领域', '本能性变体不是核心类型本身，也不是翼型，而是一个相对独立的关注领域。自我保存取向更关注金钱、食物、居住、健康、舒适和身体安全；社会取向更关注群体参与、地位、贡献、认可和归属位置；性取向不等于“好色”，更常表现为对一对一强烈连接、亢奋体验和活力感的追求。同一型号叠加不同本能，会在生活议题上很不一样。App 端可把它作为情境层，帮助用户分辨“我的核心恐惧正在投向身体安全、群体位置，还是亲密强度”。', '["九型人格", "本能性变体", "自我保存", "社会本能", "亲密关系", "动机"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 579, now()),
(100580, '关系策略三组：进攻、屈从、退缩不是好坏，而是安全方案', '九型还可借霍尼的人际取向理解为三组关系安全策略：3、7、8 更容易以扩张、争取、进入环境来处理威胁；1、2、6 更容易屈从于内化规则、责任或权威要求；4、5、9 更容易后撤到内在世界、思考、幻想或不露面。这里的“进攻、屈从、退缩”不是价值评判，而是人在压力下保安全的方向。App 端处理冲突时可问：我现在是在冲上去、按应该做、还是撤回来？这个策略保护了什么，又让我失去了什么连接或行动？', '["九型人格", "关系互动", "霍尼", "进攻型", "屈从型", "退缩型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 580, now()),
(100581, '自我实现预言：人格策略常把人带到最害怕的结果', '书中提出一个很适合 App 端转化的悖论：每种类型都在追求自己以为会带来幸福的东西，但若把它绝对化，常会制造最害怕的结果。2 号追求被爱却可能更觉得缺爱，3 号追求成就却可能更空虚，5 号追求知识却仍感无力，6 号追求安全却更焦虑，9 号追求平静却更无根。产品中不要把这写成“某型注定失败”，而应写成复盘问题：我正在把哪部分好东西当成全部？有没有一种更健康的方式满足背后的真实需要？', '["九型人格", "自我实现预言", "核心欲望", "成长建议", "动机复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 581, now()),
(100582, '沟通不是把句子交出去：意义需要共同背景和意图推理', '很多关系冲突并不是因为某一句话“语法上不通”，而是双方没有共享同一套背景、目标和心理预期。《语言本能》在讨论真实谈话时提醒我们：生活中的对话并不像教科书例句那样完整、整齐。人会大量使用“它”“那件事”“你知道的”等代词和省略，也会把逻辑链条压缩成短短一句，因为谈话是现场发生的，若每一步都从头解释，交流就会慢到无法进行。听者之所以能懂，是因为他会把话语碎片放回共同经历、场景、常识和对说话者意图的推断里。

这对 App 端沟通知识库很有价值：当用户说“对方明明听见了，却故意曲解我”时，可以引导他先区分三个层面：我实际说了什么、我以为对方知道哪些背景、对方可能用什么背景在理解。关系里的“听懂”不是自动解码，而是一种合作推理。越是在亲密、家庭和职场高压场景中，双方越容易误以为“你懂我的意思”，却没有把必要前提说出来。更稳妥的做法是把隐含信息补足：先说共同主题，再说新的请求；先交代背景，再表达判断；先确认对方理解到哪一步，再继续推进。

这条知识也能避免把沟通问题完全道德化。对方没懂，不一定是不在乎；自己说不清，也不等于表达能力差。更可迁移的练习是：在重要谈话前写下“对方必须知道的三件背景”“我真正希望他采取的一个行动”“我需要核对的一个理解”。把沟通从猜心转为共同建模，关系里的防御会明显降低。', '["语言沟通", "关系表达", "误解修复", "共同背景", "职场沟通", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 582, now()),
(100583, '把复杂话说得让大脑省力：先安放主题，再推进新信息', '“说得有道理”和“让人听得懂”不是同一件事。书中关于句子理解的章节指出，人脑在处理语言时有短期记忆瓶颈：一个句子如果把重要成分悬在那里太久，让听者长时间等待主语、动词、宾语或结论，理解负担就会陡增。那些头重脚轻、插入成分过多、绕了很久才到重点的表达，会让听者在还没理解内容前就已经耗尽注意力。好的表达不是堆满信息，而是让信息在听者脑中有地方落脚。

迁移到心理教育和日常沟通，可以形成一条实用原则：先给对方“主题”，再给“新信息”。比如职场反馈不要一开口就塞进五个背景、三个例外和一串情绪，而可以先说“我想讨论这次交付的时间安排”，再说“最影响协作的是临近截止才同步风险”。亲密关系中也一样，与其说“你上次、这次、还有每次都这样”，不如先安放主题：“我想谈的是我在临时变更计划时的不安”，再补充例子和请求。

这并不是要求每个人都像写公文，而是照顾对方大脑的处理方式。App 可将其转化为表达模板：第一句标明话题，第二句说明事实，第三句给出自己受到的影响，第四句提出一个可回应的请求。复杂内容可以分层，不要让一个句子承担全部任务。越重要的话，越要让它短、清楚、可停顿、可确认。沟通的善意不仅体现在语气，也体现在不给对方制造不必要的理解负担。', '["表达结构", "职场沟通", "认知负荷", "关系沟通", "清晰表达", "写作思维"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 583, now()),
(100584, '礼貌和暗示是一种关系缓冲：间接表达要给退路，也要及时核对', '人并不总是把真正意图直接说出来。书中谈到礼貌用语时指出，很多社会都会用绕一点的方式表达请求：表面上像是在询问、猜测或表达愿望，实际意图可能是“请你帮我”。这不是虚伪，而是一种关系技术：直接命令会让对方难堪，间接表达给了对方拒绝、协商和保全面子的空间。幽默、反语、暗示、比喻和委婉说法，也常常依赖这种“表面意思”和“真实意图”之间的张力。

但间接表达有两面性。它能保护关系，也容易制造误会。亲密关系里，“你今晚忙吗”可能是想约对方，也可能只是问行程；职场里，“这个方案是不是还可以再看看”可能是温和建议，也可能是明确否定。如果双方都默认对方会读懂弦外之音，就容易进入委屈循环：一方觉得“我已经说得很明显了”，另一方觉得“你为什么不直接说”。

因此，App 端可以把这条知识转化成两个方向的练习。表达者可以在保留礼貌的同时补足意图：“如果你方便，我想请你今晚帮我看一下；不方便也可以改明天。”听者则可以用低防御核对：“我听起来你是在希望我调整这个方案，对吗？”这样既不粗暴拆穿对方，也不把猜测当事实。好的沟通不是永远直白，也不是永远委婉，而是知道什么时候给对方退路，什么时候把关键请求说清。', '["礼貌表达", "非直义语言", "请求", "边界协商", "关系修复", "沟通核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 584, now()),
(100585, '心中所想不等于口中所言：别把语言当成思想的牢笼', '《语言本能》对“语言决定思维”的批评，适合转化为一条重要的心理教育原则：人的想法不等于他说出口的那串词。我们常常在说话中停顿、改口、寻找更贴切的词；也常常在听完别人说话后只记得大意，而记不住原句。这说明头脑里有独立于具体语言的意义表征。语言会影响表达的便利程度，却不是思想的全部，也不应该被神化成决定人格、命运或关系质量的唯一力量。

在人际关系里，这能帮助用户减少两种误区。第一，不要把对方一时表达不准，直接等同于“不真诚”“不爱我”“态度恶劣”。话语可能笨拙，意图仍需要核对。第二，也不要因为自己词穷、表达混乱，就判定自己没有想法或不配沟通。尤其在强烈情绪中，人的内在经验往往先以身体感、画面、冲动或模糊判断出现，语言只是后续整理工具。

这条知识可以支持一个 App 练习：把“我说了什么”与“我真正想表达什么”分开写。第一栏记录原话，第二栏写意图，第三栏写对方可能听到的意思，第四栏改写成更清楚、更少攻击的版本。它也适用于冲突复盘：不要只逐字审判一句话，而要追问场景、意图、影响和可修复的表达。承认语言不是思想本身，反而能让沟通更负责：我们既不迷信措辞，也不放弃把内在经验翻译得更准确。', '["认知心理", "语言决定论", "情绪表达", "关系沟通", "自我觉察", "冲突复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 585, now()),
(100586, '词穷不等于没有感受：给非语言思维留出图像、身体和行动通道', '书中在讨论“思维不同于语言”时列举了许多非语言思维线索：有人在失去语言能力后仍保留推理与理解；创作者、科学家常先以图像、空间结构、身体动作或模糊模型进行思考，再把它们翻译成词语。这个观点对心理教育很重要：当一个人说“我说不上来”“脑子一片空白”“我只知道胸口堵”，并不代表他没有内在经验，而是语言通道暂时不够用。

App 端可以据此提供更包容的自我表达路径。对于情绪强烈、创伤记忆、亲密冲突或职业困惑，用户未必能马上写出准确叙述。可以先问：这个感受像什么颜色、重量、形状？它在身体哪里最明显？如果用一张图表示，现在的你和对方距离多远？如果只能做一个很小的动作，你想靠近、离开、挡住、还是伸手？这些问题不是绕开语言，而是在帮助语言找到前置材料。

这条知识也能提醒助人者不要过早逼迫用户“讲清楚”。有些经验需要先被感知，再被命名；先被画出来、摆出来、比喻出来，再进入理性讨论。对亲密/家庭沟通也一样，当孩子或伴侣说不出来时，可以给选项、图像、身体词和时间，而不是立刻追问“你到底什么意思”。表达的目标不是立刻漂亮，而是让内在经验逐渐可见、可承载、可协商。', '["非语言思维", "情绪命名", "身体觉察", "表达困难", "心理教育", "亲密沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 586, now()),
(100587, '共享词汇像通用货币：关系中的关键词需要重新对齐含义', '《语言本能》把单词看作一种共享符号：它之所以有效，不是因为声音和意义天然相连，而是因为一个语言共同体默认大家都可以用它来传递相近意思。单词像通用货币，让说话者把意思转成声音，让听者再把声音转回意思。这个机制看似平常，却解释了许多关系误会：同一个词在不同家庭、行业、伴侣关系和成长经历中，可能绑定了不同经验。

例如“陪伴”对一个人可能意味着每天聊天，对另一个人可能意味着遇到困难时不消失；“尊重”在一方那里是少干涉，在另一方那里是主动汇报；“负责”在职场中可能是交付结果，在亲密关系里可能是情绪可回应。如果双方只争论“你到底有没有尊重我”，而不拆解这个词在各自心理词典中的含义，就会把符号当成事实本身。

App 可将这条知识转化成“关键词对齐”练习：选择冲突中反复出现的一个词，分别写下“我说这个词时指什么行为”“我最害怕它缺席时发生什么”“我希望对方具体怎么做才算有这个词”。沟通时用“对我来说，安全感具体包括……”替代“你从来不给我安全感”。这样做不是咬文嚼字，而是在重建共享代码。很多关系不是没有爱，而是关键符号没有校准；把抽象词翻译成可观察行为，才有协商空间。', '["心理词典", "关系表达", "关键词对齐", "亲密关系", "需求沟通", "误解修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 587, now()),
(100588, '儿童语言发展靠真实互动：少一点机械纠错，多一点共同注意', '书中关于儿童语言习得的讨论指出，孩子不是靠电视、录音或机械灌输学会说话的。声音环境重要，但“有人在眼前谈论正在发生的事情”更重要。现实中的照料者会放慢语速、夸张语调、围绕孩子正在看见和经历的事说话；孩子则像小小的读心者，把成人的话与场景、动作、意图对应起来。所谓母亲式语型并不是必修课，也不是简单语法课，但它之所以有帮助，是因为它把语言放进了可理解、可互动、可共同注意的现场。

这对亲子知识库可以提炼为：促进语言和沟通，不是把孩子当成被动接收器，而是和他共享注意。与其反复播放教学视频，不如在穿衣、吃饭、散步、收玩具时说“你在拿红色杯子”“水洒出来了，我们擦一擦”“你想要大的还是小的”。语言最好贴着当下经验生长，并且允许孩子用眼神、动作、声音和不完整词语参与。

同时，父母不必把每个语法错误都当成教育时机。书中提到，父母对孩子语法是否正确往往并不给出稳定反馈，而孩子仍能逐渐掌握复杂语法。更重要的是回应意义、扩展表达和保持互动：孩子说“狗狗跑”，成人可以接“对，黑色狗狗跑得很快”，而不是急着纠正句式。真实互动给孩子的不只是词汇，还有轮流、回应、共同关注和关系安全，这些都是语言成长的土壤。', '["亲子沟通", "儿童语言", "共同注意", "家庭教育", "学习成长", "互动回应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 588, now()),
(100589, '孩子说错话不等于学坏了：过度概化常是规则感正在形成', '孩子的语言错误常让成人着急，但《语言本能》提醒我们，许多错误并不是混乱，而是规则学习的证据。孩子会把规则后缀套用到不规则词上，也会创造成人觉得别扭但逻辑清楚的表达。这类“过度概化”说明孩子不是单纯模仿，而是在主动归纳语言规律。三岁左右的孩子已经能处理大量复杂结构，错误率远低于成人直觉想象；他们真正困难的往往不是“没有规则”，而是还在学习哪些地方需要例外、哪些表达在本语言中被允许。

迁移到心理教育，可以帮助父母把焦虑从“孩子是不是笨/不认真/被我教坏了”转向“他正在尝试建立规律”。这并不表示完全不用引导，而是引导方式要从羞辱纠错变成自然示范。孩子说“我昨天去ed那里”，成人可以用正常句子回应：“你昨天去了那里，很开心吧？”让正确形式进入互动，而不是打断孩子的表达欲。对年龄较大的孩子写作或外语学习也是如此，错误常常是系统正在运行，只是规则边界还没收窄。

这条知识还能延伸到成人成长。人在学习新技能、新沟通方式时，也会经历“套规则过头”的阶段：学非暴力沟通后说话变得生硬，学边界后拒绝显得过猛，学职场表达后像背模板。与其嘲笑，不如把它视为新系统的练习期。成长不是一开始就自然流畅，而是先有粗糙规则，再通过反馈变得灵活。', '["儿童发展", "学习成长", "规则学习", "亲子教育", "成长型思维", "表达练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 589, now()),
(100590, '标准语是场景工具，不是人格高低：减少语言羞耻', '书中区分了两类“语法”：一种是人脑自然使用语言的机制，另一种是学校、编辑、写作手册和社会权威制定的规定性规则。一个人的话可能从语言机制看完全有规则，却不符合某个正式场合的标准。这个区分对心理教育很有用，因为许多人的语言羞耻来自把“标准”误读成“价值”：口音、方言、非正式用法、教育背景差异，被当成了聪明、礼貌、家教甚至人格高低的证据。

更健康的理解是：标准语是一种场景工具。它像正式服装、会议礼仪或行业格式，在考试、求职、报告、法律文件等场景中确实有用，因为它降低陌生人之间的理解成本，也减少不必要的偏见。但它不是衡量一个人心智复杂度和情感深度的唯一标准。家庭和亲密关系中，如果把每次表达都审判成“你怎么这么不会说话”，对方更可能收缩、防御或沉默，而不是变得清楚。

App 可提供双重建议：一方面鼓励用户学习正式表达，把它当成扩大选择的工具；另一方面帮助用户拆除语言羞耻，不把口音、方言或不够书面化等同于低价值。真正需要改进的，往往不是“像权威一样说话”，而是表达是否清楚、是否尊重场景、是否让对方能理解并回应。把标准语从身份审判还原成可学习工具，沟通会少很多压迫感。', '["语言羞耻", "标准语", "自我价值", "社会心理", "沟通教育", "非评判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 590, now()),
(100591, '方言、俚语和口头禅背后有身份与距离：先理解功能再评价', '《语言本能》批评一些“语言专家”低估普通人的语言能力，也提醒读者：俚语、口头禅、非标准表达并不只是语言腐败。很多俚语是亚文化的身份徽章，能迅速标记“我们是谁、和谁一伙、与谁保持距离”；一些看似多余的口头禅，可能是在降低权威感、缩短社会距离、让谈话不那么像训话。语言不仅传递信息，也在调节关系位置。

这对家庭、亲密和职场沟通都很实用。父母听到孩子的新词，不必第一反应就是“没教养”；管理者听到年轻同事的口头表达，也不必马上贴上“不专业”。更有效的做法是先问它在这个群体里起什么作用：是在开玩笑、缓和紧张、表示亲近、保护边界，还是逃避清晰表达？理解功能之后，再讨论场景适配。比如可以说：“和朋友这样说没问题，但给客户邮件要换成更正式的表达。”

这条知识也能帮助用户识别关系中的距离变化。伴侣忽然使用很客气的书面语，可能是在拉开距离；团队里共享的玩笑话变少，可能代表安全感下降；孩子用同辈语言而不用家庭语言，可能是在寻找身份。不要把语言风格只当“对错”，还要看它在调节亲近、权力、归属和反抗。先理解功能，再给出边界，沟通才不容易变成代际或身份战争。', '["语言风格", "身份认同", "代际沟通", "职场关系", "方言俚语", "关系距离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 591, now()),
(100592, '不同语言不等于不同人性：跨文化沟通要同时看差异与共同心智', '书中一方面承认世界语言差异巨大，另一方面也强调人类语言背后有许多共同结构。不同语言、方言、口音会形成身份边界，甚至引发“我们/他们”的区分；但不能由此推断不同群体拥有完全不同、彼此不可理解的心智。把语言差异神秘化，容易走向两种极端：要么把对方文化浪漫化成无法理解的异域奇观，要么把对方表达方式贬低成落后、混乱或不讲理。

跨文化、跨地域、跨阶层沟通更稳妥的原则是：承认差异，但不夸大成人性鸿沟。差异层面包括词汇、礼貌规则、直接/委婉程度、沉默含义、称呼和权力距离；共同层面包括人都需要被理解、被尊重、被安全对待，也都会依靠背景知识、意图推理和共同注意来理解语言。只看共同性，会忽略具体文化规则；只看差异性，又会把对方当成另一个物种。

App 可将其用于关系教育：遇到“他家就是这样说话”“他们那类人都这样”的归因时，先把标签拆成可观察行为。问：具体是哪句话让我不舒服？这句话在他的语境中可能是什么意思？我们共同需要解决的问题是什么？我可以提出哪条明确边界？这样既不否认语言和文化差异，也不把差异变成偏见。真正成熟的跨文化沟通，是在共同人性上建立尊重，在具体差异上进行核对。', '["跨文化沟通", "语言多样性", "共同人性", "偏见修正", "关系理解", "文化差异"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 592, now()),
(100593, '从语言本能看成长：学习不是白板吸收，而是天赋框架与环境协作', '《语言本能》反复反对一种过于简单的学习观：孩子不是空白容器，环境也不是把知识直接倒进去。语言习得显示，人有先天的组织框架，会主动从有限输入中归纳规则；但如果完全没有语言环境，能力也无法自行长成。也就是说，成长既不是纯靠天赋，也不是纯靠灌输，而是内在准备与外部条件的协作。

这条知识可以迁移到 App 端的学习成长和心理教育。用户常把改变理解成两种极端：要么“我天生就是这样，改不了”，要么“只要方法对，我应该立刻变好”。语言本能提供了第三种视角：人有自己的发展窗口、敏感点、已有结构和限制；好的环境不是替他完成成长，而是提供足够清晰、稳定、可互动的输入，让他把潜在能力组织出来。亲子教育、伴侣沟通、情绪调节和职场训练都可按这个逻辑设计。

实际应用时，可以问三个问题：第一，我已经具备哪些内在资源或直觉？第二，当前环境缺少什么输入、反馈或安全感？第三，我能不能用小步练习让内在能力被唤醒，而不是用羞耻逼迫自己？比如学习边界表达，不是背一句模板就结束，而是在低风险场景中反复体验“说清楚—被回应—再调整”。成长不是白板被写满，而是一个系统在合适环境中逐渐分化、校准和成熟。', '["学习成长", "发展心理", "内在资源", "环境支持", "行为改变", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 593, now()),
(100594, '口语天然不完美：重要谈话不要只拿逐字稿审判彼此', '书中提到，真实对话一旦被逐字记录，常会显得断裂、重复、跳跃甚至不知所云。原因并不只是说话者水平差，而是口语本来就依赖语调、停顿、眼神、共同场景和即时修正。人说到一半会改方向，会用代词承接前文，会省略双方都知道的部分；新闻采访、法庭记录和日常争吵一旦丢掉现场线索，就很容易把活的互动误读成混乱文本。

这对亲密关系尤其重要。很多争吵后的复盘会变成逐字审判：“你刚才明明说了那句话。”逐字记忆当然有价值，特别是涉及伤害、承诺和边界时不能随便否认；但如果只抓一句脱离语境的话，就可能忽略当时的语气、停顿、被打断、未说完的修正，以及双方共同建构的含义。更有帮助的是同时记录“原话、语境、我听到的影响、对方后来是否修正、我需要的澄清”。

App 可把这条知识做成冲突复盘提示：先不要急着判案，分别写下三层材料。第一层是可回忆的原句；第二层是场景，包括谁先提起、当时压力、是否在赶时间；第三层是意义，包括我听成了什么、对方可能想表达什么、需要对方为哪部分负责。这样既不纵容伤害性语言，也不把所有口误、卡顿和不完整表达都定罪。关系修复需要事实，但也需要理解口语现场的天然不完美。', '["冲突复盘", "口语表达", "关系修复", "语境核对", "亲密沟通", "非评判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 594, now()),
(100595, '把九型当作自我观察地图，而不是命运判决', '九型人格最适合被当作一张“观察地图”，而不是给自己或他人下结论的判词。原书一开始用图表介绍九种人格，并强调不同类型只是人回应社会与自然的方式不同：有人先回应关系，有人先回应目标，有人先回应安全，有人先回应秩序。App 端使用这类内容时，可以把重点从“我是哪一型，所以我注定如此”转为“我在什么情境下最容易重复哪一种反应”。

一个更安全的使用方式，是把类型当成假设，而不是身份。比如：当你发现自己总想照顾别人，可以先问“我是不是在用帮助换取连接”；当你总想把事情做到最好，可以问“我是不是把错误看得太危险”；当你习惯预想最坏情况，可以问“这是必要预案，还是焦虑在接管”。这些问题不会把人锁死，反而帮助人把自动反应变成可观察、可调整的模式。

九型觉察也不应用来解释“命运决定”。一个人的家庭、文化、经历、资源、关系和当下压力都会影响行为，同一类型的人也会有很大差异。真正有价值的是：看见自己的注意力习惯，看见它曾经如何保护自己，也看见它现在可能带来的代价。觉察之后，不必急着否定原来的自己，而是多给自己一个选择：我可以继续用旧方式，也可以用更清楚、更温和、更有效的方式回应。', '["九型人格", "自我觉察", "非宿命化", "人格地图", "成长路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 595, now()),
(100596, '心脑腹三中心：从感受、思考和行动看见惯性', '原书把九型分成心、脑、腹三个中心，提供了一个很适合 App 端心理教育的入口：你不必一开始就判断自己是哪一型，可以先观察自己更常从哪个通道回应世界。心中心的人更容易透过关系和感受确认自己，脑中心的人更容易透过分析、预想和资讯获得安全，腹中心的人更容易透过行动、存在感和力量感与世界连接。

这三个中心没有高低之分。感受敏锐的人，容易捕捉他人的需要，但也可能忽略自己的需要；思考发达的人，能提前规划和分析风险，但也可能陷入怀疑、退缩或过度准备；行动力强的人，能推动事情发生，但也可能没有停下来辨认真正的优先级。练习的重点不是把自己改造成另一个中心，而是让三个中心彼此补位。

一个简单练习是：遇到情绪或冲突时，分别问三个问题。心的问题是“我现在真实的感受和需要是什么”；脑的问题是“我掌握的事实是什么，哪些只是猜测”；腹的问题是“我接下来能做的一个小行动是什么”。当三类问题同时出现，人就不容易只被某一种惯性带走。九型在这里的价值，是帮助用户把模糊的性格标签转化为可练习的觉察路径：感觉要被看见，思考要被校准，行动要被选择。', '["九型人格", "三中心", "自我觉察", "情绪觉察", "行动练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 596, now()),
(100597, '内在观察者练习：把类型反应和觉察分开', '第十章谈到检测人格类型时，区分了“人格”和“内在观察者”：人格像是现实中的性格、气质、能力、思想、感觉和感官经验；观察者则是能看见这些反应的觉察力。这个区分很适合转化为 App 端练习，因为九型学习真正要培养的，不是更快给自己贴标签，而是多出一个能看见自己的位置。

当你说“我就是容易讨好”“我就是爱怀疑”“我就是忍不住控制”时，类型已经变成身份。观察者练习会把句子改成：“我注意到自己正在讨好”“我注意到自己开始怀疑”“我注意到自己想用控制获得安全”。这几个字的差别很大：前者像判决，后者像观察；前者让人停在旧模式里，后者给人留下选择空间。

可以做一个三步小练习。第一步，给反应命名：我正在进入哪一种熟悉模式？第二步，描述身体和情境：它发生在什么场景，身体哪里紧、热、空、僵或想逃？第三步，选择一个微行动：是表达需要、暂停十分钟、询问事实、写下担心，还是向对方说明边界。这样，九型不再是“我是什么人”的答案，而成为“我如何看见自己正在发生什么”的工具。长期练习后，用户会逐渐明白：人格反应可以被理解，内在观察者可以被训练，成长来自看见之后的小选择。', '["九型人格", "内在观察者", "自我觉察", "正念练习", "成长路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 597, now()),
(100598, '给予型觉察：助人之前先问“我也需要什么”', '原书中的给予型把快乐和价值感放在帮助他人上，能敏锐发现别人的需要，愿意付出智慧、时间、财物和情感支持。这是一种重要能力：它让关系更温暖，也让人容易成为团队和家庭中的支持者。但当助人成为唯一的自我确认方式时，人可能会忽略自己的需要，不愿求助，甚至用付出来间接要求别人理解、回报或靠近自己。

App 端可以把给予型内容转化为“照顾者的自我照顾”练习。第一步，帮助前先暂停十秒，问自己：我是真的愿意，还是害怕被拒绝、被忽略、被认为不够好？第二步，把需要说出来，而不是让别人猜。例如“我愿意帮你，但我今天也需要休息”“我希望我的付出被看见”。第三步，练习接受别人给自己的帮助。接受不是软弱，也不是亏欠，而是让关系从单向照顾变成双向流动。

和给予型相处时，及时表达感谢很重要，但更重要的是不要把他们的付出视为理所当然。若你不需要帮助，可以温和说明原因，而不是冷淡拒绝。若你发现他们用批评或抱怨表达未被满足的需要，可以邀请他们直接说：“你真正希望我怎么支持你？”这样，助人不再是牺牲自我的证明，而成为有边界、有选择、有回流的连接方式。', '["九型人格", "给予型", "助人模式", "自我照顾", "边界表达", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 598, now()),
(100599, '实践型觉察：从任务清单回到真实感受', '原书中的实践型把大量注意力放在目标、任务、效率和成功上。他们精力充沛，能激励团队，愿意为了结果持续投入；但也容易把生活变成一个接一个任务，把休息、人际感受和真实情绪都排在后面。为了被认可，他们可能不自觉调整形象，让自己看起来更能干、更成功，久而久之反而和真实需要失去连接。

对这类模式，App 端可以提供“任务—感受双记录”。每天列出最重要的三件事，同时为每件事补一句：我做这件事时想获得什么感受？是成就、安全、被尊重，还是避免失败？完成后再写一句：我身体现在怎么样，我的情绪是什么？这种练习不是削弱行动力，而是让行动不再只为外部评价服务。

实践型还需要练习慢下来。原书建议主动停下工作、散步、听可信朋友反馈、不要急着转入下一个目标。可以把它转化成一个具体规则：重要任务完成后，先不立刻开新战线，留出 15 分钟复盘“事实、感受、关系影响、下一步”。与实践型沟通时，也适合直截了当说明事情的价值、收益和影响，同时提醒他们：别人努力不一定是在竞争，别人表达感受也不是浪费时间。真正稳固的成功，不只来自完成任务，也来自能在成就之外认出真实的自己。', '["九型人格", "实践型", "成就动机", "真实感受", "自我觉察", "工作关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 599, now()),
(100600, '浪漫型觉察：在强烈情绪里保持稳定和当下', '原书中的浪漫型重视情绪深度、独特性、意义感和美感，容易被不寻常、富有象征性或艺术性的经验吸引。他们能对他人的痛苦保持高度同情，也能把生活中的细节转化为审美与创造力。但当注意力长期停留在失落、被遗弃感、理想化关系或“我与别人不同”上，情绪就容易放大，关系也容易在冷热之间摇摆。

App 端可以把浪漫型觉察设计成“强烈感受的稳定练习”。当情绪上来时，不急着证明自己是对的，也不急着推开对方。先做三件事：给情绪命名，确认它是悲伤、羞耻、羡慕、愤怒还是失望；把注意力带回当下，写下眼前三个客观事实；再问自己：我真正害怕失去的是什么，我可以直接表达哪个需要？这样能把“情绪浪潮”变成“可理解的信息”。

浪漫型的成长不是抹掉独特性，而是把独特性落回生活结构。原书提醒要学习看眼前正面和积极的东西，减少对失落的执着，让生活更有节奏。可以从小处练习：固定睡眠、完成一件普通但有益的事、把灵感变成一个具体行动、向朋友直接说明感受而不是等待猜测。与浪漫型相处时，肯定他们的感受和贡献，但不要卷入戏剧化拉扯；既承认他们的独特，也帮助他们回到稳定、现实和可完成的一步。', '["九型人格", "浪漫型", "情绪觉察", "关系安全", "创造力", "稳定练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 600, now()),
(100601, '观察型觉察：保留独处，也让自己参与世界', '原书中的观察型喜欢保持距离、收集资讯、独立思考，并珍惜自己的时间、空间和精力。他们的优势是专注、客观、敏感、分析力强，适合研究、判断和创造。但当“保持距离”变成主要保护方式时，人可能退回头脑，远离身体、情绪和关系；为了不被打扰，错过参与、合作和亲密的机会。

App 端可以把观察型内容转化为“安全参与”练习。第一步，尊重独处需要：每天保留一段明确的私人时间，让大脑有空间整理。第二步，给参与设定边界：在参加会议、聚会或亲密谈话前，提前确认时间、主题和退出方式。第三步，练习小剂量表达：不必一次说出全部感受，只需表达一个事实、一个观点或一个需要，例如“我需要想一想，晚点回复你”。

观察型的成长不是强迫自己变外向，而是把知识和观察带回生活现场。原书建议参加适度集体活动、做身体锻炼、敢于体验、不要执着观察。一个可操作方法是每周安排一次“可预测的参与”：提前约好时间、地点、对象和活动内容，结束后记录身体感受和收获。与观察型相处时，少用命令，多用请求；少突然闯入，多提前沟通；少逼他们立即表态，多给思考时间。这样，他们既能保有边界，也能慢慢发现：参与世界并不必然意味着被吞没。', '["九型人格", "观察型", "边界感", "独处需求", "关系参与", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 601, now()),
(100602, '质疑型觉察：把最坏预案变成可验证的问题', '原书中的质疑型擅长发现风险，常会预想最坏结果，对权威、动机和安全条件保持警觉。他们的优势是谨慎、忠诚、可靠、有正义感，能替容易被忽略的人发声；但当风险扫描过度时，怀疑会扩散到关系、工作和自我判断中，导致拖延、反复确认、难以信任，甚至用先发制人的攻击来保护自己。

App 端可以把质疑型内容处理成“怀疑的校准练习”。当你开始担心时，不要立刻压制怀疑，也不要完全相信它。先写下三个栏目：我担心什么；支持这个担心的证据是什么；反证或其他解释是什么。接着把最坏预案转成具体行动：如果担心项目失败，就列出一个可检查的风险清单；如果担心关系不可靠，就约定一次清楚对话；如果担心自己能力不足，就回顾过去成功经验和已有技能。

原书建议质疑型练习信任、肯定成就、向可信朋友核对看法，并通过身体练习把觉察从头脑带回身体。可以设置一个日常提醒：今天我是在准备，还是在被恐惧驱动？准备会让行动更清楚，恐惧会让问题越来越多却不行动。与质疑型相处时，要直接、稳定、言行一致，不要玩心理试探；给他们事实，也给他们时间。被安全地回应后，质疑型的敏锐会从防御转向洞察，怀疑也能变成负责任的判断力。', '["九型人格", "质疑型", "安全感", "焦虑觉察", "信任练习", "风险校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 602, now()),
(100603, '享乐型觉察：不逃开痛苦，才能让快乐更稳', '原书中的享乐型乐观、精力充沛、兴趣广泛，喜欢新的经验、新的人和新的点子。他们能把生活带向轻松和可能性，也能在压力下激发智慧和创造力。但如果一直用快乐、幻想、忙碌和更多选择来避开痛苦，重要问题就会被延后：承诺难以落地，计划容易分散，关系中的痛苦也可能被低估。

App 端可以把享乐型觉察转化为“快乐与痛苦都能承载”的练习。遇到不舒服的事情时，先不急着换话题、找新计划或立刻解决别人问题，而是停下来问：我现在想逃开的是什么？这个痛苦和我有什么真实关系？如果我只做一个小行动，最应该做什么？这种练习不会剥夺快乐，反而让快乐不再依赖逃避。

原书提醒，愉悦只是人生的一部分，痛苦中也有经验。享乐型可以尝试“少选项承诺”：在一周内只推进一到两个重要目标，写清楚下一步、完成时间和验收方式；当新点子出现时，先放入停车场，而不是立刻改变方向。与享乐型相处时，别只批评他们不稳定，可以把建议和真实价值、自由空间连接起来；当他们听见批评后反感，也可以邀请他们晚点回来讨论。成长后的享乐不是没有痛苦，而是能在现实中保留轻盈，同时不再把困难留给未来的自己。', '["九型人格", "享乐型", "逃避模式", "承诺练习", "情绪承载", "成长路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 603, now()),
(100604, '支配型觉察：把力量从控制转向保护与倾听', '原书中的支配型重视力量、正义、公平和自主，不愿被控制，也愿意保护朋友、家人或自己认为有价值的事情。他们行动快、能扛事、敢表达，常在关键时刻成为推动者。但力量如果缺少觉察，就容易变成压迫：说话音量过大、问题过于尖锐、急于证明自己正确、用责备代替沟通，让别人感到被控制或被伤害。

App 端可以把支配型内容转化为“力量使用说明”。在进入争论、会议或亲密冲突前，先问三句：我现在是在保护价值，还是在保护面子？我想推动事实，还是想赢过对方？我有没有给别人足够时间说完？这类问题能把力量从自动攻击转成有意识的影响力。真正有力量的人，不只敢说，也能听；不只敢承担，也能承认自己伤到了别人。

原书建议支配型学习倾听别人的观点、在回应前琢磨、注意嗓门和提问方式、发现伤害后及时道歉、在愤怒中练习放松。可以做一个“强度调节”练习：把当前表达强度从 0 到 10 打分，如果超过 7，就先降到 5，再继续谈事实和请求。与支配型相处时，直接、坦诚、保留尊重很重要；不要用绕弯和操控激起他们的防御。成长后的支配型会把力量用来保护边界、支持弱者和推动问题解决，而不是证明别人必须服从自己。', '["九型人格", "支配型", "力量觉察", "愤怒管理", "倾听", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 604, now()),
(100605, '媒介型觉察：找回优先级，和谐才不等于消失', '原书中的媒介型友善、随和、能理解多方观点，喜欢和平、有组织、可预期的生活。他们能调和冲突，也愿意为团体和朋友付出；但代价是容易“自我遗忘”：不知道自己真正想要什么，把别人的事排在前面，把重要事项拖到最后，或者用沉默、不置可否来表达反感。表面和谐，内在却可能累积委屈和愤怒。

App 端可以把媒介型觉察转化为“我也在场”的练习。每天早晨先写下三件对自己重要的事，并标出第一优先级；遇到别人请求时，不急着答应，先问“这件事会挤掉我今天哪件重要的事”；如果自己沉默了，补一句说明：“我需要一点时间想清楚，不是拒绝你”。这样能把和谐从迎合别人，转成双方都能被看见的合作。

原书提醒，媒介型可以把愤怒当线索：我失去了什么？我真正想保护什么？我是否因为只看别人优点而否定了自己的判断？这并不是鼓励冲突，而是让冲突里的信息被看见。与媒介型相处时，要认真听他们说话，用问题帮助他们集中注意力，给他们慢慢形成真实想法的环境，不要用强势命令催逼。成长后的媒介型仍然温和，但不再让自己消失；仍然维护关系，但也能清楚表达立场、时间表和优先级。', '["九型人格", "媒介型", "自我遗忘", "优先级", "和谐关系", "边界表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 605, now()),
(100606, '完美型觉察：在规则之外练习允许不完美', '原书中的完美型严肃、负责、重视正直和规则，愿意把事情做到正确、得体、可靠。他们能成为很好的组织者，也能用高标准推动自己和团队前进。但当“正确”变成唯一安全感，人就容易陷入自我批判、批评他人、害怕犯错、卡在细节、把世界分成对与错。外在看似坚强，内在可能长期压抑愤怒和不满足。

App 端可以把完美型内容设计成“允许小缺口”的练习。第一步，识别内在的应该清单：我此刻认为自己或别人“必须”怎样？第二步，区分原则和偏好：这真的涉及价值底线，还是只是我习惯的标准？第三步，故意做一个安全范围内的小不完美：比如发出一份足够好的草稿、允许家务晚一点完成、对别人不同做法先询问原因。练习重点不是放弃责任，而是让责任不再被恐惧驱动。

原书建议完美型把愤怒转化为思想，安排游戏和娱乐，承认差异不等于错误，学习赞扬别人，并在规则之外看见真实需要。与完美型相处时，直接、真诚、不要操控；若指出问题，最好说明事实、影响和共同责任，减少羞耻和过度自责。成长后的完美型仍然重视品质，但能把“完美无缺”改成“持续修正”；仍然坚持原则，但也能看见不完美中的生命力和关系空间。', '["九型人格", "完美型", "完美主义", "自我批判", "规则觉察", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 606, now()),
(100607, '九型沟通：按对方的敏感点提供可承受的回应', '原书每一章末尾都提供“如何交往”的建议，适合提炼成 App 端的关系沟通原则：沟通不是只把话说对，而是让对方在能承受的方式里听见。不同类型的敏感点不同：给予型需要真实感谢和直接表达需要；实践型需要清楚目标、价值和节奏提醒；浪漫型需要情绪被承认但不被戏剧化放大；观察型需要时间、空间和提前说明；质疑型需要稳定、透明和言行一致；享乐型需要在自由感中看见承诺的价值；支配型需要直接和尊重；媒介型需要被倾听并被帮助聚焦；完美型需要真诚、事实和柔和反馈。

这套沟通原则不应用来操控别人，而应用来降低误解。比如同样是提出请求，对观察型可以提前说明背景和截止时间；对实践型可以说清结果与好处；对媒介型可以问“你真实想法是什么”；对完美型可以先承认其用心，再讨论可调整的行为。九型视角提醒我们：很多冲突不是恶意，而是双方安全感入口不同。

一个简单的沟通流程是：先判断对方可能在保护什么，再选择表达方式。保护被需要，就给感谢和边界；保护成功，就给明确目标；保护独特，就给理解和现实锚点；保护空间，就给预告和选择；保护安全，就给证据和一致性；保护自由，就给选项和承诺；保护力量，就给尊重和直话；保护和谐，就给耐心和聚焦；保护正确，就给事实和温和修正。这样，九型不再是贴标签工具，而成为关系修复的翻译器。', '["九型人格", "关系沟通", "沟通修复", "敏感点", "同理心", "边界表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 607, now()),
(100608, '九型自测前先看动机：相似行为背后可能是不同需要', '第十章进入人格检测时提醒，外表相似并不代表类型相同，还列出若干相似类型的辨别线索。这一点对 App 端很重要：九型自测不应只问行为，更要问行为背后的动机。同样是努力工作，有人是为了成功和认可，有人是为了正确无误，有人是为了避免不安全；同样是帮助别人，有人是为了连接，有人是为了维持和谐，有人是为了完成目标；同样是保持沉默，有人是在思考，有人是在压抑愤怒，有人是在观察风险。

因此，自测题和内容推荐可以加入三个维度：注意力落点、核心担心、常用保护策略。注意力落点问“我最先看见什么”：关系、目标、意义、资讯、风险、选择、权力、和谐还是规则。核心担心问“我最怕失去什么”：被需要、成功感、独特价值、私人空间、安全感、自由、掌控、连接、正确性。保护策略问“我通常怎么避免不舒服”：讨好、加速、情绪化、退缩、怀疑、转移、控制、顺从或批判。

用户看到多个类型都像自己时，不必急着定型。可以连续一周记录具体情境：事情发生了什么、我第一反应是什么、我真正想保护什么、结果如何。比起一次性得出标签，这种记录更接近九型觉察的目的。类型不是测出来就结束，而是在生活里被反复验证、修正和理解。把动机放在行为之前，能减少误判，也能避免把复杂的人简化成单一标签。', '["九型人格", "人格自测", "动机模式", "注意力焦点", "误判预防", "自我观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 608, now()),
(100609, '把九型当作自我观察地图：从性格惯性回到选择权', '九型人格最适合被当作一张自我观察地图，而不是给自己或别人贴标签的工具。书中用“牢笼与钥匙”的比喻说明：性格像一把反复运作的大锁，我们越不了解它，越容易把习惯反应误认为“这就是我”。学习九型的重点，不是急着证明自己属于哪一型，而是看见自己在压力、关系、选择和情绪中，常常被哪一种惯性带走。

你可以把每一次明显的情绪波动当作入口：我刚才最想保护什么？最怕失去什么？我是不是又在用熟悉的方法解决不安，比如批评、讨好、表现、撤退、怀疑、转移、控制或妥协？当你能在反应发生的一刻多停留几秒，就已经拿回了一部分选择权。

九型觉察不是要求你变成另一个人，而是帮助你不再只剩一种反应。真正的成长，是在看见惯性后，仍然允许自己有新的行动：可以先深呼吸、先核对事实、先表达需要、先暂停争辩，或先承认自己还不确定。这样，九型会从“我是哪一种人”的答案，转化为“我此刻可以怎么更自由地回应”的练习。', '["九型人格", "自我觉察", "性格惯性", "选择权", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 609, now()),
(100610, '性格测试只是入口：用真实反应而非理想自我确认类型', '九型测试可以提供线索，但它不等于最终结论。书中提醒，很多人会用“我希望自己是这样”“我应该这样做”来作答，而不是回到真实生活中“我通常真的怎么反应”。这会让测验结果偏向理想自我或美化自我，而不是看见正在运作的性格惯性。

更稳妥的方式，是把测试结果当成一个假设，然后用日常记录来验证。你可以连续一周观察三个场景：被批评时、被忽略时、计划受阻时。记录自己第一时间的念头、身体反应、想采取的行动，以及事后是否后悔。不要只看外在行为，因为同样是沉默，有人是在压抑愤怒，有人是在保留精力，也有人是在避免冲突；真正需要辨认的是背后的动机和恐惧。

如果某个类型让你特别喜欢或特别反感，也值得多看一眼。强烈的吸引和排斥，常常说明它触碰了你熟悉但不愿承认的部分。确认类型的目的不是自我判决，而是找到最常重复、最容易让你失去弹性的模式。越诚实地回到真实反应，九型越能成为自我理解的起点。', '["九型人格", "人格识别", "自我观察", "测评解释", "核心动机"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 610, now()),
(100611, '九大惯性到九大美德：把“原罪”改写成可练习的人生课题', '书中沿用九型传统里的“原罪/美德”框架，但在 App 端更适合把它改写为“惯性课题/成长态度”。所谓惯性，不是道德定罪，而是人在成长中为了保护自己形成的自动化反应：有人用批评维持正确，有人用服务换取连接，有人用形象证明价值，有人用幻想逃离缺憾，有人用知识获得安全，有人用怀疑预防风险，有人用乐观避开痛苦，有人用征服抵挡脆弱，有人用习惯维持平静。

成长不是压制这些惯性，而是为它们加入新的态度。批评可以练习节制与平静；过度服务可以回到自我需要；追求表现可以练习诚实；沉溺情绪可以练习安住；过度分析可以练习分享与行动；怀疑可以练习信任；追逐快乐可以练习专注；控制可以练习同理；逃避冲突可以练习主动。

你可以在每天结束时问自己：今天我最常戴着哪副“有色眼镜”看世界？它保护了我什么，又让我错过了什么？明天我愿意尝试哪一个小态度？当九型从“我有问题”变成“我有一个可练习的课题”，自我接纳和改变就能同时发生。', '["九型人格", "成长态度", "核心恐惧", "性格惯性", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 611, now()),
(100612, '童年封印的温和看法：看见家族印记，不把成长困境变成责怪', '书中把九型的形成与童年经验、家族印记联系起来。适合 App 端采用的角度是：早年经历会影响一个人如何保护自己，但这不等于要把问题简单归咎于父母或家庭。许多反应最初都是适应策略：有人很早学会负责，有人学会照顾别人，有人学会表现优秀，有人学会退回内心，有人学会保持距离，有人学会寻找支持，有人学会让自己快乐，有人学会强硬自保，有人学会配合大家。小时候这些方式可能帮我们度过困难，长大后却可能变成限制。

做童年觉察时，重点不是追究“谁害我变成这样”，而是温和地问：我当时为了得到安全、爱、认可或平静，学会了什么？这个策略现在还适合我吗？它在哪些关系里仍然自动启动？

一个可操作练习是写下三句话：第一，我小时候最常被期待成为什么样的人；第二，为了符合这个期待，我放弃了哪些感受或需要；第三，今天的我可以怎样重新照顾那个部分。这样处理童年线索，既能尊重真实伤痕，也能避免把自己固定成受害者。理解过去，是为了在现在拥有更多选择。', '["九型人格", "童年经验", "家族印记", "内在小孩", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 612, now()),
(100613, '在关系里及时喊“卡”：识别角色扮演与冲突升级', '关系冲突常常不是单一事件造成的，而是两个人都在无意识地扮演某种角色。书中把这种过程称为“开麦拉的声音响起”：第一型可能进入老师或执法者角色，第二型进入照顾者或好人角色，第三型进入明星或第一名角色，第四型用情绪吸引理解，第五型退到观察者，六型寻找支持和保证，七型负责让气氛快乐，八型表现强势不可欺，九型维持好相处。角色本身不一定错，但当我们过度认同它，就会期待别人配合剧情。

关系里的觉察练习，是在冲突刚出现时喊“卡”。你可以问自己：我现在最想证明什么？我是不是在要求对方按我的剧本回应？如果对方不配合，我的失望、愤怒或退缩来自事件本身，还是来自角色受挫？

下一步不是压抑反应，而是把角色语言换成真实需要。把“你怎么总是不听我的”改成“我担心事情失控，所以很想给建议”；把“我都是为你好”改成“我其实很想被你需要”；把“随便，都可以”改成“我需要一点时间确认自己的想法”。当角色被看见，关系会从互相拉扯，转向更清楚的表达与协商。', '["九型人格", "关系沟通", "角色扮演", "冲突觉察", "表达需要"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 613, now()),
(100614, '第一型觉察练习：把批评冲动转成平静与弹性', '如果你常觉得事情“本来就应该更好”，并且很难忍受错误、混乱或开放式结果，可能需要观察第一型式的惯性。它的核心不是单纯爱挑剔，而是内在有一套很高的标准；当现实不符合标准时，愤怒可能被压抑成严肃、指责、自责或过度负责。长期下来，你会承担很多不属于自己的任务，也容易把“正确”变成关系压力。

成长方向不是放弃原则，而是为原则加入平静和弹性。你可以练习在想纠正别人前先暂停：这件事真的需要我现在指出吗？对方是否请求建议？如果不按我的方式做，最坏会怎样？我是否把自己的焦虑包装成责任感？

一个小练习是“减少一次批评，增加一次好奇”。当别人做法不同，先问一个开放问题：“你当时是怎么考虑的？”再决定是否给建议。对自己也一样：把“我不该犯错”改成“我已经尽力，也可以从错误中学习”。当注意力从不完美转向可理解、可调整、可合作的部分，内心的紧绷会下降，平静不是降低标准，而是让标准服务于生命，而不是支配生命。', '["九型人格", "第一型", "批评觉察", "情绪调节", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 614, now()),
(100615, '第二型觉察练习：把被需要的渴望转成自我照顾', '如果你很容易察觉别人的需要，却不太习惯表达自己的需要，可能需要观察第二型式的惯性。它看起来是热心、体贴、愿意付出，内在却可能藏着“我必须有用，才值得被爱”的焦虑。当付出没有被看见，或对方并不需要你的帮助时，委屈、失落、愤怒就会出现。

成长不是变得冷漠，而是让付出重新成为选择。每次想帮忙前，可以先问三件事：对方明确提出请求了吗？这件事在我的能力范围内吗？我期待对方用感谢、亲近或依赖来回报我吗？如果答案让你不舒服，正好说明你需要回到自己。

第二型的重要练习是“先把自己照顾好”。这不是自私，而是让爱不再以耗竭为代价。你可以每天安排一个只为自己的小行动：休息、表达真实想法、拒绝超出能力的要求、接受别人的帮助，或把注意力从“他需要什么”转向“我现在感觉如何”。当你能承认自己也有需要，就更容易发展真正的谦卑：我可以爱人，也不必用爱来换取存在感。', '["九型人格", "第二型", "自我照顾", "关系边界", "讨好模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 615, now()),
(100616, '第三型觉察练习：把成功表演转成真实价值', '如果你习惯用成果、效率、形象或他人的赞赏来确认价值，可能需要观察第三型式的惯性。它不只是“想赢”，而是把被看见、被肯定和被爱联系在一起。为了维持理想形象，人可能会隐藏真实感受，快速适应环境期待，甚至连自己真正想要什么都变得模糊。

成长的关键是诚实。诚实不是把所有事情摊开给别人看，而是先对自己承认：我正在追求的目标，真的是我的目标吗？如果没有掌声、排名、收入或头衔，这件事还值得我投入吗？我最近一次感到幸福，是因为被认可，还是因为内心确实被滋养？

可以做一个“价值剥离”练习：写下你目前最重要的三个目标，再分别划掉外在评价因素，看看剩下什么。例如“成为第一名”背后也许是想证明自己可靠；“赚更多钱”背后也许是想让家人安心；“保持完美形象”背后也许是害怕失败。看见真实需要后，行动会更有方向。第三型的成长不是不再成功，而是让成功服务于真实价值，而不是用成功遮住空洞感。', '["九型人格", "第三型", "真实自我", "价值澄清", "成就压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 616, now()),
(100617, '第四型觉察练习：在情绪里安住，不用缺憾定义自己', '如果你经常被“我缺少什么”“别人拥有我没有的东西”“没有人真正理解我”牵动，可能需要观察第四型式的惯性。它的敏感和深度很珍贵，但当注意力长期停在缺憾、比较和过去伤口上，情绪会变成定义自我的方式：我现在很痛，所以我就是被遗弃的人；我感到不同，所以我注定无法被理解。

成长不是否定情绪，而是学习不被情绪完全带走。情绪是一时的反应，不是全部的你。你可以练习把一句“我就是这样悲伤的人”改写为“悲伤正在我身上出现，它提醒我有某个需要没有被照顾”。这种表达既承认感受，也保留变化空间。

一个具体练习是“从幻想回到当下”：当你反复回忆、比较或想象理想关系时，立刻观察身边三个真实细节，再做一件小的现实行动，例如整理桌面、回复一条信息、散步十分钟，或直接向对方核对事实。第四型的天赋在于感受力和表达力；当它不再被缺憾绑住，就能把痛苦转化为理解、创作和更真实的连接。', '["九型人格", "第四型", "情绪调节", "缺憾感", "当下练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 617, now()),
(100618, '第五与第六型觉察练习：从过度准备和怀疑回到行动信任', '第五型和第六型都容易把安全感放在“先弄清楚”上，只是方式不同。第五型倾向退回知识、分析和个人空间，担心被外界要求耗尽；第六型倾向不断确认风险、寻找支持和权威意见，担心自己的判断不可靠。两者都可能在准备、推演、询问、质疑中消耗大量心力，真正的行动却被延后。

对第五型式惯性，练习方向是分享和落实：好想法需要进入现实，才会产生力量。可以给自己设定“七成准备就行动”的规则，先发布一个初稿、先表达一个感受、先向一个人求助，而不是等到完全确定。分享不会让你失去自己，反而可能带来更多资源。

对第六型式惯性，练习方向是信任和承担：谨慎有价值，但反复确认会让焦虑扩大。你可以为一个决定设置时限，列出必要信息、可承受风险和下一步行动，然后停止继续搜集意见。事后再复盘，而不是事前无限怀疑。

共同的提醒是：安全感不只来自想清楚，也来自“我经历过、我能调整、我可以求助”。当思考服务于行动，而不是替代行动，内在力量会变得更稳定。', '["九型人格", "第五型", "第六型", "行动力", "安全感", "信任练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 618, now()),
(100619, '第七与第八型觉察练习：从逃避痛苦和强势控制回到专注同理', '第七型和第八型都带有很强的行动能量，但容易用行动避开脆弱。第七型常用新计划、快乐体验、笑声和未来可能性转移痛苦；第八型常用掌控、强硬、先发制人保护自己不被伤害。一个逃向更多选择，一个冲向更强控制，背后都可能是不愿停下来感受空虚、害怕或柔软。

对第七型式惯性，练习方向是专注和节制。你可以在想立刻换项目、找娱乐、热场或逃离无聊时，先停三分钟，问自己：我此刻真正不想感受的是什么？如果我不马上填满空白，会发生什么？选择一件值得深入的事，把它做完，再给自己奖励。快乐不是被禁止，而是从分散刺激转向更有质量的体验。

对第八型式惯性，练习方向是同理和柔软。你可以在想压过别人、证明自己不能被欺负时，先评估言行的杀伤力：我这样做是在保护价值，还是在保护面子？如果我承认软弱，会不会反而让关系更真实？

强大的能量若能与感受连接，就会从逃避和控制，转化为投入、担当、保护和温暖。', '["九型人格", "第七型", "第八型", "情绪调节", "同理心", "专注练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 619, now()),
(100620, '第九型觉察练习：从无所谓的和平回到真实行动', '如果你常说“都可以”“顺其自然”，却在事后感到低落、拖延或被忽视，可能需要观察第九型式的惯性。第九型追求和谐，本身有包容和稳定的力量；但当和谐变成避免表达、避免冲突、避免期待，内在生命力会被压低。看起来没有烦恼，可能只是把烦恼推到一边；看起来很好相处，可能是习惯把自己的需要排在最后。

成长方向是诚实和行动。诚实地问自己：我是真的不在意，还是怕说出来会麻烦别人？我是真的满意，还是已经把期待降到不会失望？我拖着不处理，是因为它不重要，还是因为我害怕面对冲突？

一个小练习是“今天主动一件事”：主动提出一个偏好，主动解决一个拖延的问题，主动为自己的成果署名，主动安排一个只属于自己的计划。行动不需要很大，但要清楚地告诉自己：我的存在、选择和愿望也有分量。真正的和平不是没有冲突，而是问题被看见、需要被表达、关系有空间协商之后，内心仍然安定。', '["九型人格", "第九型", "行动力", "自我表达", "冲突回避"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 620, now()),
(100621, '九型日常练习包：呼吸观察、聚焦提问与柔软书写', '九型觉察需要落到日常练习，否则很容易停留在知道类型、分析类型。书中最后给出几个可迁移到 App 的练习方向：第一，启动内在观察系统。找一个安静位置，把注意力放在呼吸上；念头、画面和情绪出现时，不追着它们发展，也不批判，只是看见它们来去。这个练习能帮助你在情绪高峰前多一点稳定。

第二，聚焦提问。每天至少几次问自己：我现在把心力花在什么事情上？为什么？这是习惯性反应，还是更清醒的选择？不同类型可以观察不同焦点：是非对错、别人的需要、成功形象、缺憾、被打扰、最坏情况、未来机会、控制权或一致性。

第三，分享与支持。选择可信任的人，谈谈自己正在观察的模式，请对方反馈他看到的你。不是让别人判定你的类型，而是借关系增加盲点信息。

第四，柔软书写。当你因为成长不够快而责备自己时，写下批判，再想象朋友遇到同样困难，你会怎样安慰他。把同样的宽容给自己。自我探索不是把自己改造成完美版本，而是在每个反应中，多一次看见、接纳和重新选择。', '["九型人格", "自我觉察", "正念练习", "书写练习", "支持系统", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 621, now()),
(100622, '按类型选择修习方式：用互补练习恢复身心平衡', '身心练习不一定要选择自己最舒服的方式。有时，真正有帮助的练习，正好补足我们平时忽略的部分。书中建议，不同类型在选择成长工具时，可以留意自己的偏好与盲点。过度严谨、负责或焦虑的人，可能不习惯把按摩、休假、放松活动当成成长；但只要能让心安静、舒缓、打开，放松本身就是练习。

过度追求成果、刺激或掌控的人，可能觉得静坐、志愿服务、没有即时回报的付出很没效率；但这些练习能帮助人靠近被封闭的心房，学习不以产出衡量价值。偏向活在内心世界的人，可能更喜欢静态修习，却容易忽略身体；散步、慢跑、瑜伽、伸展或动态活动，可以让精神探索重新接回身体。

App 端可以把这个原则转成“互补处方”：如果你总是用脑，安排一次身体练习；如果你总是行动，安排一次静心停留；如果你总是照顾别人，安排一次自我照顾；如果你总是独处，安排一次安全分享。练习的目的不是追求某种完美方法，而是在熟悉模式之外，给身心一个新的经验。', '["九型人格", "身心练习", "自我调节", "互补练习", "成长工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 622, now()),
(100623, '风险识别：看重复模式、伤害后果与修复能力', '把《犯罪心理分析》的材料迁移到 App 端时，重点不是教用户给身边人贴上“危险人格”标签，而是训练观察长期、重复、跨场景的模式。一次冷漠、一次撒谎、一次失控，不等于一个人不可接近；但如果某人反复忽略他人感受、把所有后果推给别人、被提醒后从不修复，甚至把他人的退让当成可继续越界的许可，就需要提高关系安全等级。App 可引导用户记录三类事实：发生了什么、谁受到了什么影响、对方之后是否承认并改变。风险识别要从猎奇判断转为自我保护：减少单独相处，保留证据，向可信赖的人求助，必要时联系专业机构或现实安全资源。', '["风险识别", "非诊断", "关系安全", "边界感", "心理教育", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 623, now()),
(100624, '习惯性欺骗的红旗：不是测谎，而是记录责任模式', '普通关系里偶尔会有回避、尴尬或善意的隐瞒，App 不应鼓励用户用微表情或猜测去“测谎”。真正值得警惕的是欺骗成为一种稳定策略：说法频繁变化、关键事实无法核对、被指出后立刻转移话题或攻击提问者、承诺很多却没有可验证行动。面对这种模式，用户可以把注意力从“TA 当下有没有骗我”转向“这件事是否影响我的钱、身体、名誉、工作或安全”。边界做法包括：重要事项只接受书面确认；不在压力下做决定；把可核对事实和感受分开记录；当欺骗牵涉财务、胁迫或人身安全时，优先寻求外部支持。', '["风险识别", "边界感", "关系安全", "事实记录", "沟通", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 624, now()),
(100625, '同理处境但不替伤害找借口', '一个人可能经历贫困、创伤、压力、孤独或被排斥，这些处境值得被理解，也可能需要心理与社会支持。但理解原因不等于替伤害开脱，更不意味着受影响的人必须继续承受。App 端可以采用“双轨回应”：一轨承认处境与情绪，例如“你经历的压力是真实的”；另一轨把责任放回行为上，例如“但吼叫、威胁、侵犯边界仍需要停止”。当用户反复问“是不是我不够理解 TA”时，知识库应帮助其检查：对方是否愿意承担后果、是否愿意接受帮助、是否停止伤害。如果答案长期是否定的，同理应转向安全计划、边界表达和求助路径。', '["同理但不纵容", "边界感", "风险沟通", "关系安全", "责任", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 625, now()),
(100626, '青少年同伴风险：看主动靠近、身份需求和退场能力', '青少年确实会受到同伴影响，但材料提醒我们，风险不只在于“坏朋友把孩子带坏”，还要看孩子是否主动靠近危险圈子，用逞强、违抗、羞辱他人来证明自己够酷。App 端可把家长或青少年的提问从“谁害了谁”转成三个观察点：是否为了获得身份感而不断突破规则；是否能在不舒服时退出群体；是否愿意对自己的选择负责。沟通上先避免羞辱式审问，改用具体事实：“你最近三次晚归分别发生了什么？你想从这群人那里得到什么？”边界上要清楚：危险行为不能被浪漫化；家庭、学校和专业支持需要形成一致规则。', '["青少年", "风险识别", "身份认同", "家庭沟通", "边界感", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 626, now()),
(100627, '学校与职场越界：把规则冲突当作早期风险信号', '学校或职场中的风险信号常被解释成“厌学”“不适合这份工作”或“和领导不合”，但 App 端更适合引导用户看模式：是否长期把基本要求视为羞辱，是否只在有利可图时表现合作，是否利用好成绩、好名声或职位掩盖越界，是否把迟到、失约、推责当作理所当然。对普通用户而言，这不是为了诊断别人，而是为了降低现实损失。可以设置更清晰的合作边界：职责写清楚、资源权限分开、重要承诺留痕、发现异常及时升级给家长、主管、人事或学校支持系统。善意帮助需要配合可执行规则，否则容易变成被消耗。', '["职场边界", "学校支持", "风险识别", "规则感", "责任", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 627, now()),
(100628, '信任关系也要验边界：权威、照护与隐私的风险沟通', '材料中一个重要启发是：风险不一定来自“看起来很坏”的人，也可能出现在有声誉、有职位、被家庭或机构信任的人身上。App 端应把这一点转为边界教育，而不是制造恐慌。适用于儿童、来访者、学生、下属和照护关系的原则是：权威越强，边界越要清楚；任何让弱势一方保密、单独承受压力、把特殊关注包装成“只有你懂”的互动，都需要被第三方看见。用户可学习三句话：我需要告诉一个可信的大人；这件事不能只由我们两个人决定；如果你要求我保密，我会暂停互动。对未成年人和依赖关系中的人，求助路径应优先于自行对质。', '["边界感", "权力关系", "未成年人保护", "风险沟通", "关系安全", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 628, now()),
(100629, '积怨型愤怒的降级：先保安全，再谈道理', '有些冲突并不是观点不同，而是对方把很小的挫折理解成羞辱，把不顺从理解成攻击。此时继续解释“我不是那个意思”常常无效，甚至会让局面升级。App 可提供降级步骤：先判断身体安全和退出路线；降低语言刺激，少用反讽、审判和追问；把议题缩小到当前可执行的下一步；必要时明确暂停，“我会在双方冷静后再谈”。同理可以表达对方的失望，但不能接受威胁、摔物、堵门、跟踪或持续辱骂。若愤怒反复以控制、报复或恐吓形式出现，用户应把它视为关系安全问题，而不是单纯的情绪管理问题。', '["冲突降级", "愤怒管理", "关系安全", "边界感", "风险识别", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 629, now()),
(100630, '物质使用后的关系安全：清醒复盘，不用酒药解释伤害', '酒精或药物会放大冲动、降低顾虑、增加危险，但它们不应成为伤害他人的通行证。App 端可以帮助用户把“TA 喝多了才这样”转为更实际的问题：清醒后是否承认影响？是否愿意停止高风险饮酒或用药场景？是否主动寻求成瘾、精神健康或医疗帮助？是否愿意让关系中更弱势的一方拥有退出和求助空间？如果一个人总把越界归因于酒药，却拒绝改变环境和行为，用户需要优先保护自己：避免在对方使用物质后单独沟通，把交通、财务和居住安全安排好，必要时联系亲友、专业服务或紧急资源。', '["物质使用", "风险识别", "关系安全", "边界感", "求助路径", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 630, now()),
(100631, '“我是好人”不等于安全：看具体修复和停止伤害', '一个人偶尔善良、能说出漂亮价值观、或坚称自己“本质不坏”，并不能自动抵消现实中的伤害。App 端可把用户从自我叙事拉回可观察行动：TA 是否能说清自己做了什么，而不是只谈动机？是否承认你的感受和损失，而不是说“又没人受伤”？是否愿意补偿、道歉、接受限制，并持续停止同类行为？如果一个人只用好人形象、宗教/道德语言、过往贡献或偶尔的温柔来要求你继续信任，却没有稳定修复，这不是关系安全的证据。对方可以被理解，但信任需要由行为重新赚回，而不是由自我评价直接获得。', '["关系安全", "修复", "责任", "风险识别", "同理但不纵容", "边界感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 631, now()),
(100632, '精神健康与伤害风险分开看', '心理症状需要照护，伤害风险需要边界，两者不能混在一起。App 不应把精神疾病等同于危险，也不应让用户用诊断标签解释一切；同时，当现实中出现威胁、跟踪、控制、严重自伤他伤表达或拒绝治疗等情况时，也不能只用“TA 只是生病了”来安慰自己。更稳妥的做法是双重评估：一方面鼓励专业评估、治疗和危机支持；另一方面检查具体行为是否让自己或他人处于危险。用户可以准备安全联系人、就医/报警/危机热线等路径，减少单独承担照护压力。对关系中的另一方，关心可以存在，但边界和安全安排也必须存在。', '["心理健康", "风险识别", "危机支持", "边界感", "关系安全", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 632, now()),
(100633, '改变要可验证：从承诺转向长期责任记录', '真正的改变通常不是一句“我以后不会了”，而是长期、具体、可验证的责任记录。App 端可帮助用户把观察标准写清楚：是否停止同类伤害；是否主动避开高风险场景；是否接受外部监督或专业帮助；是否在金钱、时间、工作、亲密关系中表现出稳定责任；是否在被批评时能复盘而非报复。对于正在修复关系的人，信任可以分阶段恢复：小权限、小承诺、小验证，达成后再扩大。对于反复失信的人，用户不需要无限等待“态度变好”，而应根据行为记录调整边界。改变值得鼓励，但关系安全不能建立在没有证据的保证上。', '["行为改变", "责任", "关系修复", "边界感", "风险识别", "长期观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 633, now()),
(100634, '帮助高风险关系中的人：坚定善意，也要有外部支持', '当用户想帮助一个反复越界、强烈愤怒或存在现实风险的人时，App 应避免把“拯救对方”包装成个人使命。材料对专业矫治者的提醒可转化为普通用户原则：善意不等于无条件承受，坚定不等于羞辱对方，耐心不等于没有期限。有效帮助需要清楚规则、稳定支持和外部资源，而不是一个人秘密扛下所有危机。用户可以做三件事：确认自己的安全底线；把支持任务分给亲友、机构、医生、学校或职场系统；在对方拒绝改变且风险升级时，优先退出和求助。共情的边界是：我希望你好，但我不会让自己成为代价。', '["求助路径", "同理但不纵容", "关系安全", "支持系统", "边界感", "风险沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 634, now()),
(100635, '三种人生脚本自查：顺从、隔离与主动创造', '成长并不总是从宏大的目标开始，而是从看见自己正在用哪一种人生脚本生活开始。你可以把当前状态分成三类：第一类是顺从外界标准，努力表现“应该成为的样子”；第二类是因为受伤、失望或不被理解而退到隔离和旁观；第三类是带着真实愿望主动参与生活。练习时，写下你最近一周分别落入这三种模式的时刻，不评判前两种，只问：它们曾经保护了我什么？如果今天选择更主动创造，我愿意先迈出哪一个很小、很具体的行动？', '["英雄之旅", "自我觉察", "人生脚本", "成长练习", "目标行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 635, now()),
(100636, '召唤线索采集：从童年、逆境、作品和终点视角找价值', '所谓“召唤”可以理解为反复触动你的价值线索，而不是神秘指令。可以从四个入口收集：小时候让你敬佩或心动的人；一次艰难经历后你变得更清楚的东西；一本书、一首歌、一部电影或一个作品带来的强烈共鸣；想象生命终点回望时，会让你觉得“这样活过值得”的事。把答案写成关键词，不急着定终身目标，只观察它们共同指向什么价值：自由、创造、照顾、探索、表达、修复关系，或服务他人。', '["价值澄清", "召唤", "自我觉察", "生命方向", "书写练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 636, now()),
(100637, '愿望、批评与支持：把“不可能”的声音摆出来', '当你想做一件重要的事时，内在或外在常会立刻出现“你不行”“不现实”“别人会失望”的声音。这个练习不是消灭批评，而是把它从脑内拉到可观察的位置。先用一句话说出愿望：“我最想创造的是……”。然后写下或用身体姿态表现批评者的声音，承认它确实存在。最后选择一位真实或想象中的支持者，写下他会如何提醒你：你可以小步尝试、可以求助、可以边学边做。这样，愿望、阻力和支持都被看见，行动就不必只靠硬撑。', '["内在批评", "自我支持", "目标行动", "导师资源", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 637, now()),
(100638, '多重视角练习：让创造力从单一身份里松动', '卡住时，人往往只剩一个很窄的身份：“我是失败者”“我是必须负责的人”“我不能犯错”。可以用多重视角松动这种僵硬感。先回到呼吸和身体，再依次想象：四岁孩子会怎样好奇地看这件事？成熟的成年人会怎样负责而不苛责？如果把时间拉长到很久以后，这件事还意味着什么？如果像一棵树或一只动物一样感受身体，它会需要更多扎根、休息还是移动？把这些答案写下来，你会发现问题不只一种解释，行动也不只一种可能。', '["创造性心智", "多重视角", "自我觉察", "正念练习", "认知灵活性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 638, now()),
(100639, '三分钟正念种子：身体静下来、念头安住、关系变宽', '当目标很多、压力很大时，可以先做一个三分钟调节。第一分钟，把“静止”带给身体：放慢动作，感受脚底、背部和呼吸，让肌肉不用继续绷紧。第二分钟，把“寂静”带给念头：不必赶走想法，只把它们放进一个更宽的空间里，允许它们暂时休息。第三分钟，把“宽阔”带给关系和环境：想起你所在的家庭、城市、自然或社群，提醒自己不是孤立完成一切。之后再回到目标，通常会更清楚、更稳。', '["正念练习", "身体觉察", "情绪调节", "高能量状态", "场域连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 639, now()),
(100640, '目标落地三连结：一句意图、一个身体中心、一个支持圈', '把愿望变成行动，可以先建立三个连接。第一，用五个词以内说清正向意图，例如“稳定复习”“修复沟通”“照顾身体”。第二，找到身体中心：心口、腹部、脚底或其他让你感到稳的位置，压力来时先回到这里。第三，列出支持圈：能帮你的人、地点、习惯、工具、自然环境或榜样。然后选择一个今天能做的动作，把意图像种子一样带到现实中。这个练习能把抽象愿望变成有身体感、有资源、有下一步的计划。', '["目标行动", "资源连接", "身体中心", "高能量状态", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 640, now()),
(100641, '温柔、坚定、轻松：沟通前的三种状态调频', '重要沟通前，可以检查自己是否同时拥有三种状态。温柔，是先对自己和对方保持基本善意，让紧张气氛变软；坚定，是记得自己的边界、目标和承诺，不把讨好当成和平；轻松，是保留一点幽默、弹性和好奇，不让沟通变成审判。练习时，分别想象一位代表温柔、坚定、轻松的人，借用他们的姿态说出同一句话：“我想表达的是……”。最后把三种状态合在一起，再进入真实沟通。', '["沟通状态", "情绪调节", "边界表达", "关系成长", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 641, now()),
(100642, '遇到阻碍时先回到中心：非对抗式应对流程', '阻碍出现时，第一反应常是硬冲、逃开或自责。更有效的流程是：先暂停，回到呼吸、脚底和身体中心；再承认阻碍存在，给它一个具体名字，比如“害怕被否定”“资源不足”“对方不支持”；接着分别尝试三种回应：用温柔照顾自己的脆弱，用坚定守住边界和下一步，用轻松寻找新的角度或替代路径。这个练习把“对抗问题”改成“与问题合作”，让阻碍成为调整策略的信息。', '["障碍应对", "目标行动", "情绪调节", "非对抗", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 642, now()),
(100643, '问题行为背后的正向需求：用身体动作读懂卡点', '反复出现的问题行为，常常不是单纯“坏习惯”，而是某个需求用了不合适的方式表达。练习时，选一个卡点，例如拖延、焦虑性检查、逃避沟通或冲动消费。不要立刻分析对错，先用一个简单身体动作表现它，放慢三到五倍，带着好奇重复几次。然后问自己：这个动作想保护我什么？它在寻找安全、休息、被看见、掌控感、温暖还是自由？最后写出三种更健康的满足方式。这样，改变不是压制自己，而是重新照顾真实需求。', '["问题行为", "正向需求", "身体觉察", "自我接纳", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 643, now()),
(100644, '目标与拖延的双人舞：把内在冲突整合成行动节奏', '目标和阻力不一定是敌人。比如一部分你想高效完成项目，另一部分却拖延、疲惫或想逃。可以把两边都当成需要被听见的部分：先用身体动作表现“我想达成目标”的一面，再表现“我卡住了”的一面。用缓慢、连续的动作在两边之间来回转换，观察它们各自带来的信息：一边可能需要专注和承诺，另一边可能需要休息、弹性或降低压力。最后设计一个节奏：专注一段、放松一段、再回来。整合比自责更能带来持续行动。', '["目标障碍", "拖延", "内在冲突", "行动节奏", "自我整合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 644, now()),
(100645, '把获得的支持传出去：帮助别人前先稳定自己', '成长到后面，不只是“我如何变好”，也包括“我如何把有用的支持传给别人”。但帮助不是拯救、控制或替别人解决人生。练习时，先让自己回到稳定和善意，感受心里仍有一盏灯；再想起家人、朋友、同事，甚至与你关系紧张的人，问：我能用什么方式支持他的自主性？也许只是认真倾听、分享一个练习、表达感谢、看见对方的努力，或在边界内提供资源。真正的传递，是让别人也更相信自己有力量。', '["连接", "助人边界", "关系成长", "社群支持", "高能量状态"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 645, now()),
(100646, '每日英雄之旅复盘：从触动到贡献的六个提问', '每天结束前，可以用六个问题做成长复盘：今天什么触动了我，提醒我真正重视什么？我在哪里回避、麻木或被“不可能”的声音挡住了？我得到或需要什么支持？今天最大的阻碍在提醒我哪个需求或边界？我是否用到了温柔、坚定和轻松中的某一种，下一次还可以补上哪一种？我能把今天获得的一点理解、善意或资源传给谁？这不是考试，而是把普通一天看成一次小型练习，逐步形成更清醒、更有连接感的生活方式。', '["成长复盘", "英雄之旅", "自我觉察", "目标障碍", "连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 646, now()),
(100647, '风险不是单一标签：要看累积因素和保护资源', '一个人的危险或失控风险，通常不是由某个单一特质决定的。更值得关注的是风险是否在叠加：长期暴露在暴力中、物质滥用、冲动控制困难、反复威胁、孤立无援、缺少稳定照护等。App 端可以引导用户把“他是不是坏人”改成“有哪些风险正在叠加、有哪些保护资源可以增加”。当风险涉及现实伤害、明确威胁或无法自控时，应尽快联系可信亲友、专业人员或当地紧急支持。', '["犯罪心理", "风险识别", "心理教育", "保护性因素", "非标签化", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 647, now()),
(100648, '保护性因素能改变轨迹：稳定连接会让风险转向', '风险识别不是为了给人定罪，而是为了尽早增加保护性因素。支持性的养育者、可信任的老师、健康同伴、清楚规则、规律生活、专业服务和社区资源，都可能让原本滚雪球式发展的困境停下来。对于青少年或家庭冲突，App 可以提示用户先补足支持网络：找一个稳定成年人、联系学校心理老师、建立家庭会议或求助计划，而不是只靠惩罚、羞辱或单次谈话解决问题。', '["保护性因素", "心理弹性", "家庭支持", "青少年心理", "预防干预", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 648, now()),
(100649, '被同伴排斥的孩子需要技能支持，而不是“坏孩子”标签', '同伴拒绝、冲动、注意力困难、易怒和社交技能不足常会互相放大。孩子越被排斥，越可能失去练习合作、表达和修复关系的机会，也更容易靠近问题同伴。对家长和老师来说，重点不是把孩子贴成“危险人物”，而是帮助他学会停下来、说清需求、识别情绪、练习加入同伴活动，并在学校和家庭之间建立一致支持。若出现持续攻击、虐待动物、严重威胁或伤人行为，应及时请专业人员介入。', '["青少年心理", "同伴关系", "风险识别", "社交技能", "情绪调节", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 649, now()),
(100650, '道德脱离的红旗：把伤害说成玩笑、规矩或对方活该', '当一个人持续把伤害合理化，关系安全就需要被重新评估。常见信号包括：把侮辱说成“开玩笑”，把控制说成“为你好”，把群体规则当作伤害理由，或把受害者说成“活该”。这些说法会让人暂时摆脱内疚，也让旁观者更难阻止伤害。App 端可引导用户回到三件事：发生了什么具体行为、造成了什么影响、责任应由谁承担。如果对方拒绝承认影响并继续升级，优先拉开距离并扩大支持。', '["犯罪心理", "道德脱离", "关系安全", "责任边界", "风险识别", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 650, now()),
(100651, '旁观者不等于冷漠：把求助变成具体动作', '危急场景里，人们不帮忙有时不是没有善意，而是不确定发生了什么、害怕判断错、以为别人会处理。降低旁观者效应的办法，是把责任具体化：点名请某个人报警，请某个人联系保安或家属，请某个人陪在安全距离外记录时间地点。普通用户不需要冒险冲进危险现场，但可以在保护自己的前提下发出清楚求助、保留事实信息，并把“有人会管”改成“我能完成一个安全动作”。', '["旁观者效应", "求助路径", "危机沟通", "风险识别", "关系安全", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 651, now()),
(100652, '亲密伴侣暴力不只看伤痕：强制控制也是危险信号', '亲密伴侣暴力包括身体、心理和性方面的伤害，也包括持续控制。需要警惕的不是单次吵架，而是模式：限制社交、检查手机、控制钱和出行、反复贬低、威胁伤害自己或他人、用宠物或孩子施压、把暴力归咎于“你惹我”。如果你正在经历这类关系，先不要独自摊牌或激烈对抗，优先把证件、资金、住处、可信联系人和求助电话整理成安全计划，并寻求专业或当地保护资源。', '["亲密伴侣暴力", "强制控制", "关系安全", "安全计划", "边界感", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 652, now()),
(100653, '家庭安全要看风险网：伴侣、孩子和宠物可能同时受伤', '家庭暴力常常不是孤立事件。伴侣暴力、儿童虐待、兄弟姐妹攻击、忽视、情感贬低和威胁伤害宠物，可能出现在同一个家庭系统里。对普通用户来说，重要的是不要只问“有没有打人”，还要问：家里是否有人经常害怕、被隔离、被剥夺资源、被迫保守秘密，孩子或宠物是否被用来威胁。若答案反复为是，应把它视为家庭安全问题，而不是单纯家务矛盾，并联系可信亲友、学校、社区或专业机构。', '["家庭暴力", "儿童保护", "多重被害", "关系安全", "风险识别", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 653, now()),
(100654, '分手后的持续纠缠要按安全事件处理', '分手后仍反复出现的跟踪、堵门、连续电话短信、监视社交账号、威胁、毁坏财物、散布隐私或骚扰亲友，不是“太爱了”，而是需要认真处理的安全信号。尤其当对方曾有控制、暴力、威胁或破坏行为时，不建议单独见面谈清楚。更安全的做法是：保存记录，告知可信亲友和单位/学校，调整隐私设置，避免单独行动，并咨询法律、心理或当地保护资源。恐惧本身就是需要被看见的风险信息。', '["跟踪骚扰", "分手安全", "关系安全", "风险识别", "边界感", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 654, now()),
(100655, '性边界安全：亲密关系里也需要明确同意', '性安全的核心不是猜测对方“应该愿意”，而是尊重清楚、持续、可撤回的同意。恋爱、婚姻、暧昧、穿着、喝酒、沉默或僵住，都不能自动代表同意。若有人把“不”解释成“欲拒还迎”，把对方友好当作性暗示，或用关系身份要求配合，就已经越过边界。App 端可以提醒用户：不确定时就停下并询问；被胁迫后不要自责，优先获得医疗、心理、法律和可信支持。', '["性边界", "关系安全", "同意教育", "风险识别", "求助路径", "去责备"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 655, now()),
(100656, '儿童披露伤害常会很晚：先保护，再温和求助', '儿童或青少年遭遇性伤害后，可能很久都说不出口，也可能表现为退缩、孤独、情绪低落、噩梦、害怕特定人物或场景。延迟表达不等于事情不严重，更不等于孩子在撒谎。照护者最需要做的是保持平静、相信孩子的感受、避免追问细节和责备，先确认当前是否安全，再联系专业人员、儿童保护资源或医疗支持。对孩子来说，被稳定的大人接住，往往是复原的第一步。', '["儿童保护", "性侵创伤", "创伤支持", "求助路径", "家庭安全", "去责备"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 656, now()),
(100657, '网络关系里的未成年人保护：快亲近、保密和线下邀约都要放慢', '网络风险常从“特别懂你”“不要告诉别人”“发张照片证明信任”“我们线下见一面”这类快速亲近开始。未成年人需要被反复告知：任何要求保密、转移平台、索要私密照片、给出过度承诺或让你离开可信大人的关系，都应暂停并告诉现实中的安全成年人。家长的重点不是羞辱孩子“怎么会上当”，而是建立可求助的氛围：孩子一旦觉得不对，可以截图、拉黑、退出，并立刻来找你。', '["网络安全", "未成年人保护", "关系安全", "边界感", "风险识别", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 657, now()),
(100658, '老人照护风险识别：经济剥夺、忽视和沉默都需要被看见', '老人受虐并不只表现为明显伤痕，也可能是钱被擅自使用、药物和医疗被忽视、基本生活需要得不到照顾、被威胁或被长期羞辱。认知下降、行动不便、依赖照护者和社会隔离，都会让求助更困难。App 端可提示家属或助人者私下询问“你在家里安全吗”，同时观察账户异常、身体照护、情绪变化和照护者压力。若怀疑受虐，应联系社区、医疗、法律或成人保护服务，而不是只劝老人忍耐。', '["老人保护", "照护关系", "经济剥夺", "忽视", "风险识别", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 658, now()),
(100659, '高唤起冲突降级：先降刺激、拉长时间，再谈决定', '人在高度唤起、被围观、被催促或觉得完全失控时，更容易做出冲动反应。普通关系冲突中，降级的第一步不是讲道理，而是降低刺激：减少围观和噪音，放慢语速，保持安全距离，不当场逼迫承诺，给彼此一个可返回的暂停时间。若对方出现明确威胁、武器、堵门、限制离开或失控迹象，不要把它当作沟通技巧问题，应优先离开现场并联系紧急支持。安全永远先于说服。', '["冲突降级", "情绪调节", "关系安全", "危机沟通", "边界感", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 659, now()),
(100660, '酒精和药物不是借口：把聚会冲突先当安全问题管理', '酒精和药物与暴力、冲突之间的关系很复杂，不能简单说“喝了才这样”，也不能用“喝多了”替伤害开脱。更实用的做法是把它当作安全变量：聚会前约定回家方式，避免在对方醉酒或用药后继续争辩，不坐失控者驾驶的车，发现威胁或性边界模糊时及时离开并找清醒同伴。若物质使用反复导致关系伤害、失控或违法风险，应把成瘾支持、心理咨询和安全计划一起纳入。', '["药物滥用", "酒精风险", "关系安全", "风险识别", "冲突降级", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 660, now()),
(100661, '从愿望到行动：先找到自己能干涉的一小块', '人可以有偏好、希望和抱怨，但真正改变处境的是对“可干涉之处”的选择。把一个愿望转成行动时，先不要急着证明自己够不够好，而是问三个问题：我想让哪种不满意稍微减少？我现在能影响哪一小块？我准备采用什么手段？如果选择暂时不做，也不是空白，而是在让现状继续产生后果。用于成长练习时，这一条可以帮助用户把“我想改变”改写成“我下一步要做什么、放下什么、承担什么”。', '["行动选择", "目标手段", "责任边界", "自我觉察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 661, now()),
(100662, '冲动也是选择现场：把感受、代价和后果一起看见', '强烈情绪会让眼前目标显得特别重要，也会让需要付出的代价变得不明显。但冲动不是命令，人仍然可以在感受、欲望、后果之间重新排序。App 端可以把这条转化为一个暂停练习：先承认“我很想立刻这样做”，再写下“我会得到什么、可能失去什么、有没有更小的替代动作”。这不是压抑情绪，而是把情绪从自动反应带回有意识选择，让用户在愤怒、渴望、拖延或逃避中多出一点主动空间。', '["情绪觉察", "行动选择", "冲动管理", "责任边界", "目标手段"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 662, now()),
(100663, '目标和手段分开看：方法失效不等于人失败', '很多自责来自把“方法没用”误读成“我这个人不行”。更清晰的做法是把目标、手段和结果拆开：一个人可以真诚地想变好，却用了不合适的方法；方法错了，需要修正路径，不必立刻否定自己的价值。面对关系、学习、工作或习惯改变时，可以先问：我真正想达到的状态是什么？现在的方法是否真的通向它？有没有成本更低、反馈更快的新方法？这样能把羞耻感转成实验心态，把失败从身份判决改写成策略信息。', '["目标手段", "行动复盘", "认知成长", "自我责任", "策略调整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 663, now()),
(100664, '在不确定中行动：用估计、试探和调整替代确定性幻想', '人的行动总是面向未来，而未来的需求、环境反应和他人选择无法被完全预言。成熟的决策不是等到百分百确定再开始，而是在信息有限时做可承受的估计，并为修正留下空间。对用户来说，不确定性不是“我不该行动”的理由，而是提醒自己降低赌注、设定观察点、准备备选方案。把选择看成一次小规模试探，可以减少完美主义和灾难化想象：先做能验证现实的一步，再根据反馈调整下一步。', '["不确定性", "行动选择", "决策练习", "心理弹性", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 664, now()),
(100665, '选择就是排序：看见得到背后的放弃', '每一次选择都在表达一个当下的优先级：选择某件事，也意味着暂时放弃另一种满足。把这一点看清楚，有助于减少“我什么都想要”的内耗。做决定时，与其追问哪个选项绝对正确，不如写下：这个选择服务什么价值？我要付出的时间、注意力、关系或机会是什么？我是否愿意承担这份代价？当用户把选择理解为排序，而不是对自己一生的最终裁判，就更容易在现实限制中做出负责而不僵硬的决定。', '["价值判断", "行动选择", "目标手段", "取舍", "责任边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 665, now()),
(100666, '社会协作的边界：合作由具体个人行动连接，不替任何人活', '人在关系和社会中成长，但“社会”“团队”“家庭”并不是一个能替个人行动的巨人。合作来自许多个体为了各自目标而形成的相互配合，也需要清楚的角色、交换、承诺和边界。迁移到 App 端，可以提醒用户：不要把所有问题都归咎于自己，也不要把所有责任推给关系或环境；先分清我能做的、对方要做的、规则能提供的支持，以及这段合作是否仍然让彼此受益。健康协作不是吞没个人，而是让个人在连接中拥有更好的行动条件。', '["社会协作", "责任边界", "关系觉察", "行动选择", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 666, now()),
(100667, '取悦模式自检：从自动答应、怕冲突和求认可开始观察', '如果你常在别人提出请求时立刻答应、把自己的需求排到最后、害怕对方失望或生气，可以先把它看成一种旧有应对模式，而不是人格缺陷。记录最近三次“我其实不想但还是答应”的情境：对方是谁、我担心失去什么、身体有什么反应、事后是否疲惫或怨恨。看见模式的目的不是责备自己，而是把自动反应变成可选择的反应。', '["取悦症", "自我觉察", "讨好模式", "关系模式", "非诊断", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 667, now()),
(100668, '把苛刻的“应该”改写成有选择的偏好', '讨好模式里常有很多内在命令：我应该让每个人满意、我不能让人失望、我必须永远友善。可以把它们改写成更柔软的句子：我希望关系顺利，但我也可以评估自己的时间和精力；我愿意帮助重要的人，但不是所有请求都必须由我承担。每次把“必须”换成“我可以选择”，内疚感会少一点，边界感会清楚一点。', '["取悦症", "认知重构", "边界感", "内疚调节", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 668, now()),
(100669, '想拒绝时先暂停答复：给自己争取选择时间', '很多人不是不会拒绝，而是太快进入自动答应。面对邀请、加班、人情或求助，先练习一句缓冲语：“我需要看一下安排，稍后答复你。”这不是拖延责任，而是在把选择权拿回来。等情绪降下来，再分别写下答应、拒绝和折中的代价，尤其要看它会怎样影响你的睡眠、精力、财务和心情。真正的边界，往往从不立刻说“行”开始。', '["拒绝练习", "边界感", "选择权", "时间管理", "讨好模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 669, now()),
(100670, '温和说不：少解释、说清限制、保留尊重', '拒绝不需要写一篇辩护书。一个清楚的“不”可以同时包含尊重和边界：先确认对方的邀请或信任，再说明这次不能答应，最后给出简短祝福或可承受的替代。过多解释容易让对话变成谈判，也会让你再次被内疚推着答应。练习让语气友善、句子简短、立场稳定：我理解这件事重要，但这次我不能接。', '["拒绝练习", "边界表达", "关系沟通", "温和坚定", "内疚调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 670, now()),
(100671, '折中方案要由你决定，而不是被压力推出来', '折中不是“换一种方式继续讨好”。只有当你确实愿意参与、只是需要改变时间、强度或范围时，才提出折中方案。例如：我不能帮一整天，但可以上午来一个小时；如果这样不合适，这次我就不能帮了。折中的重点是保留你的条件，而不是进入来回讨价还价。对方可以失望，但失望不等于你必须让步。', '["折中方案", "拒绝练习", "边界感", "关系协商", "温和坚定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 671, now()),
(100672, '内疚感调节：分清真实伤害和未满足期待', '说“不”后冒出的内疚，不一定说明你做错了。可以先问自己两个问题：我是否真的伤害了对方，还是只是没有满足对方期待？我是否愿意为这个选择承担合理后果，而不是承担对方所有情绪？如果只是拒绝了一个超出能力的请求，可以用自我支持代替自责：我可以关心对方，也可以保护自己的时间和身体。', '["内疚调节", "拒绝练习", "自我支持", "边界感", "去羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 672, now()),
(100673, '认可需求降级：不是每个人喜欢你，你才有价值', '希望被喜欢很正常，但把所有人的认可当成自我价值证明，会让人一直处在讨好和防御里。可以试着把“他不喜欢我，所以我不好”改成“我希望被理解，但我不需要每个人都认可我”。每天记录一件自己认可自己的具体行为，例如守住休息时间、表达真实偏好、没有立刻答应。自我价值需要来自稳定的自我尊重，而不是不断换取掌声。', '["认可瘾", "自我价值", "取悦症", "自我认可", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 673, now()),
(100674, '照顾自己不是自私：先把需求放回关系里', '长期把别人放在第一位的人，常会忘记自己也有需求。可以从很小的自我照顾开始：每天安排两件让自己恢复能量的事，哪怕只是散步、安静吃饭、早睡半小时。自我照顾不是从关系中退出，而是让你有余力用更稳定的方式爱人。一个总是耗尽的人，迟早会在关系里积累委屈；照顾自己是预防委屈的边界。', '["自我照顾", "边界感", "需求表达", "关系内耗", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 674, now()),
(100675, '别替所有人解决问题：支持可以不接管', '当朋友或家人带着难题来找你，你可以倾听、共情、一起梳理，但不必立刻把问题扛到自己身上。可以说：“我能理解这很难，我相信你会找到办法；我现在不能替你处理。”如果需要考虑是否帮忙，也可以先约定一个答复时间。健康的帮助是和对方一起解决，而不是代替对方解决；把责任还给对方，也是在尊重对方的能力。', '["助人边界", "关系沟通", "责任边界", "拒绝练习", "共情"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 675, now()),
(100676, '冲突不是关系失败：把分歧当作需要被看见的信息', '讨好者常把冲突理解成危险信号，于是用沉默、让步或道歉来压下分歧。但未表达的冲突不会消失，可能会变成冷淡、怨气或突然爆发。更有建设性的做法是先降低语气和节奏，再说事实、感受和请求：刚才那句话让我有压力，我需要我们暂停一下，晚点再谈。关系修复不是没有冲突，而是能在冲突后重新建立理解和规则。', '["冲突处理", "关系修复", "边界感", "需求表达", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 676, now()),
(100677, '愤怒也能温和使用：先量化，再表达边界', '害怕愤怒的人，容易在低强度不满时压抑，等到承受不了才爆发。可以给愤怒做一个0到10的刻度：2分是不舒服，5分是明显生气，8分需要暂停。每次察觉身体变紧、声音变急、想立刻反击时，先给情绪打分，再选择行动。愤怒的功能是提醒边界和需求，不一定要变成攻击；越早识别，越容易温和表达。', '["愤怒管理", "边界表达", "情绪调节", "身体觉察", "冲突处理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 677, now()),
(100678, '边界实验日志：用现实结果更新灾难预测', '在拒绝、请求帮助或表达不满之前，先写下你的预测：我担心对方会怎样反应？然后真的做一次低风险边界练习，并记录实际发生了什么。很多时候，对方可能只是失望、调整安排，甚至愿意理解。用事实反复检验“我一拒绝就会被讨厌”的旧假设，可以给自己积累新证据。边界不是一次完成的勇敢，而是一系列可复盘的小实验。', '["边界练习", "行为实验", "拒绝练习", "自我觉察", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 678, now()),
(100679, '拒绝后的关系修复：承认失望，不补偿到失去边界', '当你拒绝后对方失望，可以先承认影响：我知道你原本很希望我帮忙，这让你有压力。然后稳住边界：但这次我确实不能接。修复关系不等于撤回拒绝，也不是用额外付出来赎罪。真正的修复是让对方知道你仍重视关系，同时让新的相处规则变得可预期。你可以理解对方失望，也可以不为对方的全部情绪负责。', '["关系修复", "拒绝练习", "边界感", "内疚调节", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 679, now()),
(100680, '表达需求不是麻烦别人：把请求说得具体又可拒绝', '取悦模式会让人把求助看成打扰，于是自己越扛越累。练习需求表达时，先说具体情境和影响，再提出一个小而清楚的请求：我这周连续加班，今晚需要你负责洗碗；如果不方便，我们一起换个时间。具体请求让别人知道怎样支持你，也保留对方协商空间。你不是在命令别人照顾你，而是在把真实的自己带进关系。', '["需求表达", "请求练习", "边界感", "关系沟通", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 680, now()),
(100681, '性格陷阱识别：看见反复出现的旧剧本', '有些困扰不是单个事件，而是同一个主题在不同关系、工作和情绪里反复上演。识别性格陷阱可以看三个线索：它从很早以前就开始出现；它让你明明想要爱、自由、成就或安全，却反复走向相反结果；它会用熟悉感让自己延续下去。App 可引导用户记录：这件事像不像旧经历？我最强烈的感受是什么？我自动选择了谁、回避了什么、又重复了哪个结局？这样能把“我就是这样”转成“我正在被某个旧模式触发”。', '["性格陷阱", "图式模式", "童年影响", "自我觉察", "关系重复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 681, now()),
(100682, '三种保护性应对：顺着旧模式、躲开触发、反向证明', '早年的痛点被触发时，人常会进入三种保护方式。第一种是顺着旧模式：像真的不值得被爱、一定会失败、必须讨好那样行动。第二种是躲开触发：不靠近、不尝试、不谈感受，用忙碌、麻木或回避换短期安全。第三种是反向证明：用强势、完美、优越或控制掩盖脆弱。它们都曾有保护意义，但如果长期自动运行，就会限制亲密、成长和真实表达。练习提问：我现在是在屈从、逃避，还是反击？这个反应保护了什么，又让我失去了什么？', '["图式模式", "保护性应对", "自我觉察", "逃避模式", "关系重复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 682, now()),
(100683, '修复旧模式的七步流程：命名、回看、证据卡和行为实验', '改变旧模式通常不是一次顿悟，而是一套反复练习。可以先给模式命名，理解它来自哪些早年需要未被满足；再用安全的方式回看童年感受，分清当年的事实与今天的现实；接着写出支持和反对旧信念的证据，把新的提醒做成卡片；再列出自己如何强化陷阱，并选两三个最容易的行为做替代实验。练习要从小处开始，例如少一次追问、表达一个偏好、完成一个独立任务。每次复盘都问：我今天有没有用新行动给旧信念一个反例？', '["修复练习", "行为实验", "童年影响", "自我觉察", "图式模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 683, now()),
(100684, '遗弃感触发时：把正常距离和真正离开分开', '遗弃陷阱常把伴侣没回复、朋友临时取消、对方需要独处等普通距离，快速解释成“他不要我了”。触发后可能出现黏住、追问、指责、嫉妒、先离开或只选择忽冷忽热的人。练习时先给反应命名：“这是遗弃感被激活，不等于事实已经发生。”再记录客观证据：对方过去是否稳定？这次分离有其他解释吗？我能不能先等二十分钟再行动？替代行动包括照顾自己的生活、联系稳定朋友、做一件独处时也能完成的事。择偶上要警惕让你像坐过山车的人，也给可靠关系一点适应时间。', '["遗弃陷阱", "关系重复", "触发器", "自我安抚", "行动替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 684, now()),
(100685, '不信任保护墙：守住边界，也练习可验证的信任', '经历过伤害的人，容易把世界看成随时会被欺骗、羞辱、利用或控制的地方。高墙能保护你，但也可能让值得信任的人永远进不来。App 可把练习分成两层：第一层是安全边界，任何持续贬低、操控、胁迫或伤害都需要停止容忍，并寻求可信支持；第二层是可验证的信任，对没有伤害证据的人，分别写下“值得信任”和“不值得信任”的证据，从很小的开放开始练习。重点不是强迫自己天真，而是把旧危险和当前关系分开：哪些是真实红旗，哪些是旧伤在扫描威胁？', '["不信任", "童年创伤", "边界", "关系安全", "修复练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 685, now()),
(100686, '情感剥夺：把“没人懂我”拆成照顾、共情和引导', '情感剥夺感常表现为“没有人真正关心我、理解我、支持我”，也可能表现为总被冷淡的人吸引，或自己也变得冷淡。可把模糊的缺爱拆成三类需要：照顾，例如温暖、陪伴、身体或情绪安慰；共情，例如有人认真理解你的感受；引导，例如在迷茫时得到支持和方向。练习时记录最近一次失落：我缺的是哪一种？我有没有清楚说出来，还是等对方猜？如果遇到愿意回应的人，尝试表达脆弱和具体请求；如果遇到长期冷漠的人，减少用愤怒和苛求换关注，重新评估这段关系是否真的能滋养你。', '["情感剥夺", "情绪需求", "亲密关系", "修复练习", "关系重复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 686, now()),
(100687, '社交孤立：从“我是异类”到小剂量参与', '社交孤立陷阱会让人在群体里像局外人，觉得自己无趣、笨拙、低人一等或一定会被排斥。它最常用逃避维持自己：不参加聚会、不主动说话、人在场但心里退回去，结果得不到新的社交证据。练习可以从“社交阶梯”开始：列出回避的场景，按难度从低到高排序，先做最容易的一项，例如和同事短聊、向店员提问、参加小范围活动。进入场景前准备一个开场话题，给自己设定可完成目标，如主动和两个人说话。也要区分可改善的社交技能和无需羞耻的个人差异，练习在融入和保留自己之间找到平衡。', '["社交孤立", "暴露练习", "自我接纳", "社交焦虑", "行动替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 687, now()),
(100688, '依赖陷阱：把“我做不到”训练成逐级独立', '依赖陷阱会让人觉得没有别人帮忙就无法做决定、处理任务或面对世界。改变的方向不是突然变得无所不能，而是系统训练胜任感。先列出日常依赖清单：哪些决定总让别人替你做？哪些任务一焦虑就求助？再列出一直回避的挑战，按难度排序，从最简单的开始独立完成。行动前可以做准备和预案，但先不要立刻寻求确认；只有认真尝试后仍卡住，才请求具体帮助。完成小任务后要承认进步，不用“别人早就会”来贬低自己。关系里也要警惕强烈吸引你的过度保护者，给平等、鼓励你长大的关系一次机会。', '["依赖陷阱", "自主性", "能力训练", "亲密关系", "行动替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 688, now()),
(100689, '脆弱陷阱：给灾难想象做概率校准', '脆弱陷阱让人长期感觉灾难快要发生：生病、失控、破产、遇害或其他最坏结果。它会用反复确认、过度防范、逃避和仪式化行为维持焦虑。练习可从一张恐惧清单开始：我害怕什么？我怎样过度保护自己？家人怎样配合了我的害怕？随后给每个场景标出焦虑值，拆成由易到难的小步骤。关键是做概率校准：我感觉危险有多大？更客观的资料或可信他人会怎样估计？再用呼吸放松、提醒卡和安全意象帮助自己停留在场景里，最后在现实中从低难度步骤开始练习。目标是扩大生活，而不是让自己完全没有害怕。', '["脆弱陷阱", "灾难化", "焦虑调节", "概率校准", "暴露练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 689, now()),
(100690, '自我缺陷感：把羞耻声音还给旧经历', '自我缺陷感常像一个内化的批评声音：我不够好、别人了解我就会离开、我不配被爱。它可能让人隐藏真实自我、追求难以得到的人、容忍贬低，或反过来用挑剔、优越和成功面具保护自己。练习时先辨认这是谁的声音：父母、同伴、旧伴侣，还是长期被羞辱后的自动结论？可以写一封不必寄出的信，把当年受伤、愤怒和本应得到的尊重说清楚。再写一张自我提醒卡，列出真实优点和支持证据。亲密关系里，按安全节奏分享真实感受，练习接受赞美和照顾；同时停止容忍持续贬低，也停止把自己的羞耻感转嫁给伴侣或孩子。', '["自我缺陷", "羞耻修复", "内在批评", "亲密关系", "童年影响"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 690, now()),
(100691, '失败陷阱：把能力缺口和整个人价值分开', '失败陷阱会把“我在某个领域落后、缺技能或曾经失败”扩大成“我整个人就是失败者”。有时失败感与事实不符，只是旧评价在过滤现实；有时确实因为长期逃避、缺少支持或方向不合适，能力没有发展起来。第一步是客观评估：和同阶段的人相比，我在哪些方面真实落后，哪些成就被我低估了？第二步是找出模式：我是否拖延、回避晋升、选择不适合的领域，或把成功寄托在伴侣身上？第三步是行动计划：回到自己的天赋和兴趣，补基础技能，把目标拆成小阶梯。每完成一步，都把证据写进卡片里，让“我能进步”逐渐替代“我注定失败”。', '["失败陷阱", "自我效能", "能力训练", "行动计划", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 691, now()),
(100692, '屈从陷阱：从隐忍和怨气回到清楚表达', '屈从陷阱让人把别人的需求放在前面，害怕拒绝、冲突、内疚或被抛弃。表面上很会照顾人，内心却可能累积怨气，最后以冷战、爆发或消极抵抗表达。练习从找回偏好开始：今天我想吃什么、看什么、怎样安排时间？再做一张关系收支表：我给了对方什么，对方给了我什么，是否长期失衡？行动上从低难度表达练起，例如说出一个小偏好、提出一个具体请求、拒绝一个不合理要求。表达时用清楚、具体、冷静的句子，不用攻击证明自己有理。重点是让“我的需求也重要”从头脑理解，慢慢变成身体能承受的关系经验。', '["屈从陷阱", "边界表达", "讨好模式", "关系平衡", "行动替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 692, now()),
(100693, '苛刻标准：用生活质量校准“必须完美”', '苛刻标准陷阱会把价值感绑在完美、秩序、成就、地位或高效率上。它可能带来成绩和认可，但也常牺牲健康、放松、亲密和快乐。练习时先列出高标准出现的领域，再分别写出好处和代价：它让我得到了什么，又让我失去了什么？接着做一个“降低25%标准”的实验，允许任务达到够好而非完美。可以给每项任务设定时间上限，到点就停止，把更多时间分配给真正重要的人和需要。若难以判断合理标准，可询问生活相对平衡的人。提醒语可以是：我可以把事情做到中等偏好，同时仍然是有价值的人。', '["苛刻标准", "完美主义", "生活平衡", "自我价值", "修复练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 693, now()),
(100694, '权利错觉与边界：把“我想要”转成互惠请求', '权利错觉不只是自信，而是把自己的需求放得过大，忽略他人的感受、规则、时间和代价，也可能表现为冲动、缺自律或一生气就越界。改变要从看见后果开始：我的要求、发火、拖延或特殊待遇期待，给别人和长期目标带来了什么影响？再识别借口，例如“我就是这样”“我没有伤害任何人”“以后再补也行”。替代练习是写情境卡：先感知对方需求，再按互惠、公平、平等原则行动；把命令改成请求，把即时满足改成延迟选择。若愤怒升高，先暂停离开，降温后再表达。若涉及自律问题，用由易到难的任务阶梯训练挫折耐受。', '["权利错觉", "边界", "自律", "同理心", "冲动控制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 694, now()),
(100695, '改变旧模式的方向感：愿景、同情和支持网络', '修复旧模式不只是减少痛苦，还要知道自己想走向哪里。可以从五个方向写愿景：我想要怎样的亲密和社交联结？我需要怎样的独立与自主？我希望怎样建立自尊？我想如何表达需求、兴趣和快乐？我愿意怎样关心他人并参与世界？改变时要保持“同情式正视”：理解旧模式为什么形成，不用羞辱逼自己；同时也为今天的行动负责，不让童年痛苦成为继续伤害自己或他人的理由。支持网络很重要，可以邀请可信亲友见证小步骤、给客观反馈；当问题太重、影响生活或关系安全时，也可以把专业支持纳入计划。', '["改变哲学", "人生愿景", "自我同情", "支持系统", "修复练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 695, now()),
(100696, '习得性无助：不是懒，而是“做什么都没用”的预期', '习得性无助不是简单的懒惰或意志差，而是在反复经历“行动和结果没有关系”之后，大脑形成的一种预期：我再做也不会有用。它会同时影响三个层面：更难启动行动，更难看见新的线索和机会，情绪也更容易从紧张、焦虑滑向低落和麻木。自助时，先把无助感当作一种被学会的反应，而不是对人格的判决。可以写下最近一件让你想放弃的事：我做过哪些尝试？哪些部分确实不由我控制？现在情境是否已经变化？还有没有一个小反应可能带来可见结果？这个练习的目的不是强迫自己乐观，而是重新检查“完全没办法”是否仍然成立。', '["习得性无助", "心理教育", "可控感", "行动恢复", "情绪调节", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 696, now()),
(100697, '先分清失败、痛苦和不可控：别把一次挫折解释成一生无能', '让人受伤的事件不一定都会造成习得性无助。关键差别在于：这件事是否让你相信“我的反应和结果没有关系”。一次考试失败、面试被拒、关系受挫，可能只是痛苦；如果你把它解释成“我怎样都不可能改变”，无助感才更容易扩大。练习时可以把事件拆成三栏：事实发生了什么；我当时能控制和不能控制的部分分别是什么；现在还有哪些新的资源、规则或选择。这样做可以减少把局部失败扩大成整体否定，也能帮助你把注意力从“我完了”转向“下一次我可以改变哪一个变量”。如果现实中确实存在安全、经济或关系压力，也可以把寻求外部支持列为可控行动之一。', '["习得性无助", "归因", "自责缓解", "可控感", "压力应对", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 697, now()),
(100698, '无助感自查三线索：少行动、低预期、情绪下沉', '可以用三个线索判断自己是否正在进入无助循环。第一，行动减少：在其实还有一点空间的情境里，开始拖延、退缩、放弃尝试。第二，预期变低：脑中反复出现“做了也没用”“结果不会变”。第三，情绪下沉：先是紧张和不安，随后变成疲惫、麻木、低落或对自己失望。发现这些线索后，不需要立刻责备自己，而是先做一次“情境校准”：这件事现在真的完全不可控吗？有没有一个最小行为可以测试环境是否会回应？有没有一个人、工具或规则能增加我的控制感？自查不是给自己贴标签，而是尽早把无助循环从自动运行中拉出来。', '["习得性无助", "自我觉察", "行动恢复", "情绪调节", "可控感", "低落预警"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 698, now()),
(100699, '解释风格三问：这真的是“我、永远、处处都不行”吗', '无助感常被一种悲观解释风格放大：把坏事解释成“都是我造成的”“永远会这样”“生活每个方面都证明我不行”。遇到挫折后，可以用三问来松动这种解释。第一，内外：这件事有多少来自我，有多少来自情境、时机、规则或他人的反应？第二，稳定：这个原因会永远存在，还是可能随练习、休息、信息和资源改变？第三，范围：它只影响这件事，还是我把它扩展到了所有领域？更有帮助的解释通常不是逃避责任，而是更具体、更暂时、更可行动。例如，把“我就是没用”改成“这次准备方式不适合这个任务，我可以换一个方法再试一次”。', '["解释风格", "归因", "习得性无助", "认知重评", "自我效能", "可控感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 699, now()),
(100700, '从“我不行”到“方法还没对”：用再归因保护自尊', '当结果只是对自己不可控、别人却能做到时，人更容易把失败解释成“我这个人不行”，自尊也更容易受损。更稳妥的做法是把评价对象从“整个人”缩小到“这一次的方法、资源和练习条件”。例如，学习、工作或关系中的失败，可以先问：我是否缺少信息？是否任务太大？是否反馈不清楚？是否需要换策略或求助？把“能力不足”改写为“方法、努力方向、支持资源还需要调整”，会让下一步更可操作。它不是否认问题，而是避免用一个结果审判整个人。对儿童、伴侣或同事提供反馈时，也尽量具体到行为和策略，少用固定人格标签。', '["再归因", "自尊修复", "解释风格", "行动恢复", "自我效能", "习得性无助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 700, now()),
(100701, '恢复可控感：先找一个会回应你的微行动', '无助感的修复通常不是靠一次想通，而是靠重新体验“我做一点，世界会有一点回应”。可以选择一个足够小、反馈足够快的行动：洗一个杯子、整理桌面一角、走五分钟、发出一条具体求助信息、完成一个两分钟任务。关键是让行动和结果之间的关联变得清楚，而不是追求宏大的改变。完成后记录三句话：我做了什么；出现了什么结果；这个结果说明我在哪个小范围内有影响力。连续积累这种微小的掌控体验，会削弱“什么都没用”的旧预期，帮助行动系统重新启动。', '["可控感", "行动恢复", "微行动", "自我效能", "习得性掌控", "心理练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 701, now()),
(100702, '行动取向练习：把反复追问“为什么”变成下一步“做什么”', '人在不可控事件后容易反复追问原因，短期内这是理解世界的努力；但如果一直停留在“为什么会这样、是不是我太差”，注意力会被困住，行动反而更少。可以给自己设置一个温和的切换流程：先允许5分钟写下担心和解释；然后圈出其中一个可验证的问题；最后写下今天能做的一个动作，最好小到10分钟内能完成。这个动作不一定直接解决全部问题，它的作用是把大脑从状态取向拉回行动取向。若持续陷入反刍、失眠、明显低落或自伤念头，应及时联系可信的人和专业支持。', '["行动取向", "反刍", "认知耗竭", "情绪调节", "行动恢复", "专业支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 702, now()),
(100703, '成功也要留痕：让大脑重新看见“我做了所以有效”', '无助感会让人特别关注失败，却忽略成功中自己的作用。恢复自我效能时，不只要复盘挫折，也要给小成功留下证据。每天记录一件“有一点点变好”的事，并写清楚：我做了哪一个动作；这个动作可能怎样帮助了结果；下次能否重复其中一小部分。比如，不只是写“今天状态好一点”，而是写“我提前睡了半小时，早上更容易起床”。这样的记录能帮助大脑重新学习行动和结果之间的关联。它也能防止把成功全都归因于运气，把失败全都归因于自己，从而让解释系统更平衡。', '["自我效能", "成功记录", "解释风格", "习得性掌控", "积极心理", "行动恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 703, now()),
(100704, '低谷中的活动循环：先恢复生活启动，再追求意义感', '无助感和抑郁低谷会互相强化：越觉得做什么都没用，越难开始；越不行动，越缺少新的反馈，旧预期就越牢。低谷时不要把目标设成“立刻变好”，可以先恢复最基础的活动循环：起床后拉开窗帘、喝水、吃一点东西、出门走几分钟、完成一个可结束的小任务。行动的目的不是证明自己已经好了，而是给身心一个新的输入，让“我还能影响一点点生活”的证据重新出现。如果低落持续、功能明显受损，或出现自伤自杀念头，要尽快寻求专业帮助和现实支持。', '["低谷修复", "行动恢复", "抑郁预警", "生活节律", "可控感", "专业支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 704, now()),
(100705, '复发预防：情绪好转后继续维护解释风格和生活结构', '无助感减轻后，旧的解释习惯仍可能在下一次挫折中被重新激活。复发预防不是一直紧张地监控自己，而是在状态较好时提前留下维护系统。可以每周做一次简短回顾：最近哪件事让我想放弃？我有没有把它解释成“都是我、永远、处处”？我采取过哪些小行动有效？下次低谷出现时，我要联系谁、暂停什么、保留哪一个最低生活动作？把工具箱留在情绪变好之后，能让下一次波动来临时不必从零开始。必要时，可以把这些预案和咨询师、医生或可信支持者一起完善。', '["复发预防", "解释风格", "行动计划", "支持系统", "抑郁预警", "自助练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 705, now()),
(100706, '支持系统不是替你控制，而是帮你重新获得回应', '人在无助时需要支持，但最有帮助的支持不是替你包办一切，而是帮助你重新看见选择、反馈和行动余地。向他人求助时，可以尽量把请求说具体：请陪我梳理三个可控部分；请提醒我完成今天的十分钟行动；请和我一起联系专业资源。对支持者来说，也可以少说“你想开点”，多给清晰、及时、可执行的回应。长期只表达“什么都没用”容易让关系双方都感到无力，所以支持系统也需要边界和轮换。好的支持会让人逐渐把控制感拿回来，而不是形成新的依赖或孤立。', '["支持系统", "可控感", "求助表达", "关系支持", "行动恢复", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 706, now()),
(100707, '健康行为中的无助修复：从一个可坚持的小习惯开始', '无助感会影响健康行为：当人相信“我改变不了”，就更容易放弃睡眠、饮食、运动、就医和遵医嘱等行动。自助练习可以从一个最小健康习惯开始，而不是同时改造全部生活。选择一个你愿意连续7天尝试的动作，例如固定时间喝水、睡前远离屏幕10分钟、饭后散步5分钟、按时记录症状或预约必要检查。每天只记录是否完成，以及完成后身体和情绪有什么细微变化。这个练习不替代医疗建议，它的价值在于提升“我能为健康做一点事”的自我效能，并把健康照护从抽象愿望变成可执行行动。', '["健康行为", "自我效能", "微习惯", "可控感", "行动恢复", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 707, now()),
(100708, '可控与不可控清单：明智地坚持，也允许暂时保存能量', '恢复无助感并不等于盲目坚持。若环境确实暂时没有回应，继续硬撞可能只会耗尽资源；若情境已经有可控空间，过早放弃又会巩固无助预期。可以把困境分成两栏：我现在能影响的；我现在不能直接影响的。对可控栏，选一个最小行动去测试反馈。对不可控栏，练习承认现实、保存能量、寻找替代路径或外部支持。这样的区分能避免两种极端：把所有事都怪自己，或把所有事都判定为无能为力。真正的可控感，来自对现实限制和行动余地的同时看见。', '["可控感", "现实检验", "行动恢复", "情绪调节", "复原力", "习得性无助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 708, now()),
(100709, '让环境更有回应性：减少“努力和结果无关”的反馈', '无助感不只发生在个人内心，也可能被环境放大。学校、工作、家庭或团队里，如果奖励、惩罚和反馈长期与具体行为无关，人就容易觉得努力没有意义。可以做一次环境审计：我在哪些场景里最常感到做什么都没用？这里的规则是否清楚？反馈是否及时、具体、可预测？我能否请求更明确的评价标准，或把目标拆成可被回应的小步骤？如果你是家长、老师、管理者或支持者，尽量让反馈连接到可观察行为：指出什么有效、为什么有效、下一步如何调整。更有回应性的环境，本身就是无助感的修复资源。', '["环境反馈", "可控感", "支持系统", "行动恢复", "自我效能", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 709, now()),
(100710, '优势识别从自我观察开始：把反应写成可调整的地图', '性格优势不是一次测评给出的固定标签，而是在日常反应中逐渐看清的模式。可以选择一个具体情境，记录触发事件、身体感受、第一冲动、真实动机、行动结果，再问自己：这里已经出现了哪些可欣赏的品质？哪些反应过强或过弱？下一次我想让哪一种品质多一点？这种练习把“我就是这样”改写成“我正在观察并训练自己”，也能避免只盯缺点或只夸大优点。每一次思想、感觉和行为都会加深一种路径，记录它，就是重新选择路径的开始。', '["性格优势", "自我观察", "积极心理", "优势识别", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 710, now()),
(100711, '把冲动看成能量：先判断方向，再谈好坏', '恐惧、愤怒、好奇、表现欲、亲近需要等情感倾向本身并不等于好或坏，它们更像推动行动的能量。问题不在于“我有没有这个冲动”，而在于它被什么价值引导、强度是否合适、有没有压倒其他重要需要。练习时可以先给冲动命名：它想保护什么、争取什么、探索什么？再问：如果把这股能量放到更成熟的方向，它可以服务哪种品质？比如愤怒可转为边界和正义感，恐惧可转为谨慎，好奇可转为学习，而不是让冲动直接接管行为。', '["性格优势", "情绪调节", "积极心理", "自控", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 711, now()),
(100712, '好奇心的安全用法：靠近未知，也保留边界', '好奇心会把注意力带向陌生、复杂和有待理解的事物，是学习和探索的重要动力。成熟的好奇心不是无边界地打探他人，也不是被焦虑牵着走，而是在安全范围内提出问题、收集事实、亲自体验，再把发现转化为理解和行动。可以给自己设一个“小探索”：选择一个不熟悉但有益的主题，限定时间和范围，写下三个想知道的问题、一个可验证的小行动、一个需要尊重的边界。这样，好奇心会从分心和窥探，变成拓展能力与连接世界的优势。', '["好奇心", "性格优势", "学习", "积极心理", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 712, now()),
(100713, '勇气不是不害怕：看清你为何往前走', '外表相似的“勇敢行为”，背后可能是鲁莽、愤怒、求赞许、服从压力，也可能是责任、保护、理想和清醒选择。真正可持续的勇气，不是证明自己没有恐惧，而是在害怕存在时仍能看见重要价值，并为风险做准备。行动前可问四个问题：我想保护的是什么？最小可承受风险是什么？我需要哪些支持或退路？如果不是为了面子，我还会这样做吗？这样，勇气就从逞强变成有判断的前进。', '["勇气", "性格优势", "积极心理", "价值澄清", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 713, now()),
(100714, '自控不是硬压：先绕开触发，再练早停', '自控不是假装自己没有冲动，也不是靠羞耻把情绪压下去。更稳的做法包括三步：先减少高风险触发，例如让过强倾向少被环境反复激活；再练习在冲动刚出现时早停，识别身体信号和第一句话；最后把注意力转向更有价值的替代活动，如运动、创作、学习、服务或一项无害爱好。复盘时只问“哪个环节可以提前设计”，少问“我为什么这么差”。自控越像环境设计和早期选择，越不像临场硬扛。', '["自控", "意志力", "情绪调节", "成长行动", "习惯改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 714, now()),
(100715, '幽默降温：用温和自嘲替代羞辱和爆发', '幽默可以成为自我调节工具，但前提是它不是讽刺、羞辱或把别人推到悬崖下的嘲笑。温和的幽默能让人看到自己的局限，承认“人都会有笨拙时刻”，从而降低愤怒、羞耻和防御。可以为常见失误准备一句轻一点的提醒，例如“我又把小麻烦看成宇宙灾难了”，然后回到具体修正：现在能补救哪一步？对亲密关系和亲子沟通来说，幽默的目标不是赢过对方，而是让双方都能重新思考。', '["幽默", "自控", "情绪调节", "积极心理", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 715, now()),
(100716, '性情地图：按内外向和脾气差异安排成长', '成长不等于把所有人训练成同一种样子。外向者可能更需要在行动前暂停，补上思考、倾听和后果评估；内向者可能更需要在思考尚未完美时迈出小步，避免被反复推演困住。情绪起伏大的人可以降低刺激、建立稳定节律；稳定但迟缓的人可以增加提醒和外部承诺。先承认自己的气质、性情和脾气差异，再设计适配行动，会比用同一套标准责备自己更有效。目标不是消灭天性，而是在航图上标出暗礁，选择更安全的航线。', '["性格优势", "气质", "自我接纳", "行动设计", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 716, now()),
(100717, '坚毅来自注意力训练：练习做重要但不有趣的事', '坚毅不是天生喜欢吃苦，而是能把注意力放到“重要但暂时不吸引我”的事情上，并在小范围内重复完成。训练时不需要用恐吓或自我惩罚，而要让任务和价值相连：我为什么要学会它？它会服务谁、改善什么？然后把任务切成短时段，只要求完成一个清楚动作。每次按计划完成，都是在练习把即时冲动让位给长期目标。久而久之，人会获得一种更可靠的力量：即使兴趣不足，也能为自己认可的方向投入行动。', '["坚毅", "意志力", "注意力", "成长行动", "自律"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 717, now()),
(100718, '原则是路标：没有动力时还要回到价值情感', '原则能提醒我们哪些路容易偏离目标，但原则本身不一定提供行动动力。一个人知道“应该守时、诚实、礼貌”，并不等于在压力下自然做得到。更有用的做法，是把原则和自己珍视的品质、关系与理想连接起来：我想成为怎样的人？这个选择会保护哪段关系、哪种信任、哪种自尊？然后选一个最小行动去体现它。原则适合做路标，情感和价值提供燃料，反复行动才会让品质真正进入性格。', '["价值观", "原则", "性格优势", "行动改变", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 718, now()),
(100719, '兴趣让成长持续：把能力、愉悦和意义拌在一起', '许多长期行动并不是先靠强烈热爱开始，而是在“能做出一点进步、过程中有一点愉悦、背后有一点意义”时逐渐长出兴趣。强迫自己或孩子反复接触讨厌的内容，常会制造厌恶；更好的方式是把困难内容拌进已喜欢的场景里，降低剂量，创造小成就，并允许逐步深入。比如把阅读放进轻松对话，把运动放进社交，把学习放进真实问题。兴趣不是逃避努力，而是让努力有可持续的心理燃料。', '["兴趣", "好奇心", "积极心理", "学习", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 719, now()),
(100720, '升华：把强烈欲望转成创造、服务和长期目标', '强烈冲动不一定只能被放纵或压住，也可以被转化到更高层次的行动中。渴望被看见，可以转成作品、表达和贡献；愤怒可以转成维护边界、改善规则；亲密和爱慕的能量可以转成成长、创造和照顾；竞争心可以转成精进技能。练习时先承认能量存在，再问：如果不让它直接支配我，它能支持哪件更有意义的事？接着安排一个具体出口，例如写一页、运动二十分钟、完成一项服务、推进一个长期项目。', '["升华", "性格优势", "自控", "创造力", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 720, now()),
(100721, '补偿不过度：短板可以训练，不必反向证明自己', '意识到短板后，人常会想通过努力弥补，这是成长的重要动力；但如果补偿变成“我必须永远证明自己不是那样”，就可能走向固执、冒险或过度敏感。更稳的补偿方式，是把短板改写成可训练技能：害怕表达，就从一次简短发言开始；容易退缩，就设计一个可承受挑战；缺少坚持，就设一段可完成周期。用事实反馈校准进步，而不是用极端行为证明价值。短板可以成为训练入口，但不必成为新的身份枷锁。', '["补偿", "自我接纳", "坚毅", "成长行动", "积极心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 721, now()),
(100722, '稳健乐观：把注意力放回可享受、可分享、可行动', '乐观不是否认痛苦，也不是保证未来一定顺利，而是训练注意力不要长期困在后悔、缺陷和灾难预期里。可以从三类小事练起：第一，觉察今天已经存在的简单愉悦，例如阳光、食物、洗澡、休息；第二，把快乐分享给别人，把痛苦说给可信的人听；第三，遇到问题时，把注意力从反复懊悔转向下一步可行动的部分。这样的乐观更像心理卫生习惯：它不替代解决问题，却能减少无效消耗，让人保留行动力。', '["乐观", "积极心理", "注意力", "情绪调节", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 722, now()),
(100723, '内心和谐：减少互相拉扯的目标，力量才会集中', '一个人不快乐，常不只是因为外界困难，也可能因为内在目标长期互相拉扯：既想亲近又想逃开，既想成功又害怕代价，既坚持理想又不愿承认现实限制。回避冲突会让能量消耗在暗处。可以把冲突写成两句话：“我一部分想……另一部分担心……”再分别写下它们保护的价值，尝试调整优先级、协商边界或做出阶段性选择。内心和谐不是没有矛盾，而是让重要力量能被看见、排序，并朝同一方向合作。', '["内心和谐", "自我觉察", "价值澄清", "积极心理", "成长行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 723, now()),
(100724, '渴求识别：把“我必须马上做”拆成触发、行为和奖励', '当冲动出现时，先不要把它理解成“我太差了”或“我没救了”。更实用的看法是：大脑正在运行一个习惯循环。请在 App 里写下三件事：刚才发生了什么触发了我；我想立刻做什么；这个行为承诺给我的奖励是什么，例如放松、麻木、刺激、被连接或逃离压力。看清这三步，会让冲动从一团命令变成一张可观察的地图。改变通常不是靠羞辱自己开始，而是靠一次次看见：这个行为到底在帮我解决什么，又把我带向哪里。', '["上瘾循环", "渴求识别", "触发器", "行为改变", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 724, now()),
(100725, '冲动浪潮：渴求会升起、到顶峰，也会自然回落', '渴求最强的时候，很容易让人相信“如果不马上满足，我会受不了”。可以把它想象成一阵浪：它会升起、变强、到达顶峰，然后在没有继续喂养时逐渐下降。练习时，给当前渴求打一个 0-10 分，记录身体哪里最明显，再每 1 分钟重新评分。目标不是立刻舒服，而是亲眼看见：冲动不是一条必须执行的命令，它是会变化的身心事件。哪怕这次只多停留 30 秒，也是在训练大脑不再把“有渴求”和“必须行动”绑死。', '["冲动管理", "渴求识别", "正念练习", "身体觉察", "延迟行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 725, now()),
(100726, 'RAIN 正念冲浪：在冲动里识别、允许、探究和标记', '当渴求来了，可以用 RAIN 做一个 2-5 分钟的正念间隔。R：识别它，“冲动来了”；A：允许它暂时存在，不急着压下去，也不马上跟着走；I：探究身体里最明显的感觉，比如胸口紧、胃部热、手想动、脑内催促；N：用简单词标记当下体验，如“紧”“热”“想要”“急”。如果分心了，就回到一句问题：此刻身体里最明显的感觉是什么？这套练习不是和冲动作战，而是学会站在浪上，陪它走到减弱。', '["RAIN", "正念练习", "冲动管理", "身体觉察", "渴求冲浪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 726, now()),
(100727, '渴求与行动脱钩：先练习不加燃料，而不是消灭欲望', '很多人以为改变意味着“再也不能有渴求”。更现实的目标是：渴求可以出现，但我不一定按旧方式行动。书中把渴求比作火：如果每次都用旧行为满足它，就像继续添柴；如果能在渴求里停一停、观察它、选择不执行旧动作，火还会烧一阵，但燃料会慢慢减少。App 练习可记录两项：今天有没有渴求；我是否把渴求和旧行为分开了。进步不是完全没冲动，而是冲动出现时，多了一点选择空间。', '["复发预防", "冲动管理", "渴求识别", "习惯改变", "正念练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 727, now()),
(100728, '触发器地图：记录让旧习惯自动启动的线索', '触发器不只是一件大事，也可能是无聊、疲惫、被批评、手机提示音、某个地点、某个人、某段回忆，或身体里的不安。请用一周时间做触发器地图：时间、地点、情绪、身体感觉、身边的人、刚发生的事、我脑中第一句念头。不要急着评判，只把资料收集完整。几天后，你会看见旧习惯最常在哪些入口启动。看见入口后，才能提前安排间隔、离开刺激源、找人支持、做替代行动，而不是每次都等冲动变成海啸才处理。', '["触发器", "渴求识别", "自我监测", "复发预防", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 728, now()),
(100729, '真实奖励复盘：看清旧行为实际带来的味道和代价', '“我知道它不好”常常不够，因为知道停留在头脑里；真正有用的是在行为发生时保持好奇，直接观察它带来的真实奖励。比如刷完 30 分钟手机后，身体是更放松还是更麻木？冲动消费后，是满足还是空虚和担心？情绪化进食后，胃和心情分别怎样？请把“期待中的奖励”和“实际得到的结果”分开记录。越清楚看见旧行为的真实味道，大脑越容易祛魅：它并没有像广告或渴求承诺的那样真正解决问题。', '["心理教育", "行为复盘", "奖励机制", "正念练习", "上瘾循环"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 729, now()),
(100730, '正念间隔：迷路时先停下，再拿出压力指南针', '冲动最强时，大脑会催你赶紧动起来：马上回复、马上购买、马上点开、马上吃掉、马上发泄。正念间隔的第一步正好相反：先停下，深呼吸，确认自己在哪里。可以问三个问题：我现在是在走向更大压力，还是远离压力？这个行动 10 分钟后会让我更开阔还是更紧缩？如果我先等 3 分钟，会损失什么？这个间隔不是拖延，而是重新定位。只有先看清方向，再行动，才更可能从自动驾驶切换到有选择的回应。', '["正念间隔", "压力指南针", "冲动管理", "情绪调节", "延迟行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 730, now()),
(100731, '自控力会疲劳：别把改变全押在硬扛上', '靠意志力硬扛有时能撑一阵，但压力、疲劳、饥饿、情绪高涨时，理性控制最容易掉线。与其等到深夜、吵架后或工作崩溃时再要求自己完美自律，不如提前设计低风险环境：睡前把手机放远，关掉非必要通知，准备可执行的替代动作，给高风险时段安排支持联系人，并保证基本睡眠和进食。自控不是证明自己够强，而是承认人在压力下会回到旧路，所以提前把新路铺得更容易走。', '["自控力", "环境设计", "复发预防", "冲动管理", "压力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 731, now()),
(100732, '手机冲动管理：看见通知背后的不确定奖励', '手机和社交媒体特别容易形成习惯，因为它们不断制造“也许有新消息、也许有人点赞、也许有重要内容”的期待。不确定奖励会让人反复查看，即使大多数时候并没有真正重要的东西。练习时，不必把手机当敌人，而是看见它怎样训练自己：声音一响，身体哪里动了？脑中出现什么期待？点开后实际获得什么？可以把查看手机改成固定窗口，关闭非必要提醒，并在想点开时先做一次 RAIN。你要夺回的不是手机，而是注意力的选择权。', '["手机成瘾", "冲动管理", "注意力", "触发器", "数字健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 732, now()),
(100733, '思考上瘾：把反刍看成脑内习惯，而不是事实命令', '有些上瘾不表现为拿起某样东西，而是脑内不停重复：反复想一句批评、预演最坏结果、证明自己是对的、追着某个念头不放。思考本身不是问题，问题是被想法钩住后，身体开始紧缩，注意力离开当下，越想越焦虑或越想越兴奋。可以把念头标记为“计划”“担心”“回放”“证明”“幻想”，再把注意力放回呼吸、脚底或手边任务。标记不是否定想法，而是提醒自己：念头只是念头，不必自动变成行动或身份。', '["反刍", "思考上瘾", "正念练习", "情绪调节", "认知松动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 733, now()),
(100734, '好奇心练习：用“此刻发生了什么”替代自我批评', '面对冲动时，自我批评会让人更紧、更想逃离；好奇心则能把注意力带回真实体验。下一次想刷、想吃、想买、想发火时，试着不说“我怎么又这样”，改问：“此刻身体最明显的感觉是什么？它在变强还是变弱？它想让我得到什么？如果我不马上行动，会发生什么？”好奇不是纵容，而是用观察代替自动反应。越能具体观察身体、情绪和念头，越容易发现冲动背后的需要，也越容易选择更温和有效的下一步。', '["好奇心", "正念练习", "冲动管理", "自我接纳", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 734, now()),
(100735, '复发预防：为高风险时刻准备回到轨道的系统', '复发预防不是保证永不反复，而是提前知道自己在什么情况下最容易回到旧路，并准备恢复动作。可以建立一张“高风险卡”：最危险的三个场景；最早出现的身体信号；我可以做的 3 分钟练习；我能联系的一个人；如果已经发生旧行为，下一步最小修复是什么。请把重点放在“尽快回到轨道”，而不是用羞耻惩罚自己。对已经严重影响生活、安全或健康的行为，自助练习应与专业支持、可信任的人和现实环境调整一起使用。', '["复发预防", "支持系统", "安全计划", "正念练习", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 735, now()),
(100736, '替代行动：满足真实需要，而不是换一个坏习惯', '替代行动有用，但要小心：如果只是把抽烟换成不停吃糖、把焦虑换成刷短视频、把孤独换成冲动购物，旧循环可能只是换了外壳。更好的替代要先识别真实需要：我需要放松、连接、休息、刺激、被安慰，还是从压力里退一步？然后选低代价、可重复的动作，例如喝水散步、刷牙、给朋友发一句真实消息、做 10 次呼气、离开诱发场景、写下一个请求。替代行动不是压制渴求，而是用更少代价满足更真实的需要。', '["替代行动", "冲动管理", "情绪调节", "需求识别", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 736, now()),
(100737, '去阻力训练：用频率、强度和持续时间观察反应性', '每一次被触发后立刻反应，都会像训练肌肉一样强化旧模式；每一次看见冲动却不马上跟随，也是在训练新的自由度。可以用三个指标观察反应性：它今天出现了几次；每次有多强；持续多久才松开。不要只问“我有没有彻底改掉”，而要看：我是否更早发现身体紧缩？强度是否少了一点？持续时间是否短了一点？能否更快放下？这样，改变就从抽象自责变成可追踪训练。习惯也可以成为老师，提醒你下一次在哪里更早醒来。', '["韧性训练", "复发预防", "身体觉察", "正念练习", "行为追踪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 737, now()),
(100738, '先看连接：把关系困扰从“谁错了”改成“循环如何形成”', '当关系、家庭或团队问题反复出现时，先不要急着把原因压到某一个人身上。系统视角会问：有哪些人、期待、规则、资源和信息在互相牵连？最近一次冲突是怎样被触发的？一方的反应又怎样改变了另一方的反应？例如，一个人越沉默，另一个人越追问；追问越急，沉默越深，最后双方都觉得自己只是被迫自保。把问题改写成互动循环后，责任感不会消失，但责怪会下降，因为重点变成“我们怎样共同改变这个循环”。App 端可引导用户记录：触发事件、我的回应、对方回应、短期好处、长期代价，以及可以插入的新回应。', '["系统思考", "关系模式", "互动循环", "问题解决", "家庭沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 738, now()),
(100739, '系统边界：问题要框得够大，也要避免把全世界拉进来', '一个问题框得太窄，会只看见“半只大象”：比如只说孩子不写作业，却不看睡眠、亲子互动、任务难度和奖惩方式；但框得太大，又会把所有历史、性格和社会因素都拉进来，让人无从下手。实用的系统边界，是把“会直接驱动问题、也能被我们观察或影响”的因素先放进来，把暂时无法处理的因素标成背景。家庭或团队讨论时，可以先问三句：这个问题最关键的结果是什么？最明显的外部压力是什么？哪些因素一变，冲突就会跟着变？这样既保留整体感，又能把咨询、沟通或自助练习落到可行动的范围。', '["系统边界", "问题澄清", "系统思考", "家庭沟通", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 739, now()),
(100740, '局部修补的副作用：别把今天的问题推到明天或别人身上', '很多看似有效的处理方式，只是在局部暂时止痛。冷战能让今晚不再吵，却可能让信任在几周后变少；讨好能避免当场冲突，却可能让别人越来越不知道你的真实边界；父母替孩子完成任务能减少眼前焦虑，却可能让孩子更难形成能力。系统思考提醒我们检查“这里—那里”和“现在—以后”的后果：这个办法解决了谁的压力？压力会不会转移给另一个人？短期安静会不会换来长期更大的问题？在 App 中，这类条目可以帮助用户把“有效”分成短期有效、关系有效、长期有效三层，而不是只凭当下情绪判断。', '["副作用", "系统思考", "延迟效应", "关系模式", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 740, now()),
(100741, '增强回路：小小回应怎样滚成关系里的良性或恶性循环', '增强回路的特点是：每转一圈，原来的趋势就被放大。关系中的恶性循环常常如此：我越担心被忽视，就越用指责确认对方在不在乎；对方越被指责，就越防御或逃开；我又更确信自己被忽视。良性循环也使用同一种结构：一次具体感谢让对方放松，对方更愿意合作，你也更容易表达肯定。关键不在于“这个人本来好或坏”，而在于回路被什么触发、朝哪个方向滚动。用户可以练习寻找循环中的最小可变点：降低一句攻击、增加一次确认、提前说出需要，看看系统下一轮是否变得不一样。', '["增强回路", "反馈回路", "关系模式", "冲突降温", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 741, now()),
(100742, '调节回路：用目标、差距和行动把生活慢慢带回平衡', '调节回路不是让事情越滚越大，而是让系统朝某个目标靠近。放到个人和关系里，它可以变成一个清晰步骤：先说出目标状态，再观察现实状态，找出差距，然后采取一项行动。例如“我希望每周有两晚安静相处；现实是我们每天都在刷手机；差距是缺少共同时间；行动是周三、周六饭后散步20分钟”。很多沟通失败，是因为目标没有被说清楚，行动却已经开始互相要求。把目标、现实、差距、行动拆开后，人会更少陷入人格评价，更容易讨论下一步怎么调。', '["调节回路", "目标设定", "问题解决", "关系沟通", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 742, now()),
(100743, '延迟效应：改变还没显现时，别急着连续加码', '很多系统都有延迟：你说出边界，对方可能需要几天才适应；你调整亲子规则，孩子可能先反弹再稳定；团队改流程，也要经过理解、试错和反馈。若在效果还没出现时连续加码，就像反复拧一个有延迟的淋浴器，系统会忽冷忽热。更稳的做法是：一次只做小调整，提前估计延迟时间，在等待期记录反馈，不因短暂波动立刻推翻全部方案。对焦虑型用户尤其重要，因为焦虑会把“还没见效”解释为“完全没用”，从而制造过度控制、频繁确认或突然放弃。', '["延迟效应", "调节回路", "情绪调节", "问题解决", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 743, now()),
(100744, '成长上限：努力无效时，先找正在踩刹车的约束', '一个人或一段关系卡住，并不总是因为努力不够。系统里可能有“刹车”：睡眠不足、长期压力、技能缺口、信任太低、角色不清、外部资源不足，都会限制成长。若只继续加油，比如更用力沟通、更密集学习、更严格要求孩子，反而可能让约束反弹得更强。成长上限的视角会问：这个系统本来想往哪里长？现在是什么因素让它一到某个阶段就慢下来或倒退？在 App 中，可把“我为什么又失败了”改成“哪个约束先出现了”，帮助用户从自责转向结构性诊断。', '["成长上限", "约束", "系统思考", "自我成长", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 744, now()),
(100745, '杠杆点：先松开限制，再给愿望加油', '有些行动是在推动愿望，有些行动是在缓解限制。前者像催促自己更自律、要求伴侣多改变、给孩子加任务；后者像修复睡眠、降低冲突强度、补足技能、重新分配家务、减少不必要的干扰。系统思考里的杠杆感，常常来自后者：当真正的限制被松开，原本的良性动力会自己转起来。用户可以把待办事项分三类：推动增强回路、缓解约束、其他。若某项计划已经被情绪耗竭、信任不足或资源不足卡住，继续加压未必是杠杆；先创造安全、时间和能力，可能更有效。', '["杠杆点", "约束管理", "问题解决", "系统思考", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 745, now()),
(100746, '心智模式可视化：把“我以为”画出来，团队才可能对齐', '同一件事，不同人会带着不同心智模式理解。伴侣一方以为“沉默代表不在乎”，另一方以为“沉默是在避免吵架”；团队里有人相信“加宣传最重要”，有人相信“先训练新人最重要”。这不一定是谁对谁错，而是每个人脑中有不同的因果图。实用做法是把“我以为 A 会导致 B”说出来或写出来，再请对方补充他的版本。外化之后，争论会从“你怎么这么想”转为“我们看到的连接哪里不同”。这能减少强行说服，增加共同修正的机会。', '["心智模式", "团队沟通", "伴侣沟通", "系统图", "共识形成"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 746, now()),
(100747, '主动倾听是反馈回路：沟通要让对方知道你真的接收到了', '倾听不是安静等对方说完，也不是脑中准备反驳。主动倾听是一种反馈：我把接收到的信息返回给你，让你知道我有没有理解对。可以使用三步句式：“我听到你在担心……”“这对你意味着……”“我理解得准确吗？”这会在人和人之间建立连接，降低对方继续加大音量或重复解释的需要。家庭、伴侣和团队中的很多升级，来自一方没有收到“我被听见了”的反馈，于是不断加强表达。把倾听做成闭合回路，沟通才不只是信息投递，而是共同校准。', '["主动倾听", "反馈回路", "沟通技巧", "关系修复", "团队协作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 747, now()),
(100748, '跨边界冲突：从双方各自合理，走向共同有利', '很多冲突不是因为一方完全不讲理，而是双方都在各自系统里合理行动，却合在一起制造恶性循环。家庭中，父母想降低风险，孩子想争取自主；职场中，一方想控成本，另一方想保质量和收益；伴侣中，一方想确认关系，另一方想保留空间。系统视角会分别画出双方压力，再寻找共同目标：安全、信任、长期合作、可预期的规则。解决不只是让一方让步，而是重新设计关系：共享信息、共同承担成本和收益、承诺长期合作，并建立双方都能看见的反馈机制。', '["跨边界冲突", "关系系统", "双赢", "共同目标", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 748, now()),
(100749, '未来实验室：重要决定先做小推演，再进入现实', '系统思考不只用于解释过去，也能帮助人在行动前推演后果。面对分手、换工作、搬家、亲子规则调整等重大决定，可以先做一个简化“未来实验室”：如果我采取这个行动，最先改变什么？谁会受到影响？短期指标和长期指标可能分别怎样变化？哪些反馈会让我知道方向不对？不需要复杂软件，纸面推演、小范围试行和固定复盘就能降低盲目性。它特别适合那些看似能立刻止痛、却可能在几周后制造新问题的决定。', '["未来实验室", "决策推演", "延迟效应", "系统动力学", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 749, now()),
(100750, '看不见的变量：安全感、信任和疲惫也要进入问题地图', '并不是只有能量化的东西才重要。关系里的安全感、信任、羞耻、疲惫、被尊重感，往往难以精确测量，却深深影响行为。如果问题地图里只放“作业完成率”“收入”“回复速度”，就可能漏掉真正的驱动因素。系统思考允许把这类模糊变量放进图里：它们可以先用强/弱、高/低、增加/减少来描述，再通过具体线索观察，例如争吵后恢复时间、主动分享次数、身体紧绷程度。对心理教育来说，这能帮助用户承认主观经验的系统作用，而不是因为它“不好量化”就忽略。', '["模糊变量", "安全感", "关系模式", "系统思考", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 750, now()),
(100751, '图不是定论：把自己的解释当成可修正的假设', '系统图或问题地图的价值，不是一次性证明“我终于看懂了真相”，而是提供一个可以讨论、检验和修改的版本。人很容易爱上自己的解释：一旦画出“对方冷淡—我焦虑—我追问—对方更冷淡”，就以为关系只剩这一条因果链。但真实系统会变，遗漏因素也会出现。更成熟的用法是把地图拿去核对：对方是否同意？有没有别的驱动？这张图解释不了哪一次例外？下一周的观察是否支持它？当解释保持可更新，系统思考才不会变成新的标签化。', '["系统图", "假设检验", "反馈修正", "关系沟通", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 751, now()),
(100752, '先问清楚问题，再用力解决', '很多痛苦不是因为你不够努力，而是因为一开始就把问题看窄了。遇到困扰时，可以先暂停“我要马上解决”的冲动，写下三个层次：正在发生的事实是什么；我给它贴上的解释是什么；它真正触动的是安全感、被认可、自由、关系还是价值感。只有把“事情本身”和“我对事情的判断”分开，努力才不会变成盲目的消耗。深度思考的起点，是先确认自己到底在解决什么问题。', '["深度思考", "问题澄清", "事实区分", "认知成长", "自我反思"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 752, now()),
(100753, '把“我不行”拆回事实、解释与下一步', '当你得出“我不行”“别人都不喜欢我”“这次肯定失败”这类结论时，先把它当成情绪发出的警报，而不是最终事实。可以问自己：我实际观察到了什么？哪些只是推测？还有没有其他解释？如果最坏情况发生，我能做的第一步是什么？这种练习不是否定感受，而是让感受回到可被理解、可被行动回应的位置。焦虑会把故事讲得很绝对，深度思考则帮助你把故事拆开。', '["情绪觉察", "证据意识", "问题澄清", "认知偏差", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 753, now()),
(100754, '把“应该如此”的声音当成待验证假设', '很多内耗来自“我应该成为某种人”的声音：应该外向、应该稳定、应该成功、应该照顾所有人。可以把这些“应该”改写成假设：是谁告诉我必须这样？它适用于现在的我吗？有没有反例？如果我少遵守一点，会发生什么？把规则当成假设，不是任性地推翻一切，而是给自己重新选择的机会。成熟的自我认知，常常从质疑那些习以为常的标签开始。', '["认知偏差", "假设检验", "标签松动", "自我反思", "深度思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 754, now()),
(100755, '决定之前，先看见决定背后的动机', '一个选择表面上可能是换工作、结束关系、继续坚持或放弃计划，真正需要被看见的是背后的动机：我是为了接近自己重视的东西，还是为了逃开不舒服的评价？我是出于好奇、热爱和责任，还是出于证明、讨好和恐惧？决定没有绝对正确，但动机会影响你承担后果的能力。做重大选择前，写下“我最想保护什么”“我最怕失去什么”“我愿意为此付出什么”，能让选择更接近真实。', '["决策澄清", "动机觉察", "价值排序", "自我反思", "决策复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 755, now()),
(100756, '让证据和直觉共同参加判断', '只依赖感觉，容易把愿望当成事实；只依赖数据，又可能忽略身体已经感到不对劲的信号。更稳的判断是让二者一起参加：先收集能验证判断的证据，再记录直觉带来的细微反应；如果证据和感觉冲突，不急着选边，而是继续追问缺了什么信息、有什么假设没有被检验。个人成长不是压抑直觉，也不是迷信直觉，而是让感受、事实和逻辑互相校准。', '["证据意识", "直觉判断", "假设检验", "深度思考", "决策质量"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 756, now()),
(100757, '用小选择复盘自己的长期方向', '人生方向不一定来自一次宏大的顿悟，很多时候藏在反复出现的小选择里：你总被什么吸引？什么经历让你更有生命力？哪些“不起眼”的决定后来改变了你？可以每月做一次方向复盘，记录让你靠近自己、远离自己、意外打开可能性的三个小选择。这样做能帮助你看见隐含的价值线索，而不是只用外界眼中的成败来判断道路是否正确。', '["决策复盘", "长期方向", "自我观察", "价值澄清", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 757, now()),
(100758, '允许问题暂时没有答案，但不要停止思考', '有些问题不会马上给出清晰答案，例如“我到底适合什么”“这段关系还能不能继续”“我真正想要怎样生活”。没有答案不代表思考失败，也不代表只能逃避。你可以先承认未知，把问题保留下来，同时观察新的信息：我在什么情境下更放松？哪些选择让我更靠近价值？哪些解释反复被事实推翻？深度思考不是强迫自己立刻确定，而是在不确定中持续倾听、观察和修正。', '["不确定性", "深度思考", "问题澄清", "自我倾听", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 758, now()),
(100759, '复盘优势的阴影：过度使用长处也会伤人', '你的优点在压力下可能会变成困扰：负责变成控制，敏感变成过度解读，追求卓越变成苛刻，善解人意变成没有边界。复盘时不要只问“我哪里不好”，也要问“我的哪个长处用得太猛了”。当你能看见长处背后的阴影，就不必把反馈理解成全盘否定，而能把它当成调节方式的线索。成长不是消灭自己的特质，而是学会在不同情境中调节它的强度。', '["自我反思", "认知偏差", "优势阴影", "反馈整合", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 759, now()),
(100760, '从别人的眼睛里检查自己的盲区', '我们通常只能从一个角度看自己，所以很容易把“我的感受”误认为“全部事实”。当你陷入争执或自我怀疑时，可以练习换位：如果我是对方，我会看到什么？如果我是旁观者，我会如何描述这件事？如果信任我的人给出提醒，我最不想听见的是哪一句？换位不是讨好别人，而是扩大信息来源。能承受不同视角的人，更容易从防御转向理解，也更容易找到真实的问题。', '["换位思考", "盲区觉察", "证据意识", "关系沟通", "自我反思"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 760, now()),
(100761, '在规则里行动，也给自己保留改写规则的空间', '规则有时能保护你，让你学会基本功；规则也可能把你困在单一答案里。面对“必须这样做”的要求时，可以先分辨：这是安全和责任所需的底线，还是别人习惯性的路径？我需要先学习哪些规则，才能有能力改写它？我想突破的是规则本身，还是规则背后的刻板想象？真正的自由不是拒绝所有规则，而是在理解规则后，找到更符合真实需要的做法。', '["规则意识", "认知成长", "假设检验", "自我更新", "深度思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 761, now()),
(100762, '用边界感把关心别人和照顾自己分开', '关心别人不等于让所有人的需求都压过自己。若你总在关系里过度解释、过度负责或害怕让人失望，可以练习把边界说清：我愿意听你说，但我不能替你承担全部；我理解你的期待，但我也需要保留自己的节奏；我关心这段关系，但我不想用牺牲真实感受来维持和平。边界感不是冷漠，而是让关系不再靠消耗维持。你越能稳住自己的位置，越能真诚地靠近别人。', '["边界感", "自我照顾", "情绪觉察", "关系沟通", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 762, now()),
(100763, '把真实价值变成可表达的声音', '你可能很清楚自己在乎什么，却长期把它压下去：怕显得奇怪、怕被否定、怕失去旧身份。可以从一个小问题开始：如果我今天只用一个词提醒自己，它会是什么？真实、自由、稳定、连接、创造，还是勇气？接着问：我今天能用一个多小的行动表达它？真实价值如果一直没有声音，就会慢慢萎缩。表达不一定宏大，它可以是一句诚实的话、一次拒绝、一个选择，或一次不再假装没事。', '["真实自我", "价值表达", "身份重塑", "自我反思", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 763, now()),
(100764, '不急着模仿成功模板，先定义自己的成功', '看到别人走得很快、做得很好时，我们容易把对方的路径当成答案。但别人的成功往往对应别人的价值、资源、性格和代价。你可以问自己：我羡慕的是结果，还是其中某种状态？如果照搬这条路，我会失去什么？如果只借鉴一个原则，哪个最适合现在的我？真正的问题不是“怎样复制成功”，而是“我想用什么方式成为自己”。当成功由自己定义，比较才会慢慢松动。', '["成功定义", "标签松动", "价值澄清", "认知偏差", "深度思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 764, now()),
(100765, '把“我不配”改写为天赋线索：从借口、攀比和自我否定中回到自己', '当你反复对自己说“我做不到”“现在太晚了”“别人更好”时，这往往不是事实诊断，而是一个需要被看见的内在习惯。练习时，可以先列出最近一周最常用的三个借口，再把每个借口改写成一个愿望或下一步：不是“为什么我不能”，而是“为什么我想做”。把注意力从和别人比较，转向自己独特的经历、错误、教训和被人需要的部分。天赋识别不是证明自己比别人强，而是找到自己能持续带来价值的方式，并用更友善、具体的语言支持自己开始。', '["天赋识别", "自我认知", "避免比较焦虑", "自我对话", "成长路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 765, now()),
(100766, '从生活麻木到“人生存款”：用小行动唤醒天赋方向', '如果长期只是重复日常、拖延、缺乏方向，可能不是你没有天赋，而是生活进入了麻木模式。可以从24小时内的三笔“人生存款”开始：读一页与优势有关的书、完成一件该完成的小任务、主动与重要的人交流、为身体做一次照顾。重点不是立刻改变人生，而是每天做一点让自己更接近价值和关系的行动。连续记录这些小行动，会帮助你分辨哪些事让自己更有活力、责任感和意义感，从而成为天赋探索的线索。', '["心理教育", "天赋识别", "行动激活", "意义感", "成长路径", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 766, now()),
(100767, '天赋不是职位：寻找“最小努力也能做得更好”的自然优势', '天赋不等同于工作头衔、职业身份、兴趣热情或已经学会的技能。一个可靠线索是：哪些事情你相对不费力，却常常做得比自己预期更好，并且别人也会把你和这种能力联系起来？它可能是解决问题、调停冲突、连接资源、鼓励他人、和孩子沟通、设计、服务或组织活动。练习时写下三类证据：自己做起来顺手的事、别人反复称赞你的事、换到不同场景仍会出现的能力。这样能避免把天赋锁死在某个岗位上。', '["天赋识别", "优势发展", "自我认知", "职业探索", "能力迁移"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 767, now()),
(100768, '为优势选择合适载体：别急着坐上不适合当下的“天赋之车”', '发现优势后，还需要为它选择合适的承载场景。一个会做饭的人不一定马上开餐馆，一个善于教学的人也不一定只能在学校任教；同一份天赋可以先通过兼职、志愿服务、小项目、学习平台或团队角色运转起来。练习时问自己：我最终想去哪里？下一站是什么？现在能安全练习的载体是什么？这个载体会提升我的天赋，还是消耗我？合适的环境会让优势被看见、被练习、被反馈；不合适的环境则可能让人误以为自己没有天赋。', '["环境匹配", "优势发展", "职业探索", "成长路径", "天赋识别", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 768, now()),
(100769, '把天赋变成可被信任的呈现：用真实评估完善你的“个人包装”', '所谓包装不是伪装，而是让天赋更容易被他人信任和合作。它包括守时、坦诚、沟通清楚、愿意学习、能承认短板，也包括把优势放进可持续的工作方式里。可以做一次真实评估：哪些行为限制了我？我最常被夸奖的技能是什么？哪些弱点反复被提醒？我需要学习、找人协作，还是建立新习惯？当你愿意把“我就是这样”改成“我可以练习”，天赋会从模糊的潜力，逐渐变成别人看得见、愿意托付的能力。', '["优势发展", "自我评估", "成长路径", "习惯养成", "反馈", "合作能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 769, now()),
(100770, '失败是反馈而不是身份：从每次受挫中提取下一版计划', '害怕失败很常见，但失败不必被理解成“我不行”的证明。更有帮助的提问是：这次具体哪里没有奏效？我缺少资源、练习、计划、团队，还是时机判断？下一次可以删掉什么、保留什么、补上什么？把失败当作反馈，能减少羞耻感，也能帮助优势发展得更成熟。天赋成长往往需要许多次试错，重要的是不让一次挫折定义自己，而是带着新的计划回到练习中。', '["心理教育", "失败复盘", "成长型思维", "优势发展", "情绪调节", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 770, now()),
(100771, '把大愿望拆成可练习的下一步：目标要服务于天赋而不是制造焦虑', '有愿望并不等于要立刻完成巨大转变。更稳的做法，是把愿望拆成精确、可衡量、可实现、相关、有时间边界的小目标，并持续问：这个目标和我的天赋、生活责任、真实条件是否相连？不同人生阶段的人节奏不同，不必拿自己的进度和别人比较。即使今年只能前进很小一步，只要方向和价值一致，也是在积累。记录进展、庆祝小完成，会让成长从压力清单变成可持续的练习路径。', '["成长路径", "目标设定", "避免比较焦虑", "行动计划", "优势发展", "自我支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 771, now()),
(100772, '建立“推车者”支持系统：让同行者帮你补能而非拖垮你', '成长不是单枪匹马完成的，但也不是把所有人都带上车。可以梳理身边的人：谁会鼓励你、提供信息、帮你修正计划、照顾现实资源？谁只是消耗你、否定你、把自己的焦虑倒给你？支持系统的意义不是替你完成任务，而是在你拉绳子时为车轮上油、提醒方向、补充能量。练习时列出三类人：能支持我的人、需要设边界的人、我可以主动求助的人。这样能让天赋发展有更安全的关系环境。', '["支持系统", "环境匹配", "关系边界", "成长路径", "自我支持", "求助能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 772, now()),
(100773, '用“卷尺评估”看见优劣势：把自我认识变成发展策略', '优势识别需要热情，也需要客观测量。可以把能力分成知识类技能、通用类技能和性格类品质，再分别标注“强项、良好、熟练、有待提高”。同时请可信任的朋友、同事或导师从人际和工作两个角度给反馈。听到不舒服的评价时，先把它当作学习资料，而不是人格判决。最后选择一到三个最值得强化的优势，以及一到两个会阻碍发展的短板，制定具体练习或合作策略。', '["优势识别", "自我评估", "反馈", "成长路径", "能力发展", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 773, now()),
(100774, '重塑不是推翻自己：把旧经验迁移到更广阔的新场景', '当环境变化或旧路径受限时，重塑自己不等于否定过去，而是把已有经验换一种方式使用。先写下与天赋相伴的技能：你会组织、表达、连接、服务、创作、解决问题，还是理解他人？再思考这些能力能否进入新平台、新人群、新角色。关键是“执着而不执迷”：保留自己的根与优势，同时允许形式更新。这样可以减少从零开始的恐惧，把改变看成能力迁移和长期练习，而不是一次性冒险。', '["能力迁移", "成长路径", "环境匹配", "优势发展", "自我认知", "适应变化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 774, now()),
(100775, '用拒绝保护天赋：把时间和能量留给对的机会与关系', '并不是每个机会、请求或关系都适合你。学会拒绝，是为了让天赋在对的时间、地点和事情上被使用，而不是被过度消耗。面对一个请求，可以问：它让我更接近重要目标吗？它会提升我的天赋吗？它是否与当前责任冲突？双方是否都有合理收益？我是否得到应有回报？拒绝不等于自私，也不等于否定别人；它是一种边界练习，让你承认自己不是万能的，并把能量用于长期重要的方向。', '["边界感", "天赋保护", "能量管理", "环境匹配", "成长路径", "自我支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 775, now()),
(100776, '天赋不是越用越硬扛：用生活平衡和分享维持长期生命力', '长期发展优势，不能只靠工作投入和意志力。需要把重要关系、身体、心理、财务与精神支持纳入生活系统；休息、运动、求助、预算、与亲近的人分享成果，都是让天赋可持续的底盘。当压力大到无法向亲友倾诉时，寻求专业心理帮助也是对自己负责。天赋最终也会指向贡献：把经验、资源或方法分享给他人，能让能力从自我证明转向关系和价值连接。', '["生活平衡", "心理教育", "优势发展", "身心健康", "支持系统", "价值贡献"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 776, now()),
(100777, '把内疚从自责改写成补偿行动', '内疚有两类：一种提醒你承担责任，另一种把你绑在已经无法改变的过去。减少纠结的关键不是反复审判自己，而是把内疚翻译成三个问题：我具体做了什么？我能补偿、道歉或调整的最小行动是什么？哪些结果已经不在我控制范围内？如果确有伤害，写下一个可观察的修复承诺；如果事情已不可逆，练习把“我怎么会这样”改成“我已经看见代价，下一次我会怎样做”。', '["减少纠结", "内疚处理", "关系修复", "小步行动", "自我宽恕"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 777, now()),
(100778, '遗憾反刍的止损：回到今天能做的一件事', '遗憾会让大脑不断播放“如果当时……”。这种复盘只有在带来新信息时才有用；如果它只是重复同一段自责，就需要止损。可以写下四栏：遗憾事件、我真正学到的一条经验、今天能做的一个微动作、一个需要承认不可控的部分。把能改变的放进行程，把不能改变的交给接纳。这样做不是忘记过去，而是不再让过去持续消耗今天的选择能力。', '["减少纠结", "反刍思维", "接纳过去", "当下行动", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 778, now()),
(100779, '恐惧不是裁判：先命名，再做最小安全行动', '恐惧常伪装成“我还没准备好”“肯定会失败”“这样太危险”。先不要急着相信或压制它，而是给它命名：我是在担心被拒绝、担心失控、担心后悔，还是担心伤害别人？再区分事实和想象：目前有什么证据，缺什么信息？最后设计一个最小安全行动，例如询问一个人、查一个事实、尝试五分钟、先发一条确认信息。恐惧的任务是提醒你检查安全，不是替你取消人生。', '["恐惧管理", "情绪命名", "小步行动", "接纳不确定", "自我效能"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 779, now()),
(100780, '停止指责循环：把问题拆成三份责任', '当事情不顺时，指责能短暂保护自尊，却会让人失去下一步选择。可以把问题拆成三份责任：对方确实做了什么，环境或时机带来了什么限制，我可以为自己的反应和下一步承担什么。这样做不是替别人开脱，而是把注意力从“谁害我”转向“我还能影响哪一小块”。当你能说清自己的部分，纠结就不再只是情绪拉扯，而会变成边界、沟通或行动方案。', '["减少纠结", "责任区分", "关系沟通", "边界", "小步行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 780, now()),
(100781, '宽容练习：释放怨恨，不取消边界', '宽容不是说伤害没有发生，也不是要求你继续靠近伤害你的人。它更像是停止让怨恨每天继续占用注意力。练习时可以写下：我仍在抓住哪段情节？它让我付出了什么睡眠、关系或行动成本？如果不再反复审判，我今天能把精力用在哪里？必要时仍要保留边界、减少接触或寻求支持。宽容的重点是把自己从消耗中释放出来，而不是替伤害者免除责任。', '["宽容", "减少纠结", "自我关怀", "边界", "情绪释放"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 781, now()),
(100782, '信息不全时，别把最坏解释当事实', '很多纠结来自信息缺口：消息没回、结果未定、别人态度模糊，大脑会自动补上最坏解释。遇到这种情况，先暂停判断，做一次“事实—解释—缺口”记录：我确定知道什么？我脑中正在解释什么？我还缺哪条信息？下一步可以是询问、等待、查证或设定截止时间。接纳不确定不是放任不管，而是在信息不足时不让焦虑替你做结论。', '["接纳不确定", "事实核对", "减少纠结", "决策", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 782, now()),
(100783, '积极行动从一个两分钟善意开始', '当大目标动不了时，不必先等状态完美。选择一个两分钟内能完成的积极动作：给人发一句感谢，整理桌面一角，打开文档写标题，出门走到楼下，或向某人确认一个误会。它的意义不是证明你很优秀，而是把大脑从“我只能被事情推着走”切换到“我仍然能影响一小块现实”。小善意和小行动会降低无力感，也会让后续选择更容易出现。', '["小步行动", "积极行动", "自我效能", "减少纠结", "幸福练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 783, now()),
(100784, '活在当下的感官锚点：从存在回到生活', '人很容易被待办清单、他人期待和过去未来拉走，只是在“存在”，而不是在生活。可以用一个一分钟感官锚点把注意力带回现在：说出眼前3个颜色、听到2种声音、身体1处触感；再问自己“接下来一小时，什么事最值得我认真参与？”活在当下不是不规划，而是让计划回到真实体验和可执行行动，避免把生命交给自动驾驶。', '["当下练习", "幸福练习", "正念", "减少纠结", "注意力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 784, now()),
(100785, '冥想不是清空大脑，而是少给杂念加戏', '冥想练习中出现杂念很正常。目标不是把脑子变空，而是看见念头经过时不继续追着演。可以把念头轻轻命名为“计划”“担心”“回忆”“评价”或“比较”，然后把注意力带回呼吸、脚底或心口。每次回来都算一次练习，而不是失败。对容易纠结的人来说，这能训练一个重要能力：想法出现了，但我不必立刻相信、辩论或执行它。', '["冥想", "正念", "情绪命名", "减少纠结", "自我观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 785, now()),
(100786, '低落时的感恩清单：把注意力拉回可用资源', '感恩不是否认痛苦，也不是强迫自己开心。它是一种注意力训练：当一件坏事占满视野时，提醒自己现实中仍有资源。低落时写下三项具体内容：今天仍然支持我的人或条件、一件没有变糟的事、一个我可以继续使用的能力。写完后再回到问题本身，通常会更稳一些。感恩练习的目标不是“别难过”，而是让你在难过中仍能看见可依靠的东西。', '["幸福练习", "感恩", "情绪调节", "资源觉察", "自我关怀"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 786, now()),
(100787, '写一封不一定寄出的信，安放未完成情绪', '有些话无法当面说：告别、道歉、感谢、愤怒、委屈或宽恕。可以写一封不一定寄出的信，把未完成情绪从脑内循环搬到纸面上。建议分四段：我想对你说的事实；这件事带给我的感受；我没有说出口的需要；从今天起我愿意如何照顾自己。写信的目的不是控制对方反应，而是让情绪有出口，让心里腾出更多空间给现在的生活。', '["书写疗愈", "减少纠结", "情绪释放", "自我关怀", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 787, now()),
(100788, '困难选择后的自我安顿：尽力、负责、允许未知', '困难选择不一定带来完美结果，也不应只用结果或他人的看法倒推自己错了。做完艰难决定后，可以复盘四件事：当时我知道哪些信息？我依据了什么价值和边界？我愿意为哪些后果负责？还有哪些结果本来就无法保证？这样的复盘能减少“如果当时”的折磨。成熟不是永远选对，而是在不确定中尽力选择、承担可承担的部分，并允许人生仍有未知。', '["接纳不确定", "决策复盘", "自我关怀", "减少纠结", "责任感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 788, now()),
(100789, '多重身份练习：不要把自己缩成一个标签', '当一个人把自己只理解成“某一种人”时，很容易把生活里的其他可能性关掉。你可以试着列出此刻同时拥有的多个身份：家人、朋友、工作者、学习者、某个城市的人、某种兴趣的爱好者、需要休息的人。冲突来临时，再问自己：现在被触动的是哪一个身份？还有哪些身份也值得被带进来？这样做不是否认真实处境，而是把“我只能这样反应”改成“我可以选择让哪一部分先发声”。', '["身份认同", "多重身份", "自我觉察", "非二元视角", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 789, now()),
(100790, '关系冲突中，先把“你是哪类人”换成“你此刻在乎什么”', '很多关系争执会从一件具体事，迅速升级成对人的定性：“你就是自私”“你们这种人都这样”。这种话会让对方进入身份防御，接下来讨论的就不再是问题，而是谁被误解、谁被否定。降级的做法是把身份判断退回到具体关切：这件事里你最在乎什么？你担心失去什么？你希望我看见你哪一部分？当谈话回到需要、影响和下一步行动，双方才更容易从互相贴标签回到共同解决。', '["关系沟通", "冲突降级", "身份防御", "标签化", "需要表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 790, now()),
(100791, '被贴标签时，分清“事实不准”和“把我说成全部”', '被别人贴标签时，痛苦常来自两层：一是对方描述的事实可能不准确，二是对方把某个描述当成了你的全部。回应时可以分别处理：先澄清事实，例如“这件事的经过不是这样”；再保护完整自我，例如“即使我这里做得不好，也不能代表我整个人都是这样”。这种表达既不回避责任，也不接受被单一标签吞没。它能帮助你把谈话从人格审判拉回具体事件、具体影响和可修复的行动。', '["标签化", "身份认同", "关系沟通", "自我保护", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 791, now()),
(100792, '群体归属有两面：给人力量，也可能制造排斥', '家庭、团队、社群和文化背景能给人温暖、资源和安全感，这是身份认同积极的一面。但同一种归属也可能把世界切成“我们”和“他们”，让人更容易忽略外部人的真实需要。判断一个群体身份是否正在变窄，可以问三个问题：它是否让我更能照顾身边的人？它是否允许我看见外部人的普通人性？它是否允许成员有不同想法？如果答案越来越是否定，就需要放慢群体情绪，重新加入事实、边界和共情。', '["群体归属", "社会心理", "冲突降级", "非二元视角", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 792, now()),
(100793, '从对立身份回到非对立身份：给冲突找第三个入口', '冲突升级时，人们常只看见一组对立身份：家长和孩子、领导和员工、老成员和新成员、我方和对方。可以试着寻找不直接对立的身份入口：我们也是同一个家庭里想减少伤害的人、同一个项目里要交付结果的人、同一段关系里都需要被尊重的人。第三个入口不是让分歧消失，而是给谈话换一个站位：先确认共同身份和共同目标，再回到分歧本身，讨论哪些行为需要调整。', '["冲突降级", "非二元视角", "关系沟通", "共同目标", "身份认同"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 793, now()),
(100794, '身份不是命运：选择优先级，比寻找唯一答案更重要', '我们无法随意选择所有身份，出身、环境和别人眼光都会带来限制；但这不等于身份完全没有选择空间。更现实的问题是：在这个场景里，哪一种身份最需要被优先照顾？例如一次家庭争执中，你既是子女，也是成年人，也是需要边界的人；一次职场冲突中，你既是员工，也是合作者，也是有专业判断的人。把身份看成“可排序的多重关系”，能减少宿命感，让人从“我就是这样”回到“我此刻选择怎样回应”。', '["身份认同", "选择", "自我觉察", "心理灵活性", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 794, now()),
(100795, '少用“你们这种人”：单一身份叙事会放大敌意', '“你们这种人”“他就是那一类”这类句子，会把一个具体的人压缩成一个群体标签，也会让听者觉得自己必须为整个群体辩护。冲突降级时，可以把语言改成三层：具体的人、具体情境、具体行为。比如把“你们都不负责任”改成“昨天约定的时间没有完成，我感到不安，因为这影响了后续安排”。越能减少宏大标签，越容易让对方回应真实问题，而不是进入对抗姿态。', '["标签化", "冲突降级", "关系沟通", "非暴力沟通", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 795, now()),
(100796, '文化尊重不是把人固定在传统里，而是支持有意识的选择', '尊重一个人的文化背景，不等于要求他永远按照原来的传统生活。真正的尊重包含两部分：允许一个人保留重要的传承，也允许他在获得更多信息、经验和思考后调整自己的生活方式。在家庭或亲密关系中，可以把“我们家一直这样”改成“这个传统对我们意味着什么？你现在愿意保留哪部分、调整哪部分？”这样的问法能减少身份压迫，也能让文化成为连接资源，而不是束缚人的命令。', '["文化自由", "身份认同", "家庭沟通", "非二元视角", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 796, now()),
(100797, '多元文化不是多组标签并排，而是让人跨身份相遇', '有时人们以为多元就是把每个人放回自己的社群盒子里：你代表这个群体，我代表那个群体。这样看似尊重差异，实际上仍可能把人固定在单一身份里。更有帮助的多元视角，是承认一个人同时有语言、职业、兴趣、价值观、家庭角色和公民角色等多种关系。关系沟通中，可以多问“除了这个背景，你还有哪些重要经验？”当人被允许跨身份表达，误解和防御通常会下降。', '["多元文化", "身份认同", "社会心理", "关系沟通", "非二元视角"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 797, now()),
(100798, '非此即彼会收窄判断：多重忠诚可以同时存在', '很多内心冲突来自“如果我在乎A，就等于背叛B”的二选一想法。比如在家庭中保持边界，不等于不爱家人；重视个人成长，不等于放弃关系；关心更大的社会议题，也不等于忽视身边责任。多重身份的思路提醒我们，忠诚可以有层次和场景，不必总是互相消灭。遇到拉扯时，可以写下：我同时在乎什么？这一次哪个优先？被暂时放后的部分，之后如何补上？', '["非二元视角", "身份认同", "价值澄清", "关系沟通", "心理灵活性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 798, now()),
(100799, '高唤起冲突里，先恢复思考自由，再决定站队或回应', '当愤怒、羞耻或群体压力很强时，人会更容易只看见一个身份：受害者、敌人、背叛者、外人。此时先不要急着做关系结论。可以暂停几分钟到二十分钟，做三个动作：描述身体状态，写下对方至少三个非冲突身份，写下这件事中可以核对的事实。等神经系统稍微降温后，再决定要表达边界、提出请求还是退出谈话。恢复思考自由，是防止身份冲突升级的重要步骤。', '["冲突降级", "情绪调节", "身份认同", "关系沟通", "高唤起"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 799, now()),
(100800, '不要用宏大分类解释一个具体的人', '文化、性格、地域、职业和家庭背景都能帮助我们理解人，但任何一个分类都不能直接替代对具体人的观察。若你发现自己很快得出“他这种背景的人就是这样”的结论，可以暂停并补问三个问题：我看到的具体行为是什么？还有哪些情境压力可能影响了他？有没有反例说明这个标签并不完整？这不是要求你放弃判断，而是让判断更慢、更准，也更不容易把误解升级成敌意。', '["标签化", "社会心理", "非二元视角", "认知偏差", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 800, now()),
(100801, '童话不是说教：它给孩子一个安全排练内心冲突的舞台', '童话的价值不在于把道理直接灌输给孩子，而在于提供一个可想象、可重复、又与现实保持距离的心理舞台。孩子会把害怕、嫉妒、贪心、想被爱、想反抗等感受投射到角色身上：有时认同主角，有时害怕女巫，有时又被诱惑吸引。亲子共读时，成人不必急着解释“正确答案”，更适合在孩子发问时温和回应：你觉得他为什么这样做？如果是你会怎么办？这样，故事会帮助孩子把混乱情绪变成可谈论、可整理、可重新选择的自我叙事。', '["童话心理", "儿童发展", "自我叙事", "情绪整理", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 801, now()),
(100802, '女巫原型：把可怕冲动放进故事，孩子才有办法面对它', '女巫、恶王后、怪物或吃人的巨人，不宜简单理解成现实里的某个坏人。它们更像故事把孩子难以承认的冲动外化出来：想独占、想报复、想贪吃、想逃避责任、想被所有人看见。孩子听到“坏力量”被识别、限制或战胜，会得到一种安定感：我有坏念头，并不等于我是坏孩子，也不等于会被父母抛弃。成人可以借故事帮助孩子区分“感受可以被理解”和“行为需要有边界”，让善恶理解从羞耻转向自我管理。', '["童话原型", "善恶理解", "性格形成", "恐惧处理", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 802, now()),
(100803, '可怕情节的作用：在成人陪伴下练习处理恐惧，而不是删光恐惧', '许多童话包含森林、死亡、抛弃、吞食、追赶等惊险情节，看似残酷，却常触及儿童本来就会有的深层恐惧：怕父母离开、怕被惩罚、怕自己不够好、怕陌生世界。关键不在于把所有可怕内容删除，而是让孩子在可承受的故事距离里，看到主角害怕、求助、想办法、最后走出来。成人讲述时要观察孩子状态，必要时停下来抱一抱、解释“这是故事里的危险，你现在是安全的”，让恐惧被陪伴，而不是被否认。', '["恐惧处理", "亲子陪伴", "儿童安全感", "童话心理", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 803, now()),
(100804, '森林、豆茎与黄砖路：分离成长从跨过熟悉边界开始', '童话里的森林、豆茎、黄砖路和陌生国度，都在讲一个发展任务：孩子必须从熟悉环境走向未知，才会发现新的能力。跨出边界并不意味着不要父母，而是带着被爱的底气，学习探索、判断、求助和返回。孩子上幼儿园、搬家、独睡、结交新朋友，都会经历类似的“进入森林”。家长可以把故事变成过渡语言：你现在也在走自己的黄砖路，我们会在你需要时支持你，但有些路要你一步步试出来。', '["分离成长", "儿童发展", "安全基地", "自我效能", "童话原型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 804, now()),
(100805, '糖果屋与大野狼：用故事谈欲望、饥饿和身体边界', '《韩塞尔与葛蕾特》和《小红帽》把“吃”写得很夸张：糖果屋、吞食、被吃掉、贪得无厌的狼。对孩子来说，这些情节可转化为关于身体和欲望的教育：想吃、想要、想靠近都很正常，但需要知道什么时候够了、哪里危险、谁可以靠近自己的身体。成人不必羞辱孩子的食欲或好奇心，而可以讨论：饿和馋有什么不同？如果一个人用好吃的诱惑你，你可以怎么保护自己？这样能把欲望教育转成边界练习。', '["身体边界", "欲望管理", "儿童发展", "亲子沟通", "恐惧处理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 805, now()),
(100806, '魔镜与玻璃棺：外貌焦虑背后常是“我是否值得被爱”', '《白雪公主》里的魔镜、束带、梳子、毒苹果和玻璃棺，都围绕“被看见”和“外貌价值”展开。孩子在意漂亮、衣服、身高或别人评价时，成人不必急着批评虚荣，而应看见背后的需要：我会不会被喜欢？我是不是不如别人？我除了外表还有什么价值？共读时可以问：为什么她一次次忘记警告？如果大家只看见她漂亮，会漏掉她哪些部分？这能帮助孩子把自我价值从单一外貌，扩展到能力、善意、勇气和选择。', '["外貌焦虑", "自我价值", "童话心理", "儿童发展", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 806, now()),
(100807, '灰姑娘的树、玩偶和红鞋：孩子把照顾者的爱带在心里', '许多童话里的树、玩偶、手帕、缎带、红鞋和小动物，都像孩子的安抚物：它们在主角孤单、受欺负、离家或失去母亲时，继续提供支持。心理教育上，这可以帮助家长理解孩子为什么依恋某条毯子、某个玩偶或某件旧衣服。那不是“幼稚”，而是孩子在练习把照顾者的爱内化成自己的安全感。成人可以尊重这些物品，同时慢慢引导孩子说出：它陪你度过了什么？当它不在身边时，你还可以怎样安慰自己？', '["安全感", "移情物品", "依恋", "分离成长", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 807, now()),
(100808, '嫉妒与手足竞争：先承认“我也想被选中”，再学习合作', '灰姑娘故事反复出现继母、姐妹、舞会和鞋子，本质上触及孩子常见的嫉妒：为什么别人被看见？为什么他拥有我没有的东西？为什么父母好像更喜欢他？嫉妒并不等于坏，它常说明孩子渴望爱、位置和公平。亲子沟通中，可以先接住“你也想被选中”的感受，再讨论行为边界：嫉妒时可以说出来、请求陪伴、表达不公平，但不能羞辱、破坏或伤害别人。故事让竞争感变得可命名，也让孩子学习从比较走向合作。', '["嫉妒", "手足关系", "性格形成", "亲子沟通", "情绪教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 808, now()),
(100809, '说谎、承诺与身份：故事帮助孩子理解信任怎样被建立或破坏', '《牧鹅姑娘》《青蛙王子》《侏儒怪》等故事，把说谎、冒名、违背承诺和交易后果写得很醒目。对孩子来说，重点不是把“说谎”贴成永远不可饶恕的标签，而是理解：有些话会保护别人，有些谎会剥夺别人位置、伤害信任；承诺不是为了讨好当下，而是会影响后来的关系。成人可以问：如果你是被骗的人，会有什么感觉？如果已经说谎，怎样修复？这样能把诚信教育从惩罚，转为责任、同理和关系修复。', '["诚信", "身份认同", "关系修复", "儿童发展", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 809, now()),
(100810, '长发公主与小美人鱼：性好奇需要边界、节奏和可谈论的语言', '一些古老童话含有青春期、身体变化、亲密吸引和性好奇的线索。转化为 App 端心理教育时，不需要把性描写玄学化或恐吓化，而应强调：好奇和吸引本身不是罪，真正需要学习的是年龄与成熟度、同意、秘密、身体自主和求助边界。孩子越容易从媒体接触零散信息，成人越需要用平实语言回应问题：什么触碰合适？什么秘密不该替别人保守？喜欢一个人时怎样保护自己？童话可成为温和开口，而不是羞耻来源。', '["身体教育", "青春期", "边界", "亲子沟通", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 810, now()),
(100811, '桃乐丝的伙伴：孩子缺的不是标签，而是可被唤醒的资源', '《绿野仙踪》里的稻草人、铁皮人和狮子都以为自己缺少头脑、心和勇气，但旅途中他们不断用行动证明这些资源已经存在。这个原型很适合亲子和自我成长场景：当孩子说“我笨、我没用、我胆小”时，成人不要急着反驳或贴标签，而可以带他回看具体证据：哪一次你想出了办法？哪一次你关心了别人？哪一次你害怕但仍然做了？成长不是突然变成另一个人，而是在任务中看见自己已有的能力。', '["自我效能", "资源取向", "性格形成", "自我叙事", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 811, now()),
(100812, '亲子共读童话：少解释、多提问，把故事变成孩子自己的成长语言', '童话最适合被当成对话入口，而不是成人单方面讲解的心理测验。孩子问“女巫为什么死”“杰克为什么偷琴”“白雪公主为什么开门”时，成人可以先邀请孩子想象，再补充一点点线索。好的问题包括：你最担心谁？你希望谁来帮忙？这个角色哪里像你？如果重讲结局，你会怎样安排？这样的共读能训练孩子表达感受、理解他人、区分事实与解释，也能让家庭沟通从说教转向共同探索。', '["亲子共读", "亲子沟通", "自我叙事", "心理教育", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 812, now()),
(100813, '情绪先命名：把“我很糟”拆成具体感受和强度', '低落时，大脑常把许多感受压缩成一句“我很糟”。更有帮助的做法，是先把情绪拆开并标注强度：悲伤 70 分、焦虑 50 分、羞耻 40 分，或疲惫、失望、愤怒、孤独各占多少。情绪命名不是评判自己，而是在混乱中建立一张地图。记录后再问：刚才发生了什么？我脑中最刺痛的想法是哪一句？下一步只需要照顾哪一种情绪？', '["好心情", "情绪命名", "情绪调节", "自我觉察", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 813, now()),
(100814, '自动想法不是事实：先写下脑内第一句话', '情绪突然下坠时，通常先出现一个很快、很像事实的自动想法，例如“我肯定完了”“他们都讨厌我”“我没有价值”。练习的第一步不是立刻说服自己积极，而是把这句话原样写下来，并在旁边标注：这是一个想法，不是已经被证明的事实。然后补三栏信息：支持它的证据、反对它的证据、一个更平衡的说法。这样做能让 App 引导用户从被想法带走，转为观察想法。', '["好心情", "自动想法", "认知重评", "情绪调节", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 814, now()),
(100815, '给想法贴思维标签，而不是给自己贴人格标签', '当脑中出现“我就是失败者”“这件事全毁了”时，可以练习给想法贴标签，而不是给自己贴标签。常见标签包括：非黑即白、以偏概全、过滤负面、否定积极、读心、灾难化、情绪化推理、应该化、人格贴标签、过度归责。标出扭曲类型后，再把句子改成更具体的描述：不是“我没用”，而是“这次准备不足，我可以补一个步骤”。', '["好心情", "认知扭曲", "认知重评", "自我接纳", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 815, now()),
(100816, '三栏情绪记录：情境、想法和更客观的回应', '适合 App 做成每日小练习：第一栏写触发情境，只写可观察事实；第二栏写自动想法和情绪强度；第三栏写更客观、更有帮助的回应。回应不需要强行乐观，只要比原想法更完整，例如“我这次表现不好，但不能推出我永远不行”“对方没回消息可能有多种原因”。记录完成后，再重新给情绪打分，观察强度是否有变化。', '["好心情", "情绪记录", "认知重评", "CBT", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 816, now()),
(100817, '低落时先做一点：用小行动松动无力感', '低落会让人等待“有动力了再行动”，但动力常常是在行动之后才回来。可以把任务缩到非常小：洗一个杯子、出门走三分钟、打开文档写一句、给朋友发一个表情。目标不是立刻变好，而是让身体获得“我还能影响一点现实”的经验。完成后记录实际感受：比开始前轻松 5 分也算有效；如果没有变化，也只说明需要换一个更小或更合适的动作。', '["好心情", "低落应对", "行为激活", "情绪调节", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 817, now()),
(100818, '快乐与成就双评分：把日常微小回报找回来', '心情低落时，人容易觉得“什么都没意思、什么都没做成”。可以把一天中的活动列出来，每项分别给两个分数：快乐感 0-10 分，成就感 0-10 分。不是为了证明今天很好，而是寻找被低落滤镜忽略的小回报：洗澡后的清爽、整理桌面后的秩序、和人说话后的连接。连续记录几天后，优先增加那些分数虽小但稳定的活动。', '["好心情", "积极情绪", "行为激活", "成就感", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 818, now()),
(100819, '自我价值不等于一次表现：把失败改写成事件', '一次失败、拒绝或失误，只能说明某件事的结果，并不能定义整个人。App 可以引导用户把“我是失败者”改写成事件句：“这次面试没有通过”“这次沟通没有表达清楚”。再补三个问题：哪里是我能学习的？哪里受环境和他人影响？如果朋友遇到同样情况，我会怎样评价他？这样既不逃避责任，也不把一次结果扩大成自我否定。', '["好心情", "自尊", "认知重评", "失败应对", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 819, now()),
(100820, '把“应该”改成选择：减少内疚式自我逼迫', '“我应该一直坚强”“我必须让所有人满意”容易把行动变成压力和内疚。练习时先圈出句子里的“应该、必须、不得不”，再改成选择语言：我希望、我可以、我决定、我愿意付出这个代价。改写后继续问：这个要求来自我的价值，还是来自害怕被否定？有没有更温和但仍负责任的做法？选择式表达能保留行动力，同时减少自我攻击。', '["好心情", "内疚", "应该语句", "认知重评", "自我关怀"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 820, now()),
(100821, '孤独时的连接任务：从等别人靠近到发出小信号', '孤独会让人更容易相信“没人需要我”，也更容易退回安全但封闭的位置。可以把“我很孤独”转成一个很小的连接任务：给一个安全的人发一句近况，约一次短时间散步，在群里回应一个话题，或把需要说成具体请求。任务重点不是马上获得亲密关系，而是打破完全隔离。完成后记录：我发出了什么信号？对方真实反应是什么？和我预想的一样吗？', '["好心情", "孤独", "关系支持", "行为激活", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 821, now()),
(100822, '生气前先降温：看见受伤、期待和边界', '愤怒常常不是单一情绪，下面可能有受伤、失望、害怕被忽视，或边界被侵犯。回应前先做三步：给身体降温，暂停争辩；写下“我真正受伤的是……”；把攻击句改成边界句，例如“当 X 发生时，我感到 Y，因为我需要 Z；下次请具体做 A”。这不是压抑愤怒，而是把愤怒从伤人或伤己的冲动，转成更清楚的需求表达。', '["好心情", "愤怒管理", "关系支持", "边界", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 822, now()),
(100823, '责任分栏：区分我的部分、别人的部分和不可控部分', '心情不好时，人容易把所有问题都归到自己身上，或把所有责任都推给别人。责任分栏可以帮助恢复现实感：第一栏写我确实能负责的部分，第二栏写他人的选择和责任，第三栏写天气、时机、规则、运气等不可控因素。随后只为第一栏制定一个小行动。这样既避免过度自责，也避免陷入抱怨，让精力回到可以改变的地方。', '["好心情", "责任分栏", "认知重评", "内疚", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 823, now()),
(100824, '完美主义实验：用足够好替代必须满分', '完美主义会把“做得不够好”解释成“我不够好”，于是人要么过度用力，要么拖着不开始。可以做一个小实验：选择低风险任务，只做到 70 分就提交或结束，然后观察真实后果。记录三件事：我担心会发生什么？实际发生了什么？别人是否真的因此否定我？练习的目标不是变随便，而是让大脑知道，足够好也能推进生活。', '["好心情", "完美主义", "行为实验", "认知重评", "拖延应对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 824, now()),
(100825, '绝望感来时缩短时间：只处理今天下一步', '绝望感会把未来压缩成一个结论：“永远不会好”。此时不适合要求自己想通人生，只需要把时间范围缩短到今天：接下来一小时我能不能喝水、吃点东西、联系一个人、离开危险环境、完成一个安全动作？如果出现伤害自己的冲动，先把自己交给现实支持：联系可信的人、专业热线或急救资源。重点是先活过这一段情绪浪潮，再谈长期问题。', '["好心情", "绝望感", "危机应对", "关系支持", "低落应对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 825, now()),
(100826, '给孩子安排活动，也给家庭留出可呼吸的时间', '有组织的课外活动能让孩子练习守时、合作、面对陌生成人、表达需求，也可能把家庭推入赶场、疲惫和冲突。给孩子选活动时，不必把“越多越好”当标准。更适合的做法是：保留一两项真正滋养孩子的活动，同时固定无安排的晚上、共同晚餐或亲子散步，让孩子既能发展技能，也能感到家不是永远的任务站。父母可以定期问：这项活动让孩子更有活力，还是让全家更紧绷？如果家庭关系开始为活动长期让路，就需要重新调整节奏。', '["童年发展", "家庭教养", "父母焦虑", "时间管理", "亲子关系", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 826, now()),
(100827, '自由玩耍不是放任：孩子也在同伴世界里学习', '孩子在没有成人全程指挥的玩耍中，也会发展真实能力：自己找伙伴、安排时间、发明规则、处理输赢、协商冲突，并在小范围挫折中练习复原。父母可以把重点放在“安全边界”而不是“全程管理”上，例如约定活动范围、回家时间、危险行为红线，再给孩子保留自己决定怎么玩的空间。这样做不是忽视孩子，而是承认儿童发展不只发生在课程、训练和作业里，也发生在院子、楼下、亲戚家和同伴游戏中。', '["童年发展", "自由玩耍", "家庭教养", "自主感", "同伴关系", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 827, now()),
(100828, '孩子的表达能力来自日常对话，而不只是语文成绩', '孩子能不能把想法说清楚，常常来自每天被怎样对话。父母多问“你怎么看”“你想怎么问”“你为什么这样选”，并认真听完孩子的回答，会让孩子练习组织观点、说明理由和提出请求。这样的对话不是让孩子和父母处处辩论，而是让孩子知道：自己的感受和意见可以被语言承载。可以从很小的场景开始练习，例如看医生前请孩子准备一个问题，和老师沟通前让孩子说出最想被理解的一点，家庭讨论时给孩子一个完整表达的轮次。', '["表达能力", "亲子沟通", "儿童语言", "家庭教养", "社会心理", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 828, now()),
(100829, '教孩子和老师、医生沟通：把需求说清楚是一种生活技能', '很多孩子在熟人面前很自在，到了老师、医生或教练面前就沉默，不一定是没有想法，而是缺少和机构中成年人沟通的脚本。父母可以提前和孩子排练三句话：我遇到的情况是……我想问的是……我希望得到的帮助是……也可以在见老师或医生后复盘：哪些话说清楚了，哪些下次可以再补充。把需求说清楚不是无礼，也不是要求特殊照顾，而是帮助孩子在规则场景里表达自己、理解对方，并逐渐学会为自己的学习、健康和安全负责。', '["表达能力", "学校互动", "亲子沟通", "家庭教养", "社会适应", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 829, now()),
(100830, '清晰边界加可协商空间：孩子需要既被照看也被尊重', '孩子既需要边界，也需要在边界内练习选择。安全、睡眠、尊重他人、按时上学等规则可以由父母清楚设定；穿什么、先做哪项作业、周末怎样安排一段自由时间，则可以留给孩子参与协商。边界不是为了压住孩子，而是让孩子知道世界有稳定结构；协商也不是让孩子说了算，而是让孩子学习表达理由、承担后果。家庭可以把规则分成三类：不可讨论的安全红线、可以商量的生活安排、孩子可以自主决定的小事。', '["边界", "家庭教养", "亲子沟通", "自主感", "规则感", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 830, now()),
(100831, '家庭作业不要变成亲子关系的唯一战场', '当父母把作业完全接到自己身上，孩子可能越来越依赖、抗拒或羞愧，亲子关系也容易被每天的催促和纠错吞没。更有保护性的做法是先分清角色：老师负责教学目标，孩子负责尝试和反馈，父母负责环境、节奏和情绪支持。可以用短时段学习、固定休息、先问孩子“你卡在哪里”、必要时向老师确认作业量和方法，而不是把每一道题都变成亲子拉锯。作业的目的不是证明父母够不够用力，而是帮助孩子逐步建立可持续的学习能力。', '["家庭作业", "亲子关系", "父母焦虑", "家庭教养", "情绪支持", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 831, now()),
(100832, '父母焦虑会把教育资源变成家庭压力', '信息、课程、人脉和个性化安排本来可以支持孩子，但当父母长期处在比较和担心中，资源也会变成压力源。父母越想为孩子扫清障碍，越容易把每个老师、每项活动、每次成绩都看成必须干预的信号。可以尝试把焦虑转化为选择：列出孩子真正需要的三类支持，区分“马上要处理的问题”和“只是别人家也在做的事”，再决定要不要投入时间和金钱。教育投入的核心不是不断加码，而是让孩子在稳定关系中获得适合自己的发展机会。', '["父母焦虑", "资源差异", "家庭教养", "教育压力", "亲子关系", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 832, now()),
(100833, '亲戚、邻居和手足关系也是儿童发展的资源', '儿童发展不只依赖课程和金钱，也依赖稳定的关系网络。和表亲玩、被哥哥姐姐照看、参加家庭庆祝、在邻里中认识可信任的大人，都能给孩子归属感、互助经验和照顾他人的机会。对很多家庭来说，这些关系是孩子情绪安全的重要来源。父母可以有意识地保留家庭仪式：一起吃饭、生日时被看见、固定探望亲友、让手足合作完成小任务。关系资源不能替代教育资源，但它能让孩子在成长中感到“我不是一个人”。', '["家庭环境", "关系资源", "手足关系", "亲属支持", "童年发展", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 833, now()),
(100834, '资源差异会影响机会，但不等于给家庭贴标签', '家庭能给孩子的支持，除了爱和努力，还包括时间、交通、居住空间、信息渠道、专业词汇、可求助的人、稳定收入和父母精力。资源少时，父母可能光是维持日常生活就已经很累，孩子也会更早意识到预算和选择的限制。理解这一点，不是为了比较谁更好，而是为了减少无效自责：有些困难不是家庭不爱孩子，而是可用资源不足。可以从“资源地图”开始：我们已有的支持是什么？最缺的是信息、时间、情绪还是具体服务？下一步能向谁求助？', '["资源差异", "家庭环境", "社会心理", "自我理解", "家庭教养", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 834, now()),
(100835, '家校沟通需要尊重，也需要可练习的提问脚本', '尊重老师不等于只能沉默，主动沟通也不等于指责学校。很多家长面对学校会担心“说错话”或“不懂规矩”，于是把困惑带回家独自承受。更稳妥的做法是准备具体、合作式的问题：孩子最近最需要练习什么？在家每天做哪一件事最有帮助？如果作业超过多少时间，是否需要记录并反馈？孩子在课堂上什么时候表现最好？这样的提问能把家校关系从互相猜测转向共同观察，也让孩子看到成年人可以用清楚、平和的方式解决问题。', '["学校互动", "家庭教养", "亲子沟通", "表达能力", "教育支持", "社会适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 835, now()),
(100836, '让孩子参与决定：被认真听见会形成自我效能', '当孩子参与评价活动、表达偏好、说明困难时，他会逐渐学习“我的观察有价值，我可以影响自己的生活”。这不是把最终决定完全交给孩子，而是在父母承担责任的同时，让孩子练习判断。比如试完一个兴趣班后，可以问：你喜欢什么？哪里不舒服？老师怎样帮助你？如果继续，需要你承担什么？父母再结合时间、费用和孩子状态做决定。被认真听见的孩子，更容易把自己看成主动参与者，而不是被大人安排和推着走的人。', '["自主感", "表达能力", "家庭教养", "亲子沟通", "儿童发展", "自我效能"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 836, now()),
(100837, '成人回看童年：看见自己被训练出的长处与缺口', '每个人的童年环境都会训练出一些能力，也可能留下某些不熟悉的场景。有人很会自娱自乐、照顾家人、在同伴中应变，却不习惯向权威提问；有人从小练习表达、规划和争取资源，却可能对松弛、等待或亲密陪伴感到陌生。成人回看童年时，不必急着责怪父母或否定自己，而是可以问：我的家庭让我擅长了什么？哪些能力当时没有机会练？现在我最想补上的一项生活技能是什么？这样回看童年，会把旧经验转化为自我理解和新的选择。', '["童年经验", "成人成长", "自我理解", "家庭环境", "社会心理", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 837, now()),
(100838, '温和纪律比恐惧更能建立安全感', '孩子需要规则，也需要在犯错后仍然感到关系是安全的。体罚、羞辱或威胁可能让孩子短期服从，却会增加害怕、隐瞒和亲子不信任。更稳定的纪律可以分三步：先让双方降温，避免在暴怒中处理；再用简短语言说清楚规则和影响；最后给出与行为相关、可执行的后果，例如修复、暂停、重新练习。父母不需要一次做到完美，但可以逐渐把“让孩子怕我”换成“让孩子知道规则、后果和我仍在这里”。', '["家庭教养", "儿童安全", "边界", "亲子沟通", "情绪调节", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 838, now()),
(100839, '不要把孩子的沉默误读成没有想法', '有些孩子在家里、球场或同伴中很有主意，到了课堂、诊室或陌生成人面前却变得安静。沉默不一定代表没有能力，也可能是环境让他不知道能不能说、该怎么说。父母和老师可以先降低表达门槛：允许孩子先写下来、用选择题回答、由父母代为开头，再逐步过渡到孩子自己说。也可以帮助孩子识别不同场景的表达规则：和朋友怎么说，和老师怎么说，和医生怎么说。孩子需要的不是被贴上“胆小”标签，而是可练习的表达通道。', '["表达能力", "儿童发展", "学校互动", "社会适应", "亲子沟通", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 839, now()),
(100840, '别急着分“好人坏人”：先看冲动、选择和约束', '把人简单分成“好人”和“坏人”，会让我们忽略更重要的问题：一个人有什么冲动，处在什么情境里，是否有能力暂停、承担后果、尊重他人。承认每个人都有阴暗面，并不是替伤害开脱，而是提醒自己少用身份审判，多看行为、选择、边界和修复能力。', '["阴影面", "自我觉察", "非二元视角", "责任感", "社会心理", "行为选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 840, now()),
(100841, '阴影面自查：我想过，不等于我必须去做', '嫉妒、报复、控制、攻击等念头出现时，不必立刻把自己判成“很坏的人”。更有用的做法是把它当作内在警报：我被什么触发了？我真正想保护什么？我能不能把冲动留在想象里，改用暂停、表达需要、离开现场、求助或修复来回应？成熟不是没有阴影，而是能在阴影和行动之间放进选择。', '["阴影面", "冲动管理", "自我觉察", "责任感", "情绪调节", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 841, now()),
(100842, '情境会放大阴暗面：把良知交给群体之前先暂停', '人在群体、灾难、强压力或“大家都这样”的气氛中，更容易把个人责任感交出去。自查可以问三句：如果只有我一个人，我还会这样做吗？如果被影响的是我在乎的人，我还会同意吗？如果明天要公开解释，我能不能承担？这些问题能把被情境带走的良知重新拉回自己手里。', '["社会心理", "情境影响", "群体压力", "责任感", "自我觉察", "边界感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 842, now()),
(100843, '解释伤害的原因，不等于替伤害开脱', '理解一个人为什么会伤人，可以帮助我们识别风险、减少复发、找到干预点；但“我有创伤”“我太痛苦”“我控制不住”并不自动取消责任。关系修复需要同时放下两个极端：只用道德标签羞辱整个人，或只用心理原因抹掉受害者的影响。更稳妥的表达是：我愿意理解原因，也要求停止伤害、承担后果和具体改变。', '["责任感", "关系修复", "非标签化", "心理教育", "边界感", "同理但不纵容"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 843, now()),
(100844, '投射会把“不敢承认的自己”放到别人身上', '当我们特别想把某个人或某类人说成“全坏、恶心、不可理喻”时，关系里可能已经有投射：我把自己不愿承认的羞耻、恐惧、攻击性或欲望放到了对方身上。自查不是否认对方真的可能有问题，而是先把事实、解释和情绪分开：我看到的证据是什么？我害怕承认自己哪一部分？我有没有把对方去人性化？', '["投射", "阴影面", "自我觉察", "去标签化", "关系沟通", "冲突降级"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 844, now()),
(100845, '被拒绝后的边界：停止追逐比证明爱更重要', '喜欢一个人、想靠近一个人，并不等于拥有进入对方生活的权利。被拒绝后反复联系、监视、堵门、威胁、用痛苦要求对方回应，核心已经不是爱，而是控制和边界混淆。对自己来说，练习把“不甘心”带回自我照顾和求助；对被纠缠的一方来说，少做情绪谈判，保存记录，告知可信任的人，并把安全放在解释关系之上。', '["边界感", "亲密关系", "控制", "自我保护", "关系安全", "拒绝处理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 845, now()),
(100846, '道歉循环不是安全：看对方是否真正停止伤害', '有些关系里，伤害之后会出现温柔、道歉、解释身世和“我太爱你才这样”，随后又把责任推回受害者身上。判断安全不能只看对方是否后悔，而要看是否停止越界、是否承认影响、是否接受外部约束、是否让你拥有离开的自由。真正的修复会减少恐惧，反复的道歉循环只是在延长控制。', '["关系安全", "边界感", "责任感", "关系修复", "控制识别", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 846, now()),
(100847, '权力位置里的边界：负责的人先守住界限', '在咨询、教育、医疗、管理、照护或任何帮助关系里，权力更大、资源更多、角色更专业的一方，承担更高的边界责任。产生好感、依赖、欣赏或被需要感并不罕见，但它们应该被用来理解关系动力，而不是满足自己的私欲。脆弱的一方不是越界的责任人；真正专业和成熟的爱护，是保护对方的自主与安全。', '["边界感", "权力关系", "责任感", "信任关系", "关系安全", "助人伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 847, now()),
(100848, '当组织要求你交出判断力，要重新拿回责任', '归属感会给人安全，但如果一个团体要求你只忠于领袖、切断外部关系、把外界都看成敌人、用疲惫和恐惧压低你的判断力，就要警觉。健康的组织允许提问、休息、离开和保留个人责任；危险的组织常把安全感换成依附，把复杂世界简化成“我们全对、他们全坏”。', '["社会心理", "群体压力", "责任感", "边界感", "归属感", "非二元视角"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 848, now()),
(100849, '工作委屈不要变成复仇剧本：先找出口和支持', '被裁员、被否定、长期不公平或职业失败，容易让人觉得“我什么都没有了”。这时最危险的不是愤怒本身，而是把全部自我价值绑在一个岗位、一位上司或一次结果上，再把痛苦解释成“必须让谁付出代价”。可以先把委屈写成具体事件、损失、需要和可求助对象，扩大生活支点，寻求协商、法律、心理或社群支持。', '["职场心理", "愤怒管理", "责任感", "自我价值", "关系修复", "求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 849, now()),
(100850, '创伤记忆需要被尊重，也需要保留核对空间', '一个人讲述创伤时，首先需要被尊重和认真对待；同时，记忆并不是录像，时间、暗示、期待和后来获得的信息都可能影响细节。关系中的稳妥做法，是把“我感到害怕/羞耻/愤怒”与“我确定发生了什么”分开放：情绪可以先被照顾，事实可以慢慢核对，避免用单一症状替复杂经历下结论。', '["创伤知情", "记忆", "事实解释分离", "自我觉察", "心理教育", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 850, now()),
(100851, '心理健康不是没有阴暗面，而是能修复和升华', '心理健康不是永远温和、正确、没有嫉妒和攻击性，而是能守住个人界限，承认自己也有阴暗冲动；伤到别人时会遗憾并愿意弥补；欲望得不到满足时能延迟、调节和求助；把攻击性能量转成竞争、创造、保护和建设。真正的成熟不是把阴影删掉，而是让阴影不再替你做决定。', '["心理健康", "阴影面", "自我觉察", "关系修复", "冲动管理", "升华"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 851, now()),
(100852, '困难选择前，先分清三种公平语言', '很多两难选择卡住，并不是因为你“不够理性”，而是因为不同价值在同时说话。一个决定可能同时牵涉三种语言：结果上能否减少伤害、选择上是否尊重每个人的自主、品格上是否符合你想成为的人。关系里也一样：分手、借钱、照顾家人、职业取舍，都不要急着用单一标准判输赢。可以先写下：这件事里谁会受益或受伤；谁的选择权被压缩；我希望自己在这段关系中练习怎样的诚实、勇气和善意。把价值拆开，常比争一个“绝对正确答案”更能带来清醒。', '["价值澄清", "两难选择", "关系决策", "公平感", "自我觉察", "沟通决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 852, now()),
(100853, '多数人的舒服，不该自动覆盖一个人的边界', '“这样对大家都好”有时是真诚的协调，也可能变成忽略少数人感受的理由。关系中的公平，不只是把总快乐加起来，还要看有没有人被迫承担过高代价。例如家庭安排、团队分工或亲密关系里的牺牲，如果总是让同一个人沉默、忍耐、让步，就算表面和谐，也会慢慢积累不公。做决定时可以多问一句：我们是不是把某个人当成了维持局面的工具？有没有更小伤害、更可协商的方案？尊重边界不是反对整体利益，而是防止“大家都方便”变成“某个人被消耗”。', '["关系公平", "边界感", "两难选择", "尊重", "沟通决策", "责任边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 853, now()),
(100854, '自愿之前，先检查压力、退路和代价', '一个人说“我愿意”，并不总代表这个选择完全自由。现实中的同意常被经济压力、情感依赖、权力差异、害怕失去关系等因素影响。App 端可以把这个视角用于关系判断：当你准备答应一个请求、继续一段关系、承担额外责任时，不只问“我有没有点头”，还要问“我有没有真实退路”“拒绝后会发生什么”“这个交换是否会损害我的尊严或身体感受”。自由不是孤立地做选择，而是在可承受的条件下说 yes 或 no。越能看见处境，越不容易把被迫适应误认为成熟。', '["自主选择", "关系边界", "压力识别", "价值澄清", "关系决策", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 854, now()),
(100855, '把人当目的：沟通里不要只把对方当工具', '有些做法看起来有效，却会损伤关系的尊严：用冷暴力逼对方让步，用示好换控制，用道歉换立刻翻篇，用“我是为你好”取消对方的判断。真正尊重一个人，不只是避免伤害结果，也包括承认对方有感受、理由和选择权。重要谈话前可以自查：我是在邀请对方共同决定，还是只想让对方配合我的方案？我有没有隐瞒关键信息，让对方无法真实选择？把人当目的，并不意味着事事迁就，而是在表达需求、设立边界和争取利益时，仍保留对对方主体性的尊重。', '["尊重", "沟通决策", "关系边界", "动机觉察", "价值澄清", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 855, now()),
(100856, '公平不是平均分：同时看需要、贡献、起点和运气', '关系中的“不公平”常被一句“大家一样就好了”简单处理，但真实生活很少完全一样。家庭照顾、金钱分担、情绪劳动、职场合作，都需要同时看四件事：谁更需要支持，谁投入了什么，谁一开始就背着更多限制，哪些结果只是运气而不是能力。这样看问题，可以减少两种极端：一是把所有差异都归咎于个人不努力，二是把所有责任都推给环境。更成熟的公平感，是在承认起点差异后，讨论可执行的分担规则、补偿方式和后续调整，而不是只争“我有没有吃亏”。', '["关系公平", "责任分配", "资源分配", "公平感", "社会心理", "沟通决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 856, now()),
(100857, '应得感冲突：先确认关系或任务的真正目的', '“我更应该得到”“你凭什么拥有”这类争执，背后往往不是物品本身，而是大家对关系目的理解不同。比如家庭资源是为了奖励听话，还是支持成长？伴侣分工是为了效率，还是为了共同生活的可持续？团队认可是在奖励结果、努力，还是关键贡献？当目的不清楚，应得感就会变成情绪战争。可以先把问题改写成：这段关系或这个任务最想服务什么？谁的哪种投入与这个目的最相关？这样讨论不一定立刻达成一致，但能把攻击人格变成澄清标准，让公平感有可谈的依据。', '["应得感", "关系公平", "价值澄清", "责任分配", "沟通决策", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 857, now()),
(100858, '关系责任不是一锅端：分清选择、角色和历史影响', '有些责任来自自己的选择，有些来自所处角色，还有些来自家庭、团队或上一代留下的影响。把责任全推给个人，会让人背上不属于自己的羞耻；把责任全推给过去，又会让当下的修复停住。处理关系旧账时，可以做三栏：我具体做过什么、我所在的角色或关系系统造成了什么影响、哪些部分不是任何一个人能单独控制。然后再问：我现在能补偿、解释、停止或改变哪一小块？这种分栏能让道歉和修复更落地，也能避免用“这不是我的错”逃开真实影响。', '["责任边界", "关系修复", "价值澄清", "家庭关系", "社会心理", "沟通决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 858, now()),
(100859, '忠诚可以有边界：爱与归属不等于盲目站队', '人不是只有孤立的个人选择，也会被家人、伴侣、朋友、团队和文化牵动。忠诚能给人力量，让人愿意承担、守护和不轻易放弃；但忠诚如果变成“无论发生什么都必须站我这边”，就会压缩判断力。关系里可以把忠诚拆成三层：我愿意理解你的处境，我愿意在合理范围内支持你，我仍保留对伤害和越界说不的权利。这样既不把亲近关系冷处理成交易，也不把爱变成失去边界。成熟的归属，是能同时容纳连接、诚实和必要的不同意。', '["忠诚", "关系边界", "归属感", "价值澄清", "亲密关系", "尊重"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 859, now()),
(100860, '把争论带回共同善：我们想一起成为什么样的关系', '有些争论停在“谁赢谁输”时，会越来越像立场比赛；一旦回到“我们想一起成为什么样的人、家庭或团队”，问题会变得更可谈。共同善不是宏大的口号，而是把关系中的价值说清楚：我们希望这里更安全、更诚实、更有承担，还是更自由、更有效率、更能照顾脆弱者？当价值说清楚，规则才不只是限制，而是共同生活的约定。发生分歧时，可以先暂停辩论对错，邀请彼此补一句：如果这段关系继续变好，我希望它多一点什么、少一点什么。', '["共同善", "沟通决策", "关系公平", "价值澄清", "冲突降温", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 860, now()),
(100861, '终极问题不是非要答对：把意义当作持续倾听', '人会在某些时刻追问：我为什么在这里、这一切意味着什么、我该怎样生活。科学和工具能帮助我们解释事实、改善条件，却不替我们决定要成为什么样的人。更温和的做法，是把不同智慧传统看作人类长期面对终极问题的经验记录：不急着站队，也不急着评价对错，而是练习倾听。可以问自己：哪些问题反复触动我？哪些经验让我更诚实、更安静、更愿意关心他人？意义感不是一次找到标准答案，而是在持续观察、选择、行动和关系中慢慢形成方向感。', '["意义感", "信念系统", "自我探索", "终极问题", "价值澄清", "倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 861, now()),
(100862, '享乐和成功之后：辨认自己真正想守护的生命品质', '愉悦、成就、财富、认可和责任都可以是真实需要，它们不必被否定；但如果把它们当成生命的全部，人很容易在短暂满足之后感到空落。价值探索可以从一个问题开始：我追求这些东西，是为了靠近哪种更深的生命品质？也许是更清醒地活着、更有爱地连接、更自由地创造、更有尊严地承担。欲望像窗口，能让我们看见自己在乎什么；它不需要被粗暴压抑，也不适合永远做主人。成熟的选择，是承认欲望的合法性，同时把方向交还给更稳定的价值。', '["意义感", "价值观", "欲望觉察", "自我探索", "成功焦虑", "生命品质"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 862, now()),
(100863, '四条价值道路：允许自己用不同方式靠近完整', '人的成长入口并不相同：有人靠思考和理解靠近答案，有人靠情感和爱建立连接，有人通过工作、服务和责任找到意义，也有人需要身体练习、呼吸、专注和实验来整合自己。价值探索不必只有一种标准模板。你可以观察自己最自然的入口：我是在理解中变清晰，还是在关系中变柔软？是在行动中确认价值，还是在安静练习中恢复中心？尊重差异也从这里开始：别人的道路与我不同，不等于更低级或更错误；它可能只是从另一种人格起点出发。', '["价值观", "尊重差异", "自我探索", "成长路径", "信念系统", "身心整合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 863, now()),
(100864, '痛苦像生命偏离中心的信号：先诊断，再训练', '痛苦不必立刻被解释成失败或惩罚，它也可能是在提醒：生命的某个部分失去平衡，关系、欲望、注意力或行动方式正在制造摩擦。一个有帮助的框架，是像医生一样处理困扰：先看症状，承认哪里更痛、哪里更冲突；再看成因，识别是否有过度抓取、逃避、比较或自我封闭；然后相信改变有路径，最后设计可练习的处方。比如，检查自己的语言是否真实而不伤人，行动是否增进生命，工作是否长期消耗价值，念头和情绪是否能被观察而不是立刻跟随。', '["心理教育", "痛苦转化", "正念", "价值行动", "自我觉察", "信念系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 864, now()),
(100865, '方法只是渡河的筏子：别把工具变成新的枷锁', '理论、练习、人格标签、测试结果、信念语言和成长方法，都可以像渡河的工具：它们的价值在于帮助我们从混乱走向清明，从自动反应走向更自由的选择。问题在于，人很容易把工具当成身份、武器或绝对真理：我就是这种人、你就是那种人、只有这套方法有效。更灵活的态度是：有用时认真使用，帮助变少时及时调整；能支持行动的留下，会制造僵化和优越感的放下。成熟的信念系统不是越抓越紧，而是能服务生命、关系和现实反馈。', '["心理灵活性", "信念系统", "自我探索", "工具意识", "尊重差异", "成长方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 865, now()),
(100866, '价值不是口号：在日常关系里练成第二天性', '一个人真正相信什么，不只看他说过哪些道理，也看价值如何进入日常生活。善意、诚实、责任、礼貌和尊重如果只停留在口号层面，遇到压力就很容易失效；它们需要通过家庭对话、故事、承诺、节日、道歉、问候、协商和小规则反复练习，最后成为“下意识也愿意这样做”的习惯。可以为自己设计一个价值内化问题：我希望培养的一个品质是什么？它今天能通过哪一句话、哪一次守约、哪一个克制或哪一个关心被看见？', '["价值观", "关系沟通", "习惯养成", "自我修养", "心理教育", "责任感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 866, now()),
(100867, '关系中的位置感：尊重不是盲从，责任要配得上影响力', '每段关系都有角色差异：父母与孩子、伴侣之间、领导与成员、年长者与年轻者、帮助者与被帮助者。差异本身并不必然伤人，真正危险的是把位置误解成特权。更健康的关系观是：影响力越大，越需要承担照顾、倾听、解释和修复的责任；被尊重不是理所当然，而要通过可靠行动赢得。对普通用户来说，关系中的尊重差异可以转化为三个问题：我在这段关系里有什么责任？对方有什么边界？如果我拥有更多资源或话语权，我有没有让对方更安全、更有尊严？', '["尊重差异", "关系沟通", "边界", "责任感", "价值观", "共同善"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 867, now()),
(100868, '创造性的静：少一点硬碰硬，找回更有效的行动', '当人紧张、急躁或过度用力时，行动看起来很多，效果却可能被摩擦耗尽。道家的“无为”可转为一种心理教育提醒：不是躺平，也不是逃避，而是在充分观察之后，减少不必要的对抗，找到事情本身的缝隙，用更省力、更合拍的方式行动。遇到卡住的任务或冲突时，可以先暂停、放松身体、看清局势中的真实限制，再问：我是否在和无法改变的部分硬撞？有没有一个更小、更柔软但更有效的下一步？像水一样行动，不是软弱，而是不把能量浪费在僵硬上。', '["意义感", "心理教育", "行动策略", "身心调节", "道家智慧", "压力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 868, now()),
(100869, '把平凡日常重新变得值得珍惜：个人仪式与感恩感', '仪式不一定属于某个宗教，它也可以是心理上安放情绪、转换阶段和提醒价值的方式。一次认真吃饭、一次告别、一个睡前感谢、一次家庭固定谈话、一个纪念日动作，都能把容易被忽略的生活重新放进更大的意义框架。人在失去、庆祝、相聚或做选择时，常需要的不只是道理，而是一个可重复的动作来承载情感。个人仪式的关键不是形式复杂，而是让自己暂停自动驾驶：看见我拥有的关系、身体、自然、时间和责任，并用一个小动作表达珍惜。', '["意义感", "敬畏感", "感恩", "个人仪式", "情绪安放", "价值观"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 869, now()),
(100870, '聆听陌生信念与具体世界：在差异中练习敬畏', '当我们只把人看成观点标签、把自然看成可利用资源、把地方看成抽象空间，敬畏感会变弱，冲突也更容易变粗糙。可以练习把他人、地点和世界重新看作具体存在：在分歧中先问“这对你意味着什么”，而不是急着反驳；在熟悉的街道、树木、河流或房间里停留片刻，感受它们怎样支持、限制并塑造了你的生活。尊重差异不是必须认同所有观点，而是承认别人和世界都不只是供我使用的对象。这样的聆听，会让理解更深，也让关系更有余地。', '["尊重差异", "敬畏感", "关系沟通", "多元信念", "自然连接", "意义感", "倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 870, now()),
(100871, '三赢检查：决定前同时照顾自己、对方与更大系统', '做重要决定或提出请求前，先做三赢检查：这件事怎样让我更好？怎样照顾对方的需要？对家庭、团队或长期生活有什么影响？若内心有一部分明显抗拒，不急着压下去，把担心写成具体条件，再寻找能同时减少损害、增加支持的方案。', '["NLP沟通", "价值澄清", "关系沟通", "决策练习", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 871, now()),
(100872, '把讲道理转成看效果：冲突中的表达修正练习', '争执中“我说得有道理”不等于沟通有效。把注意力从证明自己对，改成观察对方回应：他是否更明白、更愿意谈、更清楚下一步？若没有，调整声调、句式、时机和例子。可用一句话练习：我真正想得到的效果是什么？还有哪三种说法更可能达到它？', '["NLP沟通", "关系沟通", "冲突处理", "表达练习", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 872, now()),
(100873, '尊重不同地图：先理解对方的信念、价值与规条', '每个人都带着自己的经历、价值和规条理解世界。沟通前先假设：对方不是故意错误，而是在按自己的地图行动。用“你这样看重的是什么？”“什么使你这样判断？”代替立刻反驳；同时保留自己的边界。尊重差异不等于认同所有做法，而是为后续合作留下空间。', '["NLP沟通", "关系沟通", "信念调整", "边界表达", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 873, now()),
(100874, '情绪是提示而非命令：先接住推动力，再选择行为', '情绪可以被看作一股提醒和推动力，而不是必须压下去的错误。出现焦虑、愤怒或委屈时，先命名感受，再问：它想保护什么价值？提醒我学习什么？随后把行为选择分开：可以接纳情绪和需要，同时选择更有效、更少伤害的表达方式。', '["情绪理解", "信念调整", "自我觉察", "行为选择", "NLP沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 874, now()),
(100875, '正面动机不等于行为有效：关系沟通中的分层回应', '一个行为背后可能有想被尊重、想安全、想证明能力等正面动机，但行为本身仍可能无效。沟通时先确认动机：我猜你是想……；再讨论行为影响：这样做带来的结果是……；最后一起找替代做法。亲子、伴侣和团队沟通都可用这三步减少防御。', '["NLP沟通", "关系沟通", "亲子沟通", "情绪理解", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 875, now()),
(100876, '内感官三通道：用看、听、感觉提升沟通接收度', '有些人主要用画面思考，有些人依赖语言和声音，有些人更重视身体感受。解释事情时尽量同时提供三种通道：画面或示例、清楚步骤、实际感受或体验。倾听时留意对方常说“看起来、听起来、感觉到”，再用相近通道回应，沟通会更容易被接收。', '["NLP沟通", "内感官", "学习方法", "关系沟通", "表达练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 876, now()),
(100877, '内在画面与抽离：温和调节不愉快记忆的练习', '回忆之所以影响情绪，常与脑中画面的距离、亮度、声音大小、身体感受位置有关。面对一般性不愉快记忆，可先做温和观察：把画面想象成屏幕，尝试拉远、调暗、缩小；或想象自己站到旁观者位置看现场。只把它作为自我稳定练习，不强迫挖掘重大创伤。', '["情绪理解", "NLP练习", "自我觉察", "压力调节", "经验元素"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 877, now()),
(100878, '理解层次排查：不要把行为问题升级成身份否定', '理解层次提醒我们区分环境、行为、能力、信念价值和身份。很多冲突本来只是“这次没做某件事”或“还没学会某能力”，一旦说成“你就是没用/自私”，就升级成身份攻击。反馈时尽量落在行为和能力层：说事实、影响、可改做法，而不是给人贴身份标签。', '["信念调整", "亲子沟通", "关系沟通", "自我觉察", "反馈练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 878, now()),
(100879, '自我价值三步：从能力经验建立自信、自爱与自尊', '自我价值可拆成自信、自爱、自尊。自信来自经验和能力积累；自爱是愿意保护自己的身心资源；自尊是同时尊重自己与他人。练习时，每天记录一件已做到的小能力、一个照顾自己的行动、一次清楚表达边界或责任的时刻，让自我评价建立在可观察证据上。', '["自我觉察", "自我价值", "信念调整", "情绪理解", "行动练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 879, now()),
(100880, 'BVR 拆解：把应该如此还原成价值与做法', '信念系统可以拆成 BVR：信念是“事情应该怎样”，价值是“这样对我有什么意义”，规条是“我必须怎样做”。当你被“应该、必须、不能”卡住时，写下这句话，分别找出背后的价值和具体做法，再问：还有没有其他做法也能实现同样价值？', '["信念调整", "价值澄清", "自我觉察", "NLP沟通", "行为选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 880, now()),
(100881, '换框三问：在意义、选择和环境中松动局限信念', '换框不是粉饰问题，而是在保留事实的基础上寻找更多解释和选择。可用三问练习：这件事还能有什么学习或提醒？有没有办法让两个看似冲突的需要同时被部分满足？这个特质在哪些情境中可能有用、在哪些情境需要调整？这样能松动绝对化信念。', '["信念调整", "NLP练习", "情绪理解", "认知灵活性", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 881, now()),
(100882, '检定语言提问：把绝对化和含糊话说清楚', '很多困扰藏在含糊或绝对化语言里，例如“他总是伤害我”“我永远做不到”。检定语言的做法是温和追问：总是指哪些时候？有没有例外？他具体做了什么？你把什么拿来比较？问题的目的不是审问，而是把模糊痛苦还原为可观察、可选择、可行动的信息。', '["NLP沟通", "检定语言", "信念调整", "情绪理解", "表达练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 882, now()),
(100883, '目标确定七要素：把愿望写成可行动计划', '好目标不只是愿望，而要写成可执行结果。检查七点：用正面词语说明想要什么；符合自己、他人和长期生活的整体平衡；具体清楚；可量度；主要由自己可控；想象达成时有足够满足感；有时间限期。最后补上第一步、所需资源和可能障碍。', '["目标设定", "行动计划", "价值澄清", "自我觉察", "NLP练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 883, now()),
(100884, '家庭共同价值清单：把关系修复变成每周小行动', '家庭关系需要共同信念和共同价值，而不是只靠权威或忍让维持。可以做一个低冲突清单：每人写20件愿意一起做、成本低、1-2小时可完成的小事，只保留所有人都同意的项目，每周安排两项。亲子沟通中，把孩子当作“准大人”，用爱、鼓励和支持替代恐惧、羞愧和内疚驱动。', '["亲子沟通", "关系沟通", "家庭练习", "价值澄清", "行动练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 884, now()),
(100885, '注意力会放大线索：先选择要靠近的方向', '一个人反复看的东西，会更容易被大脑筛选出来；反复谈论和想象的主题，也会影响后续解释与行动。把这理解为注意力机制，而不是外部世界被念头操控。练习时先问：我现在把注意力投给了问题本身，还是投给了我想靠近的状态？如果发现自己在反刍“不要失败、不要被讨厌”，就把它翻译成可观察的正向方向：我想更稳定地表达、我想完成今天的一步、我想找到一个可用资源。注意力不是用来否认困难，而是帮助你从困难中看见可选择的下一步。', '["注意力管理", "目标澄清", "心理教育", "自我觉察", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 885, now()),
(100886, '把“我不要”翻译成“我想要”：负向目标的转向练习', '很多愿望最初以排斥的形式出现：我不想拖延、不想焦虑、不想再吵架。排斥可以提示边界，但如果一直停在“不想要”，注意力会被问题本身占满，行动也容易只剩逃避。更有用的做法是把负向表达翻译成正向目标：不想拖延→我想在 10 分钟内打开文件；不想焦虑→我想先把担心写成三条可验证事项；不想吵架→我想先确认我们共同在乎什么。这样做不是假装问题不存在，而是让目标从模糊的抗拒变成可执行的靠近。', '["目标澄清", "注意力管理", "愿望行动", "情绪调节", "行动反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 886, now()),
(100887, '情绪是反馈灯：用感受检查目标是否对齐', '情绪可以被当作反馈灯：它不直接证明事情对错，却能提示你的解释、目标和行动是否在互相拉扯。持续低落、烦躁或失望时，先不要急着压住情绪，也不要把它当成失败证据；可以问三个问题：我正在关注什么？这个关注点是在扩大无力感，还是帮助我靠近价值？我能否换一个更具体、更可行动的表述？积极情绪也不是必须一直保持，而是提示某个方向可能更贴近需要。把情绪当反馈，就能在想法—感受—行动之间建立温和的校准循环。', '["情绪调节", "行动反馈", "目标澄清", "自我觉察", "注意力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 887, now()),
(100888, '十五分钟目标工作坊：把理想画面落到下一步', '可以把原书的“创造性工作坊”转成一个不神秘的目标澄清练习：每天或每周找 10—15 分钟，不用追求仪式感，只做三件事。第一，写下最近让你感觉有力量、喜欢或向往的具体片段；第二，把这些片段整理成一个方向句，例如“我想拥有更稳定的作息和更清楚的表达”；第三，选出一个今天能做的最小行动。这个练习的重点不是用想象替代现实，而是让零散的羡慕、渴望和好感变成可复盘的目标素材，再用小行动收集反馈。', '["目标澄清", "行动反馈", "自我觉察", "愿望行动", "注意力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 888, now()),
(100889, '先停一下再行动：避免用匆忙行动补偿不安', '行动很重要，但匆忙行动有时只是为了摆脱焦虑、孤独或不确定。原书多次区分“想清楚后的行动”和“被不安推着走的行动”，可以转译为：先澄清需要，再选择行动。开始前问自己：我现在行动是为了靠近目标，还是为了立刻消除某种难受？如果是后者，先做一个更小的稳定动作，如呼吸、写下真实担心、向可信的人确认事实，再决定下一步。愿望需要行动承接，但行动也需要和真实需要对齐；否则做得越多，反馈越混乱。', '["行动反馈", "愿望行动", "情绪调节", "目标澄清", "冲动管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 889, now()),
(100890, '阶段计划：每个场景只先确定一个优先意图', '一天里不同场景需要不同意图：开车时是安全抵达，开会时是清楚表达，亲密沟通时可能是保持连接。所谓“阶段计划”可以转成一个简单练习：进入下一个场景前停 20 秒，问“这个阶段我最想守住什么？”只选一个优先意图，并让行动围绕它展开。当争论升级时，这个问题能把注意力从输赢拉回关系；当任务混乱时，它能把注意力从所有事情拉回第一步。阶段计划不是控制每个细节，而是在切换场景时给大脑一个行动方向。', '["阶段计划", "目标澄清", "注意力管理", "行动选择", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 890, now()),
(100891, '计划要具体到有力量，不能具体到更焦虑', '目标越具体，越容易行动；但如果过早规定唯一方法，也可能让人被压力卡住。一个实用标准是：具体到让你更清楚、更愿意开始，而不是具体到更紧绷、更想逃。比如“我要变优秀”太空，可以改成“本周完成一次作品迭代”；但如果规定“必须三天内得到某个外部结果”，反而会让行动被焦虑绑架。好的计划会同时包含方向、可控步骤和反馈方式：我想靠近什么？我今天能做什么？我如何知道这一步有帮助？', '["目标澄清", "行动反馈", "愿望行动", "自我效能", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 891, now()),
(100892, '接纳不是认命：把他人的选择和自己的焦点分开', '接纳不是把一切都说成合理，也不是要求自己喜欢所有人。更可操作的理解是：承认他人有他们的选择，同时把自己的注意力收回到价值、边界和可行动的部分。当你长时间盯着别人的错误、比较或不可控反应，情绪会被对方牵着走；当你问“我能守住什么、表达什么、选择什么距离”，注意力就回到自己这里。接纳的核心不是被动忍受，而是停止把全部心理资源交给不可控对象，为自己的行动留出空间。', '["接纳练习", "注意力管理", "边界感", "自我觉察", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 892, now()),
(100893, '把缺失感改成证据收集：从“还没有”回到“正在靠近”', '当人想要某件事却总盯着“我还没有”，愿望会很快变成失望和无力。可以把缺失感改成证据收集：今天有哪些微小迹象说明我正在靠近？我获得了什么信息、练习了什么能力、遇到过什么资源？如果没有证据，下一步最小实验是什么？这个练习不是自我安慰，而是让大脑从反复证明“我不行”转向寻找可用反馈。愿望需要现实证据来滋养，行动也需要反馈来修正；只看缺口，会忽略已经出现的进展线索。', '["行动反馈", "注意力管理", "愿望行动", "自我效能", "积极心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 893, now()),
(100894, '儿童性格优势不是天赋标签：把勇气、好奇和乐观看成可练习的能力', '孩子的发展不能只看会背多少知识、考了多少分。勇气、好奇心、乐观、自控、责任感和坚持等品质，更像一组可以被环境支持、被日常练习强化的心理能力。App 端引导时，可以避免把孩子说成“天生胆小”“没有毅力”，而是帮助家长和老师观察：孩子在哪些情境里更敢尝试？什么时候会主动提问？遇到挫折后是否还能调整策略？把性格优势拆成具体行为，才能给出可练习、可复盘、可支持的下一步。', '["儿童发展", "性格优势", "心理教育", "非认知能力", "品格培养"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 894, now()),
(100895, '安全回应是孩子探索世界的基地：亲子支持能缓冲早期压力', '幼儿并不是被及时抱起、安抚和回应就会“宠坏”。稳定、敏感的照顾，会让孩子在紧张后更容易恢复平静，也更敢离开熟悉区域去探索。对家长来说，关键不是时时包办，而是在孩子害怕、愤怒、受挫时提供可预期的连接：先接住情绪，再帮助孩子说出发生了什么，最后一起回到规则和行动。这样的安全感会成为孩子日后好奇、勇敢、自控和社交能力的基础。', '["儿童发展", "安全依恋", "亲子支持", "压力缓冲", "家庭支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 895, now()),
(100896, '先降压再谈学习：压力过载会占用孩子的自控和执行功能', '当孩子长期处在冲突、创伤或高压环境里，大脑会优先处理威胁感，专注、等待、听指令、调节情绪都会变难。此时单纯批评“不认真”“不自律”，常常无法解决问题。更有效的顺序是：先帮助孩子恢复安全感和身体平静，再把任务拆小，给出清晰步骤，并让孩子练习暂停、命名情绪、选择下一步。自控不是凭空出现的意志，而是需要稳定环境、可理解规则和反复练习共同支撑。', '["儿童发展", "自控", "执行功能", "压力管理", "学习支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 896, now()),
(100897, '勇气不是不害怕：在可承受的困难里练习重新站起来', '儿童和青少年的勇气，不是逞强、冒险或永远不哭，而是在有支持的环境里面对一点困难，承认害怕，同时继续尝试。家长可以把勇气练习设计成“可承受的挑战”：做一件略难但安全的事，失败后复盘哪里卡住，再决定下一次怎么调整。这样培养出的勇气更接近坚毅和韧性，它帮助孩子穿过挫折，而不是把孩子推向超出承受范围的压力。', '["性格优势", "勇气", "坚持", "抗挫折", "成长反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 897, now()),
(100898, '乐观是一种解释习惯：把挫折看成具体、有限、可调整的事件', '有用的乐观不是假装一切都好，而是在失败后避免把一次事件解释成“我永远不行”。孩子考试失利、比赛输了、被同伴拒绝时，可以练习把原因说得更具体：这次准备不足、方法不合适、节奏太急、需要求助。具体的解释会留下行动空间，孩子也更容易恢复情绪、重新尝试。App 端可以把乐观设计成“解释风格训练”，帮助孩子从灾难化、自责化，转向可复盘、可修正、可继续的叙事。', '["性格优势", "乐观", "解释风格", "情绪复原", "成长反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 898, now()),
(100899, '保护孩子的好奇心：少灌输标准答案，多创造安全探索', '好奇心来自孩子对世界的主动接近。它不只表现为问很多问题，也可能表现为拆开玩具、反复试错、对某个主题持续投入。家长和老师可以少急着纠正答案，多问“你观察到了什么”“你还想试什么”“如果换一种方法会怎样”。同时要给出安全边界：哪些可以探索，哪些需要成人陪同，哪些会伤害自己或他人。被保护的好奇心，会和专注、学习兴趣、独立思考一起成长。', '["儿童发展", "好奇心", "探索", "学习兴趣", "家庭支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 899, now()),
(100900, '自控需要动机也需要工具：把目标改写成“如果—那么”的小计划', '孩子有目标并不等于能坚持，只有意志力也不够。自控更像“动机＋工具＋环境”的组合：知道为什么要做，知道被诱惑时怎么做，并把环境调整得更容易成功。可以让孩子写下具体计划，例如“如果写作业时想刷视频，那么先把手机放到客厅，完成两题后休息五分钟”。这种计划比抽象地喊“我要自律”更可执行，也能让孩子在一次次成功中形成自我效能。', '["自控", "意志力", "目标管理", "执行计划", "青少年发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 900, now()),
(100901, '专注力不是只靠奖励：让孩子看见任务意义并练习抗干扰', '外在奖励能带来短期推动，但很难替代孩子对目标的理解和投入。培养专注力时，可以先降低任务难度和干扰，再帮助孩子把任务和自己的目标连接起来：为什么这件事值得做？完成后能带来什么能力？过程中最容易分心的点是什么？比起不断加码奖惩，更可持续的方法是训练孩子识别分心信号、设置短时专注段、记录完成感，并在复盘中看到自己确实能更投入。', '["儿童发展", "专注力", "内在动机", "学习习惯", "品格培养"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 901, now()),
(100902, '失败后做一次温和复盘：把“我输了”变成“我学到了哪一步”', '孩子失败后最需要的，不是立刻被安慰到忘记，也不是被羞辱到不敢再试，而是有人陪他把过程慢下来。复盘可以按三步进行：先承认难受是真实的；再还原关键节点，找出哪一步太急、漏看或没准备；最后确定一个小改法，带到下一次练习中。这样做能让孩子把失败看成信息，而不是身份评价。失败仍然会痛，但它会变成成长材料。', '["失败复盘", "成长反馈", "勇气", "自控", "学习方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 902, now()),
(100903, '成长型反馈不评价整个人：只指出行为、策略和下一次练习', '给孩子反馈时，最容易伤人的不是指出问题，而是把问题说成固定人格。更适合 App 端的表达是：你这次在哪个行为上做得好？哪个策略没有奏效？下一次可以练哪一个具体动作？当性格被理解为可塑的能力，勇气、自控、乐观和社交能力就不再是给孩子贴标签，而是帮助他看见自己的优势、短板和成长路径。反馈越具体，孩子越容易把改变当成可练习的事。', '["性格优势", "成长型思维", "品格培养", "亲子沟通", "学校支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 903, now()),
(100904, '家庭支持不是直升机保护：爱、边界和适度挑战要同时存在', '孩子需要被爱和安抚，也需要规则、限制和承担后果的机会。过度保护会让孩子少了练习失败的机会，过度放任又会让孩子缺少安全边界。更平衡的家庭支持，是在孩子遇到可承受的困难时不急着替他清场，而是陪他评估风险、决定尝试、失败后复盘，再鼓励他自己站起来。这样的支持既保护安全感，也训练责任、自控和抗挫折能力。', '["亲子支持", "适度挑战", "抗挫折", "家庭边界", "品格培养"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 904, now()),
(100905, '青少年升学不只拼分数：时间管理、求助和问题解决也是准备度', '进入高中和大学后，孩子面对的不只是考试内容，还包括时间安排、财务和信息选择、与老师同学沟通、遇到困难时主动求助。很多青少年并非没有能力，而是缺少把目标落地的生活技能。面向 App 端，可以把升学准备拆成可训练清单：每周计划、截止日期提醒、求助脚本、学习环境设计、情绪低落时的支持资源。分数重要，但坚持完成路径也需要这些非认知准备。', '["青少年发展", "大学准备", "非认知能力", "时间管理", "求助能力", "规划能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 905, now()),
(100906, '兴趣能带来深度投入：让孩子在挑战和快乐之间体验心流', '孩子需要的不只是避免失败，也需要体验“我真的投入其中”的快乐。无论是棋类、运动、音乐、阅读还是手工，当难度略高于现有能力、反馈及时、目标清楚时，孩子更容易进入专注状态。父母不必把兴趣立即变成竞赛和成绩，也不必要求孩子每样都坚持到底；可以观察哪些活动让孩子愿意反复练习、主动改进、忘记外界干扰。健康的兴趣会滋养好奇心、专注力和坚持。', '["儿童发展", "心流", "兴趣培养", "专注力", "好奇心", "坚持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 906, now()),
(100907, '高风险孩子需要连续支持：家庭、学校和社区一起修复成长环境', '面对创伤、贫困或长期压力中的孩子，不能把责任全部推给孩子“没性格”，也不能只靠一次谈话或一个补习班解决。更有效的是连续支持：儿科和心理创伤照护、稳定照顾关系、幼儿自我调节训练、学校里的学习与情绪支持、青春期的升学和生活技能辅导。性格优势可以被塑造，但需要成人和系统一起创造条件。对 App 来说，这类内容应鼓励求助、连接资源和长期陪伴，而不是简单责备家庭或孩子。', '["儿童发展", "家庭支持", "学校支持", "创伤知情", "社区支持", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 907, now()),
(100908, '把择偶偏好翻译成真实需要，而不是给人贴标签', '被某类人吸引，不必急着解释成命运或性别本能。进化心理材料提醒我们，择偶偏好常围绕安全、可靠、活力、资源、照顾、共同生活能力等线索展开；但对现代关系来说，更有帮助的是把偏好翻译成可沟通的需要：我想要怎样的稳定感、尊重、成长空间和生活协作？当你评估一个人时，不只看第一眼吸引，也看对方是否持续尊重边界、能否承担责任、是否愿意修复分歧。这样既承认吸引的自然性，也避免用单一标准物化自己或他人。', '["择偶心理", "亲密关系", "需求表达", "安全感", "尊重差异", "关系边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 908, now()),
(100909, '长期关系优先看可持续品质：善意、可靠与情绪稳定', '亲密关系里，外貌、成就或新鲜感可能先引发注意，但长期安全感更依赖可持续品质。资料反复提到，长期伴侣的重要线索包括善良、聪慧、可靠、情绪稳定、健康、忠诚和愿意协作。App 端可把它转化为自查：对方是否守约、是否在压力下仍愿意沟通、是否尊重你的生活节奏、是否能一起处理现实责任？你自己是否也在提供同样的品质？好的关系不是找到一个“完美对象”，而是两个人都有能力让日常生活更安全、更可信、更可修复。', '["亲密关系", "择偶心理", "安全感", "信任承诺", "关系识别", "情绪稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 909, now()),
(100910, '承诺看连续行动：喜欢要能落到时间、透明和责任', '一句喜欢或暧昧承诺，不等于稳定关系已经形成。资料在“承诺问题”和“吸引伴侣”章节中提示：人有时会用看似投入的信号争取亲密机会，却未必愿意承担长期责任。现代关系中，不需要用试探或控制来验证承诺，可以观察更具体的行为：是否愿意公开基本关系期待，是否在约定上稳定，是否在冲突后修复，是否把时间、情绪劳动和现实责任纳入关系。若你发现对方只在需要亲近时热情、涉及责任时模糊，可以温和但清楚地询问：“我们对这段关系的期待是否一致？”', '["信任承诺", "择偶心理", "亲密关系", "安全感", "需求表达", "关系识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 910, now()),
(100911, '亲密信号容易被错读：推进关系前先确认边界', '微笑、热情聊天、调侃或愿意相处，不必然代表对方同意更进一步。资料中的“错误管理/知觉偏误”讨论提醒：人们可能把对方的友好、礼貌或暧昧信号读成自己期待的意思，从而引发压力和冲突。更成熟的做法是把猜测改成确认：我这样靠近你可以吗？你愿意继续聊这个话题吗？如果你不舒服可以直接说。确认边界不会破坏吸引，反而能增加安全感。对普通用户来说，尊重同意、允许拒绝、及时停止，是亲密关系中最基础的信任建设。', '["关系边界", "亲密关系", "择偶心理", "安全感", "尊重同意", "差异沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 911, now()),
(100912, '嫉妒是关系警报，不是监控和占有的许可', '嫉妒常在关系安全感被威胁时出现，它可能提示你在意承诺、害怕失去、担心边界不清。资料把嫉妒与留住伴侣、竞争者线索和不忠担忧联系起来，但 App 端更适合把它转化为调节练习：先命名触发点，是事实、想象还是旧伤？再表达需要，我需要更多透明、确认或共同规则；最后守住底线，不用查手机、隔离社交、羞辱对方来换安全。嫉妒可以成为对话入口，不能成为控制、惩罚或侵犯隐私的理由。', '["嫉妒调节", "关系边界", "安全感", "信任承诺", "情绪调节", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 912, now()),
(100913, '留住关系靠正向投入，而不是让对方害怕离开', '资料中列举了很多“留住伴侣”的方式：有些是表达承诺、共同时间和关心，有些则是监控、贬低、威胁或把伴侣与外界隔离。转为亲密关系教育时，应强调前者、避免后者。想让关系更稳，可以增加可感知的安全信号：主动表达欣赏，安排高质量相处，公开重要期待，遇到诱惑或边界模糊时提前沟通。不要用制造内疚、限制社交、贬低竞争者或让对方害怕后果来维持关系。真正能留住人的，是被尊重、被珍惜和可以自由选择留下来的感受。', '["亲密关系", "信任承诺", "关系边界", "安全感", "关系修复", "尊重"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 913, now()),
(100914, '冲突背后常是目标不一致：先翻译需要，再谈对错', '伴侣冲突不一定说明不爱了，很多时候是两个人的目标、节奏或代价感不一致：一方想要更多陪伴，另一方想保留空间；一方期待明确承诺，另一方还在观望；一方重视现实责任，另一方更看重自由。资料把冲突理解为一方目标干扰另一方目标。App 端可以引导用户把“你总是这样”改成三句话：我看到的事实是……我受影响的是……我真正需要的是……。当需要被说清楚，双方才有机会协商边界、投入和节奏，而不是把差异升级成人格攻击。', '["差异沟通", "亲密关系", "需求表达", "关系边界", "冲突降温", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 914, now()),
(100915, '关系投入要具体化：时间、照顾、金钱和情绪劳动都需要协商', '很多亲密关系的不满并不来自某个大事件，而来自长期感觉“我在投入，你没有回应”。资料中的资源投入和忽视失信讨论，提示伴侣会把时间、精力、现实支持和情感回应看作承诺线索。现代关系中，与其让对方猜，不如把投入具体化：每周需要多少高质量相处？家务和照顾如何分担？经济支持与个人独立怎么平衡？遇到压力时希望怎样被回应？这些问题越早谈清楚，越不容易把失望积累成冷战、指责或突然分手。', '["信任承诺", "需求表达", "亲密关系", "责任分配", "关系公平", "差异沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 915, now()),
(100916, '比较和替代选项会影响关系：觉察它，不必被它牵着走', '人在关系中仍可能注意到其他有吸引力的人，也可能在关系低谷时比较“现在的伴侣”和“可能的选择”。资料把这种心理与分手适应和配偶价值变化相连。App 端不宜鼓励比较或骑驴找马，而是帮助用户觉察：我是在被新鲜感吸引，还是当前关系里有重要需要长期未被回应？我有没有用幻想中的替代者逃避真实沟通？如果关系仍值得投入，就把比较带回具体需求和修复行动；如果安全、尊重和承诺长期缺失，也应负责任地沟通结束，而不是暧昧拖延或隐瞒伤害。', '["亲密关系", "择偶心理", "信任承诺", "关系决策", "需求表达", "关系边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 916, now()),
(100917, '分手不是失败标签：看安全、尊重和可修复性', '资料把分手视为人类关系中会反复出现的现实，而不是单纯的个人失败。对 App 用户来说，判断一段关系是否需要结束，可以看三个维度：安全是否受威胁，包含羞辱、恐吓、暴力或持续侵犯边界；尊重是否还在，包含诚实、责任和基本善意；问题是否可修复，双方是否愿意承认影响并改变行为。若只是阶段性失望，可以先做清晰沟通和修复；若长期冷酷、欺骗、资源撤回或伤害反复出现，结束关系可能是在保护自己。分手也需要尽量诚实、克制和有支持系统。', '["关系边界", "关系决策", "安全感", "分手修复", "自我保护", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 917, now()),
(100918, '关系会随人生阶段变化：定期重谈期待与边界', '同一段关系在不同阶段会遇到不同压力：年龄、健康、事业、收入、家庭责任、社交环境和个人成长都会改变双方的需求。资料在“时过境迁”中讨论了处境变化如何影响吸引、承诺和关系稳定。App 端可以把它转化为“关系复盘”练习：每隔一段时间问彼此，我们现在最需要被支持的是什么？哪些旧约定已经不适合？哪些边界需要更新？有哪些感谢和不满需要说出来？关系不是签一次永久合同，而是在变化中持续更新共同生活的规则。', '["亲密关系", "信任承诺", "关系边界", "需求表达", "人生阶段", "关系复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 918, now()),
(100919, '用进化视角理解差异，但不用它为伤害找借口', '进化心理材料能帮助我们理解吸引、嫉妒、竞争、承诺焦虑等反应为什么常见，但它不应被用来给性别刻板印象、控制欲或不负责任行为背书。资料也强调，人类有共享的心理机制，现实行为受文化、情境和选择影响。更适合 App 的表达是：我可以理解自己为什么会有冲动，但我仍要为行动负责；我可以承认伴侣与我需要不同，但不能取消对方的边界；我可以谈本能和偏好，但最终要回到尊重、同意、诚实和共同规则。理解不是纵容，解释不是命运。', '["择偶心理", "关系边界", "尊重差异", "亲密关系", "自我觉察", "信任承诺"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 919, now()),
(100920, '家庭互动循环：先看关系位置，再判断个人反应', '一个人在不同关系位置里，可能呈现完全不同的状态：独处时、和父母在一起时、和伴侣或兄弟姐妹在一起时，感受、说法和行动都会变化。遇到家人情绪激烈、退缩或反复争执时，先不要急着判断“谁有问题”，而是把互动循环画出来：谁先说了什么，谁靠近或退后，哪句话让安全感下降，哪种沉默让误会继续。把问题从“某个人不好”改写成“我们怎样相互影响”，才更容易找到可调整的一小步。', '["家庭系统", "互动循环", "关系位置", "沟通模式", "情绪理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 920, now()),
(100921, '双重束缚：当规则互相矛盾，先把期待说清楚', '家庭里最让人混乱的，不一定是明确的拒绝，而是互相冲突的期待：既要独立又不能让家人担心，既要诚实又不能说出真实感受，既要亲密又不能有自己的边界。处在这种处境里的人，怎么做都像是错的，久了容易焦虑、愤怒或躲进沉默。修复的起点不是争谁有理，而是把隐性规则说成明规则：你希望我做到什么？哪些选择可以被允许？如果我不同意，会发生什么？规则清楚了，关系才有协商空间。', '["双重束缚", "沟通模式", "家庭系统", "边界感", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 921, now()),
(100922, '被否认的感受：确认体验比证明对错更能降温', '当一个人说“我害怕、我难过、我不想这样”时，家人若马上回答“你不是这样想的”“你只是想多了”“你根本不记得”，对方会同时失去表达空间和自我信任。确认感受不等于同意所有观点，也不等于放弃边界；它只是先承认：你的体验对你来说是真实的。更稳妥的回应可以是：“我听见你是这样感受的，我的理解可能不同，我们慢慢核对。”先确认，再讨论事实，关系更容易从辩解回到合作。', '["情绪理解", "感受确认", "沟通模式", "关系修复", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 922, now()),
(100923, '标签化伤害：把“你就是这样”改成具体行为', '“你就是懒、怪、自私、叛逆、不正常”这类标签，会把一次行为扩大成整个人的身份，让对方越听越防御，也让改变变得更难。家庭沟通更适合落在具体事实和影响上：不要说“你总是没救了”，可以说“昨晚约好九点沟通，但我们没有谈成，我感到失落，也担心问题继续拖着”。标签让人被固定，事实让人还有选择。尤其在情绪高涨时，先把身份判断拿掉，关系才不会被一句话推向对立。', '["标签化", "沟通模式", "事实表达", "关系修复", "情绪理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 923, now()),
(100924, '情绪失调也可能是在矛盾中努力求生', '强烈情绪、混乱表达或突然退缩，有时不是“故意作对”，而是一个人在无法同时满足多方期待时的挣扎。看见这一点，并不意味着纵容伤人的行为，而是把焦点从责备转向理解：这个反应试图保护什么？它在逃开什么压力？它真正需要的是安全、尊重、自由、休息，还是被听见？当家人愿意把情绪看成信号，而不是立刻贴上坏标签，就更可能找到新的表达方式，例如暂停、写下来、用请求代替爆发。', '["情绪理解", "家庭系统", "沟通模式", "压力反应", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 924, now()),
(100925, '家庭秘密与无声指责：沉默也会传递压力', '有些家庭表面没有直接冲突，但秘密、羞耻和不能谈的话题会通过眼神、停顿、回避和暗示传递出来。被卷入其中的人可能说不清发生了什么，却持续感到自己被怀疑、被评判或必须猜测真相。修复不是逼所有人立刻坦白，而是先减少无声指责：把可说的部分说清楚，把不能说的部分承认为“现在还难以谈”，并约定不再用暗示和冷处理惩罚彼此。清楚的边界和有限的诚实，通常比假装没事更安全。', '["家庭系统", "沟通模式", "无声指责", "边界感", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 925, now()),
(100926, '角色固化：别把家人困在旧版本里', '家庭很容易给成员分配固定角色：懂事的孩子、麻烦制造者、永远需要照顾的人、最会忍的人、最不可靠的人。角色一旦固化，新的尝试也会被旧眼光解释，例如独立被看成反抗，表达需求被看成自私，保持距离被看成不爱。更健康的家庭会定期更新彼此的认识：你现在和以前有什么不同？你希望我们怎样称呼和对待你？我有哪些旧印象需要放下？允许家人长出新版本，是关系继续流动的前提。', '["家庭系统", "角色固化", "沟通模式", "自主", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 926, now()),
(100927, '边界感：区分共享生活和私人空间', '亲密家庭不代表所有时间、空间、物品和想法都必须共享。一个人需要自己的房间、日程、朋友、记忆和内心活动，并不等于不爱家人。关系紧张时，可以具体梳理边界：哪些事必须共同决定，哪些事只需要告知，哪些事属于个人选择；哪些空间可以敲门进入，哪些时间不被打扰。边界不是把家人推开，而是让每个人都有足够呼吸空间，再带着更稳定的自己回到关系里。', '["边界感", "家庭系统", "私人空间", "自主", "沟通模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 927, now()),
(100928, '分离不是背叛：允许家人在亲密中保有不同', '有些家庭把“像我们一样”当作爱的证明：喜好一致、想法一致、生活方式一致，才算亲近。可一个人长大后出现不同选择，往往只是发展自主性，并不必然代表背叛。若家人把差异解释成“不懂事、不爱我、出了问题”，双方都会更痛苦。更可修复的说法是：“我看见你和我不一样，这让我有点不安，但我愿意了解这对你意味着什么。”亲密不是互相复制，而是在不同中仍能保持连接。', '["家庭系统", "自主", "分离", "关系修复", "情绪理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 928, now()),
(100929, '沟通修复：把家庭故事从谁有问题改成我们怎样互动', '很多家庭冲突会形成一个固定故事：某个人总是错，其他人只是被迫应对。这个故事也许能暂时降低焦虑，却会让真正的互动模式被遮住。修复时可以换一种提问：在这个循环里，每个人各自做了什么？谁掌握信息，谁沉默，谁解释，谁被要求服从，谁最害怕关系破裂？当故事从“找出有问题的人”转为“看见共同生活如何运转”，对话就能出现新的入口：复述、道歉、澄清规则、重新分配责任。', '["关系修复", "家庭系统", "沟通模式", "互动循环", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 929, now()),
(100930, '把紧绷当作恐惧线索：先问“我在怕什么”', '恐惧不一定只表现为“我很害怕”。它也可能藏在肩膀上提、下颌咬紧、呼吸变浅、身体缩成一团、突然对人不耐烦，或在一个电话、一段谈话前感到恶心。练习时先暂停几秒，观察身体哪里紧、哪里想躲，再轻轻问自己：这里面有没有一个我还没说出口的担心？先命名，不急着解决，恐惧就从自动反应变成了可以被看见的信息。', '["恐惧识别", "身体信号", "情绪命名", "自我觉察", "焦虑调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 930, now()),
(100931, '恐惧会戴上很多面具：拖延、疲惫、烦闷也值得追问', '有些恐惧不会直接说“我怕”，而是变成拖延、工作狂、沉迷电视、暴饮暴食、睡眠困难、过度列清单、对小事烦躁、羡慕或怨恨别人成功。App 练习可以把这些状态当作入口：今天我是在休息，还是在躲开某件事？如果我继续不做，会避开什么不舒服的感受？不把自己贴上懒惰或没用的标签，只把它看成恐惧正在求保护。', '["恐惧识别", "回避循环", "拖延", "情绪命名", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 931, now()),
(100932, '把真实风险和想象灾难分开：恐惧常把过去投向未来', '恐惧本来有保护作用：看到真实危险时，身体快速警觉能帮助我们离开危险。但焦虑常把过去的不舒服经验投射到未来，把“可能会糟”升级成“必然会完”。可以写下三栏：真实事实是什么？我想象的灾难是什么？现在能做的一个小行动是什么？这样既不否认风险，也不让想象接管全部选择。', '["焦虑调节", "风险区分", "认知觉察", "灾难化", "小步行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 932, now()),
(100933, '用呼吸和身体记录找到恐惧源头', '当脑子很乱时，可以用短记录替代反复分析。找一个安静位置坐下或躺下，先听见自己的呼吸，再让念头自然浮现。结束后记录：我刚才想到过去还是未来？身体哪里收紧？呼吸有没有屏住？哪些画面让我最有感觉？连续做几次后，常能看见某些重复主题，例如被拒绝、失败、失控、受伤或被抛下。记录的目的不是审判自己，而是找到恐惧的名字。', '["焦虑调节", "呼吸觉察", "身体信号", "书写练习", "恐惧识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 933, now()),
(100934, '看见回避循环：越躲越安全，世界也越变越小', '回避能暂时降低焦虑，所以大脑会记住“躲开是安全的”。但长期看，电梯、电话、聚会、开车、求职、表达需求等情境会越来越像危险区，生活选择也随之缩小。识别回避循环时，可以写下：触发情境、身体反应、我躲开的动作、短期好处、长期代价。看清这个回路后，再决定是否要用很小、很安全的一步重新拿回选择。', '["回避循环", "焦虑调节", "恐惧症", "行为模式", "小步行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 934, now()),
(100935, '小步扩大安全区：在边界内靠近，而不是硬闯', '面对强烈恐惧时，目标不是证明自己“马上能做到”，而是在安全边界内学习。先选择一个非必须、可退出的时段，慢慢靠近让你害怕的情境；一旦觉察到恐惧开始萌芽，就停下，观察呼吸、手心、肩膀和念头，然后退回安全处。不要越过舒适范围。多次练习后，边界可能自然移动；即使没有完成目标，你也更了解自己的极限和选择。', '["小步暴露", "安全区域", "焦虑调节", "身体信号", "小步行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 935, now()),
(100936, '用柔和手势和呼吸给神经系统一个安全信号', '焦虑上来时，短促呼吸和僵硬动作会让神经系统更像处在危险中。可以试一个很小的安定动作：让拇指与其他手指轻轻相触，再像花打开一样慢慢分开，同时观察呼吸是否仍然柔和。也可以把双手合在胸前，配合自然呼气。重点不是动作幅度，而是温和、有节奏、能被身体感到。先在安全环境中练熟，再用于睡前、出门前或紧张情境前。', '["焦虑调节", "身体信号", "呼吸练习", "安抚神经", "自助练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 936, now()),
(100937, '给恐惧至少三个选择：从“只能这样”里退出来', '恐惧常让人以为只有两个选项：要么硬上，要么放弃。可以刻意写出第三、第四个选择，哪怕看起来很小或有点笨。例如害怕开车，不必只在“永远不开”和“立刻上高峰路”之间选；还可以先坐朋友车熟悉路线、只开安静小路、紧张时靠边停、请人陪同练习。选择越多，身体越不需要靠僵硬和控制来保护自己。', '["恐惧识别", "选择感", "小步行动", "控制感", "行动恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 937, now()),
(100938, '害怕失败或成功时，先做一个小改变', '害怕失败会让人不开始，害怕成功则可能让人在机会临近时自我破坏，因为成功意味着责任、期待、被看见或关系变化。恢复行动不靠喊口号，而靠一个小改变：整理一个抽屉、换一条散步路线、给旧同事发一条消息、把大目标拆成今天能做的五分钟。小改变会告诉身体：变化不等于坍塌，前进也可以保持动态稳定。', '["行动恢复", "失败恐惧", "成功恐惧", "微行动", "动态稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 938, now()),
(100939, '被拒绝和被抛下的恐惧：从取悦别人回到自我参照', '很多“不敢说、不敢选、不敢走自己的路”，底层不是能力不足，而是害怕被拒绝、被抛下、失去爱或失去群体位置。可以问自己：我现在是在表达真实需要，还是只是在避免别人不高兴？如果我不再以他人评价决定价值，我还想怎么选择？这不等于立刻和关系对抗，而是先把自尊从单一评价里收回来，再寻找更清楚、更温和的表达。', '["被遗弃恐惧", "自尊", "关系安全", "边界表达", "恐惧识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 939, now()),
(100940, '被压住的梦想：不必推翻人生，先重新连接一点点', '长期焦虑和身体僵硬，有时与一个从未说出口的梦想有关。它可能不是要你立刻辞职或重来，而是提醒你：生命里有一部分需要重新被看见。可以回想 8 岁左右最喜欢做的事，找一张照片、画一幅简图或写几个关键词，放在能看见的地方。每次看见它就问：我害怕什么？害怕拒绝、失败、被笑、太晚，还是失去现实安全？答案出现后，只做一个能承受的小连接。', '["行动恢复", "梦想连接", "恐惧识别", "书写练习", "小步行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 940, now()),
(100941, '用连接和倾听把注意力带回现在', '恐惧常把人拉到未来灾难或过去经验里，而倾听、运动、服务和真实连接能把注意力带回此刻。可以从一个低压力连接开始：认真听一个人说话，不在脑中急着反驳；加入散步、读书、志愿服务或兴趣小组；选择让人一起做事、而不是只互相抱怨的支持环境。行动不必宏大，关键是让身体重新体验：我不是孤立无援的，我可以和世界发生联系。', '["情绪支持", "当下觉察", "人际连接", "行动恢复", "倾听练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 941, now()),
(100942, '感知不是照相：先整合线索，再核对判断', '我们常把“我看见了”“我听见了”直接当成事实，但一次感知通常包含多个层次：眼耳鼻舌身接收线索，内在心智把颜色、声音、触感、位置和过去经验合在一起，再形成“这是什么、它对我意味着什么”的判断。自我观察时，可以把体验拆成三栏：我实际接收到什么感官线索；我脑中自动补出了什么解释；还需要向现实核对什么。这样做不是否定感觉，而是让感觉从最终判决变成可继续理解的资料。', '["心智哲学", "感知想象", "现实校准", "自我观察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 942, now()),
(100943, '想象会保存和重组经验：脑内画面需要现实校准', '想象不是随便乱想，它会保存曾经感知到的形式，也会把不同经验重新组合、分开和联想。它能帮助我们回忆、预演和创造，但在疲惫、恐惧、睡眠不足或情绪强烈时，脑内画面也可能像真实发生一样有说服力。练习时，可以先承认“这个画面正在我心里出现”，再问：它来自刚刚的事实、过去的记忆，还是对未来的推测？最后用一个小的现实反馈来校准它，而不是立刻被它带走。', '["感知想象", "现实检验", "情绪调节", "自我观察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 943, now()),
(100944, '欲望和回避常来自快速评价：看见判断，再选择行动', '很多冲动并不是凭空出现的。心智会先给某个对象贴上“有利、有害、亲近、危险、值得追求、需要躲开”的意义，随后身体和行动倾向才被带动。欲望、希望、恐惧、愤怒都可能包含这种快速评价。遇到强烈想要或强烈想逃时，不必马上压下去，也不必立刻执行。可以先问：我把这件事判断成了什么？它真的只意味着这一种结果吗？如果把感受和行动分开，我现在能选择哪一个较小、较稳的下一步？', '["欲望选择", "情绪理解", "行为选择", "身体心智", "自我观察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 944, now()),
(100945, '理性有两种用法：看清真假，也决定怎么做', '理性不只是想明白一个道理，也包括把道理落到具体处境里。可以把它分成两种练习：一种负责分辨真伪、证据和普遍规律；另一种负责在眼前处境中判断什么更好、什么更坏、什么值得做或暂时不做。做决定时，先不要把“事实判断”和“行动选择”混在一起。先写清楚：我知道的事实是什么、还缺什么证据；再写清楚：我重视什么、要承担什么代价、下一步能做什么。这样理性才既不空转，也不变成冷冰冰的自我逼迫。', '["理性反思", "决策思维", "行为选择", "自我观察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 945, now()),
(100946, '身体状态会拉动心智：先照顾系统，再讨论道理', '人在疲劳、疼痛、饥饿、害怕或情绪高涨时，理解和判断会变窄，并不是因为这个人“不讲理”，而是身体状态正在占用心智资源。感觉、想象、肉体快乐、愤怒、恐惧和痛苦都可能把注意力拉走，使理性反思暂时变弱。自我调节可以先从身体入口开始：睡一会儿、吃点东西、放慢呼吸、离开刺激源、把身体放稳。等系统恢复一点，再回到问题本身，往往比在高唤醒中强迫自己想通更有效。', '["身体心智", "情绪调节", "自我关怀", "理性反思", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 946, now()),
(100947, '我不等于一次感受：自我是整合经验的观察视角', '我们会说“我的手、我的脑子、我的感受、我的想法”，这提醒我们：自我并不等于某一个身体部位、某一个冲动，也不等于当下最强烈的一种情绪。身体和感官是我们行动与认识世界的重要工具，但“我”还包含一个能够觉察、整合和使用这些工具的视角。情绪强烈时，可以把“我就是很糟”改成“我正在体验羞耻、紧张或愤怒”；把“我控制不了”改成“我观察到身体、想法和欲望正在同时发生”。这种说法能为选择留出空间。', '["自我理解", "自我观察", "身体心智", "心智哲学", "情绪理解", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 947, now()),
(100948, '接纳不是认输：看清事实后再选择怎么回应', '接纳现实并不等于说“一切都好”，也不是让别人占便宜。它更像一次清醒的暂停：先承认事情已经这样发生，停止把精力耗在否认、反复设想和硬碰硬上，再问自己：我还需要坚持什么、拒绝什么、下一步能做什么？当人放下“必须立刻把现实改成我想要的样子”的压力，反而更容易保留判断力、边界和行动力。适合在计划被打乱、关系卡住、工作不顺时使用：先接受当下事实，再选择一个最小、清醒、对自己有益的回应。', '["接纳练习", "现实接纳", "行动选择", "边界感", "压力调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 948, now()),
(100949, '抗拒、接纳、放下：把强撑改成三步练习', '放下通常不是一下子做到心甘情愿，而是有过程。第一步是看见抗拒：我不想失去、不想改变、不想承认这件事发生了。抗拒本身不是失败，它只是压力下的自然警报。第二步是接纳：承认旧办法暂时行不通，自己已经尽力，继续强求只会消耗更多。第三步是放下：哪怕只有一点点愿意，也先暂停无效反应，比如停止反复追问、停止灾难化想象、停止用自责推动自己。这样做能把“我必须马上解决”转成“我可以一步一步回应”。', '["接纳练习", "放下控制", "抗拒觉察", "情绪允许", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 949, now()),
(100950, '可控与不可控分栏：把注意力收回自己能做的事', '当事情失控时，大脑容易把注意力全部投向不可控部分：别人会不会改变、结果会不会失败、过去为什么发生、外部环境何时好转。可以把纸分成两栏：左边写“我无法直接控制的事”，右边写“我此刻能影响的事”。可控项通常包括呼吸、核实信息、提出请求、设置边界、准备备选方案、把注意力放回正在做的一步。不可控项被看见后，不再反复咀嚼；可控项被写下后，马上选择一个最小行动。接纳不是放弃行动，而是把行动从幻想控制转回真实影响。', '["控制感", "可控不可控", "压力调节", "行动选择", "焦虑缓解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 950, now()),
(100951, '过度控制会放大压力：已经表达需求后练习松手', '焦虑上来时，人会把催促、施压、反复确认当成负责，结果常让对方更防御，关系也更紧绷。更有效的做法是先确认自己是否已经清楚表达需求、截止时间和可协商的下一步；如果已经表达，就把重点转向调节自己：深呼吸、离开屏幕几分钟、和可信任的人讨论、把感谢或合作意愿说出来。松手不是纵容失责，而是在能做的部分完成后，不继续用控制制造阻力。它让你把能量留给复盘、备选方案和下一次更清晰的协作。', '["放下控制", "过度控制", "职场压力", "关系协作", "压力调节", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 951, now()),
(100952, '给理智一个放下的理由：看见控制的收益与代价', '如果头脑一直说“我不能放手”，不要硬压它。可以给理智一个可理解的理由：过度控制短期像是在保护安全，长期却可能带来紧张、疲惫、人际防御和判断变窄。练习时写下一个控制习惯，例如必须最后拍板、必须马上回击、必须掌握所有信息；再写下它帮你避免了什么、又让你付出了什么代价。最后选择一次相反的小行为：少解释一句、多听十秒、把信息分享给同事、允许别人用不同方式完成。让理智看到“放下”能增强而不是削弱你的力量。', '["理智接纳", "控制感", "行为练习", "压力调节", "沟通选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 952, now()),
(100953, '允许情绪流动：感受它，而不是压住或爆发', '情绪允许不是任由自己伤人，也不是把难受压到没感觉。它的重点是先把情绪当作正在经过身体的一股浪潮：给它命名，比如害怕、委屈、愤怒、悲伤；感受它在身体哪里最明显；允许它存在几分钟，同时保持呼吸和观察。这样做能把“我就是这个情绪”改成“我正在经历这个情绪”。当强度下降后，再决定是否需要表达、求助、设边界或休息。对悲伤尤其如此，它可能一阵阵回来，允许眼泪和起伏存在，比命令自己立刻好起来更有助于恢复。', '["情绪允许", "情绪调节", "悲伤处理", "身体觉察", "接纳练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 953, now()),
(100954, '腹式呼吸暂停：让身体先从紧绷中松开', '担忧会让身体先紧起来，越紧越容易陷入反刍。可以做一个短暂停顿：一只手放胸口，一只手放腹部，用鼻子慢慢吸气，让腹部那只手轻轻升起；停留一两秒后，用嘴缓慢呼气，想象把肩颈、下巴和胸口的紧绷一起呼出去。连续做三轮，再问自己“此刻最小的一步是什么”。这个练习适合财务担心、等待消息、睡前焦虑、电脑出问题或通勤受阻时使用。身体先降速，头脑才更容易从灾难化想象回到当下。', '["腹式呼吸", "身体放松", "压力调节", "焦虑缓解", "当下练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 954, now()),
(100955, '冲突中先降温：放下赢输，保留边界', '冲突里的放下控制，不是放弃立场，而是不让对方的怒气牵着自己走。被激怒时先暂停回应，做几次缓慢呼气，让身体离开“马上反击”的状态；在恢复相对中立前，不急着辩解、讽刺或报复。等情绪稍降，再先承认对方立场中你能理解的部分，然后表达自己的看法、需求和一个可行的小改变。这样既不吞下委屈，也不把关系推向口水战。真正的掌控，是能选择回应方式，而不是被刺激自动按下旧按钮。', '["冲突降温", "沟通练习", "边界感", "情绪调节", "放下控制", "压力调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 955, now()),
(100956, '设定意向后放下执念：不把结果绑死在唯一剧本上', '在关系、求职、目标推进中，可以先认真设定意向：我真正想要的关系质量、工作方向或生活状态是什么？然后练习放下对某个人、某个时间表、某个唯一结果的抓取。放下不是降低标准，而是停止强迫现实必须按同一剧本发生。你仍然可以筛选、表达、争取和行动，但不再把全部价值押在一个对象或结果上。这样既保留方向，也给新的可能性留出空间；当某条路不合适时，更容易及时收手，转向对自己更健康的选择。', '["意向设定", "放下执念", "关系成长", "行动选择", "控制感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 956, now()),
(100957, '身体不适时的接纳：照顾失衡，而不是跟症状硬拼', '身体疲惫、生病或疼痛时，接纳不是放弃治疗，而是承认身体正在发出需要照顾的信号。与其一边硬撑一边自责，不如问：我现在需要休息、就医、睡眠、喝水、调整工作量，还是请人帮忙？也可以把注意力轻轻放在不适附近，尝试让周围肌肉变软，配合缓慢呼吸，减少和症状对抗带来的额外紧张。身体状态每天不同，允许自己根据当天的能量调整节奏。照顾身体本身就是行动，而不是软弱。', '["身体接纳", "身体放松", "压力调节", "睡眠休息", "行动选择", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 957, now()),
(100958, '言语伤害不只是在吵架：识别隐蔽的精神暴力信号', '言语虐待不一定表现为明显的辱骂，也可能是持续贬低、嘲讽、威胁、纠正、冷暴力、排斥孤立，或反复否定你的记忆和感受。判断一段话是否有伤害性，不只看对方是否“有意”，也要看它是否让你长期恐惧、困惑、自责、羞耻，甚至开始怀疑自己是否值得被尊重。先把这些互动命名为“伤害”，而不是急着解释为“我太敏感”，是恢复清晰感和自我保护的第一步。', '["言语虐待", "精神暴力", "煤气灯操纵", "情感伤害", "关系识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 958, now()),
(100959, '不要否认你的痛苦：把感受当作需要被照顾的线索', '面对言语和情感上的伤害时，否认常常是一种保护自己的方式：在还没有安全空间之前，人会先把痛苦藏起来。但如果长期不承认痛苦，焦虑、羞耻、困惑和无力感可能会越来越重。可以从一个小练习开始：想起一件近期挥之不去的言语伤害事件，只写下“发生了什么、我感到了什么、我现在需要什么”。不需要立刻原谅、解释或做决定；先允许自己承认：这件事让我受伤了，我的痛苦值得被看见。', '["创伤恢复", "情绪觉察", "自我接纳", "安全空间", "非否认"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 959, now()),
(100960, '战斗、逃跑、僵住、讨好：理解被触发时的身体反应', '被言语攻击触发时，身体可能比头脑更快反应：想反击、想立刻逃走、说不出话，或下意识讨好对方以避免冲突。这些反应不说明你软弱，也不说明你“处理得不好”，它们可能是神经系统在提醒你曾经感到不安全。恢复时可以先回到身体：做几次深呼吸，感受脚踩在地面上，扫描身体紧张的位置，并给情绪命名。先让自己稳定下来，再决定是否沟通、暂停或寻求支持。', '["创伤反应", "身体觉察", "情绪调节", "安全感", "讨好反应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 960, now()),
(100961, '把现实记录下来：区分事实、感受与他人投射', '长期言语伤害会让人分不清“事实是什么”和“别人让我相信什么”。可以建立一份只为自己服务的现实记录：时间地点、对方说了什么、我当时的身体反应、我产生了哪些想法、有哪些证据支持或反驳这些想法、如果朋友经历同样的事我会怎么回应。记录的目的不是收集材料去对抗谁，而是帮助自己从混乱、自责和被否定中重新找回清晰感。', '["记录现实", "煤气灯操纵", "认知澄清", "自我保护", "创伤恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 961, now()),
(100962, '有害羞耻不是你的本质：松动自责和内在批评', '健康的羞耻感会提醒我们某个行为偏离了自己的价值；有害羞耻感却会把“我做错了事”变成“我这个人就是错的”。言语虐待很容易把别人的愤怒、贬低和未处理的痛苦投射到你身上，让你误以为自己不够好。恢复时可以问自己：这个批评的声音最像谁？它说的有事实依据吗？我会这样对一个受伤的朋友说话吗？用更温和、具体、基于事实的话回应自己，是重建自尊的重要开始。', '["有害羞耻", "内在批评", "自尊恢复", "自我同情", "创伤修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 962, now()),
(100963, '边界不是自私：用价值观保护自己的内在空间', '边界不是惩罚别人，也不是控制别人，而是确认“我是谁、我重视什么、什么互动会伤害我”。经历言语虐待后，人可能会把设定边界误解为自私、冷漠或会破坏关系，但健康边界恰恰是在保护恢复所需的空间。你可以先写下自己的核心价值和不可接受的互动，例如辱骂、吼叫、隐私侵犯、持续贬低或被迫回应。边界的重点是你将如何照顾自己：暂停谈话、离开冲突、寻求支持，或重新安排接触方式。', '["关系边界", "价值观", "自我保护", "精神暴力", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 963, now()),
(100964, '温和但坚定地说“不”：从个人权利开始练习边界', '当你习惯了取悦、解释或压下感受，说“不”可能会让你内疚。可以先从确认个人权利开始：你有权被尊重，有权表达感受，有权不同意，有权在答应请求前了解内容，也有权远离冲突。若环境安全，可以使用以“我”为主体的表达，例如“当声音变大时，我会害怕，我需要先暂停一下”。如果沟通会增加危险，不必强迫自己当场说明；保护安全、减少刺激、联系可信的人，同样是边界的一部分。', '["关系边界", "拒绝练习", "个人权利", "自信沟通", "安全计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 964, now()),
(100965, '选择安全的见证者：让支持系统参与恢复', '言语虐待常让人孤立，越需要连接时越不敢靠近别人。恢复不必独自完成，可以先找一个安全的见证者：能倾听、不打断、不急着给建议、尊重你的节奏，也不会把你的经历拿去评判或传播。这个人可以是朋友、家人、支持小组成员或专业助人者。你不需要一次说完全部故事，可以从“我最近在整理一段让我受伤的关系，我需要被听见”开始。被可靠的人看见，会帮助你重新相信自己的感受。', '["支持系统", "社群连接", "创伤恢复", "安全关系", "求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 965, now()),
(100966, '重建自尊从小成功开始：用证据挑战无价值感', '持续的言语贬低会让人形成“我没用、我有缺陷、我不配”的普遍感受。重建自尊不需要一开始就相信自己很强大，可以从更小、更可验证的证据开始：写下十个让你与众不同的品质，每周完成一个小目标，并记录“我做到了什么”。当消极想法出现时，问自己：这是事实还是感受？有相反证据吗？我会对朋友这样下结论吗？一次小小的完成、庆祝和复盘，都在帮助你把自我价值从别人的评价中拿回来。', '["自尊恢复", "限制性信念", "小目标", "自我价值", "认知澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 966, now()),
(100967, '自我照顾也是安全计划：为求助、休息和离开做准备', '自我照顾不是奢侈，也不是等问题解决后才做的事；它可以是一份现实的安全计划。你可以列出可信联系人、专业支持、可暂时停留的安全地点、重要证件和必要物品，想好情绪强烈时先联系谁、如何让自己远离冲突、如何安排休息和屏蔽社交媒体的时间。如果一段关系持续让你恐惧、被控制或失去自我，先和可信的人讨论求助与离开的准备，而不是把计划当作威胁或对抗。需要帮助时寻求帮助，本身就是照顾自己。', '["自我照顾", "安全计划", "求助准备", "离开准备", "支持系统", "关系边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 967, now()),
(100968, '区分内疚和羞耻：从“我做错了”回到“我可以修”', '内疚和羞耻常一起出现，但方向不同。内疚更像在说：“我做了什么，影响了谁？”它能把注意力带向对方的感受和可修复的行为。羞耻更像在说：“我这个人很糟。”它容易带来躲藏、自我攻击或反击。练习时先把“我很差”改写成三句：我做了什么；造成了什么影响；我现在能补哪一步。', '["内疚", "羞耻", "情绪辨识", "自我接纳", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 968, now()),
(100969, '内疚的出口是补救，不是反复惩罚自己', '内疚的价值在于提醒你关系可能受损，而不是让你在脑内一遍遍审判自己。越重要的关系，内疚往往越强，因为你更在意对方和关系的未来。可以把内疚转成三件事：承认具体影响，询问对方需要，提出可执行补救。做完这些以后，允许自己停止惩罚，继续用稳定行动证明改变。', '["内疚", "关系修复", "责任", "补救行动", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 969, now()),
(100970, '承担代价可以表达悔意，但不等于伤害自己', '资料中提到，自我惩罚有时会被对方理解为“我愿意为伤害付出代价”的信号。但在 App 中更适合把它转成非伤害性的承担成本：花时间修复、归还资源、接受合理后果、公开更正、减少辩解。真诚不是让自己更痛，而是让对方看见你愿意为具体影响负责。', '["内疚", "自我惩罚", "道歉边界", "关系修复", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 970, now()),
(100971, '道歉不只是“对不起”：让对方看见影响和改变', '一句“对不起”有时不够，尤其当伤害较重时。更完整的道歉可以包含四步：说出事实，说出对对方的影响，承担自己的部分，给出可验证的后续行动。不要把道歉变成索取原谅，也不要用“我已经很惨了”逼对方心软。对方有权需要时间；你能做的是持续、具体、稳定地修复。', '["道歉边界", "关系修复", "内疚", "责任", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 971, now()),
(100972, '羞耻来袭时，先停下“我整个人都不行”', '羞耻会让注意力缩到“别人怎么看我”和“我是不是很差”。这时先不要急着证明自己，也不要马上反击。可以做一个去羞耻暂停：命名情绪，分清事实和评价，把“我很糟”改成“我在某件事上暴露了不足”。自我价值先落地，才更容易决定接下来要解释、补救、练习，还是离开不健康的评价环境。', '["羞耻", "自我攻击", "自我接纳", "情绪调节", "去羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 972, now()),
(100973, '羞耻后的躲藏冲动：用低风险连接重新露面', '羞耻常伴随想躲起来、消失、断联的冲动。短暂退开可以保护自己，但长期躲藏会让大脑更相信“我不能被看见”。可以选择低风险连接：给可信任的人说一句“我现在有点羞耻，不需要评价，只想被陪一下”；或者先完成一个很小的现实动作，再决定是否谈细节。修复不是立刻公开一切，而是慢慢恢复可连接感。', '["羞耻", "回避", "关系支持", "自我接纳", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 973, now()),
(100974, '羞耻会变成愤怒：先照顾疼痛，再处理冲突', '羞耻的心理疼痛很强，有时会转成愤怒：开始挑对方问题、推开责任，或用攻击保护面子。愤怒出现时先问自己：我是在维护边界，还是在躲避“我不够好”的疼？如果是后者，先让身体降温，再只回应眼前事实。这样既不吞掉委屈，也不把羞耻变成伤人的武器。', '["羞耻", "愤怒", "情绪调节", "身体反应", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 974, now()),
(100975, '被看见失误时：控制愤怒不等于讨好退让', '当别人已经知道你的失误或缺点，羞耻会让你特别在意评价。资料中的实验显示，这类情境下人可能压住愤怒，以免关系更坏。App 可以提醒：控制愤怒不是讨好，也不是放弃边界。先确认安全和底线，再选择不升级冲突的表达：“我需要先冷静，但我会负责这件事，也会说明我的感受。”', '["羞耻", "愤怒管理", "边界", "关系修复", "道歉边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 975, now()),
(100976, '身体很痛时，把身体当报警器，而不是惩罚对象', '内疚和羞耻都可能带来强烈心理疼痛，身体也会跟着反应：脸热、胸口紧、胃下沉、想缩小，甚至想用疼痛抵消情绪。先把身体从“该被惩罚的对象”改成“正在报警的系统”：脚踩地、慢呼吸、喝水、放松肩颈。身体反应强，不代表你很坏，只说明关系、责任或评价威胁触发了警报。', '["身体反应", "内疚", "羞耻", "情绪调节", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 976, now()),
(100977, '把“如果我是另一个人”改成“下次换一个做法”', '出问题后，大脑可能会想：“如果我不是这样的人就好了。”这会把人推向羞耻和自我否定。更有帮助的问题是：“如果下次早一点提醒、多问一句、换个步骤，会怎样？”把反事实思考从人格改成行为，不是否认责任，而是把精力放回可改变的地方。能改变的越具体，情绪越容易转向修复。', '["反事实思考", "羞耻", "内疚", "行为改变", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 977, now()),
(100978, '情绪要和事件匹配：过度内疚和过度羞耻都要降温', '内疚和羞耻不必被简单贴成坏情绪。它们在强度适中、与事件匹配时，能提醒我们照顾关系、保护连接；如果强到让你长期自责、躲避、攻击或无法行动，就需要降温和支持。可以看三个指标：情绪是否指向具体事件；是否能导向行动；在修复或澄清后是否逐渐减轻。', '["内疚", "羞耻", "情绪调节", "自我接纳", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 978, now()),
(100979, '补偿不只是给钱：修复尊严和信任需要承担后果', '有些伤害不能只靠“赔钱”解决，尤其当它触碰尊严、公平、信任或价值观时。修复可以先从承担后果开始：公开更正，归还决定权，接受监督，花时间弥补，停止再次伤害。补偿的核心不是买走对方的痛，而是让对方看见你理解了伤害的意义，也愿意为防止重复付出代价。', '["关系修复", "补偿", "道歉边界", "责任", "信任修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 979, now()),
(100980, '内疚修复三问：把对方重新带回视野', '内疚修复时，不要只盯着自己有多难受。可以把注意力带回对方：对方失去了什么？最需要我承认哪一点？什么行动能减少未来伤害？如果一直停在“我太差了”，情绪看似很深，却没有修复力。把对方的感受和需要带回视野，内疚才会成为连接，而不是内耗。', '["内疚", "共情", "关系修复", "自我攻击", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 980, now()),
(100981, '儿童虐待不只等于重暴力：冷落、羞辱和忽视也需要被看见', '很多家庭会把打骂、羞辱、长期冷落或照顾不足理解成“管教”或“家务事”，但儿童保护关注的是孩子的安全、尊严和发展是否受损。家长可以先把“我是不是在帮助孩子成长”放在“我是不是有权惩罚孩子”之前：停止让孩子在恐惧、羞耻或孤立中服从，改用清楚规则、稳定回应、正面引导和必要的专业支持。App 内容只做儿童保护提醒，不能替代法律、医疗或心理专业判断。', '["儿童保护", "风险识别", "亲子支持", "非暴力管教", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 981, now()),
(100982, '发现疑似受伤或被羞辱的孩子：先靠近支持，再连接资源', '身边孩子如果在公共场合被羞辱、看起来害怕、哭泣退缩，旁观者不必先判断谁对谁错。更安全的做法是用平静语气询问孩子是否需要休息、喝水或联系可信大人，避免围观、指责和激化冲突；同时尽量与照顾者沟通可用的亲子教育、社工、医院、妇联或公安等资源。目标不是替家庭“定罪”，而是让孩子尽快离开持续受伤的处境，让照顾者也得到有效帮助。', '["儿童保护", "旁观者支持", "求助路径", "亲子支持", "风险识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 982, now()),
(100983, '儿童风险识别：看连续模式，不凭单一表现贴标签', '孩子突然退缩、睡眠饮食变化、学业明显下滑、害怕特定人或地点，或受伤解释前后不一致，都值得被认真看见。但单一迹象不能直接等于虐待诊断，更不能在孩子面前审问或贴标签。App 端可以引导用户记录时间、场景、照顾者解释、孩子自己的表达和是否反复出现；一旦存在当前危险、严重伤情、孩子明确求助或照顾者拒绝合理帮助，应尽快联系医疗、学校、社工、妇联、公安等专业支持。', '["风险识别", "儿童保护", "非诊断", "求助路径", "创伤敏感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 983, now()),
(100984, '情感虐待常是“看不见的伤”：长期贬低、隔离和无回应都要警惕', '持续指责、讽刺、贬低、恐吓、把孩子当替罪羊、长期拒绝回应孩子的情绪需求，可能会破坏孩子的安全感、自尊和信任能力。家长可以把“你怎么这么差”改成“我看到这个问题，我们一起想办法”，把命令和羞辱改成具体规则、可执行请求和情绪安抚。如果家庭压力、伴侣冲突或照顾者情绪失控反复影响孩子，优先寻求家庭咨询、父母互助、儿童心理或社工支持。', '["情感虐待", "亲子沟通", "儿童保护", "心理安全", "亲子支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 984, now()),
(100985, '忽视不等于贫穷：关键是孩子的基本需要是否持续无人回应', '儿童忽视包括身体照护、情感回应、医疗保健、教育机会、安全环境和社会环境等多个面向。贫穷家庭首先需要资源和支持，不能简单指责；但如果照顾者长期拒绝合理帮助，孩子又持续缺少食物、睡眠、卫生、就医、上学、安全看护或情感交流，就需要提高警觉。对 App 用户来说，最实用的行动是先补足孩子当下需要，再联系学校、社区、社工、医疗或儿童保护相关部门。', '["儿童忽视", "儿童保护", "风险识别", "亲子支持", "求助路径"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 985, now()),
(100986, '非暴力管教：严格可以和友好同时存在', '不打不骂不等于没有规则。更有效的管教可以是：用平和语气说明边界；大人生气时先暂停，约定稍后再谈；教孩子下次怎么做，而不只是惩罚错误；用正向、具体、可执行的话表达要求；在合理范围内给孩子选择和弹性；把冲突变成一起解决问题的机会。惩罚越重不一定越有效，真正能保护关系的，是稳定、一致、尊重和成人先调节自己的情绪。', '["非暴力管教", "亲子沟通", "情绪调节", "亲子支持", "儿童保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 986, now()),
(100987, '高风险家庭需要支持，不是羞辱：先减压、补技能、建连接', '儿童虐待风险常与多重压力叠加有关，例如照顾者童年受虐、育儿知识不足、社会孤立、伴侣冲突、经济困难、情绪失控、物质滥用，或孩子有特殊照护需要。识别这些因素不是给家庭贴“坏父母”标签，而是提醒尽早补上支持：育儿技能训练、喘息照护、家访、父母互助、心理咨询、医疗随访和社区资源。越早让家庭被看见、被支持，越可能降低孩子继续受伤的风险。', '["风险识别", "亲子支持", "家庭压力", "儿童保护", "预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 987, now()),
(100988, '身体边界教育：让孩子知道“不保密、不自责、一直求助到被保护”', '儿童安全教育不需要恐吓孩子，而是用年龄能理解的语言建立家庭安全原则：哪些成人可信，哪些身体边界需要被尊重，哪些秘密不该替别人保守。孩子要知道，当有人让自己不舒服、要求保密或越过边界时，可以说“不”、离开现场、去安全地方，并告诉父母、老师或其他可信成人；如果第一个大人没有相信，就继续告诉下一个，直到得到保护。任何越界都不是孩子的错。', '["儿童保护", "身体边界", "安全教育", "求助路径", "创伤敏感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 988, now()),
(100989, '孩子说出受伤经历时：相信、保持平静、说明下一步', '当孩子主动讲出让自己害怕或受伤的经历，成人最重要的第一反应是相信并接住，而不是震惊、责怪、追问细节或要求孩子马上证明。可以说：“谢谢你告诉我，这不是你的错，我会陪你一起找能保护你的人。”随后用孩子听得懂的话说明接下来可能联系谁、为什么需要帮助，并尽量让孩子参与安全安排。涉及现实危险、身体不适或违法风险时，应联系医疗、儿童保护、公安或法律专业人员处理。', '["创伤敏感", "亲子沟通", "儿童保护", "求助路径", "心理支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 989, now()),
(100990, '求助路径要提前准备：学校、医院、社工、妇联和公安都可能是入口', '儿童保护不是单靠某一个人完成的。普通用户可以提前保存本地可用资源：班主任或学校心理老师、社区工作者、妇联、儿童保护机构、医院儿科急诊或心理科、公安派出所、法律援助等。报告时尽量提供孩子基本信息、发生时间地点、已观察到的风险和当前安全状况，同时保护儿童隐私，不在群聊或社交平台扩散。App 可以帮助用户整理信息，但法律判断、医疗诊断和强制处置必须交给相应专业部门。', '["求助路径", "儿童保护", "风险识别", "隐私保护", "专业转介"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 990, now()),
(100991, '儿童保护沟通：少审问、多倾听，让孩子在安全环境里表达', '疑似儿童受伤害时，成人的沟通方式会影响孩子是否敢继续求助。更安全的做法是选择安静、私密、没有疑似施害者在场的环境，用孩子听得懂的语言提开放问题；不要随意打断、诱导、威胁、嘲笑或用羞辱性词语。记录事实时区分“孩子说了什么”“我看见了什么”“我推测什么”，并及时转给专业人员。这样的沟通既保护孩子，也避免普通人把判断做过头。', '["创伤敏感", "儿童保护", "风险识别", "亲子沟通", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 991, now()),
(100992, '预防比补救更重要：儿童保护需要三级支持网', '儿童虐待可以预防，重点不是等伤害发生后才处理。一级预防面向所有家庭：普及儿童权利、非暴力管教、身体边界和求助知识；二级预防面向压力较高或照护困难的家庭：提供家访、育儿训练、医疗随访和社区支持；三级预防面向已发生伤害的儿童：确保安全、不再受伤，并提供医疗、心理、教育和家庭修复支持。App 端可以把这些内容做成日常提醒、风险自查和本地资源导航。', '["预防", "儿童保护", "非暴力管教", "求助路径", "亲子支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 992, now()),
(100993, '家庭仪式不是形式感：它给孩子可预期的安全和方向', '家庭仪式不一定是盛大的庆祝，也可以是每天重复的小动作：一起吃饭、睡前拥抱、出门前一句固定的祝福、周末一起整理计划。对孩子来说，可预期的流程会减少“接下来会怎样”的不安，让他们更容易配合日常安排，也更愿意信任照顾者。好的仪式不是控制孩子，而是把时间、规则和关系变得清楚、温暖、可依靠。', '["家庭仪式", "安全感", "日常秩序", "亲子沟通", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 993, now()),
(100994, '早晨少一点催促：用固定流程和几分钟自由开启一天', '很多亲子冲突发生在早晨：起床、洗漱、穿衣、吃早餐、出门都挤在一起。可以把早晨拆成固定顺序，并为孩子预留几分钟“醒来后的自由时间”，例如安静躺一会儿、抱抱、听一小段音乐、自己选衣服或看天气决定外套。流程稳定后，孩子会知道下一步是什么；保留一点选择权，也能减少被催促和被支配的感觉。', '["日常秩序", "家庭仪式", "亲子沟通", "自主感", "情绪稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 994, now()),
(100995, '共餐是每天的连接窗口：在餐桌上练习归属、倾听和规则', '一天至少留出一次相对稳定的共餐时间，能让孩子感到“我是这个家的一部分”。餐桌上可以有简单开场，例如一句开饭词、轮流摆餐具、饭后一起收拾，或每个人分享今天的一件小事。餐桌规则不必严厉，但要清楚：什么时候开始、谁负责什么、如何轮流说话。这样的共餐既是营养支持，也是家庭对话和归属感的练习。', '["家庭仪式", "共餐", "亲子沟通", "归属感", "规则感", "日常秩序"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 995, now()),
(100996, '睡前仪式要安静可重复：把一天收束到安全感里', '睡前最需要的是可重复、低刺激、能安顿身体和情绪的顺序。比如整理房间、洗漱、换睡衣、读故事、说晚安、亲吻拥抱、放好安抚物、留一盏小夜灯。孩子反复说“不想睡”时，家长可以保持温和坚定，重复流程，而不是把床当惩罚或在睡前翻旧账。稳定的睡前仪式会让孩子把床和休息、安全、被照顾联系在一起。', '["睡前仪式", "安全感", "情绪稳定", "亲子连接", "日常秩序"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 996, now()),
(100997, '规则需要温柔边界，也需要孩子可呼吸的自由时间', '仪式和规则能让生活更顺，但不应把家庭变成没有弹性的时间表。适合孩子的秩序，既有明确边界，也保留自由活动、发呆、玩耍和选择的空间。家长可以先从一两个最需要改善的流程开始，不要一次塞满很多仪式；随着孩子长大、家庭结构变化，也要定期调整。好的家庭仪式是被理解和愿意参与的，不是被迫完成的任务。', '["规则与自由", "家庭仪式", "儿童发展", "自主感", "日常秩序", "心理支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 997, now()),
(100998, '分离不是突然放手：用道别仪式和陪伴物帮孩子过渡', '孩子害怕分离时，真正需要的是“我会回来、你会被照顾”的确定感。可以设计简短固定的道别：拥抱、亲吻、说清楚谁来接、把一个小玩偶、布巾、石头或带有父母气味的小物交给孩子。道别不要偷偷离开，也不要无限拖长；温柔而坚定地离开，反而能让孩子慢慢相信流程可靠。每次接回时再用拥抱和问候完成团聚仪式。', '["分离过渡", "安全感", "亲子连接", "幼儿园适应", "家庭仪式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 998, now()),
(100999, '入园入学前先预演：把陌生环境变成孩子见过的路线', '进入幼儿园或小学，是孩子从家庭走向更大世界的关键过渡。与其只说“别害怕”，不如提前把陌生变熟悉：一起参观园所或学校、读相关绘本、走几次上学路线、模拟早晨道别和班级活动、让孩子参与挑选书包或用品。预演不是制造压力，而是让孩子知道会发生什么、自己能做什么，也让父母用积极语言陪孩子跨过新阶段。', '["入园入学", "分离过渡", "儿童发展", "安全感", "亲子沟通", "日常秩序"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 999, now()),
(101000, '拥抱、击掌和问候：微小肢体连接能让孩子被看见', '亲子连接不只靠长谈，也藏在每天短短几秒的身体回应里：出门前特别的吻，回家后一个拥抱，成功时击掌，晚餐后坐在父母腿上聊几分钟。对孩子来说，这些重复的小动作会变成“我被欢迎、被认可、被安慰”的信号。家长不必追求复杂方法，只要在道别、问候、鼓励和安抚时稳定出现，孩子就更容易感到被看见。', '["亲子连接", "亲子沟通", "安全感", "情绪支持", "家庭仪式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1000, now()),
(101001, '孩子害怕时先认真对待：把恐惧转成可携带的勇气资源', '孩子说害怕怪兽、上学、表演或新挑战时，先不要急着否认“这有什么好怕”。更有帮助的是承认害怕存在，再和孩子一起做一个可用的勇气资源：勇气石、守护小物、勇气手提箱、画下恐惧再撕掉、练习一句支持自己的话。父母的语气也很关键，多说“我相信你可以试试看”，少用“别出事”“你会不会不行”来强化担忧。', '["恐惧应对", "安全感", "勇气", "儿童发展", "亲子支持", "情绪稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1001, now()),
(101002, '家庭会议让孩子参与规则：家务和安排可以一起商量', '当家庭安排总靠父母临时通知，孩子容易只感到被要求。可以每周或每月开一次简短家庭会议：聊这段时间发生的事、下周计划、谁负责哪些家务、周末一起做什么。为了让孩子真正参与，可以使用“发言物”，谁拿着谁说话；家务也可以做成轮值表或箭头盘。孩子被允许参与规则，才更容易把规则当成共同生活的约定。', '["家庭会议", "规则感", "亲子沟通", "家务分工", "自主感", "日常秩序"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1002, now()),
(101003, '争吵之后要有和解路径：让孩子知道爱不会因为冲突消失', '家庭里有争吵并不代表关系失败，关键是孩子能不能看见冲突之后如何修复。可以约定一个冷静流程：先分开休息几分钟，等情绪降下来再说发生了什么；说不出口时，可以写字条、画爱心、举“白旗”表示想停止争吵。和解时不必追求谁彻底赢了，而是让孩子学会道歉、表达感受、重新靠近，并确认彼此的爱仍然在。', '["冲突修复", "亲子沟通", "情绪稳定", "家庭仪式", "道歉", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1003, now()),
(101004, '变化和困难中保留固定成分：给忧虑、生病和离异中的孩子一条线', '当孩子遇到烦恼、生病、看医生、搬家、父母离异或亲人离世时，家庭更需要保留一些熟悉的固定成分。比如睡前电话、固定探视频率、病中专属故事、疼痛时的安抚歌、写信或画画表达思念。困难无法被仪式抹掉，但稳定的小流程能告诉孩子：虽然生活有变化，仍然有人记得我、接住我、按约定回来。', '["特殊处境", "安全感", "家庭仪式", "情绪支持", "分离过渡", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1004, now()),
(101005, '心理防御入门：它是在保护感受，不是给人贴标签', '心理防御可以理解为心灵的“保护动作”：当焦虑、羞耻、愤怒、失望等感受太难承受时，我们可能会自动把某些感受、想法或愿望挡在意识之外。它不等于“这个人有问题”，也不是用来给伴侣、家人或自己贴标签。更适合的用法是温和自查：我现在最不想感受到的是什么？这个反应短期保护了我什么？它长期是否让我更难解决问题、靠近他人或表达需要？看见防御的目标不是立刻拆掉它，而是在安全感足够时增加一点选择。', '["心理防御", "自我觉察", "心理教育", "情绪调节", "去标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1005, now()),
(101006, '否认与最小化：先轻轻承认现实，再决定下一步', '否认不是“装傻”，很多时候是人暂时不敢面对某个现实；最小化则是已经隐约知道有事发生，却习惯说“没什么大不了”。这两种反应能让人短期稳住，但如果反复出现，就可能延误求助、沟通或边界行动。App 端可以引导用户用低压力句式靠近现实：我暂时不需要把事情夸大，也不需要马上解决；我只先写下三个可观察事实、一个我最怕承认的影响、一个今天能做的小动作。承认现实不是自责，而是把方向盘慢慢拿回来。', '["否认", "最小化", "自我觉察", "情绪调节", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1006, now()),
(101007, '投射自查：我看到的对方，是否也有我的情绪影子', '投射常发生在关系紧张时：我以为自己只是在判断对方，其实可能把自己的愤怒、恐惧、羞耻或愿望放到了对方身上。例如“TA 一定讨厌我”有时也包含“我正在生气，却不敢承认”。自查投射不是替对方开脱，也不是把责任都揽到自己身上，而是在行动前多一个校准步骤：事实是什么？我加上的解释是什么？这个解释是否反映了我自己的担心？如果对方确实有伤害行为，我仍然可以保留边界；如果只是误读，就有机会少一次冲突升级。', '["投射", "关系误读", "自我觉察", "事实解释分离", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1007, now()),
(101008, '合理化自查：理由很充分时，也问问我在避开什么', '合理化会给困难行为找出听上去很有道理的解释：我太忙所以不沟通、我这样做是为你好、我只是需要某个外在原因才能行动。理由可能有一部分真实，但也可能遮住更难说出口的感受，例如内疚、害怕被拒绝、对亲密的不满。温和的自查方式是：如果这些理由都成立，我仍然还在回避哪一个事实或感受？这个解释帮助我少感到什么？有没有一个更诚实、但不攻击自己的说法？把合理化松开一点，关系里才更容易出现真实请求和修复行动。', '["合理化", "自我觉察", "关系修复", "真实表达", "心理防御"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1008, now()),
(101009, '退行时刻：压力大时回到旧反应，先安抚再选择', '退行可以理解为人在压力下暂时回到更早、更熟悉的应对方式：变得特别依赖、固执、像孩子一样赌气，或突然不会使用平时拥有的判断和表达能力。这不必被羞辱成“幼稚”，它往往说明系统过载了。App 端更适合先帮用户降唤醒：喝水、呼吸、离开刺激源、找安全的人确认现实。等身体稍稳后再问：我现在像回到了哪个旧场景？我真正需要的是照顾、边界、被理解，还是休息？退行被看见后，下一步才有可能从自动反应变成主动选择。', '["退行", "压力反应", "情绪调节", "自我安抚", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1009, now()),
(101010, '情感隔离与理智化：只讲逻辑时，也给身体和感受留位置', '有些人谈起很痛的事时非常平静，能把前因后果讲清楚，却感受不到悲伤、愤怒或委屈；也有人不停分析理论、原因和方案，却始终不触碰自己的心情。这可能是情感隔离、理智化或超理性的保护：思维还在，感觉被关到了门外。它在紧急时能帮人保持判断力，但在亲密关系里会让对方觉得“你不在场”。练习时不必强迫自己崩溃，只需补上一句身体和情绪线索：我说这件事时胸口如何？如果这个经历发生在朋友身上，我会觉得 TA 可能有什么感受？', '["情感隔离", "理智化", "身体觉察", "情绪调节", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1010, now()),
(101011, '反向形成：过度友好或过度镇定背后的真实感受', '反向形成是把一个难以承认的感受转成相反表现：很生气却异常客气，明明受伤却笑得很轻松，害怕失控于是过度守规矩、过度完美。它保护了内疚和焦虑，也可能让真实需要长期说不出口。自查时可以关注“过度”两个字：我是不是比平时更用力地友好、讲理、镇定或完美？如果允许自己只承认 10% 的真实感受，那会是什么？在关系里，温和表达可以是：我刚才表现得没事，但其实有一点受伤/生气，我想慢一点说清楚。', '["反向形成", "真实表达", "自我觉察", "关系修复", "情绪识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1011, now()),
(101012, '置换与迁怒：把情绪从安全出口带回真正议题', '置换是把对某个人或某件事的感受转移到另一个更安全的人、场景或小事上。比如在工作里受了压，却回家后因为杯子没放好而爆发；对伴侣失望，却把火发到孩子或自己身上。发现置换时，不要只责备“我怎么又失控”，可以先追踪情绪来源：这股火最早从哪里开始？我真正不敢面对谁或什么议题？下一步是把强度降下来，再用更准确的对象和更小的句子表达：我今天的焦虑不全是你的错，我需要先缓一缓，之后再谈真正让我难受的事。', '["置换", "迁怒", "情绪调节", "关系修复", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1012, now()),
(101013, '回避与疏远：距离能降压，也需要约定何时回来谈', '回避会让人离开那些引发冲突感受的情境：不回消息、不谈关系、不去某个地方，或突然把自己从亲密里撤走。距离本身不坏，很多时候它能防止争吵升级；但如果没有说明和回归，就容易被对方体验为冷漠、抛弃或不负责。更成熟的做法是把回避变成“有边界的暂停”：我现在太紧绷，继续谈会伤人；我需要 30 分钟冷静；今晚 9 点我们只谈一个具体问题。这样既尊重自己的承受度，也给关系留下修复入口。', '["回避", "疏远", "关系修复", "边界", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1013, now()),
(101014, '幽默的成熟用法：让痛苦可承受，而不是被一笑带过', '幽默可以让沉重的情绪变得可承受，也可能变成绕开痛苦的方式。成熟的幽默通常带着温柔和连接感：它不羞辱别人，不否认现实，也不阻止后续沟通；防御性的幽默则常在紧张时自动冒出，让人笑完以后仍然不敢说真实感受。App 端可提示用户区分：这个玩笑让我更能面对问题，还是让我不用面对问题？对关系更友好的句式是：我刚刚开了个玩笑缓一下，但认真说，我其实有点难过/害怕/尴尬。这样幽默就成了桥，而不是墙。', '["幽默", "成熟防御", "情绪调节", "真实表达", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1014, now()),
(101015, '升华练习：把强烈能量转成创造、运动与服务', '升华不是压抑冲动，而是给强烈能量找一个不伤人、能创造价值的出口。愤怒可以转成维护边界、运动或推动规则改进；渴望被看见可以转成作品、表达和长期训练；攻击性能量也可以进入竞技、劳动、艺术或保护他人的行动。练习步骤是：先承认“这股能量存在”，再问“如果不直接冲出去伤人，它能支持哪件有意义的事？”最后安排一个具体出口，如走路二十分钟、写一页、完成一项整理、给需要的人提供实际帮助。', '["升华", "成熟防御", "情绪调节", "创造力", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1015, now()),
(101016, '成熟防御组合：有意识地暂停、承认感受和选择出口', '防御并不都需要被消灭。关键差别在于：它是否让人更能面对现实、保护关系、做出选择。比较成熟的用法，是在情绪太强时先有意识暂停，不立刻按冲动行动；承认“我现在不想碰这个感受”，而不是假装没有；再选择不伤人的出口，比如幽默降温、升华行动、写下来、找人商量或约定稍后再谈。这样做不是逃避，而是让心灵的保护从自动断电变成可调节的开关。App 端可把它设计成“暂停—命名—选择出口”的小练习。', '["成熟防御", "压制", "幽默", "升华", "情绪调节", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1016, now()),
(101017, '关系中的防御识别：先问它保护了什么脆弱感受', '关系冲突里，防御常常成组出现：一个人否认影响，另一个人投射恶意；一个人理智化，另一个人用夸大或迁怒争取被看见。只追究“谁对谁错”容易让防御更硬。更有帮助的问题是：这个反应保护了什么脆弱感受？它短期避免了什么痛？它长期让关系付出了什么代价？当双方能把“你就是这样”改成“我们好像进入了一个保护模式”，关系里就多了共同面对问题的空间。注意，这不等于纵容伤害；事实、责任和边界仍然要清楚。', '["心理防御", "关系修复", "冲突循环", "自我觉察", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1017, now()),
(101018, '修复对话里的防御：好奇地命名模式，别急着定罪', '指出防御很容易被听成指责，所以在亲密关系和自我对话中，更适合用“好奇地命名模式”而不是“你在防御”。可以说：我注意到我们一谈到这件事，你会解释很多，我会开始追问；这可能是在保护我们不碰到更难受的部分。接着邀请具体化：我们先各自说一个感受、一个担心、一个请求。合适的时机也很重要：人在高度羞耻、愤怒或恐惧中，先需要降温和安全感；等情绪稍稳，再讨论模式和责任，修复更容易发生。', '["关系修复", "防御识别", "沟通模板", "安全感", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1018, now()),
(101019, '自我觉察五问：事实、感受、解释、防御和需要', '把防御用于 App 端，最安全的方式不是让用户给自己下结论，而是提供一组可复盘的问题。第一，事实：我实际看见或听见了什么？第二，感受：身体和情绪有什么反应？第三，解释：我脑中自动给了它什么意义？第四，防御：我正在否认、投射、合理化、回避、过度分析，还是用玩笑带过？第五，需要：如果不攻击自己和别人，我真正想保护或表达什么？这五问能把混乱体验拆开，让用户既尊重感受，也不立刻被感受推着行动。', '["自我觉察", "心理防御", "事实解释分离", "情绪调节", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1019, now()),
(101020, '心饿与胃饿：突然、急迫、只想吃某一种，多半是在求安抚', '当饥饿像开关一样突然出现、只锁定某一种食物、伴随烦躁或委屈，并且越吃越停不下来时，可以先把它看作“心饿”信号；真正的身体饥饿通常会慢慢出现，选择更灵活，吃到满足会自然停下。下次冲动来时，先问：我现在是胃需要能量，还是情绪需要被看见？', '["情绪化进食", "身体觉察", "饥饿识别", "需求识别", "冲动管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1020, now()),
(101021, '渴望不是意志力失败：它可能是未被照顾的需求在报警', '想吃东西不必立刻解释成自控差。书中把食欲视为身体和情绪共同发出的信号：爱、休息、乐趣、安全感、认可或放松没有被满足时，食物会暂时承担安抚功能。与其责备自己，不如把渴望翻译成一句需求：“我真正想要的是……”', '["情绪化进食", "需求识别", "自我关怀", "心理教育", "食欲信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1021, now()),
(101022, '四种底层情绪：害怕、愤怒、紧张、羞愧常躲在暴食背后', '情绪化进食背后常有四类感受：害怕失控或被抛下，愤怒于被忽视或被利用，紧张到无法放松，羞愧地怀疑自己不够好。App 可以引导用户在冲动前勾选最接近的一项，再写下触发事件。只要情绪被命名，食物的“必须立刻吃”感往往会松动。', '["情绪化进食", "情绪命名", "需求识别", "冲动管理", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1022, now()),
(101023, '15分钟暂停：让冲动先经过一个温柔的缓冲区', '强烈想吃时，先给自己 15 分钟：离开厨房或外卖页面，喝水或刷牙，让身体脱离食物线索；然后问自己是否害怕、愤怒、紧张或羞愧。最后用一句自我接纳语安抚自己：“我可以先照顾感受，再决定要不要吃。”这不是禁止进食，而是把选择权拿回来。', '["冲动管理", "替代安抚", "情绪化进食", "自我关怀", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1023, now()),
(101024, '从照顾别人回到照顾自己：用身体扫描找回饥饿和饱足', '很多习惯照顾他人的人，会对别人的需要很敏锐，却忽略鞋子勒脚、肩膀紧、胃已经饱等身体信号。可以做 60 秒身体扫描：脚踩地面的感觉、腿和背的支撑、胃部空或满、嘴巴是否只是想咀嚼。身体感被重新听见，情绪性饥饿和生理饥饿才更容易分开。', '["身体觉察", "情绪化进食", "饱足感", "自我照顾", "需求识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1024, now()),
(101025, '压力型进食：先给压力出口，而不是让牙齿替你扛', '想咬脆、硬、有嚼劲的东西时，可能不是身体缺某种食物，而是压力、愤怒或焦虑需要出口。可以把“我想嚼碎什么”改写为“我想对谁说不、想从哪件事里减负、想让谁帮忙”。散步、写下不满、分配家务、提出边界，比让嘴巴独自承担压力更能触及源头。', '["压力进食", "冲动管理", "需求识别", "边界表达", "替代安抚"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1025, now()),
(101026, '食物像拥抱时，真正缺的可能是连接', '面包、甜点或巧克力带来的安慰感，常与童年奖励、被照顾、浪漫和亲密记忆相连。App 端不必把某种食物固定解释成某个问题，而是可提醒用户：我现在是在找甜味，还是在找拥抱、理解、陪伴和被珍惜？如果是连接需求，可以发一条消息、约一次散步，或把感受告诉一个安全的人。', '["关系支持", "情绪化进食", "需求识别", "替代安抚", "自我关怀"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1026, now()),
(101027, '内在空缺：想把胃填满时，问问生活哪里太空', '当进食更像“把自己塞满”，尤其伴随孤独、害怕改变、关系不安全或目标感模糊时，食物可能在替你遮住内在空缺。可以温和地问：我最近逃避了哪个决定？哪段关系需要边界？我想要的生活方向是什么？不用立刻解决全部，只需要找出一个今天能做的小行动。', '["内在空缺", "需求识别", "身体觉察", "边界表达", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1027, now()),
(101028, '乐趣缺席也会变成食欲：休闲不是奖励，而是基本需要', '工作太多、玩得太少、生活缺少兴奋和自由，会让人把食物当成少数可获得的快乐。把乐趣排进日程，不是放纵，而是在照顾内在小孩和创造力。每天安排一个低成本愉悦动作：听歌、晒太阳、做手工、看云、和朋友玩十分钟，都能让需求不只靠食物发声。', '["乐趣需求", "替代安抚", "自我关怀", "情绪化进食", "需求识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1028, now()),
(101029, '替代安抚清单：给灵魂准备食物以外的补给', '当食物承担了安抚、奖励、陪伴和提神的全部功能，生活会变得很窄。可以建立“精神食粮”菜单：五分钟独处、写几句真实感受、整理一个安心角落、读书或兴趣小组、创意练习、减少消极信息、对自己说支持性语言。关键是让情绪有多种被照顾的通道。', '["替代安抚", "精神食粮", "自我关怀", "情绪调节", "需求识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1029, now()),
(101030, '高刺激饭局和节日：先设计环境，再考验意志力', '自助餐、聚会和节假日会同时触发多样选择、“花钱要吃够”、童年家庭角色和亲戚压力。比起临场硬扛，更适合提前设计：先浏览全场再选择，限定最想吃的几样，慢下来觉察饱足；被家人催促时，用“我已经很饱了”表达边界；情绪被触发时先离开现场深呼吸或写几句。', '["环境设计", "冲动管理", "身体觉察", "边界表达", "节日压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1030, now()),
(101031, '非此即彼的饮食念头：从“反正破戒了”回到下一口选择', '许多暴食来自“要么完全不吃，要么一次吃完”的黑白思维。吃了一口并不代表今天已经失败，也不需要用最后一次、明天再开始来推动自己继续吃。更温和的练习是：停在下一口之前，问“我现在还想吃吗？身体舒服吗？如果继续，是为了味道还是为了情绪？”', '["冲动管理", "黑白思维", "身体觉察", "自我关怀", "情绪化进食"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1031, now()),
(101032, '情感勒索识别：先看长期模式，不急着贴人格标签', '情感勒索不是一次情绪化争吵，也不是用某个诊断词给对方定性。更适合观察的是长期、跨场景、反复出现的互动模式：对方的需求总被放在最前面，规则只要求别人遵守，出了问题很少承担影响，总要求你立刻回应，一被拒绝就用愤怒、冷脸、哭诉、羞辱或内疚感把你拉回去。App 端回答时可引导用户记录具体事实、频率和后果，而不是急着判断“他是什么人格”。关键问题是：这段关系是否持续消耗你的时间、金钱、情绪和自尊？你是否越来越不敢拒绝、求证或和别人讨论？把注意力放回可观察行为和你的选择，才是安全的第一步。', '["情感勒索", "软暴力", "关系识别", "非诊断", "自我保护", "关系风险"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1032, now()),
(101033, '被“吸干”的信号：关系让你长期丢失时间、钱和情绪余量', '有些软暴力并不表现为明显攻击，而是让你在关系里慢慢失去余量。常见信号包括：一开始被魅力、承诺或脆弱故事吸引，后来总在替对方收拾烂摊子；每次见面或通话后都疲惫、内疚、焦虑；你花了更多钱、时间和注意力，却很少得到稳定回报；你的生活变窄，睡眠、工作、朋友和兴趣都被关系挤占。识别“被吸干”时，不必争论对方是否故意，也不必证明谁更可怜。先看结果：这段关系让你更有力量，还是让你长期处在耗竭和自我怀疑里？如果答案偏向耗竭，就需要降低投入、恢复支持系统，并重新设置边界。', '["能量耗竭", "软暴力", "情感勒索", "关系内耗", "自我照顾", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1033, now()),
(101034, '高压请求先按暂停键：越着急越不要立刻答应', '情感勒索常出现在“你现在就得答应我”的高压时刻：临时借钱、替班、照看孩子、加班、帮忙处理烂摊子、证明爱或忠诚。越是伴随哭诉、愤怒、催促和“只有你能帮我”，越需要先暂停。可以练习一句固定话术：“我需要想一下，十分钟后回复你。”普通人通常能接受你思考；如果对方持续逼你当场决定，这本身就是风险信号。暂停不是冷漠，而是让大脑从情绪裹挟中回到判断。回复前先问清楚：具体要我做什么？做到什么时候？代价是什么？如果我拒绝会发生什么？你越能慢下来，越不容易在内疚和恐惧中签下模糊的关系“空白支票”。', '["拒绝练习", "情感勒索", "边界", "决策暂停", "自我保护", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1034, now()),
(101035, '把模糊帮助变成具体条款：谁在何时做什么', '很多关系内耗从一句模糊的“帮我一下”开始。健康帮助需要把范围说清楚：谁负责、做什么、什么时候开始和结束、需要多少成本、如果超出范围怎么办。面对反复越界的人，口头默契往往不够，家务、借钱、共同育儿、工作协作都可以写成简短清单或消息确认。这样做不是把关系变得冷冰冰，而是减少误解和事后扯皮。App 端可引导用户把“我总是被利用”改写成具体协议：“我今天只能帮到晚上八点；超过时间你需要另找人”“我不直接转钱，只能帮你付这张账单”。越具体，越能保护善意不被消耗。', '["关系边界", "具体请求", "书面约定", "软暴力", "自我保护", "职场沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1035, now()),
(101036, '观其行而非听其言：承诺要用事实和时间验证', '在消耗性关系中，承诺、解释和眼泪很容易让人重新燃起希望。但真正可靠的不是“他说得多真诚”，而是他是否长期做出可验证的改变：是否尊重你的拒绝，是否按约定行动，是否愿意接受外部帮助，是否在没有立刻得到满足时仍能保持耐心。不要把“每天发很多消息、送礼、痛哭道歉”自动理解为改变，它也可能只是想快速恢复控制。面对重要决定，可以给事实留时间：查看过去记录、询问可信第三方、观察几周或几个月的稳定行为。App 端可提示用户把承诺转为指标：具体行为、截止时间、复盘点和再次越界后的处理方式。', '["关系判断", "承诺验证", "情感勒索", "行为观察", "安全沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1036, now()),
(101037, '拒绝不是辩论题：说“不”后停止解释循环', '很多人不会拒绝，是因为一说“不”就开始解释、道歉、证明自己不是坏人。可在情感勒索模式里，解释常被当成继续谈判的入口：对方追问“为什么”，挑出你的每个理由反驳，直到你为了安静而妥协。拒绝可以简短、平静、重复：“我不能借这笔钱”“今晚我不继续聊了”“这个安排我不同意”。如果对方继续纠缠，可以说“我已经回答过了，答案不变”，然后结束对话或离开。拒绝时的内疚感不一定说明你错了，可能只是你正在打破旧模式。真正尊重你的人，可以不喜欢你的决定，但会承认你有拒绝权。', '["拒绝练习", "关系边界", "情感勒索", "讨好", "安全退出", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1037, now()),
(101038, '边界要配得上后果：只说自己真的会执行的底线', '边界不是吓唬对方，也不是让对方立刻变懂事，而是提前说明“如果发生什么，我会怎么保护自己”。有效边界必须具体、可执行，并且你真的做得到。比如“六点半还没到，我就先走”“如果你继续骂人，我会结束通话”“如果再次借钱不还，我之后不再借”。不要用自己并不准备执行的分手、离职、断联来威胁，因为空威胁会让对方更会试探你的底线。也不要替对方阻止自然后果，否则关系会学到“只要纠缠够久，就有人收拾残局”。温和而一致的后果，比反复说教更能保护你。', '["关系边界", "底线", "自然后果", "情感勒索", "自我保护", "拒绝练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1038, now()),
(101039, '不再扮演被耗干的角色：支持别人不等于替他生活', '有些人会用脆弱、混乱、戏剧化痛苦或“只有你能懂我”把你推到救援者位置。你可以关心一个人，但不必成为他的唯一观众、免费治疗师、情绪垃圾桶或生活管理员。面对反复危机，先把隐性期待变成清楚请求：“你希望我现在具体做什么？”再检查这件事是否在你的能力和边界内。能做的就限定范围，不能做的就把对方导向更合适的资源，如专业咨询、家人、同事、法律或医疗支持。真正的支持不是替对方承担所有后果，而是在不牺牲自己的前提下，帮助关系回到责任和现实。', '["支持系统", "关系边界", "能量耗竭", "软暴力", "自我照顾", "求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1039, now()),
(101040, '安全沟通先做雷区地图：一次只谈一个目标', '如果某些话题一谈就爆炸，临场硬讲道理通常会让局面更糟。可以先做“雷区地图”：哪些话题、时间、地点和语气最容易引发攻击、冷战或转移焦点？沟通前只选一个目标，并把目标写成你希望发生的具体行动，而不是“你别再这样”。例如把“你别总逃避家务”改成“我们今晚十点前确认本周谁负责哪三件事”。选择相对安全的时间和地点，避免在开车、睡前、对方赶时间或你极度疲惫时谈。若对方开始辱骂、盘问或转移到人格攻击，先暂停，约定稍后再谈。安全沟通的重点不是赢辩论，而是保护目标、身体和关系边界。', '["安全沟通", "冲突降温", "关系边界", "软暴力", "沟通计划", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1040, now()),
(101041, '控制性盘问的边界：回答大问题，不进入无限细节', '在亲密关系里，信任问题可以被认真讨论，但不应变成无休止盘问、查手机、核对行程、要求你用放弃自主权来证明爱。面对“你到底爱不爱我、有没有背叛我”这类大问题，可以诚实回答；但对于反复细节审讯，要设置边界：“我愿意谈我们的信任和安全感，但不接受查手机和逐分钟交代行程。”越试图用更多解释消除猜疑，越可能被拉进新的疑点。不要用谎言换短暂安宁，这会让盘问升级；也不要独自承受。若对方限制你离开、威胁、跟踪或让你害怕，优先联系可信的人和专业资源，必要时制定安全退出计划。', '["控制性关系", "安全沟通", "关系边界", "安全退出", "情感勒索", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1041, now()),
(101042, '把关系带到阳光下：不要替软暴力保密', '软暴力常在保密和孤立中变强。对方可能说“这是我们之间的事”“别人不会懂”“你告诉别人就是背叛”，也可能让你因羞耻而不敢开口。但越是让你害怕讨论的关系问题，越需要带到可信的人面前。可以选择一两位稳重的朋友、家人、咨询师、医生、律师、上级或同事求证事实和方案。求助不是让别人替你做决定，而是帮你从单一叙事里出来，重新看见选择。App 端可鼓励用户建立支持名单：我害怕时先联系谁？谁能陪我复盘？谁能提供法律、医疗、财务或住宿资源？保持连接，是对抗情感勒索的重要力量。', '["支持系统", "求助", "软暴力", "情感勒索", "安全退出", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1042, now()),
(101043, '安全退出计划：离开高风险关系时先找人站在你身边', '当关系里出现威胁报复、限制行动、阻止你离开、持续跟踪、控制钱和证件、反复突破法律或协议边界时，重点不再是说服对方理解，而是安全退出。退出前尽量不要只靠私下谈判，可以先让可信朋友、家人、专业咨询师、律师或相关机构知道你的计划。准备好证件、钱、住处、交通、重要记录和紧急联系人；必要沟通尽量留痕，并通过第三方或正式渠道进行。关系结束后，不必用礼貌性回复维持牵连，因为对方可能把任何回应都解读为复合信号。如果有现实人身危险，优先联系当地紧急服务和身边可立即到场的人。', '["安全退出", "自我保护", "支持系统", "关系边界", "软暴力", "法律求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1043, now()),
(101044, '关系能否修复：看耐心、责任和持续行动，而不是瞬间悔意', '关系修复不靠一次痛哭、送礼或“我真的变了”的保证。更可靠的判断是：对方是否愿意承认具体影响，而不是只说自己可怜；是否能接受你暂时不原谅、不立刻恢复亲密；是否愿意给改变留时间，而不是用大量消息和承诺催你回头；是否能持续执行约定、承担后果、寻求专业帮助，并允许你和支持系统讨论。真正的修复会让你越来越安全、清醒、有选择；假的修复常让你更内疚、更保密、更急着安抚对方。App 端可以把修复观察期设置成可复盘的行为清单，而不是让用户凭一时心软决定去留。', '["关系修复", "情感勒索", "安全感", "承诺验证", "边界", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1044, now()),
(101045, '与完美控制型相处：协商成果，别被过程审判吞没', '有些关系冲突来自过度控制和完美标准：对方不断纠错、挑剔过程、把小失误上升到价值判断，让你越来越紧张。应对时，不必证明自己每一步都对，也不要用反批评开战。更有效的是把话题拉回成果和优先级：“你希望我最终交付什么？最重要的三条标准是什么？哪些步骤必须按你说的做，哪些我可以自行决定？”如果你感到受伤，可以直接说影响，而不是用冷战、故意犯错或背后求援来反击。区分“成果”与“过程”能保留合作空间，也能保护你不被无休止审判吞没。若对方连基本尊重都无法维持，再讨论距离和求助。', '["关系边界", "控制型关系", "安全沟通", "完美主义", "职场沟通", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1045, now()),
(101046, '大脑不是固定出厂设置：连接会被经验持续改写', '很多人以为性格、能力和习惯像出厂设置一样固定，但大脑更像一套会边使用边更新的系统。新的经验、练习、阅读、对话和情绪体验，都会让神经连接发生细微变化；经常一起被使用的通路会更顺手，不再使用的通路会慢慢变弱。这意味着“我就是这样的人”不一定是终点。改变通常不是靠一次顿悟，而是靠反复选择、持续练习和合适环境，让大脑把新的反应方式慢慢写进连接里。', '["大脑基础", "神经可塑性", "认知成长", "学习", "习惯改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1046, now()),
(101047, '神经连接像森林：学习是在长出新枝叶', '学习不是把资料塞进某个抽屉，而是在大脑里建立更容易通行的连接。书中把树突和突触比作森林里的枝叶：新的练习会让某些枝叶变多、连接变强，少用的连接则可能被修剪。对 App 用户来说，这个比喻很重要：刚开始学不会，不代表大脑没有能力，而是路线还没铺稳。把任务拆小、重复练习、及时反馈，大脑就更容易把陌生能力变成熟悉路径。', '["大脑基础", "神经连接", "学习", "神经可塑性", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1047, now()),
(101048, '注意力是有限资源：少切换，才更容易深度学习', '注意力不是无限电量。我们以为自己能同时处理很多事，实际上大脑在任务之间切换时会付出代价，手机提示、社交信息和多任务会不断打断正在形成的理解。真正的学习需要一段相对完整的专注时间，也需要休息来恢复。可以把学习或工作切成小段：先关掉主要干扰，专注二三十分钟，再短暂休息。训练注意力不是逼自己永远不分心，而是一次次把焦点带回当下。', '["注意力", "深度学习", "大脑基础", "自我管理", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1048, now()),
(101049, '学习靠重复和反馈：越使用的通路越容易被调用', '大脑会优先保留经常被使用的路线。背一首诗、学一门语言、练一项运动，真正起作用的不只是“用力”，而是带着注意力的重复、逐步增加难度，以及让大脑知道哪里做对了、哪里需要调整。临时突击也许能应付一次考试，却很难形成长期能力。更可靠的方法是每天小步练习，把新知识和已有经验连接起来，让大脑有足够次数去加固这条路。', '["学习", "记忆", "神经可塑性", "注意力", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1049, now()),
(101050, '情绪会带动身体：心跳、呼吸和肌肉反应都在传递信息', '情绪不是只发生在脑海里的念头，它会同步改变身体。恐惧来临时，心跳、呼吸、肌肉和激素都会快速准备行动；亲密、愉悦和安全感也会通过身体被感受到。理解这一点后，情绪调节就不必只靠讲道理。先觉察身体哪里紧、呼吸是否变浅、心跳是否加快，再通过放慢呼吸、放松肩颈、离开刺激源或联系安全的人，让身体把“现在更安全”的信息传回大脑。', '["情绪身体", "情绪脑", "身体觉察", "压力调节", "大脑基础"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1050, now()),
(101051, '恐惧是快速保护系统：先安住身体，再辨认真正危险', '恐惧的任务本来是保护生命，所以它启动得很快，甚至会早于理性判断。看到像蛇的树枝、听到突然声响，身体可能先僵住、心跳加快，然后大脑才慢慢确认到底有没有危险。问题不在于有恐惧，而在于旧经验有时会把普通情境误判成威胁。遇到强烈害怕时，可以先让身体停稳、呼吸放慢，再问自己：这里真实的危险是什么？有没有其他解释？这样是在训练大脑区分警报和事实。', '["情绪脑", "恐惧", "情绪调节", "安全感", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1051, now()),
(101052, '习惯是一条循环路线：信号、行动和奖励都能重新设计', '习惯的力量来自大脑的省力机制：某个信号出现，大脑自动启动熟悉行动，并期待奖励。比如压力后刷手机、饭后想吃甜食、情绪低落时冲动消费。改变习惯不是单纯责备自己，而是看清循环：触发信号是什么？我真正想要的奖励是放松、连接、安慰，还是成就感？保留同一个信号，换一个更健康的行动，并给自己一个小奖励，新的循环就有机会逐渐替代旧路线。', '["习惯形成", "奖励系统", "行为改变", "神经可塑性", "自我管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1052, now()),
(101053, '长期压力会消耗学习力：恢复安全感是成长前提', '短暂压力能让人集中、行动和应对挑战，但长期处在紧绷、担忧或创伤后的警戒中，大脑会把更多资源用于防御，记忆、学习和情绪稳定都会受影响。很多时候，一个人“学不进去”或“控制不住情绪”，并不是意志太差，而是神经系统长期没有安全感。成长练习需要先降低过载：规律睡眠、运动、呼吸、稳定关系、减少持续刺激，让身体从警报状态回到可学习状态。', '["长期压力", "情绪身体", "学习", "安全感", "神经系统", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1053, now()),
(101054, '终身学习是大脑保养：年龄不是停止改变的理由', '大脑会随着年龄变化，但年龄不是学习的截止日期。持续学习新知识、新语言、新技能，会让大脑不断建立和维护连接，也能让人保持好奇、灵活和参与感。终身学习不等于一直考试，而是自由选择让自己变丰富的事：读书、学乐器、练外语、做手工、理解新领域。越常使用学习能力，大脑越容易进入学习状态；开始得晚也不等于没有价值，每一次新练习都在给大脑做保养。', '["终身学习", "神经可塑性", "认知成长", "大脑保养", "学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1054, now()),
(101055, '影响力不是压过别人，而是改善一个人的处境', '在日常关系里，影响力可以理解为“让别人的处境发生改变”的能力。它不一定来自职位、财富或嗓门，而可能来自一个好问题、一句鼓励、一次引荐、一次资源分享。使用这条内容时，可以提醒用户：先问“我的行动会让谁更有力量、更清楚、更安全”，再谈表达、说服或带领。真正稳定的影响力，通常来自持续服务他人，而不是让别人害怕你。', '["影响力", "服务他人", "关系责任", "共同利益", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1055, now()),
(101056, '赋权给别人，也是保护自己的影响力', '如果你在团队、家庭或亲密关系中拥有更多经验、资源或话语权，最成熟的用法不是把所有决定抓在手里，而是让别人也更能行动：认可贡献，分享信息，提供机会，把责任交给对方并给到支持。一个人越能让身边的人变得有能力、有尊严、有选择，他的影响力越不容易变成控制。', '["赋权", "影响力", "团队关系", "家庭关系", "关系责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1056, now()),
(101057, '长期影响力来自持续增加共同利益', '很多关系里的“谁更有分量”，不是靠抢来的，而是别人根据长期体验交给你的：你是否让事情变好，是否减少伤害，是否照顾到多数人的真实需要。对用户来说，这可以转成一个自检：我的表达是在增加信任、合作和安全感，还是只是在赢面子、保位置、压下异议？越能为共同利益稳定负责，越容易得到真正的尊重。', '["共同利益", "影响力", "信任", "团队协作", "关系责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1057, now()),
(101058, '地位是别人给的尊重，不是自动拥有的特权', '被看重、被听从、被依赖，会让人误以为自己天然更正确。但地位本质上是别人给你的尊重和信任，不是永久许可证。它需要用稳定的行动续约：守承诺、承认影响、接受反馈、在犯错后修复。尤其当你是父母、老师、领导、资深者或照顾者时，越被尊重，越要记得尊重不是服从，而是双方仍有尊严。', '["地位", "尊重", "权力边界", "反馈倾听", "关系责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1058, now()),
(101059, '拥有更多话语权时，最先变少的可能是共情', '权力感会悄悄改变注意力：人更容易关注自己的目标、感受和欲望，也更容易漏掉对方的表情、语气、沉默和压力信号。所以，当你发现自己频繁打断、急着给建议、听不进不同意见，或把对方的难受看成“矫情”时，可以先暂停。恢复共情的第一步不是让对方闭嘴，而是重新确认：我真的听懂他在经历什么了吗？', '["共情", "权力边界", "反馈倾听", "自我觉察", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1059, now()),
(101060, '权力感会放大冲动，重要决定先慢半拍', '人在觉得自己更有资格、更有位置时，更容易把“我想要”误当成“我应该得到”。这会体现在抢话、抢资源、随口承诺、越界亲近、消费或情绪爆发上。一个实用提醒是：越是在自己占优势、对方难拒绝的情境里，越要慢半拍，问三句：这会不会让对方更难说不？我是否在利用位置？明天回看，我愿意为这个决定负责吗？', '["冲动管理", "权力边界", "自我觉察", "责任边界", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1060, now()),
(101061, '给反馈之前，先检查语气是否在制造羞耻', '反馈可以帮助人成长，也可能变成位置优势下的刺伤。权力感会让人更直接、更尖刻，更容易把“我只是说事实”当成不顾对方尊严的理由。更负责任的反馈是具体、可承受、可修正的：说行为和影响，不评价整个人；留出对方解释和提问的空间；如果情绪太满，先约定稍后再谈。关系里的影响力，要能承担自己语言造成的影响。', '["反馈倾听", "沟通", "权力边界", "关系责任", "尊重"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1061, now()),
(101062, '越有影响力，越要主动邀请反对意见', '当别人依赖你的评价、资源或许可时，他们可能不会自然说真话。沉默不一定是同意，顺从也不一定是信任。更健康的做法是主动降低对方表达成本：提前说明不同意见不会被惩罚，先听完再回应，感谢提醒你盲点的人。把反对意见当作关系的保护栏，而不是权威受挑战，能避免影响力滑向自我封闭。', '["反馈倾听", "谦逊", "权力边界", "团队协作", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1062, now()),
(101063, '关系里的影响力，以让对方更有选择为准', '亲密关系、亲子关系和团队关系里，健康的影响力会让人更能表达、选择和行动，而不是更害怕、更顺从、更没主见。你可以用这个标准检查自己：我提出建议后，对方是否仍能说不？我提供帮助时，是否保留了对方的节奏？我表达失望时，是否仍尊重对方边界？让对方变小的爱和领导，最终都会削弱关系。', '["亲密关系", "家庭关系", "权力边界", "自主性", "关系责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1063, now()),
(101064, '看见无权信号：沉默、紧张和羞耻都是提醒', '当一个人在你面前变得过度紧张、只会道歉、突然沉默，或总说“都听你的”，这不一定代表沟通顺利，也可能是他感到没有选择。关系责任不是逼对方更快表态，而是先降低威胁：放慢语速，允许暂停，确认对方可以不同意，必要时把决定权还给对方。能看见无权信号，是避免滥用影响力的重要能力。', '["无权感", "关系安全", "权力边界", "共情", "反馈倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1064, now()),
(101065, '感激和认可，是最日常的赋权方式', '很多人以为影响力来自强势表达，其实日常的感谢、认可和赞赏也在改变关系。被真诚看见的人，更容易感到有尊严，也更愿意合作。可以提醒用户把感激说具体：谢谢你刚才做了什么，它给我或团队带来了什么影响。这样的表达不是讨好，而是在关系中确认彼此的价值，让连接和信任被看见。', '["感恩", "认可", "赋权", "关系责任", "团队协作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1065, now()),
(101066, '把问题当成邀约：让一个问题引出更多问题', '高质量提问不是审问对方，也不是逼出标准答案，而是发出一个“我愿意继续理解你”的邀约。亲子或伴侣讨论中，可以少问“你到底为什么这样”，多问“这件事对你意味着什么”“还有哪些可能”“如果换个角度会怎样”。一个好问题常常不会立刻结束争论，而是让双方愿意继续探索。App 可用这一原则，把用户的冲突表达转化为开放问题，帮助对话从定输赢走向共同理解。', '["哲学思维", "提问能力", "开放探究", "亲子沟通", "伴侣沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1066, now()),
(101067, '先给每个人发声时间，再进入判断和建议', '很多讨论失败，是因为一方还没有形成自己的想法，另一方已经开始评价、纠正或给建议。遇到家庭分歧、伴侣冲突或孩子不愿开口时，可以先留出短暂安静时间，让每个人想一想、写一句、或先和身边人说两分钟，再进入集体讨论。沉默不一定是拒绝，也可能是在整理。App 可提醒用户：先创造安全的发声空间，再处理观点差异。', '["倾听", "表达安全", "冲突降温", "亲子沟通", "思辨训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1067, now()),
(101068, '倾听不是等反驳：让别人的观点真正进入自己', '倾听不是安静等待轮到自己说话，而是允许对方的话影响自己的理解。练习时，可以先复述：“我听到你在意的是……我理解得对吗？”再补充自己的不同意见。这样做不是同意对方，而是承认对方的经验有被认真听见的价值。App 在生成沟通建议时，可先给倾听句，再给表达句，避免用户一开口就反驳、解释或教育对方。', '["倾听", "观点差异", "共情沟通", "伴侣沟通", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1068, now()),
(101069, '从“你怎么证明”改成“这个想法从哪里来”', '要求别人立刻证明自己，容易让对话变成辩护和防御。更适合思辨训练的问法是：“你为什么会这样想？”“这个判断来自哪些经历？”“如果沿着这个想法走下去，会带来什么结果？”这种追问不是放弃理由，而是把理由看成一条可以继续探索的线索。App 可在用户坚持某个结论时，引导其说明来源、证据、例外和可能后果。', '["理由充分", "提问能力", "思辨训练", "开放探究", "沟通澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1069, now()),
(101070, '用“是或不是”启动立场，再用追问展开复杂性', '有些大问题太抽象，直接问“你怎么看”会让人无从开始。可以先设计一个能回答“是/不是”的小问题，例如“孩子一定要听父母的吗”“伴侣之间应该毫无保留吗”，让双方先站位，再追问“为什么”“有没有例外”“什么情况下会改变看法”。封闭问题负责启动，开放追问负责深入。App 可把混乱议题改写成清晰立场题，再逐步展开。', '["提问能力", "思辨训练", "观点澄清", "亲子沟通", "伴侣讨论"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1070, now()),
(101071, '讨论概念前先定义，再用反例修正', '亲密关系和亲子沟通常被“尊重、自由、公平、负责”这类大词卡住。实用做法是先请双方各自定义：你说的尊重具体包括什么？再找反例：如果我不同意你但认真解释，算不算不尊重？如果定义无法覆盖真实情境，就一起修正。App 可用“定义—反例—修正”流程，让抽象争执变成可讨论的具体边界。', '["概念澄清", "提问能力", "价值澄清", "边界沟通", "思辨训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1071, now()),
(101072, '把他人的话当作需要解读的文本，而不是直接定罪', '我们很容易把一句话立刻解释成冷漠、攻击、敷衍或不爱，但他人的真实感受并不总能被准确读出。更稳妥的做法是先把解释降级为假设：“我听成了你不在乎我，但我想确认你真正的意思。”面对孩子、父母或伴侣时，先询问情境、感受和意图，再做判断。App 可帮助用户区分“对方说了什么”“我如何解释”“还需要确认什么”。', '["倾听", "误解修复", "沟通澄清", "亲密关系", "开放探究"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1072, now()),
(101073, '把价值冲突拆成权利、感受和规则三条线', '很多争执混在一起：有人谈规则，有人谈感受，有人谈权利，于是越说越乱。可以先分三条线：这件事是否侵犯了谁的权利？它让谁受到了什么伤害？它违反了哪些共同规则？比如孩子被欺负、伴侣隐私、家庭分工，都可以这样拆开。App 可用这一框架帮助用户看见：不同理由可能都重要，但需要先分清它们各自支持什么结论。', '["价值澄清", "道德判断", "亲子沟通", "伴侣沟通", "思辨训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1073, now()),
(101074, '用阶梯问题找到边界：从哪一步开始不可以', '当双方争论“这有没有问题”时，可以把行为拆成由轻到重的阶梯，再问：从哪一步开始你觉得不可以？为什么这一阶和上一阶不同？例如从提醒、催促、检查手机到控制行踪；从摘一片叶子到砍倒一片树林。阶梯问题能帮助人发现自己的真实边界和价值依据。App 可用于亲子规则、伴侣边界和公共议题讨论。', '["边界沟通", "价值澄清", "开放探究", "亲子沟通", "伴侣沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1074, now()),
(101075, '语言会塑造体验：先检查关键词和绝对词', '很多冲突不是事实本身造成的，而是被词语放大了。“你从来不关心我”“我就是失败者”“孩子太自私”会把复杂体验压成标签。思辨沟通可先检查关键词：这里的“关心”“失败”“自私”具体指什么？有没有更准确、更少伤害的说法？App 可引导用户把绝对词、标签词改写成具体事实、感受和请求，让对话更可修复。', '["语言觉察", "沟通澄清", "冲突降温", "提问能力", "思辨训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1075, now()),
(101076, '分清前提、推理和结论，别只争最后一句', '争论中最常见的卡点，是双方只盯着结论：“你不爱我”“孩子必须听话”“这样才公平”。可以把话拆成三层：我根据哪些事实或前提？这些前提可靠吗？它们真的能推出这个结论吗？如果前提弱或推理跳跃，就不必急着接受结论。App 可把用户的强烈判断整理成“前提—推理—结论”，再帮助寻找证据、反例和替代解释。', '["逻辑训练", "理由充分", "批判性思维", "沟通澄清", "思辨训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1076, now()),
(101077, '把课堂交给对方：让当事人也参与设计问题', '在亲子、伴侣或咨询式对话中，提问者不必永远掌控方向。可以邀请对方一起设计问题：“你觉得我们真正该讨论的问题是什么？”“如果只能问一个问题，哪个问题最重要？”“你想先谈事实、感受还是选择？”当事人参与提问，会更愿意承担回答。App 可在用户想说服别人时提醒：不要只抛问题给对方，也让对方拥有提问权。', '["开放探究", "提问能力", "自主性", "亲子沟通", "伴侣讨论"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1077, now()),
(101078, '关系忽远忽近时：把害怕被丢下和害怕被吞没分开看', '有些关系会在“很想靠近”和“突然推开”之间摆动：靠太近时担心失去自己，被冷落时又像被抛下。先不要急着给任何人下结论，可以把当下反应拆成两类需要：我需要被确认，也需要保有空间。沟通时尽量说具体请求，例如“今晚能不能回我一条消息让我安心”，而不是用试探、冷战或追问证明爱。稳定关系不是全天候黏在一起，而是在靠近和独处之间有可预期的约定。', '["情绪波动", "亲密关系", "抛弃恐惧", "关系边界", "稳定沟通", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1078, now()),
(101079, '从理想化到失望：给重要关系留下灰色地带', '当一个人前一刻被看成“唯一懂我的人”，后一刻又因为一次迟到、一句没接住的话变成“完全不在乎我”，关系就容易被推到极端。可以练习在情绪最强时暂停下结论：把对方这次行为、过去的稳定表现、自己的受伤感受分开写下来。一个人可以有让你失望的部分，也仍然有曾经可靠、关心你的部分。保留灰色地带，不是替对方开脱，而是给自己多一个更稳的回应空间。', '["黑白思维", "理想化贬低", "关系修复", "情绪调节", "事实解释分离", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1079, now()),
(101080, '强烈情绪来袭时：先过情绪浪，再谈关系结论', '关系中的强烈愤怒、绝望或恐慌，常常会让人把一瞬间的感受当成全部事实。此时最优先的不是追问“你到底爱不爱我”，而是先让情绪浪过去：离开刺激现场、放慢呼吸、喝水、给自己设定二十分钟暂停，再回来看发生了什么。可以把要说的话改成“我现在很激动，晚一点再谈，但我会回来”。先稳定，再讨论关系结论，能减少把短暂情绪变成长期伤害。', '["强烈情绪", "冲突降温", "情绪调节", "稳定沟通", "关系安全", "暂停"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1080, now()),
(101081, '害怕被抛下时：把确认需求说成可执行请求', '被忽视、未回复、临时改约，可能会触发“我是不是不重要”的强烈不安。相比反复试探、翻旧账或用分手威胁换关注，更可行的是把确认需求说清楚：我需要知道你什么时候方便回应；如果计划改变，请提前告诉我；今天我想要一个拥抱或一句确认。具体请求让对方知道怎么做，也让自己从无限猜测回到现实协商。对方能否回应，也会帮助你判断这段关系是否足够安全。', '["抛弃恐惧", "具体请求", "关系沟通", "安全感", "情绪波动", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1081, now()),
(101082, '支持不等于接管：用关心、理解和事实三句话沟通', '面对关系中的失控、威胁或崩溃感，单纯讲道理会显得冷，单纯安慰又可能变成替对方负责。可以尝试三句话：第一句表达支持，“我在乎你，也愿意一起面对”；第二句表达理解，“我能想象这件事让你很痛、很怕”；第三句回到事实和责任，“现在我们需要决定下一步，你打算怎么做，我能帮到哪一步”。这样的沟通既不抛下对方，也不把对方的人生接管过来。', '["SET沟通", "稳定沟通", "支持系统", "关系边界", "现实检验", "危机沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1082, now()),
(101083, '有温度的边界：在关心和后果之间保持一致', '边界不是惩罚，也不是冷漠，而是提前说明自己能做什么、不能做什么，以及超过底线后会怎样行动。比如“我愿意听你说二十分钟，但辱骂开始时我会先挂电话，晚点再谈”。如果边界说了却每次都被内疚感推翻，关系会继续混乱；如果只有后果没有关心，又容易变成攻击。稳定的边界要温和、具体、可执行，并且尽量每次一致。', '["关系边界", "温和坚定", "一致性", "稳定沟通", "自我保护", "支持沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1083, now()),
(101084, '出现自伤或轻生信号时：认真对待并连接现实帮助', '当一个人提到想伤害自己、活不下去，或已经有具体计划时，不要把它当成“只是博关注”，也不要独自承担全部责任。可以先表达关心和陪伴，同时直接连接现实帮助：联系当地急救、危机热线、精神科急诊、可信赖家人或专业人员；移开明显危险物；不要承诺替对方保密。认真对待风险，不等于被威胁操控，而是在危险时把问题交给更合适的支持系统。', '["危机求助", "自伤风险", "支持系统", "现实帮助", "安全计划", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1084, now()),
(101085, '照顾者也要看见自己的内疚、害怕和愤怒', '陪伴一个情绪起伏很大的人时，照顾者很容易在内疚、害怕和愤怒之间摇摆：怕自己不够好，怕对方出事，也怕被不断消耗。先承认这些感受是关系压力下的正常反应，再决定行动。你可以关心对方，但不需要用牺牲睡眠、工作、金钱或安全来证明爱。找朋友、家人、咨询师或支持小组做外部支点，能帮助你更稳定地陪伴，也更清楚地守住边界。', '["照顾者支持", "支持系统", "关系边界", "内疚", "情绪觉察", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1085, now()),
(101086, '反复冲突像旧剧本：用记录看见触发点和循环', '有些关系冲突看似突然，其实常在相似情境中重复：一段平静后开始不安，一次拒绝后升级争吵，一句批评后转向自责或攻击。可以用简单记录捕捉循环：触发事件是什么，我脑中出现了什么解释，身体有什么反应，我做了什么，对方怎么回应，结果如何。记录不是为了定罪谁，而是看见“下一次最早能在哪一步暂停”。能被看见的模式，才有机会被调整。', '["关系模式", "触发点", "情绪记录", "冲突循环", "自我觉察", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1086, now()),
(101087, '亲密不是融合：稳定关系需要各自站得住', '越亲密的关系，越需要分清“我负责我的感受和选择，你负责你的感受和选择”。把对方当成唯一救生圈，短期会带来安全感，长期却容易让两个人都窒息；完全推开对方，又会让孤独和不信任加重。更稳定的亲密，是能说“我需要你”，也能说“这部分我要自己处理”；能彼此支持，也允许各自有朋友、工作、兴趣和独处时间。', '["亲密关系", "关系边界", "自主性", "稳定关系", "共生", "自我负责"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1087, now()),
(101088, '把“他们都一样”拆回具体的人和具体行为', '群体冲突最危险的时刻，常常从一句“他们都一样”开始。它会把很多不同的人压缩成一个标签，让真实的行为、处境和选择都消失。降级练习是把判断拆成三层：我看到的具体行为是什么？这是否真的代表每一个成员？对方有没有与这个标签不一致的时刻？回到具体的人和具体行为，不等于放弃边界，而是让沟通有可以修复和协商的入口。', '["去人化", "群体标签", "冲突降级", "社会心理", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1088, now()),
(101089, '仇恨会把一次伤害变成“这个人本质坏”', '愤怒通常指向一件具体伤害，仇恨却容易把对方整个人、甚至整个群体，看成本质上不可改变的坏。日常争执里，如果你发现自己在说“他就是那种人”“他们永远不会变”，可以先暂停，把句子改成：这件事造成了什么影响？我需要什么修复？我会设置什么边界？这样做能保留对伤害的严肃态度，也避免让关系从解决问题滑向人格审判。', '["仇恨语言", "本质化", "情绪觉察", "冲突降温", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1089, now()),
(101090, '恐惧升高时，先核对威胁而不是急着站队', '恐惧本来是保护信号，但群体恐惧一旦被不断放大，就会让人把传闻当事实、把防御当正义。面对让你立刻愤怒或害怕的信息，先做四个核对：信息从哪里来？威胁是眼前的还是想象中的？有没有相反证据？谁会从我的恐慌和转发中受益？核对不是否认危险，而是把“我被吓到了”变成“我正在判断怎样更安全”。', '["恐惧调节", "群体冲突", "信息核对", "冲突降级", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1090, now()),
(101091, '报复循环里，公道感需要边界和停止点', '受伤之后想讨回公道很自然，但如果公道感没有边界，就会变成你来我往的报复循环。可以把问题写成两栏：第一栏是必须停止或修复的具体伤害，第二栏是我不会做的越界回应。再问自己：我的目标是保护、修复和设限，还是让对方也痛苦？当情绪过高时，先暂停、找第三方或约定稍后再谈，比立刻反击更能保护长期关系。', '["报复循环", "冲突降级", "边界", "关系修复", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1091, now()),
(101092, '去人化词汇一出现，先把语言降级', '当谈话开始把某些人说成污物、害虫、疾病或“不是正常人”，共情就会被迅速切断。更安全的表达是把语言降级：把“他们很脏”改成“我不接受这个行为”；把“那类人没救”改成“我担心这种做法带来的影响”；把“对方群体”改成“其中一些人、一些选择、一些处境”。可以拒绝伤害性行为，但不必抹掉对方作为人的复杂性。', '["去人化", "仇恨语言", "嫌恶", "非暴力沟通", "冲突预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1092, now()),
(101093, '相似的人更容易夸大差异：别把小边界变成生死线', '很多冲突发生在相似的人之间：同一个家庭、团队、社群或行业里，越接近，越容易把一点差异看成身份威胁。降级时可以先列出共同部分：我们共同在乎什么？共同承担什么后果？再区分差异属于偏好、习惯、规则、价值还是安全底线。只有真正的安全底线需要强边界，其他差异往往可以通过规则、轮换、补偿和协商来处理。', '["微小差异", "身份认同", "群体冲突", "冲突降级", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1093, now()),
(101094, '群体压力越强，越要保留个人责任', '人在团队、社群或组织里，很容易因为“大家都这样”“上面要求”“不做就不合群”而放下自己的判断。遇到可能伤人的集体行动，可以先问三句：如果没人看着我，我仍然认可吗？这个行动会让谁承受不可逆的伤害或羞辱？有没有更小、更尊重人的替代做法？归属感不等于交出判断力，真正可靠的群体也应该允许成员保留良知和提问。', '["群体压力", "责任感", "服从权威", "自我觉察", "冲突预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1094, now()),
(101095, '冲突也需要规则：先约定不可越线的底线', '分歧不一定能避免，但可以被规则装进安全容器。重要谈话前，先约定几条底线：不羞辱人格，不扩大到整个群体，不传播未经核对的信息，情绪过高时暂停，暂停后必须回来继续谈。规则不是压住真实感受，而是让双方知道冲突不会失控。越是难谈的问题，越需要先保护人，再处理事。', '["冲突规则", "冲突降级", "关系沟通", "边界", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1095, now()),
(101096, '有效接触不是合照，而是对等合作', '只是把两个有矛盾的群体放在同一空间，并不一定减少敌意；如果地位不平等、目标互相竞争，接触反而可能加深防御。更有效的接触要有四个条件：彼此能作为具体的人相识，地位尽量对等，有共同目标，需要合作完成，并且得到规则或权威支持。家庭、团队和社区都可以把“强行和好”改成“设计一个公平的小合作”。', '["跨群体接触", "宽容", "公民社会", "共同目标", "冲突降级"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1096, now()),
(101097, '历史伤口要被理解，不要变成给当下的人定罪的工具', '记住伤害很重要，但如果历史故事只剩“他们一直如此”“他们的后代都该负责”，痛苦就会变成新的敌意。更有修复力的做法，是把历史分成三层：发生过的事实、当时具体责任、今天的人能做的补偿和改变。这样既不否认伤口，也不把当下每个具体的人都固定成过去的罪人。和解不是遗忘，而是让记忆服务于减少伤害。', '["历史记忆", "群体冲突", "和解", "责任边界", "社会心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1097, now()),
(101098, '自由不是控制一切，而是在限制中选择下一步', '很多事并不由你决定：身体状态、环境条件、他人的反应、已经发生的过去，都像重力一样限定着行动空间。但这不等于你完全没有选择。更实际的可控感，来自把注意力收回到此刻仍然开放的部分：我接下来把注意力放在哪里，我要不要暂停，我用什么方式回应，我愿不愿意把一个念头落成行动。复盘时不要问“为什么我不能掌控全部”，而是问“在这些限制里，我真实能动用的一小步是什么”。这样的选择不夸大个人责任，也不把人变成环境的受害者，而是在边界内重新获得行动感。', '["行动选择", "可控感", "责任边界", "自我觉察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1098, now()),
(101099, '理由会影响你，但不必替你做决定', '一个选择背后常有很多理由：短期愿望、长期目标、关系压力、价值判断、身体疲惫。它们会影响你，却不等于已经替你完成决定。行动前可以先把理由摊开：我想满足什么？我害怕失去什么？哪个理由只是事后合理化，哪个理由真正值得我承担后果？当你承认“我是在这些理由影响下选择”，而不是“我只能这样”，责任感会更清晰：既不否认处境和动机的力量，也把最后的回应方式带回自己手里。', '["理由复盘", "行动选择", "责任感", "自我觉察", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1099, now()),
(101100, '责任不等于把所有后果都背到自己身上', '复盘一件事时，可以把责任拆小，而不是把结果全归为“都是我的错”。先分清：哪些是我主动做出的行动，哪些后果是我当时能够合理预见和阻止的，哪些来自他人选择、环境限制或已经不可改变的条件。真正有帮助的责任感，是把注意力放在自己确实参与和可以调整的部分，例如下一次如何表达、确认、拒绝、补救；而不是把不可控的结果也变成自我攻击。这样既不逃避行动后果，也保护人不被过度内疚吞没。', '["责任边界", "可控感", "行动复盘", "自我接纳", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1100, now()),
(101101, '在自动反应里找一个可重新评估的岔路口', '很多日常行为是习惯性的：听到消息就回、焦虑时就刷手机、走到熟悉路口就按旧路线行动。不是每个小动作都需要严肃审判，也没有必要时时重新选择，那会让人耗尽。但当你意识到某个习惯正在把自己带向不想要的方向，可以把它当作一个“岔路口”：我还要沿着旧意图走吗？有没有一个更贴近当下价值的小替代？选择权常常不是宏大的自由，而是在自动反应被看见时，多争取几秒重新评估。', '["行动选择", "习惯觉察", "可控感", "自我觉察", "理由复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1101, now()),
(101102, '即使答案很明显，也还能选择表达方式', '有些情境里，大方向其实已经清楚：不收不该收的钱，不做会伤人的事，不继续一段越界的互动。此时选择并没有消失，因为“怎么做”仍然重要。你可以愤怒地拒绝，也可以平静说明边界；可以立刻中止，也可以补充交代后续安排。复盘时不要只问“我有没有做正确的事”，也问“我用什么方式做，它是否符合我想成为的人”。当方向确定，表达方式、节奏和边界感仍是可练习的行动选择。', '["行动选择", "责任边界", "价值澄清", "沟通边界", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1102, now()),
(101103, '冲动越强，越要把选择缩小到可执行的一步', '强烈欲望、成瘾式渴望或高度紧张，会让人的选择范围变窄。此时空喊“我应该更有意志力”往往没有用，甚至会制造羞耻。更实际的做法，是承认当下自由度有限，然后寻找仍然可控制的一步：把手机放远一点，延迟五分钟回应，离开刺激现场，联系一个支持者，或只调整语气和速度。责任不是要求自己在最窄的空间里表现完美，而是提前设计环境、在冲动中保留微小刹车，并在事后复盘哪些条件让选择变窄。', '["冲动管理", "行动选择", "可控感", "责任边界", "自我支持", "复盘行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1103, now()),
(101104, '复盘时问“我当时想满足什么”', '人行动时不一定完全清楚自己的动机。表面理由可能很体面，真实驱动却可能是想被看见、想避开冲突、想证明自己、想减少内疚。温和复盘不是给自己定罪，而是把行动和理由重新对齐：我当时说自己为了什么？身体和情绪真正追着什么？这个理由是否值得我继续让它带路？当能分辨“我有这个理由”和“我选择按它行动”，你就更容易从后悔进入学习，而不是停在自责。', '["理由复盘", "行动复盘", "自我觉察", "责任感", "认知成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1104, now()),
(101105, '焦虑不是敌人：把它读作过度响起的社会警报', '《焦虑和抑郁的起源》的核心视角是：许多焦虑/低落体验原本像社会本能的警报，提醒人靠近群体、避免出丑、维持秩序、减少冲突或保存资源。到了现代，警报可能在飞机、会议、升学、亲密关系、工作表现等场景被触发，强度超过实际需要。App 端可把用户从“我太脆弱/我有问题”的自责里带出来：先承认这是一套在保护人的系统，再一起判断它此刻是否过响、是否需要用事实、小步行动和支持来校准。', '["焦虑教育", "社会本能", "情绪功能", "去污名化", "自我理解", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1105, now()),
(101106, '惊恐体验：身体在喊“回到安全处”', '惊恐体验常让人以为身体马上会失控：心跳快、呼吸急、想逃离、害怕被困或找不到出口。书中把它理解为古老的分离/迷路警报：身体在催促人回到家、群体或可信赖的人身边。App 回应时不要说“这没什么”，而要先帮助用户命名体验：这是强烈警报，不等于真实灾难已经发生。可引导用户看见三个问题：我此刻在哪里是安全的？身边有没有可联系的人？下一步能不能只做一个很小的稳定动作。', '["惊恐体验", "身体警报", "分离焦虑", "安全感", "情绪命名", "当下稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1106, now()),
(101107, '预期焦虑：害怕下一次发作会把生活越缩越小', '有些人最难受的不是一次惊恐，而是之后一直担心“万一又来怎么办”。这种预期焦虑会让人避开地铁、电梯、课堂、远行或聚会，短期变安全，长期却让生活半径缩小。App 可帮助用户把“我不能去”拆成“我预测会发生什么、概率多大、我能准备什么支持、最小一步是什么”。目标不是硬扛到崩溃，而是在可承受范围内收集新的安全经验，让大脑知道：不是所有不适都等于危险。', '["预期焦虑", "回避循环", "行为实验", "安全经验", "生活半径", "焦虑调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1107, now()),
(101108, '分离焦虑：先有安全基地，才有力量探索', '离家上学、换城市、出差、恋爱关系变化或重要依靠者离开，都可能激活分离警报。书中反复强调“家”和“群体”的安全功能：人感觉被接住时，才更容易探索外部世界。App 端可把独立理解为“带着安全感逐步外出”，而不是突然切断依赖。对用户来说，实用问题是：我可以和谁约定报平安？我能带上什么熟悉物或日程？今天的探索边界在哪里？这样能把分离焦虑从“不能离开”转为“有准备地离开”。', '["分离焦虑", "安全基地", "自主探索", "依恋安全", "过渡支持", "日常计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1108, now()),
(101109, '社交焦虑：害怕出丑背后的等级警报', '社交焦虑常表现为害怕被盯着、被评价、说错话、脸红、发抖、让老板或同学失望。书中把它看作一种“社会等级警报”：在原始群体里，低调、顺从、不冒犯权威能减少冲突。现代生活却要求演讲、面试、表达观点和争取机会，于是保护策略反而可能困住人。App 可先验证它的功能：你不是没用，而是在努力避免丢脸和被排斥；再邀请用户把社交目标拆成低风险步骤，而不是一次性变外向。', '["社交焦虑", "害怕评价", "羞耻感", "低风险练习", "人际安全", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1109, now()),
(101110, '社交敏感的另一面：倾听、读懂线索和建立连接', '书中也提醒，社交焦虑不只有阻碍。对他人表情、语气、眼神和反应敏感，可能让人更会倾听、更重视别人的感受，也更愿意修正自己的表达。App 端可以帮助用户把“我太敏感”改写成“我有很强的社会雷达，只是需要调低警报音量”。适合的练习不是否定敏感，而是区分线索和结论：我看见对方皱眉，这是线索；“他讨厌我”只是解释；我可以用提问、澄清或延后判断来验证。', '["社交敏感", "倾听能力", "事实解释分离", "沟通练习", "自我接纳", "关系调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1110, now()),
(101111, '强迫循环：从有用的秩序感到停不下来的检查', '书中把强迫相关冲动拆成清洁、整齐/检查、囤积和举止得当等方向。轻微时，它们帮助人保持卫生、做计划、储备资源、减少冲突；过量时，就变成“洗了还不够、查了还不放心、留着才安全、脑中坏念头必须抵消”。App 端可用功能性语言解释：这些冲动起初想保护你，但现在可能占用了太多时间和注意力。第一步不是责备自己，而是识别触发—焦虑—仪式—短暂安心—再次怀疑的循环。', '["强迫循环", "检查", "清洁", "囤积", "仪式行为", "功能性理解", "焦虑循环"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1111, now()),
(101112, '够好练习：让秩序服务生活，而不是接管生活', '强迫冲动常把人推向“再确认一次才安心”。但安心如果只来自反复确认，就会越来越短。App 可设计“够好练习”：先写下这件事真正要服务的生活目标，例如吃饭、出门、交作业、睡觉；再设置一次可接受标准，如检查门锁一次、整理桌面十分钟、保留真正有用的物品；完成后把注意力带回原目标。重点不是故意变脏乱或冒险，而是练习让清洁、秩序和谨慎回到合适比例。', '["够好原则", "强迫调节", "时间边界", "注意力回收", "生活功能", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1112, now()),
(101113, '被拒敏感：一点冷落为什么像被重重击中', '非典型低落的核心线索之一是被拒敏感：别人没打招呼、回复慢、语气淡，都可能被体验成“我被排除”。书中把它理解为群体生活中的和谐警报：过去被群体拒绝很危险，所以大脑会放大冷落信号。App 端可帮助用户同时做两件事：承认受伤是真实的，不嘲笑敏感；也把解释放慢，问问“还有哪些可能？我能否先照顾难过，再核对事实？”这样能减少因过度解读而退缩、讨好或突然断联。', '["被拒敏感", "低落", "关系误读", "事实核对", "情绪照顾", "非典型抑郁"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1113, now()),
(101114, '低落像冬眠：退回去休息，也要慢慢回到连接', '书中用“冬眠”类比某些低落状态：想睡、想吃、想躲开人、暂时不参加活动，像是在减少进一步受伤。这个比喻适合 App 做温和教育：退缩可能是自我保护，不等于懒；但如果一直退缩，连接、活动和意义感会越来越少。可引导用户做“轻量回归”：晒光、洗漱、吃一顿稳定的饭、给安全的人发一句话、完成一个五分钟任务。目标不是马上开心，而是让身体和关系重新收到一点点“我还在生活里”的信号。', '["低落调节", "冬眠隐喻", "行为激活", "小行动", "恢复节律", "关系连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1114, now()),
(101115, '无用感与绝望：重建“我仍能贡献一点”的证据', '书中讨论抑郁时，反复提到目标丧失、孤独、疾病、退休、亲密关系失去和“自己成了负担”的感受。对普通用户，App 不宜把低落解释成意志薄弱，而要帮助其与无用感拉开距离：此刻大脑在报告“我没有价值”，但这不是最终事实。可从很小的贡献感开始：照顾一盆植物、整理一小块空间、给家人发问候、分享一个经验、帮别人一个小忙。意义感常不是想出来的，而是在可完成的连接和贡献中慢慢回来。', '["抑郁心理教育", "无用感", "意义感", "贡献感", "孤独", "小行动", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1115, now()),
(101116, '求助不是失败：把痛苦交给支持系统一起承接', '书中多处提醒，强烈焦虑或低落容易被本人和旁人误解为外部压力、性格问题或“想太多”，也有人会用酒精等方式自我缓解，反而带来新问题。App 端应把求助正常化：当痛苦持续、影响学习工作关系，或出现绝望和伤害自己的念头时，应尽快联系可信任的人和专业资源。支持系统的作用不是替用户做诊断或替代治疗，而是在能量最低、警报最响时提供陪伴、结构、转介和现实帮助。', '["求助支持", "专业资源", "非诊断", "风险识别", "支持系统", "去污名化", "危机支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1116, now()),
(101117, '反本能冲刺：把害怕当挑战前，先校准代价', '书中描述一些人会把恐惧转化为表演、销售、创造或工作成就：越害怕越去做。这能带来成长，也可能让人长期紧绷、难以休息、关系变少。App 端可提供日常校准：今天我是为了价值前进，还是为了逃避羞耻、被拒或空虚而过度用力？行动后身体更开阔还是更耗竭？我需要挑战、休息、陪伴还是边界？这样既保留焦虑带来的行动能量，又不让它变成无止境的自我证明。', '["日常调节", "反本能行为", "自我校准", "休息", "边界", "焦虑动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1117, now()),
(101118, '用故事替代说教：孩子更容易接住间接表达', '当孩子陷在害怕、羞耻或不愿开口时，App 端可以把建议包装成短故事、童话式角色或动画式情境，而不是直接评价孩子。故事提供一个“也有某个角色经历相似处境”的安全距离，让孩子先认出感受，再慢慢把故事带回自己的生活。亲子场景中，适合用于睡前故事、情绪卡片、亲子共读后的温和提问，重点是陪伴和理解，而不是要求孩子立刻改变。', '["故事隐喻", "儿童情绪表达", "亲子沟通", "安全距离", "App内容"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1118, now()),
(101119, '回到孩子的眼睛：成人先连接自己的内在小孩', '家长在沟通前可以先暂停成人式解释、纠错和资料判断，试着用孩子的眼睛看见房间、玩具、声音、害怕与好奇。App 可设置“内在小孩暂停键”：我小时候遇到类似感觉时最需要什么？孩子现在最想被谁看见？这样让共情先于纠正，也让家长从自己的童年经验里找到温柔、有趣、陪伴和支持的资源。', '["内在小孩", "亲子支持", "共情", "父母视角转换", "陪伴"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1119, now()),
(101120, '怪物也想要礼物：把恐惧放进可亲近的想象', '对害怕黑暗、怪物、分离或噩梦的孩子，App 可以提供“怪物可能也只是没被理解的角色”的故事模板，邀请孩子画出它、给它取名字、想象一个友好礼物或一条安全边界。重点是先承认孩子的主观世界，再引导孩子为害怕找到新的关系；避免直接说“这不是真的”或“别怕”，因为被否定的恐惧往往更难表达。', '["安全想象", "恐惧安抚", "故事重构", "儿童情绪表达", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1120, now()),
(101121, '幻想和游戏是孩子的语言', '空盒子可以变成城堡，石头可以变成宝藏，纸片可以变成礼物。App 端可把情绪签到或亲子任务设计成象征游戏：今天哪个物品像你的心情？它想变成朋友、船、宝藏还是护盾？家长不急着纠正“这不是真的”，而是跟随孩子的想象问一句：它正在帮你做什么？这种方式让难讲的感受有了可玩、可画、可移动的表达出口。', '["幻想游戏", "象征表达", "儿童语言", "情绪表达", "亲子互动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1121, now()),
(101122, '从积极经验进入孩子的资源世界', '在谈问题之前，先收集孩子喜欢的卡通、动物、电影、玩伴、运动、音乐、气味、颜色和记忆。App 可做“资源采集卡”：最喜欢的角色、最安心的地点、最有力量的动作、最能让自己放松的一种声音。以愉快联想作为入口，能让孩子先看到自己已有的资源感，再把后续故事背景贴近他的真实世界。', '["资源感", "积极经验", "兴趣线索", "儿童支持", "故事素材"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1122, now()),
(101123, '读懂微小线索：先观察再回应', '很多孩子不会直接说“我害怕”“我不舒服”“我想靠近”。App 的亲子支持内容可训练家长做轻观察：孩子的眼神、声调、身体紧绷、呼吸、靠近或躲开、选择哪个玩具、讲故事时对哪个角色更有反应。家长据此调整语速、距离和故事素材，而不是连续追问原因；对表达能力还在发展中的孩子，微小线索本身就是情绪语言。', '["隐微线索", "亲子观察", "非语言表达", "情绪识别", "回应方式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1123, now()),
(101124, '用孩子的感官母语沟通', '同样是“安心”，有的孩子需要画面，有的需要声音，有的需要抱枕、动作或气味联想。App 可为同一个故事准备视觉版、声音版、动作版和味觉/气味联想版，让孩子选择“最像我的版本”。亲子沟通中，跟随孩子的感官偏好，比反复讲道理更容易建立连接，也能让孩子感觉自己的体验被准确接住。', '["感官偏好", "儿童沟通", "安全感", "个性化内容", "亲子支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1124, now()),
(101125, '安全距离的角色故事：把问题给主角而不是给孩子', '当孩子觉得“只有我这样”时，App 可以让相似处境发生在小鸭、小鱼、小树、彩虹公主或小英雄身上：角色遇到困难，发现帮助者和资源，跨过一个可承受的危机，最后被看见与庆祝。故事要准确触及感受但保持间接，不给孩子贴标签，不逼孩子承认“这说的就是我”，而是让他在角色身上看见一种可能。', '["角色故事", "安全距离", "羞耻缓冲", "资源发现", "故事结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1125, now()),
(101126, '生活隐喻：把故事落到每天的小行动', '听完故事后，不必立刻追问“你学到了什么”。App 可建议一个温和小行动：照顾一盆植物、整理一个小篮子、挑一首代表心情的歌、为今天的勇气画一枚小徽章。小行动像故事的锚，把内在资源感落到真实生活中，也让亲子之间多一个可共同完成、可轻松回顾的支持经验。', '["生活隐喻", "资源锚定", "亲子任务", "日常练习", "资源感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1126, now()),
(101127, '画出资源：让颜色和形状替孩子说话', 'App 可以提供“我喜欢的东西”“今天帮到我的力量”“我的安全颜色”“我心里的天气”等绘画提示。绘画不用于分析孩子，而是让孩子用形状、颜色、角色和场景表达语言难以表达的感受，也让家长看见可被支持的资源：音乐、运动、朋友、动物、彩虹、树、海浪或任何让孩子感觉更好的元素。', '["内在资源绘画", "艺术表达", "非语言沟通", "资源识别", "儿童情绪表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1127, now()),
(101128, '篮子隐喻：秘密、边界和自我保护', '孩子可以想象一个有盖的篮子，决定哪些心事、记忆、愿望或秘密要放进去，什么时候打开，什么时候合上。App 可把它做成亲子对话卡：今天篮子里需要保护什么？想拿出什么支持自己？这类隐喻的重点是让孩子体验“我可以选择、我可以掌控、我的里面是安全的”，尤其适合边界感和安全感主题。', '["安全想象", "边界感", "自我保护", "亲子对话", "故事游戏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1128, now()),
(101129, '光之碗：把痛苦看成遮光的石头', 'App 端可把“我不好”改写为“我的光被一些石头挡住了”。孩子可以选择代表担心、愤怒、自我怀疑或难过的小石头，再选择一种温和方式把它们暂时放到旁边，同时记住光本来就在。这个隐喻适合培养希望、资源感和复原力：孩子不是问题本身，孩子还有天赋、技能、好奇心和正在等待被看见的光。', '["光之碗", "资源感", "希望感", "复原力", "内在小孩"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1129, now()),
(101130, '身体语言观察：把动作当线索，不当读心证据', '非语言沟通适合被当作观察入口，而不是判定他人真实想法的工具。App 端可把手势、表情、姿势、动作和运动解释为“可能传递信息的视觉线索”：先看当时场景、关系、文化背景、重复模式和对方本人基线，再提出温和假设。一个动作可能让旁观者感觉不安、舒服或亲近，但真正可靠的做法是把这种感觉转化为好奇和澄清，而不是贴上操控、撒谎、喜欢或敌意的标签。学习身体语言的价值在于提高理解与宽容：知道别人可能正受压力、礼仪、角色、习惯或文化规则影响，便更容易选择询问、放慢节奏和尊重边界。', '["非语言沟通", "身体语言", "观察方法", "避免读心术", "情境理解", "同理心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1130, now()),
(101131, '姿势是被看见的动作：区分有意信号和无意线索', '一个动作只有被别人看见并被赋予信息时才成为姿势。挥手、点头、指示等常是有意发出的原生信号；打呵欠、用手托头、脚拍地、整理衣扣等本来可能只是身体需要、习惯或自我调节，却会作为从属姿势被旁观者读出疲惫、紧张、无聊或不耐烦。App 端不宜把单个动作直接解释为固定心理，而应提示用户：先问“如果这个人独处还会这样做吗”“这个动作是否有机械功能”“它是否持续或与其他线索同步出现”。这样的区分能帮助用户避免把普通生理动作误判为人际态度，也能在会议、约会、咨询、客服等场景中更敏感地调整沟通方式。', '["姿势信号", "从属姿势", "身体觉察", "场景判断", "沟通误解", "行为观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1131, now()),
(101132, '多义手势：同一动作不能跨文化硬翻译', '同一手势在不同地区可能从“好/精确”变为“零/钱/侮辱/性暗示”等完全不同含义；同一含义也可能有多套姿势表达。App 端可以把跨文化身体语言设计为“本地化词典+情境提醒”，而非全球通用手势表。对旅行、跨国团队、异文化约会等场景，应提醒用户：看到陌生手势先暂停解释，观察表情、语调、互动结果和当地人的反应；必要时用语言确认。越是高度约定俗成、越是简化的手势，越容易脱离原始动作来源而成为地方符号。理解这一点，能减少把对方误判为无礼、冷淡或挑衅的风险。', '["多义姿势", "跨文化沟通", "手势误解", "地方习俗", "文化差异", "谨慎解释"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1132, now()),
(101133, '点头、招手和指向：低风险表达优先于猜测', '指点、招呼、点头、摇头看似简单，但书中把它们列为地区差异明显的信号。食指指向、掌心朝上或朝下招手、拇指示意、点头确认、摆头否定，在不同国家可能有亲切、粗鲁、命令、催促或相反含义。App 端可以提示用户：在跨文化场景中，尽量使用更低风险的开放手掌、明确语言和确认式问题；不要把“没有点头”理解为不同意，也不要把“招手方式不同”理解为不尊重。尤其在服务、教育、医疗、商务和旅行场景，最稳妥的做法是用语言补足方向、请求和同意，并留意对方是否表现出困惑或后退。', '["指示信号", "是非信号", "招呼手势", "跨文化礼仪", "确认沟通", "低风险表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1133, now()),
(101134, '眼神不是诚实检测器：注视要和关系阶段一起看', '注视不是单纯的诚实检测器。两个人关系从陌生、害羞、亲近到冲突，目光接触的次数、时长和方向都会变化；地位差异、社交礼节、兴趣、焦虑、敌意、文化规范也会改变直视与避视。App 端解释眼神时应避免“躲眼=说谎”“直视=真诚”之类读心术，而应提示：看目光是否与面部表情、身体朝向、距离、谈话内容和关系阶段一致。适度目光可以表达倾听和连接；过强注视可能被感到压迫；过少注视也可能只是害羞、礼貌、文化习惯或思考。最佳建议是根据对方反馈动态调整，而不是追求固定注视比例。', '["注视行为", "眼神交流", "关系阶段", "地位差异", "避免测谎", "动态调整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1134, now()),
(101135, '姿势对应：同步能带来亲和感，但不是关系证明', '姿势对应指朋友或关系融洽的人常在坐姿、站姿、点头节奏、手部小动作上无意识同步。它能让双方感觉“我们在同一边”，也常被医生、咨询师、服务人员用来降低对方紧张感。但同步不是操控技巧，也不是关系证明：地位差异、群体立场、职业角色或紧张防御都会改变同步程度。App 端可把它用于建立舒适感的建议：先采用开放、放松、不夸张的姿势，温和跟随对方节奏，再用语言确认感受。若刻意模仿过度，反而会显得讽刺或侵犯。关系符号如同行、靠近、触碰、共同沉默，也应结合身份、场合和文化边界理解。', '["姿势对应", "亲和感", "关系符号", "同步行为", "咨询沟通", "边界感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1135, now()),
(101136, '个人空间和阻挡信号：后退、交叉双臂未必是拒绝', '人会把国家、家庭、座位、办公桌、海滩上的物品、公共长椅的一段距离，乃至身体周围的一圈空间当作领地。距离过近时，人会减少表情和动作、避免面对面、交叉双臂或借桌子、包、杯子形成阻挡；这些不一定是拒绝，而可能是自我保护和空间调节。App 端可提示用户：观察对方是否后退、身体转开、把物品放在中间或动作变少，再主动给出空间。跨文化沟通尤其要谨慎，不同地区对谈话距离的舒适范围不同：一方靠近可能是亲切，另一方却会感到被侵入；一方后退可能是保持礼貌，另一方却会感到被冷落。', '["个人空间", "领地行为", "阻挡信号", "社交距离", "跨文化理解", "边界尊重"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1136, now()),
(101137, '矛盾、短缺和过度信号：把不一致当提醒，不当审判', '矛盾信号、短缺信号和过度信号都说明：身体语言常呈现为一组强弱不一的线索，而不是一个动作给出答案。微笑同时握拳、笑得太快消失、目光接触过短、对小笑话反应过度，都可能来自礼貌、紧张、角色要求、文化表达强度、拍照或表演压力，而不应直接判定为撒谎。App 端可以采用“可信度阶梯”思路：呼吸、腿脚、整体姿态等较少被意识控制的线索可作为参考，但仍必须结合场景与语言。更安全的建议是：当信号不一致时，不要拆穿或审判，而是放慢互动，询问对方是否需要时间、空间或澄清。', '["矛盾信号", "短缺信号", "过度信号", "情绪线索", "避免测谎", "温和澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1137, now()),
(101138, '中介信号：先判断“这是什么场”，再解释动作', '中介信号是“说明其他信号性质的信号”：笑容能让打闹变成玩笑，注视方向能说明争吵是否针对你，制服或舞台能改变动作的社会意义，屏幕、表演和游戏规则会提醒旁观者不要按现实敌意来理解。App 端在解释身体语言前，应先识别这些元背景：这是游戏、玩笑、职业角色、仪式、表演、亲密互动还是公共冲突？同一个动作在不同框架下含义会完全改变。若忽略中介信号，用户容易把开玩笑当攻击、把角色动作当人格、把群体仪式当私人态度。先判断“这是什么场”的性质，再解释动作，才更接近负责任的观察。', '["中介信号", "元沟通", "玩笑识别", "角色场景", "表演框架", "情境优先"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1138, now()),
(101139, '性别化身体信号：作为社会线索，而非本质标签', '性别化身体信号容易被误用为刻板判断。书中既讨论了社会如何通过服饰、游戏、礼仪和角色期待塑造“男性化/女性化”的动作，也提醒许多动作来自群体学习、模仿、训练和时代风格，而非单纯天性。App 端如需处理性别相关身体语言，应把它放在文化、年龄、职业、服装、场合和个人习惯中理解：某人走路、坐姿、手势、音调或触碰方式，并不能证明其性格、能力、取向、意图或关系状态。更好的知识库表达是：性别符号多是可观察的社会线索，具有时代性和地方性；使用时应避免把“常见模式”说成“必然规律”，并允许个体差异。', '["性别符号", "避免刻板化", "社会学习", "个体差异", "文化角色", "身体语言边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1139, now()),
(101140, '儿童友谊是情感营养：不是社交装饰品', '儿童需要的不只是“有人一起玩”，而是在同伴那里获得陪伴、盟友感、反馈、被喜欢和被理解的经验。亲密朋友能帮助孩子穿过转学、家庭变化、青春期困惑和学校小团体压力，也能让孩子借由朋友的眼光重新认识自己。App 端回应孩子没有朋友、朋友变少、被小团体冷落等问题时，应先承认友谊对孩子是真实而重要的需要，再帮助用户区分“受欢迎”与“有可靠朋友”：前者是群体地位，后者才更能提供日常支持。避免用“这有什么大不了”“小孩忘得快”否定社交痛苦。', '["儿童友谊", "同伴关系", "亲密朋友", "社交支持", "自我价值", "儿童心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1140, now()),
(101141, '朋友数量没有魔法数字：先看质量、幸福感和自愿性', '孩子不一定需要很多朋友，也不一定必须有一个被公开命名的“最好的朋友”。有的孩子满足于一个亲密朋友，有的喜欢小圈子，有的需要一段独处时间恢复精力。App 端可以引导家长观察：孩子见到朋友时是否高兴，游戏中是否有互动，是否能考虑对方感受，冲突是否多半能自行恢复，孩子是否因现状长期痛苦或被孤立。若孩子自愿选择少量关系且状态稳定，不必把内向、慢热或社交面窄解释成问题；真正需要关注的是孩子想交朋友却不会、想进入群体却反复受挫。', '["朋友数量", "友谊质量", "社交风格", "内向孩子", "家长焦虑", "幸福感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1141, now()),
(101142, '亲子依附是进入同伴世界的底盘，但不是命运判决', '父母与孩子早期稳定、敏感、可回应的互动，会让孩子形成“我值得被爱、他人可以信任”的社交底盘。孩子在这种底盘上更容易享受陪伴、分享、等待、合作、读懂他人情绪和保持自控。App 端可把亲子支持讲成“给孩子造船和帆”，而不是替孩子挡掉所有风浪。也要避免宿命化：早期关系不够稳定的孩子并非注定社交失败，后来的朋友、老师、亲戚、咨询关系和安全群体都可能提供第二次关系经验。建议家长把重点放在持续提供可靠回应、可回归的安全港和对外探索的许可。', '["亲子支持", "依附关系", "安全感", "社交能力", "信任", "非宿命"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1142, now()),
(101143, '儿童社交要看发展阶段：先问年龄，再给建议', '儿童建立友谊的能力会随年龄改变。年幼孩子先需要熟悉、相近、能移动接近对方和能把游戏延续下去；幼儿常在分享、轮流、争夺成人注意上受挫；青春期友谊则更强调隐私、自我坦白、身份认同和与父母分离。App 端回答“孩子不会交朋友”“不分享”“总粘一个朋友”“青春期什么都跟朋友说”时，应先询问年龄、场景、孩子气质和发展任务，再给符合阶段的建议。不要把成人式理性、稳定和宽容直接套到孩子身上，也不要把尚未成熟的能力解释成品行差。', '["发展阶段", "游戏能力", "儿童社交", "年龄差异", "同伴互动", "青春期"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1143, now()),
(101144, '同伴压力的核心是归属需要：既有风险，也有正向影响', '同伴压力不只是别人强迫孩子做坏事，更常来自孩子内心想留在圈子里、想和大家一样、害怕被孤立的需求。它可以让孩子更努力、守规则、向好朋友学习，也可能让孩子为了归属而违背判断、参与嘲笑、冒险或排斥他人。App 端可帮助家长和孩子把压力拆开：我是想被接纳，还是相信群体判断更正确？我害怕失去谁？有没有一个不牺牲底线、又能保留关系的选择？回应时不要羞辱孩子“没主见”，而要承认归属压力是人类普遍经验，再训练底线、延迟决定和寻找支持者。', '["同伴压力", "归属感", "从众", "群体规则", "青少年", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1144, now()),
(101145, '小团体不是天生有害：痛点在接纳、排斥和身份标签', '小团体来自孩子对相似性、身份和归属的需要，午餐桌、穿着、共同兴趣和“我们这类人”的感觉都会让孩子获得安全感。问题在于，小团体也可能通过“我们/他们”来巩固边界，把某个孩子排除、惩罚或当作共同敌人。App 端不宜简单劝孩子“别理小团体”，因为对青春期孩子来说，被团体抛下可能像每天承受折磨。更有用的是：帮助孩子保留一两个可靠关系，发展团体之外的活动和身份来源，识别哪些规则可以配合、哪些已经越过羞辱和伤害的边界。', '["小团体", "归属感", "排斥", "身份认同", "午餐桌", "青春期社交"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1145, now()),
(101146, '排斥和孤立要从群体动力看，避免给单个孩子贴死标签', '被排斥的孩子可能安静退缩，也可能因焦虑、莽撞、愤怒或技能不足而让同伴害怕；被忽视的孩子可能不惹麻烦，却长期没人看见。群体一旦给孩子贴上“怪”“坏”“爱哭”等标签，同样行为会被更消极地解释，孩子很难靠自己翻盘。App 端应避免把问题简单归为“孩子太差劲”或“其他孩子都坏”，而是引导家长收集更完整的信息：孩子是否开心，是否有一个朋友，是否长期被抛下，老师观察到什么，孩子是否也在用不成熟方式保护自己。目标是理解系统并尽早支持，而不是定罪。', '["排斥", "孤立", "替罪羊", "群体动力", "去标签化", "学校社交"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1146, now()),
(101147, '嘲笑与欺凌要看权力、重复性和孩子是否能脱身', '孩子之间的嘲笑、打闹和语言攻击有时是笨拙的互动、地位试探或男孩之间的交流方式，但当它持续针对差异、让孩子恐惧羞耻、被旁观者默许、无法安全离开或反复损害自尊时，就不能轻描淡写。App 端可引导用户记录具体事实：发生了什么，是否重复，谁在场，孩子能否说停，旁观者如何反应，学校是否知情，孩子是否出现回避、失眠、持续低落或报复冲动。不要把欺凌简化成固定的“恶霸—受害者”二分，很多事件涉及群体授权、旁观者沉默和长期挑衅后的爆发。', '["欺凌", "嘲笑", "语言攻击", "权力关系", "旁观者", "校园安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1147, now()),
(101148, '朋友冲突常是关系、认同感和力量感三种需求在拉扯', '孩子之间的冲突并不总是友谊失败，而常是三种需要相互碰撞：想被某个朋友特别在乎，想在群体中被看见和认可，想拥有力量与控制感。争座位、抢排头、炫耀、传八卦、冷落朋友或加入更酷的小团体，都可能是在用不成熟的方式满足这些需要。App 端可以把“谁对谁错”升级为“当时谁在争取关系、认同或力量”：孩子想被谁选中，想证明什么，害怕失去什么。这样既不纵容伤害，也能帮助孩子学习自我管理、轮流、分享和在关系中表达需求。', '["朋友冲突", "关系需求", "认同感", "力量感", "情绪起伏", "社交学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1148, now()),
(101149, '修复友谊：孩子有和解能力，成人不要急着把一时伤害定格', '许多孩子在争吵、误会、嫉妒和短暂背叛之后，会通过玩笑、共同任务、拥抱、道歉、重新一起玩或第三方调解慢慢恢复关系。成人若把孩子昨天的痛苦固定成“那个孩子就是坏”“你一直是受害者”，反而可能阻断孩子自己的修复能力。App 端可建议家长先倾听和承认影响，再问孩子是否希望修复、需要怎样的支持、对方是否持续伤害。对可修复的误会，给孩子空间；对反复羞辱和孤立，则进入保护与学校协作流程。重点是同时看见伤害和关系韧性。', '["友谊修复", "和解", "误会", "道歉", "关系韧性", "亲子倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1149, now()),
(101150, '父母介入边界：做救生员，不做律师、经理或复仇者', '父母无法替孩子经营社交生活，也不能给孩子戴上情绪头盔。更合适的角色是放松而警觉的救生员：提供稳定支持、同理倾听、信任孩子的适应力，必要时迅速行动。App 端应提醒家长避免“痛苦追问”：反复追问谁又欺负你、替孩子长期记仇、把孩子短暂的愤怒升级成成人之间的敌意。孩子需要的是可依靠的肩膀和清醒判断，不是律师和保镖。若出现长期孤立、恶意欺凌或安全风险，父母要介入；若是普通波折，则先陪伴、观察、帮助孩子自己消化。', '["父母介入", "边界", "社交痛苦", "痛苦追问", "亲子支持", "家长焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1150, now()),
(101151, '支持友谊的幕后工作：机会、家中基地和成人联盟', '父母支持友谊往往不是直接教孩子“你该怎么交朋友”，而是在幕后创造条件：搬家后主动认识邻居家庭，为年幼孩子安排玩伴，愿意接送孩子见朋友，让孩子的朋友来家里时感到被欢迎，适度认识朋友和“敌人”的父母，给友谊提供安全的大本营。App 端可给出可执行建议：欢迎孩子朋友、具体表扬来访孩子、支持孩子去看朋友的比赛或演出、扩大跨年龄和跨文化接触。边界是不要越界讨好、监视或抢占孩子的关系。', '["友谊支持", "家庭环境", "玩伴机会", "成人联盟", "社交机会", "交友支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1151, now()),
(101152, '长期无友或被排斥时：从观察走向协作支持', '如果孩子真的没有朋友、总被集体抛下、长期痛苦，或经常以恶意方式欺负别人，家长不能只等孩子自己长大。App 端可提供一条非诊断化行动路线：先与老师沟通，列出观察到的事实，了解孩子在班级中的位置；再评估是否存在社交技能缺口，如冲动、读不懂暗示、过度索取、退缩或持续焦虑；必要时联系学校顾问、友谊小组、家庭治疗或儿童心理专业支持；同时维持亲戚、邻居、营地、社区等安全关系网，为孩子增加被接纳的机会。协作时避免指责老师或单方面责怪孩子。', '["长期孤立", "学校协作", "社交技能", "家庭治疗", "友谊小组", "早期干预"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1152, now()),
(101153, '受欢迎的孩子也需要道德引导：把影响力转成保护力', '孩子如果受欢迎、被接纳或在小团体中有影响力，家长仍有重要任务：帮助他看见自己的话语、排斥和玩笑会怎样影响地位较低的孩子。App 端可建议父母抓住具体场景，而不是空泛说“你要善良”：当孩子在车后座议论同学、游戏中排除别人、嘲笑某个孩子时，用问题带出同理心和公平感，也可以清楚表达家庭底线。受欢迎不是纵容刻薄的通行证；好的社交领导力是让群体更安全、更包容，而不是用魅力和地位维持恐惧。', '["受欢迎孩子", "道德领导力", "同理心", "排斥他人", "家庭教育", "群体影响力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1153, now()),
(101154, '儿童焦虑需要被陪着练习，而不是被催着勇敢', '孩子的焦虑不只表现为“害怕”，也可能变成发脾气、退缩、咬指甲、反复确认、肚子痛或拒绝尝试。父母首先要把它理解为孩子的安全系统过度警觉，而不是故意闹。有效支持不是催促“别怕”，而是在接纳感受的基础上，陪孩子做一点点可承受的练习，让身体和大脑重新获得“我能应对”的经验。', '["儿童焦虑", "亲子支持", "接纳", "小步练习", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1154, now()),
(101155, '把焦虑称为“警报”，能减少孩子的羞耻感', '可以和孩子一起建立“安全系统”的家庭语言：先察觉危险，再拉响警报，随后进行理性评估，最后解除警报。这样说能把问题从“你太胆小”转成“警报器有点敏感”。孩子更容易观察自己的身体和想法，也更愿意和父母合作寻找降警报的方法。语言越中性，孩子越少把焦虑等同于“我不好”。', '["儿童焦虑", "安全系统", "情绪命名", "心理教育", "羞耻感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1155, now()),
(101156, '先共情再开解，孩子才可能听见建议', '当孩子说出看似不合理的担心时，先不要急着证明“不会发生”。对孩子来说，害怕的感受是真实的。父母可以先复述和承认感受，例如“你现在真的很担心”，再询问他看见了什么、身体哪里不舒服、需要怎样的陪伴。被理解之后，孩子的大脑才更可能重新接入思考，听得进解释或解决办法。', '["共情", "接纳", "亲子沟通", "情绪命名", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1156, now()),
(101157, '父母要做镇定又共情的“第二只小鸡”', '容易焦虑的孩子会不断从身边成人身上寻找安全线索。父母若跟着惊慌，孩子的警报会更响；父母若只冷冰冰地说“没事”，孩子又会觉得没人理解。更合适的姿态是：语气稳定、身体放松，同时承认孩子正在害怕，并用拥抱、陪伴、轻声安抚等方式传递“我在这里，我们可以一起面对”。', '["父母稳定", "共情", "亲子支持", "安全感", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1157, now()),
(101158, '恐惧测量计让紧张变得可观察、可讨论', '和孩子一起设计一个1到10的“恐惧测量计”，让孩子自己命名刻度：几分是有点紧张，几分是快崩溃。重点不是父母纠正分数，而是让孩子练习觉察：现在是几？做完呼吸、拥抱、运动或游戏后降到几？当焦虑被画出来、说出来、打上分，它就不再只是铺天盖地的感受，而变成可以一起处理的信号。', '["恐惧测量计", "情绪命名", "自我觉察", "放松练习", "亲子工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1158, now()),
(101159, '轻推的关键是在临界点停留，而不是把孩子推过头', '面对害怕的事，孩子可能逃避、情绪失控、咬牙硬扛，或在还能承受的范围内直面感受。真正有帮助的“轻推”，是带孩子来到害怕和安全的交界处，停一停、抱一抱、笑一笑、退一步也可以，再向前一点。若孩子已失控，先安抚；若一直逃避，才轻轻推进；若正在面对，就帮他放松。', '["轻推", "临界点", "陪伴式暴露", "接纳与挑战", "小步练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1159, now()),
(101160, '陪伴式暴露要让孩子有“停”和“退”的权利', '练习靠近害怕对象时，孩子需要保有一定控制感。可以把目标拆成极小步骤：先看一眼、靠近一点、停下呼吸、退回安全处、再试一次。父母的角色不是强迫完成，而是陪孩子体验紧张升高又下降的过程。每一次“我害怕，但我能停住、能恢复、能再试一点”，都在为安全系统积累新经验。', '["陪伴式暴露", "小步练习", "自主性", "安全感", "亲子支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1160, now()),
(101161, '勇气不是不害怕，而是害怕时仍能做一点点', '对焦虑的孩子说“勇敢点”常会被听成“你太胆小”。更好的做法是在事后肯定具体努力：刚才你很怕，但还是走近了一步；你停下来呼吸，然后又试了一次。孩子需要知道勇气可以练习，不是天生性格。把注意力放在尝试、恢复和解决问题上，孩子会逐渐形成“我能应对”的自信。', '["勇气", "自信", "成长型思维", "小步练习", "正向反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1161, now()),
(101162, '欢迎所有情绪，不等于允许所有行为', '孩子可以生气、害怕、悲伤、嫉妒，也可以不喜欢某个变化；情绪本身没有对错。但情绪带来的冲动需要学习管理，比如想打人、想逃跑、想尖叫。父母可以说：“你很生气，生气时会想打人，但我不会让你打人；我们可以跺脚、捶枕头、画出来或抱一会儿。”接纳感受和设定边界可以同时发生。', '["情绪接纳", "行为边界", "情绪命名", "亲子支持", "自我调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1162, now()),
(101163, '不要和“万一”争辩，用好奇心拆解焦虑性思维', '焦虑性思维常以“万一……”的形式出现，越争辩越容易陷入循环。父母可以先承认“这个想法听起来很吓人”，再用好奇提问：除了最坏结果，还有哪些可能？这个念头想让你避开什么？现在眼前有什么证据？也可以把担心列成清单，让孩子自己给每条想法取名、质疑和改写。', '["焦虑性思维", "万一心理", "好奇心", "认知练习", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1163, now()),
(101164, '把焦虑外化，孩子更容易找回力量感', '当孩子说“我就是胆小”“我压力太大”时，可以把焦虑变成一个外部角色：紧张怪、悲观使者、警报器、捣乱间谍。孩子可以画出它、给它配音、当侦探研究它什么时候出现，也可以在游戏里命令它退后。外化不是否认感受，而是帮助孩子明白：焦虑是我正在经历的问题，不等于我这个人。', '["游戏力", "外化焦虑", "角色扮演", "自信", "儿童焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1164, now()),
(101165, '分离焦虑要先补联结，再练习短暂分离', '分离练习不是突然把孩子推开，而是让孩子反复体验“离开—重逢—仍然被爱”。睡前、入园、父母出门前，可以先补充专注陪伴，再用躲猫猫、你好再见、秘密任务、牵绳距离等游戏练习分离。若孩子已经进入依恋恐慌，先抱持和安抚，等平静后再处理规则或不当行为。', '["分离焦虑", "依恋", "联结", "自主性", "游戏力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1165, now()),
(101166, '社交焦虑的孩子需要预热时间和低压练习', '慢热或社交焦虑的孩子并不是不礼貌，也不一定是不想交朋友。他们常常需要先观察、靠近父母这个“安全大本营”，再尝试加入。父母可以提前预留预热时间，减少当众催促，用角色扮演练习问候、目光交流、加入游戏等小技能。每次轻推之后，都要用更多理解、拥抱和鼓励帮孩子恢复平衡。', '["社交焦虑", "慢热型孩子", "预热时间", "社交练习", "安全大本营"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1166, now()),
(101167, '焦虑的反义词不是完全不紧张，而是联结、信任和快乐', '帮助孩子的目标不是把紧张彻底消灭，而是让孩子在紧张出现时仍能生活、玩耍、学习、交朋友和承担合理风险。亲密联结让孩子有地方可回，信任让父母不必事事代劳，游戏和笑声让身体重新体验快乐。最终，孩子需要形成一种内在声音：我可能会害怕，但我有办法，也有人陪我。', '["重拾快乐", "联结", "信任", "游戏力", "自主性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1167, now()),
(101168, '自我概念不是固定标签：在角色、关系与比较中更新自我', '社会心理学把自我看成会被关系、角色、文化和比较持续塑造的系统。人会高估别人对自己的注意，也会把成功更多归因给自己、把失败外推。App 问答可引导用户把“我就是这样的人”改写为“我在这个情境里形成了这种反应”，区分自我图式、社会身份和可能的自我，减少自责或自大，用更可行动的目标更新自我叙事。', '["社会心理学", "自我概念", "社会比较", "自我服务偏见", "成长导向", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1168, now()),
(101169, '归因偏差：先还原情境，再评价人格', '基本归因错误提醒我们：观察别人时，人的行为最显眼，情境约束却常被忽略；解释自己时，我们又更容易看到压力、规则和选择受限。App 可把它转化为反应练习：遇到冲突、迟到、冷淡或失误，先列出三个可能的情境因素，再判断稳定特质。这样能减少贴标签和道德化批判，也能让自我反思更公平。', '["归因偏差", "基本归因错误", "情境因素", "反标签", "关系修复", "批判性思维"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1169, now()),
(101170, '认知失调：把内在不适当作价值校准信号', '认知失调并不只是“口是心非”，而是当行为、信念和自我形象不一致时产生的心理张力。人常通过改写理由来减轻不适，尤其在选择看似自愿、外部理由不足时。App 可鼓励用户在冲突后追问：我是在为行为找借口，还是在调整价值？更成长的做法是承认不一致，补偿受损关系，并把小承诺用于建立真实想要的习惯。', '["认知失调", "态度行为", "自我辩解", "价值澄清", "习惯养成", "反操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1170, now()),
(101171, '从众的两种来源：想被接纳，或想做对', '从众不必被简单评价为软弱，它可能来自规范影响：担心被拒绝、想获得接纳；也可能来自信息影响：情境模糊时借他人反应判断事实。App 可以帮助用户区分这两类压力：如果只是怕尴尬，可先写下个人底线；如果确实缺信息，就主动寻找多源证据。成长目标不是永远反从众，而是在归属与独立之间保留选择权。', '["从众", "规范影响", "信息影响", "群体压力", "边界感", "独立判断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1171, now()),
(101172, '社会影响的免疫力：慢下来，审视论据与线索', '说服既可能是教育，也可能滑向灌输。中心途径依赖论据质量，外周途径依赖吸引力、权威、好心情和重复等线索。App 可把“态度免疫”做成反操控提醒：先识别信息源、利益关系和情绪触发，再为自己的立场写出温和反驳。不是拒绝改变，而是让改变来自证据和反思，而非稀缺感、权威感或群体热度。', '["社会影响", "说服", "态度免疫", "中心途径", "外周线索", "反操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1172, now()),
(101173, '群体压力的风险：责任扩散、去个体化与极化', '群体能带来支持，也会稀释个人责任。匿名、规模大、情绪唤起和缺少个人评价时，人更可能去个体化；只和同温层讨论时，观点会被推向更极端。App 可建议用户在群聊、团队和社区中保留个人署名、明确责任、邀请反方证据，并在强情绪下延迟决策。反群体压力的关键不是孤立自己，而是让群体更透明、更可反思。', '["群体压力", "责任扩散", "去个体化", "群体极化", "团队决策", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1173, now()),
(101174, '防止群体思维：把异议设计成安全流程', '凝聚力强的群体未必决策更好。当领导暗示倾向、成员追求一致、异议被压制时，群体会高估自身正确性，合理化风险，屏蔽不愉快信息。App 可把它转化为团队问答模板：决策前指定“反对者”，列出最坏证据，允许匿名补充，复盘被忽略的信息。少数派如果稳定、清晰、非攻击地表达，能帮助群体看到替代方案。', '["群体思维", "少数派影响", "异议", "决策质量", "团队心理", "风险复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1174, now()),
(101175, '刻板印象去标签化：从类别回到具体的人', '刻板印象是为了简化世界而形成的概括，但一旦过度使用，就会把个体压扁成群体标签。人还会产生外群体同质效应：觉得“他们都差不多”，而对自己的群体看见更多差异。App 可引导用户用三个问题去标签化：我掌握的是群体均值还是此人的信息？我是否把突出特征当成全部？我还能看到哪些与标签不一致的具体证据？', '["刻板印象", "去标签化", "外群体同质", "个体化", "偏见", "反歧视"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1175, now()),
(101176, '刻板印象威胁：高标准要配合可信任的支持', '当人担心自己会被负面刻板印象评价时，注意力、工作记忆和表现都会受影响。降低这种威胁，不是降低期待或贴“弱者”标签，而是让任务与身份标签脱钩，同时传达可信的高标准和支持：我相信你能达到更高水平，所以给你具体反馈。App 可用于学习、职场和亲子场景，帮助用户把标签压力转为可操作的成长反馈。', '["刻板印象威胁", "高标准支持", "学习表现", "身份压力", "反馈", "成长型沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1176, now()),
(101177, '旁观者效应：把“有人会管”改成“我先确认”', '紧急情境中，人越多，个体越可能少注意、少判断为紧急、少承担责任。旁观者会观察彼此的镇定，从而误以为事情不严重。App 可给用户一个助人脚本：先确认安全，再明确点名求助，如“你拨电话、你找工作人员、我留下观察”。对求助者，也可建议直接指定对象与需求，降低责任扩散，让善意更容易变成行动。', '["利他", "旁观者效应", "责任扩散", "助人", "紧急情境", "社会责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1177, now()),
(101178, '助人行为的来源：共情、规范与可承受的行动', '助人既可能来自互惠、社会责任和自我回报，也可能来自共情带来的真正关切。研究还显示，时间压力会显著压低助人概率，榜样、相似性和清晰责任会提高行动可能。App 可鼓励用户把助人设计得更小、更明确、更可持续：先做一个安全可承受的动作，再评估后续资源。这样既保护自己，也让利他不只停留在情绪感动。', '["利他", "共情", "互惠规范", "社会责任", "助人行为", "可持续行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1178, now()),
(101179, '亲密关系沟通：自我表露要配合倾听与安全感', '亲密关系的深化常来自逐步、互惠的自我表露：一个人适度开放，另一个人以关注、接纳和共情回应，信任才会继续增长。App 可将其用于伴侣、朋友和家庭沟通：从低风险话题开始，表达感受而非审判人格，复述对方重点，再分享自己的需要。自我表露不是情绪倾倒，而是在双方可承受的节奏里建立真实连接。', '["亲密关系", "沟通", "自我表露", "倾听", "共情", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1179, now()),
(101180, '关系修复：公平、承诺与非对抗表达比发泄更有效', '长期关系的满意度与知觉到的公平、支持、承诺和非对抗沟通密切相关。单纯“发泄怒气”并不稳定地减少敌意，反而可能强化攻击性表达。App 可引导用户把指责改成“我感到……因为……我希望……”，接纳反馈，避免翻旧账和人格攻击。关系中的成长不是压抑冲突，而是把冲突转化为可协商的需要与共同规则。', '["亲密关系", "冲突沟通", "公平", "承诺", "非暴力表达", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1180, now()),
(101181, '冲突降温：识别镜像知觉，创造共同目标', '冲突常被竞争、知觉到的不公平和误解放大。双方都容易把自己看成防卫者、把对方看成敌意来源，形成镜像知觉和自我实现循环。App 可帮助用户做降温三步：先描述事实与影响，暂缓动机判断；再找双方都在乎的超级目标；最后设计小而可验证的互惠行动。重点是恢复信任与沟通，而不是逼迫一方屈服。', '["冲突降温", "镜像知觉", "超级目标", "合作", "沟通", "和解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1181, now()),
(101182, '跨群体接触的条件：平等、合作与双重身份', '单纯把不同群体放在一起，并不必然减少偏见；有效接触往往需要平等地位、共同目标、合作任务和制度支持。友谊能降低焦虑，但也要让对方既是具体的人，又能代表其群体，积极经验才可能外溢。App 可用于社区或团队场景：把“我们/他们”改造成更大的“我们”，同时保留多元身份的尊重。', '["跨群体接触", "合作学习", "双重身份", "偏见减少", "共同目标", "社会融合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1182, now()),
(101183, '情绪不是事实：先把感受还原为想法', '低落、焦虑或羞耻出现时，大脑常把“我感觉很糟”翻译成“事情一定很糟”。App 可引导用户先记录情境、情绪强度，再追问：我刚才相信了哪句话？这句话是否只是情绪化推理、灾难化或读心术？目标不是否定感受，而是把感受当作提示灯，回到可检验的想法，更适合轻量自查。', '["情绪校准", "自动化想法", "认知重评", "感觉不是事实", "自助练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1183, now()),
(101184, '10大认知扭曲：给负面念头贴“错误类型”', '负面念头最有迷惑性时，通常显得“像事实”。可把它先归类：非黑即白、以偏概全、过滤好事、否定正面、读心或预言、放大缩小、情绪化推理、应该句式、乱贴标签、过度归责。App 可做成速查卡，每次只选最像的1—2类，再写一个更均衡的版本。适合作为每日复盘的第一步。', '["认知扭曲", "负面念头", "速查卡", "认知校准", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1184, now()),
(101185, '三栏法：自动想法—扭曲—理性回应', '当心里冒出“我不行、别人看不起我、我完了”这类自我批评时，把它们从脑中搬到纸面：第一栏写下意识想法，第二栏标注认知扭曲，第三栏写真实可信的理性回应。关键不是自我打气，而是让回应经得起自己相信，帮助用户从苛刻评价转向具体事实。适合在情绪波动后立即填写。', '["三栏法", "自动化想法", "自我批评", "理性回应", "情绪记录"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1185, now()),
(101186, '消极思维日志：把情绪记录做成一次小实验', '单纯写“我很烦”往往不够，日志应拆成：发生了什么、我有哪些情绪、我相信了哪些想法、这些想法有何扭曲、可替代的解释是什么。前后各给情绪强度打分，就能看到某个回应是否真的降低困扰。App 可用表单化流程降低书写门槛。它也便于后续追踪高频触发点。', '["消极思维日志", "情绪记录", "情绪强度", "认知实验", "自助表单"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1186, now()),
(101187, '从自责到负责：区分行为失误与人格否定', '自责和羞耻常把“我做错了一件事”升级为“我这个人很糟”。更有用的校准是：先确认行为是否真的不妥，再看影响范围，最后决定是否修正、道歉或补救。后悔可以指向行动，羞耻式标签只会让人反复惩罚自己。App 应引导用户评价“事”，少评价“人”。这样更容易产生具体、温和的改变。', '["自责", "羞耻", "内疚校准", "人格标签", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1187, now()),
(101188, '减少“应该”：把命令改成选择、希望和下一步', '“我应该、我必须、我不该”常带来压力、怨气和拖延。可把命令句改成更可执行的句子：我希望做到什么？这样做有什么好处？如果没做到，下一步能调整什么？这种语言替换不是放任，而是把自我惩罚改成选择、奖励和可持续的行动。用户可把新句式保存为个人提示语。', '["应该句式", "自我推动", "自责", "拖延", "语言替换"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1188, now()),
(101189, '每日活动计划：用掌控感和愉悦感重新排日程', '低动力时，先不要等待“有心情”。可以按小时写下当天小计划，晚上记录实际完成内容，并给每项活动标注掌控感与愉悦感分数。这个练习能帮助用户看见时间流向，也能发现哪些小事会带来一点秩序、休息或满足，作为下一天安排的依据。连续一周即可形成个人活动偏好图谱。', '["行为激活", "每日计划", "掌控感", "愉悦感", "低落自助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1189, now()),
(101190, '反拖延表：预测难度，再用实际体验校准', '拖延常来自“会很难、没回报、做了也没用”的预测。把任务拆成15分钟以内的小步骤，先估计每步的难度和满足感，再实际完成并记录真实体验。用户常会发现：任务没想象中难，完成后的满足感也不为零。App 可把它做成“预测—行动—校准”的闭环。每次只验证一个最小行动即可。', '["拖延", "反拖延表", "小步行动", "预测校准", "行为实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1190, now()),
(101191, '化整为零：只做一个可停下来的小步骤', '当任务像一座山时，人容易把“没做完全部”误读成“做一点也没意义”。更稳妥的做法是限定时间或范围：只听3分钟、只写一段、只整理一个角落，时间到即可停。可停下来的小步骤会降低威胁感，让行动重新启动，而不是靠压力硬推。尤其适合家务、学习和工作启动。', '["化整为零", "小步行动", "任务分解", "行动启动", "拖延"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1191, now()),
(101192, 'TIC-TOC：把任务干扰想法换成任务导向想法', '面对某项任务时，先写下阻碍行动的念头，例如“肯定做不好、没意义、会被批评”。这类念头是 TIC；再写一个更面向行动的 TOC，例如“先做一版草稿，之后再修改”。App 可把它设计成左右栏对照，帮助用户把注意力从自我评判转回任务本身。它能把焦虑转化为可执行指令。', '["TIC-TOC", "任务导向", "拖延", "自动化想法", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1192, now()),
(101193, '快乐预测：用事实检验“一个人做也不会开心”', '低落时，人会预测“做什么都没意思”“一个人更没劲”。可先列几个独自或结伴活动，给预期愉悦感打分，完成后记录真实分数。这个练习不要求强迫快乐，而是用数据检查旧假设：哪些活动仍有一点点滋养？哪些活动该减少？适合做成 App 的轻量打卡。也能帮助发现适合独处的恢复性活动。', '["快乐预测", "行为激活", "独处", "愉悦感", "假设检验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1193, now()),
(101194, '受批评时：先问具体，再回应立场', '被批评时立刻反击，常让对话升级。更稳的步骤是：先提具体问题，弄清对方不满什么；再承认其中可能真实或可理解的部分，降低敌意；最后用坚定但不攻击人格的方式表达自己的看法和需求。App 可把它拆成“澄清—认同—协商”的沟通脚本。这比争输赢更适合维护长期关系。', '["沟通", "批评应对", "移情", "协商", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1194, now()),
(101195, '边界练习：坚定说“不”不等于拒绝关系', '容易内疚的人常把拒绝请求理解成“我不够好”或“关系会破裂”。边界练习可以先承认对方需求，再清楚说明自己的限制，并重复立场而不卷入攻击。重要的是区分爱与妥协：尊重关系不代表答应所有要求。App 可提供拒绝话术、角色扮演和复盘。必要时可提前写好底线句并演练。', '["沟通边界", "拒绝", "内疚", "关系校准", "角色扮演"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1195, now()),
(101196, '垂直箭头法：追到隐性假设再松动它', '一个表层想法背后常藏着更深规则。写下负面念头后连续追问：“如果这是真的，最糟意味着什么？”直到看见核心假设，如“被批评就说明我没价值”“不成功就没人尊重”。再回到这些假设，检查证据、扭曲和替代观点。适合用于反复出现的焦虑或低落主题。它适合处理反复出现的同类困扰。', '["垂直箭头法", "隐性假设", "核心信念", "焦虑校准", "低落自助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1196, now()),
(101197, '成就不等于价值：把结果从自我价值里拆出来', '工作、考试或业绩可以反映某次表现，却不能等同于一个人的价值。把“我失败了”改成“这次结果不理想，我能学习或调整什么”，能减少结果对自尊的绑架。App 可在复盘页区分三栏：结果事实、可控过程、个人价值，帮助用户把身份从成绩单里拿回来。对职场、学习与创作复盘都适用。', '["自我价值", "工作压力", "成就焦虑", "自尊", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1197, now()),
(101198, '完美主义校准：用低一点的标准做一次实验', '完美主义常把“高标准”包装成动力，但也会制造紧张、拖延和无法满足。可以设计一次小实验：把标准降到80%、60%甚至40%，完成后记录表现和满意度。目的不是变差，而是验证“必须完美才安全/才快乐”是否真实，并练习接受可修改的初稿。它适合和任务打卡、初稿提交结合使用。', '["完美主义", "标准校准", "行为实验", "初稿思维", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1198, now()),
(101199, '把儿童画当作表达线索，而不是给孩子贴标签的证据', '儿童画可承载想法、感受、事件和身体经验，但同一图像可能受年龄、文化、材料、环境和亲子/成人关系影响。App 提示家长时，应把画看成“孩子可能在表达什么”的邀请，而非“这说明孩子有某问题”的结论。更合适的做法是温和询问、听孩子解释，并结合最近生活变化和日常行为一起理解。', '["儿童画", "非诊断", "亲子观察", "多元意义", "不贴标签"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1199, now()),
(101200, '绘画是孩子说不出口时的另一种语言', '当孩子还不能清楚表达害怕、失望、委屈或矛盾时，画画能成为相对自然的出口。纸上的线条、角色、颜色和故事，给孩子提供了比直接谈话更柔软的表达方式。App 端可引导家长说：“你愿意画给我看看吗？”而不是追问“你到底怎么了”。画本身不必漂亮，重点是让孩子知道：你的感受可以被看见，也可以慢慢说。', '["非语言表达", "情绪支持", "亲子陪伴", "安全表达", "儿童沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1200, now()),
(101201, '先陪孩子画完，再谈画里发生了什么', '孩子投入绘画时，成人频繁追问可能打断思路，也可能让孩子感觉被审问。更好的节奏是先提供材料、时间和安静陪伴，观察孩子是否愿意边画边说；画后再用开放问题邀请讲述。家长可以从“这幅画里发生了什么？”“你想给它起什么名字？”开始，允许孩子不回答。被允许沉浸和停顿，孩子才更容易把画变成自己的故事。', '["画后提问", "开放式问题", "倾听", "亲子对话", "尊重节奏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1201, now()),
(101202, '用“不知道”的姿态看画，把解释权交还给孩子', '成人很容易把自己的经验套进孩子的画里，例如把某种颜色、大小或形象直接解释成某种情绪。书中强调更稳妥的姿态是“我不知道，所以想听你说”。App 可提供示范语：“我看到这里有一条蓝线，它像什么？”“这个角色在想什么？”这种好奇而不下结论的提问，能减少误解，也让孩子成为自己作品的专家。', '["不知道姿态", "非评判", "现象学", "儿童主体", "倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1202, now()),
(101203, '把情绪画出来，有助于把“我有问题”变成“问题在这里”', '孩子把害怕、愤怒、孤独或冲突画成怪兽、天气、角色或场景时，情绪就从身体里“搬”到纸上，变成可以一起观看和讨论的东西。家长可以陪孩子给情绪角色起名字、问它需要什么、它什么时候会变大或变小。这样做不是否认感受，而是帮孩子和感受保持一点距离，学习“我正在经历情绪，但我不等于情绪”。', '["情绪外化", "儿童情绪", "叙事表达", "自我接纳", "亲子工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1203, now()),
(101204, '看一组画里的变化，比盯住一张画更接近孩子', '单张画像电影里的一个定格，只能呈现当下的一小部分。孩子在不同时间、关系和心情下画出的内容会变化：有时更封闭，有时更丰富，有时从小人物变成更开阔的场景。App 可鼓励家长保存一段时间的作品，观察孩子讲述、主题、主动性和情绪恢复的变化，而不是因为一次画得黑、乱或小，就给孩子贴上固定标签。', '["看见变化", "不贴标签", "连续观察", "儿童发展", "成长记录"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1204, now()),
(101205, '孩子不想画时，先降低压力而不是催促配合', '有些孩子拒绝画画，不一定是“不合作”，可能是害怕画错、缺乏安全感、不信任成人，或对白纸感到无从下手。家长可以把任务变小：先画一个点、一条线、一个拇指印，或一起补全一个搞笑角色；也可以换成贴纸、积木、木偶、讲故事。重点是让表达重新变得可玩、可退、可选择，而不是把画画变成新的压力。', '["抵触绘画", "游戏化表达", "降低压力", "亲子支持", "选择感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1205, now()),
(101206, '安全的表达空间，来自材料、环境和成人反应', '孩子是否愿意画，和纸笔质量、空间大小、旁人是否围观、成人是否尊重作品都有关系。一个舒适、不被打扰、允许弄脏又有边界的地方，会让孩子更容易放松。家长还要避免在画上随意批改、嘲笑或公开展示孩子不想分享的内容。对孩子来说，画不是废纸，而是“我说过的话”；被妥善对待，才会带来安全感。', '["安全感", "表达环境", "作品尊重", "保密", "亲子陪伴"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1206, now()),
(101207, '家庭画适合作为对话入口，不适合当作家庭关系判决书', '孩子画家人时，人物距离、大小、边界和活动可能提供关系线索，但不能被成人直接判定为“亲谁”“怕谁”或“家庭有问题”。更适合的 App 引导是围绕画面邀请孩子讲故事：“大家在做什么？”“谁最需要帮助？”“你希望家里多一点什么？”这样既能了解孩子眼中的家庭体验，也能避免把画变成审讯或标签。', '["家庭画", "亲子对话", "关系线索", "非评判", "家庭支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1207, now()),
(101208, '在画里寻找孩子的力量：希望、主动性和恢复感', '关注孩子画中的痛苦很重要，但只看问题会错过另一半信息：孩子可能也在画安全的家、会保护自己的角色、温暖的动物、未来会变好的场景。App 可以提醒家长问：“这幅画里谁在帮忙？”“哪里让你觉得舒服？”“接下来会出现什么好办法？”把注意力放到希望、资源和应对方式上，能支持孩子形成“我能慢慢恢复”的经验。', '["康复力", "希望感", "儿童资源", "积极关注", "情绪复原"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1208, now()),
(101209, '创伤知情倾听：先把掌控权还给对方', '当一个人尝试谈起受虐经历，最有帮助的不是追问细节，而是提供稳定、可选择的倾听：告诉对方可以按自己的速度说、可以停下、也可以只说感受。回应时保持平静、尊重与保密边界，承认谈起这些很难，并把决定权还给对方。若内容带来强烈痛苦或安全风险，应协助联系可信赖的专业支持。', '["创伤知情", "倾听", "安全感", "自主权", "幸存者支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1209, now()),
(101210, '相信与确认：让幸存者重新相信自己的感受', '受虐幸存者常经历“不被相信”带来的二次伤害。支持者可以表达：我愿意认真听，你的痛苦值得被看见，这不是你的错。确认并不等同于做法律或事实裁判，而是承认对方的感受、困惑和受伤是真实需要被照顾的。避免用“为什么现在才说”“你确定吗”来增加羞耻和自责。', '["相信", "情感确认", "避免责备", "二次伤害", "关系支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1210, now()),
(101211, '边界与安全：清楚说明可做与不可做的事', '创伤后的安全感来自可预测的关系：什么时候谈、在哪里谈、谁会知道、遇到风险如何处理，都应尽量说明清楚。支持者或专业人员不要承诺做不到的事，也不要替对方决定进度。允许对方选择座位、暂停话题、拒绝回答或提出需要，本身就是在修复曾被侵犯的边界，也是在重新学习安全地说“不”。', '["边界", "安全计划", "保密", "可预测性", "专业边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1211, now()),
(101212, '避免责备受害者：离不开不代表愿意受伤', '有些人难以离开伤害关系，并不是“愿意受伤”或“不够坚强”。创伤可能破坏自我价值感、安全感和求助能力，现实中还可能存在经济、住所、威胁、羞耻或亲密依赖等限制。支持时应少问“你为什么不走”，多问“你现在最需要什么支持”“怎样做会更安全”。先把安全、资源和选择放在第一位。', '["避免受害者责备", "关系支持", "安全", "羞耻修复", "创伤理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1212, now()),
(101213, '亲子支持：创伤父母需要把过去和现在分开', '有受虐史的父母可能在养育中更容易焦虑、过度保护或不敢设限，这常与旧创伤被孩子年龄、亲密接触或独立需求触发有关。重要的是区分“我感到害怕”和“孩子真的处在危险中”，也区分“有强烈情绪”和“会做出伤害行为”。稳定的亲子边界、年龄适配的信息和专业支持，都能帮助家庭减少创伤传递。', '["亲子支持", "创伤父母", "养育边界", "触发因素", "代际影响"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1213, now()),
(101214, '儿童保护意识：不要独自背负正在发生的风险', '当信息提示儿童可能正处于危险中，支持者不应把压力独自扛住，也不应自行调查或草率下结论。更稳妥的做法是查看所在地区和机构的儿童保护流程，向督导、专业机构或合规负责人咨询；在可行且安全的情况下，与当事人透明讨论隐私边界和保护儿童的必要性。把孩子安全与当事人支持同时纳入计划。', '["儿童保护", "风险识别", "隐私边界", "求助资源", "专业咨询"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1214, now()),
(101215, '自伤回应：把行为当作痛苦信号而非作秀', '面对自伤，贴上“求关注”“故意添麻烦”的标签会加重羞耻。更有帮助的是先评估当下安全，平静询问是否需要医疗或紧急支持，再在对方愿意时探索触发点、情绪功能和可替代的表达方式。不要命令式要求立刻停止，而是把它看作痛苦无法用语言表达时的信号，并引导寻求专业帮助。', '["自伤支持", "危机安全", "非评判", "情绪表达", "专业帮助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1215, now()),
(101216, '接触伤害者前：先做安全与期待梳理', '幸存者有时希望通过接触伤害者获得承认、道歉或结束感，但结果可能与期待不同，也可能重新激活无力和羞耻。支持者不应替对方决定“该不该见”，而应一起梳理：想得到什么、最糟结果是什么、谁能陪伴、事后如何照顾自己、是否有更安全的替代方式。最终选择仍属于当事人。', '["安全计划", "自主选择", "关系边界", "创伤支持", "期待管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1216, now()),
(101217, '照顾者自我稳定：支持别人前先稳住自己', '长期倾听创伤故事会影响照顾者、咨询师或亲友的睡眠、情绪和安全感。稳定自己不是自私，而是避免把愤怒、震惊或拯救冲动带回到对方身上。可通过督导、同伴支持、工作量管理、身体照顾和个人生活边界来承接压力。支持者越能照顾好自己，越能提供不侵入、不过度反应的陪伴。', '["照顾者稳定", "间接创伤", "督导", "自我照顾", "反移情"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1217, now()),
(101218, '短程支持的边界：有限帮助也要透明与温和', '当支持时间有限时，不宜为了“赶进度”强行深挖创伤细节。可以诚实说明服务边界，聚焦当下最需要的稳定、倾听、资源连接和下一步安排。有限支持仍然可以有价值：让对方被认真对待，知道自己不必马上说完一切，也知道还可以通过本地专业服务、互助组织或长期咨询继续获得帮助。', '["短程支持", "资源引导", "稳定化", "非侵入", "转介"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1218, now()),
(101219, '专业边界：不把固定答案强加给幸存者', '创伤恢复没有统一剧本。有人需要谈很多，有人暂时只能谈感受；有人选择宽恕，有人选择不宽恕；有人适合某种方法，有人会因此感到被控制。专业支持应服务于当事人的安全与恢复，而不是让当事人去适应理论、信念或他人的期待。尊重选择、持续评估和承认局限，是专业边界的一部分。', '["专业边界", "尊重选择", "避免强加", "恢复路径", "创伤知情"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1219, now()),
(101220, '不确定记忆：接纳感受，避免暗示结论', '有些人只有模糊感受、身体反应或童年空白，却没有清晰记忆。支持时既不要否定痛苦，也不要暗示“这一定说明发生过什么”。可以陪对方探索这些感受何时出现、与哪些压力或关系有关、现在需要怎样的照顾。允许“不确定”存在，往往比急于给出解释更安全、更尊重。', '["不确定性", "记忆", "非暗示", "情感接纳", "创伤支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1220, now()),
(101221, '重要不等于紧急：先给任务排信号等级', '用户说“事情太多”时，先不要立刻给时间管理建议，而是把任务分成四类：真重要、只是紧急、可延后、可删除。App 可追问：如果今天只能推进一件事，哪件会改变后续局面？哪些只是缓解焦虑？这样能把注意力从灭火转回长期价值，减少被消息、截止时间和他人期待牵着走。', '["结构化思考", "优先级", "重要紧急", "行动校准", "拖延拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1221, now()),
(101222, '可逆决策先行动：别把所有选择都当终局', '很多犹豫来自把每个决定都想成“不能回头”。可先区分：这件事是可逆试错，还是不可逆承诺？可逆事项适合小步行动、设复盘点、保留退出条件；不可逆事项才需要更多信息和更严验证。App 可帮助用户把“我要不要做”改成“用什么最小成本试一次”，并提前写清何时继续、暂停或退出。', '["决策校准", "可逆决策", "小步试错", "行动前假设", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1222, now()),
(101223, '40%—70%信息区间：停止用查资料伪装拖延', '信息太少会鲁莽，信息太多会瘫痪。行动前可以问：我掌握的信息是否已超过最低判断线？继续收集会改变选择，还是只是降低不安？当信息处在可判断但不完美的区间，就应先做低风险行动，再用反馈更新。App 可把“还没准备好”拆成缺失事实、可验证假设和下一步实验。', '["信息判断", "行动校准", "反拖延", "风险评估", "假设验证"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1223, now()),
(101224, '多米诺骨牌：把行动后果推到第二层', '一阶思维只问“这样做马上会怎样”，二阶思维还问“然后呢”。用户做关系、职业或消费选择时，App 可引导列出直接收益、延迟成本、对他人的影响、未来选择空间是否变窄。不是为了把人吓住，而是让决定从即时舒服变成整体可承受，尤其适合冲动回复、辞职、分手和大额投入前。', '["二阶思维", "系统思考", "后果推演", "冲动管理", "决策校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1224, now()),
(101225, '贝叶斯式校准：新证据更新概率，不改写人生结论', '遇到一次失败、一次冷淡回复或一个异常结果，用户容易立刻下结论。更稳的做法是先写下原先判断、当前新证据、证据强度和替代解释，再更新概率，而不是从“可能有问题”跳到“我完了”。App 可提醒：黑天鹅、均值回归和样本量不足都可能误导判断，先校准概率，再决定行动。', '["概率思维", "贝叶斯更新", "认知校准", "异常值", "情绪决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1225, now()),
(101226, '反证优先：把观点当假设，而不是身份', '当用户坚持“我就是这样”“他一定是故意的”时，可把判断暂时降级为假设。先问：如果这个想法是错的，会有哪些迹象？我最想回避的证据是什么？谁能做同行评议？这种方式不是否定感受，而是把自我防卫转成求真流程，帮助用户在关系误解、职业判断和自我评价中减少确认偏误。', '["反证思维", "确认偏误", "同行评议", "自我觉察", "问题拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1226, now()),
(101227, '相关不等于因果：先找第三变量和机制链', '“我一主动他就冷淡”“我努力后反而失败”这类叙述常把同现当因果。App 可引导用户列出：时间顺序是否成立？有没有共同原因？是否存在第三变量？机制链能否说清？再用鱼骨或五问法拆出环境、行为、资源、沟通、时机等可能原因。目标不是争辩谁对，而是找到真正可改变的环节。', '["因果推理", "问题拆解", "五问法", "鱼骨图", "误判修正"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1227, now()),
(101228, '第一性原理：拆到不可再借用的前提', '当用户困在“大家都这么做”“这个行业只能这样”时，适合回到第一性原理：目标到底是什么？不可违背的约束是什么？哪些只是惯例、面子或他人经验？把问题拆到事实、约束、资源和可组合要素后，再重新设计方案。它尤其适合职业转型、关系边界和产品选择，能避免在旧框架里微调。', '["第一性原理", "问题拆解", "边界思维", "创新解法", "反惯性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1228, now()),
(101229, '逆向目标：先列出怎样一定会失败', '如果正向规划让人空泛，可以反过来问：怎样做会让这段关系更糟、这个项目失败、这次改变半途而废？把失败路径列出来，再转成避险清单：不熬夜做重大决定、不在情绪峰值沟通、不把关键任务放到最后一天。逆向思考能把模糊目标变成边界和预案，让用户在行动前看见坑。', '["逆向思维", "预演失败", "边界思维", "风险预案", "行动前假设"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1229, now()),
(101230, '奥卡姆+汉隆：先用简单且非恶意的解释降噪', '面对他人迟回、语气变化或工作失误，用户常把解释升级为复杂阴谋或恶意攻击。可先应用两步：有没有更简单的解释？如果疏忽、信息差或能力不足足以解释，是否暂缓恶意归因？这不会取消边界和追责，但能避免在证据不足时把关系推向敌对，适合沟通前的情绪降噪。', '["解释校准", "奥卡姆剃刀", "汉隆剃刀", "沟通准备", "关系误解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1230, now()),
(101231, '金线表达：先找一条主线，再安排数据', '用户想表达很多时，常把事实、感受、证据一次性倒给对方。金线思路要求先确定一句主线：我希望对方理解什么、改变什么、记住什么？再选择能支撑主线的材料，删除重复和跑题信息。App 可用于道歉、汇报、谈边界、写长消息前，帮助用户从“堆信息”转向“有结构地促成理解”。', '["结构化表达", "沟通", "故事力", "信息筛选", "提问"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1231, now()),
(101232, '用“什么”问题打开思路：把判断题转成探索题', '封闭问题容易把对话推向防守，例如“你是不是不在乎我”。更有用的是把它改成探索式问题：你当时最在意什么？我们现在真正要解决什么？什么做法能让双方都更安心？App 在陪伴中可优先使用“什么”类提问，让用户从定罪、追问原因和自责中退一步，看到需求、目标和可行动选项。', '["提问方式", "沟通", "探索式问题", "情绪降温", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1232, now()),
(101233, '向上/向下归类：在愿景和细节之间切换', '沟通卡住时，可能不是立场冲突，而是信息层级不一致。向上归类问目的、价值和共同收益；向下归类问谁、何时、在哪里、怎么做、标准是什么。App 可先帮用户把争执上调到共同目标，再下调到具体行动。这个方法适合谈判、家庭分工、目标设定和会议复盘，能把抽象口号落到可执行细节。', '["NLP归类法", "沟通提问", "抽象具体", "目标拆解", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1233, now()),
(101234, '合作从“不知道”开始：先理解利益，再谈方案', '冲突中最危险的不是分歧，而是过早确信自己懂了对方。合作式思维提醒先承认未知：我可能漏掉了什么事实？对方真正想保护的利益是什么？哪些人受影响却没发声？App 可把争执拆成目的、利益相关方、隐藏担忧、可共赢方案四栏，让用户从妥协或压服转向共同解决。', '["合作式思维", "利益相关方", "冲突处理", "倾听", "共同利益"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1234, now()),
(101235, '复杂问题不能只问谁错了：看系统、变量与小实验', '关系、团队和人生选择常属于复杂系统，不能只靠单一因果解释。App 可引导用户区分：哪些部分可预测，哪些变量太多只能试验？不要急着找唯一责任人，而是观察反馈回路、关键杠杆和边界条件，再做一个低成本小实验。复杂问题需要多视角、持续校准，而不是一次性标准答案。', '["复杂系统", "系统思考", "多元视角", "小实验", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1235, now()),
(101236, '战略就是放弃：用赛点和变量选择战场', '成长不是把所有事都做满，而是识别赛点、放弃低杠杆选项。用户可以问：当前最关键的成败节点是什么？我是在常量上硬拼，还是能找到新变量？哪些机会虽好但会分散主线？App 可把选择变成取舍表：必须抓住的大机会、可以错过的小机会、要借势的框架、要停止投入的低回报事项。', '["战略思维", "赛点", "变量思维", "取舍", "机会成本"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1236, now()),
(101237, '真实反馈—结果—复利：成长靠可重复的增强回路', '用户容易把学习、忙碌或打卡当成成长本身。更可靠的链条是：进入真实场景，拿到反馈，修正行动，产出结果，再把有效动作重复。凡能积累的能力都有复利，但前提是反馈真实、归因正确、周期足够长。App 可在复盘时追问：结果是什么？反馈来自哪里？下一轮保留、删除、加强什么？', '["真实反馈", "结果思维", "复利", "迭代", "行动复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1237, now()),
(101238, '反直觉机会：糟糕创意可能藏着未命名需求', '有些选择初看不合理，是因为大众还没看见新需求。App 面对用户的职业或项目想法时，可不急着按常识否定，而是追问：这个想法解决了谁的真实痛点？为什么别人没做，是太小、太麻烦，还是尚未命名？能否用最小作品验证？反直觉不是盲目冒险，而是在不确定中发现被忽视的机会。', '["反直觉思维", "创业思维", "需求发现", "最小验证", "机会识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1238, now()),
(101239, '把英雄之旅当成转折复盘图，而不是命运剧本', '英雄之旅适合被当作人生转折的叙事地图：召唤出现、出现抗拒、寻找协助、进入试炼、获得新的理解，再把收获带回日常。它不预测你“注定会怎样”，而是帮助你把混乱经历分段整理。遇到换工作、关系变化、疾病恢复、身份重建时，可以先标记自己处在哪一段，再问：这一段需要我看见什么、练习什么、寻求什么支持？', '["英雄之旅", "人生转折", "叙事工具", "复盘框架", "行动练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1239, now()),
(101240, '三种生活位置：顺从、退场与主动参与', '面对人生选择时，人常在三种位置之间移动：顺从位置，把外界标准当成唯一答案；退场位置，因为失望或受伤而与世界保持距离；主动参与位置，承认现实限制，同时尝试把真实愿望带进生活。这个分类不是给人贴标签，而是一个自查仪表盘。每天记录一个时刻：我是在迎合、退缩，还是在创造性参与？下一步只需要从其中多拿回一点选择权。', '["自我觉察", "人生脚本", "选择权", "英雄之旅", "成长框架"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1240, now()),
(101241, '召唤不是神秘声音，而是反复让你变鲜活的线索', '“召唤”可以去神秘化理解为价值线索：某些人、作品、经历或问题反复让你被触动，让你觉得“这件事和我有关”。它可能来自童年崇拜的人、一次艰难后更清楚的珍视、一个艺术作品带来的共鸣，也可能来自临终回望时仍觉得值得的事。练习时先收集线索，不急着定义终身使命，只观察它们共同指向的价值和今天可实践的小动作。', '["召唤", "价值澄清", "生命方向", "书写练习", "自我观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1241, now()),
(101242, '抗拒召唤：把“不可能”的声音外化出来', '当一个愿望真正重要时，抗拒常会立刻出现：不现实、你不行、别人会失望、现在太晚。抗拒不一定是敌人，它可能是在保护你免于风险、羞耻或失控。实用做法是把三方写出来：愿望说什么，批评者说什么，支持者会提醒什么。这样你不必在脑内被单一声音压住，而能看见愿望、恐惧和资源同时存在，再选择一个低风险试验。', '["抗拒", "内在批评", "目标行动", "自我支持", "复盘工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1242, now()),
(101243, '向导不是救世主，而是帮你恢复可能感的资源', '向导可以是真实老师、家人朋友、榜样人物、一本书、一个社群，甚至是一段让你想起勇气的经历。它的功能不是替你决定人生，而是在你被“不可能”困住时，提供一个更大的参照系：有人这样活过，有方法可以学习，有支持可以借用。为一个目标建立“向导清单”：谁能给经验、谁能给陪伴、谁能给反馈、哪个环境能让你更稳。', '["向导", "资源感", "榜样学习", "支持系统", "人生转折"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1243, now()),
(101244, '阈限时刻：离开旧系统前，先搭一个新系统', '人生转折常像跨过阈限：旧生活系统失效，新的系统还没成形。此时单靠热情容易迷路，单靠忍耐又会僵住。更稳的做法是给新阶段搭最低限度的结构：固定作息、学习路径、支持联系人、每周复盘、身体照顾和财务边界。转折不是一次性跳跃，而是从旧身份到新身份的过渡工程；结构越清楚，探索越安全。', '["阈限", "人生转折", "系统搭建", "过渡期", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1244, now()),
(101245, '试炼之路：把困难拆成正在训练的能力', '试炼不是为了证明你吃苦够多，而是把一个目标所需的能力逐步显影。一个障碍可能在训练边界表达，一个失败可能在训练复盘能力，一段不确定可能在训练求助和耐心。复盘时不要只问“为什么又出问题”，也问：这个困难要求我发展哪项能力？我已经有哪些资源？下次可以做哪一个更小、更具体的实验？这样试炼会从打击变成训练场。', '["试炼", "能力成长", "复盘", "行动实验", "目标障碍"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1245, now()),
(101246, '资源感三联：一句意图、一个身体中心、一个支持圈', '把愿望落地时，可以先做三联校准。第一，把意图压缩成一句正向短语，越简单越容易行动。第二，找到身体中心，可能是心口、腹部、脚底或背部，让注意力不只停在焦虑的头脑里。第三，展开支持圈：人、地点、工具、习惯、榜样、自然环境都算资源。意图给方向，身体中心给稳定，支持圈给现实承托，三者合在一起才更容易前进。', '["资源感", "目标行动", "身体中心", "支持系统", "自我调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1246, now()),
(101247, '原型能量是状态语言：温柔、勇猛、顽皮', '原型能量可以理解为自我观察的状态词，而不是神秘力量。温柔帮助你照顾脆弱、建立信任；勇猛帮助你表达边界、保持专注；顽皮帮助你松动僵硬、发现新办法。三者缺一都容易失衡：只有温柔可能不敢行动，只有勇猛可能变强硬，只有顽皮可能逃避承诺。沟通或行动前问自己：现在最缺的是哪一种状态？', '["原型能量", "温柔", "勇猛", "顽皮", "状态调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1247, now()),
(101248, '面对障碍时，先建立关系，再寻找新路径', '障碍出现时，人很容易进入对抗、逃避或僵住。英雄之旅的练习把障碍当成需要互动的对象：先回到中心，看清它是什么；再选择一种状态进入关系，可能是温柔地照顾害怕，勇猛地设边界，或顽皮地换视角。目标不是把障碍立刻消灭，而是不把全部力量交给它。只要能多一个回应方式，行动空间就变大了。', '["障碍应对", "非对抗", "原型能量", "情绪调节", "行动空间"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1248, now()),
(101249, '恶魔翻译：把问题行为读成未被照顾的需求', '“恶魔”可以去神秘化为反复卡住你的问题模式，如拖延、焦虑、沉迷、回避或自我批评。练习不是给自己定罪，而是把模式翻译成需求：这个行为想替我满足什么？它在保护什么？有没有更健康的方式满足同一需求？可以用一个身体姿态表现这个模式，放慢、观察、写下它背后的正向意图。看见需求后，改变才不只是压制。', '["问题行为", "正向需求", "身体觉察", "模式转化", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1249, now()),
(101250, '目标与障碍的和谐：别急着消灭拖延和焦虑', '有些障碍并非目标的反面，而是目标系统里失衡部分的提醒。例如过度用力时出现拖延，可能在提醒你需要休息、节奏或更柔软的方法；强烈焦虑可能在提醒你需要保护、准备或支持。复盘时把目标和障碍分别写成两个角色，观察它们各自想守护什么，再设计一个同时照顾两方的小步骤。整合比压制更能带来持续行动。', '["目标障碍", "拖延", "焦虑", "整合练习", "行动节奏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1250, now()),
(101251, '回归阶段：把收获变成可传递的支持', '英雄之旅的最后不是“我终于成功了”，而是把获得的理解、能力和温度带回关系与日常。回归可以很小：把自己走过的经验整理成一条建议，陪伴一个正在相似困境中的朋友，或把某个练习变成家庭、团队里的共同语言。帮助别人不是拯救对方，而是稳定地呈现你已经学会的东西，让他也更容易看见自己的资源。', '["回归", "贡献", "关系支持", "经验传递", "成长复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1251, now()),
(101252, '每日英雄复盘：用六个问题整理今天的成长线', '英雄之旅可以缩小到每天的复盘。睡前用六个问题整理：今天什么触动了我？我在哪里退缩或抗拒？谁或什么给了我支持？我遇到的试炼在训练什么能力？我从障碍中读到了什么需求？明天我能把一点收获带给谁或带到哪里？这个练习把宏大叙事变成日常行动，让成长不依赖戏剧性事件，而落实为持续观察和小步实践。', '["每日复盘", "英雄之旅", "行动练习", "自我观察", "成长记录"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1252, now()),
(101253, '把天赋看成“兴趣—投入—练习”的循环', 'App 可引导父母少问“孩子天生适合什么”，多观察孩子在哪些活动里自然投入：反复追问、愿意试错、忘记时间、做完还想继续。天赋不是一次测评给出的命运，而是孩子在有意义的经验中不断使用、练习并巩固出来的能力倾向。记录这些高能量时刻，比急着报班更能帮助父母看见真实潜能。', '["儿童天赋", "兴趣观察", "内在动机", "能力练习", "非宿命"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1253, now()),
(101254, '避免把“有天赋/没天赋”变成孩子身份标签', '当成人用单一标准判断天赋时，被夸“特别有天赋”的孩子可能背上必须成功的压力，被说“没有天赋”的孩子则容易低估自己。App 回答亲子问题时，应把天赋表述为“当前显现的兴趣和优势线索”，而不是身份判决；既不神化孩子，也不否定孩子，让父母继续观察具体行为和成长环境。', '["不贴标签", "天赋不是命运", "成长型视角", "亲子评价", "孩子自我认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1254, now()),
(101255, '安全感是探索和创造的基地', '孩子只有确认“真实的我也被爱”，才更敢离开父母视线去探索、尝试和创造。App 可提醒父母：支持天赋开发的第一步不是训练强度，而是稳定回应、接纳感受、允许孩子表达需要。安全关系让孩子保留开放、好奇和创造热情；长期被迎合期待的孩子，可能看似听话，却逐渐失去自己的方向。', '["安全依恋", "无条件接纳", "探索基地", "创造热情", "真实自我"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1255, now()),
(101256, '自我效能来自孩子亲手完成的小挑战', '孩子学翻身、站立、走路时，真正让他兴奋的是“我靠自己做到了”。父母若过早代劳或急着纠正，会削弱这种自我效能。App 可建议把能力练习拆成安全的小挑战：让孩子自己试、允许慢一点、在关键处提供材料或提示，完成后描述他做到了什么。孩子越多体验“我能影响结果”，越愿意继续练习。', '["自我效能", "小步挑战", "放手练习", "能力感", "少代劳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1256, now()),
(101257, '榜样和关系比说教更能点燃练习', '孩子会模仿重要关系人的动作、语气、态度和价值。与其反复讲“你要努力”，不如让孩子看到一个真实投入的人：父母读书、修理、运动、画画、认真道歉、合作解决问题。App 可提示父母把“教育孩子”改成“共同做给孩子看”，再邀请孩子参与。关系越亲近，榜样越容易转化为孩子愿意练习的能力。', '["榜样力量", "镜像学习", "亲子关系", "共同参与", "能力习得"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1257, now()),
(101258, '给孩子真实玩耍、感官和创造空间', '孩子认识世界需要摸、跑、搭、拆、问、想象和与同伴互动。若生活只剩课程、屏幕和被安排的任务，孩子容易从创造者变成消费者。App 可建议家庭每周保留“无成果压力”的真实体验：户外探索、做饭、手工、照顾植物、自由游戏。天赋常在不被急着评价的玩耍里露出线索。', '["自由玩耍", "真实经验", "创造力", "感官探索", "反鸡娃"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1258, now()),
(101259, '共情、合作和责任感也是重要天赋', '天赋不只存在于数学、音乐、体育等显眼领域。孩子能察觉他人情绪、愿意帮助、会在游戏中照顾别人、能与同伴合作解决问题，也是在发展珍贵能力。App 可把“我的孩子没有特长”转向更宽的观察：他如何关心人、协调冲突、承担小任务、表达善意。不要把竞争成绩当成唯一成长尺度。', '["共情能力", "合作能力", "责任感", "社会性发展", "多元天赋"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1259, now()),
(101260, '先保护孩子“想说”的欲望', '孩子表达不清、说得慢或观点幼稚时，最需要的不是立刻纠正，而是有人认真听完。App 可提示父母：放下手头事，眼神回应，不抢话，不用“大人说话小孩别插嘴”堵住孩子。表达欲来自被看见和被尊重；一旦孩子在重要场合被嘲笑、打断或羞辱，就可能学会沉默。', '["孩子表达欲", "主动倾听", "不打断", "亲子沟通", "尊重孩子"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1260, now()),
(101261, '反馈式倾听：先照见感受，再讨论做法', '当孩子哭闹、生气或抱怨时，父母可以先把听到的感受说出来：“你是觉得被冷落了？”“你很害怕，但又想试试？”这种反馈不是纵容，而是在帮孩子理解自己的情绪。App 可生成三步话术：认真听；猜测并核对感受；再说明原因、规则或下一步。孩子感到被理解后，更容易听进建议。', '["反馈式倾听", "情绪命名", "共情倾听", "开放式提问", "沟通话术"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1261, now()),
(101262, '用选择权替代命令，训练孩子判断力', '命令常让孩子把注意力放在反抗父母上，选择题则把注意力带回问题本身。App 可建议父母给出有限而真实的选择：“先吃饭再吃糖，还是吃完饭后吃糖？”“吉他和滑板都要练习，你更想长期投入哪一个？”选择权不是放任，而是在安全边界内让孩子思考后果、听见建议，并为自己的决定负责。', '["选择权", "非命令沟通", "判断力", "自主性", "边界内自由"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1262, now()),
(101263, '少评价多描述，鼓励要落到具体行为', '“你真棒”容易空泛，“你坚持改了三遍，还能找出更好的写法”更能让孩子知道可复制的努力。App 可把父母的评价改写为描述：说事实、说过程、说进步、说下一步，而不是给人格下结论。尤其避免“笨、懒、没出息、内向”这类负面标签，因为孩子可能把它当成自己的人生脚本。', '["少评价多描述", "具体鼓励", "不贴标签", "正向沟通", "自信心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1263, now()),
(101264, '边界不是羞辱：犯错后给规则和补救路径', '孩子犯错时，羞辱和惩罚容易让他学会隐瞒；清楚规则和补救方法，才会帮助他负责。App 可建议父母先稳定情绪，描述影响，再给出可执行的弥补路径：“墙被画脏了，我们一起清理；以后画在纸上。”边界要具体、可执行、有后果，但不否定孩子本身。这样既保护关系，也让孩子学习责任。', '["鼓励与边界", "犯错修复", "正向教养", "责任感", "不羞辱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1264, now()),
(101265, '低落不是意志薄弱：先把病耻感卸下来', '低落、失去兴趣、睡眠紊乱、精力下降和自责，并不说明一个人懒惰、矫情或不够坚强。误解会让人更羞耻，也更不愿开口求助。App 端适合先用去污名语言回应：这是需要被理解和支持的痛苦体验，不是人格缺陷；接下来再一起看今天最需要减轻的负担、能联系谁、是否需要专业帮助。', '["去污名化", "病耻感", "自责", "非诊断", "心理教育", "求助意愿"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1265, now()),
(101266, '“黑狗感”：把暗淡、隔绝和无力先说出来', '有些低落像一只看不见的黑狗：世界变暗，关心听不进去，想说又怕被评价，越沉默越孤立。App 不必急着劝用户“振作”，可以先帮 TA 命名体验：你正在被沉重感包围，难以回应别人并不等于不在乎。下一步只需要找一个能承接的人，说出“我最近撑得很辛苦”，让孤岛先打开一道缝。', '["低落体验", "情绪命名", "孤立感", "表达困难", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1266, now()),
(101267, '支持系统不是麻烦别人，而是给恢复留出口', '深陷低落时，人常觉得“我不该麻烦任何人”，但长期独自承受会让想法更封闭。可把支持系统分成三层：一位可信亲友负责倾听和陪伴；互助小组或社区提供同路人的理解；医生、心理咨询师或员工援助计划提供专业资源。App 可引导用户先填一个“今天能联系的人”，而不是一次性公开所有处境。', '["支持系统", "亲友支持", "互助小组", "社区资源", "员工援助", "减少孤立"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1267, now()),
(101268, '陪伴者怎么说：少评判，多确认，多给具体帮助', '陪伴低落的人，最怕把关心说成责备：如“你想太多”“你就是不努力”。更合适的表达是：我可能还不完全懂，但我愿意了解；你不用一个人扛；今天我可以陪你散步、预约、吃饭或只是待一会儿。不要急着给大道理，先确认痛苦真实存在，再给一个可执行的小支持，这比催促更安全。', '["陪伴者", "避免责备", "有效沟通", "亲友支持", "共情", "具体帮助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1268, now()),
(101269, '求助信号：看功能变化，而不是给自己贴标签', 'App 端不应替用户做诊断，但可以提醒观察求助信号：连续低落或失去兴趣，睡眠和食欲明显改变，精力下降，注意力变差，强烈无价值感，家庭、工作或学习功能受影响，或出现伤害自己的念头。重点不是“我是不是某种病”，而是“这些变化已经让我独自处理很困难，需要找可信的人和专业资源一起评估”。', '["求助信号", "功能变化", "睡眠食欲", "无价值感", "非诊断", "专业评估"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1269, now()),
(101270, '危机念头需要被听见：及时联系真人支持', '如果用户表达“不想活了”、强烈绝望或担心自己会伤害自己，App 应把重点放在即时安全和真人连接上：鼓励立刻联系身边可信的人、当地急救/危机热线或专业人员，并尽量不要独处。询问这类念头本身不会把风险“问出来”；对许多人来说，能把可怕想法说给专业人士听，反而是一种卸压和保护。', '["危机求助", "自伤风险", "真人支持", "危机热线", "及时求助", "安全计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1270, now()),
(101271, '复发预防：把个人警示信号写成提前清单', '复发预防不只是“好了以后再说”，而是平时就记录自己的早期信号。有人会先出现起床困难、睡眠需求变多或变乱；有人会饮食改变、停止锻炼、对平常小事异常情绪化，或重新出现危险念头。App 可以做成个人化清单：信号出现时先减负、联系支持者、恢复基础节律，并把危险念头设为立即求助触发项。', '["复发预防", "警示信号", "自我监测", "睡眠变化", "饮食变化", "及时求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1271, now()),
(101272, '生活节律是情绪地基：先稳住睡眠、光照和日常', '睡眠—觉醒、光照、进食、活动和社交节奏会影响情绪、注意力、食欲和精力。对 App 来说，比灌输复杂理论更有用的是帮用户守住基础节律：固定起床时间，白天接触自然光，安排轻量活动，减少熬夜和过度透支。它不承诺“这样就会好”，但能作为复发预防和日常稳定的底盘。', '["生活节律", "睡眠", "光照", "日常稳定", "复发预防", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1272, now()),
(101273, '小步行动：不要规划余生，只规划下一周', '低落时，大脑常把未来想成一整座山。更适合的做法是只看下一周：每天安排一件体力活动、一段与喜欢的人连接的时间、一件有意义的小事和一点休闲。如果状态很差，“穿上鞋到户外待几分钟”也算完成。App 要鼓励庆祝微小进展；没完成时不责骂，只调整为明天更小的一步。', '["小步行动", "一周计划", "行为激活", "微目标", "自我鼓励", "避免自责"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1273, now()),
(101274, '运动不必很猛：先选能长期坚持的轻量活动', '对低落用户，运动建议最容易变成新的压力。更温和的设计是：先问“哪种活动最不讨厌、最容易开始”，比如散步、游泳、骑车或和朋友一起走一段。目标应从现实状态出发，10—15 分钟也可以。重点不是表现好不好，而是让身体重新获得一点节奏、自然接触和掌控感。', '["轻量运动", "散步", "掌控感", "自然接触", "低门槛行动", "长期坚持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1274, now()),
(101275, '工作/学习效率下降：先当健康信号，不当道德失败', '低落会影响注意力、信心、社交和任务完成，表现成迟缓、退缩、效率下降。旁人容易误读为“不尽责”，用户也会因此更自责。App 可以提示：这可能是身心系统超载的信号，先减少自我攻击，再考虑是否向可信同事、老师、管理者、HR 或员工援助计划寻求保密支持，并把任务拆到可完成的最小单位。', '["工作压力", "效率下降", "假性出勤", "保密支持", "任务拆分", "避免污名"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1275, now()),
(101276, '求医前准备：把混乱感整理成可沟通的信息', '当决定寻求专业帮助时，用户可以先准备一页简表：出现了哪些变化，持续多久，对家庭、学习或工作影响多大，可能诱因是什么，现在有哪些情感支持，是否用酒精或其他方式麻痹痛苦，是否出现危险念头。也可以请可信亲友陪同，帮助记录医生建议。这样能把“我很糟”转成医生更容易评估的线索。', '["专业求助", "就诊准备", "信息整理", "亲友陪同", "风险沟通", "治疗团队"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1276, now()),
(101277, '反刍时退一步：把“解释”从“事实”里分出来', '低落会让人反复追问“为什么是我”，并把朋友没回消息、一次失误或身体疲惫解释成“我不重要、我没救了”。App 可引导用户写下事件—想法—感受—行动冲动：发生了什么？我脑中自动冒出的解释是什么？还有没有其他可能？然后选一个小行动，如发一条澄清消息、休息十分钟或联系支持者，打断越想越沉的循环。', '["思维反刍", "自动想法", "事实解释分离", "情绪记录", "小行动", "认知校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1277, now()),
(101278, '“量度差”：同一件事在两边不是同一件事', '书中反复提醒，伤害在两边的重量不同：做出行为的人常把它当成一次插曲，承受一方却可能把它视为改变信任和安全感的关键事件。关系修复不能只问“我当时是不是故意”，还要问“这件事对对方造成了什么持续影响”。App 端可把它转化为冲突复盘问题：先分别写下意图、实际影响、残留感受，再讨论补救。', '["冲突复盘", "受害者视角", "施害者叙事", "量度差", "关系修复", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1278, now()),
(101279, '当施害者把自己也讲成受害者', '很多冲突中，施害者会把叙事中心移到“我也被逼、被冒犯、被误解”。这可能包含部分真实处境，但不能自动抵消他对他人造成的伤害。更稳妥的区分是：原因可以解释行为怎样发生，责任用来决定怎样修复和防止再发生。关系或团队复盘时，允许每个人说出压力源，但不允许用受害感跳过道歉、边界和补偿。', '["责任边界", "受害者角色", "关系修复", "非暴力沟通", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1279, now()),
(101280, '别让“纯粹恶”标签吞掉事实', '“纯粹恶”的叙事让冲突变得简单：我方无辜，对方邪恶，所有痛苦都由对方造成。它能快速凝聚情绪，却会削弱事实核对和共情，尤其容易把普通分歧升级成群体敌意。降温时要把“坏人”翻译成可核对的具体行为、具体影响和具体请求；只评价行为，不把对方整个人或整个群体判成不可沟通。', '["标签化", "群体敌意", "事实核对", "冲突降级", "反去人性化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1280, now()),
(101281, '冲突升级常从小刺激开始', '冲突升级往往不是突然爆发，而是从玩笑、讽刺、否认、推责、当众羞辱等小刺激逐步叠加。每一步当事人都可能觉得自己只是回应上一轮不公，旁观者却能看到强度在上升。适合 App 的提醒是：一旦谈话出现重复指责、提高音量、翻旧账或观众站队，就先暂停议题，转入冷却和复述规则，避免继续“加码”。', '["冲突升级", "关系降温", "团队沟通", "暂停机制", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1281, now()),
(101282, '报复螺旋：双方都觉得自己只是扯平', '报复的陷阱在于，受害一方通常会把自己的回击看成“刚好扯平”，而对方感受到的却是新的过度伤害，于是下一轮又要加倍讨回。螺旋真正追求的不是解决问题，而是让对方“尝到痛苦”。关系修复应把目标从报复改成止损：承认影响、真诚道歉、明确不再重复、约定第三方或规则介入，减少凭情绪自行结算。', '["报复螺旋", "冲突降级", "道歉", "止损", "关系修复", "反暴力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1282, now()),
(101283, '自尊受威胁时，先保护对话而不是面子', '书中把许多攻击性反应连接到“自尊被威胁”：一个人越需要维持高而脆弱的自我形象，越容易把普通不同意理解成羞辱。关系沟通里，可以先识别被触动的是事实、面子还是身份感。回应时少用“你就是不行”，多用“这件事没有达到约定标准”。给对方面子不是纵容，而是把谈话留在问题层，避免把人推入防御性反击。', '["自尊威胁", "面子冲突", "沟通降级", "防御反应", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1283, now()),
(101284, '理想主义也需要刹车', '理想主义本来能约束人，但当一个人坚信自己代表绝对正义时，它也可能反过来授权伤害：对手被看成正义的敌人，手段就容易被目标美化。团队和亲密关系里，同样要警惕“我是为你好”“为了大局所以你必须忍”。健康的理想要接受手段审查：若实现目标的方式正在摧毁尊严、选择和信任，就需要停下来重设边界。', '["理想主义伤害", "目标与手段", "边界感", "团队伦理", "反操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1284, now()),
(101285, '去人性化语言会削弱同情', '去人性化常先发生在语言里：把人说成异类、麻烦、障碍、废物，或用漂亮的抽象词掩盖具体伤害。语言一旦让对方不像一个会痛、会怕、会需要解释的人，同情和内疚就会下降。降温实践是改用朴素、人化、可负责的表达：谁做了什么、谁受到什么影响、我们准备怎样修复。越直白，越不容易让伤害藏进口号。', '["去人性化", "语言觉察", "同情心", "冲突降级", "责任表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1285, now()),
(101286, '权力欲会把关系变成控制游戏', '权力并不必然有害，健康权力可以保护、组织资源、推动事情发生；危险在于有人通过制造恐惧、羞辱或不可预测来证明“我能影响你”。在关系和团队中，若某人总让他人猜脸色、怕犯错、为安全感让步，冲突就已进入控制模式。降温要把权力拉回制度：明确权限、透明决策、允许申诉，让影响力服务目标而不是支配他人。', '["权力与支配", "控制关系", "团队治理", "心理安全", "反操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1286, now()),
(101287, '群体中要给个人疑虑留出口', '群体比个人更容易把责任切碎：有人只提建议，有人只执行流程，有人只保持沉默，于是没有人觉得自己需要负责。组织还会把忠诚误认为不质疑，使成员私下不安却公开附和。团队知识库可提炼为三条保护线：重大决定必须有具名责任人；会议必须记录反对意见；任何人可用安全词暂停高风险行动，先审查影响。', '["群体责任", "责任分散", "团队安全", "反从众", "组织伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1287, now()),
(101288, '降温三件事：拉远视角、恢复选择、及时发声', '自制力失效时，人会陷入“此时此地”的狭窄视角，只盯着眼前情绪、输赢和操作细节，而忘记长期关系与价值原则。冲突降温可以用三步：先暂停并让身体降唤起；再把问题写成事实、感受、请求三栏；最后请旁观者或权威及时发声，避免沉默被理解成默认。降温不是退让，而是恢复选择能力。', '["关系降温", "自我控制", "旁观者责任", "情绪调节", "冲突复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1288, now()),
(101289, '先问“已经有什么”：把匮乏感改成资源地图', '遇到卡住，先别把自己放在“我缺钱、缺人、缺时间”的框里。变通思维提醒我们观察情境里已经在运作的系统：谁在流动信息，谁有稳定网络，哪些人事物被视为背景却能承载新用途。App 可引导用户列出3类现成资源，再设计一个借力的小实验。重点是让已有系统更协调，而不是凭空造一套新方案。', '["变通思维", "资源盘点", "认知换框", "心理弹性", "小实验", "搭便车"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1289, now()),
(101290, '找共生关系：让别人的路径顺带服务你的目标', '“搭便车”不是占便宜，而是寻找彼此目标可以短暂重叠的地方。职场协作、亲子安排或关系修复中，先问：谁已经在走一条相近的路？我能提供什么，让对方原本的路径也更顺？当方案从“求对方帮我”变成“让双方的系统都更顺”，阻力会下降。App 可做成“对方目标—我的目标—可交换价值”的三列表。', '["共生关系", "借力", "合作设计", "职场沟通", "关系修复", "认知灵活性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1290, now()),
(101291, '规则先拆开：在限制中找可重新解释的空隙', '面对规则，不必只剩“服从”或“硬碰硬”。更灵活的做法是把规则拆成：它限制谁、在哪些场景适用、是否有另一套更合适的规则、执行条件是否真的成立。这样做不是投机，而是在价值目标清楚时寻找低风险路径。App 可引导用户把“我不能”改写成“这条限制具体限制了什么”。', '["规则拆解", "限制重释", "低风险行动", "价值目标", "钻漏洞", "换框架"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1291, now()),
(101292, '钻漏洞前先问价值：谁受益，谁承担代价', '漏洞本身没有自动的道德颜色，同一种技巧可能保护弱者，也可能转嫁伤害。使用变通前，先做价值澄清：我想守住什么？这个方案让谁获得机会？会把风险推给谁？是否有更少伤害的替代？App 适合把“可行性”与“受益/受损清单”并排呈现，避免把聪明误当正当。', '["价值澄清", "道德校准", "风险转嫁", "受益受损", "变通边界", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1292, now()),
(101293, '迂回侧进：先让恶性循环慢下来', '有些问题靠正面劝说无效，因为它们由自我强化循环维持：越争吵越想证明自己，越拖延越害怕开始，越责备越隐藏错误。迂回侧进的重点不是一次解决根因，而是插入一个能改变流向的小动作，例如暂停、换场景、改提醒、延后回应。先让循环降速，才有余地谈长期改变。', '["迂回侧进", "恶性循环", "暂停反应", "情绪调节", "关系冲突", "心理弹性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1293, now()),
(101294, '权宜之计不是失败：它为重要目标争取时间', '临时方案常被嫌“不彻底”，但复杂处境里，争取时间本身就是价值。疫情中的社交距离无法消灭病毒，却能减少伤害、等待医疗资源；关系冲突中，暂时分开也不等于放弃，而是给双方恢复理智。App 可提醒用户区分“临时止损”和“最终答案”，把权宜措施设定为有期限的试验。', '["权宜之计", "止损", "时间窗口", "关系修复", "试验期限", "认知灵活性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1294, now()),
(101295, '退而求其次：用手边资源先完成眼前目标', '当理想方案太慢、太贵或权限不够时，次佳方案能把人从停滞中救出来。关键是把手边资源重新命名：香水设备也能生产洗手液，咖啡机也可能解决午餐问题。App 可引导用户写下“目标是什么、我现在有什么、它还能怎么用”。这不是降低标准，而是在限制里先恢复行动。', '["退而求其次", "资源重组", "行动感", "替代方案", "职场应变", "小实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1295, now()),
(101296, '亲子和教育中的变通：不只盯着标准教室', '亲子教育常被单一路径绑住：成绩、教材、课堂、权威答案。书中教育案例提醒我们，学习也可以从日常活动、社区经验和孩子主动提问中发生。家长卡住时，可先问：孩子真正需要练习的能力是什么？除了正式课程，还有哪些生活场景能承载？App 可设计“能力目标—生活替代场景—一次尝试”的练习。', '["亲子教育", "替代路径", "日常学习", "能力目标", "家庭沟通", "变通思维"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1296, now()),
(101297, '让熟悉变新奇：换镜头看同一个问题', '熟悉会让人麻木，越懂一个场景，越容易只看见惯常解法。变通心性要求我们像调相机一样换焦距：近看细节、远看网络、换角度看资源和规则。App 可在用户反复抱怨同一问题时，提供三个换镜头问题：如果我是新手会问什么？如果只看关系会看到什么？如果只做一步会做什么？', '["换镜头", "认知灵活性", "熟悉变新奇", "问题重构", "反惯性", "自我提问"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1297, now()),
(101298, '请一个局外人看盲点：新手可能看见旧系统的裂缝', '专家熟悉流程，也容易被流程驯化；局外人缺少经验，却能提出“为什么一定要这样”的问题。职场、伴侣或亲子难题中，可刻意找一个不在局内的人复述现状，让他指出哪里显得奇怪、浪费或过度默认。App 可做成“局外人提问卡”，帮助用户从身份和惯例里松动出来。', '["局外人视角", "盲点发现", "新手问题", "职场复盘", "关系卡点", "认知松动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1298, now()),
(101299, '少怪一个人，多看他遵守了哪套游戏规则', '关系冲突里，我们很容易把问题归咎于某个人不懂事、不努力或故意作对。变通视角会问：他可能在遵守哪套未明说的规则？家庭里的面子、职场里的考核、同伴里的忠诚，都可能让行为看似固执。先看规则，不等于替伤害开脱，而是让下一步从指责转向改变情境，找到更可改动的节点。', '["关系冲突", "游戏规则", "减少指责", "系统视角", "家庭沟通", "职场关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1299, now()),
(101300, '别追最终目的地：把变通做成连续小实验', '复杂问题很难预先找到终局答案。更可行的是像拼乐高一样先搭一个能动的结构，试试看，再根据反馈调整。完美主义会把人困在列清单、找全信息和等待条件成熟里；变通要求亲手试验，让一次尝试带出新问题、新资源和下一次机会。App 可用“本周一个变通实验”承接。', '["连续实验", "完美主义", "反馈调整", "行动学习", "心理弹性", "变通练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1300, now()),
(101301, '稳定的层级边界，能减少团队里的无谓攻击', '雄性大象围绕水源形成等级，并不只是“谁更凶”，也有减少稀缺资源冲突的功能。对团队问答来说，这条可转译为：当角色、决策权、资源分配和申诉路径模糊时，成员会用试探、站队或抢话来确认位置。先把边界和规则说清，再谈合作，往往比单纯要求大家“别内耗”更有效。', '["群体层级", "团队安全感", "角色边界", "资源竞争", "冲突降低"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1301, now()),
(101302, '地位不等于领导力：追随来自可预期的照顾', '书中区分了“站在顶端”和“能带队”。占优势者若只用惩罚、抢占和威胁，短期能压住局面，却很难得到稳定追随；当它能照顾支持者、降低攻击、发出可理解的行动信号，群体才更愿意跟随。App 可提醒管理者、父母或资深者：真正的权威不是让别人怕你，而是让别人跟着你更安全、更有路。', '["领导力", "地位", "追随", "团队安全感", "影响力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1302, now()),
(101303, '资源越稀缺，越要少用“性格差”解释冲突', '在干旱环境里，大象被迫频繁聚集在同一水坑，资源压力会放大等级、联盟和冲突。人的团队也类似：预算、晋升、曝光、时间和照护资源紧张时，很多“难相处”其实是位置焦虑和规则压力的外显。回答用户时，可先问：争执背后在抢什么资源？规则是否透明？有没有替代方案？', '["资源竞争", "地位焦虑", "结构视角", "团队冲突", "非性格化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1303, now()),
(101304, '联盟不只是小圈子，也可能是在寻找安全和筹码', '大象联盟通过问候、触碰、共同行动和站位被维持；有时联盟保护成员，有时也改变等级格局。放到职场或关系里，“小团体”未必都源于恶意，可能是在不确定处境中寻找安全、信息和谈判筹码。App 可引导用户少急着贴标签，先看联盟满足了什么需要，以及正式沟通渠道是否失灵。', '["合作联盟", "小团体", "团队安全感", "地位变化", "沟通渠道"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1304, now()),
(101305, '年轻成员需要导师和同伴规则，而不只是被处罚', '年轻雄性大象的冲动并非单纯“天生坏脾气”，激素状态、导师是否在场、能否获得跨年龄互动，都会影响其行为。用于新人、青春期孩子或团队新成员时，可提醒：纪律之后还要有示范、稳定反馈和安全练习场。没有导师的环境，容易把试探边界变成反复惹事；比起只抓错误，更要让他知道怎样算合适。', '["导师关系", "新人融入", "跨年龄支持", "行为边界", "团队成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1305, now()),
(101306, '把“我为什么这样选”放进结构—状况—选择里看', '《当代中国的阶层结构分析》提示，社会位置会影响一个人的资源、约束、生活机会和生活选择。App 在处理成长、择业或亲密选择时，可少问一句“你怎么这么没用”，多问几句：你拥有多少时间、钱、信息、学历、支持和决定权？哪些选项真实可达？这样既保留个人行动，也减少不必要的羞耻。', '["社会位置", "选择", "生活机会", "结构视角", "自责松动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1306, now()),
(101307, '职场安全感常常来自权威位置和工作自主性', '同样在一个组织里，是否能管理他人、参与决策、拥有监督权和工作自主性，会影响收入、晋升、保障、满意度和生活方式。团队问答可把“为什么他总焦虑/防御”拆成位置问题：谁有决定权，谁承担后果，谁能解释规则，谁能拒绝不合理要求。安全感不是口号，也来自可见的权责结构。', '["组织权威", "工作自主性", "职场关系", "安全感", "权责结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1307, now()),
(101308, '关系里的不平等，常是互动位置而非单个人品', '阶层分析强调，不平等不是简单的高低排名，而是人们在雇佣、权威、资源和交换关系中的相对位置。放到团队和亲密关系里，反复冲突也未必是某个人“坏”，可能是信息、钱、照护、评价权长期不对称。App 可引导用户同时看人和结构：行为要负责，位置压力也要被看见。', '["关系不平等", "互动位置", "权力关系", "非性格化", "关系责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1308, now()),
(101309, '公平感比差距本身更容易触发冲突感', '书中关于“公平感”和“冲突感”的分析说明，人们并非不能接受所有差异，更在意差异是否有可信理由、程序是否公正、所得是否与贡献相称。团队里同样如此：奖金、机会、表扬和惩罚可以不同，但标准要清楚、解释要充分、申诉要可达。否则差距会被体验成羞辱和排斥。', '["公平感", "冲突感", "分配规则", "团队信任", "地位焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1309, now()),
(101310, '让受影响的人参与规则，能降低被支配感', '书末谈到协调分化关系时，强调公开、参与和平衡。转译到 App 的团队与关系建议：当规则影响某些人，却不让他们表达经验和成本，他们更容易感到被摆布。制定排班、分工、家庭开支或团队制度时，给受影响者解释权、反馈权和修订入口，往往比事后安抚更能减少对立。', '["参与感", "规则制定", "被支配感", "团队协作", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1310, now()),
(101311, '行为观察先问“发生了什么”，再谈“代表什么”', '人际困扰里最容易跳过的一步，是还没描述清楚事实，就急着给对方贴标签。可先把问题写成可观察句：谁在什么场景做了什么、持续多久、带来什么结果；再另起一栏写自己的解释与感受。这样能把“他就是不在乎”“孩子就是叛逆”“同事就是针对我”改成可验证线索，减少读心和道德审判。', '["行为观察", "事实解释分离", "非标签化", "关系沟通", "可验证假设", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1311, now()),
(101312, '把结论写成铅笔稿：每个判断都能被新信息修正', '观察他人和复盘自己时，最好把结论当成铅笔稿，而不是一次写死的身份判决。一个假设可以暂时帮助行动，但当新行为、新反馈、新情境出现时，就要允许擦掉重写。App 端可提示用户使用“目前看来”“我暂时猜测”“还需要验证”的语言，把确定化叙事改成可更新模型，避免为了维护旧看法而筛选证据。', '["假设思维", "证据更新", "认知灵活性", "避免绝对化", "观察方法", "自我复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1312, now()),
(101313, '实地报告不是日记：记录行为、意图、结果和偏差', '普通日记常把情绪写得很满，却不一定能帮助行动改变。更有用的实地报告像一次事后复盘：我当时想达成什么、实际做了什么、对方或环境怎样回应、哪里有效、哪里失效、下一次要改哪个变量。它不服务于证明自己有理，而是把阅读、思考和真实行动连接起来，让经验变成可复用的学习材料。', '["实地报告", "行动复盘", "行为改变", "反馈学习", "记录练习", "OODA"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1313, now()),
(101314, '趁记忆还没改写，先留下事实版复盘', '冲突结束后，大脑会按情绪强度和自我保护重新整理记忆：有些细节被放大，有些被省略，故事会越来越像自己熟悉的版本。复盘最好分两步：先在事件新鲜时写下时间线、原话、动作和结果；隔一段时间再回看，检查哪里是在替自己辩护、哪里漏掉了关键背景。写下来不是为了定罪，而是防止记忆替现实改稿。', '["事实记录", "记忆偏差", "复盘练习", "冲突复盘", "自我观察", "证据意识"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1314, now()),
(101315, 'OODA循环：从清楚描述问题开始校准行动', '很多问题卡住，不是因为缺少建议，而是因为问题本身还没被看清。可以把 OODA 用成日常卡片：观察——我能明确描述的事实是什么；调整——这些事实适合用哪个解释框架；决定——我要尝试哪一个小行动；行动——执行后记录反馈。下一轮继续问：它让我离目标更近、变远，还是偏航？这能把焦虑转成迭代。', '["OODA", "问题澄清", "行动校准", "反馈回路", "决策练习", "成长工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1315, now()),
(101316, '复盘时让“我”回到主角：少猜动机，多看可控行动', '写关系复盘时，如果整篇都在写“他怎么想、她为什么这样、他们应该怎样”，就很难找到自己能改变的部分。更有效的写法是把“我”放回主角：我观察到了什么，我当时怎样解释，我做了什么，我回避了什么，我下一次能试验什么。这样不是否认他人的责任，而是把注意力从读心和指责转向可行动的选择。', '["责任边界", "可控行动", "动机区分", "关系复盘", "避免读心", "自我负责"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1316, now()),
(101317, '把模糊责备翻译成具体请求', '“你从来不帮忙”“你总是不听我说”这类话容易把沟通推向辩解。可以先把它翻译成具体、可观察的请求：你希望我做哪一件事、在什么时间、做到什么程度？如果对方只是情绪宣泄，也能被温和看见；如果确有现实问题，就能进入协商。亲子和团队沟通也一样，少用人格评价，多问下一次可被看见的行为。', '["具体请求", "行为描述", "亲子沟通", "团队沟通", "冲突降温", "非暴力沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1317, now()),
(101318, '强烈情绪不是失败：承认感受，但不放弃事实和边界', '关系里的强烈情绪常让人误以为“必须立刻让对方平静下来”。更稳的方向是：先承认对方确实有感受，再回到事实、任务和边界。比如“我理解你现在很生气，我们可以十分钟后继续谈具体安排”。承认感受不等于同意所有指责，也不是压制对方；它让沟通从情绪洪水回到可讨论的下一步。', '["情绪承认", "边界沟通", "关系沟通", "冲突降温", "事实核对", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1318, now()),
(101319, '责任要有边界：同时看个人行动和环境约束', '把所有问题都归到自己不够努力，会让人看不见真正的变量；把责任都推给外界，又会失去行动空间。复盘时可以分三栏：我能直接改变的行为、需要协商或适应的环境、暂时只能放下的限制。这样的责任划分适合伴侣、家庭和团队问题：既不把自己塑造成唯一罪人，也不把他人当成唯一原因。', '["责任边界", "环境因素", "可控不可控", "系统视角", "行动选择", "复盘练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1319, now()),
(101320, '从单个故事到重复模式：用收敛证据提高判断可靠度', '一个案例只能提供线索，不能直接变成规则。更可靠的观察，是把多个低置信度证据放在一起：不同场景是否出现相似触发、相似反应、相似后果？如果重复模式越来越清楚，就可以提高假设置信度；如果只有一次偶发，就先保留疑问。App 可引导用户用“模式次数、场景差异、反例”来避免凭一次冲突定义一个人。', '["模式识别", "收敛证据", "证据意识", "避免标签化", "观察方法", "判断校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1320, now()),
(101321, '家庭和团队规则要写成可看见的行为', '规则若只写成“要尊重”“要负责”，执行时很容易变成批评人格。更可用的表达是可观察行为：开会时不打断别人；孩子面前不互相吼叫；任务变更需提前说明；情绪过载时先暂停再回来谈。规则越具体，越少需要羞辱和辩解。亲子或团队复盘时，可以问：这条规则下次能被摄像头拍到什么？', '["行为规则", "亲子沟通", "团队协作", "边界表达", "可观察行为", "冲突预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1321, now()),
(101322, '把“都是我的问题”改写成“我在什么情境里反应”', '当一个人陷入关系、工作或自我评价困境时，社会学视角提醒我们：不要只把结果归结为性格缺陷或意志力不足。先看自己所在的家庭、职场、阶层位置、性别期待、教育经历和当下制度，如何给出了可选项、奖励与惩罚。这样做不是推卸责任，而是把“我怎么了”扩展为“我在怎样的环境中学会这样反应”，更容易找到可改变的边界。', '["社会学想象力", "自责松动", "情境视角", "个人选择", "结构影响", "心理成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1322, now()),
(101323, '选择常常带着社会化痕迹', '我们以为亲密选择、审美和价值观完全出自“我喜欢”，但偏好常常来自日常社会化：谁被认为可靠、体面、有吸引力，往往与语言、教育、职业、宗教、阶层等背景相连。理解这一点，可以减少“我为什么总是这样选”的羞耻感，也能帮助你区分：哪些偏好是真实需要，哪些只是长期环境教给你的默认答案。', '["社会化", "亲密选择", "价值观", "择偶模式", "羞耻感", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1323, now()),
(101324, '角色期待：关系里的很多冲突不是谁坏，而是谁在演什么', '家庭和职场关系并不只是两个个体相遇，还带着“母亲、伴侣、子女、上司、员工、朋友”等角色剧本。冲突有时来自双方对同一角色的期待不同：有人期待照顾，有人期待平等；有人把沉默当体贴，有人把它当疏离。把问题说成“我们对这个角色的脚本不一样”，比直接指责人格更容易开启沟通。', '["角色期待", "关系沟通", "家庭关系", "职场关系", "冲突理解", "群体规范"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1324, now()),
(101325, '规范不是束缚的反义词，也可能是安全感来源', '人的可能性很大，能选择的路太多，反而容易焦虑。共享规则、习惯和仪式会把无限选择缩小到可处理范围：几点下班、怎样表达礼貌、关系里哪些事需要回应。成长不是简单摆脱所有规范，而是辨认哪些规范在保护你，哪些规范已不适合你，再有意识地调整它们，让安全感从僵硬服从转向可选择的秩序。', '["安全感", "社会规范", "选择焦虑", "习惯", "边界感", "自我调整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1325, now()),
(101326, '社交比较与相对剥夺：痛苦不只来自“我少”', '很多不满足并非因为客观上“一无所有”，而是因为身处一种鼓励人人追求成功、又让机会分布不均的环境。看到同龄人、同事或同学获得认可时，人会自然比较“为什么不是我”。这类痛苦可以被理解为相对剥夺感：它需要被看见，但也需要重新设定参照对象和个人节奏，而不是直接等同于失败。', '["社交比较", "相对剥夺", "成功焦虑", "同伴压力", "自我评价", "机会分布"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1326, now()),
(101327, '向上空间变大，不等于每个人的机会一样', '当社会或行业扩张时，很多人确实获得了更好的职位和生活条件；但这不代表起点差异消失。一个人的努力很重要，同时也受“目标位置有多少”“家庭和教育资源如何分布”“规则是否偏向既有优势者”等因素影响。把发展迟缓全归咎于自己，容易忽略结构条件；把结构当成全部，又会丢掉可行动部分。', '["阶层流动", "机会差异", "职业发展", "自我归因", "教育资源", "现实评估"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1327, now()),
(101328, '标签会改变一个人如何理解自己', '同一个行为或状态，在不同情境中可能被称为“敏感”“不合群”“认真”“需要帮助”或“有问题”。标签不是单纯描述，它会影响他人如何对待你，也影响你如何解释自己。心理成长中可以练习追问：这个标签是谁给的？它服务于什么关系或制度？它帮助我理解和行动，还是让我更窄地看自己？', '["贴标签", "自我认同", "心理污名", "关系情境", "身份理解", "叙事重构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1328, now()),
(101329, '公域与私域：在不同场景切换不同自我', '现代生活要求人在公共领域遵守更通用的规则：排队、契约、绩效、流程；同时又鼓励人在私人领域表达偏好和亲密需要。很多疲惫来自两套规则的切换：工作中要克制、理性、可靠，回家后又被期待真诚、放松、有情绪。理解这种切换压力，有助于为自己设置过渡空间，也能减少对伴侣或家人的过度索取。', '["公私边界", "角色切换", "职场压力", "亲密关系", "情绪调节", "现代生活"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1329, now()),
(101330, '亲密关系承载的期待越高，压力也越大', '当家庭不再只是经济合作和身份安排，亲密关系就被期待提供陪伴、理解、疗愈、激情和自我实现。期待变高本身不是错，但如果把全部安全感都压在一个人或一段关系上，失望会被放大。更稳妥的做法是区分：哪些需要适合在关系中协商，哪些需要朋友、工作、兴趣、专业支持或自我照顾共同承担。', '["亲密关系", "安全感", "家庭功能", "情感期待", "关系压力", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1330, now()),
(101331, '参照群体会悄悄改变你的目标和标准', '人会把自己放进某个群体里理解“我应该怎样”：同事圈、同学圈、同龄父母、同城同行、网络社群都会成为参照。参照群体改变后，你对成功、体面、消费、亲密和自律的标准也会改变。若长期焦虑，可以检查：我正在用谁的尺子量自己？这个群体真的理解我的资源、处境和价值排序吗？', '["参照群体", "社交比较", "目标设定", "群体规范", "焦虑来源", "自我标准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1331, now()),
(101332, '关系不是无限义务：先分清“缘、情、伦”各自带来的期待', '书中把中国人际关系理解为人缘、人情、人伦交织的结构：相遇的机缘、情感与互惠、角色规范会同时作用。用于 App 时，可引导用户先问：我和对方的关系基础是什么？是亲近、职责、同事合作，还是临时求助？把关系说清楚，不是变冷漠，而是避免把所有熟人都自动变成无限责任。清楚位置后，才更容易既表达尊重，也说出自己能做与不能做的边界。', '["关系定位", "人情", "角色期待", "边界", "心理教育", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1332, now()),
(101333, '人情往来会形成互惠压力：善意需要范围和结束点', '人情不是一次等价交易，而常常带着“欠着、以后还”的连续性。接受帮助会带来感激，也可能带来长期亏欠感；主动帮忙若没有边界，也容易期待对方未来必须回报。App 端可提醒用户把善意具体化：我能帮到哪一步？多久？是否需要对方回馈？如果回馈不是必须，也可以明说。这样既保留温度，也减少人情债带来的压力、误会和隐性控制。', '["人情压力", "互惠", "边界", "亏欠感", "关系压力", "请求与拒绝"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1333, now()),
(101334, '合情合理的沟通：把感受、关系和原则放进同一句话', '书中所谓“情理社会”提示：很多冲突并不只是对错之争，还包含关系、处境和面子的感受。App 端不宜只教用户“拿规则压人”，也不应鼓励牺牲原则换和气。更适合的表达是：先承认关系和对方处境，再说出自己的限制与原则。例如“我理解你着急，也珍惜我们的关系；但这件事我不能替你决定，我可以陪你把选择列出来”。这能让真实表达不必等同于攻击。', '["情理沟通", "真实表达", "尊重", "边界", "冲突缓和", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1334, now()),
(101335, '面子不是自我价值：把“别人怎么看我”和“我怎么看自己”分开', '书中区分“脸”和“面子”：前者更接近个人形象与表现，后者更依赖他人在关系中的承认。一个人被冷落、被轻视、被当众否定时，痛感常来自“我在对方心里的位置下降了”。App 端可帮助用户把羞耻感拆开：这是否真的说明我没有价值，还是说明某段关系没有给我足够尊重？当自我价值不完全交给外界排序，人才更能稳定地表达需求。', '["面子", "自我价值", "羞耻感", "心理地位", "自尊", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1335, now()),
(101336, '留面子的拒绝：先承认关系，再说明限制，最后给出可承受的替代', '在重视面子的关系里，拒绝常被听成“不重视我”。因此，健康拒绝不是冷硬地切断，也不是勉强答应，而是把尊重和边界同时说出来。可以按三步表达：先确认对方的重要性或处境；再说明自己做不到的具体原因与范围；最后只在能力内给替代选项。比如“我知道这事对你重要，但我今晚无法加班；我可以明早帮你看第一版”。重点是拒绝请求，而不是否定关系。', '["拒绝练习", "留面子", "边界表达", "请求沟通", "尊重", "职场关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1336, now()),
(101337, '关系平衡压力：别人都做，不等于你必须照做', '书中用住院探望、送礼等例子说明，三人以上的同类关系里，人们会追求“大家差不多”的平衡标准。它能维持和谐，也会制造压力：别人送了我也要送，别人去了我也要去，否则怕显得不合群。App 端可引导用户辨认：这是我的真实意愿，还是害怕破坏平衡？如果必须参与，能否降低成本、明确限度？把群体标准看见后，才有机会做更自主的选择。', '["关系平衡", "从众压力", "人情压力", "团队关系", "边界", "自主动机"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1337, now()),
(101338, '强信任不等于真安全：亲近关系也需要事实验证', '书中讨论农民工求职时指出，熟人、亲属、老乡带来的信息更容易被相信，因为它有关系担保。但强信任并不保证信息一定真实，也可能出现“杀熟”。App 端可提醒用户：信任一个人和验证一件事并不冲突。涉及钱、工作、合作、借贷、照护等重要决定时，可以同时保留礼貌与核实：看凭证、问细节、找第三方确认、设小额试行。真正稳固的关系，经得起适度透明。', '["关系信任", "熟人关系", "事实验证", "边界", "风险识别", "合作沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1338, now()),
(101339, '权力距离中的表达：尊重位置，但不要让需求消失', '书中多处指出，中国式互动会迅速确认身份、辈分、资历和权威位置。面对长辈、领导或强势成员时，表达真实并不等于挑战权威；关键是把“人”和“事”分开。可以先承认对方角色，再聚焦具体影响：“我尊重您的经验，也想说明这个安排对我目前的工作量有影响”。这样既减少对方被冒犯的感觉，也帮助自己不在权力距离中完全沉默。', '["权力距离", "真实表达", "长幼关系", "职场沟通", "角色期待", "尊重"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1339, now()),
(101340, '家庭和团队里的“摆平”：公平不只是平均，也包括解释和安抚', '书中认为，关系中的“均”不只指物质平均，也包括被重视、被照顾、被公平说明。家庭分工、团队机会、父母偏心、领导资源分配，常让人受伤的不是少拿了一点，而是觉得自己被低估、被忽略。App 端可引导用户把“他们不公平”拆成三层：资源是否不均？情感是否偏向？规则是否没解释？表达时越具体，越可能从抱怨转向协商。', '["公平感", "家庭关系", "团队关系", "摆平", "情感需求", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1340, now()),
(101341, '个人地位焦虑：被重视的需求可以温和说出来', '书中提出“个人地位”概念，指一个人的社会重要性在交往中被他人承认的方式和程度。日常里，称呼、语气、座次、回复速度、是否被邀请，都可能被体验为“我算不算数”。App 端可帮助用户承认这种被重视的需要，同时不把它变成面子竞争。更成熟的说法是：“我希望这件事能提前和我沟通，因为我也承担了责任”，而不是用冷战或讽刺争位置。', '["个人地位", "被重视", "面子焦虑", "关系需求", "非暴力沟通", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1341, now()),
(101342, '形式化人情：仪式能表达心意，也可能遮住真实', '书中指出，人情在礼的牵引下容易形式化，变成“表示”和象征。请客、送礼、客套、节日问候能承载关心，但当它们取代真实感受时，关系会变成负担：做了怕不够，不做怕失礼。App 端可鼓励用户把仪式还原成可承受的心意：一句清楚的感谢、一次力所能及的帮助、一个不超预算的礼物，都比勉强维持排场更有利于长期关系。', '["礼尚往来", "形式化人情", "真诚表达", "关系负担", "边界", "家庭职场"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1342, now()),
(101343, '关系中的“撑腰”需求：先看安全感，再回到透明规则', '书中分析“权力的再生产”：关系可能让无权者感觉自己有了靠山，也可能让权力通过人情和面子扩散。用于关系成长时，不必鼓励借势压人，而应看见背后的安全感需求：我为什么需要别人撑腰？是害怕被忽视、被欺负，还是缺少正式渠道？更健康的方向是寻找可说明、可复盘、可共同遵守的规则与支持系统，让安全感不只依赖某个强势关系。', '["权力距离", "撑腰", "安全感", "透明规则", "关系边界", "组织沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1343, now()),
(101344, '关系契约的起点：先确认我们要共同保护什么', '在亲密关系、团队协作或社群共创中，规则不应只是约束某个人的工具，而要回答一个共同问题：我们想用彼此的力量保护什么？当承诺被说成“大家都要守、大家都因此更安全”，个体才更容易把规则看成自己的选择，而不是外来的压迫。App 可引导用户把争执从“谁赢谁输”转成“哪些底线能同时保护你我”。', '["公共承诺", "关系契约", "共同目标", "规则感", "安全边界", "协作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1344, now()),
(101345, '多数意见不等于真正共识', '一群人表面投票一致，未必真的形成共识；也可能只是小圈子压力、情绪感染或沉默服从。真正有质量的共同决定，需要每个人先以自己的经验和判断发声，再寻找能被共同利益连接的交集。App 在处理家庭会议、伴侣决策、团队冲突时，可提醒用户：先减少阵营化，再谈多数服从。', '["共识", "多数意见", "群体压力", "公共意志", "对话", "家庭沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1345, now()),
(101346, '好的边界必须同时约束双方', '边界不是“我要求你怎样”，而是“我们都同意什么条件下关系才安全”。如果一条规则只让一方付出、只保护另一方，它很快会变成控制或怨气。可用在关系协商中：把要求改写成对等条款，例如“争吵时不翻旧账”也意味着双方都有暂停、澄清和被倾听的权利。这样边界才不会变成单向服从。', '["边界", "对等", "规则协商", "关系安全", "权利义务", "冲突修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1346, now()),
(101347, '自由不是无约束，而是不被个人任意支配', '很多关系冲突把自由理解成“我想怎样就怎样”，结果强者更自由、弱者更沉默。更成熟的自由，是大家都受同一套清楚规则保护，不因某个人的脾气、地位或资源而随时被改变。App 可把自由与边界放在一起解释：稳定规则不是削弱自由，而是减少任意支配，让每个人知道自己可以怎样说“不”。', '["自由", "边界", "规则稳定", "不被支配", "平等", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1347, now()),
(101348, '规则要面向行为，不要变成针对某个人的判决', '当关系里出现问题，临时为某个人定制惩罚，往往会激化羞耻和对抗。更可持续的做法，是把规则写成可普遍适用的行为标准：什么行为可接受，什么行为需要修复，谁违反都按同一流程处理。这样既保留边界，也减少“你就是坏人”的身份攻击，也更方便事后复盘和修订规则。', '["规则感", "行为标准", "非标签化", "公平", "修复流程", "关系治理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1348, now()),
(101349, '价值分歧中，先拆开事实、预测和愿望', '许多争论之所以吵不清，是因为一句话里混合了事实判断、未来预测和价值偏好。对方未必“没有良心”，也可能是在不同信息、不同风险想象下得出结论。App 可引导用户复盘：我说的是已发生的事实、对未来的担心，还是我希望被重视的价值？拆开之后，才有真正对话的空间。', '["价值分歧", "事实判断", "对话", "意识形态", "沟通澄清", "批判思维"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1349, now()),
(101350, '不要把一个观点当成全部自我', '当一个人把观点、团体或立场等同于自尊，任何质疑都会被体验成背叛或攻击，于是他只能维护正确，无法继续学习。关系沟通中可把“我错了”改写为“我正在更新一个判断”，把身份从观点中松开。App 可提醒用户：你可以认真相信，也可以保留修正自己的空间。', '["信念刚性", "自我认同", "观点松动", "学习心态", "非防御", "自我成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1350, now()),
(101351, '宏大意义不能取消具体人的复杂处境', '一旦相信自己掌握了“最终意义”，就容易把现实中的人简化成先进或落后、支持或反对、正确或错误。个人关系中也会如此：为了证明某个大道理，我们可能忽略对方此刻的恐惧、利益和限制。App 可提示：先理解具体处境，再谈原则；原则若不能容纳人，就会变成审判。', '["宏大叙事", "具体处境", "理解他人", "价值判断", "避免审判", "同理心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1351, now()),
(101352, '警惕“事情一定会这样”的必然性幻觉', '在人际关系里，我们常把推测说成命运：TA 一定会离开、这个家永远不会变、我注定无法被理解。必然化会让人放弃尝试，也会把对方固定成角色。更有帮助的提问是：有哪些证据？是否存在替代路径？我能做一个多小的可逆实验？把确定性降下来，行动空间才会回来。', '["必然性幻觉", "关系复盘", "认知松动", "可逆实验", "希望感", "行动空间"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1352, now()),
(101353, '有理智的怀疑，是关系宽容的基础', '怀疑并不等于冷漠，也不等于没有价值。它是在热情之外保留一句“我可能还没看全”。当人不再把某种方案当作唯一拯救，就更能承认不同人的限制、节奏和选择。App 可把怀疑设计成温和练习：列出我相信的、我不确定的、我愿意继续观察的，帮助用户从狂热评判回到清醒关心。', '["怀疑主义", "宽容", "清醒关心", "价值弹性", "关系对话", "反狂热"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1353, now()),
(101354, '进化视角是动机雷达，不是“天生如此”的借口', '进化心理学适合用来观察“哪些需要被启动了”，不适合把人固定成天生标签。一个反应可能同时受到安全、资源、地位、亲密和文化学习影响。App 可把“我就是这样”改写为：这个情境触发了什么动机？我还有哪些可选择的回应？这样既承认人的生物性，也保留自我控制、学习和修复空间，不用本能替伤害辩护。', '["进化心理学", "动机观察", "反标签", "自我控制", "心理教育", "非宿命论"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1354, now()),
(101355, '恐惧的适应性偏差：身体报警要配合事实校准', '恐惧和焦虑可以被理解为安全雷达：它们帮助人更快注意高度、陌生环境、疾病线索或潜在威胁。但雷达会有误报，身体紧张并不自动等于现实危险。App 可引导用户分三步校准：我看到了哪些具体线索？危险概率和可控行动是什么？是否需要求助或离开？这样既不压抑警觉，也避免被恐惧牵着走。', '["恐惧", "焦虑", "风险识别", "环境线索", "事实校准", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1355, now()),
(101356, '环境线索会放大冲动：先降唤醒，再处理冲突', '冲动往往不是凭空出现，而是在高唤醒环境里被放大：拥挤、羞辱感、持续刺激、敌意暗示、围观和群体起哄都会让人更难慢下来。App 的建议应先做“降刺激”而非讲大道理：离开现场、减少观众、暂停输入、喝水呼吸、找可信第三方。等身体唤醒下降后，再讨论事实、责任和边界。', '["冲动控制", "环境线索", "冲突降级", "高唤醒", "反暴力", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1356, now()),
(101357, '地位竞争去标签化：把面子冲突翻译成规则问题', '很多冲突表面上是“谁更强”“谁更有面子”，底层可能是地位、尊重、资源或公平感被威胁。把对方贴成好斗、心机或自卑，容易继续升级。App 可提示用户把竞争语言翻译成规则语言：我们在争什么资源？评价标准是否透明？有没有共同目标和退出方式？把地位需求说清楚，才有机会从压制转为协商。', '["地位竞争", "关系安全", "去标签化", "公平感", "冲突沟通", "规则意识"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1357, now()),
(101358, '把嫉妒翻译成不安全感，而不是控制权', '嫉妒可以被看成关系警报：它提示承诺、信任、比较或失去感正在被触发。但警报不是授权，不能变成监控、隔离、羞辱或威胁。App 可引导用户先区分事实与想象，再表达可协商请求：我需要更多透明、确认还是边界？如果对方用嫉妒要求放弃社交、隐私或工作，应把它视为关系安全信号，及时寻求外部支持。', '["嫉妒", "关系安全", "边界感", "反控制", "亲密关系", "安全信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1358, now()),
(101359, '短期/长期关系动机：先澄清期待，再推进亲密', '亲密关系中的误伤常来自动机不清：有人寻找长期承诺，有人偏向短期探索，也有人自己尚未确定。进化视角能帮助观察不同策略背后的收益、代价和情境因素，但不能拿来道德化别人或合理化欺骗。App 可设置关系推进前的三问：双方期待是否一致？边界和同意是否明确？投入、风险和退出方式是否被说清楚？', '["亲密关系", "动机澄清", "同意教育", "边界感", "反操控", "关系决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1359, now()),
(101360, '合作不是盲目信任：互惠、声誉和退出权都要看', '合作能让人获得联盟与支持，但健康合作需要互惠、透明和可退出。若一段关系总让一方付出、催促保密、拒绝承担后果，或把拒绝说成背叛，就可能滑向操控。App 可把合作观察做成清单：投入是否大致对等？规则是否公开？拒绝后是否仍被尊重？有无第三方可求助？识别风险，是为了保护合作，而不是鼓励猜疑。', '["合作", "互惠", "反操控", "关系边界", "信任", "退出权"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1360, now()),
(101361, '亲属和照护也会有资源冲突：安全感要看权力不均衡', '血缘和照护关系常带来支持，也可能因为资源分配、依赖程度、代际期待和家庭角色产生压力。App 不应把家庭冲突简单解释为“不孝”或“冷血”，而应看具体权力结构：谁掌握钱、空间、信息和照护？谁没有拒绝权？谁被迫沉默？当关系里出现隔离、威胁或长期剥夺时，优先连接外部支持和安全资源。', '["家庭关系", "照护安全", "资源冲突", "权力不均衡", "关系安全", "反标签"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1361, now()),
(101362, '群体场景的冲动风险：匿名、围观、一致声浪要降温', '人在群体中更容易被规范、服从和情绪传染影响；匿名、拥挤、强一致声浪会削弱个人责任感，也可能让观点极化。App 可提示用户在群聊、团队和现场冲突中做三件事：给自己署名、延迟转发或表态、主动邀请反方证据。若有人被围攻，先减少围观和羞辱，再建立安全沟通渠道。', '["群体影响", "去个体化", "从众", "冲动控制", "责任感", "冲突降级"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1362, now()),
(101363, '重大判断别只靠第一印象：记忆和证词需要多源核验', '风险识别需要敏感，也需要谨慎。社会心理学提醒我们，目击、回忆和他人反馈可能被暗示、重复叙述和事后解释影响；第一印象也会被外貌、身份和情绪带偏。App 可建议用户把重大判断拆成事实、推测和感受三栏，保留时间线与可核对材料。若涉及现实安全，先保护自己，再用多源信息减少误判。', '["风险识别", "多源核验", "第一印象", "记忆偏差", "司法心理", "安全决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1363, now()),
(101364, '积极倾听：先让对方说完整，再用复述确认你听懂了', '在冲突或谈判中，急着解释会让对方更防御。更稳妥的做法是先听完，不抢话，用简短回应表示在听，再把对方的核心意思复述一遍：“我理解你担心的是……对吗？”这不是认同所有观点，而是先确认信息没有误读。App 可引导用户把“我要反驳什么”改成“我听到的事实、感受和需求分别是什么”，再决定回应。', '["积极倾听", "复述确认", "冲突沟通", "误解澄清", "情绪降温", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1364, now()),
(101365, '开放式提问：用“多说一点”替代逼问和审判感', '想核实情况时，问题越像审问，对方越容易紧张或防御。可先用开放式问题收集背景：“这件事从哪里开始的？”“你能按时间顺序说一遍吗？”不急着追问“为什么”，也不要在对方没说完时打断。等叙述结束后，再针对缺口补问时间、地点、人物、凭证。这样既保护沟通氛围，也更容易得到可核实的信息。', '["开放式提问", "事实核实", "澄清问题", "非暴力沟通", "避免审问感", "信息收集"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1365, now()),
(101366, '情绪很高时，先降压再谈事实', '人在恐惧、愤怒或羞耻中，很难立刻讲清事实。先从低敏感、容易回答的问题开始，让对方恢复安全感和基本秩序，再逐步进入关键问题。沟通中可说：“我先确认几件简单的事，等你准备好再讲细节。”这能避免把对方推向更强防御，也能提醒自己：情绪稳定不是浪费时间，而是事实核实的前置条件。', '["情绪降温", "压力识别", "安全感", "事实沟通", "创伤知情", "沟通节奏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1366, now()),
(101367, '发现矛盾时，先标记疑点，不急着下结论', '可疑之处不等于定罪，也不等于对方一定恶意。更安全的做法是把矛盾写成待核实问题：哪些说法与时间线、证据或常识不一致？哪些细节需要第三方材料支持？哪些只是自己的猜测？App 可引导用户用“我注意到这里前后不一致，能帮我补充一下吗”来澄清，而不是直接贴“骗人”的标签。', '["矛盾识别", "事实核实", "证据意识", "避免误判", "冷静判断", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1367, now()),
(101368, '承诺要有边界：不知道、无权限、没核实就不要答应', '沟通中一句随口的“可以”“没问题”，很容易被当成承诺。遇到自己不知道、没有权限或尚未核实的信息，应直接说明限制：“这点我现在不能确认，需要看资料/问负责人后再答复。”清楚表达不确定性，比为了讨好而打包票更可靠。App 可提醒用户把承诺改成条件句：在什么前提下、何时回复、能做到哪一步。', '["边界表达", "谨慎承诺", "不确定性", "职场沟通", "谈判安全", "责任清晰"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1368, now()),
(101369, '共同利益：把“谁赢谁输”改成“我们共同要解决什么”', '谈判僵住时，双方常盯着立场：价格、责任、面子、道歉。更有建设性的切入点是共同利益：双方都想减少损失、保住合作、避免误会、尽快恢复秩序。App 可引导用户先写出“我想要什么、对方可能想避免什么、我们共同不想发生什么”，再提出方案。共同利益不是讨好，而是把问题从对抗搬回解决。', '["共同利益", "谈判沟通", "冲突解决", "合作框架", "立场与需求", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1369, now()),
(101370, '说“不”是边界，不是攻击', '当对方要求你超出能力、原则或资源时，含糊拖延常会制造更大误会。可以用三步拒绝：先承认对方处境或信任，再明确说出不能做什么，最后给出可承受的替代方案。例如“我理解你着急，但这笔钱我不能借；我可以陪你一起列预算或找正规渠道。”清楚的“不”能减少纠缠，也保护双方关系。', '["拒绝技巧", "边界表达", "自我保护", "关系沟通", "替代方案", "避免纠缠"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1370, now()),
(101371, '面对投诉或指责，先感谢提醒，再查事实', '被指责时立刻辩解，容易把问题变成面子冲突。可先接住对方的信息：“谢谢你提醒，我会核实这件事。”随后把事实拆开：对方的具体主张是什么？是否有记录、账单、聊天、时间线支持？需要向谁确认？这种回应既不急着认错，也不急着反击，而是把情绪化的指责转成可处理的核查流程。', '["指责应对", "事实核查", "情绪降温", "客户沟通", "避免升级", "问题拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1371, now()),
(101372, '重大消息先降传播强度：多线索核实后再判断', '面对突发传闻、内部消息或高风险结论，先不要急着转发或下注。可以把信息拆成：来源是谁、是否有独立证据、是否存在反常信号、哪些点仍未确认、如果错了代价是什么。即使多个线索指向同一结论，也应保留“暂未证实”的标记。App 可提醒用户：越是刺激、稀缺、催促你立刻行动的信息，越要慢一步核实。', '["事实核查", "谣言识别", "信息来源", "避免被骗", "风险判断", "慢决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1372, now()),
(101373, '安全沟通环境：安静、低干扰、不过度施压', '沟通结果不仅取决于话术，也受环境影响。重要谈话应尽量选择安静、可坐下、少被手机打断的地点；如果对方明显紧张，可先说明谈话目的和时长，让对方知道不是被突然围攻。对自己也一样：不要在饥饿、疲惫、被催促或围观时做重大承诺。合适的环境能降低误解和冲动决定。', '["沟通环境", "压力管理", "重大谈话", "自我保护", "冲动决策", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1373, now()),
(101374, '用“4个圆”做身心自查：把情绪放回完整生活里理解', '当你感到疲惫、易怒、焦虑或脑子混乱时，不必急着把问题归咎于性格。可以从四个维度做自查：身体状态是否被睡眠、饮食、运动、激素、酒精或咖啡因影响；心理层面是否充满自责和灾难化想法；关系层面是否缺少支持或压力过载；意义层面是否仍知道自己为什么而努力。这个框架帮助用户把“我不行”改写为“我有哪些可调整的条件”。', '["大脑健康", "4个圆", "自我观察", "情绪管理", "压力管理", "身心整合", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1374, now()),
(101375, '提升“大脑储备”：日常习惯就是压力缓冲垫', '大脑储备可以理解为人在压力、变化和疲劳面前的缓冲能力。它不是固定资产，而会被长期睡眠不足、过度压力、酒精、低营养饮食、孤立和缺乏运动慢慢消耗；也会被规律作息、均衡饮食、学习新事物、运动、支持性关系和减少毒素暴露逐步补充。App 可引导用户每天选择一件“补储备”的小事，而不是等到崩溃后才修补自己。', '["大脑储备", "复原力", "习惯养成", "睡眠", "运动", "营养", "压力缓冲", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1375, now()),
(101376, '睡眠是情绪能量的底座：先保护夜间恢复', '睡眠不足会让注意力、记忆、判断和情绪稳定都变得更脆弱。书中多次强调，每晚尽量获得7—8小时睡眠；如果白天靠咖啡因硬撑、晚上靠酒精放松，身体可能进入“兴奋—醒来—更疲惫”的循环。App 建议可以从固定起床时间、下午减少咖啡因、睡前降低刺激、记录连续三天睡眠感受开始，温和找回恢复节律。', '["睡眠", "情绪能量", "注意力", "咖啡因", "酒精", "恢复力", "大脑健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1376, now()),
(101377, '健脑饮食不是节食：让血糖、肠道和情绪更稳定', '饮食的目标不是“少吃”，而是吃得更有质量。书中建议优先选择高品质热量、足量水、优质蛋白、低升糖且高纤维的碳水、健康脂肪和彩色天然食物，并减少高糖、高盐、加工食品和含热量饮品。对 App 用户来说，可把每餐理解为一次能量调节：让血糖更平稳，让肠道更舒服，也让情绪和专注力更少被食物波动牵着走。', '["营养", "血糖稳定", "肠道健康", "情绪稳定", "高纤维", "优质蛋白", "健康脂肪", "饮水"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1377, now()),
(101378, '运动用“适度且持续”打开脑血流和行动力', '运动不必一开始就很剧烈。书中给出的简明方向是：每周多次快走，配合适当力量训练，关键是持之以恒、不过度强迫。运动能促进血液循环，帮助身体利用能量，也常常让人更愿意继续选择健康饮食和睡眠。App 可把运动提示设计成“今天给大脑送氧了吗”，鼓励散步、快走、轻力量或瑜伽等安全、可坚持的形式。', '["运动", "快走", "力量训练", "脑血流", "行动力", "习惯养成", "压力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1378, now()),
(101379, '压力需要“修复动作”：深呼吸和冥想是日常维护', '压力不只是心理感受，也会带来身体层面的兴奋和消耗。书中区分了“没有新增压力”和“主动修复压力损伤”：回家瘫着不一定等于恢复，真正的修复可以是慢呼吸、短时冥想、放松训练、大笑、散步或识别错误想法。App 可提供一分钟版本：慢慢吸气、停顿、慢慢呼气，重复5—10次，让用户在情绪升高前先把身体降速。', '["压力管理", "深呼吸", "冥想", "放松训练", "皮质醇", "情绪调节", "身心恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1379, now()),
(101380, '自动消极想法不是事实：写下来、分类、再反驳', '当脑中出现“我总是失败”“没人理解我”“一定会出事”等念头时，可以先把它当作自动消极想法，而不是事实。书中建议三步：写下念头，识别它属于灾难化、读心、贴标签、责备等哪类，再用更准确的说法反驳它。App 可把这个练习做成情绪日记：我刚才相信了什么？证据是什么？如果不相信它，我会怎样行动？', '["自动消极想法", "认知重评", "情绪日记", "自我对话", "焦虑", "自信", "心理资源"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1380, now()),
(101381, '直觉可以当信号，不要直接当结论', '直觉、敏感和对气氛的觉察可以帮助一个人更快发现关系中的线索，但它们也容易被饥饿、睡眠不足、压力、疼痛或低血糖扭曲。更稳妥的做法是：先接住感觉，再问“证据是什么”“还有没有别的解释”。App 在关系场景中可提醒用户：我感到不安，不等于对方一定有敌意；先照顾身体状态，再做沟通和决定。', '["直觉", "自我观察", "关系沟通", "证据检查", "睡眠", "压力", "血糖", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1381, now()),
(101382, '共情也要有边界：照顾别人前先保留自己的能量', '共情和合作能带来亲密、支持和团队力量，但如果总把别人的问题背到自己身上，就容易出现照护疲劳、内疚和失控感。边界不是冷漠，而是区分“我能支持什么”和“对方需要自己承担什么”。App 可引导用户列出三栏：我愿意做的、我暂时做不到的、需要对方或第三方承担的，让关心不再等同于过度消耗。', '["共情", "边界", "照护疲劳", "自我照顾", "关系", "内疚", "心理资源", "能量管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1382, now()),
(101383, '支持团队是心理免疫力：别独自扛过低谷', '在情绪低落、担忧反复或压力过载时，可靠的人际支持能帮助人重新获得现实感和力量。书中建议主动招募志同道合的人，维护家人、朋友、社区或志愿服务中的支持网络。App 可鼓励用户建立“支持清单”：谁适合倾听，谁能陪走路，谁能给专业建议，谁会带来消耗。把求助设计成能力，而不是软弱。', '["社会支持", "关系资源", "求助", "支持团队", "社区", "情绪低谷", "复原力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1383, now()),
(101384, '创造性心智：把问题从单一视角里松开', '当一个问题只剩“必须这样”“我就是这样的人”时，创造力会变窄。练习可以先停下，做几轮呼吸，把注意力从头脑带回身体；再故意换几个观察位置：孩子会看到什么新鲜处？成熟成年人会怎样负责？很久以后回望，这件事还重要吗？像树一样扎根时，身体想要什么支持？这些视角不必都正确，它们的作用是让僵硬认同松动，给下一步行动留出弹性。', '["创造性心智", "多重视角", "认知灵活性", "自我观察", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1384, now()),
(101385, '游戏感不是幼稚：用动作和声音恢复流动', '游戏感可以被理解为一种轻量的心理实验：暂时放下“我必须表现得正确”，允许身体做一个小动作、发出一个轻声、用夸张或幽默的方式表达愿望。若立刻出现“我做不到”“太傻了”，先把它当成拒绝或紧绷的信号，而不是事实。App 里可做成30秒练习：呼吸、放松肩颈、做一个代表“我想更有创造力”的动作，再观察身体是否多了一点柔软或好奇。', '["游戏感", "创造性心智", "身体动作", "内在小孩", "正念练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1385, now()),
(101386, '倒着读书的启发：同一件事可以换入口', '课程中的“倒着读书”故事适合转化为一个实用提醒：很多能力不是只有一种标准姿势。遇到卡点时，别急着问“我是不是不行”，先问“还有哪些入口？”可以列出三种替代方式：从相反顺序开始、换一个身体位置、用图像而非语言描述、请别人从另一角度解释。这个练习不是追求新奇，而是训练大脑记得：经验和行动方式可以比习惯中的那一种更丰富。', '["灵活思考", "多重入口", "创造性心智", "认知灵活性", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1386, now()),
(101387, '先扎根再许愿：让正向意图回到身体里', '正向意图不必写得宏大，越短越容易落地。先选一个当下想创造的方向，最好一到五个词，例如“更稳定”“修复沟通”“照顾身体”。然后站稳或坐稳，感受脚底向下、脊柱向上，双臂像枝叶一样舒展。再把这句话放在身体里感受：说出它时哪里紧、哪里亮、哪里想退缩？这样的练习把目标从纯头脑计划，转成可被身体观察和承载的行动线索。', '["正向意图", "身体安顿", "目标澄清", "身心练习", "自我观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1387, now()),
(101388, '三颗正念种子：身体静止、念头寂静、环境开放', '可以把三颗种子看成三步身心调节，而不是神秘仪式。第一颗“静止”给身体：放慢动作，感受肌肉和呼吸逐渐安顿。第二颗“寂静”给语言心智：不用赶走念头，只让它们在更宽的空间里暂时休息。第三颗“开放”给关系和环境：想起自己所在的房间、家庭、城市或自然，让注意力从孤立的自我扩展到更大背景。完成后再回到意图，观察选择是否更清楚。', '["三颗正念种子", "静止", "寂静", "开放", "身体觉察", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1388, now()),
(101389, '从紧绷认同切换到流动观察', '紧绷时，人会把一个念头误当成全部自我：我很焦虑、我不行、我必须立刻解决。流动观察的练习是先承认“这里有焦虑/僵硬/催促”，再把注意力放到身体：脚底、腹部、胸口、肩颈分别有什么感觉？然后问一句：如果我不需要马上证明自己，下一步最小的、友善的行动是什么？这个过程不否认困难，只是把自我从单一标签中移出来，回到可观察、可调整的状态。', '["流动观察", "僵硬认同", "自我觉察", "身体安顿", "行动选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1389, now()),
(101390, '科学心理学：把常识问题变成可观察的问题', '心理学不只给“看起来合理”的解释，而是围绕描述、解释、预测和影响四类目标工作。把“帮助意愿”“紧急状况”等抽象词转成可观察、可记录的行为，是科学研究的重要一步。用于自我成长时，可先区分事实、解释和假设：我看到了什么？我怎样定义它？还有哪些证据能验证？这样能减少把常识判断误当结论。', '["心理学基础", "科学方法", "操作性定义", "行为观察", "自我成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1390, now()),
(101391, '行为由多种条件共同决定，少用单一人格标签', '同一个人在不同情境中可能表现不同，行为通常受个人特征、情境线索、旁观人数、情绪和既往经验共同影响。旁观者没有及时帮助，不一定说明“冷漠”，也可能与责任扩散、是否识别为紧急情况有关。App 问答中适合引导用户先看条件：当时有哪些人、规则、压力和可选行动，再讨论个人选择。', '["行为观察", "归因", "社会互动", "旁观者效应", "情境因素"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1391, now()),
(101392, '发展既有连续变化，也有阶段性转变', '发展心理学提醒我们，不同能力的变化节奏并不相同。身高、词汇量、知识储备常呈连续增长；规则理解、逻辑操作、道德判断等能力有时会出现更明显的阶段性转变。遗传和环境也不是二选一，而是共同参与发展。面对孩子或自己的成长，不宜用“太笨”“天生不行”定论，更适合看当前任务、练习条件和成熟水平是否匹配。', '["发展心理学", "发展阶段", "遗传与环境", "成长教育", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1392, now()),
(101393, '婴幼儿认知与语言：能力常早于表达', '婴幼儿并非只靠反射被动反应，他们很早就会对熟悉声音、物体是否仍然存在、语音差异等作出反应。语言发展通常经历从声音敏感、咿呀学语、单词表达到两词组合和更完整句子的过程。成人回应、模仿榜样和天生的语言准备共同发挥作用。理解这一点，有助于减少对低龄儿童“说不清就是不懂”的误判。', '["婴幼儿发展", "语言发展", "认知发展", "亲子教育", "学习准备"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1393, now()),
(101394, '学习是经验带来的较持久改变，但表现会受状态影响', '学习不是能直接看见的东西，通常通过较持久的行为变化来推断，并需区别于疲劳、成熟、药物或短暂情绪造成的变化。一个人“会不会”与“当下表现得好不好”也不同：考试压力、健康状况、动机和环境干扰都会影响发挥。自我成长场景中，可把学习目标拆成经验、练习、反馈和表现条件四部分来检查。', '["学习心理学", "行为变化", "练习经验", "表现状态", "自我成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1394, now()),
(101395, '观察学习：榜样、后果和自我效能会影响模仿', '人并不只从亲身奖惩中学习，也会通过观察他人的行为及其后果形成新的行为倾向。榜样是否被奖励、是否有力量、是否友善，以及观察者是否相信自己也做得到，都会影响模仿。App 中可把“我为什么会学到这个习惯”拆成三问：我常看到谁这样做？他得到了什么结果？我是否相信自己能用别的方式行动？', '["观察学习", "榜样作用", "自我效能", "习惯养成", "社会学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1395, now()),
(101396, '记忆不是刻录，而是注意、加工和提取的系统', '记忆更像主动加工系统，而不是把经历原样刻进脑中。感觉记录保留极短暂的大量信息，注意力把一部分内容送入工作记忆，工作记忆再通过意义加工、复述和已有知识连接，形成更稳定的长期记忆。分组和赋义能显著减轻工作记忆负担，例如把零散字母变成有意义的单位。学习时关键不是“多看几遍”，而是让信息变得可理解、可组织、可提取。', '["记忆机制", "工作记忆", "注意力", "长期记忆", "信息加工"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1396, now()),
(101397, '提高记忆：主动复述、提问、图像化和分散练习', '机械抄写或单调重复常让人忙碌，却未必留下稳定记忆。更有效的方法包括：减少电视和噪音等干扰；读完一段后用自己的话概括；主动提问并寻找例子；把抽象内容转成图像或个人相关情境；掌握后继续适量反复学习；把练习分散到多个时段。对无意义材料，可用故事、关键词或位置法建立提取线索。', '["学习策略", "记忆提升", "分散练习", "主动复述", "记忆术"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1397, now()),
(101398, '解决问题先理解情境，再选择策略', '面对复杂问题，过早套方案会降低成功率。有效做法是先分析现状、目标和关键限制，再用图示、手段—目的分析、类比参照物或算法等策略推进。专家往往先花时间理解问题本质，而新手更容易被表面特征带偏。还要警惕确认偏差、功能固着和习惯性定势：它们会让人只看支持原判断的信息，忽略物品或方法的其他用途。', '["问题解决", "思维策略", "确认偏差", "功能固着", "决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1398, now()),
(101399, '动机解释：目标、驱力、诱因与意志共同作用', '有动机的行为通常表现为启动、方向、持续性和强度，但不能仅用“本能”“懒惰”“上进”等词替代解释。生理需求会推动行动，外部诱因会吸引或阻止行动，内在兴趣也能让人投入。外部奖励若被体验为控制，可能削弱原本的兴趣。实现长期目标时，还需要意志过程：选择注意焦点、控制情绪、调整环境、把失败当作计划反馈。', '["动机心理学", "内在动机", "外在奖励", "意志力", "目标管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1399, now()),
(101400, '情绪由身体、认知和文化共同塑造', '情绪并非只有“开心/难过”两类，它包含身体唤醒、认知解释和文化表达方式。交感神经会在威胁或激动时让心跳、出汗、呼吸等发生变化；同一处境如何解释，也会影响愤怒、同情、愧疚等体验；不同文化对哪些情绪该表达、表达多强，有不同规则。自我成长中，可练习同时命名身体反应、事件解释和表达场合。', '["情绪识别", "身体反应", "认知解释", "文化规则", "情绪表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1400, now()),
(101401, '情感表达是社会信号，也会被情境和经验影响', '面部表情、声音、手势和身体姿态能帮助人们理解彼此，但表情并不总是内心体验的简单外泄。人常在有观众或关系对象在场时更明显地表达情绪，婴儿也会参考照料者表情来判断是否安全。识别他人情绪既有普遍基础，也受文化经验影响。实际沟通中，最好把表情当作线索而非结论，并结合语境和对方叙述确认。', '["情感表达", "非语言沟通", "社会参照", "共情", "情绪线索"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1401, now()),
(101402, '社会感知既高效，也容易受公式和刻板印象影响', '人能在短时间内形成对陌生人的印象，这有助于快速社交判断。但为了省力，大脑常借助社会公式或类别标签，把性别、年龄、穿着、群体归属等表面特征扩展成对能力、动机和性格的推断。这样会带来过度概括、确认偏差和自我实现预言。App 可引导用户把第一印象降级为假设，多观察具体行为和互动过程。', '["社会感知", "刻板印象", "第一印象", "确认偏差", "人际理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1402, now()),
(101403, '社会吸引：接近、熟悉、相似和真诚互惠都会起作用', '关系往往从偶遇开始，但是否继续发展，受空间接近、反复接触、熟悉效应、共同活动、核心价值相似和真诚好感影响。频繁见面能增加好感，却不是决定因素；外貌和第一印象会影响注意力，但不能直接代表能力或品格；相似性尤其体现在兴趣、信念和价值观上。经营关系时，可创造稳定接触、表达真实善意，并尊重差异。', '["社会互动", "人际吸引", "熟悉效应", "相似性", "关系经营"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1403, now()),
(101404, '一句话有两层：事实层和情绪层', '语言心理学提醒我们，口语不只传递字面信息。音量、重音、停顿、表情、手势和选词，都会给同一句话加上情绪色彩。关系沟通中，很多冲突并非“听不懂字”，而是把情绪层误读成攻击或冷漠。App 可引导用户先分开记录：对方说了什么事实、我听到了什么情绪、我还需要核对什么。先核对情绪，再讨论观点，能减少防御。', '["语言与情绪", "语气", "情绪识别", "关系沟通", "误解修复", "倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1404, now()),
(101405, '被某个词刺痛，常常来自私人词典', '同一个词对不同人并不一样。有些称呼、评价或玩笑，会勾起个人经历、家庭语境和身体反应；旁人觉得只是普通词，当事人却可能听成羞辱或抛弃。沟通修复时，不要只争“这个词客观上严重不严重”，更要问：这个词在你那里意味着什么？它让你想起什么？把私人意义说出来，关系才有机会从字面争执转向理解彼此的学习史。', '["个人语言习惯", "词语触发", "心理词典", "关系修复", "自我觉察", "家庭沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1405, now()),
(101406, '情绪性语言会被记得更久', '人对一句话的逐字记忆通常很快变淡，但带有羞辱、禁忌、性暗示或强烈情绪的话，更容易被保留下来。也就是说，“气头上一句”未必会被对方当成临时噪音，它可能成为日后冲突中的证据。App 端可把这点用于冲突降温：越是想用狠话证明自己受伤，越需要暂停；如果已经说出，修复要尽早说明影响、承担责任，并重新表达真实需求。', '["语言与情绪", "冲突降温", "气话", "记忆", "冒犯修复", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1406, now()),
(101407, '理解不是自动解码：共同背景要一起建立', '对话像两个人共同完成一件事，而不是一个人把信息丢给另一个人。说话者会省略背景，听者会用已有经验补全；如果双方的共同背景不同，误解就会自然发生。可用一个简单修复动作：复述自己听到的意思，再请对方确认或修正。比如“我理解你是在担心时间，而不是否定我，对吗？”这类核对能把猜测变成共同建模。', '["共同背景", "倾听", "沟通误解", "复述确认", "关系沟通", "对话"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1407, now()),
(101408, '间接请求保护面子，也容易制造委屈', '很多请求会被包装成询问、暗示或抱怨，因为直接命令容易让人感到被支配。间接表达能保留礼貌，也能给对方拒绝空间；但在亲密关系里，它也常让人陷入“我都暗示了你还不懂”。更稳妥的做法是：先说明需要，再给选择余地，如“如果你今晚有余力，我希望你帮我一起收拾；不方便我们可以约明天。”清楚不等于强迫，温和也不等于含糊。', '["请求表达", "礼貌", "边界协商", "亲密关系", "面子", "沟通误解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1408, now()),
(101409, '讽刺和玩笑需要修复，不是补一句“开玩笑”', '讽刺、挖苦和戏弄常常有两层意思：表面像幽默，底层却可能是批评、轻视或报复。说的人觉得自己没有直说重话，听的人却承受了被嘲弄的感觉。修复时，不宜只用“我只是开玩笑”结束，而要承认对方接收到的伤害：“我原本想轻松一点说，但听起来像在否定你，这点我负责。”随后把真实意见改成可讨论的请求。', '["冒犯修复", "讽刺", "玩笑边界", "关系沟通", "道歉", "情绪安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1409, now()),
(101410, '隐喻能帮情绪落地，也会放大冲突', '人常用隐喻表达难说清的感受，例如把愤怒说成要爆炸，把关系说成投入或消耗。隐喻能让抽象情绪变具体，适合用来帮助自我觉察；但如果隐喻带着攻击，如“你就是一堵墙”，也会把对方固定成问题本身。App 可引导用户把隐喻翻译为体验：我说“墙”时，是指我感到进不去、听不到回应，还是害怕被拒绝？翻译后更容易协商。', '["隐喻", "情绪表达", "自我觉察", "关系沟通", "冲突修复", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1410, now()),
(101411, '和孩子说话：跟随注意力，比灌输词语更有效', '儿童语言学习不是被动听大人讲课，而是在互动中把词和当下经验连起来。照顾者放慢语速、强调重音、重复短句，并跟随孩子正在看的东西命名，会让孩子更容易抓住词义。亲子沟通里，与其不断追问“这是什么”，不如先观察孩子关注什么，再用清楚、温暖、短而完整的句子回应。共同注意比机械纠错更能支持词汇和理解发展。', '["儿童语言发展", "亲子沟通", "共同注意", "儿童导向语言", "词汇学习", "倾听"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1411, now()),
(101412, '孩子说禁忌词时，重点是教语境和情绪出口', '孩子很早就会学到“不能说”的词，而且常在兴奋、模仿、试探边界或表达挫败时使用。成人若只用羞辱或强惩罚，反而会让词变得更神秘、更有情绪能量。更适合的回应是平静标记规则：这个词会让别人不舒服，不适合在这里说；你可以说“我很生气”“我想停一下”。这样既保护边界，也教孩子把冲动转成可被理解的情绪语言。', '["儿童语言发展", "禁忌词", "亲子教育", "情绪表达", "边界", "冒犯修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1412, now()),
(101413, '文化语境会改变“怎样讲故事才算正常”', '人们记忆和讲述事件时，会把故事放进自己的文化模板。不同家庭和文化对“好叙述”的期待也不同：有人重视道德教训，有人重视娱乐，有人习惯少说细节、让听者自己补全。关系沟通中，不要急着把对方的叙事风格贴成敷衍、夸张或没逻辑。更有帮助的问题是：你这样讲，想让我注意哪一部分？在你的家庭里，人们通常怎么讲这种事？', '["文化语境", "叙事", "家庭沟通", "倾听", "沟通误解", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1413, now()),
(101414, '语言风格既能拉近人，也能把人排除在外', '行话、俚语、称呼和方言会标记“我们是谁”。熟悉同一套说法的人更容易产生归属感；听不懂的人则可能感到被排除、被轻视。亲密关系、亲子和职场中，语言风格本身就是关系信号。App 可引导用户觉察：我此刻使用专业词、网络梗或家乡话，是为了亲近、保护隐私、表达身份，还是无意中让对方觉得被挡在门外？必要时，把圈内语翻译给对方。', '["个人语言习惯", "文化语境", "俚语", "方言", "归属感", "关系距离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1414, now()),
(101415, '有权力差的对话，更需要给提问空间', '医生—病人式对话显示：当一方掌握专业知识和流程控制权，另一方容易沉默、少问、误解甚至迎合。家庭和亲子沟通也有类似结构，尤其在父母、老师、主管给结论时。更好的倾听不是快速诊断，而是留出澄清空间：你最担心哪一点？我刚才的说法哪里不清楚？你会怎么转述我的意思？让弱势一方能提问，才是真正减少误解。', '["倾听", "权力差", "亲子沟通", "沟通误解", "提问", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1415, now()),
(101416, '人格理论是观察工具，不是身份判决', '这本书把人格理解为多因素交织的结果：遗传、特质、社会文化、学习、无意识、认知过程与个人选择都可能参与其中。App 端可把人格理论设计成“观察镜头”：此刻哪种解释能帮助我看见模式、增加选择？而不是追问“我到底是哪种人”。对九型用户尤其适合提醒：型号只是进入自我理解的入口，不是给人生盖章。', '["人格理论", "自我观察", "多范型", "非诊断", "九型人格", "成长工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1416, now()),
(101417, '人格不是命运：影响因素只提供倾向', '人格理论常讨论基因、家庭、文化、奖惩和早期经验，但书中也提醒，即使持决定论立场，也只能对行为做概率性预测。App 可以把“我就是这样”改写为“我在某些条件下容易这样”。九型类型、童年经验或特质分数都不应被当成宿命；更好的用法是识别触发条件、资源和可练习的新反应。', '["非宿命化", "人格可塑性", "概率预测", "自我选择", "反标签化", "九型解释"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1417, now()),
(101418, '特质能描述倾向，但不能替代情境观察', '特质理论帮助我们描述相对稳定的行为倾向，例如外向、尽责或敏感；但奥尔波特和后来的社会认知观点都提示，行为还会被情境修正。App 端展示特质或九型时，应避免写成“你总是怎样”，而改成“在这些情境中，你可能更常这样反应”。这样既保留洞察，也给用户留下调整空间。', '["特质理论", "情境变量", "行为倾向", "非标签化", "人格测评", "自我复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1418, now()),
(101419, '精神分析可用于提问：我在保护什么？', '精神分析范型强调无意识、焦虑和防御机制。对 App 来说，安全的用法不是替用户断言“你压抑了某创伤”，而是把反复出现的情绪、回避、投射或过度反应当作自我探索线索：我在避免什么感受？我想保护哪部分自我？书中也提醒，防御在适度时可能有适应功能，只有僵化频繁时才值得进一步关注。', '["精神分析", "防御机制", "无意识线索", "自我保护", "非诊断", "情绪观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1419, now()),
(101420, '行为主义视角：把习惯拆成行为与后果', '斯金纳的价值不在于给人格下标签，而在于说明行为如何被习得、强化、塑造和消退。App 可把“我太拖延/太冲动”改成可观察的问题：触发线索是什么？具体行为是什么？它带来了什么短期奖励？想培养新习惯时，不必一次变成另一个人，而是用小步骤、正强化和环境安排，逐步提高目标行为出现的概率。', '["行为主义", "习得行为", "强化", "习惯改变", "正强化", "行为观察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1420, now()),
(101421, '观察学习：我们会从榜样那里学到预期', '社会认知理论强调，人不只通过亲身奖惩学习，也会观察父母、同伴、媒体和权威人物的行为后果，并形成“这样做会怎样”的预期。App 可引导用户盘点：我正在模仿谁的应对方式？这种榜样让我更自由，还是更受限？对九型用户而言，类型里的惯性也可能来自长期观察到的关系脚本，而不是不可改变的本质。', '["社会认知理论", "观察学习", "榜样", "行为预期", "关系脚本", "九型成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1421, now()),
(101422, '自我效能：先恢复“我能试一试”的感觉', '班杜拉把自我效能看作个体能动性的基础：一个人实际能做什么，与他相信自己能做什么并不总一致。App 在给建议时，应先降低任务门槛，让用户通过小成功、可接近榜样和情绪调节，修正“我完全做不到”的预期。自我效能不是盲目自信，而是让信念逐渐贴近真实能力，从而愿意行动。', '["自我效能", "行动信心", "小步练习", "能动性", "目标坚持", "心理资源"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1422, now()),
(101423, '罗杰斯自我概念：人被接纳，行为仍可调整', '罗杰斯强调自我概念、积极关注和价值条件。很多人为了获得爱与认可，把外界条件内化成“只有我做到某样才值得被喜欢”。App 可帮助用户区分：这是我的真实体验，还是我学来的价值条件？同时保留边界：接纳一个人，并不等于赞成所有行为。这样能减少羞耻式改变，转向更稳定的自我理解。', '["罗杰斯", "自我概念", "价值条件", "无条件积极关注", "自我接纳", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1423, now()),
(101424, '成长动机：不只修补缺口，也追求价值', '马斯洛区分匮乏型动机与成长动机。人当然需要安全、归属、尊重等基本需要，但当一些基本需要被满足后，也会被真实、美、创造、使命和意义吸引。App 可在用户状态评估中同时问两类问题：我现在缺什么支持？我又被什么价值召唤？这样避免把成长简化为“修好问题”，也避免忽略现实需要。', '["马斯洛", "成长动机", "匮乏动机", "需要层次", "价值感", "自我实现"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1424, now()),
(101425, '阿德勒视角：自卑感可以转向合作', '阿德勒把自卑感看作人人都会经历的感受，它既可能压倒人，也可能推动补偿和成长。关键在于追求的是孤立的个人优越，还是与社会兴趣相连的贡献与合作。App 可把“我不够好”转译为两个问题：我想发展哪项能力？这项能力能如何服务关系或共同目标？自卑由此不再是标签，而是行动线索。', '["阿德勒", "自卑感", "社会兴趣", "合作", "生活方式", "成长动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1425, now()),
(101426, '霍妮提醒：警惕“应该的我”取代真实需要', '霍妮描述了真实自我、理想化自我和“应该的专横”。当人长期用一串不真实的“我应该”维持形象，就容易离开真实感受，只剩紧张的自我要求。App 可把九型中的高标准、讨好、强撑或退缩，解释为焦虑下的适应策略，而不是人格缺陷；再引导用户辨认：我真正需要什么？哪些“应该”来自旧关系？', '["霍妮", "真实自我", "理想化自我", "应该的专横", "基本焦虑", "自我关怀"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1426, now()),
(101427, '身份不是一次定型，而是人生阶段中的整合', '埃里克森把人格发展放在整个生命周期中看，强调每个阶段都有需要处理的心理社会任务。青少年期的同一性尤其重要，但身份并不是一次选择后永远不变；角色、关系和文化都会持续参与整合。App 可把九型结果放在“当前人生任务”里解释：它帮助我理解此阶段的冲突，而不是替我决定职业、伴侣或未来。', '["埃里克森", "同一性", "生命周期", "角色探索", "人生阶段", "九型应用"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1427, now()),
(101428, '凯利视角：换一个构想，就多一种行动', '凯利认为人像科学家，会用个人构想解释经验、预测未来；当构想无法帮助我们理解现实，就需要修订。App 可把认知重构做得更轻：我现在用什么词解释这件事？还有哪些同样合理的解释？哪种解释能带来更有效的下一步？九型中的“核心叙事”也可被看成构想系统的一部分，可以被检验和更新。', '["凯利", "个人构想", "认知重构", "可选择性", "意义解释", "叙事更新"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1428, now()),
(101429, '存在主义视角：正常焦虑常伴随成长', '罗洛·梅把自由、责任、价值和焦虑联系起来。并非所有焦虑都意味着出错；当旧价值松动、新选择出现，人会体验到正常焦虑。App 不应只追求“立即消除焦虑”，而可帮助用户分辨：这份焦虑是否与我珍视的价值有关？我能怎样在可承受范围内迈出一步？焦虑由此成为成长信号，而非身份问题。', '["存在主义", "罗洛梅", "正常焦虑", "自由责任", "价值选择", "成长信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1429, now()),
(101430, '自我观察要同时看人、行为与环境', '社会认知理论的交互决定论很适合 App 端：行为不是只由“我是什么类型”决定，也不是只由环境推动，而是个人解释、行为选择和环境反馈不断相互影响。用户复盘时可分三栏：我当时怎样理解自己和对方？我做了什么？环境给了什么反馈？这样九型洞察会变成动态循环图，而不是静态标签。', '["交互决定论", "人境互动", "行为复盘", "动态人格", "九型非标签化", "社会认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1430, now()),
(101431, '九型结果最适合写成“可检验假设”', '结合全书结论，App 端九型解释不宜输出“你注定怎样”，而应写成可验证的成长假设：你可能更容易关注某类威胁、奖励或关系信号；你可以在未来一周观察它是否出现，并尝试一个小替代反应。若经验不支持，就更新解释。这样的呈现既保留九型的洞察力，也符合人格理论的科学审慎与成长取向。', '["九型人格", "可检验假设", "成长建议", "非宿命", "自我实验", "人格整合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1431, now()),
(101432, '关系里的“内容”和“过程”：不只听说了什么，也看正在怎么互动', '很多关系冲突表面上是在争论一件事，深层却是在重复一种互动：谁在指挥，谁在退让，谁害怕被评价，谁急着证明自己。把“内容”和“过程”分开看，会让沟通更清楚：内容是垃圾谁倒、孩子谁管；过程是我是否被尊重、是否能发声、是否又被推到熟悉的位置。先看见过程，才有机会换一种回应。', '["人际过程", "关系沟通", "冲突觉察", "伴侣支持", "亲子沟通", "模式识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1432, now()),
(101433, '好的关系不是谁治好谁，而是一起成为问题的合作伙伴', '工作同盟的核心启发是：让人改变的关系，往往不是高低位置的“我告诉你怎么做”，也不是完全放任的“你自己想”。更有帮助的是共同看清问题、共同确认目标、共同探索可尝试的做法。放到伴侣、亲子或朋友关系里，支持不是替对方决定，而是让对方感觉“我不是一个人，但我的选择仍属于我”。', '["工作同盟", "合作关系", "关系支持", "自我效能", "伴侣沟通", "亲子支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1433, now()),
(101434, '安全避风港与安全基地：既能被安抚，也能被鼓励去探索', '一段让人安心的关系通常有两种功能：痛苦时，它像避风港，让人可以被听见、被安抚；想成长时，它像基地，让人敢于探索、做决定、变得更独立。亲子和伴侣关系都需要这两面：只安抚而不鼓励自主，容易黏住；只要求独立而不给回应，容易孤单。好的支持，是靠近后更有力量离开港口。', '["安全基地", "安全避风港", "依恋", "亲子关系", "伴侣支持", "自主性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1434, now()),
(101435, '修正性情绪体验：被“不同地回应”会改写旧预期', '人会把过去关系里的预期带到现在：表达需要会被嫌麻烦，反对别人会被抛下，成功会让亲近的人不高兴。修正性体验的关键不是讲道理，而是在重要关系里真的遇到不同回应：我说出感受后没有被羞辱，我设边界后关系没有立刻断掉。一次经验不一定改变全部，但它会打开“关系也可以不一样”的缝隙。', '["修正性情绪体验", "关系修复", "旧预期", "安全感", "体验式学习", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1435, now()),
(101436, '重复的人际模式：旧方法常会在新关系里自动上演', '有些互动像自动剧本：越想被肯定，越拼命讨好；越怕被控制，越抢着控制；越怕被拒绝，越先退开。它们也许曾在过去保护过自己，却可能在现在让伴侣、孩子、同事收到混乱信号。识别模式时，不必急着责怪自己，可以先问：这个反应以前帮我躲过什么？现在又让我付出什么代价？', '["重复模式", "人际脚本", "关系觉察", "伴侣冲突", "自我理解", "应对策略"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1436, now()),
(101437, '顺从、对抗、退缩：三种“保护自己”的关系习惯', '面对不安全的关系，人常发展出三类习惯：顺从取悦，用乖和照顾换连接；对抗攻击，用控制和赢保护自己；回避退缩，用不需要别人降低失望。它们不是人格标签，而是曾经的保护方法。真正有弹性的关系能力，是保留这些方法的优势，同时不让它们变成唯一选择：该靠近时靠近，该拒绝时拒绝，该表达时表达。', '["顺从取悦", "对抗攻击", "回避退缩", "关系策略", "灵活回应", "自我保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1437, now()),
(101438, '阻抗不是“不配合”：它可能是在保护关系里的安全感', '当一个人迟迟不说、转移话题、迟到、取消约定或对帮助保持距离，未必只是懒、冷漠或不配合。背后可能有一种预感：如果我暴露需要，会被批评；如果我真的改变，会对家人不忠；如果我依赖你，迟早会失望。把阻抗看成“这件事对你哪里不安全”，比直接指责更容易打开对话，也更能保护关系。', '["阻抗", "关系安全", "羞耻感", "求助困难", "非指责沟通", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1438, now()),
(101439, '即时反馈：温和谈“我们此刻怎么互动”', '关系修复常发生在当下。与其事后猜测，不如在安全语境里说：“我发现我们刚才好像都紧张了，你也有这种感觉吗？”即时反馈不是控诉，而是邀请双方一起看互动。它适合用温和、试探、可修正的语言：我可能理解错了；你怎么看？这样既能减少误会，也能让彼此练习更直接、更尊重地谈关系本身。', '["即时反馈", "过程评述", "元沟通", "关系修复", "沟通技巧", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1439, now()),
(101440, '共情不是“说好听话”：它是准确看见对方的核心感受', '共情的重点不是立刻安慰、建议或评价，而是抓住对方最重要的感受和意义：他真正怕的是什么，最委屈的点在哪里，哪种旧经验被触动了。被准确看见的人，常会从“我是不是太奇怪”转向“原来我的反应有来处”。在亲子和伴侣沟通中，先回应核心感受，再谈事实和选择，关系会更容易保持连接。', '["共情", "情感反映", "被看见", "关系连接", "亲子沟通", "伴侣沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1440, now()),
(101441, '边界让靠近更安全：既参与，也保持分化', '亲密并不等于混在一起，支持也不等于替对方背负人生。关系需要一种平衡：我在情感上靠近你，愿意理解你；同时我仍保有自己的位置，也尊重你的选择。缺少边界时，容易把对方的问题当成自己的任务；过度疏离时，关系又失去温度。清晰边界能让关心更可靠，让分离和连接同时存在。', '["关系边界", "共情边界", "分化", "亲密关系", "照顾者模式", "自我他人区分"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1441, now()),
(101442, '强烈感受背后，常藏着“别人会怎样回应我”的预期', '有时人不是怕感受本身，而是怕感受被看见后的关系后果：哭了会被嫌弃，生气会被离开，脆弱会被看不起，快乐成功会被嫉妒。理解这一点，能让沟通从“你为什么这么情绪化”转向“表达这个感受对你来说有什么风险”。当关系能承接这些风险，感受才更容易被说出来，也更容易被调节。', '["情绪表达", "关系预期", "羞耻", "脆弱", "安全表达", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1442, now()),
(101443, '把新体验迁移到日常关系：从低风险场景开始练习', '新的关系方式不应只停留在咨询室或一次谈话中。更稳妥的迁移路径，是先在相对安全、低风险的人际场景里练习：对熟人表达一个小偏好，对支持性朋友说一次真实需要，再逐渐进入伴侣、孩子、父母等更重要的关系。每次练习后复盘：哪里更顺，哪里又触发旧模式。改变通常靠多次小体验累积。', '["经验迁移", "修通", "日常关系", "行为练习", "关系改变", "低风险尝试"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1443, now()),
(101444, '成功和变好也可能让人不安：允许自己拥有好消息', '有些人遇到成功、快乐或变独立时，反而会内疚：我是不是超过了家人？我高兴会不会让别人失落？我不再那么需要对方，会不会伤害关系？这些不安常让人缩回旧位置。关系支持的重要一环，是由衷欢迎对方的好消息，也欢迎自己拥有好消息。能够一起庆祝成长，会让独立不再等同于背叛。', '["成功内疚", "独立", "家庭忠诚", "安全基地", "成长支持", "自我允许"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1444, now()),
(101445, '亲子关系的双重任务：有清楚限制，也有稳定回应', '孩子需要爱，也需要可预期的边界。只有控制而缺少回应，孩子容易把需求藏起来；只有纵容而缺少限制，孩子又难学会自我调节和尊重他人。更稳的亲子支持，是在孩子痛苦时看见和安抚，在孩子探索时鼓励，在行为上保持清楚规则。这样，孩子既能感到被爱，也能发展责任感、独立性和同理心。', '["亲子关系", "边界", "情感回应", "安全依恋", "自我调节", "家庭支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1445, now()),
(101446, '关系结束也能是修复：可预测、可表达、可告别', '关系的结束若突然、含糊、不能道别，容易重演旧的失落感。更有修复性的结束，需要提前说明、允许复杂感受、承认这段关系的意义，并给彼此一个好好告别的机会。无论是咨询、合作、友谊还是亲密关系，清楚地谈结束并不冷酷；它让人知道：分离可以被看见，感谢和失望都能被表达，联结也可以被内化。', '["关系结束", "告别", "分离", "关系修复", "可预测性", "情绪表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1446, now()),
(101447, '三功能检查：一句话不只是在“说事实”', '关系沟通里，同一句话常同时承担三件事：描述一个对象或事件，表达说话者的状态，并对听者形成某种召唤。比如“你又迟到了”表面是在描述事实，也可能表达失望，还可能要求对方改变。App 端可引导用户先拆分：我看见了什么事实？我真实感受是什么？我希望对方做什么？拆开后，沟通会少一些互相猜测，多一些可回应的信息。', '["语言三功能", "事实描述", "情绪表达", "关系沟通", "非暴力沟通", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1447, now()),
(101448, '事实与情绪分轨：先把“发生了什么”和“我怎么了”分开', '描述功能关注“物体和事件”，表达功能暴露说话者的内在状态。亲密关系中，许多冲突来自把情绪当事实说出，例如“你根本不在乎我”。更稳妥的整理方式是：事实层写可观察行为，情绪层写自己的体验，意义层再标注这件事让自己联想到什么。这样既不压抑感受，也不把感受包装成对方的人格判决。', '["事实与解释", "情绪识别", "沟通降温", "亲密关系", "自我觉察", "误解减少"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1448, now()),
(101449, '语境决定意思：有些短句靠共同场景才能成立', '日常说话并不总是完整句。咖啡馆里的“一杯黑的”、车上的“直走”，之所以能被理解，是因为双方已经共享了消费、乘车、排队等实践场景。亲子或伴侣沟通中，如果一句短话被误解，不一定是谁“理解力差”，可能只是共同场景不足。App 可提醒用户补齐四项：正在做什么、对象是谁、可选项有哪些、这句话要解决哪个歧义。', '["语境", "省略句", "共同场景", "亲子沟通", "关系误解", "表达清晰"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1449, now()),
(101450, '“我、你、这里、现在”：沟通从共同坐标开始', '指示词的意义不是固定在词典里，而是随说话者、听者、位置和时间变化。“我”是当前发送者，“你”是当前接收者，“这里”“现在”依赖当下坐标。关系冲突中，双方常在不同坐标里说话：一个谈此刻感受，一个谈长期付出。App 可把争执整理成坐标卡：谁在说、对谁说、指哪件事、发生在何时何地。', '["指示词", "共同坐标", "我你关系", "场景定位", "关系沟通", "语义澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1450, now()),
(101451, '说话者—听者—对象：冲突里先找三角关系', '语言不是单纯从一张嘴传到一只耳朵。一个言语事件里，至少有说话者、听者和被谈论的对象；声音只是三者之间的媒介。很多家庭冲突会把对象弄丢：本来谈“作业没完成”，很快变成“你就是懒”“你总是控制我”。App 可帮助用户回到三角关系：我是谁、我在对谁说、我们共同处理的对象到底是什么。', '["沟通三角", "说话者", "听者", "共同对象", "亲子教育", "冲突复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1451, now()),
(101452, '误解修复：不要只怪“没听懂”，先补辅助线索', '自然语言本来就大量使用多义符号，靠上下文、语序、语气、手势和现场物来限制歧义。误解出现时，关系修复不宜急着追责，而要补辅助线索：这句话指哪件事？你听成了哪一种意思？我想表达的是感受、请求还是事实？尤其在文字聊天里，缺少声音和场景，更需要主动补时间、对象、情绪强度和期望回应。', '["误解修复", "上下文", "语气", "文字沟通", "关系修复", "歧义澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1452, now()),
(101453, '语气也是信息：亲子沟通不能只看字面内容', '同样的词，在不同声调、重音和节奏下，会呈现不同的表达与感召效果。书中提到，熟悉场景里，模糊的声音形象也能被理解，因为听者会借助语调、节奏和关系经验辨认意图。亲子沟通尤其如此：孩子可能先接收到“我被责备/被催促”，再理解字面意思。App 可提醒家长检查：我的语气在表达关心、命令、失望，还是威胁？', '["语气识别", "亲子沟通", "非语言信号", "情绪表达", "听者体验", "沟通质量"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1453, now()),
(101454, '从现场依赖到清楚说明：文字沟通要补“这里和现在”', '有些话像路口指令，离开现场就失效；有些话则能较独立地描述事实。线上沟通最容易把现场依赖的话当成自足表达，例如“你刚才那样很过分”，但对方可能不知道“刚才”“那样”指什么。App 可建议把依赖场景的句子改成可复盘句：在什么时间、什么场合、哪句话或动作，让我产生了什么感受，以及我希望下次怎样处理。', '["线上沟通", "场景补全", "事实复盘", "指示场", "清楚表达", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1454, now()),
(101455, '共同感知：沟通的目的常是把“我看到的”放进“我们知道的”', '符号交往常发生在一方掌握更多场景信息时：他需要把自己看到、预见或记住的内容放入双方共同感知中。关系里也是如此，提醒风险、表达需要、说明计划，本质上都是扩展共同感知，而不是证明自己正确。App 可把用户的强烈表达转化为共享信息任务：我掌握了什么线索？对方缺哪部分信息？怎样让对方看见，而不是被我压倒？', '["共同感知", "信息共享", "关系协作", "风险提醒", "沟通目的", "情绪降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1455, now()),
(101456, '同一段经历，可以有不止一种理解方式', '一个人的困难经历不只有一种“标准解释”。同一件事可以同时被看作身体受苦、关系失落、身份改变、意义重组，也可能被不同听者听出不同重点。关系沟通中，先别急着给对方下结论，可以问：“这件事对你最像失去了什么？它又让你重新看见了什么？”多视角不是相互否定，而是给复杂经验留下空间。', '["多视角理解", "复杂经验", "避免单一解释", "心理教育", "关系沟通", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1456, now()),
(101457, '把“发生了什么”整理成“这如何改变了我”', '困难发生后，人常先被碎片化的事实、情绪和身体感受淹没。整理故事的意义，不只是复盘时间线，而是看见：这件事打断了我原来的哪种生活？我如何解释失去？我正在把自己重新安放到哪里？当经历能被连接成“过去—现在—可能的未来”，人会更容易从混乱中恢复一点方向感。', '["意义整理", "生命故事", "创伤后整理", "自我成长", "时间线", "内在秩序"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1457, now()),
(101458, '创伤后的成长，不一定是回到原来的自己', '复原不总是“变回以前”。有时旧身份已经被改变，真正的路是让旧的热爱、能力和关系在新生活中找到不同位置。失去歌剧道路的人，仍可能以新的方式保留音乐，也可能发展出新的专业、自我和关系。App 可以引导用户问：我想带走旧生活中的哪一部分？它能否换一种形式继续存在？', '["身份重构", "创伤后成长", "复原", "意义重建", "自我接纳", "人生转变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1458, now()),
(101459, '倾听时区分事实、解释和故事', '对方说“我失去了声音”可能是在讲事实和身体经验；说“我什么都不是了”是在讲当时的意义；说“我必须一直坚强”则可能是用来支撑自己的故事。倾听时不要把三者混在一起反驳。可以分层回应：先确认发生了什么，再接住感受，最后温和询问这个故事是否还有别的讲法。', '["倾听", "事实与解释", "故事视角", "关系沟通", "情绪支持", "自我叙事"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1459, now()),
(101460, '允许矛盾并存：人不是单线条的', '人在困境中常同时拥有相反的部分：很理性，也很痛；想靠自己，也渴望被懂；感谢别人照顾，又怨他们不够理解。好的倾听不是逼对方选一个“真正感受”，而是帮助他看见这些声音如何共处。把矛盾放在桌面上，反而能减少自责：复杂并不等于虚假，它可能正是经验的完整性。', '["矛盾感受", "多重自我", "情绪理解", "自我接纳", "关系支持", "复杂性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1460, now()),
(101461, '尊重当事人的声音：讲述者也需要回应权', '当别人把脆弱经历交给我们时，他不是“素材”，而是仍然拥有感受、边界和选择的人。支持性的回应包括：询问是否愿意继续说、是否希望被匿名或公开、哪些部分不想被传播，以及他是否认同我们的理解。被认真听见，还包括有机会说：“你这样理解我，有一部分对，也有一部分不是。”', '["当事人声音", "回应权", "边界", "知情同意", "尊重", "创伤知情"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1461, now()),
(101462, '不要把“坚强”当作唯一答案', '有些人会用冷静、行动和“我没事”撑过危机，这可能真的帮助他们活下去；但如果周围人只称赞他坚强，也可能让疲惫、恐惧和求助被继续隐藏。更贴近的支持是同时承认能力和代价：“我看到你很努力撑住，也想知道有没有哪一刻你其实很累。”坚强可以被尊重，但不该成为新的枷锁。', '["坚强迷思", "情绪支持", "求助", "创伤应对", "自我照顾", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1462, now()),
(101463, '解释不是贴标签：多一个视角，也要留有余地', '听者有时能看到讲述者暂时看不到的模式，但解释越深入，越需要谦逊。与其说“你其实是在逃避”，不如说“我有一个可能的理解，不知道贴不贴近你”。没有谁对一个人的生命拥有绝对权威：当事人的感受、旁观者的洞察、后来的新资料，都可能让理解继续改变。把解释当成邀请，而不是判决，关系才更安全。', '["解释边界", "避免贴标签", "谦逊倾听", "共同理解", "自我反思", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1463, now()),
(101464, '天赋不是命运标签，而是向内外同时探索的过程', '书中把天赋探索描述为双向旅程：一边向内看见自己的感觉、价值观、兴趣与能量，一边向外寻找环境中的机会。对 App 用户来说，九型类型不应被当作命运判词，而可作为提问入口：我在哪些情境更有活力？哪些选择让我像在“熬日子”？答案需要通过持续观察、尝试和反思形成。', '["天赋探索", "九型优势探索", "自我觉察", "人生选择", "非宿命化", "创造人生"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1464, now()),
(101465, '天赋是天分与热情的交汇，不只是擅长', '天分说明某些事情对你更容易上手，热情说明它是否持续给你能量。一个人可能很擅长某项工作，却并不喜欢；也可能热爱某件事，却暂时缺少训练。真正可用的优势探索，应把“我能做什么”和“我为什么愿意投入”放在一起看，再通过小行动验证，而不是只看性格描述或别人评价。', '["天分", "热情", "能力结合", "优势验证", "职业方向", "九型用户"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1465, now()),
(101466, '天分需要练成能力：优势不是自动兑现的', '书中区分了天分与能力：天分是原始潜力，能力是经过学习、教育、实践后形成的表现。九型用户看到自己的优势倾向时，不宜直接等同为职业答案；更应追问：这个倾向在哪些任务中可训练？需要哪些技能、反馈与作品积累？天赋的成熟，是先天潜能与后天练习不断互相塑造的过程。', '["天分与能力", "刻意练习", "成长路径", "优势开发", "职业技能", "自我训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1466, now()),
(101467, '测评可以启发，但不能替你定义自己', '作者提醒，天分测试、职业测评和人格分类都有启发价值，也都有误导风险。标准化测试难以完整捕捉演讲、表演、创造、关系协作等复杂能力。放到九型场景中，类型报告更适合作为“假设清单”：哪些描述有证据？哪些只是巴纳姆效应？用户需要用真实经历、他人反馈和行动结果来校准自我认识。', '["测评边界", "巴纳姆效应", "九型报告", "自我校准", "非标签化", "真实反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1467, now()),
(101468, '隐藏天分常被错误的学习方式遮住', '很多人以为自己“不擅长数学、音乐、设计或表达”，可能只是第一次遇见它的方式不适合自己。书中多次指出，教育系统常偏重少数可考试的能力，忽略视觉、实践、表演、协作等多元天分。App 端可以引导用户回看：哪些领域曾因教学方式、评价方式或羞耻感被放弃？换一种学习路径，也许会重新打开优势。', '["教育反思", "学习方式", "隐藏天分", "多元能力", "自我探索", "优势重启"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1468, now()),
(101469, '从日常活动地图中发现能量线索', '书中的练习建议把一周活动画成图，标出“喜欢、无所谓、不喜欢”的时间占比。这适合转化为 App 的轻量记录：用户不必先想宏大使命，而是先观察每天哪些任务带来活力，哪些让自己耗竭。九型优势探索也可以从此开始：类型解释只是辅助，真正的线索藏在时间、情绪和身体能量的变化里。', '["活动记录", "能量管理", "日常觉察", "喜欢与耗竭", "九型优势探索", "行动练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1469, now()),
(101470, '热情不是亢奋，而是可持续的心灵能量', '书中把热情理解为人与某些事物之间深层的吸引、满足和能量连接。它不一定表现为外向激动，也可能是安静、专注、反复投入仍不厌倦。App 可引导用户追问两个问题：我热爱什么？我热爱它的什么？这样能避免把热情简化成一时冲动，也能帮助不同九型用户找到更稳定的内在驱动力。', '["热情", "内在驱力", "心灵能量", "专注体验", "九型动机", "自我提问"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1470, now()),
(101471, '积极情绪与正念能放大创造力', '书中引用积极心理学与正念研究，说明喜悦、同情、希望等积极情绪会让思维更灵活、更有整合性，也更能释放创造力。发现天赋不是只靠理性分析，还需要觉察情绪如何影响注意力。对 App 来说，可把冥想、情绪记录、正念练习与优势探索结合，让用户从“我应该怎样”转向“什么让我更清醒、更有创造力”。', '["创造力", "积极情绪", "正念", "冥想", "情绪觉察", "注意力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1471, now()),
(101472, '幸福感是天赋探索的信号，不是保证', '书中把幸福与意义联系起来：如果一个人长期不喜欢自己每天做的事，其他层面的幸福也会被拖累；但顺应天赋并不保证永远快乐。App 知识库可强调，幸福感是一种重要信号：哪些活动让我感到有意义、有成就、愿意继续？同时也要区分短期愉悦与长期充实，把天赋放进真实生活结构中检验。', '["幸福感", "意义感", "日常工作", "长期充实", "天赋信号", "生活结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1472, now()),
(101473, '成长型思维能避免把优势固化成标签', '作者借成长型思维说明，天分、能力和态度都不是一次测出来就固定不变。固定型思维会让人不断证明自己“够聪明、够有天赋”；成长型思维则关注训练、经验、目标和坚持。九型 App 尤其需要避免让用户把类型当边界，而应把类型当成观察起点：我可以在哪些场景练习新反应，拓展自己的可能性？', '["成长型思维", "非标签化", "九型类型", "态度改变", "可能性", "持续成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1473, now()),
(101474, '处境评估：把梦想拆成优势、弱势、机遇与风险', '书中建议用 SWOT 评估当前处境：自身的优势与弱势、外部的机遇与风险，都可能影响天赋落地。它能把“我想改变人生”的模糊愿望转成可讨论的问题：我有什么资源？真正的障碍是什么？风险后果是否被夸大？下一步需要训练、机会还是支持？这比单纯鼓励追梦更适合 App 的行动引导。', '["SWOT", "处境评估", "行动引导", "资源盘点", "风险判断", "人生选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1474, now()),
(101475, '找到部落：优势需要同伴、文化和反馈', '书中把“部落”定义为由共同兴趣和热爱连接起来的人群，它能提供肯定、指引、合作和鼓舞。优势不是只在独处中被发现，也会在合适的群体文化里被看见、练习和放大。App 可引导用户寻找现实或线上社群、导师、作品反馈与合作机会，同时提醒：适合的部落会滋养能量，不适合的部落会消耗自己。', '["部落", "同伴支持", "导师", "社群", "反馈", "合作创造"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1475, now()),
(101476, '行动计划只需要下一步，不必规划完整人生', '书中强调，生命不是线性工程，无法一次规划全部人生；更实际的是从当下出发，围绕天分、热情、态度和机遇做一个初始行动计划。用户可以为每个维度写下四五句可执行描述，选出最重要的一步开始。这样既保留开放性，也避免永远停留在“思考人生”，把自我认识转化为创造人生的行动。', '["行动计划", "下一步", "创造人生", "天分热情态度机遇", "开放性", "执行"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1476, now()),
(101477, '人生不止一种天赋：开放性比唯一答案更重要', '作者提醒，一个人可能同时爱上几种事物，兴趣和目标也会随经验变化。发现天赋不是把自己锁进一种身份，而是更深地理解自己想怎样生活。对九型用户来说，这一点尤为关键：类型、优势和热情都不是终局，而是持续更新的地图。保留“还有别的什么吗”的提问，才能让人生选择更有弹性。', '["多重天赋", "人生弹性", "开放探索", "九型优势探索", "非宿命化", "自我更新"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1477, now()),
(101478, '正念是一种可练习的当下觉察', '正念不是把自己变成另一个人，也不是加入某种信念系统。它更像一种生活能力：刻意把注意带回此时此刻，知道身体、情绪、念头和环境正在发生什么；同时暂时放下马上评价、解释和解决的冲动。练习的重点不是获得特别体验，而是更清楚地与自己和当下处境建立联系。', '["正念基础", "安住当下", "观察不评判", "心理教育", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1478, now()),
(101479, '停下来：从做事模式回到存在模式', '很多压力来自一路被任务推着走，连自己正在怎样呼吸、紧张、担心都不知道。正念里的“停下来”不是消极躺平，而是短暂暂停所有必须马上完成的事，回到“我正在这里”的存在感。哪怕五秒钟，也可以放下手边的动作，觉察呼吸和感受，再决定下一步。停过之后再行动，动作往往更清楚、更有质地。', '["停下来", "doing到being", "安住当下", "呼吸觉察", "日常练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1479, now()),
(101480, '呼吸是随身可用的当下锚点', '呼吸一直在发生，因此它适合作为回到当下的锚点。练习时不需要刻意深呼吸，也不必控制节奏，只是知道气息正在进入、离开身体。心跑走时，温和地把注意带回一次完整的入息和出息。这样的练习不必很长，关键是把零散的一刻一刻串起来，让注意力有机会从纷乱念头中回到身体。', '["呼吸练习", "身体觉察", "安住当下", "注意力", "微练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1480, now()),
(101481, '当下即是：接纳现实后再选择行动', '接纳当下不等于认命，也不是赞同正在发生的一切。它的意思是先承认事实已经在这里：身体这样感觉，情绪这样波动，处境暂时如此。只有看清站立之处，才可能选择下一步。若急着否认、逃开或强迫改变，我们往往只是被反应牵着走；先承认现实，行动才更可能来自清醒而非惯性。', '["当下即是", "接纳", "自觉回应", "惯性反应", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1481, now()),
(101482, '修习不是追求特殊体验', '练习正念时，很容易把它变成另一个绩效目标：是否更放松、是否进步、是否做对了。这样的期待会让注意力离开当下，转向评估自己。更稳妥的方向是：每次练习只是在此刻与经验同在，愉快、不愉快、清晰、混乱都可以被看见。练习不是排练完美表现，而是一次次回到真实发生的这一刻。', '["修习", "不追求结果", "观察", "接纳", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1482, now()),
(101483, '不加批判：看见评价，而不是被评价带走', '不加批判并不是让大脑停止判断，而是知道“评价正在出现”。练习中可能会冒出“我做得不好”“这很无聊”“今天状态糟”等念头；它们也是当下经验的一部分。若继续批判这些批判，心会更紧。可以把评价当作一个被观察到的念头，允许它来、停留、离开，再回到呼吸、身体或正在做的事。', '["不加批判", "观察念头", "自我评价", "安住当下", "正念基础"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1483, now()),
(101484, '放下：松开喜欢和厌恶的拉扯', '放下不是压抑需求，也不是假装无所谓，而是看见自己正被“想抓住”或“想推开”的力量拉扯。某个念头、期待、关系或结果可能让心紧抓不放；当我们能觉察这种紧抓，才有机会松一松手。放下的动作很小：承认此刻有欲望、有抗拒、有不安全感，然后暂时不被它们指挥。', '["放下", "执着", "喜欢与厌恶", "情绪波动", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1484, now()),
(101485, '耐心：让混浊的水自己沉淀', '焦躁常伴随着一个隐含要求：事情必须按我的节奏立刻改变。耐心不是拖延，也不是不能加快脚步，而是在行动之前先感知内在的急迫、愤怒或不安。像等混浊的水慢慢澄清，给自己几个呼吸的时间，听一听身体和处境在说什么。需要推动时就推动，需要等待时也能等待。', '["耐心", "情绪调节", "暂停", "自觉回应", "压力时刻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1485, now()),
(101486, '用身体回家：姿势、触感与身体扫描', '正念不只发生在头脑里。坐下时，姿势会影响内在状态：既不塌陷，也不僵硬，身体可以表达一种稳定和尊严。躺下时，可以从脚到头感受各部位，觉察紧、热、沉、痛、空或麻等变化，并在呼吸中放松。把注意带回身体，是从纷乱思考回到现实的一条温和路径，也适合作为情绪波动时的自我照顾起点。', '["身体觉察", "身体扫描", "坐姿", "尊严", "呼吸与身体"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1486, now()),
(101487, '情绪像天气：山与湖的练习', '情绪会像天气一样变化：有时明朗，有时风暴，有时表面起浪。山的意象提醒我们，身体可以稳稳坐着，感受风暴而不被风暴定义；湖的意象提醒我们，表面被扰动时，水体深处仍可能有安静。练习不是否认情绪，而是让情绪被看见、被容纳，同时记得自己不只是这一阵情绪。', '["情绪波动", "山之禅", "湖之禅", "安住", "观察不评判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1487, now()),
(101488, '自动驾驶到自觉回应：给冲动一小段空间', '很多反应在意识前已经启动：想马上离开、反驳、责怪、拿起手机、冲去做下一件事。正念练习可以从识别第一个冲动开始：谁想停下？谁急着走？这股力量在身体哪里？先不急着行动，用一个呼吸观察它。这个小空间不保证情绪消失，却能减少被惯性直接接管的可能，也为更贴合当下的选择留下余地。', '["自动驾驶", "惯性反应", "冲动觉察", "暂停", "自觉回应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1488, now()),
(101489, '日常小事就是练习场', '正念不只属于安静练习时间。上楼、开门、接电话、洗澡、吃饭、取衣服、走向冰箱，都是回到当下的入口。可以留意身体是否被匆忙推着走，是否还感觉得到水流过皮肤、食物的味道、脚踩地面的触感。把一件重复小事变慢一点，就能把练习带进真实生活。这让自我照顾从概念落到可执行的片刻。', '["日常练习", "慢下来", "身体觉察", "安住当下", "生活场景"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1489, now()),
(101490, '行走中的正念：每一步都回到这里', '走路也可以是正念练习。重点不是走到哪里，而是感受正在走：重心转移、脚掌抬起和落下、身体前进、呼吸与步伐同在。速度可快可慢，关键是知道自己正在这一步里。通勤、散步、遛狗或走廊之间，都可以提醒自己：先回到身体，再走向目的地。目的地仍在，但每一步不再只是赶路。', '["行走正念", "身体觉察", "日常练习", "安住当下", "呼吸"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1490, now()),
(101491, '别把正念等同于正面思考', '正念不是把负面念头替换成积极口号，也不是要求自己永远乐观。它更像一个足够大的容器，允许念头、情绪和身体反应被看见。念头只是念头，不必立刻当成现实，也不必马上改写。先看见思考正在发生，才可能不被狭窄、惯性的解释方式困住。这样更贴近日常心理教育中的自我觉察训练。', '["正念误区", "正面思考", "观察念头", "心理教育", "不评判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1491, now()),
(101492, '把“经验判断”降级为待证假设', '很多决策卡住，是因为把“我以前这样做过”直接当成答案。更稳的做法是：先承认经验只是一个起点，再追问依据、证据和适用条件。App 可在用户说“应该没问题”“我一直都这样”时提醒：这句话背后的假设是什么？今天的环境、对象、资源是否已经变了？先把经验降级为待证假设，才有机会从旧路切换到新路。', '["逻辑思考", "经验迷恋", "假设意识", "决策校准", "个人成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1492, now()),
(101493, '先证实假设，再宣布结论', '资料整理、直觉判断、初步分析都只能算假设，不应急着包装成结论。可把思考流程拆成四步：提出假设、寻找证据、实地或实验验证、再生成结论。App 可把用户的判断改写成“我目前的假设是……”，再追问：要证明它，需要哪些事实？哪些证据会推翻它？这样能减少拍脑袋，也能让复盘更清楚。', '["假设验证", "事实推理", "科学思考", "决策复盘", "证据意识"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1493, now()),
(101494, '别在现象清单上停止思考', '“状态不好、对方不配合、事情太多”常常只是现象，不是原因。真正的思考要继续追问：这些现象背后有没有同一个更深层的触发点？如果只对现象下手，可能越补越乱。App 可引导用户把抱怨列成现象清单，再逐项问“这说明了什么”“它由什么造成”“哪个原因一变，其他现象也会跟着变”。', '["问题本质", "根因分析", "解决问题", "聚焦杠杆", "逻辑思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1494, now()),
(101495, '用脚验证：真正的答案常在现场', '坐在桌前看数据，容易以为自己已经理解问题；到现场观察、访谈、跟随一次，才会发现数字背后的真实行为。App 可把“我觉得”转成一个小型验证任务：问三个人、观察一次使用场景、记录一次真实对话、亲自走完整个流程。现场不是形式，而是为了捕捉当事人没说出口、报告里没有写出的关键事实。', '["现场验证", "事实采集", "用户观察", "行动学习", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1495, now()),
(101496, '假设错了就归零，不要把旧路走到底', '发现判断错了，不必用后悔或自责继续惩罚自己；更重要的是立刻归零、重设假设、重新出发。App 可在用户陷入“都已经这样了”时提醒：沉没成本不是继续的理由。把已经付出的代价记录为学习，再问：如果今天重新开始，我会基于哪些新事实做选择？这能帮助人从固执旧路线，切换到更有效的行动路径。', '["切换路径", "认知灵活性", "复盘", "成长心态", "决策调整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1496, now()),
(101497, '说服先搭证据台阶，再谈建议', '有效表达不是把自己想说的全倒出来，而是先让对方看见你做过哪些调查、得出什么小结论，再顺着证据走到建议。App 可用于汇报、谈判、沟通边界：先写一句总体结论，再列环境、对方需求、限制条件、可选方案和下一步。证据台阶越清楚，对方越容易从“你凭什么”转向“接下来怎么做”。', '["说服表达", "逻辑沟通", "建议结构", "沟通准备", "证据链"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1497, now()),
(101498, '逻辑之外，还要处理人的情绪阻力', '再正确的方案，如果让人丢脸、受威胁或被否定，也可能执行不下去。沟通时既要满足逻辑上的必要条件，也要照顾执行者的心理承受。App 可在用户准备提出建议前加入检查：这会让谁难堪？谁需要提前沟通？提出后如何跟进？把情绪阻力当成执行条件的一部分，而不是把对方简单归为“不讲理”。', '["情绪阻力", "沟通执行", "说服表达", "关系智慧", "行动落地"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1498, now()),
(101499, '用事实对事，不用立场护短', '冲突中最难的是承认不利于自己的事实。人一旦只忠于身份、部门、面子或过去观点，就会把问题变成互相指责。App 可在关系和工作争执中帮助拆分：已确认事实是什么？我在保护哪个立场？对方在保护什么？如果事实成立，我愿意改变哪一步？对事不对人不是冷漠，而是让解决方案重新回到现实。', '["事实核对", "冲突沟通", "对事不对人", "立场觉察", "问题本质"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1499, now()),
(101500, '无答案问题：先设前提，再给方案', '面对陌生问题，不需要立刻知道标准答案。更好的反应是先设定前提：如果环境是这样、资源是这些、目标是这个，我会如何行动？当前提改变，答案也可以随之调整。App 可把“我不知道怎么办”转成“在什么前提下，我能先给出一个可用答案”。这适合职业选择、旅行计划、复杂关系和不确定的长期目标。', '["无答案问题", "前提思考", "假设推演", "适应力", "决策训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1500, now()),
(101501, '非线性世界里，不要套旧公式', '很多现实问题不是输入固定、答案唯一的算术题，而是变量多、条件会变、初始差异会放大的非线性问题。App 可提醒用户少问“有没有一个正确公式”，多问：关键变量有哪些？哪些正在变化？我能观察到什么实时迹象？哪些旧规则已经不适用？这样能避免用过时经验解释新局面，也能让决策更贴近现实。', '["非线性思考", "复杂系统", "变量意识", "事实观察", "旧框架更新"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1501, now()),
(101502, '构想不是灵感，是疑问的累积', '新构想很少凭空降临，更多来自长期对现象保持疑问：为什么会这样？有没有类似模式？如果换个国家、行业或人群会怎样？App 可设计每日五问：读完一条信息后写出未被报道的部分、可验证的假设和下一步调查。让“不确定”维持思考张力，构想就会从问题、证据和反复验证中逐渐成形。', '["构想生成", "创造力", "持续提问", "假设验证", "信息怀疑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1502, now()),
(101503, '预测未来：拆功能，看力量往哪走', '预见不是玄学，而是把当前功能、用户行为、技术可行性和使用便利性拆开，看哪股力量会持续变强。App 可引导用户做“五年后”练习：先定义清楚领域，再找关键因果，提出简洁假设，选择最可能方向，并记录哪些前提一旦改变就要修正。预测的价值不在猜中，而在训练整合细微信号的能力。', '["未来思考", "功能拆解", "趋势判断", "假设推演", "决策训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1503, now()),
(101504, '警惕空隙被填满：把“无事可做”的时间还给恢复和思考', '《时间，快与慢》提醒我们：许多技术本来承诺节省时间，却常常把原本的空隙填得更满。等车、排队、饭后散步、睡前发呆，这些过去看似“无效率”的间隙，本来承担着情绪整理、身体恢复、关系靠近和深度思考的功能；当它们不断被消息、短视频、待办和即时回复吞掉，人会误以为自己更高效，实际上更容易烦躁、分心、睡不踏实。练习时可以先做一张“空隙地图”：记录一天中哪些时间原本可以停下来，却被自动刷手机或临时任务占用。然后选一个最容易执行的空隙，如起床后十分钟、午饭后五分钟、通勤其中一段，把它设置为不输入信息的慢时间。慢时间不是偷懒，而是让大脑从连续刺激中恢复。提醒自己：不是每一个空白都需要被填满；能保留空白，才更容易听见真实需要。', '["慢时间", "注意力", "压力管理", "数字边界", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1504, now()),
(101505, '注意力不是无限资源：别把每一次通知都当成必须回应的召唤', '书中把当代生活的紧张关系说得很清楚：发送信息的一方争夺注意力，接收信息的一方真正稀缺的是迟缓而持续的时间。App 端用户常见的疲惫，不只是事情太多，而是注意力被不断切走：一条消息、一个红点、一个提醒，都像在要求“现在就处理我”。可执行练习是设置“回应窗口”，而不是追求全天即时在线。比如每天固定三到五个时间集中处理消息，其余时间关闭非必要通知；如果担心错过重要的人，可以为少数联系人保留电话或特殊提醒。处理消息时使用三类标签：现在必须回、今天晚点回、无需回应。这个练习的重点不是变冷漠，而是把注意力从外界拉扯中拿回来。真正重要的关系，不应只靠秒回维系；真正重要的工作，也需要不被打断的连续时间。', '["注意力管理", "信息过载", "手机边界", "专注练习", "情绪稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1505, now()),
(101506, '慢速任务要先预约：深读、陪伴和复盘不会自动出现在日程里', '书里反复指出，当快速任务和慢速任务相遇时，快速任务往往获胜。因为快任务更急、更响、更容易被衡量：消息要回、表格要交、电话要接；而慢任务如读一本书、陪家人聊天、认真复盘一次冲突、思考长期方向，看起来不紧急，于是总被推后。解决办法不是等有空，而是先为慢任务预约位置。可以每周给三类慢时间做最小安排：一段深度输入时间，用来读长文或整理笔记；一段关系时间，用来不看手机地陪伴家人或朋友；一段复盘时间，用来回看本周的情绪、冲突和收获。每段先从二十分钟开始，写进日历并设置“不可被普通事务占用”。慢速任务的价值常常不能当天显现，但它们决定一个人是否还有内在秩序、长期方向和真实关系。', '["慢时间", "日程设计", "亲密关系", "深度思考", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1506, now()),
(101507, '过滤比收集更重要：信息越多，越要先问“这和我的问题有关吗”', '信息时代容易让人产生一种错觉：只要保存更多资料、关注更多账号、打开更多网页，就会更有把握。书中指出，信息丛林越茂密，过滤、探索和组织反而越重要。对 App 用户来说，焦虑时疯狂搜索心理、关系或亲子内容，可能会越搜越乱。可以使用“三问过滤法”：第一，这条信息回答的是我当前的什么问题？第二，它会让我接下来做一个更安全、更具体的行动吗？第三，它是否只是制造更多担心或比较？如果答案不清楚，就先放入“以后再看”，不要立刻继续深挖。每次学习只保留三条可执行结论，并写成自己的语言。信息的价值不在于数量，而在于能否帮助你更清楚地看见处境、做出选择、减少无效内耗。过滤不是封闭自己，而是避免被碎片牵着走。', '["信息筛选", "认知负荷", "学习方法", "决策支持", "清晰表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1507, now()),
(101508, '指数级累积会让人晚一步才发现失控：小分心也需要早期干预', '书中用指数级增长提醒我们：有些变化在开头看起来微不足道，等到明显时已经扩张很快。这个视角可以转化为自我管理工具。比如睡前多刷十分钟、工作时顺手看两次消息、亲子沟通中多一句敷衍回应，单次都不严重，但如果每天重复，就会累积成睡眠不足、注意力下降和关系疏远。练习不是要求完美自律，而是建立早期信号。选择一个正在变糟的小习惯，记录三项指标：发生频率、持续时间、事后感受。当频率连续三天上升，就启动一个小干预：减少入口、延后十分钟、换成替代动作，或请一个人提醒。越早处理，成本越低。不要等到“彻底失控”才改变；很多恢复来自在苗头阶段就温和转向。', '["行为改变", "早期干预", "分心管理", "习惯养成", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1508, now()),
(101509, '弹性工作不等于自由：没有边界的灵活会把生活拼成碎片', '书中把现代工作比作“乐高积木”：任务可以拆成很多小块，塞进一天的任何缝隙。表面上这叫弹性，实际上如果没有边界，工作就会侵入吃饭、陪伴、休息和睡眠。很多人的疲惫不是连续工作八小时，而是从早到晚都处在“随时可能被工作叫走”的状态。可执行练习是建立三层边界：时间边界，明确每天最晚处理工作的时点；空间边界，哪怕在家办公，也指定一个结束工作后的收纳动作，如合上电脑、关掉工作软件；沟通边界，提前告诉同事哪些事情需要即时联系，哪些可以第二天处理。弹性的价值应当是让人更能安排生活，而不是让工作无处不在。真正的休息需要可预期的离线时间。', '["工作边界", "弹性工作", "家庭生活", "压力管理", "时间保护"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1509, now()),
(101510, '快节奏会压缩关系：亲密需要不被效率考核的共同时间', '当生活被效率语言统治，关系也容易变成任务：吃饭时处理消息，陪孩子时想着工作，伴侣沟通时急着得出结论。书中提醒，慢速时间保存着思考、休息和亲密空间。亲密关系里的许多重要内容，如安全感、信任、幽默、共同记忆，无法用“更快完成”来获得。练习可以从“无目标陪伴”开始：每天或每周选一段时间，不解决问题、不教育、不复盘对错，只和对方待在一起，可以散步、做饭、喝茶、听孩子讲一件小事。若谈到冲突，也先用一句话确认感受：“我听到你在意的是……”而不是马上反驳。关系需要慢，是因为人只有在不被催促时，才更可能说出真实感受。把关系从效率考核中释放出来，本身就是修复。', '["亲密关系", "家庭陪伴", "慢沟通", "情绪连接", "生活节奏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1510, now()),
(101511, '把复杂问题留给连续时间：碎片化输入不适合处理长期选择', '书中批评的不是技术本身，而是连续性被切碎之后，复杂思考失去容器。很多人生问题不能靠零散搜索解决：是否换工作、如何处理长期关系、孩子的教育方向、自己的身心状态，都需要把线索连起来看。可执行练习是“连续时间决策法”：遇到复杂问题时，至少安排两段不低于三十分钟的离线思考。第一段只写事实和感受，不急着定结论；第二段再写可选方案、代价、最小下一步。中间不要用大量新信息淹没自己，只允许查证关键事实。碎片化输入适合提醒和收集，不适合承载整个人生判断。给复杂问题连续时间，是对自己负责，也是减少冲动决定和反复后悔的重要方法。', '["深度思考", "决策质量", "连续时间", "长期规划", "认知清晰"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1511, now()),
(101512, '速度会传染：用环境设计降低“别人都很急”带来的焦虑', '速度不只是一种个人选择，也会通过环境传染。身边人都在秒回、倍速、赶进度、同时开多个窗口时，一个人很容易把慢误解成落后，把休息误解成浪费。书中把速度称为会扩散的力量，提醒我们不能只靠意志抵抗。练习可以从环境设计开始：把手机主屏只留下必要工具；给常用社交软件设置固定查看时段；工作区放一张纸写下今天最重要的一件事；和家人或同伴约定一段共同不看手机的时间。还可以准备一句边界话术：“我会在今晚八点前回复你，现在先把手头这件事做完。”当外界速度很快时，边界不是拖延，而是保护判断力。你不需要跟上每一种急迫，只需要回应真正重要的事。', '["环境设计", "社会压力", "焦虑调节", "节奏感", "自我边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1512, now()),
(101513, '预设你的慢速世界：给生活保留几个不可外包的节奏锚点', '书的结尾并不是要求人们回到没有互联网的时代，而是建议在快速社会中主动预设慢速世界。慢速世界不是宏大的逃离，而是几个稳定的节奏锚点：固定的睡前离线、每周一次长散步、定期读纸质书或长文、认真写日记、与家人朋友面对面聊天、给重要决定留出过夜时间。选择锚点时要小而稳定，不要一次设计完美生活。可以先选三个：一个身体锚点，如固定睡眠仪式；一个关系锚点，如每周不带手机吃一顿饭；一个思考锚点，如周末二十分钟复盘。慢速锚点的作用，是在外界不断加速时提醒你：生活不只由效率定义。一个人能否长期成长，常取决于是否为自己保留了不被打断的节奏。', '["生活节奏", "慢时间", "自我照顾", "习惯设计", "长期成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1513, now()),
(101514, '把改变看成“人、信息、环境”的共同微调，而不是单靠意志力', '《引爆点》的核心启发不是“制造流行”，而是：许多行为改变并不完全取决于一个人有没有决心，它常常由三类因素共同推动——谁在传递影响、信息是否容易记住并转化为行动、所处环境是否给出支持性线索。用于心理成长和亲子沟通时，这个框架能帮助我们把“你怎么总改不了”转换成“我们还缺哪一个条件”。例如，孩子写作业拖延，可能不是单纯懒散，而是提醒方式太抽象、书桌旁诱因太多、身边缺少一个稳定陪伴者；伴侣沟通反复争吵，也可能是谈话总发生在疲惫时段、双方只听到指责而听不到下一步请求。可执行练习：选一个想改变的小行为，画三栏清单。第一栏写“关键关系”：谁的陪伴、示范或提醒最容易被接受；第二栏写“信息附着力”：能否把目标写成一句具体行动，如“晚饭后手机放客厅充电”；第三栏写“环境线索”：可以移走什么干扰、增加什么提示、把哪一步变得更容易。先只调整一处，观察一周。提醒：这个框架不是给人贴标签，也不是操控他人，而是降低改变的摩擦，让好选择更容易发生。在后台知识库里使用时，可把它作为“问题拆解卡”：当用户输入“孩子不听话”“我坚持不了”“家里总吵架”时，先返回三要素检查，而不是直接给训诫。还可以提示用户记录“改变前后的微小差异”，例如换了提醒人、换了时间、换了空间后，阻力是否下降。这样能让用户体验到改变来自系统优化，而不是人格缺陷。实践时还要保留“暂停点”：如果调整后关系更紧张，先停止扩张，回到倾听和确认需求。改变的节奏宜小、慢、可观察，避免把新方法变成另一种控制。', '["行为改变", "小改变", "环境线索", "自我觉察", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1514, now()),
(101515, '关键关系节点：用联系员、内行和支持型表达者搭建帮助网络', '书中把推动信息扩散的关键人物分为联系员、内行和推销员。放到 App 端知识库中，可以转化为一种温和的关系支持模型：联系员不是“人脉高手”，而是能把不同圈子、资源和经验连接起来的人；内行不是权威压制者，而是愿意认真比较信息、提供可靠经验的人；支持型表达者则能用有感染力、让人放松的方式鼓励行动。适用场景包括：家长不知道向谁请教青春期沟通，个体在低谷中不知道如何求助，伴侣需要找到更合适的第三方资源。可执行练习：画一张“支持网络地图”，写下三类名字：谁能帮我连接资源，谁能提供可信知识，谁能让我更有力量地迈出一步。每类不求多，1—3人即可。接着为每个人设计低负担请求，如“能否推荐一本适合亲子沟通的书”“能否帮我一起梳理一次沟通脚本”。提醒：不要把这些人当作替你说服别人的工具，也不要把求助变成情感勒索。关键关系节点的价值，在于让信息、陪伴和行动更顺畅地流动，而不是制造压力。在后台知识库里，这条可用于“我不知道该找谁帮忙”的检索意图。系统可引导用户区分三种求助：情绪陪伴、信息判断、资源连接。若用户暂时没有现实支持者，也可以先从低风险关系开始，如学校老师、社群管理员、同事中愿意分享经验的人。练习后可追问：这次求助让我更清楚了什么？我是否仍保有自己的选择权？使用这张地图时，也要标出“不适合求助的人”：会嘲笑、泄露隐私、习惯命令你的人暂不纳入核心支持圈。支持网络的质量比数量更重要。记录一次实际尝试，比空想完整方案更有帮助。', '["关系支持", "关键节点", "求助网络", "社群支持", "资源连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1515, now()),
(101516, '让建议有附着力：把抽象道理变成“看得见、做得到、能重复”的下一步', '“附着力”可以理解为：信息不仅被听见，还能被记住、理解并引出具体行动。很多亲子沟通和自我成长建议之所以无效，不是因为道理错，而是太抽象。例如“你要自律”“你要好好沟通”“你要多关心自己”都缺少时间、地点和动作。书中关于健康小册子、儿童节目的案例提示我们，微小的呈现方式会改变行动结果：具体地图、明确时间、互动提问、适度重复、符合对象理解方式的叙事，都能让信息更容易被吸收。可执行练习：把一个建议改写成“四件套”。第一，行为一句话：我希望做什么；第二，场景一个点：在什么时候、哪里做；第三，提醒一个物：用便签、闹钟、固定位置或同伴提示；第四，复述一次：请对方用自己的话说说下一步是什么。给孩子提要求时，可把“别磨蹭”改成“洗漱后把作业本放到餐桌左边，我会在7点半陪你看第一题”。给自己设目标时，可把“我要放松”改成“睡前10分钟关灯做三轮呼吸”。提醒：附着力不是把信息包装得刺激，而是降低理解成本和执行成本。在 App 呈现时，可以把它做成“建议改写器”：用户输入一句抽象目标，系统帮助改成可执行版本。亲子场景尤其需要避免一次塞入多个要求，因为孩子会记住情绪而忘记步骤。更好的做法是先确认一个最小动作，完成后再加下一步。复盘时不问“你为什么没做到”，而问“哪一步不够清楚、太难或没有提示”。如果对方没有马上行动，可先检查是否缺少材料、时间或陪伴，而不是立刻升级为批评。真正有附着力的信息，通常让人知道“现在就能先做哪一步”。', '["信息附着力", "可执行建议", "沟通表达", "习惯养成", "重复练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1516, now()),
(101517, '环境威力：先调整日常线索，再评价人的性格或动机', '环境威力法则提醒我们：人的行为会受到具体情境、秩序信号、时间压力和周围暗示的影响。用于心理成长时，它能帮助我们少一点“他就是不自觉”“我就是没救了”的归因，多一点可改变的设计。比如，神学院学生是否停下帮助别人，受“是否赶时间”影响很大；地铁里的涂鸦、逃票等秩序信号，也会改变人们对规则和安全的感受。家庭中也常见类似机制：餐桌上总放着手机，亲子谈话容易被打断；睡前灯光太亮，情绪更难降下来；家里只在出错时说话，孩子会把沟通和被批评绑定。可执行练习：做一次“环境线索盘点”。选一个反复出现的困扰，写下它通常发生的时间、地点、前一个动作、在场的人和周围物品。然后做一个小改动：把诱发冲突的物品移开，把提醒换成可视化清单，把困难任务拆成先做两分钟，把重要谈话移到双方不赶时间的时段。提醒：强调环境不是否认责任，而是承认责任需要可承载的场景。先把场景变友好，人的选择才更容易稳定。在知识库检索中，这条适合回应“我是不是性格太差”“孩子是不是天生自控差”等自责或标签化问题。可提醒用户先寻找情境变量：饥饿、疲劳、赶时间、噪音、空间拥挤、隐私不足、任务过大、是否有人旁观。每次只改一个变量，才知道什么有效。若环境已调整仍持续痛苦，再考虑寻求更专业的支持，而不是仓促归因。这个练习也适合自我觉察：当自己反复失控时，先记录前因后果，而不是用“我太差了”总结。记录越具体，越容易找到可替换的触发点。记录一次实际尝试，比空想完整方案更有帮助。', '["环境威力", "行为线索", "非评判", "家庭沟通", "情境设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1517, now()),
(101518, '小群体支持：稳定改变往往发生在彼此认识、能持续练习的关系里', '《引爆点》关于小群体和“150规则”的讨论，对亲子与关系支持很有价值：观念要持续，不只靠一次触动，而要有能交流、练习和互相看见的群体。书中提到，读书小组让一本书变成共同谈话和情感体验；宗教小组通过定期聚会巩固信念；组织规模过大时，人们难以彼此熟悉，信任、同伴压力和“知道该问谁”的互动记忆都会下降。转化为 App 场景，可以理解为：支持系统越具体，改变越容易落地。可执行练习：为一个成长目标建立“最小支持小组”，人数可以从2—5人开始，如一个家长同伴、一个可信朋友、一个家庭成员。约定固定频率和固定问题：本周我做到了什么，卡在哪里，下周只练哪一步。家庭内部也可做“角色记忆”：谁负责提醒日程，谁擅长安抚情绪，谁负责查资料，避免所有负担落在一个人身上。提醒：小群体不是拉帮结派，也不是让成员互相监督到窒息，而是让每个人被看见、能贡献所长、能在安全范围内反复练习。这条也适合用于线上社群运营：不要只追求大群人数，而要设计小组内的稳定互动。比如家长成长营可以拆成固定三人组，每周只讨论一个真实场景；伴侣练习可以设置“倾听者、表达者、记录者”角色轮换。小群体的关键指标不是热闹，而是成员是否逐渐知道彼此擅长什么、需要什么、可以怎样互相提醒。如果小组中有人沉默，不急着要求表达，可以允许文字记录、表情评分或只旁听一次。安全感先于深度分享，稳定性先于热烈气氛。记录一次实际尝试，比空想完整方案更有帮助。保持边界。', '["小群体", "社群支持", "150规则", "互动记忆", "持续练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1518, now()),
(101519, '转换者的价值：把专业建议翻译成身边人听得懂、愿意试的语言', '许多有帮助的知识卡在“翻译”环节：专业人士说得准确，使用者却觉得遥远；家长说得用心，孩子却只听见控制；伴侣讲的是需要，对方听成指责。书中“转变力量”的启发是，信息从创新者或专业圈层进入大众生活，常需要中间人把它删繁就简、保留要点、换成目标人群熟悉的语言和场景。健康传播从教堂转向美容院、依靠发型师讲故事的案例，也说明可信关系和自然场景比单向宣讲更容易被接受。可执行练习：当你想传递一个心理成长建议时，先做“三次翻译”。第一次，把专业词换成生活词，如把“情绪调节”说成“先让身体慢下来”；第二次，把原则换成场景，如“吵起来前先喝水离开三分钟”；第三次，让对方改写，问“如果换成你的话，你会怎么做”。在亲子沟通中，可以邀请孩子参与翻译规则，而不是只宣布规则。提醒：转换不是歪曲事实，也不是讨好对方；它是在尊重对方经验的基础上，让有用信息进入真实生活。在 App 端可把它用于“知识太难听不进去”的场景。系统可以建议用户先找到对方熟悉的比喻：对孩子用游戏关卡，对伴侣用共同生活片段，对自己用身体感受。还可提醒：如果一句话让对方立刻防御，可能不是内容无效，而是语言没有进入他的经验世界。先换说法，再判断对方是否愿意合作。翻译完成后，可以用一个检验问题：“这句话会让对方更靠近行动，还是更想防御？”如果答案是后者，继续降低姿态、减少术语、增加选择。记录一次实际尝试，比空想完整方案更有帮助。先听后说，再稳妥行动。', '["信息翻译", "亲子沟通", "可信关系", "生活化表达", "知识转化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1519, now()),
(101520, '同伴脚本会影响青少年：少渲染高风险行为，多提供安全表达方式', '书中关于青少年吸烟、模仿和封闭同伴世界的讨论，对亲子沟通的提醒是：青少年的许多行为并不只是知识不足，也不只是“叛逆”，还可能来自同伴中的身份脚本、模仿许可和表达方式。如果成年人只反复灌输危害，孩子可能听到的是“你不懂我”；如果媒体或同伴把某些高风险行为讲得戏剧化，脆弱者可能获得一种错误的表达模板。适用场景包括：孩子突然模仿某种危险挑战、沉迷带有攻击或自毁色彩的网络叙事、用极端语言表达不被理解。可执行练习：第一，少追问细节和少做猎奇讨论，避免把高风险脚本讲得更具体；第二，把注意力转向感受和需要，问“你在那个圈子里最想被看见的是什么”；第三，提供替代表达，如运动、创作、求助暗号、同伴互助小组、与可信成人的固定联系；第四，和学校或专业支持者建立沟通。提醒：不要把青少年贴成“问题孩子”，也不要只靠恐吓。更有效的是减少危险脚本的吸引力，同时增加被理解、被接纳、能求助的路径。这条在内容审核和推荐中也很重要：关于高风险行为的知识应强调求助、陪伴、替代行动和支持资源，避免提供过程性、戏剧化、可模仿的叙述。对家长来说，重点不是监控所有同伴，而是创造孩子愿意回到成人世界的入口：每天一个不评价的聊天窗口、一个可以发暗号求助的规则、一个出事后先保证安全再讨论责任的约定。如果孩子已经出现明显危险信号，家庭练习不能替代现实介入；此时重点是陪同、告知可信成人、减少独处风险，并把求助描述成保护而非惩罚。记录一次实际尝试，比空想完整方案更有帮助。', '["青少年支持", "同伴影响", "风险预防", "安全表达", "亲子关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1520, now()),
(101521, '信息过载会产生“免疫”：减少轰炸，增加信任、时机和面对面回应', '《引爆点》后记讨论了信息交流中的“免疫力”：当电话、邮件或通知太多，人们会变得更短、更慢、更有选择性，甚至直接不回应。这个观点可以用于家庭和关系沟通。很多家长以为提醒越多越有效，伴侣以为解释越长越能被理解，App 也可能以为推送越频繁越能促进行动；实际结果可能相反，对方形成屏蔽和防御。适用场景包括：孩子对唠叨自动关机，伴侣看到长消息就逃避，用户对成长提醒麻木。可执行练习：做一次“沟通减量”。把同一个主题的提醒从多次压缩为一次，把长篇道理压缩为一个请求，把线上追问改成约定时间的面对面谈话。发送重要信息前问三句：对方现在有接收空间吗？这条信息和他真正关心的问题有关吗？我能否通过可信关系而不是高频轰炸来传递？家庭中可设“低噪音时段”，只讨论一个议题，只提出一个下一步。提醒：沟通效果不等于信息数量。越是重要的内容，越需要合适时机、简洁表达和稳定关系来承载。这条也能提醒产品设计：心理成长类 App 不应把“更多推送”当成更强支持。对敏感关系议题，低频、高相关、可选择的提醒更可能被接收。可以让用户自己选择提醒时间、提醒语气和是否需要复盘；对亲子沟通内容，建议先让家长练习一次线下表达，再发送给孩子。关系里的信任感，是信息穿透免疫的前提。当必须线上沟通时，也可以先发一句“我想谈一件事，什么时候方便”，给对方选择权。被尊重的接收者，才更可能认真处理重要信息。记录一次实际尝试，比空想完整方案更有帮助。', '["信息免疫", "沟通减量", "数字边界", "信任关系", "有效提醒"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1521, now()),
(101522, '有限资源集中在关键点：用低成本小实验验证改变是否有效', '书中结尾强调，改变不一定从宏大方案开始，有限资源如果集中在关键位置，也可能产生明显效果。美容院健康传播、图书馆小额项目、问题学校教师团队等案例都说明：真正有效的干预常常不是“面面俱到”，而是找到合适场景、合适信使、合适信息，并持续观察反馈。用于 App 端成长知识库时，可以把它转化为“小实验思维”。适用场景包括：家庭想改善早晨混乱，个人想建立运动习惯，团队想推广一种更温和的沟通方式。可执行练习：设计一个两周实验。只选一个对象、一种行为、一个场景、一个指标。例如“晚饭后10分钟亲子无评价聊天”，指标不是孩子立刻改变，而是是否能连续完成、冲突是否减少、双方是否更愿意靠近。实验前写下假设，实验中只做小调整，结束后复盘：哪个关系节点起作用，哪句话最容易被记住，哪个环境线索最有帮助。提醒：小实验不是投机取巧，而是尊重现实复杂性。先验证，再扩大；先做可持续的小改变，再谈长期改变。在知识库落地时，可把这条设计成“实验模板”：目标、对象、场景、信使、提示物、观察指标、复盘日期。指标要尽量温和，如“是否少一次争吵”“是否更快恢复连接”“是否愿意继续练习”，而不是要求立刻变成理想状态。实验失败也有价值，因为它排除了一个无效方案。持续的小实验会让用户从无力感回到可行动感。复盘时建议同时记录有效因素和无效因素，避免只盯失败。每一次微调都在积累家庭或个人的“改变说明书”，以后遇到类似问题可复用。记录一次实际尝试，比空想完整方案更有帮助。', '["小实验", "资源聚焦", "反馈复盘", "行为设计", "可持续改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1522, now()),
(101523, '隐性心理虐待：当伤害没有外伤，却持续改变你的生活', '概念：隐性心理虐待不是一次争吵、一次冷淡或一段普通冲突，而是长期、重复、隐蔽地削弱一个人的现实感、自我价值和生活功能。它常发生在私下，伤害方在外界可能维持体面形象，被伤害者却显得焦虑、混乱、情绪化，甚至说不清自己到底遭遇了什么。因此，判断重点不是对方偶尔是否温和，而是这段关系是否持续让你缩小、失眠、害怕、孤立和自责。识别信号：你越来越不相信自己的判断；总在复盘“是不是我太敏感”；为了避免对方不快而长期压抑需求；与某人互动后明显胸闷、胃痛或精疲力尽；朋友、工作、兴趣、金钱或行动自由被慢慢缩小；你发现自己为了证明“我没有错”而反复解释，却越解释越混乱。外界看不到伤痕，不等于伤害不存在。安全边界：不要把私人记录、求助计划和脆弱信息暴露给可能利用它们的人；不要把“让对方承认”当作安全前提。先在安全设备上记录事件、感受、身体反应和生活影响，优先联系可信任的人或专业支持。如果暂时无法离开，也可以先做低风险保护：减少即时回复，保存重要证件和财务信息，恢复一个不受对方控制的联系渠道。恢复练习：连续两周做三列记录：“发生了什么事实—我身体/情绪有什么反应—这件事如何影响我的生活功能”。每次只写十分钟，写完做一个落地动作，如喝水、洗脸、看窗外或摸到脚踩地。两周后只回答一个问题：这段关系让我的生活更自由、更稳定，还是更恐惧、更萎缩？这个答案可以成为下一步求助和设界限的起点。使用提示：如果你还不确定这是否是心理虐待，可以先不急着命名关系，只追踪“接触前、接触中、接触后”的身体变化。身体往往比理智更早知道危险。把观察交给时间，而不是交给对方解释。连续记录后，再决定是否需要求助或调整距离。下一步只需选择一个可以在今天完成的微行动，并在完成后给自己一个明确的结束信号。小步、可重复、可停止，是创伤恢复中很重要的安全感来源。', '["隐性虐待", "心理虐待", "识别信号", "自我保护", "创伤知情", "关系支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1523, now()),
(101524, '从“我是不是有问题”到“我是幸存者”：停止把责任全部揽到自己身上', '概念：“幸存者”不是要求你马上坚强、原谅或感谢经历，而是提醒你：能够在长期混乱、贬低和自我怀疑中继续生活，本身就是一种生命力。隐性虐待常让人把矛头指向自己：如果我更懂事、更会沟通、更少需要、更能忍耐，也许就不会被这样对待。书中强调，很多幸存者具备反思、自省、愿意修复关系的能力，这些品质本来珍贵，却可能在不健康关系中被反复利用。识别信号：你把对方的持续伤害解释成自己的“不够好”；为了维持关系不断降低底线；一边痛苦一边替对方找理由；接受“你太脆弱、太敏感、太难相处”的标签；在求助时仍担心自己是在夸大事实；即使已经很疲惫，仍觉得只要自己再改变一点，对方就会停止伤害。自责会让人误以为痛苦有解，但它也会遮住真正的风险来源。安全边界：把“我需要成长”和“别人可以伤害我”分开。你可以承认自己有需要学习的沟通方式，但不必承担他人长期羞辱、控制、孤立或扭曲现实的责任。选择咨询或支持时，也要保护自己：如果某个帮助者过早要求你和解、把所有问题都归为双方各打五十大板，或忽视你的安全感，可以暂停并寻找更懂创伤和心理虐待的支持。恢复练习：画一个“责任圆”，分成三块：我的选择、对方的行为、环境限制。把每个事件放入相应区域，再写三句替代性自我叙述：我当时为什么会那样反应、我试图保护什么、我现在能给当时的自己什么支持。最后写一句确认：“我可以为自己的恢复负责，但我不需要为别人对我的伤害负责。”当自责再次出现时，先回到这张图，而不是回到对方给你的评价里。使用提示：当自责很强时，先问自己三个问题：如果朋友经历同样的事，我会怎样看待他？我是否把对方的选择也算到自己头上？我现在最需要的是惩罚自己，还是保护自己？把答案写下来，作为下一次自责来临时的替代声音。', '["幸存者", "自责", "自我价值", "心理边界", "创伤恢复", "非诊断化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1524, now()),
(101525, '心理虐待可能出现在哪里：亲密关系、家庭、友谊与职场的共同警讯', '概念：隐性心理虐待不只发生在亲密伴侣之间，也可能发生在父母子女、兄弟姐妹、朋友、同事、上下级或小团体里。判断重点不在对方的身份、性别、学历或外在形象，而在互动模式是否持续削弱你的自主、安全和现实感。一个人可以在公开场合友善、负责、受欢迎，同时在私下或特定关系中让你长期恐惧和自我怀疑。识别信号：在亲密关系中，对方在外体贴得体，私下却让你长期紧张、孤立或自我怀疑；在家庭中，你被固定为出气筒、替罪羊，其他成员默认你应该承受；在友谊中，对方贬低你的其他关系，让你为正常边界感到内疚；在职场中，某人通过排斥、贬损、抢功、散播不实信息或制造持续不确定感，让你逐渐失去信心和行动力。安全边界：按场景设置保护。亲密或家庭关系中先保护证件、资金、住处、通讯和支持网络；职场中保留客观记录，减少口头单独沟通，必要时寻求人事、法律或行业内支持；友谊中降低信息暴露度，不再分享会被反复利用的脆弱点。不要急着让所有人相信你，因为有些旁观者可能已经被对方的外在形象影响。先让自己拥有至少一个安全出口。恢复练习：画一张“关系生态图”，把身边人分为安全、观望、风险三圈。每周选择一个安全圈的人恢复低强度联系，例如散步、简短电话或共同完成一件小事。目标不是立刻讲完整故事，而是先让生活重新拥有见证者和支持点。若你发现所有关系都被某个人过滤、解释或控制，把“恢复一个独立联系”作为本周最小目标；哪怕只是保存一个热线、咨询机构或可信同事的联系方式，也是在扩大出口。使用提示：不同场景的出口不同。家庭可能需要住处和证件，职场可能需要记录和第三方见证，友谊可能需要信息节食。先选与你处境匹配的一条最小路径，不必一次解决所有关系。能先减少一个风险点，就已经是恢复主动权。', '["关系场景", "家庭关系", "职场关系", "亲密关系", "支持网络", "安全计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1525, now()),
(101526, '学习阶段：给混乱命名，但不把全部精力交给“研究对方”', '概念：康复第二阶段的重点是学习。学习不是为了给对方贴诊断标签，也不是为了掌握操控技术，而是为了让幸存者终于拥有语言描述“我经历了什么”。当一种伤害长期没有名字，人很容易以为混乱来自自己；当它被命名，羞耻和孤立感会下降。知识的作用是把模糊的恐惧变成可观察的模式，而不是让你继续围着伤害方旋转。识别信号：你被要求相信与自己记忆相反的版本；你的名誉或关系被悄悄破坏；旁人被拉入冲突让你更孤立；关系在极好和极坏之间摆动，让你不断等待“好的一面”回来；你曾被迅速理想化，又被突然贬低或抛下。学习这些概念时，只需关注它们如何帮助你理解自身经历，不需要把每个术语都变成对对方的判决。安全边界：把知识当作地图，而不是把自己困在地图里。不要在不安全的对话中抛出术语和对方争辩，这可能让你暴露更多信息；不要沉迷检索到深夜，过度研究会让创伤系统一直处于警戒状态；不要把每个细节都交给不可信任的人评判。设置“学习停止线”：当你开始心跳加速、想连续搜索、想立刻发长消息证明自己时，先暂停二十分钟。恢复练习：建立一张“命名而不纠缠”表格，四列分别写：事件、我当时被迫相信什么、我现在知道的事实、我下一步要保护什么。每周只选择一到两个概念学习，并在学习后做五分钟落地练习：看见身边五样物品、感受双脚踩地、喝水或伸展。每次学习后问自己：这个知识让我更清醒、更安全，还是让我更耗竭？只保留能服务恢复的部分。使用提示：学习术语后，可以把手机闹钟设成“回到自己”。提醒响起时，停止阅读十分钟，做一件与伤害无关的事。能停止研究，也是一种恢复掌控感的练习。知识服务于安全和复原，不服务于无尽复盘。下一步只需选择一个可以在今天完成的微行动，并在完成后给自己一个明确的结束信号。小步、可重复、可停止，是创伤恢复中很重要的安全感来源。', '["学习阶段", "煤气灯效应", "恶意宣传", "间歇性强化", "心理教育", "安全边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1526, now()),
(101527, '绝望阶段的第一任务：先稳定和保命，再慢慢做决定', '概念：康复第一阶段被称为“绝望”，不是因为你注定无望，而是因为许多人在刚求助时已经情绪混乱、焦虑、抑郁、麻木、崩溃，甚至不确定自己是否还能继续。这个阶段最重要的不是马上复盘全部关系，也不是立刻做出完美决定，而是让身心先回到足够安全、足够稳定的状态。绝望阶段需要的是照明灯，不是审判锤。识别信号：你觉得生活失控，却说不清原因；反复问“我到底怎么了”；无法集中注意力，睡眠、食欲和工作功能明显下降；快乐和能量像被抽空；出现伤害自己的念头，或觉得“不能再这样继续下去了”；你对任何建议都感到太难，因为神经系统已经长期处于过载。此时的迟钝、哭泣、麻木或摇摆，都可以理解为创伤反应。安全边界：把边界具体到当天。如果有自伤风险，先联系当地急救、危机热线、可信任的人或去急诊；把危险物品与自己拉开距离；暂停与伤害方的高冲突沟通；在重大决定上给自己缓冲，但对人身安全、孩子安全、住所安全和医疗需求要立即行动。不要把“我还没想清楚未来”误解为“我不能保护今天的自己”。恢复练习：写一张24小时稳定卡，放在手机备忘录和纸上。内容包括三个人名（可以联系的人）、三个地点（能让你安全停留的地方）、三件身体照顾（吃一点东西、洗热水澡、睡前远离争吵信息）、三句稳定语（例如“此刻我先活过今天”“我不需要今晚解决一生的问题”“我的反应有原因”）。如果只能完成一件事，就选择让身体更安全的一件事。每过24小时重新评估；绝望阶段的胜利常常只是多撑过一天、多获得一个支持点。使用提示：绝望时不要用未来十年的标准要求今天的自己。今天的目标可以只是安全吃一顿饭、睡一小段、把求助信息发给一个人。微小稳定会为后续清醒留下空间。若今天只能完成一件事，就选最能降低危险的那一件。', '["绝望阶段", "危机稳定", "安全计划", "情绪支持", "自我保护", "创伤反应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1527, now()),
(101528, '清醒阶段：顿悟、愤怒和反复摇摆都可以是恢复的一部分', '概念：清醒阶段常伴随“原来如此”的顿悟。你开始把绝望与长期心理虐待联系起来，也能用新的语言描述经历。清醒会带来力量，也可能带来悲伤和愤怒：悲伤是因为你看见自己失去了什么，愤怒是因为你终于意识到那些伤害并非都由你造成。这个阶段并不总是直线上升，人在清醒后重新跌回绝望、再回到清醒，是常见的恢复节奏。识别信号：你突然能看懂过去许多细节；不断想说“对方怎么能这样对我”；想把证据发给所有人解释；一边觉得自由，一边又被好回忆拉回去；对自己过去的忍耐感到羞耻或愤怒；看到相似情节时身体立刻紧绷。清醒不是一次性完成的开关，更像反复擦亮的镜子，每一次看清都可能伴随新的哀悼。安全边界：把清醒转化为保护，而不是冲动行动。愤怒可以提醒你哪里被侵犯，但不一定要立刻变成控诉长信、深夜对峙或公开撕扯；在法律、孩子、工作或共同财务牵涉较深时，先咨询可靠支持再行动；把“我要让对方承认”调整为“我要让自己更安全”。如果想发消息，先写在备忘录里，隔24小时再决定是否需要发送。恢复练习：做一条关系时间线，只写客观节点：关系开始、第一次明显不舒服、第一次自我怀疑、第一次求助、第一次设边界。每个节点后写“当时的我已经在努力什么”。再写一封不发送的信，允许自己表达愤怒、悲伤和失望。最后把信收好或销毁，用一个小动作结束练习，例如洗手、开窗或走十分钟，让身体知道练习已经结束。若清醒后又开始怀疑自己，回看时间线，而不是只回看对方偶尔温和的片段。使用提示：清醒常带来“我为什么当时没看见”的懊悔。把这句话改成“我当时看见了我能承受的部分”。创伤恢复不是审判过去的自己，而是把现在的自己带到更安全的位置。每次看清，都是把选择权拿回一点。下一步只需选择一个可以在今天完成的微行动，并在完成后给自己一个明确的结束信号。小步、可重复、可停止，是创伤恢复中很重要的安全感来源。', '["清醒阶段", "顿悟", "愤怒", "悲伤", "关系时间线", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1528, now()),
(101529, '界限阶段：脱离接触、断绝往来与信息边界的安全做法', '概念：界限阶段是在识别、学习和清醒之后，把注意力从“理解发生了什么”转向“我如何保护自己”。书中区分了脱离接触和断绝往来：前者可能仍有必要互动，但在情感卷入、时间投入和信息暴露上减少；后者是在条件允许时切断联系，让身心远离持续毒性。两者都不是口号，而是由幸存者根据安全、现实限制和恢复需要做出的选择。识别信号：每次接触后你都情绪崩溃或自我怀疑；你的边界被嘲笑、惩罚或反复测试；对方要求你解释隐私、交出资源或放弃支持网络；你发现自己为了避免冲突而不断牺牲睡眠、工作、金钱和尊严；你越解释，对方越把解释变成新的争论材料。需要界限的地方，往往正是你反复失去能量的地方。安全边界：界限要短、清晰、可执行。减少单独高情绪沟通；必要沟通尽量书面化、事实化；不再提供会被利用的个人信息；提前决定哪些话题不谈、哪些渠道不用、哪些行为出现就结束互动。若涉及同住、共同抚养、共同工作或安全威胁，先和可信支持者制定计划，不把撤离计划暴露给伤害方。界限不是惩罚对方，而是保护你的恢复空间。恢复练习：列出所有接触渠道：见面、电话、短信、社交媒体、共同朋友、财务、工作。给每项标绿黄红：绿色可保留，黄色需限制，红色需停止或转交第三方。为一个黄色渠道写“如果—那么”句式，例如“如果对话开始贬低我，那么我只回复事实并结束沟通”。执行后记录身体反应，而不是马上评估对方是否满意。界限的价值在于执行，不在于说服对方喜欢它。使用提示：界限开始后，内疚和想解释的冲动可能很强。可以准备一句短句反复使用，如“我现在只讨论具体事项”。短句不是冷漠，而是帮助你不再被拉回消耗性的循环。越重要的边界，越需要提前写下来并请安全的人见证。下一步只需选择一个可以在今天完成的微行动，并在完成后给自己一个明确的结束信号。小步、可重复、可停止，是创伤恢复中很重要的安全感来源。', '["界限阶段", "脱离接触", "断绝往来", "信息边界", "安全撤离", "执行计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1529, now()),
(101530, '恢复阶段：把被夺走的生活一点点拿回来', '概念：恢复阶段的一个重要迹象，是你开始愿意把时间花在与虐待和康复研究无关的事情上。你可能重新对爱好、身体、财务、住所、节日、朋友或未来计划产生兴趣。这不是逃避，而是生命力回到你身上的表现。隐性虐待常偷走的不只是关系本身，还包括重要纪念日、稳定收入、身体健康、情绪平衡、物品、社交和对生活的期待。识别信号：你不再每分钟都想搜索相关资料；开始想整理房间、修复预算、看医生、运动或学习新技能；对被毁掉的假期、生日、工作机会或物品感到哀伤；既期待新生活，又因为恢复速度不够快而灰心；你会突然发现自己很久没有问“我喜欢什么”。这些变化说明注意力正在从求生模式，慢慢回到生活本身。安全边界：允许恢复慢一点，并保护新生的兴趣不被再次吞没。不要急着进入新关系来证明自己好了；不要强迫自己立刻原谅；不要把所有钱、时间和注意力再次交给会消耗你的人；不要让旁人的催促决定你的节奏。恢复期也要设置资源边界：每周可用于处理创伤的时间、可谈论的人、可承担的任务，都需要根据体力和情绪容量调整。恢复练习：建立“四栏恢复表”：身体、金钱、空间、喜悦。身体栏写一个可执行照顾，如预约体检或每天走十分钟；金钱栏写一个小步骤，如查看账单、建立独立预算；空间栏写一个动作，如清理床头或更换让你不舒服的物品；喜悦栏写一个低成本活动，如听歌、做饭、画画、看展。每周只完成每栏一个小动作。若某天又被旧情绪拖回去，不要把它视为失败，只把当天任务缩小到喝水、吃饭、睡觉、联系一个安全的人。使用提示：恢复期可以把快乐也当成康复任务。不要等完全不痛了才生活。一个稳定的早餐、一次散步、一件喜欢的衣服，都在告诉神经系统：生活不只由伤害定义。把快乐做小，才更容易持续。', '["恢复阶段", "生活重建", "身体照顾", "财务恢复", "兴趣重建", "耐心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1530, now()),
(101531, '维持阶段：过“干净”的生活，并把接近你当作需要被赢得的权利', '概念：维持阶段并不意味着永远没有触发、永远不想起过去，也不意味着你从此不会遇到不健康的人。它更像是拥有一套稳定的内在工具：能更快识别风险，更早设界限，更愿意相信自己值得平静、真诚和被尊重的关系。维持也包括重新认识自己：经历康复后，你可能已经不是过去那个会默认忍耐的人，旧的圈子、旧的自我评价和旧的关系规则不再适合你。识别信号：你能在别人身上更快看见红色警报；不再把所有好时刻当作危险关系会改变的证明；开始怀疑“我是否配得上更好的生活”；可能因为不习惯被善待而推开稳定的人；需要重新定义高质量生活。维持阶段的挑战不是忘记过去，而是在记得过去的同时，不让过去继续决定你允许谁接近你。安全边界：把进入你生活的权利分级管理。能给你打电话、知道你的住处、分享你的隐私、影响你的财务和时间，都不是任何人天然拥有的权利，而是需要通过尊重、稳定、诚实和边界感逐步赢得。把“我是不是太挑剔”换成“这个人是否持续尊重我的边界”。如果新关系让你迅速放弃睡眠、工作、朋友和价值感，就需要放慢速度。恢复练习：写下“高质量生活清单”，具体到日常：我想如何睡觉、工作、花钱、交友、过节、养育孩子或照顾身体。再画一把“接近阶梯”：陌生人、普通熟人、朋友、亲密朋友、伴侣或家人式支持。为每一级写进入条件和退出条件。每月回顾一次：谁让我的生活更清明？谁让我再次缩小自己？如果你发现自己想把健康的人推开，先问：这是当下的危险，还是过去经验留下的警报？使用提示：维持阶段适合定期复盘“进入我生活的规则”。当新人出现时，不只看吸引力，也看稳定性、尊重度和修复能力。慢一点认识别人，是对新生活的保护。能慢下来，本身就是新的能力。下一步只需选择一个可以在今天完成的微行动，并在完成后给自己一个明确的结束信号。小步、可重复、可停止，是创伤恢复中很重要的安全感来源。', '["维持阶段", "高质量生活", "红色警报", "关系筛选", "自我价值", "长期恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1531, now()),
(101532, '给家人和朋友：如何支持一个正在从心理虐待中恢复的人', '概念：幸存者看起来反复、混乱、难以放下，并不代表他们“疯了”或不想好起来。隐性心理虐待的困难在于，它没有明显外伤，却会系统性破坏一个人的自我价值、身份感、信任感和生活功能。支持者若只用普通分手、普通家庭矛盾或普通职场冲突来理解，往往会无意中加重孤立。好的支持不是替对方决定，而是帮助他们重新拥有选择。识别信号：你爱的人在某段关系后变得不像自己；反复讲述细节，像是在确认现实；对特定日期、信息、声音或场景有强烈焦虑；既想离开又会怀念对方的好；担心说出来没人信；有时刚平静一点又突然崩溃。支持者需要理解，这种摇摆常来自长期混乱后的神经系统反应，而不是故意拖累别人。安全边界：不要劝他们马上复合、相亲、原谅或“向前看”；不要主动联系伤害方求证或调解；不要把幸存者的住址、计划、情绪和求助信息透露给可能伤害他们的人；不要要求他们一次讲完整故事。也不要把自己的不理解变成质疑，例如“他看起来不像这种人”。你可以表达疑惑，但不要让幸存者再次承担证明伤害的责任。恢复练习：使用“三步支持句”。第一步相信：“我听见你说这对你伤害很大。”第二步给选择：“你现在想要我倾听、陪你做计划，还是一起找资源？”第三步做小事：“今天我能帮你完成哪一件具体的事？”支持者也可以做一份菜单：陪同就医、临时接送、保管文件、一起吃饭、帮忙筛选咨询资源。若自己感到无力，可以寻求支持者教育，但不要把焦虑转嫁给幸存者。稳定、耐心和保密，比急着给答案更有力量。使用提示：支持者若不知道该说什么，可以少给评价，多给可选择的帮助。比如“我今晚可以陪你吃饭或帮你整理材料，你选一个”。具体、稳定、保密，往往比大道理更有效。陪伴的目标是增加安全，而不是加速对方表现得正常。', '["家人支持", "朋友支持", "陪伴", "相信幸存者", "保密", "支持者指南"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1532, now()),
(101533, '康复日志：把经历外化成记录，让恢复从可观察的小步开始', '概念：康复日志不是为了反复沉浸痛苦，也不是为了凑齐完美证据去说服所有人，而是把混乱从脑内拉到纸上，让你看见模式、感受、选择和进展。书后的日志围绕六个阶段提出问题：绝望时如何保证安全，学习时如何命名伤害，清醒时如何理解顿悟，界限时如何选择接触方式，恢复时如何重建生活，维持时如何定义高质量人生。识别信号：你脑中反复回放同一事件；在不同版本之间摇摆；记不清自己什么时候开始不快乐；想求助却说不清重点；接触某人后情绪大幅波动；总觉得“如果我能把事情想明白，就不会这么痛苦”。这些都是适合开始记录的信号。记录的重点不是写出文学作品，而是把本来缠在一起的事实、感受和选择分开放。安全边界：保护日志本身。把记录放在对方无法查看的地方；避免在高风险设备上保存敏感内容；记录事实和影响，不写会让自己陷入自责审判的长篇控诉；每次记录设置时间上限，结束后做身体安抚。如果回看让你过度痛苦，先停止分析，只标注“这里需要陪伴”，并把它带给可信任的咨询师或支持者。日志应该帮助你恢复掌控，而不是把你困在现场。恢复练习：采用“六阶段一页纸”。页面分六栏：绝望—我今天最需要的安全是什么；学习—我能命名的一个模式是什么；清醒—我现在明白了什么；界限—我今天能减少哪一种暴露；恢复—我想拿回哪一小块生活；维持—我想成为什么样的人。每栏只写三句话。每周回看一次，用不同颜色标出进步、风险和需要支持的地方。让日志成为你的导航仪，而不是伤口反复被打开的地方。使用提示：日志练习结束后要有收尾动作，例如合上本子、深呼吸三次、离开书桌、做热饮。这个动作帮助大脑区分“我在记录过去”和“我现在是安全的”。如果记录后更乱，就缩短时间并增加陪伴。下一步只需选择一个可以在今天完成的微行动，并在完成后给自己一个明确的结束信号。小步、可重复、可停止，是创伤恢复中很重要的安全感来源。', '["康复日志", "自我觉察", "记录练习", "六阶段", "模式识别", "恢复工具"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1533, now()),
(101534, '长期视角与主动投入：把亲密关系当作需要维护的共同生活', '概念：亲密关系不是一次选择后的自动运行，而是一段会随年龄、职业、孩子、健康、经济和家庭阶段不断变化的共同生活。书中强调，伴侣需要准备好营建关系，学习接纳对方的真实样子，而不是把对方改造成自己期待的版本；同时也提醒，缺少共同时间会让关系像缺水的植物一样慢慢枯萎。因此，长期视角和主动投入要放在一起看：既承认关系会变化，也为变化预留可持续的连接方式。适用场景：新婚磨合、孩子出生后疲惫、空巢期重新面对彼此、重大疾病或事业变化后关系失衡，或双方常说“没时间聊”“我们只剩事务交接”时，都适合使用。沟通练习：每人用十分钟回答三个问题：这一阶段我最需要你理解的变化是什么？我仍然欣赏你哪三个部分？未来三个月我们可以如何支持彼此？随后设置三个层级的相处计划：每天十到三十分钟无屏幕交谈，每周一次两人独处，每季度一次半天复盘。边界提醒：长期视角不是要求任何人忍受伤害、暴力、羞辱或持续背叛；主动安排相处也不能变成新的控制。若关系中存在安全风险、严重控制或长期贬低，应先保护身心安全，并寻求可信第三方或专业帮助。应用到 App 时，可把本主题拆成“长期经营”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“长期经营”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["婚姻经营", "长期视角", "高质量陪伴", "关系维护", "阶段压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1534, now()),
(101535, '从事务汇报转向真实表达：让伴侣进入你的内在世界', '概念：沟通不只是交换信息，更是向对方展示自己的内在世界。书中指出，许多关系表面上有大量话语，实际却没有分享真实感受；秘密和长期不表达会滋生不信任。有效交流包括谈日程、兴趣和决定，也包括讲出害怕、失望、孤独、期待和脆弱。对一些人来说，表达感受并不自然，需要学习词汇、时机和安全感。适用场景：伴侣之间只谈孩子、账单、工作安排；某一方更习惯把心事告诉朋友或家人而不是伴侣；发生流产、疾病、丧亲、失业等压力事件后，双方变得疏远或易怒。沟通练习：先用“事件-感受-需要”格式写下三件事，例如“今天开会被否定，我感到羞愧和紧张，我需要被听见而不是被纠正”。每晚选择一件分享。听的人先复述“我听到你感到……你需要……”，再问“你希望我陪你、帮你分析，还是给你一点空间？”每周再安排一次共同兴趣谈话，讨论书、电影、散步、运动或家庭计划，增加可谈内容。边界提醒：真实表达不等于随时倾倒情绪。敏感话题要选择双方有精力、时间和隐私的时刻；如果表达会引发威胁、辱骂或报复，应先建立安全边界。应用到 App 时，可把本主题拆成“真实表达”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“真实表达”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["沟通表达", "情绪命名", "内在世界", "脆弱沟通", "信任建立"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1535, now()),
(101536, '倾听先于建议：把“解决问题”暂时放在“理解对方”之后', '概念：亲密关系中的很多谈话，真正需要的不是答案，而是被认真听见。书中列出几类不善聆听的模式：急着给建议、打断对方、过早安慰、理性说教、把话题转回自己。它们的共同点是让说话者失去空间。好的倾听并非沉默忍耐，而是用注意力告诉对方：你的感受对我重要，我愿意先理解你。适用场景：一方下班后倾诉压力，另一方立刻教他怎么做；争吵中总有人抢话；说话者越来越少分享，只汇报必要事项；伴侣说“你根本没听懂我”。沟通练习：做十五分钟倾听轮换。说话者只讲一件事，听者不建议、不辩解、不举自己的例子，只做三件事：保持眼神或身体朝向；用自己的话复述内容和情绪；问一个开放问题，如“这件事最难的部分是什么？”结束前再问“你现在想要安慰、建议、行动支持，还是只是被陪着？”之后交换角色。边界提醒：倾听不等于同意所有观点，也不等于接受攻击。若谈话中出现羞辱、吼叫、威胁或翻旧账，可以暂停并约定稍后继续；若长期无法安全对话，可引入咨询师或可信第三方。应用到 App 时，可把本主题拆成“积极倾听”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“积极倾听”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["积极倾听", "非评判", "共情回应", "沟通练习", "情绪支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1536, now()),
(101537, '研究彼此的爱的表达方式：不要只用自己习惯的方式去爱', '概念：爱需要落到行动中，但每个人接收爱的方式不同。书中借用“爱的五种表达”：肯定话语、恩慈行动、优质时间、精心礼物和身体爱抚。一个人努力做家务，可能以为自己已经表达了爱；另一个人却真正需要被赞美或被专注陪伴。关系中的误会常来自“我已经付出了很多”与“我仍然感受不到被爱”之间的错位。适用场景：双方都觉得自己在付出，却都不满足；节日礼物、家务分工、身体亲近或陪伴时间反复引发委屈；一方说“你不爱我”，另一方说“我明明做了这么多”。沟通练习：各自写下最近一个月最让自己感到被爱的五件小事，并标注属于哪类表达；再写下三件自己期待但没有发生的事。交换后只提问，不争辩。接着为下一周设计一个“对方语言”的小行动，例如一句具体赞美、一次主动分担、三十分钟无手机陪伴、一份低价但用心的小物、或一个经过同意的拥抱。边界提醒：爱的表达必须尊重意愿，尤其是身体接触和性亲密，不能以“这是我的需要”为理由施压。礼物也不应替代道歉、责任或真实陪伴。应用到 App 时，可把本主题拆成“爱的表达”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“爱的表达”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["爱的表达", "亲密需求", "肯定话语", "服务行动", "身体边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1537, now()),
(101538, '把差异变成互补资源：从“你不正常”转向“我们不同”', '概念：差异本身不是关系失败的证据，它也可能是团队互补的来源。书中用性格、金钱、计划、整洁、社交、时间感等例子说明，伴侣常被彼此的不同吸引，后来又试图消除这些不同，于是产生抱怨和控制。成熟的做法不是证明谁更正确，而是承认双方偏好各有价值和局限，并把差异转化为分工、协商和学习。适用场景：一个人爱计划，另一个人随性；一个人节俭，另一个人重视生活体验；一个人外向爱社交，另一个人需要独处；家务标准、迟到、消费、休闲方式反复冲突。沟通练习：画一张“差异地图”，列出十个维度：金钱、整洁、准时、社交、休息、计划、亲密、育儿、家务、与父母联系。每人标出自己位置，再回答：这个偏好保护了我什么？它给关系带来什么好处？它的代价是什么？接着选择一个最常冲突的维度，设计折中规则，例如共同预算加个人自由账户、每周一次社交加一次安静夜。边界提醒：欣赏差异不等于容忍不负责任。债务隐瞒、成瘾消费、持续失约、家务剥削或社交越界，需要明确责任和后果，而不只是用“性格不同”解释。应用到 App 时，可把本主题拆成“差异协商”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“差异协商”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["差异协商", "性格互补", "金钱观", "生活习惯", "冲突预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1538, now()),
(101539, '冲突中就事论事：把问题摆在桌上，而不是把伴侣推到对立面', '概念：冲突发生时，常见反应是退缩冷战或全面攻击；前者筑墙，后者伤人。书中强调“就事论事”：聚焦具体问题，避免把一次事件扩大成对人格的审判。特别要少用“你总是”“你从不”这类绝对化指责，因为它们会让对方进入防御，而不是解决问题。健康冲突的目标不是让对方投降，而是共同理解问题并尝试可行方案。适用场景：吵架时翻旧账、冷战数天、用讽刺或贬低取胜、每次争论都从小事升级到“你根本不在乎我”；双方明知有未解冲突却不知如何开口。沟通练习：使用五问法：第一，真正的问题是什么？第二，什么时候谈最合适？第三，我是否已经听懂对方观点？第四，有哪些可能解决方案？第五，我们先尝试哪一个？表达时改用“我感到……因为……我希望……”而不是“你就是……”。如果情绪过高，先暂停二十分钟，约定回来继续，不能用暂停逃避。边界提醒：就事论事不适用于正在发生的暴力、威胁或严重羞辱；此时首要是离开危险场景。任何冲突练习都不应要求受伤一方在不安全的状态下继续对话。应用到 App 时，可把本主题拆成“就事论事”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“就事论事”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["冲突修复", "就事论事", "我语句", "冷战处理", "问题解决"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1539, now()),
(101540, '修复伤害的三步：说出受伤、无条件道歉、选择放下报复', '概念：亲密感常因未处理的小伤害逐渐流失。书中把压抑的伤害比作被按进水里的球，迟早会弹回表面；修复需要面对，而不是假装没事。有效修复包含三步：温和而具体地说出自己何时因何受伤；伤害方承担责任并无条件道歉；受伤方在安全和真实改变的基础上，逐步放下报复和反复清算。原谅不是说伤害不重要，而是不让伤害继续主导关系。适用场景：伴侣之间有积压的委屈、旧事一提就爆发、道歉总带“但是”、一方不断用过去错误攻击另一方；也适合小冲突后的日常修补。沟通练习：受伤方使用具体句式：“当……发生时，我感到……，它对我的影响是……，我需要……。”道歉方只回应三点：“我听见了你的受伤；我为我的行为负责；我愿意做的改变是……。”之后一起约定一个可观察行动和复盘时间。边界提醒：原谅不能替代责任、赔偿、戒断、治疗或法律/安全措施。面对暴力、虐待、持续背叛或成瘾行为，必须先停止伤害并建立外部支持；受伤方没有义务在未安全时快速原谅。应用到 App 时，可把本主题拆成“伤害修复”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“伤害修复”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["关系修复", "道歉", "原谅", "亲密恢复", "伤害处理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1540, now()),
(101541, '与父母和姻亲相处：把小家庭边界说清楚，同时保留尊重', '概念：大家庭会深刻影响婚姻。书中区分了从依赖到独立的成长过程，并指出婚后需要形成新的重心：伴侣之间的决策、情感支持和生活安排应逐渐从原生家庭转向小家庭。健康边界不是切断亲情，而是让父母、姻亲和伴侣都知道谁对哪些事有决定权。边界越含糊，越容易出现夹在中间、被控制、被比较或被迫站队。适用场景：父母频繁干预育儿、装修、金钱或节假日安排；一方把所有心事先告诉父母而不是伴侣；经济资助附带控制；伴侣与姻亲冲突时，另一方长期回避。沟通练习：伴侣先私下统一三类边界：信息边界，哪些事只在两人之间讨论；决策边界，哪些事由小家庭决定；探访边界，频率、时长和提前通知规则。再由与父母血缘关系更近的一方负责温和表达：“我们很重视你们，也感谢帮助；这件事我们会自己决定，决定后再告诉你们。”同时为父母保留可参与的空间，如固定探望、共同用餐或节日安排。边界提醒：尊重长辈不等于牺牲伴侣安全。若出现辱骂、操控、财务胁迫或持续挑拨，边界需要更清晰，并减少暴露在伤害中的时间。应用到 App 时，可把本主题拆成“家庭边界”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“家庭边界”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["原生家庭", "姻亲关系", "小家庭边界", "家庭决策", "伴侣联盟"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1541, now()),
(101542, '识别旧伤触发：当下的强烈反应，可能带着过去的影子', '概念：童年和成长经历会影响成年后的亲密关系。书中提到，未被看见的痛苦、控制、忽视、离别、羞辱或条件式的爱，可能在婚后以过度防御、讽刺、退缩、讨好、害怕被控制等方式出现。重要的是把“你太敏感”改成“这个反应背后可能有旧伤”，既不把责任全推给过去，也不否认过去确实塑造了当下。适用场景：某些小事总引发不成比例的愤怒或恐惧；伴侣的一句话让人突然觉得被抛弃、被控制或不被爱；姻亲互动激活旧家庭创伤；双方都困惑为什么同一类冲突反复出现。沟通练习：冲突后做一次触发复盘。每人写下：刚才发生的事实是什么？我身体有什么反应？我脑中自动出现了什么解释？这让我想起过去哪种经历？我真正需要的是安抚、空间、解释、道歉还是界限？分享时另一方只倾听和确认，不急着证明自己无辜。若发现长期创伤线索，可共同寻找咨询支持。边界提醒：理解旧伤不是允许伤害伴侣的通行证。受触发的一方仍需为自己的攻击、冷暴力或控制行为负责；伴侣也不应扮演治疗师，超出能力时要引入专业帮助。应用到 App 时，可把本主题拆成“旧伤触发”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“旧伤触发”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["童年创伤", "情绪触发", "原生家庭影响", "自我觉察", "伴侣支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1542, now()),
(101543, '保护关系边界：面对外部吸引时，及早停止隐瞒和暧昧升级', '概念：关系中的外部吸引不一定来自预谋，常发生在亲密感不足、被理解的需要未被满足、工作或社交边界模糊的时候。书中提醒，真正破坏信任的往往不只是性行为，而是隐瞒、欺骗、情感转移和持续越界。保护关系边界的目的不是制造恐惧，而是承认人会被吸引，同时为重要关系设置清晰护栏：不把伴侣应有的亲密谈话长期交给第三方，不秘密培养暧昧，不在危险情境中测试自制力。适用场景：对同事或朋友产生强烈依恋；开始删除聊天记录、隐瞒见面、比较伴侣；婚内长期缺少关注、赞美或性生活沟通；一方发现信任被破坏但还没到不可修复。沟通练习：先自查三问：这段关系是否需要向伴侣隐瞒？我是否在其中寻求本该与伴侣沟通的情感满足？如果伴侣这样做，我会不会受伤？若答案为是，立即降低接触强度，停止私密倾诉，并向可信支持者或伴侣坦诚风险。伴侣间再讨论缺失的亲密需求和可执行的修复计划。边界提醒：坦诚不等于把细节倾倒给伴侣造成二次伤害；修复需要透明、停止越界和持续行动。若已有背叛、强迫、骚扰或权力不对等关系，应优先寻求专业和安全支持。应用到 App 时，可把本主题拆成“关系边界”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。应用到 App 时，可把本主题拆成“关系边界”微练习：先让用户选出最贴近自己的处境，再分别写下事实、感受、需要和一个可观察请求。练习不追求一次谈透，而追求一次比过去更安全、更具体的互动。复盘时只问三个问题：我们是否按约定停下来听完了？是否出现了新的理解？下一步最小行动是什么？这样既保留书中强调的主动经营，也避免把关系问题简化成谁对谁错。', '["信任边界", "外部吸引", "婚姻保护", "透明沟通", "背叛修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1543, now()),
(101544, '代表性启发式：第一印象很像，不等于概率很高', '偏差概念：代表性启发式是用“像不像某类人、某种结果”替代“真实概率有多大”。相似性有信息价值，但它不能自动代表基率、证据质量和替代解释。书中关于工程师/律师、图书管理员等判断提醒我们：一旦故事很像，人会忘记总体比例。 日常场景：你看到一个沉默、爱整理、重细节的人，就判断他必定内向且不适合销售；伴侣一次冷淡，你立刻推断“不爱我了”；某个博主说话自信、案例完整，你觉得方法一定可靠。这些都是“像”压过“概率”。 自我校准练习：做“三列校准”。第一列写：我觉得它像什么。第二列写：这类情况在总体中大概多常见，例如迟到的人中有多少是人品问题，有多少是通勤、任务、家庭原因。第三列写：至少两个更普通的解释。然后把绝对句改成概率句，比如把“他就是不靠谱”改成“基于三次迟到，我估计近期时间管理不稳概率较高，但还需确认原因”。如果判断会影响关系、合作或自我评价，至少再收集一个不相似但相关的证据，例如长期记录、第三方反馈或对方解释。 App端可实践提示：当用户输入“他就是……”“我一定会……”时，触发第一印象减速器：先问总体，再问个体；先问常见解释，再问戏剧解释；先问证据质量，再问确定感。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["判断偏差", "代表性启发式", "基率", "第一印象", "自我校准", "关系决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1544, now()),
(101545, '小数律：别用几次经历判定一个人、一段关系或一种命运', '偏差概念：小数律偏差是把很小的样本误当成稳定规律。小样本天然更容易出现极端比例，但人会把它看作总体的缩影。书中医院男婴比例案例说明：样本越小，越可能大起大落；把小样本当规律，会制造过度自信和过度绝望。 日常场景：几次成功就觉得自己找到永久秘诀，几次失败就断定“我一直不行”；一次咨询没效果，就否定所有帮助；低落时只从最近几天抽样，于是把“今天很难”写成“我的人生总是这样”。情绪越强，抽样越偏。 自我校准练习：给所有“总是、从来、一定、全都”加样本检查。第一步，数样本：你用了几个事件，是一条消息、三次约会，还是半年二十次互动？第二步，标条件：这些事件是否都发生在睡眠差、冲突后、压力大、同一圈层中？第三步，补反例：找三个反例或中性例子，哪怕很小。第四步，降级结论：把“我没有能力”改成“在任务模糊和睡眠不足时，我最近三次表现下降”。当样本少于10个、时间短于两周、情境高度相似时，先不要定义人格和命运。 App端可实践提示：可设置样本数提醒：用户写下长期标签时，要求填写样本数、时间跨度、情境条件和反例。若证据不足，提示“当前更像波动，不足以定义长期模式”。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["小数律", "样本规模", "情绪判断", "过度概括", "自我觉察", "证据记录"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1545, now()),
(101546, '回归均值：别把自然回落误读成惩罚有效或自我崩坏', '偏差概念：回归均值指：一次特别好或特别差的表现之后，下一次更可能向平常水平靠近，而不一定由某个奖惩、仪式或自我评价造成。书中飞行训练案例提醒我们，教练可能误以为批评导致进步、表扬导致退步，其实很多变化只是极端值后的自然回归。 日常场景：你今天效率爆棚，明天普通，就觉得自己退步；伴侣某次特别体贴，下一次平常，就觉得爱减少；孩子考砸后被骂，下一次变好，家长就以为辱骂有效。情绪高峰后自然缓和，也常被误归因于刚做的某个动作。 自我校准练习：建立“基线-波动-干预”表。先记录过去两周的平常水平，如睡眠、完成度、沟通温度、焦虑强度。遇到极端好坏时，先标记“可能有回归”，不要急着解释。若你采取了批评、鼓励、运动、冥想等干预，至少观察多次同类情境，看它是否稳定改变平均水平，而不是只看下一次变化。复盘时问：如果我什么都不做，下一次是否也可能更接近平常？这次变化是否超过历史正常波动范围？我想强化的是过程，还是只追逐结果？ App端可实践提示：适合用于自责、育儿、伴侣沟通和绩效反馈。系统可提示用户区分单次反弹与平均水平上移，避免把严厉手段包装成有效方法，也避免把一次回落当作崩坏。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["回归均值", "因果误判", "自责", "奖惩", "情绪波动", "行为记录"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1546, now()),
(101547, '便利性启发式：脑中最容易想到的，不一定最真实', '偏差概念：便利性启发式是用“我能多快想起例子”估计频率或风险。它有时有效，因为常见事件更容易被想起；但它会被近期性、显著性、画面感、媒体报道和算法推送扭曲。书中关于名人名单、事故记忆和风险知觉的讨论，都指向这个机制。 日常场景：刚看完分手故事，就觉得亲密关系都危险；刚被拒绝一次，就觉得所有人都不欢迎你；刷到几条裁员新闻，就把职业前景估得极低；身体不适后搜索疾病，最吓人的案例最容易占据大脑。情绪越强，记忆提取越偏。 自我校准练习：做“便利性降噪”四问。第一，最近24小时我是否看过、听过、亲历过相关强刺激？第二，我想到的例子是随机抽样，还是被短视频、朋友圈、新闻标题筛过？第三，如果让我想反方向例子，能否在两分钟内列出五个？第四，有没有更稳定的数据可用，如个人长期记录、行业统计、团队真实比例、专业建议？在关系中，把“你总是忽视我”改成“这周有两次我很需要回应但没有得到，所以我现在很容易想起被忽视的例子”。这样既承认感受，也不把感受伪装成总体事实。 App端可实践提示：可让用户标注信息来源：亲历、朋友讲述、新闻、短视频、搜索结果、想象。来源越戏剧化，越提示回到长期记录或基率；恐惧高时先做90秒身体安抚再判断。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["便利性启发式", "风险感知", "记忆偏差", "焦虑", "算法信息", "事实校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1547, now()),
(101548, '关系里的自我中心偏差：我记得自己的付出，所以我觉得我付出更多', '偏差概念：自我中心偏差不一定来自自私，常来自记忆便利性：自己的努力、忍耐、委屈、临时补救最容易被自己记住，别人的隐形劳动却不在自己的记忆镜头里。书中关于合作任务和夫妻活动的研究，说明人会高估自己在共同事务中的贡献比例。 日常场景：伴侣都觉得家务和情绪劳动主要由自己承担，团队成员都觉得“没有我项目早崩了”，朋友之间都记得自己主动联系的次数，却忘记对方的让步。真实问题因此被推向道德指控：从记录不完整变成“你不懂感恩”。 自我校准练习：争论谁付出更多前，做“贡献账本互换”。各自独立列出过去一周的可见劳动、隐形劳动、情绪劳动和机会成本，再列出对方可能做过但自己不确定的部分。第二步，只讨论可观察事实，不评价人格。第三步，请对方补充你漏掉的三件事。第四步，把“我承担了80%”改成区间估计，例如“按我记得的事项，我像是承担了60%-70%，但我可能漏掉你的后台工作”。最后设计未来记录方式，如共享清单、轮值表、每周十分钟复盘。 App端可实践提示：可设置“我方镜头/对方镜头/旁观者镜头”三栏，让用户把同一事件改写三遍。多镜头不是替对方开脱，而是让关系从控诉进入协商。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["自我中心偏差", "便利性", "亲密关系", "贡献评估", "冲突沟通", "责任归因"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1548, now()),
(101549, '模拟启发式：越容易想象“差一点就好了”，越容易后悔过度', '偏差概念：模拟启发式是用心智模拟来判断事情发生的可能性、因果关系和反事实结果。它能帮助预演未来，也会让人陷入“如果当时多说一句、早走五分钟、没发那条消息，一切都会不同”。越容易在脑中改写一个细节，懊悔和内疚就越强。 日常场景：面试失败后反复重放某个回答，关系冲突后把全部责任压在一句话上，投资亏损后觉得“我明明差点就卖了”。容易想象不等于真的可控，也不等于改一个点就能改写整个系统；大脑只是找到了一条顺滑的故事线。 自我校准练习：做“反事实三层表”。第一层写最容易想象的改动，如“我当时不顶嘴”。第二层写这个改动真正需要的前提，如当时睡眠、信息、情绪、对方反应、时间压力。第三层写即使改动发生，结果仍可能不变的原因。再问：这个反事实是在帮助我学习，还是在惩罚我？若是学习，把它变成未来执行意图，如“下次争执升温时，我先暂停十分钟再回复”；若是惩罚，给它设限：每天只复盘一次，每次只产出一个可行动调整。 App端可实践提示：可把“如果当时”标成四类：可训练、可预防、不可控、需要哀悼。不可控和需要哀悼的内容不进入解决模式，而进入安抚模式，防止想象出的完美版本攻击真实自己。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["模拟启发式", "反事实思维", "后悔", "内疚", "情绪调节", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1549, now()),
(101550, '控制错觉：努力重要，但不是每个结果都由你控制', '偏差概念：控制错觉是把含有大量运气或噪声的结果，误当成自己能显著操控。书中讨论掷骰子、抽彩等机会情境中，人仍表现得像能控制结果：投前下注更大、用力或轻轻投，好像动作能改变随机性。技能线索会让人高估控制力。 日常场景：你以为只要足够谨慎就不会被拒绝，只要足够体贴就不会发生冲突，只要复盘够狠就能避免所有失败。成功时，你迷信某个动作；失败时，你把所有责任压到自己身上。亲密关系和工作评价中，这会制造过度自责。 自我校准练习：把目标拆成三圈。内圈是可控行为，如准备、表达、睡眠、练习、求助；中圈是可影响因素，如对方理解、团队协作、市场反馈；外圈是不可控噪声，如时机、他人状态、随机事件、宏观变化。结果出来后，只复盘内圈是否执行、执行质量如何；中圈只问下次怎样提高影响概率；外圈只记录不惩罚。做决定前写一句：“我能提高概率，但不能保证结果。”这句话能同时保留行动感和谦卑感。 App端可实践提示：当用户过度自责时，追问：这个结果需要几个人、几个条件、多少运气共同形成？属于你责任的比例是多少？剩下部分能否被允许存在？ 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["控制错觉", "随机性", "自责", "行动边界", "概率思维", "压力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1550, now()),
(101551, '过度自信与概率校准：把“我确定”改成可验证的百分比', '偏差概念：过度自信不是单纯自大，而是信心和准确率不匹配。书中关于校准的讨论指出：一个人说某类判断有70%把握，长期看这类判断也应大约70%成真，才算校准。清晰故事、强烈感觉、专家身份和信息量都会让人误把确定感当准确率。 日常场景：面试官看完材料很确信候选人会成功，创业者觉得计划万无一失，伴侣凭语气断定对方动机，咨询来访者凭一次情绪波动判断自己“彻底好了”或“完全没救”。这些判断可能对，也可能只是信心比证据跑得更快。 自我校准练习：建立“概率日记”。每天记录3个短期可验证判断，格式为“事件-概率-理由-何时验证”，例如“对方今天会回复：65%，理由是他通常晚上看消息”。验证时只记对错，不解释开脱。每周统计：80%-90%把握的判断是否真的大多发生？50%-60%把握是否接近一半？如果高信心区错误很多，下周同类判断自动下调10%-20%，并补一句“我还缺什么信息”。沟通中，把“我肯定你是故意的”改成“我现在有60%觉得你在回避，但我需要确认”。 App端可实践提示：提供固定概率档位55、65、75、85、95，避免用户随手写100%。只奖励校准，不奖励嘴硬；即使判断错了，只要概率给得合理，也算学习成功。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["过度自信", "概率校准", "预测记录", "自我觉察", "沟通降温", "决策反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1551, now()),
(101552, '事后诸葛亮偏差：复盘时恢复当时的信息，而不是用结果审判过去', '偏差概念：事后诸葛亮偏差是结果发生后，人会觉得它“早就明显”“本来就该知道”。书中提醒，回顾过去很容易产生解释的流畅感，但预测本来远比解释困难。用现在已经知道的结果去审判当时的信息不足，会把不确定判断改写成道德失败。 日常场景：项目失败后，团队说“早该看出方向不行”；关系破裂后，你说“我一开始就该知道他会这样”；情绪崩溃后，你责备自己“明明征兆都在”。这些复盘看似聪明，却可能让人只学会自责，而没有改进信息系统。 自我校准练习：复盘时分两张纸。第一张叫“当时可见”：只写决策时已经知道、能够合理知道的信息。第二张叫“事后才知道”：写后来出现的反馈、他人真实想法、市场变化、身体反应。只用第一张评价当时决策质量，用第二张设计未来预警。再问三个问题：当时有哪些合理选项？每个选项的风险在当时看来是多少？如果重来，我要增加哪一个检查点，而不是责骂哪一个人？把“谁这么蠢”改成“下次怎样让信息更早出现”。 App端可实践提示：可用时间线界面呈现：当时知道什么、当时不知道什么、何时出现新信号、下一次怎样提前捕捉。目标是承担责任，但不把不可预知的结果变成自我否定。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["事后诸葛亮", "复盘", "自责", "决策质量", "不确定性", "学习系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1552, now()),
(101553, '去偏差程序：重大判断不要只靠感觉，要给直觉配一个外部脚手架', '偏差概念：本书后半部分讨论校正和改善直觉推理：直觉不是要被消灭，而是要被程序支持。人在不确定情境中容易受代表性、便利性、过度自信和事后解释影响，因此重大判断需要外部脚手架，让情绪、事实和反馈各有位置。 日常场景：招聘、择业、分手或复合、投资、是否相信某个疗法、是否给自己贴长期标签，都是高影响判断。只靠“我感觉很对/很不对”，会让当下情绪拥有过大权力；只靠复杂分析，又可能拖延行动。脚手架的作用是让直觉接受结构化检查。 自我校准练习：使用“四步去偏差卡”。第一，外部视角：同类情况通常结果怎样？不要先讲自己的特殊故事，先找基率。第二，样本视角：我依据多少次观察？样本是否来自极端情绪、单一圈层或算法推送？第三，反方视角：如果我最初判断是错的，最可能错在哪里？写至少两个替代解释。第四，线性清单：把关键因素列成固定项，每项0-2分，不临场改权重，例如关系决策可评估尊重、稳定、冲突修复、价值一致、现实压力。清单不替你做决定，但能防止一个鲜明故事压倒所有信息。 App端可实践提示：重大决定模式可自动要求基率、样本、反方、清单和复查日期。清单结果与直觉冲突时，不要求立刻服从，而是记录冲突原因，并在事后用真实反馈更新清单。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。 校准结束时，把结论写成一句可被未来证据修正的话：我现在根据哪些证据，给出多少把握，还需要观察什么。这样既保留直觉的速度，也给事实、时间和反馈留下入口。', '["去偏差", "外部视角", "线性模型", "决策清单", "直觉校准", "归纳推理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1553, now()),
(101554, '把“高绩效自我”与被压抑的一面一起看见', '这部分内容可转化为一条很适合 App 的自我觉察练习：当一个人长期只依赖理性、效率、成就感来定义自己时，容易把脆弱、混乱、嫉妒、恐惧、冲动等体验推到视野之外。文本反复强调，完整的人格并不只由光亮、体面或可展示的一面构成；被忽略的阴影并不会消失，而会以更隐蔽的方式影响判断、人际关系和情绪反应。可以将其提炼为“识别被否认的自我部分”练习：回顾最近一次强烈情绪爆发或关系冲突，写下当时最不愿承认的感受是什么；再问自己，这个感受通常在什么情境下出现、我是否习惯用‘应该’和‘必须’压住它。目标不是给自己贴标签，而是帮助用户把原本被排斥的经验重新纳入观察范围，形成更稳定的自我理解。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["自我觉察", "阴影整合", "情绪识别", "内在冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1554, now()),
(101555, '意义感不只来自实用与结果', '这部分可提炼为关于“意义感来源”的心理教育内容。文本区分了只重实用、价值和可证明结果的思维方式，与另一种更能把握整体经验和深层意义的思维方式。对 App 用户来说，这可以被转译为：当生活被目标、指标和效率完全占据时，人会逐渐失去对经验本身的感受力，也更难回答“我为什么要这样生活”。可设计一个价值澄清练习：列出最近一周最耗费精力的三件事，再分别标注它们带来的不仅是收益，还有消耗、空洞感或满足感；最后写下“如果不看他人评价，我真正看重的是什么”。这一条不鼓励超自然解释，而是帮助用户把“有用”与“有意义”区分开，恢复对内在价值、关系和体验质量的敏感度。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["意义感", "价值澄清", "自我反思", "生活选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1555, now()),
(101556, '与内在经验对话，而不是只用判断压住它', '这部分非常适合转成“内在对话”类练习。文本里有一个核心姿态：不要把自己的情绪、梦境、冲动或不合逻辑的体验简单当成噪音或错误，而要像面对一个独立的内在对象那样，认真询问它想表达什么。中性化后，可以理解为：人常常习惯用分析、否定、解释迅速盖过感受，但很多困惑恰恰来自未被倾听的内在部分。App 可引导用户在安静环境中写下三个句子：‘我现在最强烈的感觉是…’、‘它可能在保护我免于…’、‘如果它会说话，它最想提醒我什么…’。这样做的目的不是神秘化内心，而是提升情绪命名能力和自我同理，帮助用户把冲突从“压制—反弹”的循环，转向“识别—理解—选择”。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["内在对话", "情绪命名", "自我同理", "冲突调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1556, now()),
(101557, '追逐空洞目标时，空虚感会放大', '这部分来自对‘偶像’与‘空洞承诺’的分析，适合改写为现代生活中的目标依附问题。书中指出，当人把金钱、地位、关系、外貌、成就等本来有价值的东西，提升为决定自我价值和生命意义的终极来源时，这些东西就会从资源变成压力源，最终导致焦虑、失控或持续空虚。App 可以把它做成“目标依赖检查”：让用户挑选一个最近特别在意的目标，分别回答‘它给了我什么短期回报’、‘如果失去它我会担心什么’、‘我是否把它当成了证明自己价值的方式’。这个练习的重点不是否定目标，而是帮助用户看见自己是否把某个局部目标误当成了全部人生，从而更容易恢复弹性与边界。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["价值观", "空虚感", "目标依赖", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1557, now()),
(101558, '当一个好东西变成唯一答案，就会引发内耗', '这条适合提炼成“过度绝对化的价值冲突”教育内容。文本不是在说金钱、亲密关系或成就本身有问题，而是在说：当某件好事被抬升到唯一重要、非得到不可的位置，它就会扭曲人的判断，让人为了它破坏原有原则、忽视他人、甚至伤害自己。对 App 用户而言，可将其转成一个自测问题：‘我最近最在意的东西是什么？我愿意为它牺牲哪些别的价值？这种牺牲是否合理？’ 进一步可以引导用户列出“不可谈判的三条底线”和“可以灵活调整的三项期待”，让自己把追求放回整体生活结构中，而不是被单一欲望牵引。此类内容有助于处理内在冲突，减少一边想要、一边自责的拉扯。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["内在冲突", "价值排序", "边界", "自我管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1558, now()),
(101559, '从“成功也空虚”识别终极期待', '这一条可转化为面向高压人群的心理教育：即使外部条件不断改善，人仍可能感到莫名的空、焦虑或绝望，这往往意味着真正被追求的不是钱、职位或认可本身，而是这些东西背后所承载的‘我终于可以安心了’‘我终于足够好了’之类终极期待。文本用大量例子说明，外部成就并不能自动填补内在的失落。App 可设计一个‘终极期待拆解’练习：用户写下自己最渴望达成的一件事，然后追问‘达成后我希望感觉到什么’、‘这种感觉是否只能靠外部结果维持’、‘还有哪些不依赖结果的来源能让我获得稳定感’。这能帮助用户把对结果的执念，转向对关系、节奏、休息、自我接纳和现实限制的重视。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["成功压力", "终极期待", "情绪稳定", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1559, now()),
(101560, '言语行为与语境对齐：把说话意图说清楚', '这份文本最可提炼的，不是语言哲学本身的学术论证，而是对“话语意图”和“语境理解”之间关系的清晰拆分：同一句话在不同场景里，可能既是陈述、请求、提醒，也可能是委婉拒绝；真正影响沟通结果的，往往不是字面词语，而是说话者意图、听者预期、关系距离与当下情境的组合。可转化为 App 练习的方向有三类：一是“我想表达什么”与“对方可能听成什么”的双栏对照，训练用户在发出消息前先做意图校准；二是“直接说/间接说/先铺垫再说”的沟通脚本选择，让用户根据关系亲疏、冲突强度和任务紧急度，选择更合适的表达方式；三是对隐喻、反话、暗示、含蓄拒绝等高误读表达做识别练习，帮助用户在亲密关系、同事协作和亲子沟通中减少猜测成本。它适合被整理成“表达意图—判断语境—选择措辞—复盘误会”的结构化小练习，而不是保留为语言哲学知识讲义。 使用时可以按“三步”练习：第一，先描述事实和感受，不急着解释对错；第二，写下自己最想保护或最害怕失去的东西；第三，选择一个小行动，让它既照顾当下情绪，也不破坏长期关系和底线。这个条目适合作为 App 中的自我提问卡片，不替用户做价值判断，而是帮助用户把模糊体验变成可观察、可复盘、可调整的行动。', '["关系沟通", "表达清晰", "语境理解", "间接表达", "冲突降噪", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1560, now()),
(101561, '情绪温度计：用固定量表追踪，而不是只凭当下感觉判断', '核心观念：情绪低落时，人很容易把“我现在感觉很糟”误当成“我一直都很糟”。伯恩斯在第2章把自评量表当作治疗第一步：不是为了给自己贴诊断标签，而是把模糊的痛苦转成可观察的趋势。App 端可把它设计成“情绪温度计”：每周一次或在明显波动时记录总分，同时拆分为情绪、想法、活动/关系、生理状态和安全信号等维度。使用时要强调三点：第一，分数只是当前状态的快照，不代表人格或命运；第二，分数变化比单次数值更重要，连续上升提示需要减负、复盘诱因和增加支持；第三，分数下降可以强化自我效能，让用户看到练习、休息、沟通和行动确实会带来变化。若 App 需要给反馈，建议使用“你最近的负担似乎变重了，我们一起查看哪一项变化最大”这样的辅助语气，而不是“你得了什么病”的口吻。

使用建议：情绪评分最好配合文字记录，而不是孤立展示数字。一次记录可包含“今天最重的情绪、最困扰的想法、做了哪些事、是否有人支持我、下一步需要什么”。当总分升高时，App 不宜只推送安慰语，而应帮助用户查看是哪一类条目拉高：是自责、无望、睡眠、活动减少，还是关系退缩。这样用户能从“我整个人坏掉了”回到“某几个系统正在超载”。当总分下降时，也要提醒用户回看有效行动，形成个人复原配方。', '["情绪评分", "自我监测", "每日心境", "趋势追踪", "非诊断", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1561, now()),
(101562, '自动想法链：事件不会直接决定情绪，中间隔着解释', '核心观念：让人突然下沉的，常不是事情本身，而是事情发生后脑中瞬间闪过的解释、判断和画面。伯恩斯把这类内容称作下意识思维：它们出现得快、像条件反射、带有强烈真实感，所以用户往往只记得情绪，不记得自己刚刚怎样解释现实。App 可以把一次情绪波动拆成“情境—自动想法—情绪—行为冲动”四格：发生了什么？我脑中最刺痛的一句话是什么？我给它信了几分？身体和行为有什么反应？这个流程的关键不是强迫积极，而是先把内在独白从脑内拉到纸面。一个有用的提示是：“如果这个情绪会说话，它刚才对你说了哪一句？”当用户能捕捉到句子，情绪就从一团雾变成可以检验的假设；接下来才有可能识别扭曲、寻找证据、写出更平衡的回应。

使用建议：自动想法常以三种形式出现：一句话、一个画面、一个身体化判断。比如“完了”“他们肯定讨厌我”“我就是没用”，或脑中闪过失败场面。App 可允许用户用语音、短句或选择卡快速捕捉，避免在情绪高峰期要求长篇书写。随后引导用户给想法命名为“我现在的解释”，而非“事实”。这一步本身就能创造距离。对咨询辅助而言，连续几次记录还能呈现个人高频主题：被拒绝、失败、失控、孤独或不公平，从而为后续垂直箭头和行为实验提供入口。', '["自动想法", "下意识思维", "认知模型", "情绪记录", "想法检验", "CBT"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1562, now()),
(101563, '十大认知扭曲：先给痛苦念头贴“思维标签”', '核心观念：情绪强烈时，用户往往会争论“这是不是事实”，但更容易入手的是先识别它属于哪种思维模式。伯恩斯整理的十类扭曲可作为 App 的标签库：非此即彼、以偏概全、心理过滤、否定正面、妄下结论（读心术/先知错误）、放大或缩小、情绪化推理、应该句式、乱贴标签、罪责归己。标签的作用不是批评用户“想错了”，而是降低念头的权威感：原来这不是绝对真理，而是一种常见的心理加工方式。交互上可让用户先选择最像的1-3个标签，再给出温和提问：是否存在灰色地带？有没有被过滤掉的正面证据？我是在预测未来还是在读别人心？如果把“应该”改成“我希望/如果能……就好了”，情绪会不会松一点？这种标签化能把自责转成观察，把混乱转成下一步练习。

使用建议：标签库应避免变成考试题。用户不需要一次选准全部扭曲，只要能识别一两个最明显的模式即可。每个标签后可配一个反问句：非此即彼对应“有没有中间分数？”；以偏概全对应“这件事发生一次，是否能推出永远如此？”；心理过滤对应“我漏掉了哪些信息？”；情绪化推理对应“感觉强烈是否等于证据充分？”；罪责归己对应“哪些部分不在我控制范围内？”标签之后再进入证据、替代解释和下一步行动，能避免用户在情绪中继续和念头硬碰硬。', '["认知扭曲", "思维标签", "情绪化推理", "应该句式", "读心术", "心理过滤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1563, now()),
(101564, '三栏情绪日志：把自我攻击改写成可相信的理性回应', '核心观念：自我批评最伤人的地方，是它听起来像事实。伯恩斯建议用三栏法处理：左栏写下伤人的下意识思维，中栏标注认知扭曲，右栏写出更客观、可信、对事不对人的理性回应。App 可把它设计成一次短练习：1）选择一个具体时刻；2）记录情绪强度；3）写出脑中原句，例如“我总是搞砸”；4）标出扭曲，如以偏概全、乱贴标签；5）写出一个自己真的能相信的回应，例如“这次迟到了，但不能推出我什么都做不好；我可以补救并调整提醒”。重点是“真实可信”，不是口号式正能量。如果用户暂时写不出回应，可以先保存问题，稍后让朋友、咨询师或 App 提问协助。长期看，三栏日志能训练一种新习惯：评价具体行为，寻找修正路径，而不是用一次失误审判整个人。

使用建议：三栏法最适合处理自责、羞耻、批评后崩溃、拖延前的无力感。App 可先让用户选择情绪强度，再填写“最刺痛的一句自我评价”，避免记录停留在“我难受”层面。理性回应的标准有三条：具体、可信、有行动余地。它不应写成“我很棒”，而应写成“这次确实有疏忽，但我可以补发说明；一次疏忽不能定义我”。完成后再让用户重新评分，看情绪是否松动。长期保存的日志还可形成个人“常见攻击句—有效回应句”库，在下次类似情境中快速调用。', '["三栏法", "每日情绪日志", "自我批评", "理性回应", "自尊", "认知重评"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1564, now()),
(101565, '每日活动计划：行动先于动力，记录掌控感与愉悦感', '核心观念：低落和无力时，人会等待“有心情了再做”，结果活动减少、生活变窄、心情更差。伯恩斯的每日活动计划表把一天按小时安排，并在结束后记录实际做了什么；每项活动再标注 M（掌控/成就感）和 P（愉悦/休闲感），用0-5分评价。App 端可引导用户先做轻量版本：今天只排3个时间块，一个照顾身体、一个处理必要事务、一个小愉悦；晚上记录实际结果，即使只是发呆也如实写下。这样做的价值有三层：一是减少“我什么都没做”的模糊自责；二是用数据发现哪些活动最能恢复能量；三是在周末、独处、假期等高风险时段提前安排结构。它特别适合行为激活：不是要求用户立刻热爱生活，而是先用小行动重新打开掌控感和愉悦感的循环。

使用建议：用户低能量时，计划越宏大越容易失败。因此 App 可提供低、中、高三档任务：低档如起床喝水、洗脸、开窗；中档如整理十分钟、回复一条消息；高档如运动、外出、完成工作块。M/P评分能帮助用户看见两类恢复来源：掌控感来自“我做得到”，愉悦感来自“我还能感受一点好”。如果某天计划落空，也不把它解释为失败，而是记录障碍：任务太大、时间不对、睡眠不足、情绪太重还是缺少提示。下一天据此调小任务，保持行动循环不断裂。', '["行为激活", "每日活动计划", "掌控感", "愉悦感", "生活节律", "无力感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1565, now()),
(101566, '反拖延实验：用“预测—行动—校准”拆穿无力感', '核心观念：拖延常由消极预测驱动，例如“太难了”“做了也没用”“我没有心情”。伯恩斯的反拖延表把这些预测变成实验：把任务拆成15分钟以内的小步骤；开始前预测难度和满足感（0-100%）；完成后记录实际难度和实际满足感。许多人会发现，任务没有想象中困难，完成后的满足感也比预期高。App 可将流程做成任务卡：任务名称、最小下一步、预计难度、预计收益、实际结果、我学到什么。配套工具包括反驳“但是”、TIC-TOC（任务干扰型认知→任务导向型认知）、化整为零、自我认同、验证“我不行”。关键提示是：目标不是证明自己勤奋，而是训练大脑校准预测。每一次小步骤完成，都是对“我只能等状态好”的反证。

使用建议：反拖延表的关键是先写预测，再行动，否则用户会用事后解释掩盖原来的悲观估计。App 可在任务开始前锁定两个数值：预计困难和预计满足；完成后再填写实际困难和实际满足，并自动显示“预测误差”。如果实际困难更低，用户获得证据；如果实际困难确实高，也能继续拆分步骤、调整资源，而不是回到“我不行”。TIC-TOC 适合做成左右滑卡：左边是拖住行动的句子，右边是任务导向回应。每张卡都应指向一个可执行动作，如“只打开文档”“只写标题”“只打一个电话”。', '["拖延", "反拖延表", "TIC-TOC", "小步骤", "行为实验", "自我效能"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1566, now()),
(101567, '快乐预测：用实验修正“一个人做什么都没意思”', '核心观念：依赖、孤独和低落常混在一起，让人相信“没人陪就不会快乐”。伯恩斯用快乐预测表把这个信念变成可检验问题：计划一些活动，先预测快乐程度，再记录实际快乐程度；同时标注是独自完成还是与别人一起完成。App 可用于两类场景：一是低落时重新发现小愉悦，二是关系焦虑时区分“我想要爱/陪伴”和“我没有它就无法生活”。用户可以在两三周内做一组小实验，如散步、看展、学习、做饭、运动、联系朋友、独处阅读等。练习的目的不是否认亲密关系的重要，而是恢复选择感：我可以享受关系，也能在独处时照顾自己。若实际快乐低于预测，也不代表失败，而是继续记录当时的自动想法，看看是否有“别人会看不起我”“一个人很可怜”等念头在破坏体验。

使用建议：快乐预测也适合处理“我必须等别人/等状态/等条件成熟”的想法。App 可鼓励用户选择低成本、可重复、可量化的小活动，而非一开始就安排高期待的大事件。记录时同时写下陪伴对象，可以帮助用户区分三件事：活动本身带来的愉悦、与某个人连接带来的愉悦、以及自己对独处的解释带来的痛苦。若用户发现独处活动实际并非零分，就能逐步建立“我可以陪伴自己”的经验。若与他人一起也不如预期，则可继续检查自己是否在讨好、比较或读心。', '["快乐预测", "独处", "孤独", "关系依赖", "行为实验", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1567, now()),
(101568, '自尊练习：评估行为，不给整个人贴标签', '核心观念：低落时最危险的跳跃，是从“我这件事没做好”跳到“我这个人没价值”。伯恩斯反复区分行为、成就、认同与人的整体价值：批评、失败、不被喜欢都只能说明某个情境里有问题，不能推出一个人低人一等。App 可把自尊练习设计成三步：先写具体行为或事件；再写用户给自己的标签；最后把标签改回可处理的问题。例如“我是废物”改成“我今天没有完成计划，可能需要把任务拆小或调整休息”。另一个练习是自我认同计数：每天记录自己做过的微小积极行为，不依赖外界夸奖来确认。系统反馈要避免空泛夸奖，可强调“你做了一个照顾自己的动作”“你识别到一个标签化念头”。自尊不是证明自己完美，而是停止用局部表现审判整个人。

使用建议：自尊模块应多用“行为语言”，少用“人格语言”。当用户写下“我很差”时，系统可追问“具体是哪件事让你这样评价自己？”当用户写下“没人喜欢我”时，可追问“你掌握了哪些证据？是否有例外？”自我认同计数不要求用户感到强烈自豪，只要承认一个事实：我完成了某个照顾、负责、学习或连接的动作。这个练习的长期意义，是让自我价值不再完全交给外界掌声、工作成绩或关系回应来决定。用户仍然可以追求认可和成就，但不再把它们当作活着是否有价值的判决书。', '["自尊", "乱贴标签", "自我认同", "行为评价", "成就依赖", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1568, now()),
(101569, '语言柔道：面对批评先理解，再消除敌意，最后协商', '核心观念：批评会刺痛人，往往不是因为对方一句话本身，而是我们迅速读出“我没价值”“他故意羞辱我”。伯恩斯的语言柔道提供了关系沟通中的认知检验流程。第一步是移情式提问：暂缓辩解，问清对方具体不满什么、发生在何时、希望怎样改变。第二步是解除戒备：即使批评很夸张，也尝试承认其中一点事实，或承认从对方角度看愤怒可以理解。第三步是反馈和协商：在对方降温后，清楚表达自己的立场、感受和边界，必要时承认错误、道歉、提出补救，或有礼貌地重复底线。App 可把它做成冲突脚本模板：我听见你在意的是……这里我能承认的是……我的看法是……我们能否尝试……。它能避免两条旧路：一条是全盘认错后自责崩溃，另一条是立刻反击造成关系升级。

使用建议：这个条目适合做成对话排练器。用户可先输入对方原话，系统帮助拆分“事实指控、情绪表达、标签攻击、合理请求”。第一轮只练提问，例如“你最介意的是哪件具体事？”第二轮练解除戒备，例如“这点我能理解，我确实迟到了”；第三轮练表达边界，例如“我愿意讨论迟到，但不接受人身攻击”。如果用户发现自己强烈想反击，可先做三栏法，检验“他批评我=我一无是处”的隐含想法。这样，沟通训练和认知检验形成闭环：先稳住自尊，再处理关系中的事实、感受和请求。', '["关系沟通", "批评应对", "语言柔道", "移情", "协商", "认知检验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1569, now()),
(101570, '愤怒记录：怒火来自解释，可用移情和预演降温', '核心观念：愤怒通常让人觉得“是对方让我生气”，但伯恩斯指出，中间仍有解释在点火，例如读心、应该句式、夸大不公、给对方贴标签。App 可建立愤怒记录：触发事件、愤怒强度、脑中规则（他不应该、她必须、这太不公平）、我想做什么、这样做的短期好处和长期代价。降温工具可分四类：1）冷却愤怒想法，把“他故意针对我”改成可检验的多种解释；2）减少“应该”，改写成“我希望/如果……就好”；3）准确移情，尝试说出对方可能的动机直到自己能理解但不必赞同；4）认知预演，提前列出愤怒等级，从低强度场景开始练习冷静回应和谈判请求。这样处理的目标不是压抑边界，而是让表达更有效：少一点爆发，多一点清楚要求、奖励合作和必要的坚定。

使用建议：愤怒模块不应要求用户“别生气”，而是帮助用户决定“怎样生气更有用”。记录中可加入“发火的好处/代价”两栏：发火可能带来控制感、让对方让步，却也可能损害关系、强化旧模式、让自己更难收场。准确移情不是替对方开脱，而是生成更多解释，削弱“他就是恶意”的唯一叙事。认知预演适合在平静时做：列出从1到10的触发场景，先练低强度情境，写好冷静想法和请求句。等真实冲突发生时，用户不必临场发明回应，而是调用已经排练过的脚本。', '["愤怒管理", "愤怒记录", "准确移情", "应该句式", "认知预演", "边界表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1570, now()),
(101571, '垂直箭头：找出情绪反复背后的隐性假设', '核心观念：同一种情绪反复出现，往往不是因为表层事件一样，而是底层规则一样。伯恩斯的垂直箭头法是在一个自动想法下面不断追问：“如果这是真的，那意味着什么？我为什么会因此难受？”每回答一层，就继续向下问，直到出现核心假设，如“被批评就说明我没价值”“必须成功才值得被尊重”“如果没人爱我就无法快乐”“犯错就完了”。App 可把它做成向下追问卡片，每次最多5-7层，最后让用户给隐性假设命名，并标注它属于成就依赖、认同依赖、完美主义、控制需求还是关系依赖。找到假设后，再回到三栏法或行为实验：这条规则有哪些证据？代价是什么？如果把它改成更灵活的偏好，会怎样行动？垂直箭头适合咨询辅助，因为它把零散情绪连接成个案地图。

使用建议：垂直箭头不适合在情绪爆炸的最高点深挖，可在用户稍微稳定后进行。每一层回答都要写成一句信念，而不是只写感受；例如不要停在“我会很难过”，而要继续问“难过说明了什么？”直到出现“我必须被认可”“我不能失败”“我不能独处”等规则。App 可把最终假设保存为“旧规则”，再邀请用户写“新规则”：把绝对要求改为偏好和选择，如“我希望被认可，但一次批评不能定义我”。后续再配一个小实验验证新规则，比如主动请求反馈、独自完成一个活动或用较低标准完成任务。', '["垂直箭头", "隐性假设", "核心信念", "个案概念化", "DAS", "深层规则"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1571, now()),
(101572, '成就与完美主义：把“必须完美”改成可实验的标准', '核心观念：把价值等同于成就，会让人永远被排名、比较和失败威胁；把快乐等同于完美，会让人越优秀越不敢满意。伯恩斯用角色扮演和反完美主义表挑战这两类假设：先看“价值=成就”会推出多么荒谬的高低人体系，再用实验检验“标准降低就会崩盘”是否真实。App 可提供两个练习：第一，价值等式反问：成就如何计量？是否每个成功者都更有价值？我会这样评价朋友吗？第二，标准实验：选一项活动，分别用100%、80%、60%的标准完成，记录表现、满意度和代价。反完美主义表还可记录“完成得多完美”和“实际满意度”，帮助用户发现满意不一定随完美上升。目标不是鼓励粗糙，而是把高标准从身份威胁变成灵活工具：该认真时认真，该完成时完成，该学习时允许不完美。

使用建议：完美主义用户常把降低标准理解为放弃，因此 App 需要强调“标准实验”只是收集数据，不是永久改变人格。每次实验可记录四项：投入标准、实际结果、满意度、身心代价。若80%标准带来相近结果和更低代价，用户就获得了新的选择；若某些场景确实需要高标准，也能更清楚地知道为什么值得投入。对工作价值议题，系统可引导用户列出“我欣赏朋友的哪些品质”，通常会出现真诚、可靠、幽默、善良、努力等非成就维度。这能帮助用户把自我评价从单一业绩指标扩展到更完整的人。', '["完美主义", "成就依赖", "工作价值", "标准实验", "反完美主义表", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v17-20260706', 1572, now())
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  tags = EXCLUDED.tags,
  status = EXCLUDED.status,
  source = EXCLUDED.source,
  sort = EXCLUDED.sort,
  update_time = now();

SELECT setval(pg_get_serial_sequence('rag_documents','id'), GREATEST((SELECT max(id) FROM rag_documents), 1));

COMMIT;
